    public void populateRFFforPipelineField() throws Exception
    {
    	DataObject dealsFldDO = FieldUtil.getFieldsDOForModule(CrmModuleConstants.POTENTIALS, null);
    	Row pipelineFld = dealsFldDO.getRow(CRMFIELD.TABLE, new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.COLUMNNAME), CRMPOTENTIAL.PIPELINE, QueryConstants.EQUAL));
    	if(pipelineFld == null) {
    		return;
    	}
    	DataObject dealHistoryFldDO = FieldUtil.getFieldsDOForModule(CrmModuleConstants.DEALHISTORY, null);
    	if(dealHistoryFldDO != null && !dealHistoryFldDO.isEmpty()) {
    		boolean flag = false;
    		Criteria crt = new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDLABEL), "Pipeline", QueryConstants.EQUAL);
    		crt = crt.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.REFER_FROM_FIELDID), null, QueryConstants.EQUAL));
    		Iterator<Row> itr = dealHistoryFldDO.getRows(CRMFIELD.TABLE, crt);
    		while(itr.hasNext()) {
    			Row fieldRow = itr.next();
    			fieldRow.set(CRMFIELD.REFER_FROM_FIELDID, pipelineFld.get(CRMFIELD.FIELDID));
    			dealHistoryFldDO.updateRow(fieldRow);
    			flag = true;
    		}
    		if(flag) {
    			PersistenceCacheUtil.getPurePersistenceLiteHandle().update(dealHistoryFldDO);
    		}
    	}
    }
    

