    public void clearQueuedBulkJobs() {
        try {
            Persistence persistence = PersistenceCacheUtil.getPersistenceLiteHandle();
            DeleteQuery delete_query = new DeleteQueryImpl(CRMBULKJOB.TABLE);
            Criteria criteria = new Criteria(new Column(CRMBULKJOB.TABLE, CRMBULKJOB.STATE),
            		new Object[] {State.QUEUED, State.PROCESSING}, QueryConstants.IN);
            criteria=criteria.and(new Criteria(new Column(CRMBULKJOB.TABLE,CRMBULKJOB.CREATEDBY), userId, QueryConstants.EQUAL));

            delete_query.setCriteria(criteria);
            persistence.delete(delete_query);
        }
        catch(Exception ex) {
        	LOGGER.log(Level.SEVERE, "Problem while deleting queued bulk jobs", ex);
        }
    }
    
    public void clearBulkWriteQueuedJobs() {
        try {
            Persistence persistence = PersistenceCacheUtil.getPersistenceLiteHandle();
            DeleteQuery delete_query = new DeleteQueryImpl(CRMDATAMIGRATION.TABLE);
            Criteria criteria = new Criteria(new Column(CRMDATAMIGRATION.TABLE, CRMDATAMIGRATION.STATUS),
            		new Integer[] {MigrationStates.PENDING.getCode()}, QueryConstants.IN);
            criteria=criteria.and(new Criteria(new Column(CRMDATAMIGRATION.TABLE,CRMDATAMIGRATION.USERID), userId, QueryConstants.EQUAL));

            delete_query.setCriteria(criteria);
            persistence.delete(delete_query);
        }
        catch(Exception ex) {
        	LOGGER.log(Level.SEVERE, "Problem while deleting queued bulk write jobs", ex);
        }   
    }

