    public JSONArray getBulkJobs() throws Exception
    {
    	JSONArray array = new JSONArray();
    	Persistence persistence = PersistenceCacheUtil.getPersistenceLiteHandle();
    	SelectQuery query = new SelectQueryImpl(Table.getTable(CRMBULKJOB.TABLE));
		query.addSelectColumn(new Column(CRMBULKJOB.TABLE, "*"));
		Criteria active_jobs_for_user = new Criteria(new Column(CRMBULKJOB.TABLE, CRMBULKJOB.STATE),
				new Object[]{State.COMPLETE, State.FAILURE}, QueryConstants.IN);
		Long time = Instant.now().getMillis() - 24*60*60*1000;
		active_jobs_for_user=active_jobs_for_user.and(new Criteria(new Column(CRMBULKJOB.TABLE, CRMBULKJOB.ENDTIME),
				time, QueryConstants.GREATER_EQUAL));
		query.setCriteria(active_jobs_for_user);
		query.setRange(new Range(1,500));
		DataObject dobject =persistence.get(query);
		if(dobject!=null && !dobject.isEmpty()) {
			List<com.adventnet.crm.bulk.read.model.Job> jobs = WorkerUtil.getInstance().getJobFromDO(dobject);
			int size = jobs.size();
			for(int i =0; i<size;i++) {
				JSONObject jsonObj = new JSONObject(jobs.get(i));
				array.put(jsonObj);
			}
		}
		return array;

    }
    
       //for automation case - retry previous day's job
      public void setRetryCaseforExport() throws Exception{
      	 try {
      		    UpdateQueryImpl update = new UpdateQueryImpl(CRMBULKJOB.TABLE);
      			update.setUpdateColumn(CRMBULKJOB.STATE,"FAILURE"); //No i18n
      			update.setCriteria(new Criteria(Column.getColumn(CRMBULKJOB.TABLE, CRMBULKJOB.CREATEDTIME), (System.currentTimeMillis()-DataBackupConstants.DAY_IN_MILLI), QueryConstants.GREATER_THAN));
               update.setCriteria(new Criteria(Column.getColumn(CRMBULKJOB.TABLE, CRMBULKJOB.FEATURENAME),FeatureNameConstants.EXPORT, QueryConstants.EQUAL));
      			int noOfRowsUpdated = PersistenceCacheUtil.getPersistenceLiteHandle().update(update);
      			LOGGER.log(Level.SEVERE, "updated rows in setRetryCaseforExport:: ", noOfRowsUpdated);
              
           }
           catch(Exception ex) {
           	LOGGER.log(Level.SEVERE, "Problem while updating setRetryCaseforExport for export", ex);
           }
      }
      //Update the Export feature limit count by calling this method
      public void updateLimitForExport() throws Exception {

   		Integer limitCountForLicense = FeatureEditionUtil.getFeatureLimits(FeatureNameConstants.EXPORT, LicenseUtil.getActualLicenseType());
   		DataObject obj=FeatureEditionUtil.getNCFeatureLimitsDO(FeatureNameConstants.EXPORT);
   		
   		Row featureRow=null;
   		Timestamp updated_time=null;
   		Integer actual_count=null;
   		if(obj!=null && !obj.isEmpty()) {
   			featureRow=obj.getFirstRow(CRMNCFEATURELIMITS.TABLE);
   		}
   		if(featureRow!=null) {
   			actual_count=(Integer) featureRow.get(CRMNCFEATURELIMITS.ACTUALCOUNT);
   		}
   		//update feature count if actual_count is 0
   		
   		if(actual_count==0) {
   			FeatureEditionUtil.insertORupdateCrmNCFeatureLimits(FeatureNameConstants.EXPORT, limitCountForLicense, 0, limitCountForLicense,false);
   			LOGGER.log(Level.INFO, "CrmFeatureLimitRow updated for the feature {0}, limitcount: {1} in ResetConfigurations", new Object[]{FeatureNameConstants.EXPORT,limitCountForLicense});
   		}
   	
      }
      
