      public JSONObject test_twitterAPI() throws Exception {

  		SocialServiceConnector connector = null;
  		JSONObject paramJson = new JSONObject();
  		JSONObject resultObj = new JSONObject();
  		JSONObject response = new JSONObject();

  		try {

  			HttpServletRequest request = IAMUtil.getCurrentRequest();

  			JSONObject param = new JSONObject(request.getParameter("params"));
  			JSONObject methodParam = new JSONObject(request.getParameter("methodParam"));
  			JSONObject content = new JSONObject(request.getParameter("content"));


  			String remoteAddress = request.getRemoteAddr();
  			String remoteAddressWithIPSignature = IAMUtil.generateRemoteUserIPSignature(request);

  			String apiCall = param.get("apiCall").toString();

  			HashMap<String,String> remoteAddr = new HashMap<>();
  			remoteAddr.put("REMOTE_USER_IP",remoteAddress);
  			remoteAddr.put("Z-SIGNED_REMOTE_USER_IP",remoteAddressWithIPSignature);

  			connector = new SocialServiceConnector(param.get("portalId").toString(), Long.valueOf(param.get("social_brand_id").toString()), Long.valueOf(param.get("zuid").toString()),param.get("network").toString(),param.get("outh").toString(),remoteAddr);
  			LOGGER.log(Level.SEVERE, "Is Social connector null? -->{0}", connector==null);
  			HashMap params = new HashMap<String,String>();

  			if(apiCall.equals("addPost")) {
  				response = connector.addPost(new HashMap<String,String>(), content);

  			}else if(apiCall.equals("addLike")) {
  				params.put("id",methodParam.get("postId").toString());
  				response = connector.addLike(params);	// post id

  			}else if(apiCall.equals("deleteLike")) {
  				params.put("id",methodParam.get("postId").toString());
  				response = connector.deleteLike(params);	// post id

  			}else if(apiCall.equals("addShare")) {
  				params.put("id",methodParam.get("postId").toString());
  				response = connector.addShare(params);  // post id

  			}else if(apiCall.equals("deleteShare")) {
  				params.put("id",methodParam.get("postId").toString());
  				response = connector.deleteShare(params); // post id

  			}else if(apiCall.equals("addFollowing")) {
  				params.put("id",methodParam.get("connectionId").toString());
  				response = connector.addFollowing(params);  // id - connection id

  			}else if(apiCall.equals("deleteFollowing")) {
  				params.put("id",methodParam.get("connectionId").toString());
  				response = connector.deleteFollowing(params); // id - connection id

  			}else if(apiCall.equals("addConversation")) {
  				params.put("id",methodParam.get("connectionId").toString());
  				response = connector.addConversation(params, content); // id - connection id, content

  			}else if(apiCall.equals("getFollower")) {
  				params.put("id",methodParam.get("connectionId").toString());
  				response = connector.getFollower(params); // id - connection id

  			}else if(apiCall.equals("getFollowing")) {
  				params.put("id",methodParam.get("connectionId").toString());
  				response = connector.getFollowing(params); // id - connection id

  			}else if(apiCall.equals("getConnection")) {
  				params.put("name",methodParam.get("userName").toString());
  				response = connector.getConnection(params); // @userName

  			}

  			if(connector!=null) {

	  				paramJson.put("param",param);
	  				paramJson.put("methodParam",methodParam);
	  				paramJson.put("content",content);

	  				resultObj.put("response", response);
  				resultObj.put("remoteAddress", remoteAddr);
  				resultObj.put("SocialServiceConnector", connector);
  				resultObj.put("paramJson", paramJson);
  			}

  		}catch(Exception e){

  			resultObj.put("Exception",e.toString());
  			status=false;

  		}

  		resultObj.put("status", status);
  		return resultObj;

  	}

    /**
     *
     * @return
     * @throws Exception
     */
    public JSONObject facebookAPI() throws Exception {

		JSONObject paramJson = new JSONObject();
		JSONObject resultObj = new JSONObject();
		JSONObject response = new JSONObject();

		try {

			HttpServletRequest request = IAMUtil.getCurrentRequest();

			JSONObject param = new JSONObject(request.getParameter("params"));
			JSONObject methodParam = new JSONObject(request.getParameter("methodParam"));
			String content = request.getParameter("Content");
			CrmSocialUtil util = new CrmSocialUtil();
			String token = util.getSocialOAuthToken(param.get("portalId").toString()); //NO I18N
			String soid = param.get("soid").toString();
			String zuid = param.get("zuid").toString();
			String social_brand_id = param.get("social_brand_id").toString();
			String apiCall = param.get("apiCall").toString();
			String networks = "facebook"; //NO I18N

			HashMap params = new HashMap<String,String>();

			if(apiCall.equals("publishPost")) {
				params.put("content",content);
				params.put("networks",methodParam.get("networks").toString());
				response = SocialRestAPIConnector.publishPost(soid, Long.valueOf(zuid),Long.valueOf(social_brand_id), token, params);

			}else if(apiCall.equals("addLike")) {
				params.put("brand_id",methodParam.get("social_brand_id").toString());
				response = SocialRestAPIConnector.addLike(soid, Long.valueOf(zuid), token, networks, methodParam.get("objectId").toString(), params);

			}else if(apiCall.equals("addComment")) {
				params.put("brand_id",methodParam.get("social_brand_id").toString());
				params.put("message",content);
				params.put("add_dm_link","false");
				response = SocialRestAPIConnector.addComment(soid, Long.valueOf(zuid), token, networks, methodParam.get("objectId").toString(), params);

			}else if(apiCall.equals("sendMessage")) {
				params.put("brand_id",methodParam.get("social_brand_id").toString());
				params.put("message",content);
				params.put("receiver_id",methodParam.get("receiver_id").toString());
				response = SocialRestAPIConnector.sendMessage(soid, Long.valueOf(zuid), token, networks, methodParam.get("objectId").toString(), params);

			}

			paramJson.put("param",param);
			paramJson.put("methodParam",methodParam);
			paramJson.put("content",content);

			resultObj.put("response", response);
			resultObj.put("OAuthToken", token);
			resultObj.put("paramJson", paramJson);

		}catch(Exception e){

			resultObj.put("Exception",e.toString());
  			status=false;

  		}

		resultObj.put("status", status);
		return resultObj;
	}


