    public void invokeVOCResyncScheduler() {
    	try {

			String zgid=request.getParameter("zgid");

    		VOCCommonUtil.deleteScheduler(VOCConstants.VOC_EMAIL_RESYNC_SCHEDULER , VOCConstants.VOC_EMAIL_RESYNC_SCHEDULER);
    		
			ScheduledJobDetails jobDetails = new ScheduledJobDetails();
			
			JSONObject info=new JSONObject();

			int scheduleTime = 2;

			info.put("zgid", zgid);

			info.put("userId", userId);
			
			Calendar calendar =GregorianCalendar.getInstance(java.util.TimeZone.getTimeZone("GMT"));

			jobDetails.setActionInfo(info);

			jobDetails.setUserId(userId);

			jobDetails.setStatus(ScheduledJobDetails.Status.SCHEDULED);

			jobDetails.setActionType(VOCConstants.VOC_EMAIL_RESYNC_SCHEDULER);

			calendar.add(Calendar.SECOND, scheduleTime);

			Long millis = calendar.getTimeInMillis();

			Timestamp startTime = new Timestamp(millis);

			jobDetails.setStartTime(millis);

			jobDetails.setSeType(VOCConstants.VOC_EMAIL_RESYNC_SCHEDULER);

			DataObject schDO = CrmScheduledJobsUtil.addAndPersistJobDetails(jobDetails, null);

			Row schRow = schDO.getRow(CRMSCHEDULEDJOBS.TABLE);

			Long jobid = Long.parseLong(schRow.get(CRMSCHEDULEDJOBS.JOBID).toString());

			CrmJobBean jobBean = new CrmJobBean(jobid, VOCEmailResyncScheduler.class.getName(), ZohoCRMScheduleConstants.VOC_THREADPOOL, startTime);

			jobBean.setTransactionTimeout(-1);

			ZohoCRMSchedule.addOneTimeJob(jobBean);
    	}
    	catch(Exception ex) {
    		
            resultObj.put("response", "operation failed");

    	}
    }
    
    
