    /**
     * @return
     */
    public JSONObject setMaximumSizeLimitForUploadFields() {
    	try {

    		String ids = request.getParameter("fieldIds");
    		Long size = Long.valueOf(request.getParameter("size"));

    		List<String> fieldIds = new ArrayList<String>();
    		for(String id : ids.split(","))
    		{
    			fieldIds.add(id);
    		}

    		DataObject fieldsDO = FieldUtil.getFieldsDOFromFieldIds(fieldIds, getZGID().toString());
    		if(!fieldsDO.isEmpty())
    		{
    			Criteria cr = new Criteria(Column.getColumn(CRMFIELD.TABLE,CRMFIELD.UITYPE), new Integer[]{CoreFieldConstants.UITYPE.UPLOAD.FILE_UPLOAD.getValue(),CoreFieldConstants.UITYPE.UPLOAD.IMAGE_UPLOAD.getValue()},QueryConstants.IN);
    			Iterator<Row> fieldsItr = fieldsDO.getRows(CRMFIELD.TABLE, cr);
    			while(fieldsItr.hasNext())
    			{
    				Row fieldRow = fieldsItr.next();
    				String fieldProp =fieldRow.getString(CRMFIELD.FIELDPROP);
    				JSONObject fieldPropJSON = null;
					if(fieldProp == null) {
						fieldPropJSON =	new JSONObject().put("maximum_allowed_size", size);
					} else {
						fieldPropJSON = new JSONObject(fieldProp);
						fieldPropJSON.put("maximum_allowed_size", size);
					}
					fieldRow.set(CRMFIELD.FIELDPROP, fieldPropJSON.toString());
    				fieldsDO.updateRow(fieldRow);
    			}
    		}
    		PersistenceCacheUtil.getPurePersistenceLiteHandle().update(fieldsDO);

    		resultObj.put("response", "MaximumSizeLimitForUploadFields update successfully completed");
    	} catch (Exception e){
    		status = false;
    		resultObj.put("response", e.toString());
    	}
        resultObj.put("status", status);
    	return resultObj;
    }

