     public JSONObject updateVocEmailResyncStatus() {
    	VOCPluginUtil pluginUtil = new VOCPluginUtil();
    	try {
			if(pluginUtil.isExtensionActive()) {
				Long vocPluginId = pluginUtil.getVOCPluginId();
				EASKeyValueUtil  keyVal = new EASKeyValueUtil(OrgUtil.getCurrentZGID());
				Criteria cr = new Criteria(Column.getColumn("EASConfigDetails", "SERVICEID"), vocPluginId,QueryConstants.EQUAL);
				cr = cr.and(Column.getColumn("EASConfigDetails", EASCONFIGDETAILS.STATUS), 2, QueryConstants.NOT_EQUAL);
				DataObject dataObj = keyVal.getCachedDataObject(cr);
				
				if(dataObj != null && dataObj.isEmpty()) {

					Criteria crt = new Criteria(Column.getColumn(CRMSCHEDULEDJOBS.TABLE, CRMSCHEDULEDJOBS.ACTION), VOCConstants.VOC_EMAIL_RESYNC_SCHEDULER, QueryConstants.EQUAL);
					crt = crt.and(new Criteria(Column.getColumn(CRMSCHEDULEDJOBS.TABLE, CRMSCHEDULEDJOBS.TYPE), VOCConstants.VOC_EMAIL_RESYNC_SCHEDULER, QueryConstants.EQUAL));
					
					DataObject schDO=CrmScheduledJobsUtil.getCrmScheduledDataObject(crt);
					
					if (!schDO.isEmpty()) {
						Row resyncRow = schDO.getFirstRow(CRMSCHEDULEDJOBS.TABLE);
						Long jobId = Long.parseLong(resyncRow.get(CRMSCHEDULEDJOBS.JOBID).toString());

						ZohoCRMSchedule.deleteOneTimeJob(jobId, ZohoCRMScheduleConstants.VOC_THREADPOOL);
						CrmScheduledJobsUtil.deleteJob(jobId);
					}
					
				}else if(dataObj != null) {
					Iterator<Row> rows = dataObj.getRows("EASConfigDetails");
					while(rows.hasNext()) {
						Row row = rows.next();
						String featureName = (String) row.get(EASCONFIGDETAILS.FEATURENAME);
						keyVal.insertOrUpdateKey(featureName, null, null, 2, -1);
					}
				}
			}
    	}
		catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }
    
    
