    /**
     * Use this with param service_name to get the handshake id for the service in CrossOrg Integration flow.
     *
     * @author dilip-14507
     * @return handshakeid
     * @throws JSONException
     */
    public JSONObject getCrossOrgHandshakeId() throws Exception {
    	String serviceName = request.getParameter("service_name"); //NO I18N
		try {
			if (serviceName == null || serviceName.isEmpty() || serviceName.isBlank()) {
				throw new Exception("INVALID VALUE for service_name");
			}
			List<APIKeyBean> apiKeyBeans = CrmAPIKeyUtil.getInstance(zgId, serviceName, 3);
			if (apiKeyBeans.size() == 1) {
				StringBuilder responseBuilder = new StringBuilder();
				responseBuilder.append(zgId).append("@").append(apiKeyBeans.get(0).getKeyId());
				resultObj.put("response", responseBuilder.toString());
			} else if (apiKeyBeans.size() < 1) {
				throw new Exception("NO RESULTS FOUND");
			} else if (apiKeyBeans.size() > 1) {
				throw new Exception("MORE RESULTS FOUND ERROR");
			}
		} catch (Exception e) {
			status = false;
            resultObj.put("response", e.toString());
		}
    	return resultObj;
    }

    public JSONObject getCstoreLagTimeInMinutes() throws JSONException { // ###used
        String time = null;
        try {
        	Long lastUpdatedTime = DBUtil.getCstoreLagTime(String.valueOf(zgId));
        	if(lastUpdatedTime != null) {
        		Long diff = System.currentTimeMillis() - lastUpdatedTime;
        		time = String.valueOf(TimeUnit.MILLISECONDS.toMinutes(diff));
        	}
            resultObj.put("response", time);
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }
    
    
