	/**
	*
	*
	* @author richard-6615
	*/
    public static boolean resetLiteProfilePermisssions(String[] tabNames) throws Exception
    {
    	Long profileId = CrmLiteUser.getLiteProfile();
    	if(profileId == null) {
    		return true;
    	}
    	int len = tabNames.length;
    	Set<Long> tabids = new HashSet<Long>();
    	for(int i=0;i<len;i++) {
    		tabids.add(TabUtil.getTabIdByName(tabNames[i]));
    	}
    	DataObject dob = PersistenceCacheUtil.getPersistenceLiteHandle().constructDataObject();
    	DataObject permissionObj = ProfileUtil.getCachedPermissionsDO();
    	List<Long> permissionIds = new ArrayList<Long>();
    	
    	addLightModuleProfilePermissions(permissionObj,permissionIds, tabids);
        List<Long> subformTabIds = CrmSubformUtil.isSubformPermissionsEnabled() ? TabUtil.getAllSubFormTabIds() : TabUtil.getAllSubTabIdsForGivenTabIds(new ArrayList<>(tabids));
    	addSubformProfilePermission(permissionIds,subformTabIds,dob,permissionObj,profileId);
    	addLightSetupPermission(permissionObj,permissionIds );
    	addProfileTabRel(tabids, profileId, subformTabIds);

     	String[] notesAttach = new String[]{"Crm_Implied_View_Notes","Crm_Implied_Edit_Notes","Crm_Implied_Create_Notes","Crm_Implied_Delete_Notes","Crm_Implied_View_Attachments","Crm_Implied_Create_Attachments","Crm_Implied_Delete_Attachments" }; //no i18n
     	int notesLen = notesAttach.length;
     	for(int i=0;i<notesLen;i++){
     		permissionIds.add(ProfileUtil.getPermissionIdByName(notesAttach[i]));
     	}
     	ProfileUtil.enableProfilePermissions(profileId, permissionIds);
     	DataObject profilePermissionsDO = ProfileUtil.getProfilePermissionDO(profileId, null);
     	Criteria cri = new Criteria(Column.getColumn(CRMPROFILEPERMISSIONS.TABLE, CRMPROFILEPERMISSIONS.PERMISSIONID), permissionIds.toArray(), QueryConstants.NOT_IN);
     	cri = cri.and(new Criteria(Column.getColumn(CRMPROFILEPERMISSIONS.TABLE, CRMPROFILEPERMISSIONS.PRESENCE), PermissionPresenceType.ENABLE.getValue(), QueryConstants.EQUAL));
      	Iterator<Row> disabledPermissionsItr = profilePermissionsDO.getRows(CRMPROFILEPERMISSIONS.TABLE, cri);
      	List<Long> disablePermissionIds = new ArrayList<Long>();
      	while(disabledPermissionsItr.hasNext()) {
      		Row row = disabledPermissionsItr.next();
      		Long permissionId = (Long)row.get(CRMPROFILEPERMISSIONS.PERMISSIONID);
      		disablePermissionIds.add(permissionId);
      	}
      	ProfileUtil.disableProfilePermissions(profileId, disablePermissionIds);
    	return true;
    }
	/**
	*
	*
	* @author richard-6615
	*/
	public static void addProfileTabRel(Set<Long> tabIds, Long profileId, List<Long>subformTabIds) throws Exception{
		List<Long> allTabIds = new ArrayList<Long>(tabIds);

		allTabIds.addAll(subformTabIds);
		allTabIds.add(TabUtil.getTabIdByName(CrmModuleConstants.NOTES));
		allTabIds.add(TabUtil.getTabIdByName(CoreModuleConstants.ATTACHMENTS));
		allTabIds.add(TabUtil.getTabIdByName(CrmModuleConstants.HOME));
		allTabIds.add(TabUtil.getTabIdByName(CrmModuleConstants.FEEDS));
		allTabIds.add(TabUtil.getTabIdByName(CrmModuleConstants.APPROVALS));
		allTabIds.add(TabUtil.getTabIdByName(CrmModuleConstants.SOCIAL));
		allTabIds.add(TabUtil.getTabIdByName(CoreModuleConstants.USERS));
                allTabIds.add(TabUtil.getTabIdByName(CrmModuleConstants.LOCKING_INFORMATION));
		Criteria profileTabCr = new Criteria(Column.getColumn(CRMPROFILETABREL.TABLE, CRMPROFILETABREL.PROFILEID),profileId,QueryConstants.EQUAL);
		profileTabCr = profileTabCr.and(new Criteria(Column.getColumn(CRMPROFILETABREL.TABLE, CRMPROFILETABREL.TABID),allTabIds.toArray(),QueryConstants.IN));

		UpdateQuery uq = new UpdateQueryImpl(CRMPROFILETABREL.TABLE);
      	uq.setCriteria(profileTabCr);
      	uq.setUpdateColumn(CRMPROFILETABREL.ISVISIBLE,true);
      	PersistenceCacheUtil.getPersistenceLiteHandle().update(uq);

      	 profileTabCr = new Criteria(Column.getColumn(CRMPROFILETABREL.TABLE, CRMPROFILETABREL.PROFILEID),profileId,QueryConstants.EQUAL);
		profileTabCr = profileTabCr.and(new Criteria(Column.getColumn(CRMPROFILETABREL.TABLE, CRMPROFILETABREL.TABID),allTabIds.toArray(),QueryConstants.NOT_IN));

		UpdateQuery uq1 = new UpdateQueryImpl(CRMPROFILETABREL.TABLE);
      	uq1.setCriteria(profileTabCr);
      	uq1.setUpdateColumn(CRMPROFILETABREL.ISVISIBLE,false);
      	PersistenceCacheUtil.getPersistenceLiteHandle().update(uq1);
	}
