    /**
	*To reset the time of the previewId and generate new one
	*
	*/
	public JSONObject resetTimeForPreviewId() throws Exception{
		
		String previewId = request.getParameter("previewId");
		String[] decryptedVal = EncryptAgent.getInstance().decrypt("ZohoCRM", previewId, RebrandLinkUtil.getRebrandKeys("EAR_DB_Token"), false).split("###");//No I18N
		AttachmentUtil attachmentScope = (AttachmentUtil) ScopedAccess.getInstance(AttachmentUtil.class, decryptedVal[0], TransactionType.NOSUPPORT);
		Integer type = null;
		double expiredTime;
		if(!request.getParameter("time").isEmpty()) {
			expiredTime = Double.parseDouble(request.getParameter("time"));
		}
		else {
			 expiredTime = Double.parseDouble(decryptedVal[1]) - 3 * 30.4368 * 1440 * 60 * 1000;
		}
		String encryptionValue = decryptedVal[0]+"###"+(long) expiredTime+"###"+Long.valueOf( decryptedVal[2] )+"###"+decryptedVal[3]+"###inline###"+type;
		JSONObject previewJObj =  new JSONObject();
		previewJObj.put("newpreviewId", EncryptAgent.getInstance().encrypt("ZohoCRM", encryptionValue, RebrandLinkUtil.getRebrandKeys("EAR_DB_Token"), false));//no i18n
		resultObj.put("response","Reset Successful"); //No I18N
		resultObj.put("status", true); //no i18n
		resultObj.put("details", previewJObj); //no i18n
		return resultObj;
     }

