    public JSONObject execute(String action) throws Exception {
        Constants constants = new Constants();
        JSONObject responseObj = new JSONObject();
        try {
            Method method = this.getClass().getDeclaredMethod(action);
            method.setAccessible(true);
            JSONObject configurationResponse = (JSONObject) method.invoke(this);
//            responseObj.put(constants.code, configurationResponse.has("status") ? configurationResponse.getBoolean("status") ? constants.error_code_ins.success : constants.error_code_ins.failure : constants.error_code_ins.success);
            responseObj.put(constants.code, resultObj.has("status") ? resultObj.getBoolean("status") ? constants.error_code_ins.success : constants.error_code_ins.failure : constants.error_code_ins.success);
    		responseObj.put(constants.details, resultObj.has("details") ? resultObj.getJSONObject("details") : new JSONObject());
    		responseObj.put(constants.message, resultObj.has("response") ? resultObj.getString("response") : JSONObject.NULL); // No i18n
            responseObj.put(constants.status_small, resultObj.has("status") ? resultObj.getBoolean("status") ? APIConstants.SUCCESS : APIConstants.ERROR : APIConstants.SUCCESS);
        }
        catch(NoSuchMethodException e) {
            responseObj.put(constants.code, constants.error_code_ins.invalid_data);
            responseObj.put(constants.details, new JSONObject());
            responseObj.put(constants.message, "Invalid action"); // No i18n
            responseObj.put(constants.status_small, APIConstants.ERROR);
        }
        return responseObj;
    }
