    public JSONObject failureDeluge() throws JSONException
    {
	   	 try
	   	 {
		   	 Long entityId = Long.valueOf(request.getParameter("entityId"));
		   	 Long ruleId = Long.valueOf(request.getParameter("ruleId"));
		   	 Criteria customFnCrt=new Criteria( Column.getColumn(CRMWFDELUGE.TABLE, CRMWFDELUGE.ISDELETED), false, QueryConstants.EQUAL);
		   	 SelectQuery retryQry = new SelectQueryImpl(Table.getTable(CRMWFDELUGE.TABLE));
		   	 retryQry.addSelectColumn(Column.getColumn(null, "*"));
		   	 retryQry.setCriteria(customFnCrt);
		   	 retryQry.setRange(new Range(0,1));
		   	 DataObject customFnRetryDO = PersistenceCacheUtil.getPersistenceLiteHandle().get(retryQry);
		   	 Row customActionRow = customFnRetryDO.getFirstRow(CRMWFDELUGE.TABLE);
		   	 Long delugeId = (Long) customActionRow.get(CRMWFDELUGE.WFDELUGEID);
		   	 WFDelugeUtil.addFailureWFDeluge(delugeId, entityId, ruleId, null, 1, null, null, -1, currentUserId, null, null, null, null);
		   	 resultObj.put("status", "success");// NO I18N
	   	 }
	   	 catch(Exception e)
	   	 {
	   		 status = false;
	   		 resultObj.put("response", e.toString());
	   	 }
   	 	resultObj.put("status", status);
   	 	return resultObj;
   	 }

    public JSONObject retryWebhook() throws JSONException
    {
    	try
    	{
    		String webhookUrl = request.getParameter("webhookUrl");
    		DataObject retryDO = WorkFlowActionsUtil.getAutomationQueueRetryDO(CrmAutomationConstants.AUTOMATION_WEBHOOK_RETRY, true);
    		Iterator<Row> rows = retryDO.getRows(CRMAUTOMATIONQUEUE.TABLE);
			   while(rows.hasNext())
			   {
				   Row retryRow = rows.next();
				   JSONObject retryData = new JSONObject((String)retryRow.get(CRMAUTOMATIONQUEUE.ENTRY_DETAILS));
				   retryData.put("urlToNotify", webhookUrl);
				   retryRow.set(CRMAUTOMATIONQUEUE.ENTRY_DETAILS, retryData.toString());
				   retryDO.updateRow(retryRow);
			   }
			   PersistenceCacheUtil.getPersistenceLiteHandle().update(retryDO);
			   resultObj.put("status", "success");// NO I18N
    	}
    	catch(Exception e)
    	{
    		status = false;
    		resultObj.put("response", e.toString());
    	}
    	resultObj.put("status", status);
   	 	return resultObj;
    }

