    public JSONObject triggerdynamicautoresponder() throws JSONException { // ###used
        try {
            SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMAUTORESPONDER.TABLE));
            sq.addSelectColumn(Column.getColumn(CRMAUTORESPONDER.TABLE, CRMAUTORESPONDER.RESPONDERID));
            sq.addSelectColumn(Column.getColumn(CRMAUTORESPONDER.TABLE, CRMAUTORESPONDER.INSTANCEID));
            DataObject dataObj = PersistenceCacheUtil.getNonCachePersistenceHandle().get(sq);
            Long jobId = null;
            @SuppressWarnings("rawtypes")
            Iterator r = dataObj.getRows(CRMAUTORESPONDER.TABLE);
            while (r.hasNext()) {
                Row ro = (Row) r.next();
                jobId = (Long) ro.get(CRMAUTORESPONDER.INSTANCEID);
                ro.get(CRMAUTORESPONDER.RESPONDERID);
                if (jobId != null) {
                    ZohoCRMSchedule.updateRepetitiveJobById(jobId, CoreScheduleConstants.RECURRING_LOW_PROCESS, true, new Timestamp(System.currentTimeMillis() + 1000 * 60));
                    resultObj.put("response", "job rescheduled" + jobId); //no i18n
                } else {
                    resultObj.put("response", "There is no jobs execute"); //no i18n
                }
            }
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }
