    public JSONObject executeRoutineMsgJob() throws JSONException { // ###used
        try {
        	String configId = request.getParameter("id"); // No I18N
            SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMINTELLIGENCECONFIG.TABLE));
            sq.addSelectColumn(Column.getColumn(null, "*"));
            sq.setCriteria(new Criteria(Column.getColumn(CRMINTELLIGENCECONFIG.TABLE, CRMINTELLIGENCECONFIG.INTELLIGENCECONFIGID), configId,QueryConstants.EQUAL));
            sq.setRange(new Range(0, 1));
            DataObject dataObj = PersistenceCacheUtil.getNonCachePersistenceHandle().get(sq);
            Row row = dataObj.getFirstRow(CRMINTELLIGENCECONFIG.TABLE);
            Long jobId = (Long) row.get(CRMINTELLIGENCECONFIG.FEATURERELATEDID);
            if (jobId != null) {
                ZohoCRMSchedule.updateRepetitiveJobById(jobId, CoreScheduleConstants.RECURRING_LOW_PROCESS, true, new Timestamp(System.currentTimeMillis()));
                resultObj.put("response", "job rescheduled"); //no i18n
            } else {
                resultObj.put("response", "There is no jobs execute"); //no i18n
            }
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }
    
    public JSONObject deleteChatbotConfig() throws JSONException { // ###used
        try {
        	String userId = request.getParameter("userid");
        	Persistence persistence =  PersistenceCacheUtil.getPurePersistenceLiteHandle();
			Criteria cr = new Criteria(Column.getColumn(CRMZIANOTIFICATIONCONFIG.TABLE,CRMZIANOTIFICATIONCONFIG.CONFIG_TYPE), ChatbotConstants.CHATBOT_CONFIGID, QueryConstants.EQUAL);
			cr = cr.and(new Criteria(Column.getColumn(CRMZIANOTIFICATIONCONFIG.TABLE,CRMZIANOTIFICATIONCONFIG.USERID), userId, QueryConstants.EQUAL));
			persistence.delete(cr);
			status = true;
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }
    
