    public JSONObject triggerAnomalyNotification() throws Exception {
        try {
        	String leadSample = "{'summary':[{'type':'title','key':'crm.intelligence.alert.title'},{'type':'body','key':'crm.intelligence.leadsattention.body.week','values':['Leads','65']}],'details':{'date':['2018-12-03','2018-12-10','2018-12-17','2018-12-24','2018-12-31','2019-01-07','2019-01-14','2019-01-21','2019-01-28','2019-02-04','2019-02-11','2019-02-18','2019-02-25','2019-03-04','2019-03-11','2019-03-18','2019-03-25','2019-04-01','2019-04-08','2019-04-15'],'original':{'crm.api.count':['154','175','190','151','98','149','180','173','82','145','159','161','180','174','71']},'normal':{'crm.api.count':['167.35508683394985','167.68121235919497','168.0073378844401','168.3334634096852','168.65958893493033','168.98571446017542','169.31183998542053','169.63796551066565','169.96409103591077','170.2902165611559','170.616342086401','170.94246761164612','171.26859313689124','171.59471866213636','171.92084418738148','173.2592567692161','173.52633062631637','173.77924547418985','174.0219091562054','174.2564130247633']},'anomaly':{'crm.api.count':['-1','-1','-1','-1','41','-1','-1','-1','54','-1','-1','-1','-1','-1','65']},'features':['crm.api.count'],'currentPeriodIndex':15,'period':'week','code':0,'title':'Leads Creation'},'isForTeam':false}"; //No I18N
        	JSONObject msgJson = new JSONObject(leadSample);
        	Long notificaitonId = NotificationUtil.constructDINotificationQA(UserUtil.getCurrentUserId(), 3, msgJson, "DINOTIFICATION", true);	//no i18n
        	if(notificaitonId != 0L) {
        		resultObj.put("response", "Message pushed successfully"); //no i18n
        	} else {
        		resultObj.put("response", "Message not pushed"); //no i18n
        	}
        } catch (Exception exception) {
            LOGGER.log(Level.SEVERE, "Exception on triggerAnomalyNotification :: ",exception);
            throw exception;
        }
        return new JSONObject().put("response", resultObj);
    }
