    public JSONObject dependency() throws JSONException { // ###used
        try {
            Criteria cr = new Criteria(Column.getColumn(CRMFIELDDEPREL.TABLE, CRMFIELDDEPREL.UID), 1, QueryConstants.GREATER_THAN);
            cr = cr.and(new Criteria(Column.getColumn(CRMFIELDDEPREL.TABLE, CRMFIELDDEPREL.ISINTERNAL), Boolean.TRUE, QueryConstants.NOT_EQUAL));
            cr = cr.and(new Criteria(Column.getColumn(CRMFIELDDEPREL.TABLE, CRMFIELDDEPREL.CATEGORY), CustomModuleUtil.CATEGORY_PIPELINE, QueryConstants.NOT_EQUAL));
            PersistenceCacheUtil.getNonCachePersistenceHandle().delete(cr);
            if(OrgUtil.isSandboxAccount())
            {
            	Criteria deleteCr = new Criteria(Column.getColumn(CRMSANDBOXCONFIGCHANGES.TABLE, CRMSANDBOXCONFIGCHANGES.CHANGESETID), null, QueryConstants.EQUAL);
                deleteCr=deleteCr.and(new Criteria(Column.getColumn(CRMSANDBOXCONFIGCHANGES.TABLE, CRMSANDBOXCONFIGCHANGES.CONFIGTYPE), SandboxConfigConstants.FIELDDEP, QueryConstants.EQUAL));
             	Persistence per = PersistenceCacheUtil.getPurePersistenceLiteHandle();
             	CommonDBUtil.deleteWithLimit(CRMSANDBOXCONFIGCHANGES.TABLE, deleteCr, per, 1000);
            }
            resultObj.put("response", "Map dependency deleted"); //no i18n
            
            String zgid = OrgUtil.getCurrentZGID().toString();
    		List<Entry<String, String>> result = CrmCacheProxy.getHashExecutor(CrmFeature.BASIC, zgid).getMapPage(zgid, "0").getResult();// No I18N
    		List<String> list = new ArrayList<String>();
    		for(Entry<String,String> a: result)
    		{
    			String key = a.getKey();
    			if(key.startsWith("DEPMAP_COMP_"))
    			{
    				list.add(key);
//    				CrmCacheUtil.deleteKeyInMap(zgid, key, null, zgid);
    			}
    		}
    		String keys[] = list.toArray(new String[list.size()]);
    		CrmCacheProxy.getHashExecutor(CrmFeature.BASIC, zgid).deleteMultipleKeysInMap(zgid, keys);
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }
    
    public JSONObject deleteMacros() throws JSONException {
        try {
//            for (int i = 0; i < modules2.length; i++) {
                List < Object[] > objList = MacroUtil.getAllMacrosWithDetailsForMod("all");//NO I18n
                for (Object eachMacro[]: objList) {
                    MacroUtil.deleteMacroRuleAndRelatedDetails((Long) eachMacro[5]);
					MacroSuggestUtil.handleMacroUpdOrDelForSugg((Long)eachMacro[5], null, null);
                }
//            }
            MacroUtil.deleteMacrosForUser(userId);

            //deleting unwanted field updates
            SelectQuery sqt = new SelectQueryImpl(Table.getTable(CRMWFREL.TABLE));
            sqt.addSelectColumn(Column.getColumn(CRMWFREL.TABLE, CRMWFREL.RULEID));
            sqt.addSelectColumn(Column.getColumn(CRMWFREL.TABLE, CRMWFREL.WFRELID));
            sqt.addSelectColumn(Column.getColumn(CRMWFREL.TABLE, CRMWFREL.TYPE));
            Criteria criterit = new Criteria(Column.getColumn(CRMWFREL.TABLE, CRMWFREL.TYPE), 1, QueryConstants.EQUAL);

            SelectQuery sqt2 = new SelectQueryImpl(Table.getTable(CRMWORKFLOWRULE.TABLE));
            sqt2.addSelectColumn(Column.getColumn(CRMWORKFLOWRULE.TABLE, CRMWORKFLOWRULE.RULEID));
            DerivedColumn dct = new DerivedColumn(CRMWFREL.RULEID, sqt2);

            Criteria lastt = new Criteria(new Column(CRMWFREL.TABLE, CRMWFREL.RULEID), dct, QueryConstants.NOT_IN);
            criterit = criterit.and(lastt);
            sqt.setCriteria(criterit);
            DataObject dataObjt = PersistenceCacheUtil.getNonCachePersistenceHandle().get(sqt);

            @SuppressWarnings("rawtypes")
			Iterator ite = dataObjt.getRows(CRMWFREL.TABLE);
            while (ite.hasNext()) {
	            Row row = dataObjt.getRow(CRMWFREL.TABLE);
	            ArrayList<String> fieldIdsArray = new ArrayList<String>();
	            fieldIdsArray.add(row.get(CRMWFREL.RULEID).toString());
	            Criteria fieldDelCri = new Criteria(new Column(CRMWFREL.TABLE, CRMWFREL.RULEID), fieldIdsArray, QueryConstants.IN);

	            dataObjt.deleteRows(CRMWFREL.TABLE, fieldDelCri);
	            PersistenceCacheUtil.getPurePersistenceLiteHandle().update(dataObjt);
            }

            //deleting unwanted field updates
            SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMWFFIELDUPDATE.TABLE));
            sq.addSelectColumn(Column.getColumn(CRMWFFIELDUPDATE.TABLE, CRMWFFIELDUPDATE.WFFIELDUPDATEID));
            sq.addSelectColumn(Column.getColumn(CRMWFFIELDUPDATE.TABLE, CRMWFFIELDUPDATE.TYPE));
            Criteria criteri = new Criteria(Column.getColumn(CRMWFFIELDUPDATE.TABLE, CRMWFFIELDUPDATE.TYPE), 1, QueryConstants.EQUAL);

            SelectQuery sq2 = new SelectQueryImpl(Table.getTable(CRMWFREL.TABLE));
            sq2.addSelectColumn(Column.getColumn(CRMWFREL.TABLE, CRMWFREL.WFFIELDUPDATEID));
            DerivedColumn dc = new DerivedColumn(CRMWFFIELDUPDATE.WFFIELDUPDATEID, sq2);

            Criteria last = new Criteria(new Column(CRMWFFIELDUPDATE.TABLE, CRMWFFIELDUPDATE.WFFIELDUPDATEID), dc, QueryConstants.NOT_IN);
            criteri = criteri.and(last);
            sq.setCriteria(criteri);
            DataObject dataObj = PersistenceCacheUtil.getNonCachePersistenceHandle().get(sq);

            if(dataObj.containsTable(CRMWFFIELDUPDATE.TABLE)){
            	dataObj.deleteRows(CRMWFFIELDUPDATE.TABLE, (Criteria) null);
            	PersistenceCacheUtil.getPurePersistenceLiteHandle().update(dataObj);
            }

            //deleting unwanted field updates
            SelectQuery sqall = new SelectQueryImpl(Table.getTable(CRMWFFIELDUPDATE.TABLE));
            sqall.addSelectColumn(Column.getColumn(CRMWFFIELDUPDATE.TABLE, CRMWFFIELDUPDATE.WFFIELDUPDATEID));
            Criteria criteriall = new Criteria(Column.getColumn(CRMWFFIELDUPDATE.TABLE, CRMWFFIELDUPDATE.TYPE), 1, QueryConstants.EQUAL);
            sqall.setCriteria(criteriall);
            DataObject dataObjall = PersistenceCacheUtil.getNonCachePersistenceHandle().get(sqall);

            if(dataObjall.containsTable(CRMWFFIELDUPDATE.TABLE)){
	            dataObjall.deleteRows(CRMWFFIELDUPDATE.TABLE, (Criteria) null);
	            PersistenceCacheUtil.getPurePersistenceLiteHandle().update(dataObjall);
            }
            String res = "";
            List < Object[] > obj = MacroUtil.getAllMacrosWithDetailsForMod("all");//NO I18n
            Set<String> updateModuleList = new HashSet<>();
            for(Object[] macroDetail:obj) {
            	updateModuleList.add(String.valueOf(macroDetail[2]));
            }
            for (int i = 0; i < modules2.length; i++) {
                if(updateModuleList.contains(modules2[i])){
                	res = res + "\nNot deleted for "+modules2[i];//no i18n
                }
            }
            if(res.equals("")){
            	resultObj.put("response", "Macro deleted"+res); //no i18n
            }else{
            	status = false;
            	resultObj.put("response", "Macro not deleted"+res); //no i18n
            }
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }

