    public JSONObject webforms() throws JSONException { // ###used
        try {
            String moduleName = request.getParameter("module");
            int count = 0;
            String resp = "";
            if(moduleName != null && !moduleName.equals("")){
                WebFormUtil.deleteAllWebForms(moduleName);
                count = WebFormUtil.getWebFormCount(moduleName);
                if(count != 0){
                	status = false;
                	resp = "WebForm not deleted from "+moduleName;// no i18n
                }else{
                	resultObj.put("response", "Webform deleted in >> "+moduleName+" , "+resp); //no i18n
                }
            }
            else{
                WebFormUtil.deleteAllWebLeadForms();
                WebFormUtil.deleteAllWebCaseForms();
                WebFormUtil.deleteAllWebContactForms();
                WebFormUtil.deleteAllWebVendorForms();
                WebFormUtil.deleteAllWebForms("CustomModule1"); // no i18n
                WebFormUtil.deleteAllWebForms("CustomModule51"); // no i18n
                count =  WebFormUtil.getWebFormCount(CrmModuleConstants.LEADS);
                if(count != 0){
                	status = false;
                    resp = resp + "\nWebForm not deleted from Leads";// no i18n
                }
                count =  WebFormUtil.getWebFormCount(CrmModuleConstants.CASES);
                if(count != 0){
                	status = false;
                    resp = resp + "\nWebForm not deleted from cases";// no i18n
                }
                count =  WebFormUtil.getWebFormCount(CrmModuleConstants.CONTACTS);
                if(count != 0){
                	status = false;
                    resp = resp + "\nWebForm not deleted from Contacts";// no i18n
                }
                count =  WebFormUtil.getWebFormCount("CustomModule1");// no i18n
                if(count != 0){
                	status = false;
                    resp = resp + "\nWebForm not deleted from CustomModule1";// no i18n
                }
                count =  WebFormUtil.getWebFormCount("CustomModule51");// no i18n
                if(count != 0){
                	status = false;
                    resp = resp + "\nWebForm not deleted from CustomModule51";// no i18n
                }
                if(status != false ){
                	resultObj.put("response", "Webform deleted in >> Leads, Contacts, Cases, CustomModule1 and CustomModule51"); //no i18n
                }
            }
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }
    
