    public JSONObject updateABTestingStartDateToCurrentTime() {
    	try {
    		String abTestId = request.getParameter("id");//NO I18N
    		DataObject abtestDo = WebFormABTestingUtil.getABTestDoById(abTestId, zgId.toString());
    		Row abtestRow = abtestDo.getFirstRow(CRMWEBFORMABTESTING.TABLE);
    		int rotationType = (Integer)abtestRow.get(CRMWEBFORMABTESTING.ROTATIONTYPE);
    		if(rotationType == WebFormABTestingUtil.VALID_CONDITIONS.indexOf(WebFormABTestingUtil.RANGE) ) {
        		Long currentTime = DateTimeUtils.getCurrentLongTimeInGMT();
    			JSONObject rotationValue = new JSONObject((String) abtestRow.get(CRMWEBFORMABTESTING.ROTATIONVALUE));
    			rotationValue.put(WebFormABTestingUtil.FROM, DateTimeUtils.getDayStartOrEndLongTime(currentTime, true));
    			abtestRow.set(CRMWEBFORMABTESTING.ROTATIONVALUE, rotationValue.toString());
    			abtestDo.updateRow(abtestRow);
    			PersistenceCacheUtil.getPurePersistenceLiteHandle().update(abtestDo);
    		}
    	}
    	catch (Exception e) {
    		status = false;
    		resultObj.put("response", e.toString());
    	}
		resultObj.put("response", true);
    	return resultObj;
    }

