    public JSONObject refresh_sandbox_account() throws JSONException {
    	try {
    		String sandboxName = request.getParameter("sandboxName");
    		Row sandboxRow;
    		if(sandboxName == null) {
    			sandboxRow = SandboxConfigUtil.getSandboxInfo();
    		} else {
    			SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMSANDBOXACCOUNTS.TABLE));
    	 		sq.addSelectColumn(Column.getColumn(null, "*"));

    	 		Criteria cr = SandboxConfigUtil.getBackupSandboxCriteria(false);
    	 		cr = cr.and(new Criteria(Column.getColumn(CRMSANDBOXACCOUNTS.TABLE, CRMSANDBOXACCOUNTS.NAME), sandboxName, QueryConstants.EQUAL));

    	 		sq.setCriteria(cr);
    	 		sq.addSortColumn(new SortColumn(Column.getColumn(CRMSANDBOXACCOUNTS.TABLE, CRMSANDBOXACCOUNTS.SANDBOXID), true));

    	 		DataObject dObj = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(sq);

    	 		sandboxRow = dObj.getRow(CRMSANDBOXACCOUNTS.TABLE);
    		}
    		if(sandboxRow == null) {
    			status = false;
    			resultObj.put("response", "Sandbox not found in this account");
    		} else {
    			Integer sandboxStatus = (Integer)sandboxRow.get(CRMSANDBOXACCOUNTS.STATUS);
    			Long jobId = (Long) sandboxRow.get(CRMSANDBOXACCOUNTS.SANDBOXID);
    			Long sandboxZgid = (Long) sandboxRow.get(CRMSANDBOXACCOUNTS.ZGID);
    			if(OrgUtil.getCurrentZGID().equals(sandboxZgid)) {
    				status = false;
    				resultObj.put("response", "Cannot invoke within sandbox account");
    			} else if(sandboxStatus.equals(SandboxConfigUtil.getSandboxStatusId(SandboxConfigUtil.CREATING)) || sandboxStatus.equals(SandboxConfigUtil.getSandboxStatusId(SandboxConfigUtil.REFRESHING))) {
    				status = false;
    				resultObj.put("response", "Already a create/refresh operation is being carried out for sandbox account");
    			} else if(!FeatureEditionUtil.isFeatureAvailable(FeatureNameConstants.SANDBOX, LicenseUtil.getActualLicenseType())) {
    				status = false;
    				resultObj.put("response", "Refresh Sandbox not supported");
    			} else {
    				//Deactivating SupportUser before rebuilding
            		try{
            			SupportAccessUtil.deactivateSupportAccessInSandBox(Long.valueOf(sandboxZgid));
            		}catch(Exception e) {
            			 LOGGER.log(Level.SEVERE, "Error on deactivating SupportUser during sandbox rebuild ResetConfiguration:::", e);
            		}
    				request.setAttribute("sandboxId", jobId);
    				SandboxCreationUtil beanInstance = (SandboxCreationUtil)ScopedAccess.getInstance(SandboxCreationUtil.class, null, TransactionType.REQUIREDNEW);
    				Long chosenSandboxId = beanInstance.reserveSandbox(SandboxConfigUtil.CONFIG, false, currentUserId, Long.valueOf(sandboxZgid));
    				SandboxCreationUtil.getInstance().refreshSandboxAccount(request, chosenSandboxId);
    				resultObj.put("response", "Sandbox account refresh initiated");
    			}
    		}
        }
        catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }
    public JSONObject is_active_sandbox() throws Exception {
		try {
			String sandboxOrgId = request.getParameter("orgId"); // No I18N
			SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMSANDBOXACCOUNTS.TABLE));
			sq.addSelectColumn(Column.getColumn(CRMSANDBOXACCOUNTS.TABLE, CRMSANDBOXACCOUNTS.SANDBOXID));
			sq.addSelectColumn(Column.getColumn(CRMSANDBOXACCOUNTS.TABLE, CRMSANDBOXACCOUNTS.ZGID));
			Criteria activeSandbox = new Criteria(Column.getColumn(CRMSANDBOXACCOUNTS.TABLE, CRMSANDBOXACCOUNTS.ZGID), sandboxOrgId, QueryConstants.EQUAL);
			activeSandbox = activeSandbox.and(new Criteria(Column.getColumn(CRMSANDBOXACCOUNTS.TABLE, CRMSANDBOXACCOUNTS.STATUS), new Integer[] {1,6}, QueryConstants.IN));
			sq.setCriteria(activeSandbox);
			DataObject dObj = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(sq);
			if (!dObj.isEmpty()) {
				status = true;
				// return true;
			}else {
				status = false;
			}
			resultObj.put("response", "Success");
		} catch (Exception e) {
			status = false;
			resultObj.put("response", e.toString());
		}
  	    resultObj.put("status", status);
  	    return resultObj;
//  		return false;
    }
    public JSONObject provideSandboxAccessForAll() throws Exception {
    	try {
	    	CrmUserCriteria userCriteria = new CrmUserCriteria();
			userCriteria.setIsSandBoxDevUser(true);
			userCriteria.setIsConfirmed(true);
			userCriteria.setIsActive(true);
			CrmUsersNonCache usersNonCache = CrmUsersNonCache.builder()
					.setUserCriteria(userCriteria)
					.build();
			List<Long> zuids = usersNonCache.getZuIdsAsList();
			SandboxConfigUtil.updateSandboxUserAccess(zuids.toArray(new Long[]{}), false, false, null);
			resultObj.put("response", "Success");
    	} catch (Exception e) {
    		resultObj.put("response", "Failed. Exception occured : " + SandboxConfigUtil.getExceptionTraceAsString(e));
    	}

		resultObj.put("status", status);
    	return resultObj;
    }

  //IMPORTANT ::: DO NOT CHANGE THIS METHOD - THIS METHOD USED FOR PROXYING - FOR ANY CHANGES RELATED TO undoAllImports() PLEASE USE _internal_undoAllImports()
  //CONTACT SERVER TEAM IF ANY ASSISTANCE NEEDED
	public JSONObject undoAllImports() throws JSONException {
		boolean isMassActionProxyEnabled = Boolean.valueOf(CrmDynamicProperty.getPropertyOrDefault("QA_AUTOMATION_MASS_ACTION_PROXY_ENABLED", "true"));// NO I18N
		if (isMassActionProxyEnabled) {
			ResetConfigurationsWithMassAction resetConfigWithMassAction = (ResetConfigurationsWithMassAction) MassActionProxy.getInstance(ResetConfigurationsWithMassAction.class);
			return resetConfigWithMassAction.undoAllImportsWithMassAction(this);
		} else {
			return this._internal_undoAllImports();
		}
	}
    
    public JSONObject _internal_undoAllImports() throws JSONException {
        try {
        	int count = 0;
        	SelectQuery sQry = new SelectQueryImpl(Table.getTable(CRMIMPORTINFO.TABLE));
            sQry.addSelectColumn(Column.getColumn(CRMIMPORTINFO.TABLE, CRMIMPORTINFO.IMPORTID));
            sQry.addSelectColumn(Column.getColumn(CRMIMPORTINFO.TABLE, CRMIMPORTINFO.IMPORTTYPE));
            sQry.addSelectColumn(Column.getColumn(CRMIMPORTINFO.TABLE, CRMIMPORTINFO.STATUS));
            Criteria criteria = new Criteria(Column.getColumn(CRMIMPORTINFO.TABLE, CRMIMPORTINFO.IMPORTSTATE), new int[] {
                100,
                101
            }, QueryConstants.IN);
            sQry.setCriteria(criteria);
            DataObject dbo = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(sQry);
            @SuppressWarnings("rawtypes")
            Iterator ite = dbo.getRows(CRMIMPORTINFO.TABLE);
            StringBuffer failure = new StringBuffer();
            while (ite.hasNext()) {
                Row row = (Row) ite.next();
                Long id = (Long) row.get(CRMIMPORTINFO.IMPORTID);
                try {
                	Integer type = Integer.parseInt(row.get(CRMIMPORTINFO.IMPORTTYPE)+"");
                	if(type == ImportConstants.TYPE_MIGRATION) {
                		String statusStr = (String)row.get(CRMIMPORTINFO.STATUS);
                		ImportStatus status = new ImportStatus(statusStr);
                		if(status!=null) {
                			count += status.getAddedCount();
                		}
                	} else {
                		count += ImportHistoryUtil.rollBackImport(id);
                	}
                } catch (Exception e) {
                    failure.append("Failed!!! Exception is : "+e.toString());//no i18n
                }
            }
            undoAllMigration();//to undo migration
            dbo = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(sQry);
            ite = dbo.getRows(CRMIMPORTINFO.TABLE);
            if(ite.hasNext()) {
            	Row row = (Row) ite.next();
                Long id = (Long) row.get(CRMIMPORTINFO.IMPORTID);
                resultObj.put("response","imports not deleted : "+id);//no i18n
            } else {
            	resultObj.put("response", "All imports rollbacked"); //no i18n
            }
            resultObj.put("deleted_count", count);//NO I18N
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }



    /**
    * revert into single Activity tabl which is already split enabled org.
    * @throws Exception
    */
    public JSONObject revertActivitySplitToSingleTab() throws Exception
    {
    	String isRevert = (String)request.getParameter("revert");
        if(EntityMetaDataUtil.isActivityFieldMigrationDone() && ActivityUtil.isActivityTabHidden() && isRevert.equals("true"))
    	{
    		try {
        		ActivitySplitMigrator txnBean = (ActivitySplitMigrator) ScopedAccess.getInstance(ActivitySplitMigrator.class, null, TransactionType.REQUIRED);
        		txnBean.revertMigration();
        		//re-pop deleted report
        		ReportUtil embdreport = new ReportUtil();
        		embdreport.demigrateReports(OrgUtil.getCurrentZGID());
                String PATH_FOR_CONF = new StringBuilder(PropertyUtil.getProperty("server.dir")).append(File.separator).append("conf").append(File.separator).append("AdventNetCRMSFA").append(File.separator).toString(); // No I18N
                DataObject rep = Xml2DoConverter.transform(PATH_FOR_CONF + "activityReportFolder.xml"); //No I18N
                PersistenceCacheUtil.getPurePersistenceLiteHandle().add(rep);
                ReportUtil report = new ReportUtil();
                report.migrateReports(OrgUtil.getCurrentZGID());
        		resultObj.put("response", "reverted to 1 Activities tab"); //no i18n
    		}catch (Exception e) {
                status = false;
                resultObj.put("response", e.toString());
            }

        }else if(!ActivityUtil.isActivityTabHidden() && isRevert.equals("false")){
            try {
                ActivitySplitMigrator txnBean = (ActivitySplitMigrator) ScopedAccess.getInstance(ActivitySplitMigrator.class, null, TransactionType.REQUIRED);
                txnBean.doMigration();
                resultObj.put("response", "Activities tab splited into submodules"); //no i18n
            }catch (Exception e) {
                status = false;
                resultObj.put("response", e.toString());
            }
        }else {
    		resultObj.put("response", "Activity split not enabled");
    	}
        resultObj.put("status", status);
        return resultObj;
    }

    public JSONObject revertTimelineRevampMigration() throws Exception {
    	if(CrmFeatureUtil.isFeatureEnabled(Feature.TIMELINE_REVAMP.getName(), userId, String.valueOf(zgId))) {
    		SelectQuery fieldSq = new SelectQueryImpl(Table.getTable(CRMFIELD.TABLE));
    		fieldSq.addSelectColumn(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDID));
    		Criteria cr = new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.TABID), TabUtil.getTabIdByAPIName(CrmModuleConstants.NOTES), QueryConstants.EQUAL);
    		cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.COLUMNNAME),CRMNOTES.RELATEDID, QueryConstants.EQUAL));
    		fieldSq.setCriteria(cr);
    		DataObject fieldDo = PersistenceCacheUtil.getNonCachePersistenceHandle().get(fieldSq);
    		if(fieldDo!=null && !fieldDo.isEmpty()) {
    			Row fieldRow = fieldDo.getFirstRow(CRMFIELD.TABLE);
    			Long fieldId = (Long)fieldRow.get(CRMFIELD.FIELDID);
    			Criteria fieldDeleteCr = new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDID), fieldId, QueryConstants.EQUAL);
    			Criteria modeFieldDeleteCr = new Criteria(Column.getColumn(CRMMODEFIELD.TABLE,CRMMODEFIELD.FIELDID), fieldId, QueryConstants.EQUAL);
    			PersistenceCacheUtil.getNonCachePersistenceHandle().delete(fieldDeleteCr);
    			PersistenceCacheUtil.getNonCachePersistenceHandle().delete(modeFieldDeleteCr);
    			resultObj.put("response", "Timeline revamp reverted"); //no i18n
    		}
    	}else {
    		resultObj.put("response", "Timeline revamp not enabled");
    	}
    	resultObj.put("status", status);
        return resultObj;
    }
    
    public JSONObject getMismatchedAuditlogIds() throws Exception {
    	try {
    		String requestBody=retrieveRequestBody(request);
    		JSONObject responseObj=new JSONObject();
    		JSONObject requestBodyJo = new JSONObject(requestBody);
			JSONArray zgidsArray=requestBodyJo.has("zgids")?(JSONArray)requestBodyJo.get("zgids"):new JSONArray();//No I18N
			String start_time=requestBodyJo.has("start_time")?(String)requestBodyJo.get("start_time"):"";//No I18N
			String end_time=requestBodyJo.has("end_time")?(String)requestBodyJo.get("end_time"):"";//No I18N
			LOGGER.log(Level.INFO,"zgids=======>{0},start_time======>{1},end_time==========>{2}",new Object[] {zgidsArray,start_time,end_time});
    		HashMap<String,HashMap<String,Set<String>>> mySqlModuleActionSourceVsZgidAndAuditLogIds=new HashMap<String,HashMap<String,Set<String>>>();
    		HashMap<String,HashMap<String,Set<String>>> distDbModuleActionSourceVsZgidAndAuditLogIds=new HashMap<String,HashMap<String,Set<String>>>();
    		int zgidsArrayLength=zgidsArray.length();
    		for(int i=0;i<zgidsArrayLength;i++)
    		{
    			String zgid=zgidsArray.get(i).toString();
        		CrmTimelineDBService crmTimelineDBService = (CrmTimelineDBService) ScopedAccess.getInstance(CrmTimelineDBService.class, zgid, TransactionType.NOSUPPORT);
        		crmTimelineDBService.compareAndGetDiffRowsBetweenMysqlDistDB(start_time, end_time, "IST",zgid,mySqlModuleActionSourceVsZgidAndAuditLogIds,distDbModuleActionSourceVsZgidAndAuditLogIds);//No I18N
    		}
    		responseObj.put("dist_db",distDbModuleActionSourceVsZgidAndAuditLogIds);
    		responseObj.put("my_sql",mySqlModuleActionSourceVsZgidAndAuditLogIds);
    		resultObj.put("response",responseObj);
    		status = true;
    	}catch(Exception e) {
    		 status = false;
             resultObj.put("response", e.toString());
             StringWriter writer = new StringWriter();
			 PrintWriter printWriter = new PrintWriter( writer );
			 e.printStackTrace( printWriter );
			 String stackTrace = writer.toString();
			 LOGGER.log(Level.INFO,"Exception occurred in method getMisMatchedAuditLogIds-----> trace {0} ----> {1}",new Object[] {e.getMessage(),stackTrace});
		}
    	return resultObj;
    }

    private String retrieveRequestBody(HttpServletRequest request) throws IOException {
        StringBuilder stringBuilder = new StringBuilder();
        String line;

        BufferedReader reader = new BufferedReader(new InputStreamReader(request.getInputStream()));
        while ((line = reader.readLine()) != null) {
            stringBuilder.append(line);
        }

        return stringBuilder.toString();
    }
    
    public JSONObject populateSignalsDataToAuditLog() throws Exception {
    	String module = request.getParameter("moduleName");
    	String recordId = request.getParameter("recordId");
    	if(module!=null && recordId!=null) {    		
    		SelectQuery signalsSq = new SelectQueryImpl(Table.getTable(CRMNOTIFICATIONCENTER.TABLE));
    		signalsSq.addSelectColumn(Column.getColumn(null,"*"));
    		signalsSq.addSortColumn(new SortColumn(Column.getColumn(CRMNOTIFICATIONCENTER.TABLE,CRMNOTIFICATIONCENTER.AUDITEDTIME), true));
    		Criteria signalCr = new Criteria(Column.getColumn(CRMNOTIFICATIONCENTER.TABLE,CRMNOTIFICATIONCENTER.SEID), Long.valueOf(recordId), QueryConstants.EQUAL);
    		signalCr = signalCr.and(new Criteria(Column.getColumn(CRMNOTIFICATIONCENTER.TABLE,CRMNOTIFICATIONCENTER.SETYPE),module,QueryConstants.EQUAL));
    		signalsSq.setCriteria(signalCr);
    		signalsSq.setRange(new Range(0,00));
    		DataObject signalsDo = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(signalsSq);
    		Queue<OldLogProps> queue=new LinkedList<>();
    		CrmNotificationCenterUtils.insertAuditLogEquivalentColumnforNotificationCenterEntry(queue,signalsDo);
			SalesSignalLogService.insertLogForCustomSignal(queue.poll(), signalsDo);
    		resultObj.put("response", "Data populated successfully!!!"); //no i18n
    	}else {
    		resultObj.put("response", "Error!!....moduleName and recordId are required"); //no i18n
    		status = false;
    	}
    	resultObj.put("status", status);
        return resultObj;
    }
