    public JSONObject undoAllMigration() throws JSONException {
    	try {
    		SelectQuery migQry = new SelectQueryImpl(Table.getTable(CRMDATAMIGRATION.TABLE));
    		migQry.addSelectColumn(Column.getColumn(CRMDATAMIGRATION.TABLE, CRMDATAMIGRATION.MIGRATIONID));
    		Criteria migCriteria = new Criteria(Column.getColumn(CRMDATAMIGRATION.TABLE, CRMDATAMIGRATION.STATUS), new int[] {
    				7,
    				105,
    				5,
    				9
    		}, QueryConstants.IN); //completed,user_terminated,abort,error can be rollbacked
    		migQry.setCriteria(migCriteria);
    		DataObject migDO = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(migQry);
    		@SuppressWarnings("rawtypes")
    		Iterator<Row> ite = migDO.getRows(CRMDATAMIGRATION.TABLE);
    		while (ite.hasNext()) {
    			Row row = ite.next();
    			Long id = (Long) row.get(CRMDATAMIGRATION.MIGRATIONID);
    			try {
    				new ImportRollbackScheduler().run(id);
    			} catch (Exception e) {
    				//do none and move on to next id
    			}
    		}
    		resultObj.put("response", "All migration rollbacked"); //no i18n
    	} catch (Exception e) {
    		status = false;
    		resultObj.put("response", e.toString());
    	}
    	resultObj.put("status", status);
    	return resultObj;
    }

    public void deleteAllMigration() throws Exception
    {
    DeleteQuery dQry = new DeleteQueryImpl(Table.getTable(CRMDATAMIGRATION.TABLE));
		dQry.setLimit(5000);
		while(true)
		{
			int count = PersistenceCacheUtil.getPersistenceLiteHandle().delete(dQry);
			if(count < 5000)
			{
				break;
			}
		}
    }

