    public JSONObject resetCCMigration()throws Exception {
    	try {
			CrmKeyValueUtil.deleteCrmKeyValueByKeyName("CC_MOCKMIGRATION_INPROGRESS", false); // No I18N
			CrmKeyValueUtil.deleteCrmKeyValueByKeyName("CC_MIGRATION_FLOW_ENABLED", false); // No I18N
			CrmKeyValueUtil.deleteCrmKeyValueByKeyName("CC_JOURNEY_MIGRATION_COMPLETED", false); // No I18N
			CrmKeyValueUtil.deleteCrmKeyValueByKeyName("CC_PF_MIGRATION_COMPLETED", false); // No I18N
			CrmKeyValueUtil.deleteCrmKeyValueByKeyName("CC_NEW_FLOW_ENABLED", false); // No I18N
			CrmKeyValueUtil.deleteCrmKeyValueByKeyName("CC_MOCKMIGRATION_FAILED", false); // No I18N
			Criteria cr = new Criteria(Column.getColumn(CRMKEYVALUE.TABLE,CRMKEYVALUE.KEYNAME), "CCMigration", QueryConstants.STARTS_WITH);
			cr = cr.or(new Criteria(Column.getColumn(CRMKEYVALUE.TABLE,CRMKEYVALUE.KEYNAME), "CCAPI_", QueryConstants.STARTS_WITH));
			CrmKeyValueUtil.deleteCrmKeyValueByCriteria(cr, false, false);

			HashSet<Long> processIds = new HashSet<Long>();
			DataObject journeyDO = OrchConfigDBService.Get.getOrchestrationsDO(null, true, false, false, false);			
			Iterator<Row> journeyItr = journeyDO.getRows(CRMPROCESSFLOW.TABLE);
			while (journeyItr.hasNext()) {
				Row row = journeyItr.next();
				Long pId = (Long)row.get(CRMPROCESSFLOW.PROCESSID);
				processIds.add(pId);
			}
			DataObject pathfinderDO = CrmPathFinderConfigDBService.Get.getPathFindersDO(null, true, false, false, false);
			Iterator<Row> pfItr = pathfinderDO.getRows(CRMPROCESSFLOW.TABLE);
			while (pfItr.hasNext()) {
				Row row = pfItr.next();
				Long pId = (Long) row.get(CRMPROCESSFLOW.PROCESSID);
				processIds.add(pId);
			}
			TabUtil.updateTabPresence(processIds, 1L);

		} catch (Exception e) {
			resultObj.put("status", false); // No I18N
			resultObj.put("response", e.toString()); // No I18N
		}
    	resultObj.put("status", status);
    	return resultObj;
    }
    
