    /**
     * Create a new layout for a module
     *
     * Optional parameters in the request
     * layout_id- Parent layout id; takes standard layout by default
     * profiles- profile ids as comma-separated string; assigns it to all profiles by default
     *
     * Throws error upon duplicate layout name
     * @throws JSONException
     */
    public JSONObject createNewLayout() throws JSONException {
    	try {
    		String module = request.getParameter("module");
    		String layoutName = request.getParameter("layout_name");
    		String layoutIdFromRequest = request.getParameter("layout_id");
    		String profileIdsFromRequest = request.getParameter("profiles");
    		long tabId = TabUtil.getTabIdByAPIName(module);
    		if(!PageLayoutUtil.isLayoutNameDuplicateForTab(layoutName, tabId, null))
    		{
    			throw new Exception("Layout name already present");
    		}
    		long layoutId = layoutIdFromRequest!=null ? Long.valueOf(layoutIdFromRequest) : PageLayoutUtil.getAllActiveLayoutIdByTabId(tabId).get(0);
    		JSONArray profileIds = new JSONArray(profileIdsFromRequest!=null ? Arrays.asList(profileIdsFromRequest.split(",")) : ProfileUtil.getAllProfileIds());
    		com.adventnet.crm.qa.automation.modulebuilder.ResetConfigurations.createNewLayout(module, layoutId, layoutName, userId, String.valueOf(zgId), profileIds);
    		resultObj.put("response", "qwerty");
    	} catch (Exception e) {
    		status = false;
    		resultObj.put("status", status);
    		resultObj.put("response", e.getMessage());
    	}
    	return resultObj;
    }

    public JSONObject enablePickListTracker() throws JSONException {
    	try {
    		String module = request.getParameter("module");
    		long fieldId = Long.valueOf(request.getParameter("field_id"));
    		String followedFields = request.getParameter("follow_fields");
    		List<Long> followedFieldIds = new ArrayList<Long>();
    		for(String followedField : followedFields.split(","))
    		{
    			followedFieldIds.add(Long.valueOf(followedField));
    		}
    		String durationType = request.getParameter("duration_type");
    		resetPickListFieldUtil.enablePickListTracker(module, fieldId, null, followedFieldIds, durationType=="days" || durationType==null ? DURATION_TYPES.DAYS : DURATION_TYPES.TIME); // No i18n
    		resultObj.put("response", "Pick list tracker enabled");
    	} catch (Exception e) {
    		status = false;
    		resultObj.put("status", status);
    		resultObj.put("response", e.getMessage());
    	}
    	return resultObj;
    }
    public JSONObject getMessageId_byEmailSubject() throws DataAccessException, Exception
   	{
   		Long userId=UserUtil.getUserIdByZUID(zuId);
                String subject=request.getParameter("subject");
   		SelectQuery querySq = new SelectQueryImpl( Table.getTable(CRMMASSMAILDETAILS.TABLE) );
   		querySq.addSelectColumn(Column.getColumn(CRMMASSMAILDETAILS.TABLE, CRMMASSMAILDETAILS.SUBJECT));
   		querySq.addSelectColumn(Column.getColumn(CRMMASSMAILDETAILS.TABLE, CRMMASSMAILDETAILS.MESSAGE_ID));
   		querySq.addSelectColumn(Column.getColumn(CRMMASSMAILDETAILS.TABLE, CRMMASSMAILDETAILS.SMOWNERID));
   		querySq.addSelectColumn(Column.getColumn(CRMMASSMAILDETAILS.TABLE, CRMMASSMAILDETAILS.SENTON));
   		querySq.addSelectColumn(Column.getColumn(CRMMASSMAILDETAILS.TABLE, CRMMASSMAILDETAILS.SENTORRECEIVE));
   		querySq.addSelectColumn(Column.getColumn(CRMMASSMAILDETAILS.TABLE, CRMMASSMAILDETAILS.ZMAIL_MESG_ID));
   		querySq.addSelectColumn(Column.getColumn(CRMMASSMAILDETAILS.TABLE, CRMMASSMAILDETAILS.BOUNCEREASON));
   		querySq.addSelectColumn(Column.getColumn(CRMMASSMAILDETAILS.TABLE, CRMMASSMAILDETAILS.MASSMAILID));
   	    querySq.addSortColumn(new SortColumn(Column.getColumn(CRMMASSMAILDETAILS.TABLE,CRMMASSMAILDETAILS.SENTON),false));
   		//Criteria cr = new Criteria(Column.getColumn(CRMMASSMAILDETAILS.TABLE,CRMMASSMAILDETAILS.SUBJECT), "*" + subject + "*" , QueryConstants.LIKE);
   		Criteria cr = new Criteria(Column.getColumn(CRMMASSMAILDETAILS.TABLE,CRMMASSMAILDETAILS.SUBJECT), subject , QueryConstants.EQUAL);
   		cr=cr.and(new Criteria(Column.getColumn(CRMMASSMAILDETAILS.TABLE,CRMMASSMAILDETAILS.SMOWNERID),userId, QueryConstants.EQUAL));
   		querySq.setCriteria(cr);
   		querySq.setRange(new Range(0, 10));
   		DataObject massMailDO=PersistenceCacheUtil.getPurePersistenceLiteHandle().get(querySq);
   		Row massMailRow=massMailDO.getRow(CRMMASSMAILDETAILS.TABLE);
   		String status=massMailRow.get(CRMMASSMAILDETAILS.SENTORRECEIVE).toString();
   		if(status.equals("Scheduled"))
   		{

   			resultObj.put("response","Scheduled mails dont have message ID");


   		}
   		else
   		{
   			if(status.equals("Bounced"))
   			{
   				 String BouncedReason= massMailRow.get(CRMMASSMAILDETAILS.BOUNCEREASON).toString();
   				resultObj.put("response",BouncedReason);

   			}
   			else
   			{
   				String messageId= massMailRow.get(CRMMASSMAILDETAILS.MESSAGE_ID).toString();

   				if(messageId!=null && !messageId.isEmpty())
   				{
   					resultObj.put("response",messageId);


   				}
   				else
   				{
   					String zmessageId= massMailRow.get(CRMMASSMAILDETAILS.ZMAIL_MESG_ID).toString();
   					resultObj.put("response",zmessageId);
   				}

   			}

   		}
   		return resultObj;
   	}
    public JSONObject createUserGroup() throws JSONException {
    	try {
    		HttpServletRequestExtends requestClone = RequestAndResponseUtil.getRequest();

    		String sourceType = request.getParameter("sourceType");
    		String ids = request.getParameter("ids");
    		ArrayList<String> selectedGrpObj = new ArrayList<String>();

    		for(String id : ids.split(","))
    		{
    			selectedGrpObj.add(sourceType + ":" + id);
    		}

    		requestClone.setParameter("groupName", request.getParameter("groupName")); // No i18n
    		requestClone.setParameter("groupDesc", request.getParameter("groupDesc")); // No i18n
    		requestClone.setParameter("groupType", request.getParameter("groupType")); // No i18n
    		requestClone.setParameter("selectedGrpObj", selectedGrpObj.toString().replaceAll("[\\[\\]\\s]", "")); // No i18n
    		requestClone.setAttribute("USERID_FROM_FILTER", request.getAttribute("USERID_FROM_FILTER"));
//    		requestClone.setParameter("selectedGrpObj","R:111111000000041209,R:111111000000041212");

    		GroupUtil groupBeanImplObj = (GroupUtil)ScopedAccess.getInstance(GroupUtil.class, null, TransactionType.REQUIRED);
    		Long groupId = groupBeanImplObj.createGroup(requestClone);
//    		GroupUtil groupUtil = new GroupUtil();
//    		Long groupId = groupUtil.createGroup(request);
    		resultObj.put("response", groupId.toString());
    	} catch (Exception e) {
    		status = false;
    		resultObj.put("status", status);
    		resultObj.put("response", e.getMessage());
    	}
    	return resultObj;
    }

    public JSONObject deleteInventoryRecords() throws JSONException { // ###used
    	try{
    	String[] inv_modules = new String[]{CrmModuleConstants.QUOTES,
    	        CrmModuleConstants.INVOICES,
    	        CrmModuleConstants.SALESORDERS,
    	        CrmModuleConstants.PURCHASEORDERS,
				CrmModuleConstants.BUNDLES};
    	for (String eachModule: inv_modules) {
			if(eachModule.equals(CrmModuleConstants.BUNDLES) && !FeatureEditionUtil.isFeatureAvailable(CrmModuleConstants.BUNDLES)) {
				continue;
			}
        	Long tabID = TabUtil.getTabIdByName(eachModule);
        	if(tabID!=null){
            String tableName = EntityMetaDataUtil.getBaseTableByModuleName(eachModule);
            String pkcolumn = EntityMetaDataUtil.getPKColumnName(tableName);
            SelectQuery sQry2 = new SelectQueryImpl(Table.getTable(tableName));
            try {
                Criteria cr = null;
                if ((!tableName.equals("CrmTask")) && (!tableName.equals("CrmIamUser")) && (!tableName.equals("CrmEvent"))) {
                    cr = new Criteria(Column.getColumn(tableName, "SE_PRESENCE"), RecordConstants.RecordStatus.SAVED.getStatus(), QueryConstants.EQUAL);
                    cr = cr.and(new Criteria(Column.getColumn(tableName, CrmConstants.ISAPPROVED), Integer.valueOf(6), QueryConstants.NOT_EQUAL));
                    sQry2.setCriteria(cr);
                }
            } catch (Exception e) {
            }
            sQry2.addSelectColumn(Column.getColumn(tableName, pkcolumn));
            sQry2.setRange(new Range(1, 5000));
            DataObject dbo2 = PersistenceCacheUtil.getNonAIPersistenceHandle().get(sQry2);
            @SuppressWarnings("rawtypes")
            Iterator ite2 = dbo2.getRows(tableName);
            //String entityIds = null;
            StringBuilder entityIdsBuilder = null;
            while (ite2.hasNext()) {
                Row row = (Row) ite2.next();
                if(entityIdsBuilder==null) {
                    entityIdsBuilder = new StringBuilder();
                    entityIdsBuilder.append((Long) row.get(pkcolumn));
                }else {
                    entityIdsBuilder.append(';').append((Long) row.get(pkcolumn));
                }
                //entityIds = (entityIds == null) ? (Long) row.get(pkcolumn) + "" : (entityIds + ";" + (Long) row.get(pkcolumn));
            }
            if (entityIdsBuilder != null) {
                RecycleBinUtil.moveToRecyclebin(eachModule, entityIdsBuilder.toString(), userId, 2);
            }
          }
    	 }
    	RecycleBinUtil.emptyBin(request, null, null);
    	}
    	catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
    	resultObj.put("status", status);
        return resultObj;
    }
    public JSONObject deleteSandboxRecords() throws JSONException { // ###used
        try {
        	String sandboxName = request.getParameter("sandboxName");
        	Long sandboxZgid = null;
        	if(sandboxName != null) {
        		SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMSANDBOXACCOUNTS.TABLE));
    	 		sq.addSelectColumn(Column.getColumn(null, "*"));

    	 		Criteria cr = SandboxConfigUtil.getBackupSandboxCriteria(false);
    	 		cr = cr.and(new Criteria(Column.getColumn(CRMSANDBOXACCOUNTS.TABLE, CRMSANDBOXACCOUNTS.NAME), sandboxName, QueryConstants.EQUAL));

    	 		sq.setCriteria(cr);
    	 		sq.addSortColumn(new SortColumn(Column.getColumn(CRMSANDBOXACCOUNTS.TABLE, CRMSANDBOXACCOUNTS.SANDBOXID), true));

    	 		DataObject dObj = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(sq);

    	 		Row sandboxRow = dObj.getRow(CRMSANDBOXACCOUNTS.TABLE);
    	 		if (sandboxRow != null) {
    	 			sandboxZgid = Long.valueOf(sandboxRow.get(CRMSANDBOXACCOUNTS.ZGID).toString());
    	 		}
        	}
        	if(sandboxZgid != null) {
        		ResetConfigurations tool = (ResetConfigurations)ScopedAccess.getInstance(ResetConfigurations.class, sandboxZgid.toString(), TransactionType.NOSUPPORT);
        		tool.zgId = sandboxZgid;
        		tool.init(request, response);
        		return tool.deleteRecords();
        	} else {
            	status = false;
            	resultObj.put("response", "Sandbox account not found");
            }
        } catch (Exception e) {
        	status = false;
        	resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }
    //delete records
    public JSONObject deleteRecords() throws JSONException { // ###used
        try {
            String moduleFromReq = request.getParameter("module");
            String delLimit = request.getParameter("limit");
            int limit = (delLimit != null) ? Integer.parseInt(delLimit) : 5000;
            limit = limit > 5000 ? 5000 : limit;
            if(moduleFromReq != null){
                modules = new String[]{moduleFromReq};
            }
            for (String eachModule: modules) {
            	if(eachModule.equals(CrmModuleConstants.PRODUCTS)){
            		deleteInventoryRecords();
            	}
            	Long tabID = TabUtil.getTabIdByName(eachModule);
            	if(tabID!=null){
                String tableName = EntityMetaDataUtil.getBaseTableByModuleName(eachModule);
                String pkcolumn = EntityMetaDataUtil.getPKColumnName(tableName);
                SelectQuery sQry2 = new SelectQueryImpl(Table.getTable(tableName));
                try 
                {
                    Criteria cr = null;
                    if ( (!tableName.equals("CrmTask") ) && (!tableName.equals("CrmIamUser") ) && (!tableName.equals("CrmEvent"))) {
                        cr = new Criteria(Column.getColumn(tableName, "SE_PRESENCE"), RecordConstants.RecordStatus.SAVED.getStatus(), QueryConstants.EQUAL);
                        cr = cr.and(new Criteria(Column.getColumn(tableName, CrmConstants.ISAPPROVED), Integer.valueOf(6), QueryConstants.NOT_EQUAL));
                        sQry2.setCriteria(cr);
                    }
                } catch (Exception e) {
                	LOGGER.log(Level.SEVERE, e.toString());
//                	status = false;
//                  resultObj.put("response", e.toString());
                }
                if(CRMTASK.TABLE.equals(tableName))
                {
                    Criteria taskCritieria = new Criteria(Column.getColumn(CRMTASK.TABLE, CRMTASK.SETYPE), null, QueryConstants.NOT_EQUAL);
                    Criteria availableCriteria = sQry2.getCriteria();
                    if(availableCriteria!=null)
                    {
                	availableCriteria = availableCriteria.and(taskCritieria);
                    }
                    else
                    {
                	availableCriteria = taskCritieria;
                    }
                    
                    sQry2.setCriteria(availableCriteria);
                }
                sQry2.addSelectColumn(Column.getColumn(tableName, pkcolumn));
                sQry2.setRange(new Range(1, limit));
                DataObject dbo2 = PersistenceCacheUtil.getNonAIPersistenceHandle().get(sQry2);
                @SuppressWarnings("rawtypes")
                Iterator ite2 = dbo2.getRows(tableName);
                //String entityIds = null;
                StringBuilder entityIdsBuilder = null;
                while (ite2.hasNext()) {
                    Row row = (Row) ite2.next();
                    if(entityIdsBuilder==null) {
                        entityIdsBuilder = new StringBuilder();
                        entityIdsBuilder.append((Long) row.get(pkcolumn));
                    }else {
                        entityIdsBuilder.append(';').append((Long) row.get(pkcolumn));
                    }
                    //entityIds = (entityIds == null) ? (Long) row.get(pkcolumn) + "" : (entityIds + ";" + (Long) row.get(pkcolumn));
                }
                if (entityIdsBuilder != null) {
                    RecycleBinUtil.moveToRecyclebin(eachModule, entityIdsBuilder.toString(), userId, 2);
                }
            }
            }
            RecycleBinUtil.emptyBin(request, null, null);
            modules = getModulesList();
            resultObj.put("response", "Records deleted in all modules"); //no i18n
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }

