    //updating default custom view
    public JSONObject choose_defaultviews() throws JSONException { // ###used
        try {
            String moduleFromReq = request.getParameter("module");
            if(moduleFromReq != null){
                modules = new String[]{moduleFromReq};
            }
            String res = "";
            for (String eachModule: modules) {
            	if(eachModule.equals("NewDBModules")) {
            		eachModule = "CustomModule51"; //no i18n
            	}
            	if(eachModule.equals("CModules")) {
            		eachModule = "CustomModule1"; //no i18n
            	}
            	if((eachModule.contains("Tasks")||eachModule.contains("Events")||eachModule.contains("Calls")) && !EntityMetaDataUtil.isActivitySubModulesExposed()){//no i18n
                    eachModule="Activities"; //no i18n
                }
            	Long cvIds=null;
            	String requriedCv="All ";//no i18n
                if(eachModule.contains("Leads")){//no i18n
                  requriedCv="All Open Leads"; //no i18n
                }else if((eachModule.contains("Tasks")||eachModule.contains("Events")||eachModule.contains("Calls")) && !EntityMetaDataUtil.isActivitySubModulesExposed()){//no i18n
                    requriedCv="All Activities"; //no i18n
                }else if(!eachModule.contains("CustomModule")){//no i18n
                  requriedCv = "All " + (eachModule.contains("Events") ? "Meetings": eachModule); //no i18n
                }else if(eachModule.contains("CustomModule")){//no i18n
                  requriedCv="CustomModule Default CustomView"; //no i18n
                }
                DataObject dObj = com.zoho.crm.customviews.util.CustomViewUtil.getCustomViewObject(eachModule, userId);
                if(!dObj.isEmpty())
                {
                  @SuppressWarnings("rawtypes")
				Iterator it = dObj.getRows(CRMCUSTOMVIEW.TABLE);
                  while(it.hasNext())
                  {
                    Row row = (Row) it.next();
                    String cvName = (String) row.get(CRMCUSTOMVIEW.DISPLAYNAME);
                    if(cvName.contains( requriedCv)){
                      cvIds = ((Long) row.get(CRMCUSTOMVIEW.CVID));
                      break;
                    }
                  }
                }
                if (cvIds != null) {
                    com.zoho.crm.customviews.util.CustomViewUtil.updateDefaultCV(eachModule, userId,cvIds);
                }
//                String avaialble = CustomViewUtil.getDefaultCVName(eachModule, userId);
//                if(avaialble.equals(requriedCv)){
//                	res = res + "\nChoosen as expected for "+eachModule;
//                }else{
//                	res = res + "\nNot Choosen as expected for "+eachModule;
//                }
            }
            modules = getModulesList();
            resultObj.put("response", "Default custom view selected "+res); //no i18n
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }
