    public JSONObject territory() throws JSONException { // ###used
        try {
        	Long userID = UserUtil.getCurrentUserId();
        	DataObject cacheDo = TerritoryDBService.getCachedTerritoryDo(null);
        	Iterator<Row> rows = cacheDo.getRows(CRMTERRITORIES.TABLE, new Criteria(Column.getColumn(CRMTERRITORIES.TABLE, CRMTERRITORIES.PARENTID), null, QueryConstants.NOT_EQUAL));
        	Boolean isSandbox = OrgUtil.isSandboxAccount();
        	deleteTerritories(rows, cacheDo, userID, isSandbox);
            ZohoCRMBeanWTImpl ZohoCRMBeanWTObj = (ZohoCRMBeanWTImpl)ScopedAccess.getInstance(ZohoCRMBeanWTImpl.class,zgId+"" , TransactionType.REQUIRED);
            ZohoCRMBeanWTObj.disableTerritory(userId, 1);
			if(isSandbox) {
				SandboxConfigUtil.trackChanges(null, SandboxConfigConstants.TERRITORY_MGMT_SETTINGS, "crm.title.territory.disabled", SandboxOperationType.DELETE, null);//No I18N
			}
            Map < Long, String > terrDetails = TerritoryUtil.getAllTerritoriesMap(TerritoryDBService.getCachedTerritoryDo(null));
            if(terrDetails.size() > 1){
            	status = false;
                resultObj.put("response", terrDetails.toString());
            }else{
            	resultObj.put("response", "All territories deleted"); //no i18n
            }
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }
    
