    private void deleteTerritories(Iterator<Row> terrRows,DataObject cacheDo, Long userId, Boolean isSandbox) throws Exception
    {
    	while(terrRows.hasNext())
    	{
    		Row row = terrRows.next();
    		Long territoryId = (Long) row.get(CRMTERRITORIES.TERRITORYID);
    		String deletedTerrName = (String) row.get(CRMTERRITORIES.TERRITORYNAME);
    		Iterator<Row> childRows = cacheDo.getRows(CRMTERRITORIES.TABLE, new Criteria(Column.getColumn(CRMTERRITORIES.TABLE, CRMTERRITORIES.PARENTID),territoryId,QueryConstants.EQUAL));
    		if(childRows.hasNext())
    		{
    			deleteTerritories(childRows, cacheDo, userId, isSandbox);
    		}
    		TerritoryCRUDUtil.deleteTerritory(territoryId, userId, (String) row.get(CRMTERRITORIES.TERRITORYNAME), null, CreateUpdateEntityDetails.API);
			if(isSandbox){
				Map<String, String> otherInfo = new HashMap<String, String>();
				otherInfo.put("delForecast", "true");
				SandboxConfigUtil.trackChanges(territoryId, SandboxConfigConstants.TERRITORY, deletedTerrName, SandboxOperationType.DELETE, null, null, otherInfo);
			}
    	}
    }

