    /**
     * 
     * @return
     * @throws Exception
     */
    public JSONObject fixHomePageComponentCorruption() throws Exception
	{
		Long zgid = OrgUtil.getCurrentZGID();
		
			Persistence per = PersistenceCacheUtil.getPurePersistenceLiteHandle();
	
			if(!isParentMigrationCompleted(per))
			{
				resultObj.put("response","Issue migration was not ran"); //No I18N
				resultObj.put("status", false);
				return resultObj;
			}
			
			SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMHOMEPAGELAYOUT.TABLE));
			sq.addSelectColumn(Column.getColumn(null,PMDConstants.ASTERISK));
			Criteria crt  = new Criteria(Column.getColumn(CRMHOMEPAGELAYOUT.TABLE, CRMHOMEPAGELAYOUT.LAYOUTNAME), "My Today's Calls", QueryConstants.EQUAL);
			crt = crt.and(new Criteria(Column.getColumn(CRMHOMEPAGELAYOUT.TABLE, CRMHOMEPAGELAYOUT.MODULE), "Dashboards", QueryConstants.EQUAL));
			sq.setCriteria(crt);
			DataObject homePageDO = new WritableDataObject();
			
			DOIterator homePageDOIter = new DOIterator(per, sq, 1, 2000, -1, true, true);
			while(homePageDOIter.hasNext())
			{
				homePageDO.merge(homePageDOIter.next());
			}
			
			if(isCorruptionOccurred(homePageDO, per))
			{
				Long adminUserId = OrgUtil.getUserIdOfPrimaryContact(String.valueOf(zgid));
				UserMetadataHolder adminUserMeta = new UserMetadataHolder();
				Long componentId = null;
				adminUserMeta.setUserId(adminUserId);
				//To populate the component 'My Todays Calls' in HomePage
				try {
					DataObject homePageDashboardDo = DashboardsUtil.componentsDOForUserHomePage();
					if(!homePageDashboardDo.isEmpty())
					{
						Row row = homePageDashboardDo.getFirstRow(CRMDASHBOARD.TABLE);
						Long dashId = (Long)row.get(CRMDASHBOARD.DASHBOARDID);
						List<Component> component = createDashboardComponentsInV22(adminUserMeta, dashId, "MyTodaysCalls.json", "My Todays Calls");	// No I18N
						componentId = component.get(0).getId();	
					}
					Iterator<Row> rows = homePageDO.getRows(CRMHOMEPAGELAYOUT.TABLE);
					while(rows.hasNext())
					{
						Row row = rows.next();
						row.set(CRMHOMEPAGELAYOUT.DASHLETID, componentId);
						homePageDO.updateRow(row);
					}
					per.update(homePageDO);
					resultObj.put("response","corruption was fix"); //No I18N
					status = true;
				}
				catch (Exception e){
					resultObj.put("response","corruption was not fix"); //No I18N
					status = false;
				}
				
				//To populate the component 'Calls This Week' in 'Activity Stats' Dashboard
				try {
					Long id = DashboardUtil.getDashBoardIdByName("Activity Stats");	// No I18N
					createDashboardComponentsInV22(adminUserMeta, id, "CallsThisWeek.json", "Calls This Week");	// No I18N
				}
				catch (Exception e){
				}
				 resultObj.put("status", status);
				 return resultObj;
			}
			resultObj.put("response","Corruption is not there"); //No I18N
			resultObj.put("status", false);
			return resultObj;
	}
    /**
     * 
     * @return
     * @throws Exception
     */
	private List<Component> createDashboardComponentsInV22(UserMetadataHolder userMeta, Long dashboardId, String filename, String keyName) throws Exception {
		ObjectMapper mapper = new ObjectMapper();
		CollectionType typeReference = TypeFactory.defaultInstance().constructCollectionType(List.class, Component.class);
		ObjectReader reader = mapper.readerFor(typeReference);
		ObjectNode componentsJsonArray = CommonUtil.getConfigJson(CrmConstants.PATH_FOR_DASHBOARDS_CONFIG + filename);
		ArrayNode componentsArr = (ArrayNode) componentsJsonArray.get(keyName);
		if (componentsArr != null) {
			List<Component> components = reader.readValue(componentsArr);
			IComponentsDAO serv = ComponentsDAOImpl.getInstance();
			return serv.createComponents(dashboardId, components, userMeta, true, true);
		}
		return null;
	}
	/**
     * 
     * @return
     * @throws Exception
     */
	private boolean isParentMigrationCompleted(Persistence per) throws Exception
	{
		SelectQuery sq = new SelectQueryImpl(Table.getTable(AUTOISUAUDITLOG.TABLE));
		sq.addSelectColumn( Column.getColumn(AUTOISUAUDITLOG.TABLE, PMDConstants.ASTERISK) );

		Criteria cr = new Criteria(Column.getColumn(AUTOISUAUDITLOG.TABLE, AUTOISUAUDITLOG.MIGRATION_FILENAME), "com.adventnet.crm.autoISU.CorruptedReportsQueryTableEntriesMigration", QueryConstants.EQUAL);
		cr = cr.and(new Criteria(Column.getColumn(AUTOISUAUDITLOG.TABLE, AUTOISUAUDITLOG.MIGRATION_STATUS), "SUCCESS" , QueryConstants.EQUAL));

		sq.setCriteria(cr);				
		sq.setRange(new Range(0, 1));

		DataObject auditLogDo = per.get(sq);
		
		if(auditLogDo == null || auditLogDo.isEmpty())
		{
			return false;
		}
		else
		{
			return true;
		}
	}
	/**
     * 
     * @return
     * @throws Exception
     */
	private boolean isCorruptionOccurred(DataObject homePageDO, Persistence per) throws Exception
	{
		SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMDASHBOARDITEMS.TABLE));
		sq.addSelectColumn(Column.getColumn(null,PMDConstants.ASTERISK));
		DataObject dashItemsDO = new WritableDataObject();
		
		DOIterator dashItemsDOIter = new DOIterator(per, sq, 1, 2000, -1, true, true);
		while(dashItemsDOIter.hasNext())
		{
			dashItemsDO.merge(dashItemsDOIter.next());
		}
		List <Long> dashItemsIds = new ArrayList<Long>();
		Iterator<Row> rows = dashItemsDO.getRows(CRMDASHBOARDITEMS.TABLE);
		while(rows.hasNext())
		{
			Row row = rows.next();
			dashItemsIds.add((Long)row.get(CRMDASHBOARDITEMS.DASHBOARDITEMSID));
		}
		
		Iterator<Row> homePagerows = homePageDO.getRows(CRMHOMEPAGELAYOUT.TABLE);
		while(homePagerows.hasNext())
		{
			Row homePagerow = homePagerows.next();
			Long compId = (Long)homePagerow.get(CRMHOMEPAGELAYOUT.DASHLETID);
			if(!dashItemsIds.contains(compId))
			{
				return true;
			}
		}
		return false;
	}

