    //Create template
    public JSONObject createEmailOrInventoryTemplate() throws JSONException
    {
        try
        {
        	if(userId == null)
            {
            	userId = UserUtil.getCurrentUserId();
            }
        	String content = request.getParameter("content");
            String templatName = request.getParameter("templatName");
            String subject = request.getParameter("subject");
            String module = request.getParameter("module");
            String templateType = request.getParameter("templateType");

            if(templateType==null || userId==null || module==null || subject==null || templatName==null || content==null)
            {
            	status = false;
            	resultObj.put("response", "Expected value not found");
            }
            else
            {
            	module = TabUtil.getTabNameByAPIName(module,OrgUtil.getCurrentZGID()+"");
            	if(module!=null)
            	{
            	Integer editorMode = Integer.valueOf(request.getParameter("editorMode"));
                String templaeid  = CrmTemplateUtil.createBasicTemplate(content, templatName, subject, module, editorMode, userId, templateType);
                if(!new PatternMatcherWrapper("[0-9]+").matches(templaeid))
        		{
                	status = false;
                	resultObj.put("response", "template created");
        		}
                resultObj.put("response", templaeid);
            }
        }
        }
        catch (Exception e)
        {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }

