    //creating a field with range and slider
    private void setCustomRangeAndSlider(CustomFieldForm customFieldForm) throws Exception{
    	if(!FeatureEditionUtil.isFeatureAvailable(CoreFeatureNameConstants.RADIO_BUTTON_AND_SLIDER_ENABLED,LicenseUtil.getLicenseType())) {
    		return;
    	}
        String displayFormat = request.getParameter("displayFormat"); //No i18n
        if(displayFormat != null) {
            Integer displayFormatInt = Integer.parseInt(displayFormat);
            customFieldForm.setDisplayFormat(displayFormatInt);
        }
        String splitInterval = request.getParameter("split"); //No i18n
        if(splitInterval != null){
            customFieldForm.setSplitInterval(Integer.parseInt(splitInterval));
        }
        String maxLimit = request.getParameter("max"); //No i18n
        String minLimit = request.getParameter("min"); //No i18n
        if(maxLimit != null || minLimit != null){
            JSONObject range = new JSONObject();
            if(maxLimit != null){
                range.put("from", minLimit);
            }
            if(minLimit != null){
                range.put("to", maxLimit);
            }
            customFieldForm.setRange(range);
        }
    }
