    /**
     * This method creates 50 new CustomModules with Custom Fields
     * @return
     * @throws JSONException
     */
    public JSONObject maxcustommodules() throws JSONException {
        try {
        	JSONArray profiles = new JSONArray(ProfileUtil.getAllProfileIds(null,false,false));
            for (int cm = 1; cm <= 50; cm++) {
                int customModuleNumber = CrmCustomModuleUtil.returnNextCustomModuleNumber();
                if (customModuleNumber == -1) {
                	resultObj.put("response", "Maximum no of custom module created"); //no i18n
                    break;
                }
                validateAndCreateCustomModulesForAutomation(customModuleNumber, getModuleInfoForCreateCustomModules("CModules".concat(String.valueOf(cm)), "CModule".concat(String.valueOf(cm)), "CModules".concat(String.valueOf(cm)), profiles), currentUserId, currentUserLocale, Boolean.TRUE);//no i18n
            }
            if(!resultObj.has("response")) {
            	resultObj.put("response", "Custom fields created in new section"); //no i18n
            }
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }
    
    /**
     * This method creates 50 new CustomModules with no Custom Fields
     * @return
     * @throws JSONException
     */
    public JSONObject maxcustommodulesUltimate() throws JSONException {
        try {
        	JSONArray profiles = new JSONArray(ProfileUtil.getAllProfileIds(null,false,false));
            for (int cm = 1; cm <= 50; cm++) {
                int customModuleNumber = CrmCustomModuleUtil.returnNextCustomModuleNumber();
                if (customModuleNumber == -1) {
                	resultObj.put("response", "Maximum no of custom module created"); //no i18n
                    break;
                }
                validateAndCreateCustomModulesForAutomation(customModuleNumber, getModuleInfoForCreateCustomModules("CModules".concat(String.valueOf(customModuleNumber)), "CModule".concat(String.valueOf(customModuleNumber)), "CModules".concat(String.valueOf(customModuleNumber)), profiles), currentUserId, currentUserLocale, Boolean.FALSE);//no i18n
            }
            if(!resultObj.has("response")) {
            	resultObj.put("response", "50 Custom modules created."); //no i18n
            }
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }

    public JSONObject create_maxtab() throws JSONException { // ###used
        try {
            WebTabUtil.deleteAllWebTab();
            String items[][] = WebTabUtil.getWebTabDetails();
            int noOfWebTabs = 0;
            if (items != null) {
                noOfWebTabs = WebTabUtil.getWebTabDetails().length;
            }
            int maxWebTabs = FeatureEditionUtil.getFeatureLimits(CrmConstants.CUSTOM_FUNCTION_WEBTAB);

            SelectQuery sQry = new SelectQueryImpl(Table.getTable(CRMPROFILE.TABLE));
            sQry.addSelectColumn(Column.getColumn(CRMPROFILE.TABLE, CRMPROFILE.PROFILEID));
            DataObject dbo = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(sQry);
            @SuppressWarnings("rawtypes")
            Iterator ite = dbo.getRows(CRMPROFILE.TABLE);
            String profiles = "";
            while (ite.hasNext()) {
                Row row = (Row) ite.next();
                Long id = (Long) row.get(CRMPROFILE.PROFILEID);
                profiles += id + ";";
            }
            for (int k = noOfWebTabs; k < maxWebTabs; k++) {
                String google = "http://www.google.com"; //no i18n
                String tabId = WebTabUtil.setWebTabDetails("MaxWebTabs" + k, google); //no i18n
                if (tabId != null) {
                    WebTabUtil.setWebTabProfileRelation(tabId, profiles, "");
                }
            }

            TabGroupUtil.deleteAllTabGroups();
            String tabID = TabUtil.getTabIdByName(CrmModuleConstants.LEADS) + ";" + TabUtil.getTabIdByName(CrmModuleConstants.HOME) + ";" + TabUtil.getTabIdByName(CrmModuleConstants.FEEDS);
            long tabGroupCount = TabGroupUtil.getTabGroupCount();
            if (tabGroupCount < 0) {
                tabGroupCount = 0;
            }
            int maxTab = FeatureEditionUtil.getFeatureLimits(CrmConstants.CUSTOM_FUNCTION_TABGROUP);
            for (int i = Integer.parseInt("" + tabGroupCount); i < maxTab; i++) {
                TabGroupUtil.saveTabGroupDetails("MaxTabGroups" + i, tabID, profiles, "new", userId, ""); //no i18n
            }

            resultObj.put("response", "Maximum webtabs, tab groups created"); //no i18n
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }

    public JSONObject delete_tabgroups_webtabs() throws JSONException { // ###used
        try {
            TabGroupUtil.deleteAllTabGroups();
            WebTabUtil.deleteAllWebTab();
            Map tabGroup = TabGroupUtil.getAllTabGroupIdNameMap();
            String[][] webTab = WebTabUtil.getWebTabDetails();
            Boolean c_status = true;
            if(!tabGroup.isEmpty()){
            	c_status = false;
            	status = false;
            	resultObj.put("response", "tab group not deleted : "+tabGroup.toString()); //No I18N
            }
            if(webTab!=null){
            	c_status = false;
            	status = false;
            	resultObj.put("response", "web tab not deleted : "+tabGroup.toString()); //No I18N
            }
            if(c_status){
            	resultObj.put("response", "All Web tabs and Tab groups deleted"); //no i18n
            }
            resultObj.put("response", "All Web tabs and Tab groups deleted"); //no i18n
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }

