     public JSONObject enableRebuildForGivenSandbox() throws Exception{
    	 try {
	        	String sandboxName = request.getParameter("sandboxName");
	        	int count;
	    		if(sandboxName == null) {
	         		resultObj.put("response",  "please give sandbox name "); //no i18n
	                resultObj.put("status", status);
	                return resultObj;
	    		} else {
	    			LOGGER.log(Level.INFO, new StringBuilder("enableRebuildForGivenSandbox :: sandboxname :: ").append(sandboxName).append(" :: zgid ").append(OrgUtil.getCurrentZGID().toString()).toString());
	    	 		Criteria cr = SandboxConfigUtil.getSandboxRowCriteria();
	    	 		cr = cr.and(new Criteria(Column.getColumn(CRMSANDBOXACCOUNTS.TABLE, CRMSANDBOXACCOUNTS.NAME), sandboxName, QueryConstants.EQUAL));
	    	 		UpdateQuery uq = new UpdateQueryImpl(CRMSANDBOXACCOUNTS.TABLE);
	    	  		uq.setUpdateColumn(CRMSANDBOXACCOUNTS.LASTREFRESHEDTIME, -1);
	    	  		uq.setCriteria(cr);
	    	  		count = PersistenceCacheUtil.getPurePersistenceLiteHandle().update(uq);
	    	  		resultObj.put("response", "rebuild enabled"); //no i18n
	    		}
	    		if(count == 0) {
	    			status = false;
	    			resultObj.put("response", "Sandbox not found in this account");
	    		} else {
	    			status = true;
	            	resultObj.put("response", "rebuild enabled");
	            }
	        }
	        catch (Exception e) {
	            status = false;
	            resultObj.put("response", e.toString());
	        }
	        resultObj.put("status", status);
	        return resultObj;
     }

