     public JSONObject clear_sandbox_jobs() throws Exception{
 		Criteria cr = new Criteria(Column.getColumn(CRMSCHEDULEDJOBS.TABLE, CRMSCHEDULEDJOBS.ACTION), "SANDBOX_CLEANUP", QueryConstants.EQUAL);
  		DataObject scheduledJobDO = CrmScheduledJobsUtil.getCrmScheduledDataObject(cr);
         if(!scheduledJobDO.isEmpty()) {
         	Iterator<?> rowsItr = scheduledJobDO.getRows(CRMSCHEDULEDJOBS.TABLE);
         	while(rowsItr.hasNext()) {
         		Row row = (Row) rowsItr.next();
         		long curr_time = System.currentTimeMillis();
    				long schedulerStartTime = Long.valueOf(row.get(CRMSCHEDULEDJOBS.STARTTIME).toString());
    				long diff = curr_time - schedulerStartTime;
    				long diffHours = diff / (60 * 60 * 1000);
    				if(diffHours >= 1) {
    					Long jobId = (Long) row.get(CRMSCHEDULEDJOBS.JOBID);
    					ScheduledJobDetails updateSchJobDetails = new ScheduledJobDetails();
    					updateSchJobDetails.setJobId(jobId);
    					updateSchJobDetails.setStatus(ScheduledJobDetails.Status.FAILED);
    					CrmScheduledJobsUtil.updateJobDetails(updateSchJobDetails);
    				}
         	}
         }
         status = true;
         resultObj.put("response", "success");
         return resultObj;
     }
     public JSONObject clear_sandbox() throws Exception { // ###used
		 try {
			 String deployment_reset = request.getParameter("deployment_reset");
			 if(deployment_reset != null && deployment_reset.equals("true")) {
				 UpdateQueryImpl update = new UpdateQueryImpl(CRMSANDBOXACCOUNTS.TABLE);
				 update.setUpdateColumn(CRMSANDBOXACCOUNTS.STATUS, CrmSandboxConstants.IntStatus.ACTIVE.getStatus());
				 update.setCriteria(new Criteria(Column.getColumn(CRMSANDBOXACCOUNTS.TABLE, CRMSANDBOXACCOUNTS.STATUS), CrmSandboxConstants.IntStatus.INPROGRESS.getStatus(), QueryConstants.EQUAL));
				 PersistenceCacheUtil.getPurePersistenceLiteHandle().update(update);
				 resultObj.put("response", "deployment reset success");
				 status = true;
				 return resultObj;
			 }
		 } catch(Exception e) {
			 LOGGER.log(Level.SEVERE, "Problem while resetting deployment status", e);
			 resultObj.put("response", e.toString());
			 status = false;
			 return resultObj;
		 }
    	 if(!OrgUtil.isSandboxAccount()) {
    		 try {
    			 String zgid = OrgUtil.getCurrentZGID().toString();
    			 long curr_time = System.currentTimeMillis();
 		  		SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMSANDBOXACCOUNTS.TABLE));
 	     		sq.addSelectColumn(Column.getColumn(null, "*"));
 	     		DataObject dObj = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(sq);
 	     		if(dObj.isEmpty()) {
 	     			resultObj.put("response", "Sandbox account not found in this org"); //no i18n
 	     			status = false;
 	     			return resultObj;
 	     		}
 	     	    // checking corrupted null zgid rows and deleting it
 	     		Iterator<Row> itr = dObj.getRows(CRMSANDBOXACCOUNTS.TABLE);
 	     		while(itr.hasNext())
				{
					Row row = itr.next();

					long startTime_ = Long.valueOf(row.get(CRMSANDBOXACCOUNTS.LASTREFRESHEDTIME).toString());
					long diff_ = curr_time - startTime_;
					long diffHours_ = diff_ / (60 * 60 * 1000);
					if (diffHours_ >= 6) {
						if (row.get(CRMSANDBOXACCOUNTS.ZGID) == null) {
							Criteria crt = new Criteria(Column.getColumn(CRMSANDBOXACCOUNTS.TABLE, CRMSANDBOXACCOUNTS.SANDBOXID), row.get(CRMSANDBOXACCOUNTS.SANDBOXID), QueryConstants.EQUAL);
							PersistenceCacheUtil.getPurePersistenceLiteHandle().delete(crt);

							status = true;
							resultObj.put("response", "done");
							resultObj.put("status", status);
							return resultObj;
						}
					}
				}
 	     		// is data corrupted check
 	     		Criteria sandbox_corrupted = new Criteria(Column.getColumn(CRMSANDBOXACCOUNTS.TABLE, CRMSANDBOXACCOUNTS.TYPE),2,QueryConstants.NOT_EQUAL);
 	     		sandbox_corrupted = sandbox_corrupted.and(Column.getColumn(CRMSANDBOXACCOUNTS.TABLE, CRMSANDBOXACCOUNTS.STATUS),new Integer[] {5,6,8},QueryConstants.IN);
 	     		DataObject corruptedSandbox = dObj.getDataObject(CRMSANDBOXACCOUNTS.TABLE, sandbox_corrupted);
 	     		if(!corruptedSandbox.isEmpty()) {
 	     			DataObject toClean = dObj.getDataObject(CRMSANDBOXACCOUNTS.TABLE, new Criteria(Column.getColumn(CRMSANDBOXACCOUNTS.TABLE, CRMSANDBOXACCOUNTS.STATUS),new Integer[] {5,6,8},QueryConstants.IN));
 	 	     		Iterator<Row> rowIter = toClean.getRows(CRMSANDBOXACCOUNTS.TABLE);
 	 	     		Iterator<Row> tempRowIter = toClean.getRows(CRMSANDBOXACCOUNTS.TABLE);
 	 	     		List<String> list = new ArrayList<>();
 	 	     		boolean clear_job_table = true;
 	 	     		List<Long> toCleanSandboxIDs = new ArrayList<>();
 	 	     		while(tempRowIter.hasNext()) {
 	 	     			Row sandboxRow = tempRowIter.next();
 	 	     			toCleanSandboxIDs.add( (Long)sandboxRow.get(CRMSANDBOXACCOUNTS.SANDBOXID) );
 	 	     		}
 	 	     		
 	 	     		Criteria jobCriteria =  new Criteria(Column.getColumn(CRMSCHEDULEDJOBS.TABLE, CRMSCHEDULEDJOBS.JOBID), toCleanSandboxIDs.toArray(), QueryConstants.IN);
 	 	     		DataObject scheduledJobsDO = CrmScheduledJobsUtil.getCrmScheduledDataObject(jobCriteria);
 	 	     				
 	 	     		while(rowIter.hasNext()) {
 	 	     				Row sandboxRow = rowIter.next();
 	 	     				String sandboxZgid = sandboxRow.get(CRMSANDBOXACCOUNTS.ZGID).toString();
 	 	     				String sandboxId = sandboxRow.get(CRMSANDBOXACCOUNTS.SANDBOXID).toString();
 	 	     				
 	 	     				long startTime = Long.valueOf(sandboxRow.get(CRMSANDBOXACCOUNTS.LASTREFRESHEDTIME).toString());
 	 	     				if(!scheduledJobsDO.isEmpty()) {
 	 	     					Criteria sandboxJobCriteria =  new Criteria(Column.getColumn(CRMSCHEDULEDJOBS.TABLE, CRMSCHEDULEDJOBS.JOBID), (Long)sandboxRow.get(CRMSANDBOXACCOUNTS.SANDBOXID), QueryConstants.EQUAL ); 	 	     					
 	 	     					Row scheduledJobRow = scheduledJobsDO.getRow(CRMSCHEDULEDJOBS.TABLE, sandboxJobCriteria);
 	 	     					
 	 	     					if(scheduledJobRow != null) {
 	 	     						startTime = Long.valueOf(scheduledJobRow.get(CRMSCHEDULEDJOBS.STARTTIME).toString());
 	 	     					}
 	 	     				}
 	 	     				if(SandboxConfigUtil.isSandboxDCFlow(zgid) && sandboxRow.get(CRMSANDBOXACCOUNTS.DATA_POPULATION_PREFERENCE) != null) {
 	 	     					JSONObject dataJSON = new JSONObject(sandboxRow.get(CRMSANDBOXACCOUNTS.DATA_POPULATION_PREFERENCE).toString());
 	 	     					if(dataJSON.has("jobInitiatedTime")) {
 	 	     						startTime = dataJSON.getLong("jobInitiatedTime");// No I18N
 	 	     					}
 	 	     				}

 	 	     				long diff = curr_time - startTime;
 	 	     				long diffHours = diff / (60 * 60 * 1000);
 	 	     				if(diffHours >= 6) {
 	 	     					list.add(sandboxZgid);
 	 	     					if(clear_job_table) {
 	 	     							Criteria cr = new Criteria(Column.getColumn(CRMSCHEDULEDJOBS.TABLE, CRMSCHEDULEDJOBS.ACTION), "SANDBOX_CLEANUP",QueryConstants.EQUAL);
 	 	     							CrmScheduledJobsUtil.deleteJob(cr);
 	 	     							Criteria cr1 = new Criteria(Column.getColumn(CRMSCHEDULEDJOBS.TABLE, CRMSCHEDULEDJOBS.ACTION), "SANDBOX_CREATION",QueryConstants.EQUAL);
 	 	     							CrmScheduledJobsUtil.deleteJob(cr1);
 	 	     							clear_job_table = false;
 	 	     						}
 	 	     					UpdateQuery uq = new UpdateQueryImpl(CRMSANDBOXACCOUNTS.TABLE);
 	 	     	 		      	uq.setUpdateColumn(CRMSANDBOXACCOUNTS.STATUS,SandboxConfigUtil.getSandboxStatusId(SandboxConfigUtil.DELETED));
 	 	     	 		      	uq.setCriteria(new Criteria(Column.getColumn(CRMSANDBOXACCOUNTS.TABLE, CRMSANDBOXACCOUNTS.ZGID), sandboxZgid, QueryConstants.EQUAL));
 	 	     	 		      	PersistenceCacheUtil.getPersistenceLiteHandle().update(uq);
 	 	     	 		      	ScheduledJobDetails jobDetails = SandboxCreationUtil.getInstance().scheduleCleanUpForBackupSandbox(sandboxZgid,sandboxId);
 	 	 	         			SandboxCreationUtil.getInstance().triggerCleanUpForBackupSandbox(jobDetails);
 	 	 	         			SandboxConfigUtil.updateSandboxUserAccess(new Long[]{}, true, false, Long.valueOf(sandboxZgid));
 	 	 	         			LOGGER.log(Level.INFO, new StringBuilder("Sandbox cleanup initiated ::: SandboxID: ").append(sandboxId).append(" Start Time: ").append(startTime).append(" Job ID: ").append(jobDetails.getJobId()).toString() );
 	 	 	         			status = true;
 	 	 	         			resultObj.put("response", "done");
 	 	     				}else {
 	 	     					status = false;
 	 	     					resultObj.put("response", "sandbox created within 6 hours");
 	 	     				}

 	 	     			}
 	 	     		LOGGER.log(Level.INFO,new StringBuilder("SBOXMIGRATION Production ZGID ").append(zgid).append(" sandbox ZGIDS :::").append(list.toString()).toString());
 	     		}

    		 }catch(Exception e) {
    			 status = false;
                 resultObj.put("response", e.toString());
    		 }
			}
    	 resultObj.put("status", status);
         return resultObj;
     }

