		public JSONObject sandbox() throws JSONException { // ###used
			try {
				String sandboxName = request.getParameter("sandboxName");
				String deleteAll = request.getParameter("deleteAll");

				SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMSANDBOXACCOUNTS.TABLE));
				sq.addSelectColumn(Column.getColumn(null, "*"));
				Criteria cr = SandboxConfigUtil.getBackupSandboxCriteria(false);
				if (sandboxName != null) {
					cr = cr.and(new Criteria(Column.getColumn(CRMSANDBOXACCOUNTS.TABLE, CRMSANDBOXACCOUNTS.NAME), sandboxName, QueryConstants.EQUAL));
				}

				sq.setCriteria(cr);
				sq.addSortColumn(new SortColumn(Column.getColumn(CRMSANDBOXACCOUNTS.TABLE, CRMSANDBOXACCOUNTS.SANDBOXID), true));
				DataObject dObj = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(sq);
				if (dObj.isEmpty()) {
					resultObj.put("response", "Sandbox account not found in this org"); // no i18n
					status = false;
					return resultObj;
				}
				// int count = (sandboxName != null && !sandboxName.isEmpty() && deleteAll != null && !deleteAll.equalsIgnoreCase("true")) ? 1 : 0;
				Boolean skipFirst = true;
				if (sandboxName == null && deleteAll == null) {
					skipFirst = true;
				} else if ((sandboxName != null && !sandboxName.isEmpty()) || (deleteAll != null && deleteAll.equalsIgnoreCase("true"))) {
					skipFirst = false;
				}
				Boolean partiallyDeleted = false;
				List<String> deletedSandboxZgidList = new ArrayList<>();
                Map<Long,Long> zgidVsCleanupJobid = new HashMap<>();
				Iterator<Row> rowIter = dObj.getRows(CRMSANDBOXACCOUNTS.TABLE);
				while (rowIter.hasNext()) {
					if (skipFirst) {
						rowIter.next();
						skipFirst = false;
						continue;
					}
					Row sandboxRow = rowIter.next();
					String sandboxZgid = sandboxRow.get(CRMSANDBOXACCOUNTS.ZGID).toString();
					String sandboxId = sandboxRow.get(CRMSANDBOXACCOUNTS.SANDBOXID).toString();
					Integer sandboxStatus = (Integer) sandboxRow.get(CRMSANDBOXACCOUNTS.STATUS);
					Boolean isCreationInProgress = sandboxStatus.equals(SandboxConfigUtil.getSandboxStatusId(SandboxConfigUtil.CREATING)) || sandboxStatus.equals(SandboxConfigUtil.getSandboxStatusId(SandboxConfigUtil.DATAPOP_INPROGRESS));
					Boolean isRebuildInProgress = sandboxStatus.equals(SandboxConfigUtil.getSandboxStatusId(SandboxConfigUtil.REFRESHING));
					Boolean isAlreadyDeleted = sandboxStatus.equals(SandboxConfigUtil.getSandboxStatusId(SandboxConfigUtil.DELETED));
					if (!isAlreadyDeleted) {
						if (isCreationInProgress) {

							Criteria jobCriteria = new Criteria(Column.getColumn(CRMSCHEDULEDJOBS.TABLE, CRMSCHEDULEDJOBS.JOBID), sandboxId, QueryConstants.EQUAL);
							DataObject scheduledJobsDO = CrmScheduledJobsUtil.getCrmScheduledDataObject(jobCriteria);

							long startTime = Long.valueOf(sandboxRow.get(CRMSANDBOXACCOUNTS.LASTREFRESHEDTIME).toString());
							if (!scheduledJobsDO.isEmpty()) {
								Criteria sandboxJobCriteria = new Criteria(Column.getColumn(CRMSCHEDULEDJOBS.TABLE, CRMSCHEDULEDJOBS.JOBID), (Long) sandboxRow.get(CRMSANDBOXACCOUNTS.SANDBOXID), QueryConstants.EQUAL);
								Row scheduledJobRow = scheduledJobsDO.getRow(CRMSCHEDULEDJOBS.TABLE, sandboxJobCriteria);

								if (scheduledJobRow != null) {
									startTime = Long.valueOf(scheduledJobRow.get(CRMSCHEDULEDJOBS.STARTTIME).toString());
								}
							}
							long curr_time = System.currentTimeMillis();
							long diff = curr_time - startTime;
							long diffHours = diff / (60 * 60 * 1000);
							if (!(diffHours >= 3)) {
								partiallyDeleted = true;
								continue;
							}
						}
						if (isRebuildInProgress) {
							Criteria jobCriteria = new Criteria(Column.getColumn(CRMSCHEDULEDJOBS.TABLE, CRMSCHEDULEDJOBS.JOBID), sandboxId, QueryConstants.EQUAL);
							DataObject scheduledJobsDO = CrmScheduledJobsUtil.getCrmScheduledDataObject(jobCriteria);

							long startTime = Long.valueOf(sandboxRow.get(CRMSANDBOXACCOUNTS.LASTREFRESHEDTIME).toString());
							if (!scheduledJobsDO.isEmpty()) {
								Criteria sandboxJobCriteria = new Criteria(Column.getColumn(CRMSCHEDULEDJOBS.TABLE, CRMSCHEDULEDJOBS.JOBID), (Long) sandboxRow.get(CRMSANDBOXACCOUNTS.SANDBOXID), QueryConstants.EQUAL);
								Row scheduledJobRow = scheduledJobsDO.getRow(CRMSCHEDULEDJOBS.TABLE, sandboxJobCriteria);

								if (scheduledJobRow != null) {
									startTime = Long.valueOf(scheduledJobRow.get(CRMSCHEDULEDJOBS.STARTTIME).toString());
								}
							}
							long curr_time = System.currentTimeMillis();
							long diff = curr_time - startTime;
							long diffHours = diff / (60 * 60 * 1000);
							if (diffHours >= 3) {
								// revert sandbox rebuild and schedule cleanup
								DataObject backupDO = (Integer)sandboxRow.get(CRMSANDBOXACCOUNTS.TYPE) == SandboxConfigUtil.getSandboxTypeId(SandboxConfigUtil.API_FULL_DATA) ? SandboxConfigUtil.getCStoreBackupSandbox() : SandboxConfigUtil.getBackupSandbox();
								Row oldSandboxRow = backupDO.getFirstRow(CRMSANDBOXACCOUNTS.TABLE);
								sandboxZgid = String.valueOf( oldSandboxRow.get(CRMSANDBOXACCOUNTS.ZGID)); // zgid will be cleaned up
								SandboxCreationUtil.getInstance().revertRebuildOnAutomation(sandboxRow, oldSandboxRow);

							} else {
								partiallyDeleted = true;
								continue;
							}
						}
						SandboxConfigUtil.updateSandboxUserAccess(new Long[] {}, true, false, Long.valueOf(sandboxZgid));
						deletedSandboxZgidList.add(sandboxZgid);
						ScheduledJobDetails sch = SandboxCreationUtil.getInstance().scheduleCleanUpForBackupSandbox(sandboxZgid, sandboxId);
                        zgidVsCleanupJobid.put(Long.valueOf(sandboxZgid),(Long) sch.getJobId());
						SandboxCreationUtil.getInstance().triggerCleanUpForBackupSandbox(sch);
					}
				}
				if (!deletedSandboxZgidList.isEmpty()) {
					UpdateQuery uq = new UpdateQueryImpl(CRMSANDBOXACCOUNTS.TABLE);
					uq.setUpdateColumn(CRMSANDBOXACCOUNTS.STATUS, SandboxConfigUtil.getSandboxStatusId(SandboxConfigUtil.DELETED));
					uq.setCriteria(new Criteria(Column.getColumn(CRMSANDBOXACCOUNTS.TABLE, CRMSANDBOXACCOUNTS.ZGID), deletedSandboxZgidList.toArray(), QueryConstants.IN));
					PersistenceCacheUtil.getPurePersistenceLiteHandle().update(uq);
				}
				if(deletedSandboxZgidList.isEmpty()) {
					resultObj.put("response","No Sandbox account deleted"); // no
				}else {
					resultObj.put("response", partiallyDeleted ? "Sandbox account deleted partially ::: " + deletedSandboxZgidList : "Sandbox account deleted ::: " + deletedSandboxZgidList); // no
				}
                resultObj.put("jobMap",zgidVsCleanupJobid.toString());
				LOGGER.log(Level.INFO, "delete sandbox resetJSP >>> sandboxName ::: {0}, deleteAll ::: {1}, deletedSandboxZgidList ::: {2}", new Object[] { sandboxName, deleteAll, deletedSandboxZgidList });
				resultObj.put("response", partiallyDeleted ? "Sandbox account deleted partially ::: " + deletedSandboxZgidList.toString() : "Sandbox account deleted ::: " + deletedSandboxZgidList.toString()); // no
																																																					// i18n
				Criteria clean_cr = new Criteria(Column.getColumn(CRMSCHEDULEDJOBS.TABLE, CRMSCHEDULEDJOBS.ACTION), "SANDBOX_CLEANUP", QueryConstants.EQUAL);
		  		DataObject scheduledJobDO = CrmScheduledJobsUtil.getCrmScheduledDataObject(clean_cr);
		         if(!scheduledJobDO.isEmpty()) {
		         	Iterator<?> rowsItr = scheduledJobDO.getRows(CRMSCHEDULEDJOBS.TABLE);
		         	while(rowsItr.hasNext()) {
		         		Row row = (Row) rowsItr.next();
		         		long curr_time = System.currentTimeMillis();
		    				long schedulerStartTime = Long.valueOf(row.get(CRMSCHEDULEDJOBS.STARTTIME).toString());
		    				long diff = curr_time - schedulerStartTime;
		    				long diffHours = diff / (60 * 60 * 1000);
		    				if(diffHours >= 1) {
		    					Long jobId = (Long) row.get(CRMSCHEDULEDJOBS.JOBID);
		    					ScheduledJobDetails updateSchJobDetails = new ScheduledJobDetails();
		    					updateSchJobDetails.setJobId(jobId);
		    					updateSchJobDetails.setStatus(ScheduledJobDetails.Status.FAILED);
		    					CrmScheduledJobsUtil.updateJobDetails(updateSchJobDetails);
		    				}
		         	}
		         }
			} catch (Exception e) {
				status = false;
				resultObj.put("response", e.toString());
				String logString = new StringBuilder("SandboxResetException ").append(SandboxConfigUtil.getExceptionTraceAsString(e)).toString(); // No I18N
				LOGGER.log(Level.SEVERE, logString);
			}
			resultObj.put("status", status);
			return resultObj;
		}

    public JSONObject getSandboxOrgId() throws Exception { // ###used
    	String sandboxName = request.getParameter("sandboxName");

    	SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMSANDBOXACCOUNTS.TABLE));
 		sq.addSelectColumn(Column.getColumn(null, "*"));

 		Criteria cr = SandboxConfigUtil.getBackupSandboxCriteria(false);
 		cr = cr.and(new Criteria(Column.getColumn(CRMSANDBOXACCOUNTS.TABLE, CRMSANDBOXACCOUNTS.STATUS), 4, QueryConstants.NOT_EQUAL));
 		cr = cr.and(new Criteria(Column.getColumn(CRMSANDBOXACCOUNTS.TABLE, CRMSANDBOXACCOUNTS.STATUS), 7, QueryConstants.NOT_EQUAL));
 		if(sandboxName != null) {
 			cr = cr.and(new Criteria(Column.getColumn(CRMSANDBOXACCOUNTS.TABLE, CRMSANDBOXACCOUNTS.NAME), sandboxName, QueryConstants.EQUAL));
 		}

 		sq.setCriteria(cr);

 		sq.addSortColumn(new SortColumn(Column.getColumn(CRMSANDBOXACCOUNTS.TABLE, CRMSANDBOXACCOUNTS.SANDBOXID), true));

 		DataObject dObj = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(sq);

 		Row sandboxRow = dObj.getRow(CRMSANDBOXACCOUNTS.TABLE);

    	String sandboxZgid = sandboxRow == null ? null : sandboxRow.get(CRMSANDBOXACCOUNTS.ZGID).toString();
    	resultObj.put("response", OrgUtil.isSandboxAccount() ? "Invoked within Sandbox account" : (sandboxZgid == null ? "No sandbox account present" : sandboxZgid)); //no i18n
    	resultObj.put("status", status);
    	return resultObj;
    }

    public JSONObject checkModuleFieldPresenceInSandbox() throws Exception {
    	Long sandboxZgid =null;
    	String sandboxName = request.getParameter("sandboxName");
		Row sandboxRow;
    	String response = null;
    	 if(sandboxName == null){
     		response = "please give sandbox name "; //No I18N
     		resultObj.put("response",  response); //no i18n
            resultObj.put("status", status);
            return resultObj;
     	}else {
    		SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMSANDBOXACCOUNTS.TABLE));
	 		sq.addSelectColumn(Column.getColumn(null, "*"));

	 		Criteria cr = SandboxConfigUtil.getBackupSandboxCriteria(false);
	 		cr = cr.and(new Criteria(Column.getColumn(CRMSANDBOXACCOUNTS.TABLE, CRMSANDBOXACCOUNTS.NAME), sandboxName, QueryConstants.EQUAL));

	 		sq.setCriteria(cr);
	 		sq.addSortColumn(new SortColumn(Column.getColumn(CRMSANDBOXACCOUNTS.TABLE, CRMSANDBOXACCOUNTS.SANDBOXID), true));

	 		DataObject dObj = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(sq);

	 		sandboxRow = dObj.getRow(CRMSANDBOXACCOUNTS.TABLE);
	 		if (sandboxRow != null) {
	 			sandboxZgid = Long.valueOf(sandboxRow.get(CRMSANDBOXACCOUNTS.ZGID).toString());
	 		}
    	}

    	if(OrgUtil.isSandboxAccount()) {
    		response = "Invoked within Sandbox account"; //No I18N
    	} else if (sandboxZgid == null) {
    		response = "No sandbox account present"; //No I18N
    	} else {
    		String module = request.getParameter("module");
            String fieldlabel = request.getParameter("fieldlabel");

            String tabName = TabUtil.getTabNameByLabel(module);
            if(tabName == null) {
            	response = "Tab not found for label : " + module; //No I18N
            } else {
            	Long id = null;
            	if (fieldlabel != null) {
            		id = CrmFieldUtil.getFieldIdUsingLabelFromCachedDO(tabName, fieldlabel, null);
            	} else {
            		id = TabUtil.getTabIdByName(tabName);
            	}
            	if(id == null) {
            		response = "Item missing in production account"; //No I18N
            	} else {
            		response = Boolean.toString(SandboxConfigUtil.getSandboxMappedId(id, false, sandboxZgid.toString()) != null);
            	}
            }
    	}
        resultObj.put("response",  response); //no i18n
        resultObj.put("status", status);
        return resultObj;
    }

