    public JSONObject deletebutton() throws JSONException { // ###used
        try {
            String module = request.getParameter("module");
            CrmUsers crmUsers = CrmUsers.getInstance(userId, Boolean.FALSE);
            CrmModules.Get crmModulesGet = CrmModules.getInstance(crmUsers).new Get(module);
            CrmCustomButtons crmCustomButtons = CrmCustomButtons.getInstance(crmModulesGet);
            CrmCustomButtons.Get crmCustomButtonsGet = crmCustomButtons.new Get();
            crmCustomButtonsGet.setFromAutomationResetConfiguration(true);
            JSONArray customButtonsArray = crmCustomButtonsGet.getCustomButtons();

            for (int i = 0; i < customButtonsArray.length(); i++) {
                JSONObject btn = (JSONObject) customButtonsArray.get(i);
                Long ID = Long.parseLong((String) btn.get("id"));
                CrmCustomButtons.Delete crmCustomButtonsDelete = crmCustomButtons.new Delete();
                crmCustomButtonsDelete.setButtonId(ID);
                crmCustomButtonsDelete.delete();
                LinkedHashMap<String, String> dependencyList = new LinkedHashMap<String, String>();
				dependencyList.put(TabUtil.MODULE, TabUtil.getTabIdByName(module).toString());
				Map<String, String> otherInfo = new HashMap<String,String>();
				otherInfo.put(PMDConstants.MODULE, module);
                if(OrgUtil.isSandboxAccount()){
                SandboxConfigUtil.trackChanges(ID, SandboxConfigConstants.BUTTON, String.valueOf(btn.get("name")), SandboxOperationType.DELETE, dependencyList,null,otherInfo);//no i18n
        }
            }
            boolean status_c = false;
            try{
	            crmUsers = CrmUsers.getInstance(userId, Boolean.FALSE);
	            crmModulesGet = CrmModules.getInstance(crmUsers).new Get(module);
	            crmCustomButtons = CrmCustomButtons.getInstance(crmModulesGet);
	            crmCustomButtonsGet = crmCustomButtons.new Get();
	            customButtonsArray = crmCustomButtonsGet.getCustomButtons();
            }catch(Exception e){
            	status_c = true;
            }

            if(status_c){
            	resultObj.put("response","Buttons Deleted successfully");//No I18N
            }else{
            	status = false;
            	resultObj.put("response","Buttons not Deleted : "+customButtonsArray.toString());//No I18N
            }
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;

    }

