    public JSONObject createFormRule()throws Exception{
		try{

			String module = request.getParameter("module");
			String formRuleName = request.getParameter("formRuleName");
			String crtField = request.getParameter("criteriaField");
			String crtValue = request.getParameter("criteriaValue");
			String crtComparator = request.getParameter("criteriaComparator");
			String layoutName = request.getParameter("layoutName");

			DataObject fieldsDO = FieldUtil.getFieldsDOForModule(module, null);
			Row fieldRow = fieldsDO.getRow(CRMFIELD.TABLE, new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDLABEL), crtField, QueryConstants.EQUAL));
			Long primaryFieldId = (Long) fieldRow.get(CRMFIELD.FIELDID);
			Long tabId = (Long) fieldRow.get(CRMFIELD.TABID);
			Long layoutId = PageLayoutUtil.getLayoutIDByLayoutName(tabId,layoutName);
			Criteria cr = FormRuleUtil.getLRPrimaryFieldCriteria(fieldsDO,crtField,crtValue,crtComparator);

			FormRulesPOJO formRulesPojo = new FormRulesPOJO();
			formRulesPojo.setFormRuleName(formRuleName);
			formRulesPojo.setPrimaryFieldId(primaryFieldId);
			formRulesPojo.setModule(module);
			formRulesPojo.setLayoutId(Long.valueOf(layoutId));
			formRulesPojo.setIsInternal(false);
			formRulesPojo.setCategory(1);
			formRulesPojo.setLocale(currentUserLocale);
			formRulesPojo.setUserId(userId);
			formRulesPojo.setCriteria(cr);
			FormRuleHandler.createFormRuleUsingPOJO(fieldsDO,formRulesPojo);

		}
		catch (Exception e){
		     status = false;
		     resultObj.put("response", e.toString());
		}
		resultObj.put("status", status);
		return resultObj;
	}

    public JSONObject updateFormRuleCondition()throws Exception{
    	try{
    		String module = request.getParameter("module");
			String formRuleName = request.getParameter("formRuleName");
			String conditionName = request.getParameter("conditionName");
			String crtField1 = request.getParameter("criteriaField1");
			String crtValue1 = request.getParameter("criteriaValue1");
			String crtComparator1 = request.getParameter("criteriaComparator1");
			String crtField2 = request.getParameter("criteriaField2");
			String crtValue2 = request.getParameter("criteriaValue2");
			String crtComparator2 = request.getParameter("criteriaComparator2");

			Long formRuleId = FormRuleUtil.getFormRuleIdByFormRuleName( formRuleName, module);
			DataObject queryDO = FormRuleUtil.getFormRuleandQueryDO(formRuleId);
			Long queryId = (Long) queryDO.getFirstRow(CRMFORMRULEQUERYIDMAP.TABLE).get(CRMFORMRULEQUERYIDMAP.QUERYID);
			Long layoutId = (Long) queryDO.getRow(CRMFORMRULE.TABLE).get(CRMFORMRULE.LAYOUTID);

			DataObject fieldsDO = FieldUtil.getFieldsDOForModule(module, null);
			Criteria crtDetails = ResetConfigAutomationUtil.getMainCriteria(fieldsDO, crtField1, crtValue1, crtComparator1, crtField2, crtValue2, crtComparator2);

			FormRuleHandler.updateFormRuleCondition(conditionName, crtDetails, queryId, module, false ,null);
			FormRuleHandler.updateFormRuleModifiedDetails(formRuleId, userId);
			FormRuleUtil.deleteFormRuleJSONEntryFromCacheAndZFS(layoutId, module );
			FormRuleUtil.sendAllLayoutIdsToAllClient(module);

    	}
    	catch(Exception e) {
		     status = false;
		     resultObj.put("response", e.toString());
    	}
		resultObj.put("status", status);
		return resultObj;
    }

    public JSONObject createFormRuleActions()throws Exception{
    	try {
    		String module = request.getParameter("module");
			String formRuleName = request.getParameter("formRuleName");
			int actionType = Integer.valueOf(request.getParameter("actionType"));
    		String actionLabels = request.getParameter("actionLabels");
    		String layoutName = request.getParameter("layoutName");

			JSONArray elementsArr = FormRuleUtil.getActionableElementsArr(actionLabels, actionType, module, layoutName,zgId.toString());
			Long formRuleId = FormRuleUtil.getFormRuleIdByFormRuleName( formRuleName, module);
			DataObject queryDO = FormRuleUtil.getFormRuleandQueryDO(formRuleId);
			Long queryId = (Long) queryDO.getFirstRow(CRMFORMRULEQUERYIDMAP.TABLE).get(CRMFORMRULEQUERYIDMAP.QUERYID);
			Long layoutId = (Long) queryDO.getRow(CRMFORMRULE.TABLE).get(CRMFORMRULE.LAYOUTID);

			FormRuleHandler.createFormRuleQueryActions(queryId, actionType, elementsArr);
			FormRuleHandler.updateFormRuleModifiedDetails(formRuleId, userId);
			FormRuleUtil.deleteFormRuleJSONEntryFromCacheAndZFS( layoutId, module );
			FormRuleUtil.sendAllLayoutIdsToAllClient(module);

    	}
    	catch(Exception e) {
		     status = false;
		     resultObj.put("response", e.toString());
    	}
		resultObj.put("status", status);
		return resultObj;
    }

