    public JSONObject approval_process() throws JSONException { // ###used
        try {
            @SuppressWarnings("rawtypes")
            List ap_modules=ApprovalProcessUtil.getApprovalSupportedModules();
            List<Long> wftasks = new ArrayList<Long>();
            for (Object module: ap_modules) {
                List<Long> processIds = new ArrayList<Long>();
                List<Long> ruleIds = new ArrayList<Long>();
                Criteria delCrt = new Criteria(Column.getColumn(CRMWORKFLOWRULE.TABLE, CRMWORKFLOWRULE.RULETYPE), module, QueryConstants.EQUAL);
                delCrt = delCrt.and(new Criteria(Column.getColumn(CRMWORKFLOWRULE.TABLE, CRMWORKFLOWRULE.TYPE), new Integer[] { AutomationFeatureConstants.TYPE_APPROVAL_PROCESS, AutomationConstants.TYPE_APPROVAL_PROCESS_DELETED } , QueryConstants.IN));
                SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMWORKFLOWRULE.TABLE));
                sq.addJoin( new Join( CRMWORKFLOWRULE.TABLE, CRMAPPROVALRULES.TABLE, new String[]{CRMWORKFLOWRULE.RULEID}, new String[]{CRMAPPROVALRULES.PROCESSID},Join.INNER_JOIN ) );
                sq.setCriteria(delCrt);
                sq.addSelectColumn(Column.getColumn(CRMWORKFLOWRULE.TABLE, "*"));
                sq.addSelectColumn(Column.getColumn(CRMAPPROVALRULES.TABLE, "*"));
                DataObject dObj = PersistenceCacheUtil.getNonCachePersistenceHandle().get(sq);

                if (!dObj.isEmpty()) {
                    @SuppressWarnings("rawtypes")
                    Iterator itr = dObj.getRows(CRMWORKFLOWRULE.TABLE);
                    while ( itr.hasNext() ) {
                        Row row = (Row) itr.next();
                        processIds.add((Long) row.get(CRMWORKFLOWRULE.RULEID));
                    }
                    itr = dObj.getRows(CRMAPPROVALRULES.TABLE);
                    while ( itr.hasNext() ) {
                        Row row = (Row) itr.next();
                        ruleIds.add((Long) row.get(CRMAPPROVALRULES.RULEID));
                    }
                }
                if(ruleIds.size()>0){
                sq = new SelectQueryImpl(Table.getTable(CRMWFREL.TABLE));
                sq.addSelectColumn(Column.getColumn(CRMWFREL.TABLE, "*"));
                delCrt = new Criteria(Column.getColumn(CRMWFREL.TABLE, CRMWFREL.RULEID), ruleIds.toArray(), QueryConstants.IN);
                delCrt = delCrt.and(new Criteria(Column.getColumn(CRMWFREL.TABLE, CRMWFREL.WFTASKID), null , QueryConstants.NOT_EQUAL));
                sq.setCriteria(delCrt);
                dObj = PersistenceCacheUtil.getNonCachePersistenceHandle().get(sq);
                if (!dObj.isEmpty()) {
                    @SuppressWarnings("rawtypes")
                    Iterator itr = dObj.getRows(CRMWFREL.TABLE,delCrt);
                    while ( itr.hasNext() ) {
                        Row row = (Row) itr.next();
                        wftasks.add((Long) row.get(CRMWFREL.WFTASKID));
                    }
                  }
                }
                for(Long processId:processIds) {
                    ApprovalProcessUtil.deleteApprovalProcess(processId);
                }
            }
            if(wftasks.size()>0){
    			Criteria crt = new Criteria( Column.getColumn( CRMWORKFLOWTASK.TABLE, CRMWORKFLOWTASK.WFTASKID ), wftasks.toArray(), QueryConstants.IN );
    			PersistenceCacheUtil.getPersistenceLiteHandle().delete( crt );
    		}
            String ALL = "All"; //no i18n
            JSONObject jo = ApprovalProcessUtil.getAllApprovalProcess(null,ALL,ALL,"false",(Locale) request.getAttribute("LOCALE_FROM_FILTER"),userId);
            if(jo.toString().equals("{}")){
            	resultObj.put("response", "Approval Process rules Deleted , "+jo); //no i18n
            }else{
            	status = false;
            	resultObj.put("response", "Approval Process rules not Deleted , "+jo); //no i18n
            }
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }

    public JSONObject show_my_jobs_tab(){
        try {
    			LOGGER.log(Level.INFO, "Showing approvals tab");
				String tabLabel = TabUtil.getTabLabel(ApprovalProcessUtil.APPROVALS_TAB_NAME);
				if (tabLabel == null || "".equals(tabLabel))
				{
	    			LOGGER.log(Level.INFO, "Adding approvals tab");
					List<Long> allProfileIdsList = new ArrayList<Long>();
					List allProfileList = new ArrayList();
					allProfileList = ProfileUtil.getProfilesLists(null);
					Iterator proIter = allProfileList.iterator();
					while (proIter.hasNext()) {
						Object profileObj[] = (Object []) proIter.next();
						allProfileIdsList.add((Long) profileObj[0]);
					}
//					if (customerZgid != null) {
					CrmModuleUtil.addTabAndAssociateToProfiles(ApprovalProcessUtil.APPROVALS_TAB_NAME, allProfileIdsList, null,ApprovalProcessUtil.APPROVALS_TAB_LABLE);
						
//					} else {
//						TabUtil.addTabAndAssociateToProfiles(APPROVALS_TAB_NAME, allProfileIdsList,null,APPROVALS_TAB_LABLE);
//					}
				}
				else
				{
	    			LOGGER.log(Level.INFO, "Updating presence to show approvals tab");
						TabUtil.updateTabPresense(ApprovalProcessUtil.APPROVALS_TAB_NAME, 1L);
				}
    	} catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }

