    public JSONObject scoringrule() throws JSONException { // ###used
        try {
            ScoringRulesUtil.deleteScoringRulesForModule(CrmModuleConstants.LEADS);
            ScoringRulesUtil.deleteScoringRulesForModule(CrmModuleConstants.CONTACTS);
            ScoringRulesUtil.deleteScoringRulesForModule(CrmModuleConstants.ACCOUNTS);
            ScoringRulesUtil.deleteScoringRulesForModule(CrmModuleConstants.POTENTIALS);
            String resp = "";
            DataObject scoringDO = ScoringRulesUtil.getAllCachedScoringDOForModule(CrmModuleConstants.LEADS);
			if(!scoringDO.isEmpty()){
				status = false;
				resp = resp + "\nsr not deleted for Leads";//no i18n
			}
			scoringDO = ScoringRulesUtil.getAllCachedScoringDOForModule(CrmModuleConstants.CONTACTS);
			if(!scoringDO.isEmpty()){
				status = false;
				resp = resp + "\nsr not deleted for Contacts";//no i18n
			}
			scoringDO = ScoringRulesUtil.getAllCachedScoringDOForModule(CrmModuleConstants.ACCOUNTS);
			if(!scoringDO.isEmpty()){
				status = false;
				resp = resp + "\nsr not deleted for Accounts";//no i18n
			}
			scoringDO = ScoringRulesUtil.getAllCachedScoringDOForModule(CrmModuleConstants.POTENTIALS);
			if(!scoringDO.isEmpty()){
				status = false;
				resp = resp + "\nsr not deleted for Potentials";//no i18n
			}
			if(status != false){
				resultObj.put("response", "Scoring rules deleted , "+resp); //no i18n
			}
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }

    public JSONObject deleteScoringrule() {
    	try {
    		ScoringRulesRead srRead = new ScoringRulesRead();
    		srRead.setOperation(OPERATION.DELETE);
    		List<ScoringRule> totalRules = srRead.getRules(null, null, null, null, 0, 0);
    		ScoringRulesWrite writer = new ScoringRulesWrite();
    		status = true;
    		StringBuilder ruleResp = new StringBuilder();
    		List<SRConfigResponse> srResp =	writer.deleteRules(totalRules, srRead.getReadOnlyDO());
    		srResp.forEach(resp -> {
    			if(!resp.isSuccess()) {
    				status = false;
    				ruleResp.append("\n").append(resp.getDetails()); //NO I18N
    			}
    		});
    		if(!status)
    		{
    			resultObj.put("response", ruleResp);
    		}
    	}
    	catch(Exception e) {
    		status = false;
            resultObj.put("response", e.toString());
    	}
    	resultObj.put("status", status);
        return resultObj;
    }

    /** To run daily scheduler execution */
    public JSONObject runScoringDailyScheduler() {
    	try {
    		String module = request.getParameter("module");
        	if(!SRCrudUtil.getExtnSupportedModules().contains(module)) {
        		status = false;
        		resultObj.put("response", "module not supported");
        		return resultObj;
        	}
        	SchedulerRunDetails schDetails = new ScoringRulesExecutor().new SchedulerRunDetails(module, true);
        	SRExecutionUtil.getTodayTimestamp(false, schDetails);
        	SRSchedulerExecutor executor = new SRSchedulerExecutor(module, schDetails, userId);
	    	executor.calculateScore();
	    	resultObj.put("response", "success");
    	}
    	catch(Exception e) {
    		status = false;
            resultObj.put("response", e.toString());
    	}
    	return resultObj;
    }
    
    /** To create daily scheduler job */
    public JSONObject createScoringDailyScheduler() {
    	try {
    		String module = request.getParameter("module");
        	if(!SRCrudUtil.getExtnSupportedModules().contains(module)) {
        		status = false;
        		resultObj.put("response", "module not supported");
        		return resultObj;
        	}
        	JSONObject actionInfo = new JSONObject();
        	actionInfo.put("isFromReset", true);
        	com.adventnet.crm.scoringrules.util.SRSchedulerUtil.createSequentialJob(UseCase.SCORING_DAILY_RUN, module, actionInfo, null, userId, String.valueOf(zgId));
        	resultObj.put("response", "success");
    	}
    	catch(Exception e) {
    		status = false;
            resultObj.put("response", e.toString());
    	}
    	return resultObj;
    }

    /** To trigger signal for scoring rule execution (dummy signal) */
    public JSONObject triggerSignalForScoringRules() {
		try {
			String module = request.getParameter("module");//No I18N
			String nameSpace = request.getParameter("namespace"); //No I18N
			Long seId = Long.parseLong(request.getParameter("entityId"));
			CrmNotificationCenter ntc = new CrmNotificationCenter();
			DataObject signalsDO = ntc.getSignalsSettingsDataObj();
			Row signalRow = signalsDO.getRow(CRMSIGNAL.TABLE, new Criteria(Column.getColumn(CRMSIGNAL.TABLE,CRMSIGNAL.NAMESPACE), nameSpace, QueryConstants.EQUAL));
			if(signalRow != null) {
				Long signalId = Long.parseLong(String.valueOf(signalRow.get(CRMSIGNAL.SIGNALID)));
				//As dummy entry will be added and EntityAuditLog deletion is not allowed, not inserting data into DB.
				//ntc.insert(userId, seId, module, new JSONObject().put("type", "dummyFromReset"), 10101, signalId, DateTimeUtils.getCurrentTimeInGMT(), true);
				Row notificationRow = ntc.constructRow(userId, seId, module, new JSONObject().put("type", "dummyFromReset"), 10101, signalId, DateTimeUtils.getCurrentTimeInGMT());
				DataObject newDO = new WritableDataObject();
				newDO.addRow(notificationRow);
				ntc.triggerActionsForNotificationsInsert(userId, newDO, true);
				resultObj.put("response", "success");
			}
			else {
				resultObj.put("response", "Signal not available for the given namespace");
			}
		}
		catch(Exception e) {
			status = false;
			resultObj.put("response", e.toString());
		}
		return resultObj;
    }

