    public JSONObject deleteAllCaseEscRules() throws Exception
    {
    	try
    	{
    		SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMCASEESCALATIONRULES.TABLE));
    		sq.addJoin(new Join(CRMCASEESCALATIONRULES.TABLE, CRMCASEESCALATIONS.TABLE, new String[]{CRMCASEESCALATIONRULES.RULEID}, new String[]{CRMCASEESCALATIONS.RULEID}, Join.LEFT_JOIN));
    		sq.addSelectColumn(Column.getColumn(CRMCASEESCALATIONS.TABLE, CRMCASEESCALATIONS.ESCALATIONID));
    		sq.addSelectColumn(Column.getColumn(CRMCASEESCALATIONRULES.TABLE, CRMCASEESCALATIONRULES.RULEID));
    		sq.addSelectColumn(Column.getColumn(CRMCASEESCALATIONRULES.TABLE, CRMCASEESCALATIONRULES.RULENAME));
    		sq.setRange(new Range(1,500));
    		Persistence persistenceHandle = PersistenceCacheUtil.getPurePersistenceLiteHandle();
    		DataObject caseDobj = persistenceHandle.get(sq);
    		Iterator<Row> iter = caseDobj.getRows(CRMCASEESCALATIONS.TABLE);
    		List<Long> escalationIds =  new ArrayList<Long>();
    		while(iter.hasNext())
    		{
    			Row caseEsc =iter.next();
    			escalationIds.add((Long)caseEsc.get(CRMCASEESCALATIONS.ESCALATIONID));
    		}
    		Iterator<Row> iterRules = caseDobj.getRows(CRMCASEESCALATIONRULES.TABLE);
    		while(iterRules.hasNext())
    		{
    			Row caseEscRule =iterRules.next();
    			Long ruleId = (Long) caseEscRule.get(CRMCASEESCALATIONRULES.RULEID);
    			String ruleName = (String) caseEscRule.get(CRMCASEESCALATIONRULES.RULENAME);
    			if(OrgUtil.isSandboxAccount())
				{
					LinkedHashMap<String, String> dependencyList = new LinkedHashMap<>();
					dependencyList.put(TabUtil.MODULE, TabUtil.getTabIdByName(CrmModuleConstants.CASES).toString());
					SandboxConfigUtil.trackChanges(ruleId, SandboxConfigConstants.CASEESCALATIONRULE, ruleName, SandboxOperationType.DELETE, dependencyList, null);
				}
    		}
    		
    		Criteria crt = new Criteria( Column.getColumn( CRMCASEESCALATIONRULES.TABLE, CRMCASEESCALATIONRULES.RULEID ), null, QueryConstants.NOT_EQUAL );
    		persistenceHandle.delete(crt);
    		ComponentsUsageUtil.deleteDependentComponentsUsage(escalationIds);
    	}
    	catch (Exception e)
    	{
            status = false;
            resultObj.put("response", e.toString());
        }
		resultObj.put("status", status);
        return resultObj;
    }

    public JSONObject deleteauditlog() throws JSONException { // ###used
        try {
              long no_of_days=60;
              String daysRequired = request.getParameter("daysRequired");
              if(daysRequired != null){
            	  no_of_days = Long.parseLong(daysRequired);
              }
              
              String zgid = OrgUtil.getCurrentZGID().toString();
              boolean isDistDBEnabled = CrmFeatureUtil.isFeatureEnabled(CrmFeatureUtil.Feature.DISTDB_AUDDITLOG_MIGRATION_STATUS.name(), null, zgid);
              String entityAuditLogTableName = AuditLogTableConstants.getTableName(isDistDBEnabled);
              
              List < SortColumn > sortCols = new ArrayList < SortColumn > ();
              sortCols.add(new SortColumn(Column.getColumn(entityAuditLogTableName, AuditLogTableConstants.AUDITEDTIME), false, true));
              sortCols.add(new SortColumn(Column.getColumn(entityAuditLogTableName, AuditLogTableConstants.AUDITLOGID), false, true));
              Timestamp t=new Timestamp( DateTimeUtils.getCurrentTimeInGMT().getTime() - no_of_days*86400000 );
              Criteria cr3 = new Criteria(Column.getColumn(entityAuditLogTableName, AuditLogTableConstants.AUDITEDTIME), t, QueryConstants.LESS_EQUAL);
              
              DeleteQuery dq = new DeleteQueryImpl(entityAuditLogTableName);

              //<!-- dq.addSortColumns(sortCols); -->
              dq.setCriteria(cr3);
              dq.setLimit(10000);
              int rows=0;
              if(isDistDBEnabled) {
  				  cr3 = cr3.and(new Criteria(Column.getColumn(entityAuditLogTableName, AuditLogTableConstants.ZGID), zgid, QueryConstants.EQUAL));
            	  rows = DistdbAuditLogUtil.deleteDistDBAuditLogUsingPKChunker(entityAuditLogTableName, cr3,10000);
                  LOGGER.log(Level.INFO, "DISTDB - Number of Rows deleted", new Object[] {rows});
              } else { 
            	  do{
            		  rows = PersistenceCacheUtil.getPurePersistenceLiteHandle().delete(dq);
            	  }while(rows!=0);
              }
            
              resultObj.put("response", "Auditlog entries deleted"); //no i18n
          } catch (Exception e) {
              status = false;
              resultObj.put("response", e.toString());
          }
        resultObj.put("status", status);
        return resultObj;


      }

