    /**
     * Remove BT Keys for flushing
     */
    public JSONObject remove_bt_keyval() {
        try {
            String key = request.getParameter("key");
            status = true;
			if("BEST_TIME_NOTES_INSIGHTS_ENABLED".equals(key) || "BEST_MODE_FEATURE_MIGRATED".equals(key) || "BEST_TIME_ANALYTICS_ENABLED_DURATION".equals(key)) {
				if(CrmKeyValueUtil.getCrmNCKeyValue(key) != null) {
					CrmKeyValueUtil.deleteCrmNCKeyValueByKeyName(key, OrgUtil.getCurrentZGID().toString(), true);
					resultObj.put("response", "Key deleted");
				}
				else {
					resultObj.put("response", "Key not present in DB");
				}
			}
			else {
				resultObj.put("response", "Only BEST_TIME_NOTES_INSIGHTS_ENABLED, BEST_MODE_FEATURE_MIGRATED, BEST_TIME_ANALYTICS_ENABLED_DURATION keys are supported!");
			}
		}
		catch (Exception e) {
			LOGGER.log(Level.WARNING, "EXCEPTION WHILE DELETING BT KEYS IN TABLE :::: ", e);
			status = false;
			resultObj.put("response", e.toString());
		}
		resultObj.put("status", status);
		return resultObj;
    }

    /**
     * Update migration ran key val to handle Filter options in client
     * @return response of graph.
     */
	public JSONObject update_bta_keyval() {
		try {
			status = true;
			if(BestTimeAnalyticsMetaDataUtil.didBTAnalyticsMigrationRun()) {
				CrmKeyValueUtil.insertOrUpdateCrmNCKeyValueByKeyName("BEST_TIME_ANALYTICS_ENABLED_DURATION", "915215400000", true);//NO I18N
				resultObj.put("response", "Key Updated");
			}
			else {
				resultObj.put("response", "Key not updated");
			}
		}
		catch (Exception e) {
			LOGGER.log(Level.WARNING, "EXCEPTION WHILE GETTING BT USAGE ANALYTICS :::: ",e);
			status = false;
			resultObj.put("response", e.toString());
		}
		resultObj.put("status", status);
		return resultObj;
	}

	/**
     * Trigger Zia Reminder
     * @return true if reminder triggered else false
     */
    public JSONObject triggerZiaReminders() {
        try {
			String zgId = String.valueOf(OrgUtil.getCurrentZGID());
			Map<Long, ZiaReminderNotificationDetails> notificationList = ZiaReminderUtil.getReminderDetails(null,true);
			LOGGER.log(Level.INFO, "Notification List : {0}", new Object[] {notificationList.size()});
			for (Map.Entry<Long, ZiaReminderNotificationDetails> entry : notificationList.entrySet()) {
				ZiaReminderNotificationDetails reminderData = entry.getValue();
				if(reminderData.isValid()) {
					LOGGER.log(Level.INFO, "Trigger Reminder For Automation :::: {0}", new Object[] {reminderData.toString()});
					reminderData.setZgid(zgId);
					WmsApi.sendCustomMessage(reminderData.getZuid().toString(), new JSONObject(new ObjectMapper().writeValueAsString(reminderData)));
				}
			}
			if (!ZiaReminderUtil.isReminderAvailable()) {
				ZiaReminderUtil.updateRepetitiveJob("false");
			}
        }
        catch (Exception e) {
            LOGGER.log(Level.WARNING, "EXCEPTION WHILE TRIGGERING BEST TIME ZIA REMINDER :::: ",e);
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }

