    public JSONObject deleteAutoresponder() throws JSONException {
        try {
            AutoResponderUtil.deleteAllResponders();
            SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMAUTORESPONDER.TABLE));
    		sq.addSelectColumn(Column.getColumn(null,"*"));
    		Join join=new Join(CRMAUTORESPONDER.TABLE,CRMAUTORESPONDERREL.TABLE,new String[]{ CRMAUTORESPONDER.RESPONDERID },new String[]{ CRMAUTORESPONDERREL.RESPONDERID },Join.LEFT_JOIN);
    		sq.addJoin( join );

    		join = new Join( CRMAUTORESPONDER.TABLE,CRMEMAILADDRESSDETAILS.TABLE, new String[]{CRMAUTORESPONDER.RESPONDERID}, new String[]{ CRMEMAILADDRESSDETAILS.FEATURERELATEDID }, Join.LEFT_JOIN );
    		sq.addJoin( join );
    		join = new Join( CRMAUTORESPONDERREL.TABLE,CRMEMAILADDRESSDETAILS.TABLE, new String[]{CRMAUTORESPONDERREL.RESPONDERRELID}, new String[]{ CRMEMAILADDRESSDETAILS.FEATURERELATEDID },CRMAUTORESPONDERREL.TABLE,"CrmEmailAddressDetails_ALIAS",Join.LEFT_JOIN );
    		sq.addJoin( join );

    		DataObject dataObj =  PersistenceCacheUtil.getNonCachePersistenceHandle().get(sq);
    		Iterator<Row> iter = dataObj.getRows(CRMAUTORESPONDER.TABLE);
    		List<Long> idlist = new ArrayList<Long>();
    		while(iter.hasNext())
    		{
    			Row relRow = iter.next();
    			Long responderId =(Long) relRow.get(CRMAUTORESPONDER.RESPONDERID);
    			if(responderId!=null)
    			{
    				idlist.add(responderId);
    			}
    		}
    		if(idlist.size()==0){
            resultObj.put("response", "Auto responders deleted"); //no i18n
    		}else{
    			resultObj.put("response","Auto responders not deleted : "+idlist.toString()); //no i18n
    		}
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }

