    @SuppressWarnings("deprecation")
	public JSONObject enable_anomaly() throws JSONException {
        try {
            Persistence persistence = PersistenceCacheUtil.getNonCachePersistenceHandle(zgId + "");
            //Long dbFolderId = DashboardUtil.getDashboardFolderId();
            SelectQuery qry = new SelectQueryImpl(Table.getTable(CRMDASHBOARD.TABLE));
            qry.addSelectColumn(Column.getColumn(CRMDASHBOARD.TABLE, CRMDASHBOARD.DASHBOARDID));
            Criteria cri = new Criteria(Column.getColumn(CRMDASHBOARD.TABLE, CRMDASHBOARD.DASHBOARDNAME), new String[] {
                "Trend Dashboards",//no i18n
                "Sales Trend",//no i18n
                "Sales Follow-up Trend"//no i18n
            }, QueryConstants.IN);
            cri = cri.and(new Criteria(Column.getColumn(CRMDASHBOARD.TABLE, CRMDASHBOARD.CATEGORY), new int[] {
                0,
                4
            }, QueryConstants.IN));
            qry.setCriteria(cri);
            qry.setRange(new Range(0, 25));
            DataObject dObj = persistence.get(qry);
            if (dObj.isEmpty()) {
                String PATH_FOR_CONF = new StringBuilder(PropertyUtil.getProperty("server.dir")).append(File.separator).append("conf").append(File.separator).append("AdventNetCRMSFA").append(File.separator).toString(); // No I18N
                DataObject cvobj = Xml2DoConverter.transform(PATH_FOR_CONF + "Trend-Dashboard.xml"); //No I18N
                persistence.add(cvobj);
            }

            Row statsRow = CrmKeyValueUtil.getCrmKeyValueRow("AnomalyDetection"); //no i18n
            if (statsRow != null) {
                resultObj.put("status", status);
                resultObj.put("response", "Trend dash board already enabled<li>"); //no i18n
                return resultObj;
            } else {
                TimeZone fromTZ = OrgUtil.getOrgOrPersonalUserTimeZone();
                TimeZone toTZ = TimeZone.getDefault();
                Calendar cal = Calendar.getInstance();
                cal.setTimeZone(fromTZ);
                cal.setTime(new Date());
                cal.add(Calendar.DATE, 1);
                cal.set(Calendar.HOUR_OF_DAY, 0 + (int)(Math.random() * 5));
                cal.set(Calendar.MINUTE, 1 + (int)(Math.random() * 60));
                cal.set(Calendar.SECOND, 0);

                Timestamp executionTime = DateTimeUtils.convertDateTime(cal, fromTZ, toTZ);
                DataObject dObj2 = PersistenceCacheUtil.getPurePersistenceLiteHandle(zgId + "").constructDataObject();
                Row row = new Row(CRMKEYVALUE.TABLE);
                row.set(CRMKEYVALUE.KEYNAME, "AnomalyDetection"); //no i18n
                row.set(CRMKEYVALUE.VALUE, executionTime + "___" + fromTZ.getID());
                dObj2.addRow(row);
                dObj = PersistenceCacheUtil.getPurePersistenceLiteHandle(zgId + "").add(dObj2);
                statsRow = dObj.getFirstRow(CRMKEYVALUE.TABLE);
                Long jobId = (Long) statsRow.get(CRMKEYVALUE.KEYID);
                CrmJobBean jobDetails = new CrmJobBean(jobId, ZohoCRMScheduleConstants.CRMINTELLIGENCE_ANOMALY_CLASS, ZohoCRMScheduleConstants.CRM_INTELLIGENCE_PROCESS, executionTime);
                jobDetails.setRepetitionType(ZohoCRMScheduleConstants.DAILY);
                jobDetails.setRepetitionName(ZohoCRMScheduleConstants.CRMINTELLIGENCE_ANOMALY_REPETITION);
                jobDetails.setTransactionTimeout(-1);

                ZohoCRMSchedule.addCalendarJob(jobDetails);
            }
            resultObj.put("response", "Trend dash board enabled"); //no i18n
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }

