    public JSONObject customfields() throws JSONException { //###used
        try {
            String moduleFromReq = request.getParameter("module");
            if(moduleFromReq != null){
                modules = new String[]{moduleFromReq};
            }
            for (String module: modules) {
                if (module.equals(CrmModuleConstants.CALLS)) {
                    continue;
                }
                Long tabID = TabUtil.getTabIdByName(module);
                if(tabID!=null){
                SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMFIELD.TABLE));
                sq.addSelectColumn(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDID));
                sq.addSelectColumn(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.TABID));
                sq.addSelectColumn(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.COLUMNNAME));

                Criteria cr = new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.TABID), tabID, QueryConstants.EQUAL);
                cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.GENERATEDTYPE), 2, QueryConstants.EQUAL));
                cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDLABEL), "CFText", QueryConstants.NOT_EQUAL)); //no i18n
                cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDLABEL), "CFInteger", QueryConstants.NOT_EQUAL)); //no i18n
                cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDLABEL), "CFDecimal", QueryConstants.NOT_EQUAL)); //no i18n
                cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDLABEL), "CFPercent", QueryConstants.NOT_EQUAL)); //no i18n
                cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDLABEL), "CFDate", QueryConstants.NOT_EQUAL)); //no i18n
                cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDLABEL), "CFdateTime", QueryConstants.NOT_EQUAL)); //no i18n
                cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDLABEL), "CFPhone", QueryConstants.NOT_EQUAL)); //no i18n
                cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDLABEL), "CFPickList", QueryConstants.NOT_EQUAL)); //no i18n
                cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDLABEL), "CFMultiSelect_PickList", QueryConstants.NOT_EQUAL)); //no i18n
                cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDLABEL), "CFCheckbox", QueryConstants.NOT_EQUAL)); //no i18n
                cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDLABEL), "CFCurrency", QueryConstants.NOT_EQUAL)); //no i18n
                cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDLABEL), "CFEmail", QueryConstants.NOT_EQUAL)); //no i18n
                cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDLABEL), "CFURL", QueryConstants.NOT_EQUAL)); //no i18n
                cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDLABEL), "CFtextArea", QueryConstants.NOT_EQUAL)); //no i18n
                cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDLABEL), "CFLookup", QueryConstants.NOT_EQUAL)); //no i18n
                cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDLABEL), "CFLongInteger", QueryConstants.NOT_EQUAL)); //no i18n
                cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDLABEL), "CFAutoNumber", QueryConstants.NOT_EQUAL)); //no i18n
                //Avoid Deletion of ScoringRule Score Custom Fields 
                JSONArray srFieldIds = SRCrudUtil.getCustomFieldsData(module, null, false, null);
                srFieldIds = srFieldIds.getJSONArray(0);
                if(!srFieldIds.isEmpty())
                {
                	cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDID), srFieldIds.toList().toArray(), QueryConstants.NOT_IN)); 
                }
                
                String excludeFields = request.getParameter("excludeFields");
                if (excludeFields != null) {
                    for (String eachExcludeField: excludeFields.split(",")) {
                        cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDLABEL), eachExcludeField, QueryConstants.NOT_EQUAL));
                    }
                }
                sq.setCriteria(cr);
                sq.setRange(new Range(0, 500));

                DataObject dataObj = PersistenceCacheUtil.getNonCachePersistenceHandle().get(sq);
//                ZohoCRMBeanWT beanInstance = (ZohoCRMBeanWT) BeanUtil.lookup("ZohoCRMBeanWT");
                Long fieldId = null;
                @SuppressWarnings("rawtypes")
                Iterator r = dataObj.getRows(CRMFIELD.TABLE);
                while (r.hasNext()) {
                    Row ro = (Row) r.next();
                    fieldId = (Long) ro.get(CRMFIELD.FIELDID);

                    if(ro.get(CRMFIELD.SOURCE) !=null && ro.get(CRMFIELD.SOURCE).equals(CoreFieldConstants.SOURCE.CAMPAIGN_INTEGRATION_FIELD.getValue())){    //exclude campaigns module >> surveyInteg(default layout)
                        continue;
                    }

                    FieldUtil.validateNHideCustomField( module, fieldId, UserUtil.getCurrentUserId(), 1, false, false, false );
//                    beanInstance.deleteCustomField(fieldId, module, request);
                }
            }
            }
            modules = getModulesList();
            resultObj.put("response", "Extra custom fields deleted"); //no i18n
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }

