    public void enable_composesetting() {
    	try
		{
			 //api name system.email  type 2
	       	 
         	Criteria criteria = new Criteria( Column.getColumn( CRMSETTINGS.TABLE, CRMSETTINGS.API_NAME ), "system.emailcomposesetting", QueryConstants.EQUAL);	        
     	    criteria = criteria.and(new Criteria( Column.getColumn( CRMSETTINGS.TABLE, CRMSETTINGS.ELEMENT_TYPE ), 3, QueryConstants.EQUAL));
        	 
        	 //<CrmSettings ELEMENT_TYPE="3" SEQUENCE="8" PRESENCE="1" GENERATED_SOURCE="1" ELEMENT_ACTION="1" ELEMENT_ID="CrmSettings:ELEMENT_ID:191" 
        	 //ELEMENT_LABEL="Email Relay" API_NAME="system.emailrelay" PARENT_ID="CrmSettings:ELEMENT_ID:35" />
        		
        	Persistence per = PersistenceCacheUtil.getPurePersistenceLiteHandle();
        	
        	DataObject dbObj = per.get(CRMSETTINGS.TABLE, criteria);
   	    
   	    if(dbObj == null || dbObj.isEmpty()){
   	    	
   	 		DataObject dob = per.constructDataObject();
   	    				
   	    	Row row = new Row(CRMSETTINGS.TABLE);
   	    	row.set(CRMSETTINGS.ELEMENT_TYPE, 3);
   	    	row.set(CRMSETTINGS.SEQUENCE, 13);
   	    	row.set(CRMSETTINGS.GENERATED_SOURCE, 1);
   	    	row.set(CRMSETTINGS.ELEMENT_ACTION,1);
   	    	
   	    	Criteria criteria1 = new Criteria( Column.getColumn( CRMSETTINGS.TABLE, CRMSETTINGS.API_NAME ), "system.email", QueryConstants.EQUAL);	        
		    criteria1 = criteria1.and(new Criteria( Column.getColumn( CRMSETTINGS.TABLE, CRMSETTINGS.ELEMENT_TYPE ), 2, QueryConstants.EQUAL));

		    SelectQuery sq1 = new SelectQueryImpl( Table.getTable(CRMSETTINGS.TABLE) );
		    sq1.addSelectColumn(Column.getColumn(CRMSETTINGS.TABLE,CRMSETTINGS.ELEMENT_ID));  
		    sq1.setCriteria(criteria1);       
		    sq1.setRange( new Range(0,1) );
		        
		    DataObject dbObj1 = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(sq1);
		    
		    Row prow = dbObj1.getRow(CRMSETTINGS.TABLE);
		
		    long parentEntityId = (long) prow.get(CRMSETTINGS.ELEMENT_ID);
   	    	
   	    	row.set(CRMSETTINGS.PARENT_ID, parentEntityId);
   	    	row.set(CRMSETTINGS.ELEMENT_LABEL, "Email Compose Setting");			//No I18N
   	    	row.set(CRMSETTINGS.API_NAME, "system.emailcomposesetting");		//No I18N
   	    	
   	    	row.set(CRMSETTINGS.PRESENCE, 1);
   	    		
   	    	dob.addRow(row);
   	    				
   	    	per.add(dob);
   	    	
   	    }
			
		
		}
		catch(Exception e)
		{
			LOGGER.log(Level.SEVERE, "EmailComposeSetting reset page Exception", e);
		}
    }
    public JSONObject reset_emailparser() throws JSONException {
    	try {
    		//Delete all parser related configurations.
    		Criteria deleteCriteria = new Criteria(Column.getColumn(EASFEATUREDETAILS.TABLE, EASFEATUREDETAILS.FEATURE_NAME), EmailParserConstants.EMAILPARSER, QueryConstants.EQUAL);
    		PersistenceCacheUtil.deleteWithLimit(EASFEATUREDETAILS.TABLE, deleteCriteria, PersistenceCacheUtil.getPurePersistenceLiteHandle(), 1);
    		//Delete all parser related rules.
    		//Clear old EmailParser contents.
    		EmailParserDBPersistance.deleteOldEmailParserRuleContents();
    		//Delete all parser related rules.
    		deleteCriteria = new Criteria(Column.getColumn(CRMEMAILPARSERRULE.TABLE, CRMEMAILPARSERRULE.PARSING_TYPE), new Integer[] {1, 2}, QueryConstants.IN);
    		PersistenceCacheUtil.deleteWithLimit(CRMEMAILPARSERRULE.TABLE, deleteCriteria, PersistenceCacheUtil.getPurePersistenceLiteHandle(), 40);   	
    		//Delete all parser related emails.
    		Long receivedTime = System.currentTimeMillis();
			EmailParserDBPersistance.deleteEmails(receivedTime);
			//Delete schedulers if configured.
			Long jobId = CrmKeyValueUtil.getKeyIdByKeyName(EmailParserConstants.EMAILPARSER_STATS_JOBID, CRMKEYVALUE.TABLE);
			if(jobId != null) {
				ZohoCRMSchedule.deleteRepetitiveJobByJobID(jobId, ZohoCRMScheduleConstants.EMAIL_ANALYTICS_REPETITION);
				CrmKeyValueUtil.deleteCrmKeyValueByKeyName(EmailParserConstants.EMAILPARSER_STATS_JOBID, false);
			}
			LOGGER.log(Level.INFO," MAIL PARESR CLEANUP LOGS ::::::::::::::: Everything reset by user {0} for org {1} ::::::::: {2}", new Object[] { userId, zgId, receivedTime });
    	}catch (Exception e) {
    		status = false;
    		resultObj.put("response", e.toString());
		}
    	return resultObj;
    }
