	public JSONObject reNotifyMail() throws JSONException {
		try {
			String subject = request.getParameter("subject");// No I18N
			com.zoho.crm.mailagent.Authentication  authObj = MailAPIRouting.getAuthObject(zgId, zuId, false, null, true);
			MailAPI mailAPI = MailAPI.getInstance(authObj);
			HashMap<String, Object> configMap = MailAppsUtil.getConfigMap(userId);
			String accountId = (String) configMap.get("Mail360_Account_ID");
			if (authObj.isOrgOauth()) {
				authObj.setAddSoType(true);
				authObj.setSoType(String.valueOf(IAMServiceOrg.getType()));
				authObj.setZid(String.valueOf(zgId));
			}
			JSONArray result = mailAPI.getAppDataSearchResults(accountId, "subject=(" + subject + ")", "", new String[] { "0", "25" }, null);// NO I18N
			LOGGER.log(Level.INFO, "result {0}", new Object[] { result });
			int length = result.length();
			JSONArray messageInfoArray = new JSONArray();
			for (int i = 0; i < length; i++) {
				JSONObject resObject = result.getJSONObject(i);
				if (resObject.has("resultMsgIds")) {
					messageInfoArray = resObject.getJSONArray("resultMsgIds"); // NO I18N
					break;
				}

			}
			if(messageInfoArray ==null || messageInfoArray.isEmpty())
			{
				messageInfoArray = result;
			}
			length = messageInfoArray.length();
			JSONArray allmessageIdsList = new JSONArray();

			if (length > 0) {
				for (int i = 0; i < length; i++) {
					JSONObject resObject = messageInfoArray.getJSONObject(i);
					String messageId = "";
					if (resObject.has("M")) {
						messageId = resObject.getString("M");
					} else if (resObject.has("messageId")) {
						messageId = resObject.getString("messageId");
					}
					if (!messageId.isEmpty()) {
						allmessageIdsList.put(messageId);
					}
				}
			}
			String messageId = (String) allmessageIdsList.get(0);
			LOGGER.log(Level.INFO, "messageId {0}", new Object[] { messageId });
			AppDataAPI appObj = AppDataAPI.getInstance(authObj);
			appObj.deleteAppData(Long.valueOf(accountId), messageId);
			LOGGER.log(Level.INFO, "App data deleted");
			ResyncBean bean = new ResyncBean();
			bean.setAccId(Long.valueOf(accountId));
			bean.setFromMsgId(Long.valueOf(messageId));
			bean.setToMsgId(Long.valueOf(messageId));
			JSONObject res = MailAPI.getInstance(authObj).getNotificationData(accountId, messageId);
			LOGGER.log(Level.INFO, "response {0}", new Object[] { res });
			res = res.getJSONObject("data");
			JSONObject appData = new JSONObject();
			appData.put("ZGID", zgId+"");
			appData.put("PRODUCT_ID", "CR");
			res.put("APPDATA", appData);
			res.put("event", "newMail");
			res.put("module", "mail");
			
			LOGGER.log(Level.INFO, "response {0}", new Object[] { res });
			MailAppsProducer.produceToZMQueueByJCL(res);
			MailAppsAdminTool.updateRenotifyMailId(messageId,zgId+"");
		} catch (Exception e) {
			status = false;
             LOGGER.log(Level.WARNING, "Exception in reNotifyMail:",e);
			resultObj.put("response", e.toString());
		}
		resultObj.put("status", status);
		return resultObj;
	}
