    public JSONObject reset_compose_settings() throws JSONException {
        try {
        	String userIdInParam = request.getParameter("user_id");
        	String type = request.getParameter("type");
        	Long userIdInParamLong = null;
        	try {
        		userIdInParamLong = Long.parseLong(userIdInParam);
			} catch (Exception e) {
				userIdInParamLong = userId;
			}
        	LOGGER.log(Level.INFO, "user id from the param {0}", userIdInParam);
        	LOGGER.log(Level.INFO, "user id after parse {0}", userIdInParamLong);
        	LOGGER.log(Level.INFO, "type in the param{0}", type);
        	Criteria cr = new Criteria(Column.getColumn(CRMSIGNATURE.TABLE,CRMSIGNATURE.USERID),userIdInParamLong,QueryConstants.EQUAL);
            PersistenceCacheUtil.getPurePersistenceLiteHandle(zgId + "").delete(cr);
            Criteria newCr = new Criteria(Column.getColumn(CRMMAILUSERCONFIG.TABLE, CRMMAILUSERCONFIG.USERID), userIdInParamLong, QueryConstants.EQUAL);

        	DataObject mailDetailsObj =  (DataObject) ZMailConfigUtil.getCrmMailUserConfigCachedDO().clone();
	    	Row mailDetailsRow = mailDetailsObj.getRow(CRMMAILUSERCONFIG.TABLE,newCr);
            JSONObject mailUserEmail = new JSONObject();
            JSONObject otherMailInfo =  new JSONObject();
      	    if(mailDetailsRow!=null && mailDetailsRow.get(CRMMAILUSERCONFIG.OTHER_MAIL_INFO)!=null)
	    	{
                 otherMailInfo =  JsonUtil.parseStringToJSON((String)mailDetailsRow.get(CRMMAILUSERCONFIG.OTHER_MAIL_INFO));
                 Set<String> allTypes = Stream.of(ComposeSettingType.values())
                		 .map(ComposeSettingType :: getType)
                		 .collect(Collectors.toSet());
                 if (!allTypes.contains(type)) {
                	 type = "default";// NO I18N
                 }
                 ComposeSettingType dbType = ComposeSettingType.getByValue(type);
                 LOGGER.log(Level.INFO, "after change type in the param{0}", type);
                if(otherMailInfo.has(dbType.getDBType()))
                 {
                	 otherMailInfo.remove(dbType.getDBType());
                	mailDetailsRow.set(CRMMAILUSERCONFIG.OTHER_MAIL_INFO, otherMailInfo.toString());
                     mailDetailsObj.updateRow(mailDetailsRow);
                 }
                if(otherMailInfo.has(ComposeSettingConstants.CUSTOM_FONT_DETAILS)) 
                {
                    otherMailInfo.remove(ComposeSettingConstants.CUSTOM_FONT_DETAILS);
                    mailDetailsRow.set(CRMMAILUSERCONFIG.OTHER_MAIL_INFO, otherMailInfo.toString());
                    mailDetailsObj.updateRow(mailDetailsRow);
                }
                PersistenceCacheUtil.getPurePersistenceLiteHandle().update(mailDetailsObj);

	    	}
            resultObj.put("response", "success");
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }
