    public JSONObject zfs_status() throws JSONException { // ###used
    	try {
    		boolean response=false; // true if zfs is down
    		if(check_dependency("zfs")) {
    			String filePath=new StringBuilder(128).append("/TestPath/").append(System.currentTimeMillis()).append(".txt").toString();//NO I18N
    			String zgid=OrgUtil.getCurrentZGID()+"";
    			BufferedOutputStream bouts=ZFSUtil.storeSystemFileIntoZFS(zgid,filePath);
    			if(bouts!=null) {
    				bouts.write("test file".getBytes());//NO I18N
    				bouts.close();
    				ZFSUtil.deleteSystemFileFromZFS(zgid,filePath);
    			}else {
    				response=true;
    			}
        		update_dependency_status("zfs",!response);//NO I18N
    		}
    		resultObj.put("response",response);
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        LOGGER.log(Level.INFO, "ZFS_STATUS ::: ".concat(resultObj.toString()));
        return resultObj;
    }

    /**
     * This method is used to check dependency status.
     * @param service_name
     * @return true if need to check status else returns false if dependency is up
     */
    private static boolean check_dependency(String service_name) {
    	Properties properties=dependency_status.get(service_name);
    	Boolean status=(Boolean)properties.get("response");//NO I18N
    	if(status==null || status){
    		long current_time=System.currentTimeMillis();
    		Long last_sync_time=(Long)properties.getOrDefault("sync_time",0l);//NO I18N
    		Long refresh_time=(Long)properties.getOrDefault("refresh_time",0l);//NO I18N
    		if(current_time<(last_sync_time+refresh_time)){
    			LOGGER.log(Level.INFO,service_name.concat(" is up"));
    			return false;
    		}
    	}
    	return true;
    }
 
    /**
     * This method is used to update the current status of dependency service.
     * @param service_name
     * @param status - true if service is up
     */
    private static void update_dependency_status(String service_name,boolean status) {
    	synchronized (DEPENDENCY_LOCK) {
    		Properties properties=dependency_status.get(service_name);
    		properties.put("response",status);
    		properties.put("sync_time",System.currentTimeMillis());//NO I18N
    	}
    }
    
