    /**
     *
     * @return
     * @throws JSONException
     */
    public JSONObject delete_layout() throws JSONException
    {
    	status = false;
    	try
    	{
    		String layoutId = request.getParameter("layout_id");
    		String transferToLayout = request.getParameter("transfer_to_layout");
    		String module = request.getParameter("module");

    		if(module == null)
    		{
    			resultObj.put("response", "mandatory param module not sent.");
    		}
    		else if(transferToLayout == null)
    		{
    			resultObj.put("response", "mandatory param transfer to layout not sent.");
    		}
    		else if(layoutId == null)
    		{
    			resultObj.put("response", "mandatory param layout id not sent.");
    		}
    		else
    		{
    			Long layoutToBeDeleted = Long.parseLong(layoutId);
        		Long transferToLayoutId = Long.parseLong(transferToLayout);
        		Long tabId = TabUtil.getTabIdByName(module);

        		if(tabId == null)
        		{
        			resultObj.put("response", "Invalid module sent.");
        		}
        		else
        		{
        			Long masterLayoutId = PageLayoutUtil.getMasterLayoutIdForTabId(tabId);

            		if(masterLayoutId.equals(layoutToBeDeleted))
            		{
            			resultObj.put("response", "Cannot delete Standard or master layout.");
            		}
            		else
            		{
            			DataObject dataObj = PageLayoutUtil.getAllLayoutCachedDO(tabId);
                    	Criteria layoutCriteria = new Criteria(Column.getColumn(CRMPAGELAYOUT.TABLE, CRMPAGELAYOUT.LAYOUTID), layoutToBeDeleted, QueryConstants.EQUAL);
                    	layoutCriteria = layoutCriteria.and(new Criteria(Column.getColumn(CRMPAGELAYOUT.TABLE, CRMPAGELAYOUT.SOURCE), "12", QueryConstants.NOT_EQUAL));

                    	Iterator<Row> layoutIterator = dataObj.getRows(CRMPAGELAYOUT.TABLE, layoutCriteria);

                    	if(layoutIterator.hasNext())
                    	{
                    		resultObj = resetConf.delete_layout(layoutToBeDeleted, transferToLayoutId, tabId);

                    		status = resultObj.getBoolean("status");	//No i18N
                    	}
                    	else
                    	{
                    		resultObj.put("response", "Invalid layout sent.");
                    	}
            		}
        		}
    		}
    	}
    	catch(Exception e)
    	{
    		resultObj.put("status", false); //no i18n
    		resultObj.put("response", e.getMessage()); //no i18n
    	}

    	resultObj.put("status", status);
    	return resultObj;
    }

