    public JSONObject bulk_delete_roles() throws JSONException {
    	 try {
    	    @SuppressWarnings("rawtypes")
    	    Map roles = RoleUtil.getAllRolesMap(null,true);
    	    List<Long> roleIds = new ArrayList<Long>();
    	    List<Role> deleteRoles = new ArrayList<Role>();
    	    for (Object role: roles.keySet()) {
    	        Long roleId = Long.parseLong("" + role);
    	        roleIds.add(roleId);
    	    }
    	    SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMSCHEDULEDJOBS.TABLE));
    	    Criteria cr1 = new Criteria(Column.getColumn(CRMSCHEDULEDJOBS.TABLE,CRMSCHEDULEDJOBS.ACTION ),"ROLE_UPDATE_AND_DELETE",QueryConstants.EQUAL);
    	    Criteria cr = cr1.and(new Criteria(Column.getColumn(CRMSCHEDULEDJOBS.TABLE,CRMSCHEDULEDJOBS.STATUS ),ScheduledJobDetails.Status.FAILED.getValue(),QueryConstants.NOT_EQUAL));
    	    sq.setCriteria(cr);
    	    sq.addSelectColumn(Column.getColumn(null, "*"));
    	    DataObject dob = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(sq);
    	    List<Long> scheduledRoles = new ArrayList<Long>();
    	    Iterator<Row> iter = dob.getRows(CRMSCHEDULEDJOBS.TABLE);
    	    while(iter.hasNext()){
    	        Row row = iter.next();
    	        String actionStr = row.get(CRMSCHEDULEDJOBS.ACTIONINFO).toString();
    	        JSONObject actionInfo = new JSONObject(actionStr);
    	        String action = (String) actionInfo.get("action");
    	        if(action.equals("ROLEDELETE")) {
    	            Long id = Long.valueOf(actionInfo.get("roleId").toString());
    	            if(roles.containsKey(id)){
    	                scheduledRoles.add(id);
    	            }
    	        }
    	        if(action.equals("ROLEDELETE_IN_BULK"))
    	        {
    	            JSONArray roleArr = (JSONArray) actionInfo.get("roles");
    	            int length = roleArr.length();
    	            for(int itr = 0; itr < length; itr++)
    	            {
    	                JSONObject roleJson = roleArr.getJSONObject(itr);
    	                Long roleId = roleJson.getLong("roleId");	//no i18n
    	                if(roles.containsKey(roleId))
    	                {
    	                    scheduledRoles.add(roleId);
    	                }
    	            }
    	        }
    	    }
    	    Long adminRoleId=RoleUtil.getAdminRoleId();
    	    DataObject roleDO = RoleUtil.getCachedRoleDo(null,false,true);
    	    Map<Long, RoleContext> roleIdVsCarrier = new HashMap<Long, RoleContext>();
    		List<Long> rolesInDeletion = new ArrayList<Long>();
			List<Long> rolesInTransfer = new ArrayList<Long>();
    	    HashMap<Long , List<Long>> roleVsSubRoles = RoleUtil.getRoleVsSubRolesAsMap(roleIds, null, String.valueOf(zgId));
    	    CrmRoleContext roleCarrierObj = CrmRoleContext.getInstance();
    	    ListIterator<Long> roleItr = roleIds.listIterator();
    	    while (roleItr.hasNext()) {
    	    	Long roleId = roleItr.next();
    	        String roleName = (String) roles.get(roleId);
    	        CrmRoleContext roleCarrier = CrmRoleContext.getInstance();
    	        if(roleId.equals(adminRoleId)){
    	            Role newRole = (Role) ModelUtil.getInstance(Role.class);
    	            newRole.setRoleid(roleId);
    	            newRole.setRolename("CEO");//no i18n
    	            newRole.setDescription("");//no i18n
    	            newRole.setcustomized(false);
    	            newRole.setIsPeerRoledSEnabled(true);
    	            newRole.setFcManagerId(null);
    	            RoleUtil.updateRole(newRole, roleCarrier);
    	            roleName ="CEO";//no i18n
    	            roleItr.remove();
    	        }
    	        if (!(roleName.equals("CEO") || roleName.equals("Manager")) && !scheduledRoles.contains(roleId)) {
    	            Row row = roleDO.getRow(CRMROLE.TABLE,new Criteria(Column.getColumn(CRMROLE.TABLE, CRMROLE.ROLEID),roleId,QueryConstants.EQUAL));
    	            if(row == null) {
    	                LOGGER.log(Level.WARNING, "Role Trying to Delete is not available Id - {0}", new Object[] {roleId});
    	                roleItr.remove();
    	            }
    	            else {
        	            Role roleDetail = RoleUtil.convertToRolePOJO(row);
    	                roleCarrier.setTransferToId(adminRoleId);
    	                roleCarrier.setCurrentUserId(userId);
    	                roleCarrier.setChildRoleIds(roleVsSubRoles.get(roleId));
    	                deleteRoles.add(roleDetail);
    	                roleIdVsCarrier.put(roleId, (RoleContext)roleCarrier);
    	            }
    	        }
    	    }
//    	    for(Role role : deleteRoles)
//    		{
//    			RoleContext roleCarrier = roleIdVsCarrier.get(role.getRoleid());
//    			roleIdVsTransferToId.put(role.getRoleid(), roleCarrier.getTransferToId());
//    		}
//    		RoleUtil.updateReportingToForChildRolesBulk(roleIdVsTransferToId, userId);
//    		RoleUtil.updateRoleType(roleIds, RoleType.DELETEINPROGRESS, userId);
//    	    RoleUtil.deleteRole(deleteRoles, roleIdVsCarrier);
//    	    for (Long roleid : roleIds) {
//    	        CrmAllowedIPsUtil.deleteAuthDomainsOfSource(CrmAllowedIPs.allowedIpsTypes.getRestrictToType("roles").getVal(), roleid); // No I18n
//    	    }
			RoleUtil.transferAndDeleteRole(deleteRoles, roleIds, userId , String.valueOf(zgId), remoteAddress, rolesInDeletion, rolesInTransfer, roleIdVsCarrier, roleCarrierObj);
    	    roles = RoleUtil.getAllRolesMap();
    	    if(roles.size()==2){
    	        resultObj.put("response","all roles deleted as expected "); //No I18N
    	    }else{
    	        status = false;
    	        resultObj.put("response","all roles are not deleted as expected : "+roles.size()+" , "+roles); //No I18N
    	    }
    	} catch (Exception e) {
    	    status = false;
    	    resultObj.put("response", e.toString());
    	}
    	resultObj.put("status", status);
    	return resultObj;
    }
    
    public JSONObject delete_roles() throws JSONException { // ###used
        try {
        	@SuppressWarnings("rawtypes")
            Map roles = RoleUtil.getAllRolesMap(null,true);
        	//Added to remove unwanted role temporarily
        	SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMSCHEDULEDJOBS.TABLE));
        	Criteria cr1 = new Criteria(Column.getColumn(CRMSCHEDULEDJOBS.TABLE,CRMSCHEDULEDJOBS.ACTION ),"ROLE_UPDATE_AND_DELETE",QueryConstants.EQUAL);
        	Criteria cr = cr1.and(new Criteria(Column.getColumn(CRMSCHEDULEDJOBS.TABLE,CRMSCHEDULEDJOBS.STATUS ),ScheduledJobDetails.Status.FAILED.getValue(),QueryConstants.NOT_EQUAL));
        	sq.setCriteria(cr);
        	sq.addSelectColumn(Column.getColumn(null, "*"));
        	DataObject dob = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(sq);
        	List<Long> scheduledRoles = new ArrayList<Long>();
        	Iterator<Row> iter = dob.getRows(CRMSCHEDULEDJOBS.TABLE);
    		while(iter.hasNext()){
    			Row row = iter.next();
    			String actionStr = row.get(CRMSCHEDULEDJOBS.ACTIONINFO).toString();
    			JSONObject actionInfo = new JSONObject(actionStr);
    			String action = (String) actionInfo.get("action");
    			if(action.equals("ROLEDELETE")) {
    				Long id = Long.valueOf(actionInfo.get("roleId").toString());
    				if(roles.containsKey(id)){
    					scheduledRoles.add(id);
    				}
    			}
    			if(action.equals("ROLEDELETE_IN_BULK"))
    			{
					JSONArray roleArr = (JSONArray) actionInfo.get("roles");
					int length = roleArr.length();
					for(int itr = 0; itr < length; itr++)
					{
						JSONObject roleJson = roleArr.getJSONObject(itr);
						Long roleId = roleJson.getLong("roleId");	//no i18n
						if(roles.containsKey(roleId))
						{
							scheduledRoles.add(roleId);
						}
					}
    			}
    		}
//            Long mangerId = null;
//            for (Object role: roles.keySet()) {
//                String roleName = (String) roles.get(role);
//                Long roleId = Long.parseLong("" + role);
//                if (roleName.equals("Manager")) {
//                    mangerId = Long.parseLong("" + roleId);
//                }
//            }
            Long adminRoleId=RoleUtil.getAdminRoleId();
            for (Object role: roles.keySet()) {
                String roleName = (String) roles.get(role);
                Long roleId = Long.parseLong("" + role);
                CrmRoleContext roleCarrier = CrmRoleContext.getInstance();
                roleCarrier.setExtraSchedulerInfo("isUI",false); //No I18N
                if(roleId.equals(adminRoleId)){
                    roleCarrier.setExtraSchedulerInfo("isDelForecast",false); //No I18N
                	Role newRole = (Role) ModelUtil.getInstance(Role.class);
                	newRole.setRoleid(roleId);
                	newRole.setRolename("CEO");//no i18n
                	newRole.setDescription("");//no i18n
                	newRole.setcustomized(false);
                	newRole.setIsPeerRoledSEnabled(true);
                	newRole.setFcManagerId(null);
                	RoleUtil.updateRole(newRole, roleCarrier);
            		roleName ="CEO";//no i18n
                }
                if (!(roleName.equals("CEO") || roleName.equals("Manager")) && !scheduledRoles.contains(roleId)) {
                    roleCarrier.setExtraSchedulerInfo("isDelForecast",true); //No I18N
                    RoleUtil.transferAndDeleteRole(roleId, adminRoleId, roleCarrier, userId, null, remoteAddress + "", null);// No I18n
                    CrmAllowedIPsUtil.deleteAuthDomainsOfSource(CrmAllowedIPs.allowedIpsTypes.getRestrictToType("roles").getVal(), roleId); // No I18n
                }
            }
            roles = RoleUtil.getAllRolesMap();
            if(roles.size()==2){
            	resultObj.put("response","all roles deleted as expected "); //No I18N
            }else{
            	status = false;
            	resultObj.put("response","all roles are not deleted as expected : "+roles.size()+" , "+roles.toString()); //No I18N
            }
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }
    public JSONObject rerun_delete_profiles() throws JSONException {
    	try {
    		Map<Long,Profile> profilesMap = new HashMap<Long,Profile>();
            Long stdProfId = ProfileUtil.getProfileIdByProfileName("Standard");//no I18N
    		SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMPROFILE.TABLE));
            Criteria crForDel = new Criteria(Column.getColumn(CRMPROFILE.TABLE, CRMPROFILE.TYPE), ProfileUtil.deleteProfileTypes, QueryConstants.EQUAL);
    		sq.addSelectColumn(Column.getColumn(null,"*"));
    		sq.setCriteria(crForDel);
    		DOIterator doItr = new DOIterator(PersistenceCacheUtil.getPurePersistenceLiteHandle(), sq, 1000, true);
    		DataObject dObj = null;
    		while(doItr.hasNext()) {
    		dObj = doItr.next();
    		if(!dObj.isEmpty())
    		{
    			Iterator<Row> itr = dObj.getRows(CRMPROFILE.TABLE);
    			while (itr.hasNext()){
    				Row row = (Row)itr.next();
    				Profile profileObj = new Profile();
    				profileObj.setProfileId((Long)row.get(CRMPROFILE.PROFILEID));
    				profileObj.setProfileName((String)row.get(CRMPROFILE.PROFILENAME));
    				profileObj.setCategory((Boolean)row.get(CRMPROFILE.CATEGORY));
    				profileObj.setSysRefName((String)row.get(CRMPROFILE.SYS_REF_NAME));
    				profileObj.setDescription((String)row.get(CRMPROFILE.DESCRIPTION));
                    profileObj.setSource((Integer)row.get(CRMPROFILE.SOURCE));
                    profileObj.setType(null);
                    ProfileUtil.updateProfileType(profileObj.getProfileId(),null);
    				profilesMap.put((Long)row.get(CRMPROFILE.PROFILEID),profileObj);
    			}
    		}
    		}
    		Set<Long> nonUserRoleProfileIds = new HashSet<Long>();
    		for(Long profileId : profilesMap.keySet()){
    			List<Long> userIds = ProfileUtil.getUsersListByProfileId(profileId);
    			if(userIds.size() != 0) {
    			for(Long userId : userIds) {
    			Long roleId = RoleUtil.getRoleIdFromUserId(userId);
    			if(roleId != null) {
                Profile profileObj = profilesMap.get(profileId);
                IProfileContext profileCarrier = IProfileContext.getInstance();
                Long zgid = OrgUtil.getCurrentZGID();
                profileCarrier.setTransferToId(stdProfId);
                ProfileUtil profileUtil = (ProfileUtil) ScopedAccess.getInstance(ProfileUtil.class, zgId.toString(), TransactionType.REQUIRED);
    			profileUtil.validateAndDeleteProfile(profileObj,profileCarrier);
    			 }
    			else {
    				nonUserRoleProfileIds.add(profileId);
    			}
    			}
            }
    		else
    			nonUserRoleProfileIds.add(profileId);
    		}
    		Criteria crToDel = new Criteria(Column.getColumn(CRMPROFILE.TABLE, CRMPROFILE.PROFILEID),nonUserRoleProfileIds.toArray(),QueryConstants.IN);
    		PersistenceCacheUtil.getPurePersistenceLiteHandle().delete(crToDel);
    		resultObj.put("response","Profiles Deleted Successfully");
    	}
    	catch(Exception e) {
    		status = false;
    		resultObj.put("response" , e.toString());
    	}
    	resultObj.put("status", status);
    	return resultObj;
        }
    
    public JSONObject rerun_update_permisssion(List<String> profileNames,String permissionName) throws Exception{
    	try
    	{
    		LinkedHashMap<Long,String> profileIdsVsNames = ProfileUtil.getProfileIdsVsNamesByProfileNames(profileNames);
    		Iterator itr = profileIdsVsNames.entrySet().iterator();
    		List<Long> profileIds = new ArrayList<Long>();
    		while(itr.hasNext()) {
    			Map.Entry profileIdVsNameItr = (Entry)itr.next();
    			profileIds.add((Long)profileIdVsNameItr.getKey());
    		}
    		Long permissionId = ProfileUtil.getPermissionIdByName(permissionName);
    		ProfileUtil.enablePermissionForProfile(profileIds,permissionId);
    		resultObj.put("reponse", "Permissions Updated Successfully");
    	}
    	catch(Exception e)
    	{
    		status = false;
    		resultObj.put("response", e.toString());
    	}
    	resultObj.put("status", status);
    	return resultObj;
    }
