    public JSONObject delete_sharingrules() throws JSONException { // ###used
        try {
      		Set<Long> tabIds=new HashSet<Long>();
            DataObject dbObj = SharingRuleUtil.getSharingRulesDO();
            @SuppressWarnings("unchecked")
            Iterator < Row > srIter = dbObj.getRows(CRMSHARINGRULES.TABLE);
            IDataSharingRuleContext dataSharingRuleCarrier = IDataSharingRuleContext.getInstance();
    		dataSharingRuleCarrier.setParentScopeId(zgId);
    		dataSharingRuleCarrier.setOperationSource(OperationSource.UI);
    		dataSharingRuleCarrier.setSchedulerNeeded(false);
    		dataSharingRuleCarrier.setCurrentUserId(userId);
    		IDataSharingRuleService datasharingService = IDataSharingRuleService.getInstacne();
            while (srIter.hasNext()) {
                Row eachRule = srIter.next();
                Long id = (Long) eachRule.get(CRMSHARINGRULES.SHARINGRULEID);
                tabIds.add((Long)eachRule.get(CRMSHARINGRULES.TABID));
                SharingRule sharingRule = new SharingRule();
                sharingRule.setQueryId( (Long) eachRule.get(CRMSHARINGRULES.QUERYID));
                sharingRule.setSharingruleId((Long) eachRule.get(CRMSHARINGRULES.SHARINGRULEID));
                SharingRuleDBService.getInstance().deleteSharingRule(sharingRule);
            }
            dbObj = SharingRuleUtil.getSharingRulesDO();
            if(dbObj.isEmpty()) {
             	 for(Long tabId : tabIds)
             		 datasharingService.reRunRules(tabId, dataSharingRuleCarrier);
           }
            srIter = dbObj.getRows(CRMSHARINGRULES.TABLE);
            String res = "";
            if (srIter.hasNext()) {
            	while (srIter.hasNext()) {
	            	Row eachRule = srIter.next();
	            	Long id = (Long) eachRule.get(CRMSHARINGRULES.SHARINGRULEID);
	            	res = res +"Sharing Rule not deleted "+id;//no i18n
            	}
            }
            if(res.equals("")){
            	resultObj.put("response", "All sharing rules deleted "+res);
            }else{
            	status = false;
            	resultObj.put("response", "All sharing rules are not deleted "+res);
            }
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }

    public JSONObject reset_default_permission() throws JSONException { // ###used
        try {
            String moduleFromReq = request.getParameter("module");
            if(moduleFromReq != null){
                modules = new String[]{moduleFromReq};
            }
            for (String module: modulesC) {
                Long tabId = TabUtil.getTabIdByName(module);
                if(tabId!=null){
                if (module.equals(CrmModuleConstants.PRODUCTS) || module.equals(CrmModuleConstants.SERVICES)) {
                    SharingRuleUtil.updateOrgDefaultPermission(tabId, 2, userId,CrmClientPortalUserTypes.getSelectedPublicModulesInPortalsAsIdVsDisplayName());
                } else if(module.equals(CrmModuleConstants.EMAILS))
                {
                	SharingRuleUtil.updateOrgDefaultPermission(tabId, 3, userId, CrmClientPortalUserTypes.getSelectedPublicModulesInPortalsAsIdVsDisplayName());
                } else {
                    SharingRuleUtil.updateOrgDefaultPermission(tabId, 1, userId,CrmClientPortalUserTypes.getSelectedPublicModulesInPortalsAsIdVsDisplayName());
                }
                }
            }
            modules = getModulesList();
            resultObj.put("response", "All Module default permissions reset");
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }

