    public JSONObject updateUserLocaleinIAM() throws JSONException { // ###used

    	try {
        	CrmUser user = new CrmUser(userId);
        	user = CrmUserFactory.getService().getBean(null, user);

    		User iamUser = UserUtil.getIAMUserByZUID(user.getZuid());
            if(iamUser == null) {
            	LOGGER.log(Level.WARNING,"iam user is null for the given user id {0} zuid {1}" , new Object[]{userId,user.getZuid()});
                status = false;
                resultObj.put("response", new StringBuilder().append("iam user is null for the given user id ").append(userId).append(" zuid ").append(user.getZuid()).toString());
            }else{
            	LOGGER.log(Level.INFO,"update ::: language before update in IAM ::: {0} ::: country code in IAM ::: {1} ::: lang variant {2} " , new Object[]{iamUser.getLanguage(),iamUser.getCountry(),iamUser.getLanguageVariant()});
        		UserAPI userapi = CoreIAMUtil.getIAMProxy().getUserAPI();
        		String country_code =  request.getParameter("country")==null || "".equals(request.getParameter("country")) ? iamUser.getCountry() : request.getParameter("country");
        		String language =  request.getParameter("language")==null || "".equals(request.getParameter("language")) ? iamUser.getLanguageWithVariant() : request.getParameter("language");
        		userapi.changeLocale( user.getZuid(), country_code, language, iamUser.getTimezone() );
        		iamUser = UserUtil.getIAMUserByZUID(user.getZuid());
            	LOGGER.log(Level.INFO,"update ::: language after  update in IAM ::: {0} ::: country code in IAM ::: {1} ::: lang variant {2} " , new Object[]{iamUser.getLanguage(),iamUser.getCountry(),iamUser.getLanguageVariant()});	
        		resultObj.put("response", "User details updated in IAM");
            }
    	} catch (Exception e) {
    		LOGGER.log(Level.WARNING, "updateUserLocaleinIAM:",e);
            status = false;
            resultObj.put("response", e.toString());
    	}
        resultObj.put("status", status);
        return resultObj;
    }

