    public JSONObject deleteHomepageComponents() throws JSONException { // ###used
        try {
              JSONArray jsonArray2 = HomePageLayoutUtil.getAllCustomHomePageDetails(userId,currentUserLocale);
              for (int i = 0; i < jsonArray2.length(); i++) {
                  JSONObject obj = jsonArray2.getJSONObject(i);
                  Long customizationId = Long.parseLong(obj.get("customizationId") + "");
                  HomePageLayoutUtil.deleteCustomHomePage(userId, customizationId);
              }
              jsonArray2 = HomePageLayoutUtil.getAllCustomHomePageDetails(userId,currentUserLocale);


              Long standardHomePageId = HomePageLayoutUtil.getStandardCustomHomePageId() ;
              if(standardHomePageId != null)
              {
              		 for (int i = 0; i < jsonArray2.length(); i++)
              		  {
                 		 JSONObject obj = jsonArray2.getJSONObject(i);
                	     Long customizationId = Long.parseLong(obj.get("customizationId") + "");
                		  if (standardHomePageId.equals(customizationId))
                		  {
                			  jsonArray2.remove(i) ;
                			  i = i-1 ;
                		  }
                	  }
              }
              if(jsonArray2.length()==0){
            	  resultObj.put("response","home page componenets deleted"); //No I18N
              }else{
            	  status = false;
            	  resultObj.put("response","home page componenets not deleted : "+jsonArray2.toString()); //No I18N
              }
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }

    public JSONObject resetUserHomepage() throws JSONException { // ###used
        try {
              JSONArray jsonArray = HomePageLayoutUtil.getAllLayouts(userId);
              for (int i = 0; i < jsonArray.length(); i++) {
                  JSONObject obj = jsonArray.getJSONObject(i);
                  Long layoutId = Long.parseLong(obj.get("layoutId") + "");
                  String layoutName = obj.get("layoutName").toString();

                  Integer colspan = null ;
                  if( obj.has("colspan") && obj.get("colspan") != null )
                  {
                	  colspan = (Integer)obj.get("colspan") ;
                  }

                  if( ! ( colspan != null && colspan.intValue() == 5) ) // default layouts has colspan '5' .
                  {
                  		HomePageLayoutUtil.deleteLayout(layoutId,userId, null);
                  }

                  /*
                  if (!layoutName.equals("Open Tasks") && !layoutName.equals("Todays Leads") && !layoutName.equals("Closing This Month") && !layoutName.equals("Pipeline by Stage")) {
                       HomePageLayoutUtil.deleteLayout(layoutId,userId, null);
                  }
                  */
              }
            resultObj.put("response", "success");
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }
