    public JSONObject delete_groups() throws JSONException { // ###used
        try {
            @SuppressWarnings("rawtypes")
            Map groups = GroupUtil.getAllPublicGroupsMap();
            for (Object eachGrp: groups.keySet()) {
                Long gid = (Long) eachGrp;
                Set<Long> groupUsersBeforeDelete = GroupUtil.getUseridsByGroupid(gid);
//                GroupUtil.deleteGroup(gid, userId);
            	Group groupMeta = new Group();
            	GroupContext groupCarrier = new GroupContextImpl();
				groupMeta.setUserId(userId);
				groupMeta.setGroupid(gid);
				groupCarrier.setUserIdsBeforeEvent(groupUsersBeforeDelete);
//				groupMeta.setRemoteAddress(remoteAddr);
//				groupMeta.setZgId(OrgUtil.getCurrentZGID().toString());
//				groupMeta.setUserIdsBeforeEvent(groupUsersBeforeDelete);
				GroupUtil groupUtilBean = (GroupUtil)ScopedAccess.getInstance(GroupUtil.class, OrgUtil.getCurrentZGID().toString(), TransactionType.REQUIRED);
				groupUtilBean.deleteGroup(groupMeta, groupCarrier);
                CrmAllowedIPsUtil.deleteAuthDomainsOfSource(CrmAllowedIPs.allowedIpsTypes.getRestrictToType("groups").getVal(), gid); // No I18n
            }
            groups = GroupUtil.getAllPublicGroupsMap();
            if(groups.size()==0){
            	resultObj.put("response","Groups deleted"); //No I18N
            }else{
            	status = false;
            	resultObj.put("response","Groups not deleted : "+groups.toString()); //No I18N
            }
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }

    public JSONObject deleteDataBackupRow() throws JSONException { // ###used
        try {
            DataObject dObj = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(CRMDATABACKUPINFO.TABLE, (Criteria) null);
            if (!dObj.isEmpty()) {
                dObj.deleteRows(CRMDATABACKUPINFO.TABLE, (Criteria) null);
                PersistenceCacheUtil.getPurePersistenceLiteHandle().update(dObj);
            }

            dObj = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(CRMDATABACKUPINFO.TABLE, (Criteria) null);
            if (!dObj.isEmpty()) {
            	status = false;
            	resultObj.put("response","Data Backup Row not Deleted : "+dObj.toString()); //No I18N
            }else{
            	resultObj.put("response","Data Backup Row Deleted");//No I18N
            }

            Long zgid = OrgUtil.getCurrentZGID();
            if(zgid != null)
            {
            	try
            	{
            		String basePath = new StringBuilder(ExportSchedulerConstants.ZFS_FILE_SEPARATOR)
            				.append(DataBackupConstants.DATADUMP)
            				.append(ExportSchedulerConstants.ZFS_FILE_SEPARATOR).toString();
            		Long userId = UserUtil.getCurrentUserId();
            		com.adventnet.crm.data.backup.DataBackupUtil.initiateFolderCleanUp(basePath, zgid.toString(), userId!=null ? userId.toString() : "null"); //No I18N
            	}
            	catch(Exception ex) {
            		String msg = new StringBuilder("Exception occurred while delete files in zfs for zgid ").append(zgid).toString(); // No I18N
            		LOGGER.log(Level.WARNING,msg,ex);
            	}
            }
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }
