   public JSONObject enableZOHOSAMLForPortals() {
	   try {
		   String zaid = CrmClientPortalUtil.getZaId();
		   String zuid = IAMUtil.getCurrentUser().getZuid();
		   String portalName = CrmClientPortalUtil.getPortalName();
		   ClientPortalIAMUtil.addClientPortalConfigurations(zaid, "allow.signup", "true");//No I18N
    	   ClientPortalIAMUtil.enableZohoAutheticationForPortals(zaid, zuid, portalName);
		   ClientPortalIAMUtil.addClientPortalConfigurations(zaid, "default.portal.zarid", "User");//No I18N
		   LOGGER.log(Level.INFO, "AddClientPortalConfigurations default.portal.zarid: " + ClientPortalIAMUtil.getClientPortalConfigurationByConfigName(zaid, "default.portal.zarid") + "\nallow.signup : " + ClientPortalIAMUtil.getClientPortalConfigurationByConfigName(zaid, "allow.signup"));

//    	   ClientPortalIAMUtil.updateClientPortalPolicyConfig(zaid, OrgPolicy.Policy.ALLOW_PLUS_SYMBOL_IN_USER_EMAIL.getName(), true);
    	   //ClientPortalIAMUtil.addClientPortalConfigurations(zaid, "plus.character.allowed.domain.regex", "([eucrmathndsopz.])");//No I18N
           resultObj.put("response", "Enabled SAML for portal successfully.");
       } catch (Exception e) {
           status = false;
           resultObj.put("response", e.toString());
           LOGGER.log(Level.WARNING, "Exception occurred while enabling SAML auth",e);
       }
       resultObj.put("status", status);
       return resultObj;
   }
   
