   public JSONObject featureEarlyAccess() {
	   try {
		   String featureName = request.getParameter("featureName");
		   Boolean featureStatus = Boolean.parseBoolean(request.getParameter("featureStatus"));
		   if(featureName == null || featureStatus == null) {
			   status = false;
			   resultObj.put("response", "FeatureName or featureStatus should not be empty");
			   return resultObj;
		   }
		   LOGGER.log(Level.INFO, "Trial feature reset configuration statred for " + featureName + " with stauts as " + featureStatus);
		   Long zgid = OrgUtil.getCurrentZGID();
		   CoreFeatureUtil.addOrUpdateTrailOrg(featureName, zgid.toString(), null, CoreFeatureUtil.Type.ORG.name(), featureStatus, null); //NO I18
		   switch (featureName) {
		   	case "CLIENTPORTAL_IAM_API_REVAMP":
			   	new com.adventnet.crm.autoISU.RegisterPortalDomainInIAM().doMigration(!featureStatus);
		   	}
		   } catch(Exception e) {
			   status = false;
			   resultObj.put("response", e.toString());
			   LOGGER.log(Level.WARNING, "Exception occured in trialFeatureResetConfiguration", e);
		   }
	   return resultObj;
    }

