    public JSONObject resetMailbackupDetails() throws JSONException{ // ###used
        try{
            DataObject mailDetailsObj =  (DataObject) ZMailConfigUtil.getCrmMailUserConfigCachedDO().clone();
            Criteria newCr = new Criteria(Column.getColumn(CRMMAILUSERCONFIG.TABLE, CRMMAILUSERCONFIG.USERID), userId, QueryConstants.EQUAL);
            newCr = newCr.and( new Criteria(Column.getColumn(CRMMAILUSERCONFIG.TABLE, CRMMAILUSERCONFIG.MAIL_TYPE), ZMailConstants.ZOHO_MAIL, QueryConstants.EQUAL));

            Row userRow = (Row) mailDetailsObj.getRow(CRMMAILUSERCONFIG.TABLE,newCr);
            JSONObject backupInfo = new JSONObject();
            backupInfo.put("ISBACKUPBLOCKED", false);
            userRow.set(CRMMAILUSERCONFIG.MAIL_BACKUP_INFO, backupInfo.toString());
            mailDetailsObj.updateRow(userRow);
            PersistenceCacheUtil.getNonAIPersistenceHandle().update(mailDetailsObj);

            resultObj.put("response", "mail back up resetted successfully.");
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }

    /**
     * @return This method creates 51 new CustomModules with no Custom Fields
     * @throws JSONException
     */
    public JSONObject create_max_custommodules() throws JSONException{
        try{
        	JSONArray profiles = new JSONArray(ProfileUtil.getAllProfileIds(null,false,false));
        	int cm = 0;
            for (cm = 1; cm <= 51; cm++) {
                int customModuleNumber = CrmCustomModuleUtil.returnNextCustomModuleNumber();
                if (customModuleNumber == -1) {
                	resultObj.put("response", "Maximum no of custom module created"); //no i18n
                    break;
                }
                validateAndCreateCustomModulesForAutomation(customModuleNumber, getModuleInfoForCreateCustomModules("CModules".concat(String.valueOf(cm)), "CModule".concat(String.valueOf(cm)), "CModules".concat(String.valueOf(cm)), profiles), currentUserId, currentUserLocale, Boolean.FALSE);//no i18n

            }
            if(!resultObj.has("response")) {
            	resultObj.put("response", "Custom fields created in new section"); //no i18n
            }
        }catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
      }

