    public void disableOrEnableCompose(String featureName, Boolean enable){ 
    	List<String> zuids = new ArrayList<String>();
		zuids.add(String.valueOf(zuId));
            if(featureName.equals("INLINE_COMPOSE_WINDOW"))
            {
            	CoreFeatureUtil.addOrUpdateTrailOrg("INLINE_COMPOSE_WINDOW",zgId+"",zuids,"USER",enable,null); //No I18N	
            	CoreFeatureUtil.addOrUpdateTrailOrg("INLINE_COMPOSE_WINDOW",zgId+"",null,"ORG",enable,null); //No I18N	
            	CoreFeatureUtil.addOrUpdateTrailOrg("OLD_COMPOSE_WINDOW",zgId+"",zuids,"USER",!enable,null); //No I18N
            	CoreFeatureUtil.addOrUpdateTrailOrg("OLD_COMPOSE_WINDOW",zgId+"",null,"ORG",!enable,null); //No I18N	
            }
            else if(featureName.equals("OLD_COMPOSE_WINDOW"))
            {
            	CoreFeatureUtil.addOrUpdateTrailOrg("OLD_COMPOSE_WINDOW",zgId+"",zuids,"USER",enable,null); //No I18N	
            	CoreFeatureUtil.addOrUpdateTrailOrg("OLD_COMPOSE_WINDOW",zgId+"",null,"ORG",enable,null); //No I18N	
            	CoreFeatureUtil.addOrUpdateTrailOrg("INLINE_COMPOSE_WINDOW",zgId+"",zuids,"USER",!enable,null); //No I18N
            	CoreFeatureUtil.addOrUpdateTrailOrg("INLINE_COMPOSE_WINDOW",zgId+"",null,"ORG",!enable,null); //No I18N	
            }
    	
    }
