    public JSONObject updatePathFinderSettings() throws JSONException {
		try
		{
			if (CrmFeatureUtil.isFeatureEnabled(FeatureNameConstants.PATHFINDER, null, OrgUtil.getCurrentZGID().toString())) {
				LOGGER.log(Level.INFO, "PathFinder settings updation");
				DataObject settingDo = getCrmSettingsDO();
				Criteria crt1 = new Criteria(Column.getColumn(CRMSETTINGS.TABLE,CRMSETTINGS.API_NAME), "system.pathfinder", QueryConstants.EQUAL); 
				DataObject dObj1 = settingDo.getDataObject(CRMSETTINGS.TABLE, crt1);
				
				if(dObj1.isEmpty()) {
					Criteria criteria1 = new Criteria( Column.getColumn( CRMSETTINGS.TABLE, CRMSETTINGS.API_NAME ), "system.orchestration", QueryConstants.EQUAL);	        
				    criteria1 = criteria1.and(new Criteria( Column.getColumn( CRMSETTINGS.TABLE, CRMSETTINGS.ELEMENT_TYPE ), 2, QueryConstants.EQUAL)); 
				    Row row = settingDo.getRow(CRMSETTINGS.TABLE, criteria1);
				    if (row != null) {
					    Criteria criteria = new Criteria( Column.getColumn( CRMSETTINGS.TABLE, CRMSETTINGS.PARENT_ID ), row.get(CRMSETTINGS.ELEMENT_ID), QueryConstants.EQUAL);
					    
					    int sequenceNumber = getSequenceNumber(settingDo.getDataObject(CRMSETTINGS.TABLE, criteria));
						Row newRow = new Row(CRMSETTINGS.TABLE);
						newRow.set(CRMSETTINGS.ELEMENT_LABEL, "PathFinder"); //No I18N 
						newRow.set(CRMSETTINGS.API_NAME, "system.pathfinder"); //No I18N 
						newRow.set(CRMSETTINGS.PARENT_ID, row.get(CRMSETTINGS.ELEMENT_ID));
						newRow.set(CRMSETTINGS.PRESENCE, 1);
						newRow.set(CRMSETTINGS.ELEMENT_TYPE, 3);
						newRow.set(CRMSETTINGS.SEQUENCE, sequenceNumber);
						newRow.set(CRMSETTINGS.GENERATED_SOURCE, 1);
						newRow.set(CRMSETTINGS.ELEMENT_ACTION, 1);
						newRow.set(CRMSETTINGS.SOURCE, 1);
						DataObject newDo = PersistenceCacheUtil.getPurePersistenceLiteHandle().constructDataObject();
						newDo .addRow(newRow);
						PersistenceCacheUtil.getPurePersistenceLiteHandle().add(newDo);
			            resultObj.put("response", "PathFinder settings Added.");
				    } else {
				    	resultObj.put("response", "PathFinder settings not added due to Orchestration not found.");
				    }
				} else {
		            resultObj.put("response", "PathFinder settings already Added.");
				}
			} else {
	            resultObj.put("response", "Please enable PathFinder Trial Feature");
			}
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
	}

