	/* Method to update StateNode's unique value */
	public JSONObject updatePFStateUniqueNumber() throws JSONException
	{
		try
		{
			if (CrmFeatureUtil.isFeatureEnabled(FeatureNameConstants.PATHFINDER, null, OrgUtil.getCurrentZGID().toString()))
			{
				DataObject statesDO = getPFStateNodesDO();
				if(!statesDO.isEmpty())
				{
					Iterator<Row> stateRows = statesDO.getRows(CRMPROCESSSTATE.TABLE);
					while(stateRows.hasNext())
					{
						Row stateRow = stateRows.next();
						stateRow.set(CRMPROCESSSTATE.STATEUNIQUENUMBER, stateRow.get(CRMPROCESSSTATE.PRECEDENCE));
						statesDO.updateRow(stateRow);
					}
					PersistenceCacheUtil.getPersistenceLiteHandle().update(statesDO);
					resultObj.put("response", "PathFinder - StateNode unique value field updated.");
				}
				else
				{
					resultObj.put("response", "PathFinder - No StateNodes with empty unique value field present.");
				}
			}
			else
			{
				resultObj.put("response", "PathFinder Trial Feature not enabled");
			}
		}
		catch (Exception e)
		{
			status = false;
			resultObj.put("response", e.toString());
		}
		
		resultObj.put("status", status);
		return resultObj;
	}

	/* Method to get PathFinder StateNodes */
	private static DataObject getPFStateNodesDO() throws Exception
	{
		SelectQuery sq1 = new SelectQueryImpl( Table.getTable(CRMPROCESSSTATE.TABLE) );
		sq1.addSelectColumn(Column.getColumn(CRMPROCESSSTATE.TABLE,CRMPROCESSSTATE.STATEID)); 
		sq1.addSelectColumn(Column.getColumn(CRMPROCESSSTATE.TABLE,CRMPROCESSSTATE.PRECEDENCE));
		sq1.addSelectColumn(Column.getColumn(CRMPROCESSSTATE.TABLE,CRMPROCESSSTATE.STATEUNIQUENUMBER));  
		sq1.addSelectColumn(Column.getColumn(CRMPROCESSSTATE.TABLE,CRMPROCESSSTATE.FEATURE_TYPE));  
		
		Criteria cr = new Criteria(Column.getColumn(CRMPROCESSSTATE.TABLE, CRMPROCESSSTATE.FEATURE_TYPE), AUTOMATION_FEATURES.PATHFINDER.getInt(), QueryConstants.EQUAL);
		cr = cr.and(new Criteria(Column.getColumn(CRMPROCESSSTATE.TABLE, CRMPROCESSSTATE.STATEUNIQUENUMBER), null, QueryConstants.EQUAL));
		sq1.setCriteria(cr);
		
		sq1.setRange( new Range(0,5000) );
		
		DataObject dbObj1 = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(sq1);
		
		return dbObj1;
	}

