	/**
	 * 
	 * @param dObj
	 * @return
	 */
	private static int getSequenceNumber(DataObject dObj) {
		int max = 0;
		try
		{
			Iterator<Row> itr = dObj.getRows(CRMSETTINGS.TABLE);
			while(itr.hasNext())
			{
				Row tabRow = itr.next();
				if(tabRow.get(CRMSETTINGS.SEQUENCE) != null)
				{
					if( max < (int)tabRow.get(CRMSETTINGS.SEQUENCE))
					{
						max = (int)tabRow.get(CRMSETTINGS.SEQUENCE);
					}
				}
			}
		}
		catch(Exception e)
		{
			//Suppress exception
		}
		return max + 1;
	}
