    public JSONObject run_secondschedule() throws Exception{ // ###used
        try{
            Criteria cr = new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDPROP),null,QueryConstants.NOT_EQUAL);
            DataObject fieldDO = PersistenceCacheUtil.getNCPurePersistenceLiteHandle().get(CRMFIELD.TABLE, cr);
            if(!fieldDO.isEmpty()){
            	List<Long> scheduledFields = EncryptFieldUtil.getEncryptionScheduledFieldsFromDo(fieldDO);
                @SuppressWarnings("rawtypes")
                Iterator itr = fieldDO.getRows(CRMFIELD.TABLE);
                while(itr.hasNext()){
                  Row fieldRow = (Row) itr.next();
                  JSONObject cryptDetails = FieldUtil.getCryptDetailsFromRow(fieldRow);
                  Long fieldId = Long.valueOf(fieldRow.get(CRMFIELD.FIELDID).toString());
    			  if(cryptDetails != null && cryptDetails.getInt(FieldUtil.STATUS) == 2 && !scheduledFields.contains(fieldId)){
                      if(cryptDetails.has(EncryptFieldUtil.CRYPTOMODE) && cryptDetails.get(EncryptFieldUtil.CRYPTOMODE).toString().equals(EncryptFieldUtil.ENCRYPTION)){
                          Long curTimeInGMT = DateTimeUtils.getCurrentLongTimeInGMT();
                          EncryptFieldUtil.addOneTimeJobForCleanUp(userId,curTimeInGMT, (Long)fieldRow.get(CRMFIELD.FIELDID),TabUtil.getTabNameById((Long)fieldRow.get(CRMFIELD.TABID)),1,null,0);
                      }else if(cryptDetails.has(EncryptFieldUtil.CRYPTOMODE) && cryptDetails.get(EncryptFieldUtil.CRYPTOMODE).toString().equals(EncryptFieldUtil.DECRYPTION)){
                          Long curTimeInGMT = DateTimeUtils.getCurrentLongTimeInGMT();
                          EncryptFieldUtil.addOneTimeJobForCleanUp(userId,curTimeInGMT, (Long)fieldRow.get(CRMFIELD.FIELDID),TabUtil.getTabNameById((Long)fieldRow.get(CRMFIELD.TABID)),0,null,0);
                      }
                    }
                }
            }
            resultObj.put("response", "Success.");
        }
        catch(Exception e){
            status = false;
            resultObj.put("response", "Cannot able to reset DB for Encryption corrupted entries. Exception > "+e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }

