    public JSONObject getUnsubscribeLinkUrlDecrypt() throws Exception
    {
        try
        {
            String formId = request.getParameter("formId");
            String email = request.getParameter("email");
            email=email.replaceAll("%2B", "+");
            String massMailId = request.getParameter("massMailId");
            try{
            	massMailId = ZMailConfigUtil.searchableDecrypt(massMailId);
				if(massMailId.contains(EmailsRelatedListConstants.API_DELEMITOR)){
					massMailId = massMailId.split(EmailsRelatedListConstants.API_DELEMITOR)[1];
				}
			}catch(Exception e){
				try{
					massMailId = com.zoho.common.components.security.SecurityUtil.decrypt(massMailId);
				}catch(Exception ex){
					LOGGER.log(Level.INFO,":::::Exception caught for Message ID::::{0}",massMailId);
				}
				LOGGER.log(Level.INFO,":::::Exception caught for custom header decrypt Message ID::::{0}",massMailId);
			}
            resultObj.put("response", UnsubscribeFormUtil.getUnsubscribeLinkForMail(formId, massMailId==null?null:Long.valueOf(massMailId), email, zgId.toString(), userId.toString()));
        }
        catch(Exception e)
        {
            status = false;
            resultObj.put("response", "Exception while getting unsubscribe link ::: "+e);
        }
        resultObj.put("status", status);
        return resultObj;
    }

    public JSONObject reSubscribeBlockedUnsubscribeEmails() throws Exception
    {
        try
        {
        	String subscribetype=request.getParameter("subscribetype");
        	if(subscribetype!=null)
        	{
        		Integer[] subscribeTypes=null;
        		if(subscribetype.equals("unsubscribe"))
        		{
        			subscribeTypes=new Integer[]{CrmConstants.FEATURETYPE_UNSUBSCRIPTION,CrmConstants.FEATURETYPE_UNSUBSCRIPTION_COMPLETE};
        		}
        		else if(subscribetype.equals("unsubscribecampaign"))
        		{
        			subscribeTypes=new Integer[]{CrmConstants.FEATURETYPE_CAMPAIGNS,CrmConstants.FEATURETYPE_CAMPAIGNS_COMPLETE};
        		}
        		else if(subscribetype.equals("unsbscribeall"))
        		{
        			subscribeTypes=new Integer[]{CrmConstants.FEATURETYPE_RESUBSCRIPTION,CrmConstants.FEATURETYPE_CAMPAIGNS,CrmConstants.FEATURETYPE_CAMPAIGNS_COMPLETE,CrmConstants.FEATURETYPE_UNSUBSCRIPTION,CrmConstants.FEATURETYPE_UNSUBSCRIPTION_COMPLETE,CrmConstants.FEATURETYPE_CONSENT,CrmConstants.FEATURETYPE_CONSENT_COMPLETE};
        		}
        		if(subscribeTypes!=null)
        		{

        			Criteria emailidCri = new Criteria(Column.getColumn(CRMBLOCKLIST.TABLE, CRMBLOCKLIST.FEATURETYPE), subscribeTypes, QueryConstants.IN);
        			UnsubscribeFormUtil.reSubscribeEmails(zgId, null, emailidCri);
                    UnsubscribeFormUtil.triggerEntityEmailOptOutScheduler(zgId);
                    reScheduleEntityEmailOptOutHourlyScheduler();
                    status = true;
        		}
        	}
        }
        catch(Exception e)
        {
            status = false;
            resultObj.put("response", "Exception while getting unsubscribe link ::: "+e);
        }
        resultObj.put("status", status);
        return resultObj;
    }

