    public JSONObject deleteDataSubjectRequest() throws Exception{ // ###used
        try{
        	SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMSALESENTITY.TABLE));
            sq.addSelectColumn(Column.getColumn(CRMSALESENTITY.TABLE, "*"));
            Criteria cr = new Criteria(Column.getColumn(CRMSALESENTITY.TABLE, CRMSALESENTITY.SETYPE), CrmModuleConstants.DATA_SUBJECT_REQUESTS, QueryConstants.EQUAL);
            sq.setCriteria(cr);
            Persistence per = PersistenceCacheUtil.getNonCachePersistenceHandle();
            DOIterator doi = new DOIterator(per, sq, 500, false);
            List<Long> seIDs = new ArrayList<Long>();
            while(doi.hasNext())
            {
            	DataObject DO = doi.next();
            	Iterator<Row> iter = DO.getRows(CRMSALESENTITY.TABLE);
                seIDs.clear();
                while(iter.hasNext()){
		            Row seRow = iter.next();
		            seIDs.add((Long)seRow.get(CRMSALESENTITY.SEID));
                }
	            DeleteQuery dq = new DeleteQueryImpl(Table.getTable(CRMSALESENTITY.TABLE));
	            Criteria delCr = new Criteria(Column.getColumn(CRMSALESENTITY.TABLE, CRMSALESENTITY.SEID), seIDs.toArray(), QueryConstants.IN);
	            dq.setCriteria(delCr);
	            dq.setLimit(seIDs.size());
	            PersistenceCacheUtil.getNonCachePersistenceHandle().delete(dq);
            }
            status = true;
        }catch(Exception e){
            status = false;
        }
        resultObj.put("status", status);
        return resultObj;
    }
    
    public JSONObject resetDataProcessingBasisPickListValues() throws Exception {
    	
    	Map<String, String> CONSENT_STATUS_ACTUAL_VS_DISPLAY_VALUES = new HashMap<String,String>();
		CONSENT_STATUS_ACTUAL_VS_DISPLAY_VALUES.put("Not Applicable", "Not Applicable");
		CONSENT_STATUS_ACTUAL_VS_DISPLAY_VALUES.put("Legitimate Interests", "Legitimate Interests");
		CONSENT_STATUS_ACTUAL_VS_DISPLAY_VALUES.put("Contract", "Contract");
		CONSENT_STATUS_ACTUAL_VS_DISPLAY_VALUES.put("Legal Obligation", "Legal Obligation");
		CONSENT_STATUS_ACTUAL_VS_DISPLAY_VALUES.put("Vital Interests","Vital Interests");	
		CONSENT_STATUS_ACTUAL_VS_DISPLAY_VALUES.put("Public Interests", "Public Interests");
		CONSENT_STATUS_ACTUAL_VS_DISPLAY_VALUES.put("Pending", "Consent - Pending");
		CONSENT_STATUS_ACTUAL_VS_DISPLAY_VALUES.put("Awaiting", "Consent - Waiting");
		CONSENT_STATUS_ACTUAL_VS_DISPLAY_VALUES.put("Obtained", "Consent - Obtained");
		CONSENT_STATUS_ACTUAL_VS_DISPLAY_VALUES.put("Not Responded", "Consent - Not Responded");
		CONSENT_STATUS_ACTUAL_VS_DISPLAY_VALUES.put("Stop Processing", "Consent - Stop Processing");
		CONSENT_STATUS_ACTUAL_VS_DISPLAY_VALUES.put("Delete", "Consent - Delete");
    	
    	try {
    		
    		List<String> consentModules = PrivacyPreferenceUtil.getDefaultConsentModulesList();	
    		consentModules.add(CoreModuleConstants.CONSENTS);
    		List<String> dataProcessingBasisFieldIds = new ArrayList<String>();
    		Map<String, String> processingBasisIDVsModule = new HashMap<String, String>();
    		Set<String> cacheDropModules = new HashSet<String>();
    		
    		for(String consentModule : consentModules) {
				
    			List<String> fieldIds = CrmFieldUtil.getFieldIdsByColumns(consentModule, new String[] {CRMCONSENTDETAILSTEMPLATE.PROCESSINGBASIS}, null);
    			if(!fieldIds.isEmpty()) {
    				
    				processingBasisIDVsModule.put(fieldIds.get(0), consentModule);
    				dataProcessingBasisFieldIds.addAll(fieldIds);
    			}
    			
			}
    		
    		if(!dataProcessingBasisFieldIds.isEmpty()) {
    			
    			DataObject dataProcessingBasisPickListDO = PickListFieldUtil.getPicklistValuesDO(new HashSet<String>(dataProcessingBasisFieldIds), false, null);
				
    			Iterator<Row> pickListItr = dataProcessingBasisPickListDO.getRows(CRMPICKLISTVALUES.TABLE);
    			
    			while(pickListItr.hasNext()) {
    				
    				Row pickListRow = pickListItr.next();
    				String actualValue = pickListRow.get(CRMPICKLISTVALUES.ACTUALVALUE).toString();
    				String displayValue = pickListRow.get(CRMPICKLISTVALUES.VALUE).toString();
    				
    				if(!CONSENT_STATUS_ACTUAL_VS_DISPLAY_VALUES.get(actualValue).equals(displayValue)) {
    					
    					pickListRow.set(CRMPICKLISTVALUES.VALUE, CONSENT_STATUS_ACTUAL_VS_DISPLAY_VALUES.get(actualValue));
    					dataProcessingBasisPickListDO.updateRow(pickListRow);
    					cacheDropModules.add(processingBasisIDVsModule.get(pickListRow.get(CRMPICKLISTVALUES.FIELDID).toString()));
    				}
    			}
    					
        		PersistenceCacheUtil.getNonCachePersistenceHandle().update(dataProcessingBasisPickListDO);
        		
        		if(!cacheDropModules.isEmpty()) {
	    			
	    			PageCacheUtil.createSchedulerForPageRegen(consentModules);
	    		}
    		}
    		
    		status = true;
    	} catch(Exception ex) {
    		LOGGER.log(Level.INFO, ":::::Exception occurred in resetDataProcessingBasisPickListValues :::: {0}", ex);
    		status = false;
    	}
    	
    	resultObj.put("status", status);
		return resultObj;
    }
    
	public JSONObject resetRequestTypePickListValues() throws Exception {
	    	
		Map<String, String> REQUEST_TYPE_ACTUALVALUE_VS_VALUE = new HashMap<String,String>();
		REQUEST_TYPE_ACTUALVALUE_VS_VALUE.put("Access", "Request to access data");//NO I18N
		REQUEST_TYPE_ACTUALVALUE_VS_VALUE.put("Rectify", "Request to rectify data");//NO I18N
		REQUEST_TYPE_ACTUALVALUE_VS_VALUE.put("Export", "Request to export data");//NO I18N
		REQUEST_TYPE_ACTUALVALUE_VS_VALUE.put("Stop Processing", "Request to stop processing data");//NO I18N
		REQUEST_TYPE_ACTUALVALUE_VS_VALUE.put("Delete", "Request to delete data");//NO I18N
		
		Boolean isCacheDropNeeded = Boolean.FALSE;
	
    	try {
    		
    		List<String> requestTypeFieldIds = CrmFieldUtil.getFieldIdsByColumns(CrmModuleConstants.DATA_SUBJECT_REQUESTS, new String[] {CRMDATASUBJECTREQUESTDETAILSTEMPLATE.REQUEST_TYPE}, null);
			
    		if(!requestTypeFieldIds.isEmpty()) {
    			
	    		DataObject requestTypePickListDO = PickListFieldUtil.getPicklistValuesDO(new HashSet<String>(requestTypeFieldIds), false, null);
				Iterator<Row> pickListItr = requestTypePickListDO.getRows(CRMPICKLISTVALUES.TABLE);
				
				while(pickListItr.hasNext()) {
					
					Row pickListRow = pickListItr.next();
					String actualValue = pickListRow.get(CRMPICKLISTVALUES.ACTUALVALUE).toString();
					String displayValue = pickListRow.get(CRMPICKLISTVALUES.VALUE).toString();
					
					if(!REQUEST_TYPE_ACTUALVALUE_VS_VALUE.get(actualValue).equals(displayValue)) {
						
						pickListRow.set(CRMPICKLISTVALUES.VALUE, REQUEST_TYPE_ACTUALVALUE_VS_VALUE.get(actualValue));
						requestTypePickListDO.updateRow(pickListRow);
						isCacheDropNeeded = Boolean.TRUE;
					}
				}
						
	    		PersistenceCacheUtil.getNonCachePersistenceHandle().update(requestTypePickListDO);
	    		
	    		if(isCacheDropNeeded) {
	    			
	    			PageCacheUtil.createSchedulerForPageRegen(Arrays.asList(CrmModuleConstants.DATA_SUBJECT_REQUESTS));
	    		}
    		}
    		
    		status = true;
    	} catch(Exception ex) {
    		LOGGER.log(Level.INFO, ":::::Exception occurred in resetRequestTypePickListValues :::: {0}", ex);
    		status = false;
    	}
    	
    	resultObj.put("status", status);
		return resultObj;
    }
    
