    public JSONObject delete_userfromaaa() throws Exception { // ###used
        try {
          SelectQuery sqAAAUser = new SelectQueryImpl(Table.getTable(AAAUSER.TABLE));
          sqAAAUser.addSelectColumn(Column.getColumn(AAAUSER.TABLE, "*"));
          Join aaauserJoinIamuser = new Join(AAAUSER.TABLE, CRMIAMUSER.TABLE, new String[]{AAAUSER.USER_ID},new String[]{CRMIAMUSER.USER_ID}, Join.LEFT_JOIN);
          sqAAAUser.addJoin(aaauserJoinIamuser);
          sqAAAUser.setCriteria(new Criteria(Column.getColumn(CRMIAMUSER.TABLE, CRMIAMUSER.USER_ID),null,QueryConstants.EQUAL));
          DataObject DO = PersistenceCacheUtil.getNonCachePersistenceHandle().get(sqAAAUser);
          @SuppressWarnings("unchecked")
          Iterator<Row> iter = DO.getRows(AAAUSER.TABLE);
          List<Long> userIDs = new ArrayList<Long>();
          while(iter.hasNext())
          {
            Row aaaUserRow = iter.next();
            userIDs.add((Long)aaaUserRow.get(AAAUSER.USER_ID));
          }
          if(!userIDs.isEmpty())
          {
            Criteria delCr = new Criteria(Column.getColumn(AAAUSER.TABLE, AAAUSER.USER_ID),userIDs.toArray(),QueryConstants.IN);
            PersistenceCacheUtil.getNonCachePersistenceHandle().delete(delCr);
          }
          status = true;
        }catch(Exception e){
            status = false;
        }
        resultObj.put("status", status);
        return resultObj;
    }
