    public JSONObject startDataStorageScheduler() throws JSONException {
        try {

    		Long currentTimeMillis = System.currentTimeMillis();
    		Timestamp executeTime = new Timestamp(currentTimeMillis + 50); //50 milli seconds
    		String keyValue = CrmKeyValueUtil.getCrmNCKeyValue("DATA_STORAGE_SCHEDULER"); //no i18N
    		if(keyValue != null){
    			JSONObject scheduleDetails = new JSONObject(keyValue);
    			Long jobId = scheduleDetails.getLong("id"); //No i18N
    			ScheduledJobDetails jobDetails = CrmScheduledJobsUtil.getJobDetails( jobId );
    			if(jobDetails != null){
    				ScheduledJobDetails.Status jobstatus = jobDetails.getStatus();
    				int jobStatus = jobstatus.getValue();
    				if(jobStatus == 0 || jobStatus == 1 || jobStatus == 2){
                    	Long last_sync_time = scheduleDetails.getLong("last_sync_time"); //No i18N
            			long milliseconds = executeTime.getTime() - last_sync_time;
            			long seconds =  milliseconds / 1000;
            			if(seconds > 180) {
            				CrmKeyValueUtil.deleteCrmNCKeyValueByKeyName("DATA_STORAGE_SCHEDULER", null, true); //No I18N
            			}else {
    					status = false;
    					resultObj.put("response", "Already running");
    					resultObj.put("status", jobstatus);
    					return resultObj;
    				}
    			}
    		}
            }

    		Long newInstanceId = CommonDBService.getUniqueIdNoTransact();
    		CrmJobBean jobDetails = new CrmJobBean(newInstanceId, ZohoCRMScheduleConstants.CRM_DATA_STORAGE_EXEC_CLASS, CoreScheduleConstants.ONETIME_HIGH_PROCESS, executeTime);
    		jobDetails.setTransactionTimeout(-1);
    		ZohoCRMSchedule.addOneTimeJob(jobDetails);
    		ScheduledJobDetails scheduledJobDetails = new ScheduledJobDetails();
    		scheduledJobDetails.setJobId(jobDetails.getJobId());
    		scheduledJobDetails.setUserId( UserUtil.getCurrentUserId() );
    		scheduledJobDetails.setCvId(OrgUtil.getCurrentZGID());
    		scheduledJobDetails.setActionType( "Data Storage scheduler" );//No I18N
    		scheduledJobDetails.setSeType("One Time Scheduler");//No I18N
    		scheduledJobDetails.setStartTime(executeTime.getTime());
    		scheduledJobDetails.setStatus(ScheduledJobDetails.Status.SCHEDULED);
    		CrmScheduledJobsUtil.addAndPersistJobDetails( scheduledJobDetails, null );
    		JSONObject scheduleDetails = new JSONObject();
    		if(keyValue != null){
    			scheduleDetails = new JSONObject(keyValue);
    		}else{
    			scheduleDetails.put("last_sync_time", currentTimeMillis);
    		}
    		scheduleDetails.put("id", newInstanceId);
    		CrmKeyValueUtil.insertOrUpdateCrmNCKeyValueByKeyName("DATA_STORAGE_SCHEDULER", scheduleDetails.toString() , true); //No i18N
            resultObj.put("response", "Data Storage Scheduler Started");
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
		}
    	 resultObj.put("status", status);
         return resultObj;
    }
