            sq.setCriteria(cr);
            DataObject dataObj = PersistenceCacheUtil.getNonCachePersistenceHandle().get(sq);

            @SuppressWarnings("unchecked")
			Iterator<Row> itr = dataObj.getRows(CRMREPORT.TABLE);
