    public JSONObject resetPrivateFieldsForModule() throws JSONException{ // ###used
        try{
           for(String module:modules) {
               try {
                   if(module.equals(CrmModuleConstants.CALLS)) {
                        continue;
                   }

                   Long tabId = TabUtil.getTabIdByName(module);
                   if(tabId!=null){
                   Long[] subFormTabIds = TabUtil.getSubTabIds(tabId);
                   List<Long> tabIdsList = new ArrayList<Long>();
                   tabIdsList.add(tabId);
                   for(int i=0;i<subFormTabIds.length;i++){
                      tabIdsList.add(subFormTabIds[i]);
                   }

                   UpdateQuery updQry = new UpdateQueryImpl(CRMFIELD.TABLE);
                   Criteria cr = new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.TABID),tabIdsList.toArray(new Long[tabIdsList.size()]),QueryConstants.IN);
                   cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.PRIVATE_TYPE),0,QueryConstants.GREATER_THAN));
                   updQry.setCriteria(cr);
                   updQry.setUpdateColumn(CRMFIELD.PRIVATE_TYPE, 0);
                   PersistenceCacheUtil.getPersistenceLiteHandle().update(updQry);
                }
           }
               catch(Exception e) {

               }
           }
           resultObj.put("response", "All sesitive fields removed. ");
           status = true;
         }
         catch(Exception e){
             resultObj.put("response", "exception. e= > "+e.toString());
            status = false;
        }
        resultObj.put("status", status);
        return resultObj;
    }

