    public JSONObject clean_sandbox_entries() throws JSONException { // ###used
        try {
        	String sandboxName = request.getParameter("sandboxName");
    		Row sandboxRow;
    		if(sandboxName == null) {
    			sandboxRow = SandboxConfigUtil.getSandboxInfo();
    		} else {
    			SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMSANDBOXACCOUNTS.TABLE));
    	 		sq.addSelectColumn(Column.getColumn(null, "*"));

    	 		Criteria cr = SandboxConfigUtil.getBackupSandboxCriteria(false);
    	 		cr = cr.and(new Criteria(Column.getColumn(CRMSANDBOXACCOUNTS.TABLE, CRMSANDBOXACCOUNTS.NAME), sandboxName, QueryConstants.EQUAL));

    	 		sq.setCriteria(cr);
    	 		sq.addSortColumn(new SortColumn(Column.getColumn(CRMSANDBOXACCOUNTS.TABLE, CRMSANDBOXACCOUNTS.SANDBOXID), true));

    	 		DataObject dObj = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(sq);

    	 		sandboxRow = dObj.getRow(CRMSANDBOXACCOUNTS.TABLE);
    		}
    		if(sandboxRow == null) {
    			status = false;
    			resultObj.put("response", "Sandbox not found in this account");
    		} else {
    			String sandboxZgid = sandboxRow.get(CRMSANDBOXACCOUNTS.ZGID).toString();
            	Criteria deleteCr = new Criteria(Column.getColumn(CRMSANDBOXCONFIGCHANGES.TABLE, CRMSANDBOXCONFIGCHANGES.CHANGESETID), null, QueryConstants.EQUAL);
            	Persistence per = PersistenceCacheUtil.getPurePersistenceLiteHandle(sandboxZgid.toString());
            	CommonDBUtil.deleteWithLimit(CRMSANDBOXCONFIGCHANGES.TABLE, deleteCr, per, 1000);
            	resultObj.put("response", "Successfully deleted undeployed changes entries");
            }
        }
        catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }

