    public String getTabOrder() throws DataAccessException, Exception{
        StringBuffer allIds = new StringBuffer();
        String[] modulesArray = "Home,Leads,Contacts,Accounts,Deals,Activities,Reports,Analytics,Products,Quotes,Sales Orders,Purchase Orders,Invoices,SalesInbox,Feeds,Campaigns,Vendors,Price Books,Cases,Solutions,Documents,Forecasts,Visits,Social".split(",");//no i18n
        HashMap<String, Long> module_idsMap = new HashMap<String, Long>();
        Criteria cr = new Criteria( Column.getColumn(CRMTAB.TABLE, CRMTAB.PRESENCE), new Long[] {new Long(-1L),new Long(-2L)}, QueryConstants.NOT_IN);
        Criteria cr1 = new Criteria( Column.getColumn( CRMTAB.TABLE, CRMTAB.PRESENCE), Long.valueOf(1), QueryConstants.EQUAL);
        Criteria noSubfromCr = new Criteria( Column.getColumn( CRMTAB.TABLE, CRMTAB.PARENT_TABID), null, QueryConstants.EQUAL);
        cr1 = cr1.and(noSubfromCr);
        cr = cr.and(noSubfromCr);
        if( !ZMailConfigUtil.isMailAddonEnabled(userId, ZMailConstants.ZOHO_MAIL ) ){
            cr = cr.and(new Criteria( Column.getColumn(CRMTAB.TABLE, CRMTAB.NAME), CrmModuleConstants.EMAILS, QueryConstants.NOT_EQUAL));
            cr1 = cr1.and(new Criteria( Column.getColumn(CRMTAB.TABLE, CRMTAB.NAME), CrmModuleConstants.EMAILS, QueryConstants.NOT_EQUAL));
        }

        cr = cr.and( new Criteria ( Column.getColumn( CRMTAB.TABLE, CRMTAB.NAME), ZFinanceConstants.FINANCE_MODULE_LIST, QueryConstants.NOT_IN));

        @SuppressWarnings("unchecked")
        Iterator<Row> iter = TabUtil.getAllTabsCachedDO(null, new FEATURE[]{FEATURE.WEBUIHIDDEN, FEATURE.MODULE_SETTING}).getRows(CRMTAB.TABLE, cr);
        while (iter != null && iter.hasNext()) {
            Row row = (Row) iter.next();
            String moduleName = (String) row.get(CRMTAB.TABLABEL);
            Long tabId =  (Long) row.get(CRMTAB.TABID);
            module_idsMap.put(moduleName, tabId);
        }
        for (int i = 0; i < modulesArray.length; i++) {
            allIds.append(module_idsMap.get(new String(modulesArray[i]))+";");//no i18n
            module_idsMap.remove(modulesArray[i]);
        }
        if(module_idsMap.size()>0){
             for (Map.Entry<String,Long> entry : module_idsMap.entrySet()){
                 if(EntityMetaDataUtil.isActivitySubModulesExposed() || (!entry.getKey().equals("Tasks") && !entry.getKey().equals("Events") && !entry.getKey().equals("Calls"))){
                     allIds.append(new String(entry.getValue()+";"));//no i18n
                 }
            }
        }

        String newArray = "";
        String[] respArray = allIds.toString().split(";");
        for (int i = 0; i < respArray.length; i++) {
            if(!respArray[i].equals("null")){
                newArray+=respArray[i]+";";
            }
        }

        return newArray;
    }
