       /**
        * temporary code for rp
        * @author dileep-5695
        * @throws Exception
        */
    public void runMigration() throws Exception
    {
    	try {
	    	Long fieldId = FieldUtil.getFieldId(CRMREVIEWPROCESSDETAILS.TABLE,CRMREVIEWPROCESSDETAILS.STATUSID);
	    	Long logFfieldId = FieldUtil.getFieldId(CRMREVIEWLOGS.TABLE,CRMREVIEWLOGS.STATUSID);
			SelectQuery statusQry = new SelectQueryImpl( Table.getTable(CRMPICKLISTVALUES.TABLE ) );
			statusQry.addSelectColumn(Column.getColumn(CRMPICKLISTVALUES.TABLE,"*"));
			Criteria crt = new Criteria(Column.getColumn(CRMPICKLISTVALUES.TABLE, CRMPICKLISTVALUES.FIELDID),new Long[]{fieldId, logFfieldId},QueryConstants.IN);
			crt = crt.and(new Criteria(Column.getColumn(CRMPICKLISTVALUES.TABLE, CRMPICKLISTVALUES.ACTUALVALUE),new String[]{"approved", "rejected"},QueryConstants.IN));//no i18n
			statusQry.setCriteria(crt);
			Persistence pers = PersistenceCacheUtil.getNonCachePersistenceHandle();
			DOIterator doItr = new DOIterator(pers, statusQry, 1000);
			while(doItr.hasNext()){
				DataObject dobj = doItr.next();
				Iterator rows = dobj.getRows(CRMPICKLISTVALUES.TABLE);
				while (rows.hasNext()) {
					Row row = (Row) rows.next();
					if (row.get(CRMPICKLISTVALUES.ACTUALVALUE).toString().equalsIgnoreCase("approved"))//no i18n
					{
						row.set(CRMPICKLISTVALUES.ACTUALVALUE, "Approved");//no i18n
						row.set(CRMPICKLISTVALUES.VALUE, "Approved");//no i18n
					}
					else
					{
						row.set(CRMPICKLISTVALUES.ACTUALVALUE, "Rejected");//no i18n
						row.set(CRMPICKLISTVALUES.VALUE, "Rejected");//no i18n
					}
					dobj.updateRow(row);
				}
				pers.update(dobj);
			}
			resultObj.put("response", "Review Processes migration success");
		} catch (Exception e)
		{
			resultObj.put("response", "Review Processes migration failed");
		}
    }
    public void resetReviewProcessConf() throws Exception
    {
    	try {
		SelectQuery qry = new SelectQueryImpl( Table.getTable( CRMWORKFLOWRULE.TABLE ) );

		qry.addSelectColumn( Column.getColumn(CRMWORKFLOWRULE.TABLE, CRMWORKFLOWRULE.RULEID) );
		qry.addSelectColumn( Column.getColumn(CRMWORKFLOWRULE.TABLE, CRMWORKFLOWRULE.RULETYPE) );
		Criteria crt = new Criteria(Column.getColumn(CRMWORKFLOWRULE.TABLE, CRMWORKFLOWRULE.TYPE), AutomationConstants.TYPE_REVIEW_PROCESS, QueryConstants.EQUAL);
		crt = crt.and(new Criteria(Column.getColumn(CRMWORKFLOWRULE.TABLE, CRMWORKFLOWRULE.ACTIVE), Boolean.FALSE, QueryConstants.EQUAL));
		qry.setRange(new Range(0, 2000));
		DataObject rpDO = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(qry);
		ZohoCRMBeanWTImpl beanInstance = (ZohoCRMBeanWTImpl)ScopedAccess.getInstance(ZohoCRMBeanWTImpl.class, null, TransactionType.REQUIRED);
		if (!rpDO.isEmpty())
		{
			HashMap<String, ArrayList<Long>> rpMap = new HashMap<String, ArrayList<Long>>();
			Iterator rpRows = rpDO.getRows(CRMWORKFLOWRULE.TABLE);
			while (rpRows.hasNext()) {
				Row rpRow = (Row) rpRows.next();
				String module = rpRow.get(CRMWORKFLOWRULE.RULETYPE).toString();
				if (!rpMap.containsKey(module))
				{
					rpMap.put(module, new ArrayList<Long>());
				}
				rpMap.get(module).add(JsonUtil.getLong(rpRow.get(CRMWORKFLOWRULE.RULEID)));
				rpMap.put(module, rpMap.get(module));
			}
			for (Entry<String, ArrayList<Long>> entry : rpMap.entrySet())
			{
			  beanInstance.deleteReviewProcess(entry.getValue(), entry.getKey(), currentUserId);
			}
    		resultObj.put("response", "Review Processes deactivated records deleted successfully");
		}
    	} catch (Exception e)
    	{
    		resultObj.put("response", "Review Processes deactivated records deletion failed");
    	}
    }
    public JSONObject getFailedRecordDetails(List<Long> records, String module) throws Exception { // to debug timetracking filters' failure
        String tableName = EntityMetaDataUtil.getBaseTableByModuleName(module);
        SelectQuery sq = new SelectQueryImpl(Table.getTable(tableName));
        sq.addSelectColumn(Column.getColumn(tableName, "*"));
        String pkCol = EntityMetaDataUtil.getPKColumnName(tableName);
        Criteria cr = new Criteria(Column.getColumn(tableName, pkCol), records.toArray(), QueryConstants.IN);
        sq.setCriteria(cr);
        Persistence per = PersistenceCacheUtil.getNonCachePersistenceHandle();
        DOIterator doIter = new DOIterator(per, sq, 0, 1000, true);
        JSONObject recordsJSON = new JSONObject();
        recordsJSON.put("currentTime", DateTimeUtils.getCurrentTimeInGMT());
        while(doIter.hasNext()) {
            DataObject dObj = doIter.next();
            @SuppressWarnings("unchecked")
            Iterator<Row> itr = dObj.getRows(tableName);
            while(itr.hasNext()){
                Row row = itr.next();
                JSONObject details = new JSONObject();
                details.put(CrmConstants.M_RELACTIVITYTIME_COLUMN, row.get(CrmConstants.M_RELACTIVITYTIME_COLUMN));
                details.put(CrmConstants.A_RELACTIVITYTIME_COLUMN, row.get(CrmConstants.A_RELACTIVITYTIME_COLUMN));
                recordsJSON.put(row.get(pkCol).toString(), details);
            }
        }
        return recordsJSON;
    }

    public JSONObject abtestingResumeToCompleted() throws Exception
    {
    	try{
    		String abtestid = request.getParameter("abtestid");
    		String response = "invalid id"; //NO I18N

    		DataObject abtestDo = WebFormABTestingUtil.getABTestDoById(abtestid, null);

    		if(!abtestDo.isEmpty())
    		{
    			Row abTestRow = abtestDo.getRow(CRMWEBFORMABTESTING.TABLE);

    			if(abTestRow != null)
    			{
    				Integer status = (Integer) abTestRow.get(CRMWEBFORMABTESTING.STATUS);

    				if(!WebFormABTestingUtil.VALID_STATUSES.get(status).equals(WebFormABTestingUtil.STATUS_PAUSED)){
    					response = "the a/b testing not in paused state";//NO I18N
    				}else{
    					Long createdTime = (Long) abTestRow.get(CRMWEBFORMABTESTING.CREATEDTIME);
    					Integer rotation = (Integer) abTestRow.get(CRMWEBFORMABTESTING.ROTATIONTYPE);
    					String rotationValue = (String) abTestRow.get(CRMWEBFORMABTESTING.ROTATIONVALUE);
    					JSONObject value = new JSONObject(rotationValue);
    					int days = WebFormABTestingUtil.getConditionPeriodsInDays(WebFormABTestingUtil.VALID_CONDITIONS.get(rotation), value.getInt("value"));//NO I18N
    					Long timeToBeUpdate = createdTime - ((days + 1) * DateTimeUtils.MILLISEC_PER_DAY);

    					abTestRow.set(CRMWEBFORMABTESTING.CREATEDTIME, timeToBeUpdate);
    					abTestRow.set(CRMWEBFORMABTESTING.STARTTIME, timeToBeUpdate);
    					abtestDo.updateRow(abTestRow);
    					PersistenceCacheUtil.getPurePersistenceLiteHandle().update(abtestDo);
    					response = "created time updated successfully";//NO I18N
    				}
    			}

    		}
    		resultObj.put("response", response);
    	}catch (Exception e) {
    		status = false;
    		resultObj.put("response", e.toString());
    	}
    	resultObj.put("status", status);
    	return resultObj;
    }

    public JSONObject reScheduleEntityEmailOptOutHourlyScheduler() throws JSONException
    {
    	Long zgid = null;
    	try
    	{
    		String deleteJob = request.getParameter("deleteJob");
    		zgid = OrgUtil.getCurrentZGID();
    		String repetitionName = UnsubscribeFormUtil.EMAIL_OPT_OUT_SCH_NAME + zgid;

    		if(deleteJob != null && deleteJob.equals("true")) {
    			ZohoCRMSchedule.deleteRepetitionByRepetitionName(CoreScheduleConstants.RECURRING_LOW_PROCESS, repetitionName);
    			LOGGER.log(Level.INFO, "reScheduleEntityEmailOptOutHourlyScheduler ::: Job deleted ::: {0}", new String[] {zgid.toString()});
    		}

    		RepetitiveJob job = (RepetitiveJob) ZohoCRMSchedule.getTEJobByRepetitionName(repetitionName, CoreScheduleConstants.RECURRING_LOW_PROCESS);
    		if (job != null)
    		{
    			Timestamp currentTime = new Timestamp(System.currentTimeMillis());
                EntityEmailOptOutHourlyScheduler sch = new EntityEmailOptOutHourlyScheduler();
                sch.run(job.getJobID());
    			//ZohoCRMSchedule.updateRepetitiveJobById(job.getJobID(), CoreScheduleConstants.RECURRING_LOW_PROCESS, true, currentTime);
    			LOGGER.log(Level.INFO, "reScheduleEntityEmailOptOutHourlyScheduler ::: Job updated ::: {0}, currentTime: {1}", new String[] {zgid.toString(), currentTime.toString()});
    			resultObj.put("response", "EntityEmailOptOutHourlyScheduler schedule time updated to current time");
    		}else {
    			UnsubscribeFormUtil.triggerEntityEmailOptOutScheduler(OrgUtil.getCurrentZGID());
    			LOGGER.log(Level.INFO, "reScheduleEntityEmailOptOutHourlyScheduler ::: Job created ::: {0}", new String[] {zgid.toString()});
    			resultObj.put("response", "New periodic job created - EntityEmailOptOutHourlyScheduler");
    		}
    	}
    	catch (Exception e)
    	{
    		status = false;
    		String logs = "ResetConfigurations.reScheduleEntityEmailOptOutHourlyScheduler ::: failed: zgid: " + zgid;//NO I18N
    		LOGGER.log(Level.INFO, logs, e);
    		resultObj.put("response", "reScheduleEntityEmailOptOutHourlyScheduler failed");
    	}
    	resultObj.put("status", status);
    	return resultObj;
    }

