    public JSONObject addUnsubscribeLinkInTrialFeature() throws JSONException // ###used
    {
    	try {

    		String zgid = String.valueOf(zgId);
    		String featureName = CrmFeatureUtil.Feature.UNSUBSCRIBE_LINK.getName();

    		if(!CrmFeatureUtil.isFeatureEnabled(featureName, null, zgid))
    		{
    			DataObject featureDO = com.adventnet.crm.features.CrmFeatureUtil.getTrialFeatureDataObject(CrmFeatureUtil.Feature.UNSUBSCRIBE_LINK, zgid);
    			int noOfRows = featureDO.size(CRMTRIALFEATURES.TABLE);

    			if(noOfRows > 0) {
    				LOGGER.log(Level.WARNING, "More than one entry available for UNSUBSCRIBE_LINK feature. entries count: {0}, zgid: {1}", new Object[] {noOfRows, zgid});
    			}else {
    				CoreFeatureUtil.addOrUpdateTrailOrg(UnsubscribeFormUtil.UNSUBSCRIBE_LINK, zgid, null, "ORG", true, null);//No I18N
    			}
    		}
    		
    		//Unsubscribe Field Migration
    		unsubscribeFieldMigration();

    		resultObj.put("response", "TrialFeature :: " + featureName + "  added successfully");
    	}catch (Exception e){
    		status = false;
    		resultObj.put("response", e.toString());
    	}
    	resultObj.put("status", status);
    	return resultObj;
    }

    public JSONObject unsubscribeFieldMigration() throws JSONException
    {
    	try {
    		Criteria cr = new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.COLUMNNAME), new String[] {CrmConstants.UNSUBSCRIBEDMODE, CrmConstants.UNSUBSCRIBEDTIME}, QueryConstants.IN);
    		cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.READONLYTYPE), Boolean.FALSE, QueryConstants.EQUAL));

    		Persistence pers = PersistenceCacheUtil.getNonCachePersistenceHandle();
    		List<String> emailOptSupportedModules = TabUtil.getallmodulesforEmailActions();
    		DataObject fieldsDo = FieldUtil.getFieldsDO(emailOptSupportedModules, cr);
    		String fieldProp = new JSONObject().put("isalphabetical", true).toString();

    		if(!fieldsDo.isEmpty())
    		{
    			Iterator<Row> fieldsItr = fieldsDo.getRows(CRMFIELD.TABLE);

    			while(fieldsItr.hasNext())
    			{
    				Row field = fieldsItr.next();
    				Integer uiType = (Integer) field.get(CRMFIELD.UITYPE);

    				field.set(CRMFIELD.READONLYTYPE, Boolean.TRUE);
    				field.set(CRMFIELD.CATEGORY, CoreFieldConstants.CATEGORY.INTERNAL_FIELD.getValue());
    				field.set(CRMFIELD.IS_SORTABLE, FieldUtil.getSortableValue(uiType));
    				field.set(CRMFIELD.CUSTOMIZATIONS, 1);

    				if(uiType == CoreFieldConstants.UITYPE.STRINGFIELD.PICKLIST_FIELD.getValue()) {
    					field.set(CRMFIELD.FIELDPROP, fieldProp);
    				}
    				fieldsDo.updateRow(field);
    			}

    			pers.update(fieldsDo);
    		}

    		resultObj.put("response", "unsubscribeFieldMigration successfully completed");
    	}catch (Exception e){
    		status = false;
    		resultObj.put("response", e.toString());
    	}
    	resultObj.put("status", status);
    	return resultObj;
    }

    public JSONObject delete_all_workflows() throws JSONException{ // ###used
      try {
          for(String eachModule : modules) {
              Method method = WorkFlowRuleUtil.class.getDeclaredMethod("deleteAllWFConfigForModule", String.class);//no i18n
              method.setAccessible(true);
              String actualData = (String) method.invoke(null, eachModule);

            Criteria delCrt = new Criteria(Column.getColumn(CRMWORKFLOWRULE.TABLE, CRMWORKFLOWRULE.RULETYPE), eachModule, QueryConstants.EQUAL);
            delCrt = delCrt.and(new Criteria(Column.getColumn(CRMWORKFLOWRULE.TABLE, CRMWORKFLOWRULE.TYPE),new int[]{0,10,11,12}, QueryConstants.IN));
            DataAccess.delete(delCrt);
            Criteria delCrt2 = new Criteria(Column.getColumn(CRMWORKFLOWPROCESS.TABLE, CRMWORKFLOWPROCESS.RULETYPE), eachModule, QueryConstants.EQUAL);
            delCrt2 = delCrt2.and(new Criteria(Column.getColumn(CRMWORKFLOWPROCESS.TABLE, CRMWORKFLOWPROCESS.TYPE), new int[]{0,10,11,12}, QueryConstants.IN));
            DataAccess.delete(delCrt2);
        }
        resultObj.put("response", "Work flow rules deleted successfully.");//no i18n
        }catch (Exception e) {
            status = false;
            resultObj.put("response", "exception occured while deleting workflows:  Exception e = >"+e.toString());
        }
        return resultObj;
    }

