    public JSONObject updateSubscription() throws JSONException{
        try {
            String planName = "Enterprise"; //no i18n
            String planId = "14803";
            String userAddOn = "642";
            String edition = request.getParameter("edition");
            String userscount = request.getParameter("userscount");
            String lightuserscount = request.getParameter("lightuserscount") == null ? "0" : request.getParameter("lightuserscount");
            String lightuserAddOn = "14982";
            String includeForSandbox = request.getParameter("includeSandbox");

            switch (edition) {
                case "F":
                    planName = "L"; //no i18n
                    planId = "14901"; //no i18n
                    lightuserscount =  "0";//No I18N
                    break;
                case "S":
                    planName = "Standard";//no i18n
                    planId = "14802"; //no i18n
                    userAddOn = "640";
                    lightuserscount =  "0";//No I18N
                    break;
                case "P":
                    planName = "Professional"; //no i18n
                    planId = "14801"; //no i18n
                    userAddOn = "641";  //no i18n
                    lightuserscount =  "0";//No I18N
                    break;
                case "E":
                    planName = "Enterprise";  //no i18n
                    planId = "14803";
                    userAddOn = "642";
                    userscount = String.valueOf(Integer.parseInt(userscount) - Integer.parseInt(lightuserscount));
                    break;
                case "U":
                    planName = "Ultimate";  //no i18n
                    planId = "14808";
                    userAddOn = "647";
                    userscount = String.valueOf(Integer.parseInt(userscount) - Integer.parseInt(lightuserscount));
                    break;
                case "B":
                    planName = "BiginFree";  //no i18n
                    planId = "640100";
                    lightuserscount =  "0";//No I18N
                    break;
                case "O":
                    planName = "BiginZohoOne";  //no i18n
                    planId = "640102";
                    userAddOn = "640206";
                    lightuserscount =  "0";//No I18N
                    break;
                case "I":
                    planName = "Bigin Express";  //no i18n
                    planId = "640101";
                    userAddOn = "640201";
                    lightuserscount =  "0";//No I18N
                    break;
                case "M": 
                    planName = "Bigin Premier";  //no i18n
                    planId = "640111";
                    userAddOn = "640211";
                    break;
                case "G":
                    planName = "Bigin 360";  //no i18n
                    planId = "640117";
                    userAddOn = "640237";
                    break;
            }

            JSONArray addons = new JSONArray();
            JSONObject addOnsObj = new JSONObject();
            addOnsObj.put("total", userscount);
            addOnsObj.put("id", userAddOn);
            addons.put(addOnsObj);
            if(!lightuserscount.contentEquals("0")) {
            	JSONObject lightAddOnsObj = new JSONObject();
            	lightAddOnsObj.put("total", lightuserscount);
            	lightAddOnsObj.put("id", lightuserAddOn);
                addons.put(lightAddOnsObj);
            }


            JSONObject donebyObj = new JSONObject();


            JSONObject subcriptionDetailObj = new JSONObject();
            if(edition.equals("F")){
            	donebyObj.put("role", "scheduler");
                donebyObj.put("zuid", "-1");
                subcriptionDetailObj.put("zId", zgId.toString());
                subcriptionDetailObj.put("profileid", "RP2000148554991");
                subcriptionDetailObj.put("planid", planId);
                subcriptionDetailObj.put("serviceId", "2");
                subcriptionDetailObj.put("downgradereason", "QA testing downgrade");
                subcriptionDetailObj.put("doneby", donebyObj);
                subcriptionDetailObj.put("zuid", zuId+"");
                if(includeForSandbox == null || includeForSandbox.equalsIgnoreCase(Boolean.toString(false))) {
                	subcriptionDetailObj.put("skip_sandbox", true);
                }
                	
                SubscriptionBeanImpl subObj = new SubscriptionBeanImpl();
                subObj.cancelSubscription(zgId.toString(), subcriptionDetailObj);
            }
            else{
            donebyObj.put("role", "admin");
            donebyObj.put("zuid", "72215848");
                String expiryDate="1585119600000";
                Date date=new Date(Long.parseLong(expiryDate));
                SimpleDateFormat df2 = new SimpleDateFormat("MMddyy");
                String dateText = df2.format(date);
                subcriptionDetailObj.put("expirydate", dateText);
            subcriptionDetailObj.put("zId", zgId.toString());
            subcriptionDetailObj.put("addons", addons);
            subcriptionDetailObj.put("profileid", "RP2000148554991");
            subcriptionDetailObj.put("planname", planName);
            subcriptionDetailObj.put("planid", planId);
            subcriptionDetailObj.put("zuid", zuId+"");
            subcriptionDetailObj.put("doneby", donebyObj);
            subcriptionDetailObj.put("frequency", 4);   //no i18n
            if(includeForSandbox == null || includeForSandbox.equalsIgnoreCase(Boolean.toString(false))) {
            	subcriptionDetailObj.put("skip_sandbox", true);
            }

            UpdateQuery uquery = new UpdateQueryImpl(CRMLICENSEKEY.TABLE);
            uquery.setUpdateColumn(CRMLICENSEKEY.PROFILE_ID, null);
            uquery.setUpdateColumn(CRMLICENSEKEY.PRE_ENT_TRIAL_NO_OF_USERS, null);
            PersistenceCacheUtil.getNonAIPersistenceHandle(zgId+"").update(uquery);
            PersistenceCacheUtil.getNonAIPersistenceHandle(zgId+"").update(uquery);

            SubscriptionBeanImpl subObj = new SubscriptionBeanImpl();
            subObj.modifySubscription(zgId.toString(), subcriptionDetailObj);
            }
            resultObj.put("response", "Subscription succesfully updated to : "+planName+" Edition");//no i18n
        }catch (Exception e) {
            status = false;
            resultObj.put("response", "exception occured while updateSubscription:  Exception e = >"+e.toString());
        }
        return resultObj;
    }
    
