    public JSONObject triggerTrialCleanUpScheduler() throws Exception {
    	try {
    		LicenseDetails licenseDetails = LicenseUtil.getLicenseKeyDetails(zgId.toString());
    		Long trialCleanUpInstanceId = licenseDetails.getTrialCleanupInstanceId();
    		if(trialCleanUpInstanceId!=null) {
    			Calendar cal=Calendar.getInstance();
    			cal.setTimeInMillis( (DateTimeUtils.getCurrentTimeInGMT()).getTime() + 1000 );
    			LicenseUtil.updateDataConfCleanUpScheduler(cal,trialCleanUpInstanceId);
    			resultObj.put("status",true);
    			resultObj.put("response", "scheduled the cleanup for the trial");//no i18n
    		}else {
    			resultObj.put("status",false);
    			resultObj.put("response", "Trial not enabled for the account");//no i18n
    		}
    	}catch(Exception e) {
    		resultObj.put("status",false);
    		resultObj.put("response", "Exception occured while triggering the clean up scheduler for the trial");//no i18n
    	}
    	return resultObj;
    }


