	public JSONObject addMultiOrgUser() throws Exception {
		Long orginalUserId = userId;
    	try {
    		int from = Integer.parseInt(request.getParameter("from"));
    		int totalOrgCount = Integer.parseInt(request.getParameter("totalOrgCount"));
    		int orgUserCount = Integer.parseInt(request.getParameter("orgUserCount"));
    		String emailPrefix = request.getParameter("emailPrefix");
            String mailDomain = request.getParameter("mailDomain");
            String usernamePrefix = request.getParameter("usernamePrefix");
            String validity = request.getParameter("validity");
            String edition = request.getParameter("edition");
            int repeatTimes = request.getParameter("repeatTimes") != null ? Integer.parseInt(request.getParameter("repeatTimes")) : 1;

            JSONArray result = new JSONArray();

            for (int i = 1; i <= repeatTimes; i++) {
            	JSONArray res = addMultiOrgUser(from, totalOrgCount, orgUserCount, emailPrefix, usernamePrefix, validity, edition);
            	from = from + orgUserCount + totalOrgCount - 1;
            	result.put(res);
			}

            LOGGER.log(Level.INFO, "multiOrg add user result n times {0}", result); //No I18N

			resultObj.put("response", result.toString());//no i18n
		} catch (Exception e) {
			status=false;
			resultObj.put("response", "exception occured while adding Multi Org User:  Exception e = >"+e);//no i18n
		} finally {
			try {
				SASThreadLocal.setThreadLocalForGeneratedId(orginalUserId); // NOPMD
			} catch (Exception e) {
				LOGGER.log(Level.INFO, "multiOrg add user threadlocal issue", e); //No I18N
			}
		}
    	return resultObj;
    }

	private JSONArray addMultiOrgUser(int from, int totalOrgCount, int orgUserCount, String emailPrefix, String usernamePrefix, String validity, String edition) throws Exception {
		int to = from + orgUserCount + totalOrgCount - 1 - 1;
		JSONArray users =  new JSONObject(createUsers(from, to, emailPrefix, usernamePrefix, "Z1@crmtest",validity)).getJSONObject("user").getJSONArray("data");//no i18n

		int usersLen = users.length();
		for (int i = 0, fromTemp = from; i < usersLen; i++, fromTemp++) {
			users.getJSONObject(i).put("postfixIdx", fromTemp);
		}

		ArrayList<ArrayList<Integer>> orgVsUserMapping = new ArrayList<>();

		int userIdx = 0;
		for (int orgIdx = 0; orgIdx < totalOrgCount; orgIdx++) {
			ArrayList<Integer> userMapping = new ArrayList<>();
			if(orgIdx == 0) {
				for (int i = 0; i < orgUserCount; i++) {
					userMapping.add(userIdx++);
				}
			} else {
				int tempUserIdx = userIdx++;
				for (int i = 0; i < orgUserCount; i++) {
					userMapping.add(tempUserIdx--);
				}
			}
			orgVsUserMapping.add(userMapping);
		}

		LOGGER.log(Level.INFO, "orgVsUserMapping mapping {0}", orgVsUserMapping); //No I18N

		JSONArray result = new JSONArray();

		int orgVsUserMappingSize = orgVsUserMapping.size();
		for (int orgIdx = 0; orgIdx < orgVsUserMappingSize; orgIdx++) {
			JSONArray userResult = new JSONArray();
			Long zgid = null;
			Long loginUserId = null;
			CrmUser loginUserForm = null;
			int userSize = orgVsUserMapping.get(orgIdx).size();
			for (int uIdx = 0; uIdx < userSize; uIdx++) {
				JSONObject userInfo = users.getJSONObject(orgVsUserMapping.get(orgIdx).get(uIdx));
				String reqEmail = userInfo.getString("email");
				Long zuid = Long.parseLong(userInfo.getString("zuid"));
				int postfixIdx = userInfo.getInt("postfixIdx"); // No I18N

				MultiOrgFeatureEnabler.enableMultiOrgForZuid(String.valueOf(zuid));

				if(uIdx == 0) {
					Object[] createOrgResponse = createOrg(zuid, reqEmail, usernamePrefix, postfixIdx, edition, orgUserCount);
					zgid = (Long) createOrgResponse[0];
		        	loginUserId = (Long) createOrgResponse[1];
		        	loginUserForm = (CrmUser) createOrgResponse[2];
				} else {
					addUserToCRM(zgid, loginUserId, reqEmail, usernamePrefix, postfixIdx, orgUserCount, loginUserForm);
				}
				userResult.put(reqEmail);
			}
			JSONObject orgResult = new JSONObject();
			orgResult.put("zgid", zgid);
			orgResult.put("users", userResult);
			result.put(orgResult);
		}
		LOGGER.log(Level.INFO, "multiOrg add user result {0}", result); //No I18N
		return result;
	}

	private void addUserToCRM(Long zgid, Long loginUserId, String email, String usernamePrefix, int postfixIdx, int orgUserCount, CrmUser loginUserForm) throws Exception {
		SASThreadLocal.setThreadLocalForGeneratedId(loginUserId); // NOPMD

		Role managerRole = RoleUtil.getManagerRole(((Long)zgid).toString());
		CrmUser user_ = new CrmUser();

		user_.setEmail_id(email);

		long ZUID = ZohoCRMIAMUtil.getZUIDFromEmail(email);

		user_.setZuid(ZUID);
		user_.setIsconfirmed(true);
		if (UserUtil.isFirstNameMigrationRan()) {
			user_.setFirst_name(usernamePrefix + postfixIdx);
			user_.setLast_name("");
		} else {
			user_.setFirst_name("");
			user_.setLast_name(usernamePrefix + postfixIdx);
		}
//		user_.setStatus(UserConstants.Status.ACTIVE.getVal().toUpperCase());
		user_.setCurrent_status(UserConstants.Status.ACTIVE.getVal());
		user_.setRoleid(managerRole!=null?managerRole.getRoleid():null);
		if (postfixIdx % orgUserCount == 0) {
			user_.setProfileid(ProfileUtil.getAdminProfileId());
		} else {
			user_.setProfileid(ProfileUtil.getStandardProfileId());
		}
		user_.setFull_name(usernamePrefix + postfixIdx);
		user_.setTimezone("IST"); // No I18N
		user_.setCurrencycode("IN"); // No I18N
		user_.setLocalecode("en_IN"); // No I18N
		user_.setCountrycode("en_IN"); // No I18N
		user_.setCurrent_status(null);
		user_.setLangcode("en_US");// No I18N
		user_.setTimezone(loginUserForm.getTimezone());
		user_.setLangcode(loginUserForm.getLangcode());
		user_.setCurrencycode(loginUserForm.getCurrencycode());
		user_.setCountrycode(loginUserForm.getCountrycode());
		user_.setLocalecode(loginUserForm.getLocalecode());

		SASThreadLocal.setThreadLocalForGeneratedId(loginUserId); // NOPMD

		RequestDetails requestObj = SecurityUtil.requestToPojo(request);

		List<CrmUser> users = new ArrayList<>();
		users.add(user_);

		CrmUserData core_user = CrmUserData.builder().setOrg(new CrmOrg(zgid)).setReqDetails(requestObj).setUsers(users).setProcessType(UserConstants.UserProcessType.CONFIRME).build();
        CrmUserFactory.getService().add(core_user);
	}

	private Object[] createOrg(long zuid, String reqEmail, String usernamePrefix, int postfixIdx, String edition, int orgUserCount) throws Exception {
		User reqUser = CoreIAMUtil.getIAMProxy().getUserAPI().getUser(zuid);

		IAMUtil.setCurrentUser(reqUser);

		Properties props = getUserProperties(reqUser, request, zuid + "");

		JSONObject resp = CreateCrmUserUtil.addUser(props);

		JSONObject userDetails = resp.getJSONObject("details");
		Long zgid = Long.parseLong(userDetails.get("zgid").toString());

		Long loginUserId = UserUtil.getUserIdByZUID(zuid, zgid + "");

		request.setAttribute(CrmConstants.USERID_FROM_FILTER, loginUserId);

		SASThreadLocal.setThreadLocalForGeneratedId(loginUserId); // NOPMD

		CrmUser Olduser = new CrmUser(loginUserId);
        CrmUser loginUserForm = CrmUserFactory.getService().getBean(null, Olduser);
		String orgName = "ZohoCRM"; // No I18N
		CrmUser oldUser = loginUserForm.clone();
		if (orgName != null && !"".equals(orgName)) {
			loginUserForm.setEmail_id(reqEmail);
			loginUserForm.setFirst_name(""); // No I18N
			loginUserForm.setRoleid(RoleUtil.getAdminRoleId());
			loginUserForm.setProfileid(ProfileUtil.getAdminProfileId());
			loginUserForm.setLast_name(usernamePrefix + postfixIdx);
			loginUserForm.setTimezone("IST"); // No I18N
			loginUserForm.setCurrencycode("IN"); // No I18N
			loginUserForm.setLocalecode("en_IN"); // No I18N
			loginUserForm.setCountrycode("IN"); // No I18N
			loginUserForm.setCity("Chennai"); // No I18N
			loginUserForm.setCountry("US"); // No I18N
			loginUserForm.setStreet("T.Nagar"); // No I18N
			loginUserForm.setState("Tamil Nadu"); // No I18N
			loginUserForm.setZipcode("1234567890"); // No I18N

			CrmOrg org = new CrmOrg(OrgUtil.getCurrentZGID());
			CrmUserData user_holder = CrmUserData.builder().setUsers(new ArrayList<CrmUser>(Arrays.asList(loginUserForm))).setOrg(org).build();
			user_holder.setOld_users(loginUserForm.getId(), oldUser);
            CrmUserFactory.getService().update(user_holder);
            String currentEdition = LicenseUtil.getLicenseType(String.valueOf(OrgUtil.getCurrentZGID()));
			UpdateQuery uquery = new UpdateQueryImpl(CRMLICENSEKEY.TABLE);

			boolean isBigin = CrmEnvironment.BIGIN.equals(CrmEnvironment.getCurrentEnvironment());
			String updlicType = isBigin ? LicenseConstants.LICENSE_EDITION_PROPOSED_BIGIN : edition;
			if ("P".equals(updlicType)) {
				updlicType = "R"; // No I18N
			}
			if ("F".equals(updlicType)) {
				updlicType = "N"; // No I18N
			}
			if (updlicType == null) {
				updlicType = "A"; // S - Standard , R - Professional , N - Free , E - Enterprise //No I18N

			}

			Calendar cal = Calendar.getInstance();
			cal.add(Calendar.YEAR, 1);

			uquery.setUpdateColumn(CRMLICENSEKEY.LICENSE_TYPE, updlicType);
			uquery.setUpdateColumn(CRMLICENSEKEY.NO_OF_USERS, orgUserCount);
			uquery.setUpdateColumn(CRMLICENSEKEY.FREE_USERS, 0);
			uquery.setUpdateColumn(CRMLICENSEKEY.STORAGESPACE, Long.valueOf((orgUserCount * LicenseConstants.ENT_EDITION_STORAGE_PER_USER_LICENSE)));
			uquery.setUpdateColumn(CRMLICENSEKEY.EXPIRY_DATE, new Timestamp(cal.getTimeInMillis()));
			uquery.setUpdateColumn(CRMLICENSEKEY.PRE_ENT_TRIAL_NO_OF_USERS, null);
			uquery.setUpdateColumn(CRMLICENSEKEY.PRE_ENT_TRIAL_LICENSE_TYPE, null);

			PersistenceCacheUtil.getNonAIPersistenceHandle(zgid + "").update(uquery);

			  //#change_in_update_paid_modules_status
//    		TabUtil.updatePaidModulesStatus(Long.valueOf(1));
    		com.adventnet.crm.customization.tabs.CrmModuleUtil.updatePaidModulesStatus(currentEdition, updlicType);

			if (isBigin) {
				BiginSignup biginSignup = new BiginSignup();
				biginSignup.handleIgniteSignup();
				biginSignup.createProductsSubform(String.valueOf(zgid));
			}
		}

		return new Object[]{zgid, loginUserId, loginUserForm};
	}

    public void createUsersAndAddToCrm(int from,int to,int orgUserCount,String emailPrefix,String mailDomain,String usernamePrefix,String method,String validity,String edition) throws Exception{
    	String[] userNames = new String[(to - from) + 1];
    	int usernameCounter = 0;
    	int counter = 0;
    	String reqEmail = "";
    	Long zuid = 1L;
    	Long zgid = 1L;
    	Long loginUserId = null;
    	JSONArray userData=null;
    	IAMProxy proxy = CoreIAMUtil.getIAMProxy();
        UserAPI userapi = proxy.getUserAPI();
        for (int i = from; i <= to; i++) {
            userNames[usernameCounter++] = usernamePrefix + i;
        }
        CrmUser loginUserForm = null;
        for (int i = from,j=0; i <= to; i++,j++) {
        	if(method != null && method.equalsIgnoreCase("oldusers")) {  //no i18n
        		LOGGER.log(Level.INFO, "::::::::::;; TEST 1---- Inside Else If ::::::::");
                zuid = IAMProxy.getInstance().getUserAPI().getUser(reqEmail).getZUID();
                LOGGER.log(Level.INFO, "::::::Email ----" + reqEmail);
                reqEmail = emailPrefix+"+"+usernamePrefix+i+"t"+validity+"@zohotest.com";
             } else {
               if (counter % orgUserCount == 0) {
                 String respp =  createUsers(i, i+(orgUserCount-1), emailPrefix, usernamePrefix, "Z1@crmtest",validity);//no i18n
                 LOGGER.log(Level.INFO, "Resposne in add user jsp file {0}", new Object[] {respp});
                  try {
                    JSONObject jsonObject = new JSONObject(respp);
                   userData = (JSONArray) (((JSONObject) jsonObject.get("user")).get("data"));
                  } catch (Exception e) {
                    LOGGER.log(Level.WARNING, "Exception occured at else part in addUser jsp file --"+respp, e);
                      throw e;
                  }
                  j=0;
               }
               JSONObject userInfo = (JSONObject) userData.get(j);
               reqEmail = userInfo.getString("email");
               zuid = Long.parseLong(userInfo.getString("zuid"));
            }
            User reqUser = userapi.getUser(zuid);
            Properties props = getUserProperties(reqUser, request, zuid + "");
            if(counter % orgUserCount == 0) {
            	createCRMfromAdminUser(reqUser,props,usernamePrefix+i, reqEmail, edition, orgUserCount);
            }
            else{
            	addIAMUsersToCrm(reqEmail, zgid, usernamePrefix+i, i, orgUserCount, loginUserId, loginUserForm);
            }
        	counter++;
        }

    }

