    /**
     * @warning! possible data loss
     * Removes the draft folder and any draft templates stored within.
     *
     * @author krishna-13961
     */
    public JSONObject purgeDraftTemplatesFolder() throws Exception {
        SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMTEMPLATEFOLDER.TABLE));
        sq.addSelectColumn(Column.getColumn(CRMTEMPLATEFOLDER.TABLE, CRMTEMPLATEFOLDER.FOLDERID));
        sq.setCriteria(new Criteria(Column.getColumn(CRMTEMPLATEFOLDER.TABLE, CRMTEMPLATEFOLDER.DESCRIPTION), TemplateConstants.DRAFTTEMPLATEFOLDER, QueryConstants.EQUAL));
        sq.setRange(new Range(0, 1));

        DataObject dO = com.zoho.crmcomponents.templates.common.PersistenceUtil.getPersistenceHandle().get(sq);

        if(dO.isEmpty()) {
            LOGGER.info("Draft template folder does not exist.");
            return null;
        }

        Row folderRow = dO.getRow(CRMTEMPLATEFOLDER.TABLE);
        String folderId = folderRow.get(CRMTEMPLATEFOLDER.FOLDERID).toString();
        LOGGER.info("Draft folder id: " + folderId);

        // now let's delete any draft templates that exist
        DeleteQuery dqE = new DeleteQueryImpl(Table.getTable(CRMEMAILTEMPLATE.TABLE));
        dqE.setCriteria(new Criteria(Column.getColumn(CRMEMAILTEMPLATE.TABLE, CRMEMAILTEMPLATE.FOLDERID), folderId, QueryConstants.EQUAL));
        int noOfEmailTemps = com.zoho.crmcomponents.templates.common.PersistenceUtil.getPersistenceHandle().delete(dqE);
        LOGGER.info("Deleted " + noOfEmailTemps + " draft templates from CrmEmailTemplate table.");

        DeleteQuery dqT = new DeleteQueryImpl(Table.getTable(CRMTEMPLATEDETAILS.TABLE));
        dqT.setCriteria(new Criteria(Column.getColumn(CRMTEMPLATEDETAILS.TABLE, CRMTEMPLATEDETAILS.FOLDERID), folderId, QueryConstants.EQUAL));
        int noOfTemplates = com.zoho.crmcomponents.templates.common.PersistenceUtil.getPersistenceHandle().delete(dqT);
        LOGGER.info("Deleted " + noOfTemplates + " draft templates from CrmTemplateDetails table.");

        TemplatesHandler templatesHandler = TemplatesHandler.getInstance();
        FolderDetails folderDetails = new FolderDetails();
        folderDetails.setFolderId(Long.parseLong(folderId));
        folderDetails.setFolderType(TemplateConstants.EMAIL_TEMPLATE);
        folderDetails.setFolderName(TemplateConstants.DRAFTTEMPLATEFOLDER);
        folderDetails.setDescription(TemplateConstants.DRAFTTEMPLATEFOLDER);

        // safely delete template folder
        templatesHandler.preTemplateFolderDelete(folderDetails, this.getClass().getSimpleName());
        dO.deleteRow(folderRow);
        com.zoho.crmcomponents.templates.common.PersistenceUtil.getPersistenceHandle().update(dO);
        templatesHandler.postTemplateFolderDelete(folderDetails, this.getClass().getSimpleName());

        // delete crm config mapping
        DeleteQuery configDq = new DeleteQueryImpl(Table.getTable(CRMCONFIG.TABLE));
        Criteria crt = new Criteria(Column.getColumn(CRMCONFIG.TABLE, CRMCONFIG.CATEGORY), TemplateConstants.CATEGORY_DRAFT_TEMPLATE, QueryConstants.EQUAL);
        crt = crt.and(new Criteria(Column.getColumn(CRMCONFIG.TABLE, CRMCONFIG.CONFIGTYPE), TemplateConstants.TEMPLATE, QueryConstants.EQUAL));
        configDq.setCriteria(crt);
        com.zoho.crmcomponents.templates.common.PersistenceUtil.getPersistenceHandle().delete(configDq);
        LOGGER.info("Removed config table entry for draft template folder");

        LOGGER.info("Deleted draft template folder from CrmTemplateFolder table along with all the draft templates.");

        resultObj.put("status", "purge complete");
        return resultObj;
    }

