    public JSONObject populateActivity()  throws JSONException 
    {    	
    	try {
    		String massmailid = request.getParameter("msgid"); //No I18N
	    	LOGGER.log(Level.INFO, "\n\n\n\n\n   vicki logs for  populateActivity massmailid {0}  \n\n\n\n\n\n\n", new Object[] {massmailid});			
	    	
	    	String massmailidstr[] = {};
			
	    	massmailidstr = EmailsRelatedListAPI.getMessageIdAndMailType(massmailid);		
			massmailid = massmailidstr[0];
			if(massmailid.equals("1")) {
				massmailid = massmailidstr[1];	
			}
	    	
			LOGGER.log(Level.INFO, "\n\n\n\n\n   vicki logs for  populateActivity massmailid 2.0{0}  \n\n\n\n\n\n\n", new Object[] {massmailid});
			JSONObject activityData =  new JSONObject();						
			DataObject dobj = new WritableDataObject();
			
			String type = EmailActivitySuggestionConstants.EVENTS;
			String activityDataStr = "{\"isDataPresent\":false,\"is_created\":false,\"title\":\"mail\",\"type\":\"Events\",\"isExactTimePresent\":false}";  //no i18n
			
			activityData = new JSONObject(activityDataStr);
			for(int i=0;i<3;i++) 
			{			
				Row newActivityRow =  new Row(CRMEMAILACTIVITYEXTRACTIONDETAILS.TABLE);
				
				newActivityRow.set( CRMEMAILACTIVITYEXTRACTIONDETAILS.MASSMAILID, Long.parseLong(massmailid));
				newActivityRow.set(CRMEMAILACTIVITYEXTRACTIONDETAILS.CREATEDTIME,  MailAppsConsumerHandler.getTimeInGMT(null, "GMT", false)); //no i18n			
				
				if(i == 1){ 
					activityDataStr = "{\"isDataPresent\":false,\"is_created\":false,\"title\":\"mail\",\"type\":\"Calls\",\"isExactTimePresent\":false}";   //no i18n
					activityData = new JSONObject(activityDataStr);
					type = EmailActivitySuggestionConstants.CALLS;
				}
				else if(i == 2){
					activityDataStr = "{\"isDataPresent\":false,\"is_created\":false,\"title\":\"activities\",\"type\":\"Tasks\",\"isExactTimePresent\":false}";   //no i18n
					activityData = new JSONObject(activityDataStr);
					type = EmailActivitySuggestionConstants.TASKS;
				}
				
				newActivityRow.set(CRMEMAILACTIVITYEXTRACTIONDETAILS.TYPE, type);								
				newActivityRow.set(CRMEMAILACTIVITYEXTRACTIONDETAILS.ACTIVITYDATA, activityData.toString());
					
				dobj.addRow(newActivityRow);
			}			
			PersistenceCacheUtil.getPersistenceLiteHandle().add(dobj);
			resultObj.put("response", "Activity populated successfully"); //no i18n
    	}
    	catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
		return resultObj;
    }    

