    /**
     * 
     * @return
     * @throws JSONException
     */
    public JSONObject deleteKiosks() throws Exception 
    {
    	LOGGER.log(Level.INFO, "Kiosks Delete Reset Configuration start");
    	Constants constants = new Constants();
    	CrmKioskStatesUtil.clearStaleKioskTabEntries(userId);
    	List<Long> associatedKioskIds = new ArrayList<Long>();
		List<Long> detailViewDeletionKioskIds = new ArrayList<Long>();
    	DataObject kioskDo=  KioskDBService.Get.getKiosksDO(null, null,KioskConstants.KIOSK_READ_MODE.COMPLETE_WITHOUT_CHARTDATA, false, false);
    	Iterator<Row> iter = kioskDo.getRows(CRMPROCESSFLOW.TABLE);
		while(iter.hasNext())
		{
			Row processRow = iter.next();
			Long kioskId = (Long)processRow.get(CRMPROCESSFLOW.PROCESSID);
			Set<Long> kioskIds = new HashSet<Long>();
			kioskIds.add(kioskId);
			detailViewDeletionKioskIds.add(kioskId);
			JSONArray allAssociation = CrmKioskUtil.getKioskAssociations(kioskIds, null, null, null, false);
			if(allAssociation.getJSONObject(0).get(CONSTANTS.kiosk.associations)!=JSONObject.NULL) 
			{
				 JSONArray associations = (JSONArray) allAssociation.getJSONObject(0).get(CONSTANTS.kiosk.associations);
				 Integer len = associations.length();
				 for(int i=0;i<len;i++)
				 {
					 JSONObject assocJson = associations.getJSONObject(i);
					 if(!assocJson.get("type").equals(constants.kiosk.detailview_page))
					 {
						 associatedKioskIds.add(kioskId);
					 }
				 }
				
			}
		}
		KioskUtil.deleteBulkKioskDetailViewAssociations(detailViewDeletionKioskIds);
		
    	Set<KioskDetails>  allFlowDetails = KioskUtil.getAllKioskDetails(kioskDo, new HashMap<String, DataObject>(), KioskConstants.KIOSK_READ_MODE.ESSENTIAL);
    	Set<KioskDetails> toBeDeletedKioskDetails = new HashSet<>();
    	Set<Long> toBeDeletedKioskIds = new HashSet<>();
    	for(KioskDetails kiosk: allFlowDetails)
    	{
    		if(!associatedKioskIds.contains(kiosk.getKioskId()))
    		{
    			toBeDeletedKioskDetails.add(kiosk);
    			toBeDeletedKioskIds.add(kiosk.getKioskId());
    		}
    	}
    	if(userId == null)
        {
        	userId = UserUtil.getCurrentUserId();
        }
    	if(!toBeDeletedKioskDetails.isEmpty())
    	{
        	KioskDBService.Delete.handleDeleteKiosk(toBeDeletedKioskDetails, userId,kioskDo);
    	}
    	LOGGER.log(Level.INFO, "Resetconfig process flows end, deleted KioskIds: {0}, skipped KioskIds: {1}",new Object[] {toBeDeletedKioskIds,associatedKioskIds});
    	if(associatedKioskIds.size()>0)
    	{
        	resultObj.put("response", "Kiosks deleted partially.Some of the Kiosks are associated in other places,those Kiosks have been skipped."); //no i18n
        	resultObj.put("skiped_kiosks", associatedKioskIds);
        	LOGGER.log(Level.INFO, "Resetconfig Kiosks delete skipped KioskIds: {0}",new Object[] {associatedKioskIds});
    	}
    	else if(toBeDeletedKioskIds.size()>0)
    	{
    		CrmDataHubDBService.Delete.removeAllDataHubModule();
    		LOGGER.log(Level.INFO, "Kiosks Datahub Modules Deleted");
        	resultObj.put("response", "Kiosks deleted"); //no i18n
    	}
    	resultObj.put("status", true);
    	LOGGER.log(Level.INFO, "Kiosks Delete Reset Configuration end");
        return resultObj;
    }    

    /**
     * Method to reset component filter given component Ids and user Ids
     * @param componentIds
     * @param userIds
     * @return
     * @throws Exception
     */
    public JSONObject resetComponentFilters(List<Long> componentIds, List<Long> userIds) throws Exception
    {
    	LOGGER.log(Level.INFO, "Component Filter Reset process start");
    	Criteria crt = new Criteria(Column.getColumn(CRMREPADVANCEFILTER.TABLE, CRMREPADVANCEFILTER.TYPE),  com.zoho.crm.analytics.reports.type.FilterType.COMPONENT_FILTERS.getValue(), QueryConstants.EQUAL);
    	if(userIds != null && !userIds.isEmpty())
    	{
    		crt = crt.and(new Criteria(Column.getColumn(CRMREPADVANCEFILTER.TABLE, CRMREPADVANCEFILTER.USERID),  userIds.toArray(new Long[]{}), QueryConstants.IN));
    	}
    	if(componentIds == null || componentIds.isEmpty())
    	{
    		SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMREPADVANCEFILTER.TABLE));
    		sq.addSelectColumn(Column.getColumn(null, "*"));
    		sq.setCriteria(crt);
    		DOIterator doIter = new DOIterator(PersistenceCacheUtil.getPurePersistenceLiteHandle(), sq, 1000);
    		componentIds = componentIds != null ? componentIds: new ArrayList<Long>();

    		while (doIter.hasNext())
    		{
    			DataObject dataObj = doIter.next();
    			@SuppressWarnings("unchecked")
    			Iterator<Row> rows = dataObj.getRows(CRMREPADVANCEFILTER.TABLE);
    			while(rows.hasNext())
    			{
    				Row row = rows.next();
    				Long componentId = (Long) row.get(CRMREPADVANCEFILTER.REPORTID);
    				if(!componentIds.contains(componentId))
    				{
    					componentIds.add(componentId);
    				}
    			}
    		}
    	}
    	if(componentIds.size() > 0)
    	{
    		crt = new Criteria(Column.getColumn(CRMREPADVANCEFILTER.TABLE, CRMREPADVANCEFILTER.REPORTID), componentIds.toArray(new Long[]{}), QueryConstants.IN);
    		CommonDBUtil.deleteWithLimit(CRMREPADVANCEFILTER.TABLE, crt, PersistenceCacheUtil.getPurePersistenceLiteHandle(), componentIds.size());

    		crt = new Criteria(Column.getColumn(CRMCHARTCACHEDATA.TABLE, CRMCHARTCACHEDATA.CHARTCONFIGID), componentIds.toArray(new Long[]{}), QueryConstants.IN);
    		CommonDBUtil.deleteWithLimit(CRMCHARTCACHEDATA.TABLE, crt, PersistenceCacheUtil.getPurePersistenceLiteHandle(), componentIds.size());
    	}
    	resultObj.put("status", true);
    	LOGGER.log(Level.INFO, "Component Filter Reset done successfully");
    	return resultObj;
    }

    /**
     *
     * @return
     * @throws JSONException
     */
    public JSONObject deleteTemplates() throws JSONException {
        try {
            Long zgid = OrgUtil.getCurrentZGID();
            Long userId = UserUtil.getCurrentUserId();

            List<Integer> includeCategories = new ArrayList<Integer>(Arrays.asList(TemplateConstants.CATEGORY_PORTAL_TEMPLATE,TemplateConstants.SYSTEM_DEFAULT_TEMPLATE_FOLDER,TemplateConstants.CUSTOM_FOLDER,TemplateConstants.DRAFT_FOLDER));
            HashSet<Long> accessibleFolders = CrmTemplateUtil.getAllAccessibleFolderIds(userId,true, TemplateConstants.EMAIL_TEMPLATE, includeCategories);
            TemplateParameters templateParameters = new TemplateParameters(TemplateConstants.EMAIL_TEMPLATE);
            templateParameters.setFolderIds(accessibleFolders);
            templateParameters.setTemplateMetaOnly(true);
            templateParameters.setIsTemplateReadFeatureEnabled(CrmTemplateUtil.isTemplateReadFeatureEnabled(zgid));
            templateParameters.setDeletedTemplatesOnly(false);

            int fromIndex = 0;
            int toIndex = 200;
            List<Long> templateIds = new ArrayList<>();
            while (true) {
                templateParameters.setRange(fromIndex);
                List<TemplateDetails> templates = TemplatesCRUD.getInstance().getAllTemplates(templateParameters);
                templateIds.addAll(templates.stream().map(TemplateDetails::getTemplateId).collect(Collectors.toList()));
                if (templates.size() < 200) { break; }
                else {
                    fromIndex = toIndex + 1;
                    toIndex = toIndex + 200;
                }
            }

            fromIndex = 0;
            toIndex = 200;
            templateParameters.setDeletedTemplatesOnly(true);
            while (true) {
                templateParameters.setRange(fromIndex);
                List<TemplateDetails> templates = TemplatesCRUD.getInstance().getAllTemplates(templateParameters);
                templateIds.addAll(templates.stream().map(TemplateDetails::getTemplateId).collect(Collectors.toList()));
                if (templates.size() < 200) { break; }
                else {
                    fromIndex = toIndex + 1;
                    toIndex = toIndex + 200;
                }
            }

            LOGGER.log(Level.INFO, "Template IDs to delete (queried): {0}", new Object[] { templateIds });

            if (!TemplatesUtil.isTemplatesAccessible(templateIds, false, false, accessibleFolders, false, TemplateConstants.EMAIL_TEMPLATE, null, true)) {
                throw new Exception(CrmConstants.INSUFFICIENT_PRIVILEGES);
            }

            JSONObject deletePreCheckReport = CrmTemplateUtil.preDeleteCheck(templateIds, false);
            JSONArray filteredTemplateIds = deletePreCheckReport.getJSONArray("deleteTemplateIds"); // No I18n
            templateIds = filteredTemplateIds.toList().stream().map(Object::toString).map(Long::valueOf).collect(Collectors.toList());

            LOGGER.log(Level.INFO, "Template IDs to delete (filtered): {0}", new Object[] { templateIds });

            DeletedTemplatesInfo deletedTemplatesInfo = TemplatesCRUD.getInstance().deleteTemplates(templateIds, TemplateConstants.EMAIL_TEMPLATE, userId, "RESET"); // no i18n
            String deletedTemplateIds = deletedTemplatesInfo.getDeletedTemplates().stream()
                .map(TemplateDetails::getTemplateId)
                .map(Object::toString)
                .collect(Collectors.joining(PMDConstants.SEMICOLON));

            LOGGER.log(Level.INFO, "Templates deleted ::: templateIds ::: {0}", new Object[] { deletedTemplateIds });
            resultObj.put("response", "Email templates deleted"); //no i18n
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }

        resultObj.put("status", status);
        return resultObj;
    }

