    public JSONObject getDomainVerfCode() throws JSONException {
        try{
            String domainname=request.getParameter("domainname");
            CrmCache cObj=new CrmDefaultCache(MailCachedTables.MAIL_DOMAIN_CONFIG);
            DataObject emailAuthObj =  cObj.getDataObject();
            Criteria cr = new Criteria(Column.getColumn(CRMMAILDOMAINCONFIG.TABLE, CRMMAILDOMAINCONFIG.DOMAINNAME), domainname, QueryConstants.EQUAL);
		    cr  = cr.and(new Criteria(Column.getColumn(CRMMAILDOMAINCONFIG.TABLE, CRMMAILDOMAINCONFIG.SPF_STATUS), 4, QueryConstants.NOT_EQUAL));
            DataObject verfDomain = emailAuthObj.getDataObject(CRMMAILDOMAINCONFIG.TABLE, cr);
            if(verfDomain!=null && !verfDomain.isEmpty()){
                Row row = verfDomain.getRow(CRMMAILDOMAINCONFIG.TABLE);
                resultObj.put("response", (String) row.get(CRMMAILDOMAINCONFIG.VERIFICATION_CODE));
            }
          }catch(Exception e) {
              status = false;
              resultObj.put("response", e.toString());
          }
         resultObj.put("status", status);
         return resultObj;
    }

    public JSONObject updateSPFStatus() throws JSONException {
        try{
          String domainname=request.getParameter("domainname");
          UpdateQuery uq = new UpdateQueryImpl(CRMMAILDOMAINCONFIG.TABLE);
          uq.setCriteria(new Criteria(Column.getColumn(CRMMAILDOMAINCONFIG.TABLE, CRMMAILDOMAINCONFIG.DOMAINNAME), domainname, QueryConstants.EQUAL));
          uq.setUpdateColumn(CRMMAILDOMAINCONFIG.SPF_STATUS,1);
          uq.setUpdateColumn(CRMMAILDOMAINCONFIG.DKIM_STATUS,1);
          uq.setUpdateColumn(CRMMAILDOMAINCONFIG.DKIM_LASTVERIFIEDTIME, DateTimeUtils.getCurrentLongTimeInGMT());
          uq.setUpdateColumn(CRMMAILDOMAINCONFIG.SPF_VERIFIEDTIME, DateTimeUtils.getCurrentLongTimeInGMT());
          PersistenceCacheUtil.getPurePersistenceLiteHandle().update(uq);
        }catch(Exception e) {
            status = false;
            resultObj.put("response", "updateSPFStatus :  Exception e = >"+e.toString());
        }
        resultObj.put("status", status);
        resultObj.put("response", "updateSPFStatus invoked successfully.");//NO I18N
        return resultObj;
  }

	/**
	 * @return
	 * @throws Exception
	 *
	 * UTILITY METHOD to generate header value for inter-DC request authentication
	 */
	public JSONObject getInterDCSecurityHeader() throws Exception {
		String headerValue = "SystemAuth"; //No I18N
		String dcSignature = "";
		try {
			dcSignature = com.adventnet.iam.security.SecurityUtil.getDCSignature();
		} catch(Exception exception) {
			LOGGER.log(Level.SEVERE, "Error in generating DCSignature for INTERDC AUTH !!!");
			status = false;
		}
		headerValue = headerValue + " " + dcSignature;
		JSONObject headerJSON = new JSONObject();
		headerJSON.put("Authorization", headerValue);

		resultObj.put("details", headerJSON);
		resultObj.put("response", "DCSignature generated successfully!");
		resultObj.put("status", status);

		return resultObj;
	}
	
	
	/**
	 * @return
	 * @throws Exception
	 *
	 * UTILITY METHOD to generate header value for inter-DC request authentication
	 */
	public JSONObject initiateLZOrgCloningExport(String sourceZgid) throws Exception {

		try {
				DCMUtil dcmUtil = (DCMUtil) ScopedAccess.getInstance(DCMUtil.class, sourceZgid, TransactionType.REQUIRED);
				dcmUtil.scheduleExportForLZClone(sourceZgid);
				List<Long> sandboxOrgList = SandboxConfigUtil.getAllActiveSandboxZgids(Long.parseLong(sourceZgid));
				for(Long zgid : sandboxOrgList) {
					DCMUtil dcmSandboxUtil = (DCMUtil) ScopedAccess.getInstance(DCMUtil.class, String.valueOf(zgid), TransactionType.REQUIRED);
					dcmSandboxUtil.scheduleExportForLZClone(String.valueOf(zgid));
				}
		} catch(Exception exception) {
			LOGGER.log(Level.SEVERE, "Error in Scheduling DC Migration !!",exception);
			status = false;
		}
		resultObj.put("response", "Scheduled DC Migration Successfully");
		resultObj.put("status", status);

		return resultObj;
	}
	
