	/**
	 * @return
	 * @throws Exception
	 *
	 * UTILITY METHOD to generate header value for inter-DC request authentication
	 */
	public JSONObject initiateLZOrgCloning(JSONObject iamMapping) throws Exception {

		try {
			for(String zgid : JSONObject.getNames(iamMapping.getJSONObject("serviceorg"))) {
				String destinationZgid = iamMapping.getJSONObject("serviceorg").getString(zgid);
				DCMUtil dcmUtil = (DCMUtil) ScopedAccess.getInstance(DCMUtil.class, destinationZgid, TransactionType.REQUIRED);
				dcmUtil.scheduleImportForLZClone(destinationZgid, zgid, iamMapping);
			}

		} catch(Exception exception) {
			LOGGER.log(Level.SEVERE, "Error in Scheduling DC Migration !!",exception);
			status = false;
		}
		resultObj.put("response", "Scheduled DC Migration Successfully");
		resultObj.put("status", status);

		return resultObj;
	}

