     public JSONObject authenticateDomain() throws Exception{
    	
        String email=request.getParameter("email");
		Long zgid = OrgUtil.getCurrentZGID();
		
		try {
		if(  ProfileUtil.isAdminProfileUser(currentUserId)  ){ 
			
			EmailAuthenticationUtil emailAuth = EmailAuthenticationUtil.getInstance();
			EmailAuthentication emailAuthImp = new EmailAuthenticationImpl();
			JSONArray authRow = emailAuth.generateDomainKey(currentUserId,String.valueOf(zgid),email, "Domains",emailAuthImp);//NO I18N
			if(authRow!= null && authRow.length() > 0) {
				JSONObject data =  authRow.getJSONObject(0).getJSONArray("auth_records").getJSONObject(0);//NO I18N
				DataObject dbObj = emailAuthImp.getDataObjectofDomain(data.getLong("domain_id"));//NO I18N
				EmailAuthUtil.setDomainVerification(data.getLong("domain_id"),dbObj,emailAuthImp);//NO I18N
				EmailAuthUtil.validateDomain(data.getLong("domain_id"), emailAuthImp, null);//NO I18N
		        resultObj.put("response", "Domain authenticated succesfully");//NO I18N
				
			}else {
		        resultObj.put("response", "Error in domain authentication");//NO I18N				
			}
		}else {
			resultObj.put("response","Permission denied to perform this operation");// No I18N
			status = false;
		}
    		
    	}catch (Exception e) {
    		status = false;
            resultObj.put("response", "authenticateDomain :  Exception e = >"+e.toString());
    	}
    	resultObj.put("status", status);
        return resultObj;
    }
