    public JSONObject delete_allprocess() throws JSONException {
        try {
            String moduleFromReq = request.getParameter("module");
            if(moduleFromReq != null){
                modules = new String[]{moduleFromReq};
            }

            HashMap<String, Set < Long >> actionVsIdMap = collectActionsVsIdMap(modules);
            for (String module: modules) {
                BlueprintConfigUtil.deleteAllBlueprintForModule(currentUserId, module,true);
                List<AUTOMATION_FEATURES> features=CrmAutomationUtil.getFeatureObjList(new AUTOMATION_FEATURES[]{AUTOMATION_FEATURES.BLUEPRINT_TRANSITION});
                String zgId = OrgUtil.getCurrentZGID().toString();
        		boolean isSandboxAccount = OrgUtil.isSandboxAccount();
                WFWebHookUtil.deleteAllWebHooksForModule(module,features,FROMSRC.DELETE,zgId,isSandboxAccount);
            }
            BlueprintConfigUtil.deleteAllBlueprintForModule(currentUserId,"CustomModule1",true); //no i18n
            for (Entry<String, Set < Long >> actionVsIds: actionVsIdMap.entrySet()) {
            	WorkFlowActionsMigUtil.deleteActionsInOldTable(actionVsIds.getKey(), new ArrayList<>(actionVsIds.getValue()));
            	WorkFlowActionsUtil.deleteAutomationActions(new ArrayList<>(actionVsIds.getValue()));
            }
            resultObj.put("response", "Deleted Buttons Deleted successfully");
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        modules = getModulesList();
        resultObj.put("status", status);
        return resultObj;
    }

    private HashMap < String, Set < Long >> collectActionsVsIdMap(final String[] modules) throws Exception {
    	final DataObject tabsDO = TabUtil.getAllTabsCachedDO();
    	final Set < Long > tabIds = AutomationCommonUtil.extractColumnValue(tabsDO, CRMTAB.TABLE, CRMTAB.TABID, new Criteria(Column.getColumn(CRMTAB.TABLE, CRMTAB.NAME), modules, QueryConstants.IN));
    	final SelectQuery processQry = new SelectQueryImpl(Table.getTable(CRMPROCESSFLOW.TABLE));
    	processQry.addSelectColumn(Column.getColumn(CRMPROCESSFLOW.TABLE, CRMPROCESSFLOW.PROCESSID));
    	processQry.addSelectColumn(Column.getColumn(CRMFLOWTRANSITIONS.TABLE, CRMFLOWTRANSITIONS.TRANSITIONRELID));
    	processQry.addSelectColumn(Column.getColumn(CRMFLOWTRANSITIONS.TABLE, CRMFLOWTRANSITIONS.TRANSITIONID));
    	processQry.addSelectColumn(Column.getColumn(CRMFLOWTRANSITIONS.TABLE, CRMFLOWTRANSITIONS.PROCESSID));
    	processQry.addSelectColumn(Column.getColumn(CRMPROCESSSTATE.TABLE, CRMPROCESSSTATE.STATEID));
    	processQry.addSelectColumn(Column.getColumn(CRMPROCESSSTATE.TABLE, CRMPROCESSSTATE.PROCESSID));

    	processQry.addJoin(new Join(CRMPROCESSFLOW.TABLE, CRMFLOWTRANSITIONS.TABLE, new String[] { CRMPROCESSFLOW.PROCESSID }, new String[] { CRMFLOWTRANSITIONS.PROCESSID }, Join.LEFT_JOIN));
    	processQry.addJoin(new Join(CRMPROCESSFLOW.TABLE, CRMPROCESSSTATE.TABLE, new String[] { CRMPROCESSFLOW.PROCESSID }, new String[] { CRMPROCESSSTATE.PROCESSID }, Join.LEFT_JOIN));

    	processQry.setCriteria(new Criteria(Column.getColumn(CRMPROCESSFLOW.TABLE, CRMPROCESSFLOW.TABID), tabIds.toArray(), QueryConstants.IN));
    	final DataObject processDO = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(processQry);
    	final CrmAutomationCacheObject actionscacheObj = CrmAutomationUtil.getAutomationCacheObject(currentUserId);

    	final String[] actions = new String[] {
    		WorkFlowActionsUtil.ACTIONS.WEBHOOK.Name(),
    		WorkFlowActionsUtil.ACTIONS.DELUGE.Name(),
    		WorkFlowActionsUtil.ACTIONS.ALERT.Name(),
    		WorkFlowActionsUtil.ACTIONS.TASK.Name(),
    		WorkFlowActionsUtil.ACTIONS.FIELDUPDATE.Name(),
    		WorkFlowActionsUtil.ACTIONS.CIRCUITS.Name()
    	};

    	final HashMap < String, Set < Long >> actionVsIdMap = new HashMap < String, Set < Long >> ();
    	for (String action : actions) {
    		actionVsIdMap.put(action, new HashSet<>());
    	}

    	final Set < Long > transitionIds = AutomationCommonUtil.extractColumnValue(processDO, CRMFLOWTRANSITIONS.TABLE, CRMFLOWTRANSITIONS.TRANSITIONID, null);
    	for (Long transitionId: transitionIds) {
    		HashMap < String, List < JSONObject >> associatedActions = WFRuleAssociatedActions.getActionsRelatedToTransition(transitionId, actionscacheObj);
    		for (String action: actions) {
    			if (associatedActions != null && associatedActions.containsKey(action)) {
    				associatedActions.get(action).forEach(actionObj -> actionVsIdMap.get(action).add(Long.valueOf(actionObj.get(ProcessFlowConstants.API_ID).toString())));
    			}
    		}
    	}

    	final Set < Long > stateIds = AutomationCommonUtil.extractColumnValue(processDO, CRMPROCESSSTATE.TABLE, CRMPROCESSSTATE.STATEID, null);
    	final DataObject actionsDoObj = WorkFlowRuleUtil.getActionsRelatedDOForRules(new ArrayList < > (stateIds), true, AUTOMATION_FEATURES.BLUEPRINT_STATE, true);
    	if (actionsDoObj != null) {
    		final Set < Long > triggerIds = AutomationCommonUtil.extractColumnValue(actionsDoObj, CRMTIMETRIGGERS.TABLE, CRMTIMETRIGGERS.TRIGGERID, null);
        	HashMap < Long, HashMap < String, List < JSONObject >>> triggerIdVsAssoActions = WFRuleAssociatedActions.getTriggerIdVsAssoActions(actionsDoObj, new ArrayList < > (triggerIds), actionscacheObj, AUTOMATION_FEATURES.BLUEPRINT_STATE);

        	triggerIdVsAssoActions.values().forEach(associatedActions -> {
        		for (String action: actions) {
        			if (associatedActions != null && associatedActions.containsKey(action)) {
        				associatedActions.get(action).forEach(actionObj -> actionVsIdMap.get(action).add(Long.valueOf(actionObj.get(ProcessFlowConstants.API_ID).toString())));
        			}
        		}
        	});
    	}
    	return actionVsIdMap;
    }

    //Deleting Orphan records - Record's Presence - False in Base Table, But not present in CrmRecycleBin to Delete/Restore
    public JSONObject deleteOrphanRecords() throws JSONException { // ###used
        try {
            String module = request.getParameter("module");
            String moduleBaseTable = EntityMetaDataUtil.getBaseTableByModuleName(module);
            if (moduleBaseTable != null) {
                String modulePK = EntityMetaDataUtil.getPKColumnName(moduleBaseTable);
                SelectQuery sq = new SelectQueryImpl(Table.getTable(moduleBaseTable));
                Join rbJoin = new Join(Table.getTable(moduleBaseTable), Table.getTable(CRMRECYCLEBIN.TABLE), new String[] { modulePK }, new String[] { CRMRECYCLEBIN.SEID }, Join.LEFT_JOIN);
                sq.addJoin(rbJoin);
                Criteria deletedRecordsCri = new Criteria(Column.getColumn(moduleBaseTable, CrmConstants.SE_PRESENCE), RecordConstants.RecordStatus.DELETED.getStatus(), QueryConstants.EQUAL);
                Criteria rbSeidNullCri = new Criteria(Column.getColumn(CRMRECYCLEBIN.TABLE, CRMRECYCLEBIN.SEID), null, QueryConstants.EQUAL);
                Criteria cri = deletedRecordsCri.and(rbSeidNullCri);
                sq.setCriteria(cri);
                sq.addSelectColumn(Column.getColumn(moduleBaseTable, modulePK));
                Persistence persistence = PersistenceCacheUtil.getPurePersistenceLiteHandle();
                DOIterator doIter = new DOIterator(persistence, sq, 1, false);
                while (doIter.hasNext()) {
                    DataObject dobj = doIter.next();
                    @SuppressWarnings("unchecked")
					Iterator<Row> rowIter = dobj.getRows(moduleBaseTable);
                    List<Long> orphanRecordIds = new ArrayList<>();
                    while (rowIter.hasNext()) {
                        orphanRecordIds.add((Long) rowIter.next().get(modulePK));
                    }
                    HashMap<String, List<Long>> moduleVsIds = new HashMap<>();
                    moduleVsIds.put(module, orphanRecordIds);
                    RecycleBinUtil.deleteFromRecyclebin(currentUserId, null, "", moduleVsIds, null, null, false, false);
                }
                resultObj.put("response", "Orphan Records Deleted in Module " + module); //no i18n
            }
            else {
                resultObj.put("response", module + " is not a valid Module"); //no i18n
            }
        } catch (Exception e) {
            status = false;
            resultObj.put("response", "Exception while deleting Orphan records :: " + e.getMessage() + ""); //no i18n
        }
        resultObj.put("status", status);
        return resultObj;
    }

