    public JSONObject triggerWebformABTestingScheduler() throws JSONException
    {
        try
        {
        	String zgid = OrgUtil.getCurrentZGID().toString();
        	String abtestId = request.getParameter("abtestId");

    		SelectQueryImpl sqry = new SelectQueryImpl(Table.getTable(CRMSCHEDULEDJOBS.TABLE));
    		sqry.addSelectColumn(Column.getColumn(null,"*"));
    		Criteria cri = new Criteria(Column.getColumn(CRMSCHEDULEDJOBS.TABLE, CRMSCHEDULEDJOBS.ACTIONINFO), zgid, QueryConstants.CONTAINS);
    		cri = cri.and(new Criteria(Column.getColumn(CRMSCHEDULEDJOBS.TABLE, CRMSCHEDULEDJOBS.ACTIONINFO), abtestId, QueryConstants.CONTAINS));
    		sqry.setCriteria(cri);
    		sqry.setRange(new Range(0, 1));
    		DataObject scheduleDo = PersistenceCacheUtil.getPersistenceLiteHandle(zgid).get(sqry);
    		if(!scheduleDo.isEmpty()){
    			Row scheduleRow = scheduleDo.getRow(CRMSCHEDULEDJOBS.TABLE);
    			Long jobId = (Long) scheduleRow.get(CRMSCHEDULEDJOBS.JOBID);
    			Job jobInfo = ZohoCRMSchedule.getJobObjectById(jobId, CoreScheduleConstants.ONETIME_LOW_PROCESS);
    			if(jobInfo != null){
        			jobId = jobInfo.getJobID();
            		ZohoCRMSchedule.updateOneTimeJob(jobId, CoreScheduleConstants.ONETIME_LOW_PROCESS, true, new Timestamp(System.currentTimeMillis()));
                    LOGGER.log(Level.INFO, "WebformABTestingScheduler:::"+jobId+":::reschedule to time : "+new Timestamp(System.currentTimeMillis()));
                    resultObj.put("response", "WebformABTestingScheduler schedule time updated to current time");
        		}
    		}
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }

