    public JSONObject resetConversionMappingForModule() throws Exception {
    	String tableName = null;
    	String module = request.getParameter("module");//no i18n
    	if(module == null || "".equals(module)){
    		status = false;
    		resultObj.put("status", status);
    		resultObj.put("response", "Module Param is not sent"); //no i18n
    		return resultObj;
    	}
    	Persistence per = PersistenceCacheUtil.getPurePersistenceLiteHandle();
    	DataObject finalDO = per.constructDataObject();
    	String zgid = OrgUtil.getCurrentZGID().toString();
    	try{
    		if(CrmModuleConstants.LEADS.equals(module)){
        		Long leadTabId = TabUtil.getTabIdByName(CrmModuleConstants.LEADS);
        		Long contactTabId = TabUtil.getTabIdByName(CrmModuleConstants.CONTACTS);
        		Long accountTabId = TabUtil.getTabIdByName(CrmModuleConstants.ACCOUNTS);
        		Long potentialTabId = TabUtil.getTabIdByName(CrmModuleConstants.POTENTIALS);
        		tableName = CRMLEADCONVERTMAP.TABLE;
        		DeleteQueryImpl del = new DeleteQueryImpl(tableName);
        		del.setCriteria(new Criteria(Column.getColumn(tableName, CRMLEADCONVERTMAP.LEADCUSTOMFIELDID), null, QueryConstants.NOT_EQUAL));
        		per.delete(del);
        		DeleteQueryImpl delete = new DeleteQueryImpl(CRMLEADCONVERTLAYOUTMAP.TABLE);
        		delete.setCriteria( new Criteria(Column.getColumn(CRMLEADCONVERTLAYOUTMAP.TABLE, CRMLEADCONVERTLAYOUTMAP.LEADLAYOUTID), null, QueryConstants.NOT_EQUAL));
        		per.delete(delete);
        		HashMap<String,List> defaultMappings = getDefaultConversionMapForModule(CrmModuleConstants.LEADS);
        		DataObject leadDO = FieldUtil.getCrmFieldsDOForModule(CrmModuleConstants.LEADS,zgid);
        		DataObject accountDO = FieldUtil.getCrmFieldsDOForModule(CrmModuleConstants.ACCOUNTS,zgid);
        		DataObject contactDO = FieldUtil.getCrmFieldsDOForModule(CrmModuleConstants.CONTACTS,zgid);
        		DataObject potentialDO = FieldUtil.getCrmFieldsDOForModule(CrmModuleConstants.POTENTIALS,zgid);
        		Iterator<String> it = defaultMappings.keySet().iterator();
        		while(it.hasNext()){
        			String leadField = it.next();
        			List<String> mappings = (List<String>) defaultMappings.get(leadField);
        			Criteria cr1 = new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDLABEL),leadField,QueryConstants.EQUAL);
        			cr1 = cr1.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.TABID),leadTabId,QueryConstants.EQUAL));
            		Row leadRow = leadDO.getRow(CRMFIELD.TABLE, cr1);
            		if(leadRow != null){
            			Row mappingRow = new Row(CRMLEADCONVERTMAP.TABLE);
                		Long layoutId = PageLayoutUtil.getMasterLayoutIdForTabId(TabUtil.getTabIdByName(module));
                		mappingRow.set(CRMLEADCONVERTMAP.LEADCUSTOMFIELDID,(Long)leadRow.get(CRMFIELD.FIELDID));
                		mappingRow.set(CRMLEADCONVERTMAP.LEADLAYOUTID, layoutId);
                    	for(int i = 0; i < 3; i++){
                    		String fieldLabel = mappings.get(i);
                    		if(fieldLabel != null){
                    			Criteria cr = new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDLABEL),fieldLabel,QueryConstants.EQUAL);
                    			switch(i){
                        		case 0 :
                        			cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.TABID),accountTabId,QueryConstants.EQUAL));
                        			Row accountRow = accountDO.getRow(CRMFIELD.TABLE, cr);
                        			if(accountRow != null){
                        				mappingRow.set(CRMLEADCONVERTMAP.ACCOUNTCUSTOMFIELDID, (Long)accountRow.get(CRMFIELD.FIELDID));
                        			}
                        			break;
                        		case 1 :
                        			cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.TABID),contactTabId,QueryConstants.EQUAL));
                        			Row contactRow = contactDO.getRow(CRMFIELD.TABLE, cr);
                        			if(contactRow != null){
                        				mappingRow.set(CRMLEADCONVERTMAP.CONTACTCUSTOMFIELDID, (Long)contactRow.get(CRMFIELD.FIELDID));
                        			}
                        			break;
                        		case 2 :
                        			cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.TABID),potentialTabId,QueryConstants.EQUAL));
                        			Row potentialRow = potentialDO.getRow(CRMFIELD.TABLE, cr);
                        			if(potentialRow != null){
                        				mappingRow.set(CRMLEADCONVERTMAP.POTENTIALCUSTOMFIELDID, (Long)potentialRow.get(CRMFIELD.FIELDID));
                        			}
                        			break;
                        		}
                    		}
                    	}
                    	finalDO.addRow(mappingRow);
            		}
        		}
        		Row layoutMappingRow = new Row(CRMLEADCONVERTLAYOUTMAP.TABLE);
            	layoutMappingRow.set(CRMLEADCONVERTLAYOUTMAP.LEADLAYOUTID, PageLayoutUtil.getMasterLayoutIdForTabId(leadTabId));
            	layoutMappingRow.set(CRMLEADCONVERTLAYOUTMAP.ACCOUNTLAYOUTID, PageLayoutUtil.getMasterLayoutIdForTabId(accountTabId));
            	layoutMappingRow.set(CRMLEADCONVERTLAYOUTMAP.CONTACTLAYOUTID, PageLayoutUtil.getMasterLayoutIdForTabId(contactTabId));
            	layoutMappingRow.set(CRMLEADCONVERTLAYOUTMAP.POTENTIALLAYOUTID, PageLayoutUtil.getMasterLayoutIdForTabId(potentialTabId));
            	finalDO.addRow(layoutMappingRow);
        	}
    		else if(CrmModuleConstants.QUOTES.equals(module) || CrmModuleConstants.SALESORDERS.equals(module)){
        		
        		tableName = CRMQSCONVERTMAP.TABLE;
        		DeleteQueryImpl del = new DeleteQueryImpl(tableName);
        		del.setCriteria(new Criteria(Column.getColumn(tableName, CRMQSCONVERTMAP.PARENTMODULEFIELDID), null, QueryConstants.NOT_EQUAL));
        		per.delete(del);
        		DeleteQueryImpl delete = new DeleteQueryImpl(CRMQSLAYOUTCONVERTMAP.TABLE);
        		delete.setCriteria( new Criteria(Column.getColumn(CRMQSLAYOUTCONVERTMAP.TABLE, CRMQSLAYOUTCONVERTMAP.PARENTMODULELAYOUTID), null, QueryConstants.NOT_EQUAL));
        		per.delete(delete);

        		Long quoteTabId = TabUtil.getTabIdByName(CrmModuleConstants.QUOTES);
        		Long salesOrderTabId = TabUtil.getTabIdByName(CrmModuleConstants.SALESORDERS);
        		Long invoiceTabId = TabUtil.getTabIdByName(CrmModuleConstants.INVOICES);
        		Long quoteLineItemTabId = TabUtil.getTabIdByName(CrmModuleConstants.QUOTEDITEMS);
        		Long soLineItemTabId = TabUtil.getTabIdByName(CrmModuleConstants.ORDEREDITEMS);
        		Long invLineItemTabId = TabUtil.getTabIdByName(CrmModuleConstants.INVOICEDITEMS);
        		
        		DataObject quoteDO = FieldUtil.getCrmFieldsDOForModule(CrmModuleConstants.QUOTES,zgid);
        		DataObject salesOrderDO = FieldUtil.getCrmFieldsDOForModule(CrmModuleConstants.SALESORDERS,zgid);
        		DataObject invoiceDO = FieldUtil.getCrmFieldsDOForModule(CrmModuleConstants.INVOICES,zgid);
        		DataObject quoteLineItemDO = FieldUtil.getCrmFieldsDOForModule(CrmModuleConstants.QUOTEDITEMS,zgid);
        		DataObject soLineItemDO = FieldUtil.getCrmFieldsDOForModule(CrmModuleConstants.ORDEREDITEMS,zgid);
        		DataObject invLineItemDO = FieldUtil.getCrmFieldsDOForModule(CrmModuleConstants.INVOICEDITEMS,zgid);
        		
        		//Quote default mapping
        		HashMap<String,List> defaultMappings = getDefaultConversionMapForModule(CrmModuleConstants.QUOTES);
        		Iterator<Map.Entry<String,List>> it = defaultMappings.entrySet().iterator();
        		while(it.hasNext()){
        			Map.Entry<String,List> entry = it.next();
        			String parField = entry.getKey();
        			List<String> mappings = entry.getValue();
        			Criteria cr1 = new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDLABEL),parField,QueryConstants.EQUAL);
        			cr1 = cr1.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.TABID),quoteTabId,QueryConstants.EQUAL));
            		Row quoteRow = quoteDO.getRow(CRMFIELD.TABLE, cr1);
            		if(quoteRow != null){
            			Row mappingRow = new Row(CRMQSCONVERTMAP.TABLE);
                		Long layoutId = PageLayoutUtil.getMasterLayoutIdForTabId(TabUtil.getTabIdByName(CrmModuleConstants.QUOTES));
                		mappingRow.set(CRMQSCONVERTMAP.PARENTMODULEFIELDID,(Long)quoteRow.get(CRMFIELD.FIELDID));
                		mappingRow.set(CRMQSCONVERTMAP.PARENTMODULELAYOUTID, layoutId);
                    	for(int i = 0; i < 2; i++){
                    		String fieldLabel = mappings.get(i);
                    		if(fieldLabel != null){
                    			Criteria cr = new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDLABEL),fieldLabel,QueryConstants.EQUAL);
                    			switch(i){
                        		case 0 :
                        			cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.TABID),salesOrderTabId,QueryConstants.EQUAL));
                        			Row salesOrderRow = salesOrderDO.getRow(CRMFIELD.TABLE, cr);
                        			if(salesOrderRow != null){
                        				mappingRow.set(CRMQSCONVERTMAP.CHILDMODULE1FIELDID, (Long)salesOrderRow.get(CRMFIELD.FIELDID));
                        			}
                        			break;
                        		case 1 :
                        			cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.TABID),invoiceTabId,QueryConstants.EQUAL));
                        			Row invoiceRow = invoiceDO.getRow(CRMFIELD.TABLE, cr);
                        			if(invoiceRow != null){
                        				mappingRow.set(CRMQSCONVERTMAP.CHILDMODULE2FIELDID, (Long)invoiceRow.get(CRMFIELD.FIELDID));
                        			}
                        			break;
                        		}
                    		}
                    	}
                    	finalDO.addRow(mappingRow);
            		}
        		}
        		
        		//QuoteLineItem default mapping
        		defaultMappings = getDefaultConversionMapForModule(CrmModuleConstants.QUOTEDITEMS);
        		Iterator<Map.Entry<String,List>> quoteLI = defaultMappings.entrySet().iterator();
        		while(quoteLI.hasNext()){
        			Map.Entry<String,List> entry = quoteLI.next();
        			String quoteLIField = entry.getKey();
        			List<String> mappings = entry.getValue();
        			Criteria cr1 = new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDLABEL),quoteLIField,QueryConstants.EQUAL);
        			cr1 = cr1.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.TABID),quoteLineItemTabId,QueryConstants.EQUAL));
            		Row quoteRow = quoteLineItemDO.getRow(CRMFIELD.TABLE, cr1);
            		if(quoteRow != null){
            			Row mappingRow = new Row(CRMQSCONVERTMAP.TABLE);
                		Long layoutId = PageLayoutUtil.getMasterLayoutIdForTabId(TabUtil.getTabIdByName(CrmModuleConstants.QUOTES));
                		mappingRow.set(CRMQSCONVERTMAP.PARENTMODULEFIELDID,(Long)quoteRow.get(CRMFIELD.FIELDID));
                		mappingRow.set(CRMQSCONVERTMAP.PARENTMODULELAYOUTID, layoutId);
                    	for(int i = 0; i < 2; i++){
                    		String fieldLabel = mappings.get(i);
                    		if(fieldLabel != null){
                    			Criteria cr = new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDLABEL),fieldLabel,QueryConstants.EQUAL);
                    			switch(i){
                        		case 0 :
                        			cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.TABID),soLineItemTabId,QueryConstants.EQUAL));
                        			Row salesOrderRow = soLineItemDO.getRow(CRMFIELD.TABLE, cr);
                        			if(salesOrderRow != null){
                        				mappingRow.set(CRMQSCONVERTMAP.CHILDMODULE1FIELDID, (Long)salesOrderRow.get(CRMFIELD.FIELDID));
                        			}
                        			break;
                        		case 1 :
                        			cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.TABID),invLineItemTabId,QueryConstants.EQUAL));
                        			Row invoiceRow = invLineItemDO.getRow(CRMFIELD.TABLE, cr);
                        			if(invoiceRow != null){
                        				mappingRow.set(CRMQSCONVERTMAP.CHILDMODULE2FIELDID, (Long)invoiceRow.get(CRMFIELD.FIELDID));
                        			}
                        			break;
                        		}
                    		}
                    	}
                    	finalDO.addRow(mappingRow);
            		}
        		}
        		
        		//salesOrder default mapping
        		defaultMappings = getDefaultConversionMapForModule(CrmModuleConstants.SALESORDERS);
        		Iterator<Map.Entry<String,List>> so = defaultMappings.entrySet().iterator();
        		while(so.hasNext()){
        			Map.Entry<String,List> so_entry = so.next();
        			String soField = so_entry.getKey();
        			List<String> so_mappings = so_entry.getValue();

        			Criteria cr2 = new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDLABEL),soField,QueryConstants.EQUAL);
        			cr2 = cr2.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.TABID),salesOrderTabId,QueryConstants.EQUAL));
        			Row salesOrderRow = salesOrderDO.getRow(CRMFIELD.TABLE, cr2);
            		if(salesOrderRow != null){
            			Row mappingRow = new Row(CRMQSCONVERTMAP.TABLE);
                		Long layoutId = PageLayoutUtil.getMasterLayoutIdForTabId(TabUtil.getTabIdByName(CrmModuleConstants.SALESORDERS));
                		mappingRow.set(CRMQSCONVERTMAP.PARENTMODULEFIELDID,(Long)salesOrderRow.get(CRMFIELD.FIELDID));
                		mappingRow.set(CRMQSCONVERTMAP.PARENTMODULELAYOUTID, layoutId);
                		String fieldLabel = so_mappings!=null ? so_mappings.get(0) : null;
                		if(fieldLabel != null){
                			Criteria cr = new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDLABEL),fieldLabel,QueryConstants.EQUAL);
                    		cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.TABID),invoiceTabId,QueryConstants.EQUAL));
                    		Row invoiceRow = invoiceDO.getRow(CRMFIELD.TABLE, cr);
                    		if(invoiceRow != null){
                    			mappingRow.set(CRMQSCONVERTMAP.CHILDMODULE2FIELDID, (Long)invoiceRow.get(CRMFIELD.FIELDID));
                    		}
                		}
                    	finalDO.addRow(mappingRow);
            		}
        		}
        		
        		//salesOrderLineItem default mapping
        		defaultMappings = getDefaultConversionMapForModule(CrmModuleConstants.ORDEREDITEMS);
        		Iterator<Map.Entry<String,List>> soLineItem = defaultMappings.entrySet().iterator();
        		while(soLineItem.hasNext()){
        			Map.Entry<String,List> soLineItem_entry = soLineItem.next();
        			String soLineItemField = soLineItem_entry.getKey();
        			List<String> soLineItem_mappings = soLineItem_entry.getValue();

        			Criteria cr2 = new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDLABEL),soLineItemField,QueryConstants.EQUAL);
        			cr2 = cr2.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.TABID),soLineItemTabId,QueryConstants.EQUAL));
        			Row salesOrderRow = soLineItemDO.getRow(CRMFIELD.TABLE, cr2);
            		if(salesOrderRow != null){
            			Row mappingRow = new Row(CRMQSCONVERTMAP.TABLE);
                		Long layoutId = PageLayoutUtil.getMasterLayoutIdForTabId(TabUtil.getTabIdByName(CrmModuleConstants.SALESORDERS));
                		mappingRow.set(CRMQSCONVERTMAP.PARENTMODULEFIELDID,(Long)salesOrderRow.get(CRMFIELD.FIELDID));
                		mappingRow.set(CRMQSCONVERTMAP.PARENTMODULELAYOUTID, layoutId);
                		String fieldLabel = soLineItem_mappings!=null ? soLineItem_mappings.get(0) : null;
                		if(fieldLabel != null){
                			Criteria cr = new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDLABEL),fieldLabel,QueryConstants.EQUAL);
                    		cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.TABID),invLineItemTabId,QueryConstants.EQUAL));
                    		Row invoiceRow = invLineItemDO.getRow(CRMFIELD.TABLE, cr);
                    		if(invoiceRow != null){
                    			mappingRow.set(CRMQSCONVERTMAP.CHILDMODULE2FIELDID, (Long)invoiceRow.get(CRMFIELD.FIELDID));
                    		}
                		}
                    	finalDO.addRow(mappingRow);
            		}
        		}
            		
        		Row quotelayoutMappingRow = new Row(CRMQSLAYOUTCONVERTMAP.TABLE);
        		quotelayoutMappingRow.set(CRMQSLAYOUTCONVERTMAP.PARENTMODULELAYOUTID, PageLayoutUtil.getMasterLayoutIdForTabId(quoteTabId));
        		quotelayoutMappingRow.set(CRMQSLAYOUTCONVERTMAP.CHILDMODULE1LAYOUTID, PageLayoutUtil.getMasterLayoutIdForTabId(salesOrderTabId));
            	quotelayoutMappingRow.set(CRMQSLAYOUTCONVERTMAP.CHILDMODULE2LAYOUTID, PageLayoutUtil.getMasterLayoutIdForTabId(invoiceTabId));
            	finalDO.addRow(quotelayoutMappingRow);
            	
            	Row solayoutMappingRow = new Row(CRMQSLAYOUTCONVERTMAP.TABLE);
            	solayoutMappingRow.set(CRMQSLAYOUTCONVERTMAP.PARENTMODULELAYOUTID, PageLayoutUtil.getMasterLayoutIdForTabId(salesOrderTabId));
            	solayoutMappingRow.set(CRMQSLAYOUTCONVERTMAP.CHILDMODULE2LAYOUTID, PageLayoutUtil.getMasterLayoutIdForTabId(invoiceTabId));
            	finalDO.addRow(solayoutMappingRow);
    		}
        	per.update(finalDO);
        	resultObj.put("status", true);
    	}catch(Exception e){
    		status = false;
    		resultObj.put("status", status);
    		resultObj.put("response", "Exception while resetting Conversion Mapping for :: " + module +" :: " + e.getStackTrace()); //no i18n
    	}
    	return resultObj;
    }

