    public JSONObject conversionMappingFieldsToDefault()throws JSONException {
        try{
            Long tabid = TabUtil.getTabIdByAPIName(CrmModuleConstants.LEADS);
            SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMFIELD.TABLE));
            sq.addSelectColumn(Column.getColumn(CRMFIELD.TABLE,CRMFIELD.FIELDID));
            sq.addSelectColumn(Column.getColumn(CRMFIELD.TABLE,CRMFIELD.TABID));
            sq.addSelectColumn(Column.getColumn(CRMFIELD.TABLE,CRMFIELD.GENERATEDTYPE));
            Criteria cr = new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.GENERATEDTYPE),2,QueryConstants.EQUAL);
            cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.TABID),tabid,QueryConstants.EQUAL));
            sq.setCriteria(cr);
            DataObject dObj = PersistenceCacheUtil.getNonCachePersistenceHandle().get(sq);
            List<Long> fieldIdList = new ArrayList<Long>();
            if(!dObj.isEmpty())
            {
              @SuppressWarnings("unchecked")
			Iterator<Row> it = dObj.getRows(CRMFIELD.TABLE);
              while(it.hasNext())
              {
                Row row = it.next();
                fieldIdList.add((Long) row.get(CRMFIELD.FIELDID));
              }
            }
            if(fieldIdList.size() > 0){
              Criteria leadCFCr = new Criteria(Column.getColumn(CRMLEADCONVERTMAP.TABLE, CRMLEADCONVERTMAP.LEADCUSTOMFIELDID),fieldIdList.toArray(),QueryConstants.IN);
              PersistenceCacheUtil.getNonCachePersistenceHandle().delete(leadCFCr);
              resultObj.put("response","Successful"); //no i18n
            }
            else{
                resultObj.put("response","No Custom Field"); //no i18n
            }

          }
          catch(Exception e){
              resultObj.put("response", "Exception while deleting Orphan records :: " + e.getMessage() + ""); //no i18n
          }
        return resultObj;
    }

