    public JSONObject duplicateJourney()throws Exception
    {
    	try
    	{
    		String id = (String) request.getParameter("id");
    		int count = Integer.parseInt((String) request.getParameter("count"));
    		int journeyLimit = OrchestrationConfigUtil.getJourneyGroupLimit();
    		DataObject journeyDO = JourneyConfigDBService.Get.getJourneysDO(false);
    		HashSet<Long> groupIds = OrchestrationConfigUtil.getGroupIds(journeyDO);
    		if(groupIds.size() + count > journeyLimit) {
    			status = false;
    			resultObj.put("response", "Limit exceeded");
    		}
			CommandCenterReseller reseller = (CommandCenterReseller)ScopedAccess.getInstance(CommandCenterReseller.class, OrgUtil.getCurrentZGID().toString(), TransactionType.REQUIREDNEW);
			reseller.createJourneyCopy(count, Long.parseLong(id));
    	}
    	catch(Exception e)
    	{
    		status = false;
    		resultObj.put("response", e.toString());
    	}
    	resultObj.put("status", status);
    	return resultObj;
    }
    
    public JSONObject deleteParentAndRenameDraftJourney()throws Exception
    {
    	try
    	{
    		String parentId = (String) request.getParameter("parentId");
    		String duplicateJourneyId = (String) request.getParameter("draftId");
    		Journey journey = JourneyConfigUtil.getJourney(Long.parseLong(parentId), CommandCenterConstants.JOURNEY_READ_MODE.COMPLETE);
    		String journeyName = journey.getName();
    		Integer oldJourneyStatus = journey.getStatus();
			JourneyConfigCRUD.getInstance().deleteJourney(Long.parseLong(parentId), CreateUpdateEntityDetails.UI,  OrgUtil.getUserIdOfPrimaryContact(), null);
			Journey duplicateJourney = JourneyConfigUtil.getJourney(Long.parseLong(duplicateJourneyId), CommandCenterConstants.JOURNEY_READ_MODE.COMPLETE);
			duplicateJourney.setName(journeyName);
			JourneyConfigCRUD.getInstance().updateJourney(duplicateJourney, OrgUtil.getUserIdOfPrimaryContact(), CommandCenterConstants.OPERATION.UPDATE);
			if(oldJourneyStatus!=0) {
				JourneyConfigCRUD.getInstance().activateJourney(Long.parseLong(duplicateJourneyId), CreateUpdateEntityDetails.UI, OrgUtil.getUserIdOfPrimaryContact());
			}		
    	}
    	catch(Exception e)
    	{
    		status = false;
    		resultObj.put("response", e.toString());
    	}
    	resultObj.put("status", status);
    	return resultObj;
    }

