    public JSONObject deleteInvalidTabForDeletedOrchestration() throws Exception
    {
    	try {
    		List<String> orchModules = OrchestrationConfigUtil.getOrchestrationModules();
    		Set<Long> tabIds =  TabUtil.getTabIdsByNames(orchModules,null).stream().collect(Collectors.toSet());
			DataObject orchDO = OrchConfigDBService.Get.getOrchestrationsDO(tabIds, true, false, false, false);
			if(tabIds!=null && !tabIds.isEmpty()) {
	    		for(Long tabId : tabIds) {
	    			String module = TabUtil.getTabNameById(tabId);
	    			if(orchDO!=null && !orchDO.isEmpty()) {
	    				Row orchRow = orchDO.getRow(CRMPROCESSFLOW.TABLE, new Criteria(Column.getColumn(CRMPROCESSFLOW.TABLE, CRMPROCESSFLOW.PROCESSID), tabId, QueryConstants.EQUAL));
	    				if(orchRow == null) {
	    					if(module!=null)
	    					{
	    						boolean isOrchEntityTableDataAvail = TabUtil.isEntityTableDataAvail(module);
	    						CustomModuleUtil.deleteCustomModule(OrgUtil.getUserIdOfPrimaryContact(), module, null, isOrchEntityTableDataAvail);
	    					}
	    				}
	    			}
	    			else {
						if(module!=null)
						{
							boolean isOrchEntityTableDataAvail = TabUtil.isEntityTableDataAvail(module);
							CustomModuleUtil.deleteCustomModule(OrgUtil.getUserIdOfPrimaryContact(), module, null, isOrchEntityTableDataAvail);
						}
	    			}
	    		}
			}
    	}
    	catch(Exception e) {
    		LOGGER.log(Level.WARNING, "Problem while deleting module in ResetConfigurations", e);
    		status = false;
    		resultObj.put("response", e.toString());
    		LOGGER.log(Level.WARNING,"Exception while deleting orch", e);
    	}
    	resultObj.put("status", status);
		return resultObj;
    }

    public JSONObject deleteInvalidAssosiatedAlertInOrch()throws Exception
    {
    	try
    	{
    		List<Long> toDelAlertIds = new ArrayList<Long>();
			List<Long> orchConfiguredAlertIds = new ArrayList<Long>();

			DataObject alljourneysDO = JourneyConfigDBService.Get.getJourneysDO(true);

			DataObject orchJourneysDO = alljourneysDO.getDataObject(CRMPROCESSFLOW.TABLE, new Criteria(Column.getColumn(CRMPROCESSFLOW.TABLE, CRMPROCESSFLOW.FEATURE_TYPE), AUTOMATION_FEATURES.ORCHESTRATION.getInt(), QueryConstants.EQUAL));
			HashSet<Journey> journeys = JourneyConfigUtil.getJourneys(orchJourneysDO, JOURNEY_READ_MODE.COMPLETE);
			for(Journey journey : journeys) {
				if(journey.getStates() != null) {
					for(com.zoho.crmcomponents.automation.process.state.pojo.State state : journey.getStates()) {
						Actions stateActions = state.getActions();
						if(stateActions != null) {
							if(stateActions.getInstantActions()!=null) {
								for(ActionInfo insAction : stateActions.getInstantActions()) {
									if(insAction.getActionType().equals(WorkFlowActionsUtil.ACTIONS.ALERT.Name())) {
										orchConfiguredAlertIds.add(insAction.getActionId());
									}
								}
							}
							if(stateActions.getScheduledActions() != null) {
								for(ScheduledAction secAction : stateActions.getScheduledActions()) {
									if(secAction.getActions() != null) {
										for(ActionInfo insAction : secAction.getActions()) {
											if(insAction.getActionType().equals(WorkFlowActionsUtil.ACTIONS.ALERT.Name())) {
												orchConfiguredAlertIds.add(insAction.getActionId());
											}
										}
									}
								}
							}
						}
					}
				}
				if(journey.getTransitions() != null) {
					for(Transition transition : journey.getTransitions()) {
						if(transition.getInstantActions() != null) {
							for(ActionInfo actioninfo : transition.getInstantActions()) {
								if(actioninfo.getActionType().equals(WorkFlowActionsUtil.ACTIONS.ALERT.Name())) {
									orchConfiguredAlertIds.add(actioninfo.getActionId());
								}
							}
						}
					}
				}
			}

			SelectQuery sq = new SelectQueryImpl( Table.getTable( CRMWORKFLOWALERT.TABLE ) );
			sq.addSelectColumn( Column.getColumn( null, "*" ) );
			Criteria crt = new Criteria(Column.getColumn(CRMWORKFLOWALERT.TABLE, CRMWORKFLOWALERT.TYPE), AutomationConstants.TYPE_ORCHESTRATION, QueryConstants.EQUAL);
			sq.setCriteria(crt);
			sq.setRange(new Range(0, 50));
			DataObject alertDo = PersistenceCacheUtil.getNonCachePersistenceHandle().get( sq );

			HashSet<Long> availablealertids = OrchestrationExecUtil.collectValues(CRMWORKFLOWALERT.TABLE, CRMWORKFLOWALERT.ALERTID, alertDo, crt);

			for(Long availablealertid : availablealertids) {
				if(!orchConfiguredAlertIds.contains(availablealertid)) {
					toDelAlertIds.add(availablealertid);
				}
			}

			for(Long toDelAlertId : toDelAlertIds) {
				WorkFlowAlertUtil.deleteAlert(toDelAlertId, null, null, true);
			}

    	}
    	catch(Exception e)
    	{
        	LOGGER.log(Level.WARNING, "Problem while deleting invalid assosiated Orchestration in ResetConfigurations", e);
    		status = false;
    		resultObj.put("response", e.toString());
    	}
    	resultObj.put("status", status);
    	return resultObj;
    }

