    /**
	 * Delete partially deleted orchestrations created due to wrong migration file ran 
	 */
    public JSONObject deleteInvalidOrchcreatedThroughMigration() throws Exception
	{
	    try
	    {
	    	Set<Long> validActionIds = new HashSet<>();
			Set<Long> invalidActionIds = new HashSet<>();
			Set<Long> invalidTransitionIds = new HashSet<>();
			Persistence pers = PersistenceCacheUtil.getPurePersistenceLiteHandle();
			Range range = new Range(0,50);

			SelectQuery sq = new SelectQueryImpl(new Table(CRMPROCESSFLOW.TABLE));
			Criteria cri = new Criteria( Column.getColumn(CRMPROCESSFLOW.TABLE, CRMPROCESSFLOW.FEATURE_TYPE), AutomationConstants.TYPE_ORCHESTRATION, QueryConstants.EQUAL);
			sq.addSelectColumn(Column.getColumn(CRMPROCESSFLOW.TABLE, CRMPROCESSFLOW.PROCESSID));
			sq.setCriteria(cri);
			sq.setRange(range);
			DataObject orchDO = pers.get(sq);

			Set<Long> validOrchIds = new HashSet<>();

			// Invalid Process deletion
			DataObject tabDO = TabUtil.getAllTabsCachedDO();
			String[] orchSystemDefinedTabs = {"Orchestration", "OrchestrationState"}; //no I18N
			Criteria orchestrationCr = new Criteria(Column.getColumn(CRMTAB.TABLE, CRMTAB.NAME), EntityMetaDataUtil.ORCHESTRATION_MODULE_NAME_PREFIX, QueryConstants.STARTS_WITH);
			orchestrationCr = orchestrationCr.and(new Criteria(Column.getColumn(CRMTAB.TABLE, CRMTAB.NAME), orchSystemDefinedTabs, QueryConstants.NOT_IN));
	        Iterator<Row> orchTabItr = tabDO.getRows(CRMTAB.TABLE, orchestrationCr);
	        while (orchTabItr.hasNext()) {
				Row orchTabRow = orchTabItr.next();
				String tabName = (String) orchTabRow.get(CRMTAB.NAME);

				// Skipping for valid orch process
				Long tabId = (Long) orchTabRow.get(CRMTAB.TABID);
				Criteria orchtabCriteria = new Criteria(Column.getColumn(CRMPROCESSFLOW.TABLE, CRMPROCESSFLOW.PROCESSID), tabId, QueryConstants.EQUAL);
				Row orchProcessFlow = orchDO.getRow(CRMPROCESSFLOW.TABLE, orchtabCriteria);
				if(orchProcessFlow == null) {

					// delete custom module
					Long tabLastModifieduser = (Long) orchTabRow.get(CRMTAB.MODIFIEDBY);
					CrmModuleUtil.deleteModule(tabLastModifieduser, tabName, null, false);
				} else {
					validOrchIds.add(tabId);
				}
	        }

	        // Invalid FU Actions deletion
	        SelectQuery sq1 = new SelectQueryImpl(new Table(CRMAUTOMATIONACTIONS.TABLE));
			Criteria cri1 = new Criteria( Column.getColumn(CRMAUTOMATIONACTIONS.TABLE, CRMAUTOMATIONACTIONS.FEATURETYPE), AutomationConstants.TYPE_ORCHESTRATION, QueryConstants.EQUAL);
			cri1 = cri1.and(new Criteria(Column.getColumn(CRMAUTOMATIONACTIONS.TABLE, CRMAUTOMATIONACTIONS.ACTIONTYPE),"Fieldupdate",QueryConstants.EQUAL));
			sq1.addSelectColumn(Column.getColumn(CRMAUTOMATIONACTIONS.TABLE, "*"));
			sq1.setCriteria(cri1);
			sq1.setRange(range);
			DataObject actionsDO = pers.get(sq1);

			SelectQuery sq4 = new SelectQueryImpl(new Table(CRMTRANSITIONDETAILS.TABLE));
			Criteria cri4 = new Criteria( Column.getColumn(CRMTRANSITIONDETAILS.TABLE, CRMTRANSITIONDETAILS.FEATURE_TYPE), AutomationConstants.TYPE_ORCHESTRATION, QueryConstants.EQUAL);
			sq4.addSelectColumn(Column.getColumn(CRMTRANSITIONDETAILS.TABLE, CRMTRANSITIONDETAILS.TRANSITIONID));
			sq4.setCriteria(cri4);
			sq4.setRange(range);
			DataObject allOrchTransitonsDO = pers.get(sq4);

			Set<Long> orchTransitionIds = new HashSet<>();
			if(!allOrchTransitonsDO.isEmpty()) {
				orchTransitionIds = OrchestrationExecUtil.collectValues(CRMTRANSITIONDETAILS.TABLE, CRMTRANSITIONDETAILS.TRANSITIONID, allOrchTransitonsDO, null);
			}

	        // Delete Invalid Transitions
			Set<Long> validOrchTransIds = new HashSet<>();
			if(!allOrchTransitonsDO.isEmpty()) {
				SelectQuery sq5 = new SelectQueryImpl(new Table(CRMFLOWTRANSITIONS.TABLE));
				sq5.addSelectColumn(Column.getColumn(CRMFLOWTRANSITIONS.TABLE, CRMFLOWTRANSITIONS.TRANSITIONID));
				sq5.addSelectColumn(Column.getColumn(CRMFLOWTRANSITIONS.TABLE, CRMFLOWTRANSITIONS.PROCESSID));
				sq5.addSelectColumn(Column.getColumn(CRMFLOWTRANSITIONS.TABLE, CRMFLOWTRANSITIONS.TRANSITIONRELID));
				sq5.setCriteria(null);
				sq5.setRange(range);
				DataObject allOrchFlowTransitonsDO = pers.get(sq5);

				if(!allOrchFlowTransitonsDO.isEmpty()) {
					Set<Long> allOrchFlowTransitionIds = OrchestrationExecUtil.collectValues(CRMFLOWTRANSITIONS.TABLE, CRMFLOWTRANSITIONS.TRANSITIONID, allOrchFlowTransitonsDO, null);
					for(Long transitionId : orchTransitionIds) {
						if(allOrchFlowTransitionIds.contains(transitionId)) {
							Row flowTransitionRow = allOrchFlowTransitonsDO.getRow(CRMFLOWTRANSITIONS.TABLE, new Criteria( Column.getColumn(CRMFLOWTRANSITIONS.TABLE, CRMFLOWTRANSITIONS.TRANSITIONID), transitionId, QueryConstants.EQUAL));
							Long transitionProcessId = (Long) flowTransitionRow.get(CRMFLOWTRANSITIONS.PROCESSID);
							if(validOrchIds.contains(transitionProcessId)) {
								//valid flow transition row
								validOrchTransIds.add(transitionId);
							} else {
								invalidTransitionIds.add(transitionId);
							}
						} else {
							invalidTransitionIds.add(transitionId);
						}
					}
				} else {
					invalidTransitionIds.addAll(orchTransitionIds);
				}
			}

			Set<Long> orchActionIds = new HashSet<>();
			if(!actionsDO.isEmpty()) {
				orchActionIds = OrchestrationExecUtil.collectValues(CRMAUTOMATIONACTIONS.TABLE, CRMAUTOMATIONACTIONS.ACTIONID, actionsDO, null);

				SelectQuery sq2 = new SelectQueryImpl(new Table(CRMAUTOMATIONACTIONREL.TABLE));
				Criteria cri2 = new Criteria( Column.getColumn(CRMAUTOMATIONACTIONREL.TABLE, CRMAUTOMATIONACTIONREL.ACTIONID), orchActionIds.toArray(), QueryConstants.IN);
				sq2.addSelectColumn(Column.getColumn(CRMAUTOMATIONACTIONREL.TABLE, "*"));
				sq2.setCriteria(cri2);
				sq2.setRange(range);
				DataObject actionRelDO = pers.get(sq2);

				SelectQuery sq3 = new SelectQueryImpl(new Table(CRMPROCESSSTATE.TABLE));
				Criteria cri3 = new Criteria( Column.getColumn(CRMPROCESSSTATE.TABLE, CRMPROCESSSTATE.FEATURE_TYPE), AutomationConstants.TYPE_ORCHESTRATION, QueryConstants.EQUAL);
				sq3.addSelectColumn(Column.getColumn(CRMPROCESSSTATE.TABLE, "*"));
				sq3.setCriteria(cri3);
				sq3.setRange(range);
				DataObject processStateDO = pers.get(sq3);

				Set<Long> orchStateIds = new HashSet<>();
				if(!processStateDO.isEmpty()) {
					orchStateIds = OrchestrationExecUtil.collectValues(CRMPROCESSSTATE.TABLE, CRMPROCESSSTATE.STATEID, processStateDO, null);
				}

				for(Long actionId : orchActionIds) {
					//check actionrel row present for it or not
					if(!actionRelDO.isEmpty()) {
						Row orchAutomationActionRelRow = actionRelDO.getRow(CRMAUTOMATIONACTIONREL.TABLE, new Criteria( Column.getColumn(CRMAUTOMATIONACTIONREL.TABLE, CRMAUTOMATIONACTIONREL.ACTIONID), actionId, QueryConstants.EQUAL));
						if(orchAutomationActionRelRow != null) {
							Long ruleId = (Long) orchAutomationActionRelRow.get(CRMAUTOMATIONACTIONREL.RULEID);
							//check for processstate, state, transition
							if(orchStateIds.contains(ruleId) || validOrchTransIds.contains(ruleId)) {
								// valid Action
								validActionIds.add(actionId);
							} else {
								invalidActionIds.add(actionId);
							}
						} else {
							invalidActionIds.add(actionId);
						}
					} else {
						invalidActionIds.add(actionId);
					}
		        }
			}

			if(!invalidTransitionIds.isEmpty()) {
				Criteria delCrt1 = new Criteria(Column.getColumn(CRMTRANSITIONDETAILS.TABLE, CRMTRANSITIONDETAILS.TRANSITIONID), invalidTransitionIds.toArray(), QueryConstants.IN);
				PersistenceCacheUtil.getPurePersistenceLiteHandle().delete(delCrt1);
			}
			if(!invalidActionIds.isEmpty()) {
				Criteria delCrt2 = new Criteria(Column.getColumn(CRMAUTOMATIONACTIONS.TABLE, CRMAUTOMATIONACTIONS.ACTIONID), invalidActionIds.toArray(), QueryConstants.IN);
				PersistenceCacheUtil.getPurePersistenceLiteHandle().delete(delCrt2);

				Criteria delCrt3 = new Criteria(Column.getColumn(CRMAUTOMATIONACTIONREL.TABLE, CRMAUTOMATIONACTIONREL.ACTIONID), invalidActionIds.toArray(), QueryConstants.IN);
				PersistenceCacheUtil.getPurePersistenceLiteHandle().delete(delCrt3);
			}
	    }
	    catch(Exception e)
	    {
	        status = false;
	        resultObj.put("response", e.toString());
	    }
	    resultObj.put("status", status);
	    return resultObj;
	}

    public JSONObject getSchedulerStatus() throws JSONException
    {
        try
        {
            SelectQuery sq=new SelectQueryImpl(Table.getTable(CRMSCHEDULEDJOBS.TABLE));
            sq.addSelectColumn(Column.getColumn(CRMSCHEDULEDJOBS.TABLE, "*"));
            Criteria cr=new Criteria(Column.getColumn(CRMSCHEDULEDJOBS.TABLE, CRMSCHEDULEDJOBS.ACTION),"OWNERRECALCULATION",QueryConstants.EQUAL);
            cr=cr.and(new Criteria(Column.getColumn(CRMSCHEDULEDJOBS.TABLE, CRMSCHEDULEDJOBS.STATUS),new int[]{0,1,2},QueryConstants.IN));
            sq.setCriteria(cr);
            if(PersistenceCacheUtil.getNonCachePersistenceHandle().get(sq).isEmpty())
            {
                resultObj.put("response", "Scheduler has run"); //no i18n
            }
            else
            {
                resultObj.put("response", "S"); //no i18n
            }
        }
        catch(Exception e)
        {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }

