    public JSONObject maximizeRecordCreationDailyLimit() throws Exception{
    	try {
    		int percentage = Integer.valueOf(request.getParameter("percentage"));//no i18n
    		int dayMaxCnt = WFCreateRecordUtil.getWorkflowCreateRecordLimit();
    		int actualCountPercentage = (int)(dayMaxCnt*((float)percentage/100));
    		int actualCount = (actualCountPercentage) == 0 ? 0  : actualCountPercentage-1;
    		String featureName = WorkFlowActionsUtil.WF_RECORD_CREATE_ACTION;
    		FeatureEditionUtil.setFeatureLimitCount(featureName, dayMaxCnt, 0, actualCount, false);
    		AutomationFeatureLimits.doFeatureLimitResetInTableAndRedis(featureName, actualCount);
    		status = true;
    	}
    	catch(Exception e){
    		status = false;
    		resultObj.put("response", "unable to update Record dailylimit ResetConfigurations.jsp. Exception > " + e.toString());
    	}
    	resultObj.put("status",status);
		return resultObj;
    }

    public JSONObject maximizeMassMailDailyLimit() throws Exception{
    	try {
    		int massMailLimitPerDay[] =  MailUtil.getMailUsageDetails(FeatureNameConstants.MASS_EMAIL);
    		int maxLimitPerDay = 0;
            int allowedLimit = 0;
			int actualCount = 0;
			int maxLimitPerDayInEdition = CrmMassMailUtil.getMassMailLimitCount();
			
			String zgid = OrgUtil.getCurrentZGID().toString();
			String licenseType = LicenseUtil.getLicenseType();
			
			if( !LicenseUtil.isPaidEditionAccount(zgid) && LicenseUtil.isEditionTrialEvaluationAccount(zgid))
			{
				maxLimitPerDayInEdition = CrmConstants.MASSEMAIL_LIMIT_TRAIL;
			}
		   	if(massMailLimitPerDay != null && massMailLimitPerDay.length != 0)
		   	{
		   		actualCount = massMailLimitPerDay[0];
		   		maxLimitPerDay =  massMailLimitPerDay[1];
		   		if(actualCount == -1)
		   		{
		   			actualCount = 0;
		   		}
		   		if(maxLimitPerDay == -1)
		   		{
		   			maxLimitPerDay = 0;
		   		}

		   		if(maxLimitPerDayInEdition > maxLimitPerDay)
		   		{
		   			maxLimitPerDay = maxLimitPerDayInEdition;
		   		}
		   		allowedLimit = maxLimitPerDay - actualCount;
		   	}
    		new CrmEmailFeatureLimitsUtil().addMailCount(allowedLimit,actualCount,maxLimitPerDay,FeatureNameConstants.MASS_EMAIL);
    		status = true;
    	}catch(Exception e){
    		status = false;
            resultObj.put("response", "unable to update MassMail dailylimit ResetConfigurations.jsp. Exception > " + e);
    	}
    	resultObj.put("status", status);
    	return resultObj;
    }
    
