    public JSONObject deleteAllRepetitionSchedulers()throws Exception
    {
    	try
    	{
    		Job job = TimeTriggerUtil.getTimeTriggerSchedulerJobObject();
    		if(job!=null){
    			Long jobId=job.getJobID();
    			CrmKeyValueUtil.deleteCrmKeyValueByKeyName(TimeTriggerUtil.TIME_TRIGGER_SCHEDULER, true);
    			AutomationLastRunDetailsUtil.deleteLastRunDetails(CommonUtility.getAsList(jobId));
    			ZohoCRMSchedule.deleteRepetitiveJobByJobID(jobId, CoreScheduleConstants.RECURRING_LOW_PROCESS);
    			LOGGER.log(Level.INFO, "TimeTriggerScheduler deleted for JobID : {0}",String.valueOf(jobId));
    		}

    		job = ZohoCRMSchedule.getJobObjectByRepetitionName(ZohoCRMScheduleConstants.TRIGGER_EXECUTION_REPETITION, CoreScheduleConstants.RECURRING_LOW_PROCESS);
    		if(job!=null){
    			ZohoCRMSchedule.deleteRepetitiveJobOnly(job.getJobID(), CoreScheduleConstants.RECURRING_LOW_PROCESS);
    		}

    		resultObj.put("response", "repetition schedulers deleted");
    	}
    	catch(Exception e)
    	{
    		status = false;
    		resultObj.put("response", e.toString());
    	}
    	resultObj.put("status", status);
    	return resultObj;
    }

