	public JSONObject triggerBlueprintTimeTriggers(AUTOMATION_FEATURES feature) {
    	try {
			if (AUTOMATION_FEATURES.BLUEPRINT_STATE.equals(feature)) {
    		UpdateQuery updateQuery = new UpdateQueryImpl(CRMTRIGGERENTITYREL.TABLE);
    		updateQuery.setUpdateColumn(CRMTRIGGERENTITYREL.EXECUTEDTIME, DateTimeUtils.getCurrentTimeInGMT());
				updateQuery.setCriteria(new Criteria(Column.getColumn(CRMTRIGGERENTITYREL.TABLE, CRMTRIGGERENTITYREL.FEATURETYPE), new int[] { AutomationFeatureConstants.TYPE_BLUEPRINT_SLA, AutomationConstants.TYPE_BLUEPRINT }, QueryConstants.IN));
    		PersistenceCacheUtil.getNonCachePersistenceHandle().update(updateQuery);
    		} else if (AUTOMATION_FEATURES.BLUEPRINT_TRANSITION.equals(feature)) {
    			UpdateQuery updateQuery = new UpdateQueryImpl(CRMAUTOMATIONQUEUE.TABLE);
        		updateQuery.setUpdateColumn(CRMAUTOMATIONQUEUE.EXECUTIONTIME, DateTimeUtils.getCurrentTimeInGMT().getTime());
        		updateQuery.setCriteria(new Criteria( Column.getColumn(CRMAUTOMATIONQUEUE.TABLE, CRMAUTOMATIONQUEUE.ENTRY_TYPE), AutomationQueueEntry.BLUEPRINT_AUTOMATIC_TRANSITION.entryType(), QueryConstants.EQUAL));
        		PersistenceCacheUtil.getNonCachePersistenceHandle().update(updateQuery);
			}
			TimeTriggerUtil.runTimeTriggerSchedulerNow();
			resultObj.put("response", "Timebased actions re-scheduled to current time");
    	} catch (Exception e) {
    		status = false;
    		resultObj.put("response", e.toString());
    	}
    	resultObj.put("status", status);
    	return resultObj;
    }

    public JSONObject getBlueprintEscalationTime() throws Exception {
    	try {
    		SelectQuery sq = new SelectQueryImpl( Table.getTable(CRMTRIGGERENTITYREL.TABLE) );
    		Criteria cri = new Criteria (Column.getColumn(CRMTRIGGERENTITYREL.TABLE, CRMTRIGGERENTITYREL.ENTITYID), request.getParameter("entityId"), QueryConstants.EQUAL)
    				.and(new Criteria(Column.getColumn(CRMTRIGGERENTITYREL.TABLE, CRMTRIGGERENTITYREL.FEATURETYPE), AutomationConstants.TYPE_BLUEPRINT, QueryConstants.EQUAL));
    		sq.setCriteria(cri);
    		sq.addSelectColumn( Column.getColumn( null, PMDConstants.ASTERISK ) );
    		DataObject triggerObj = PersistenceCacheUtil.getNonCachePersistenceHandle().get(sq);
    		JSONArray jsonArr = new JSONArray();
    		@SuppressWarnings("unchecked")
			Iterator < Row > triggerRows = triggerObj.getRows(CRMTRIGGERENTITYREL.TABLE);
    		while (triggerRows.hasNext()) {
    			jsonArr.put(triggerRows.next().get(CRMTRIGGERENTITYREL.EXECUTEDTIME.toString()));
    		}
    		resultObj.put("response", jsonArr);
    	} catch (Exception e) {
    		status = false;
    		resultObj.put("response", e.toString());
    	}
    	resultObj.put("status", status);
    	return resultObj;
    }
    public JSONObject enableOrDisableNewSearch() throws JSONException
    {
        String actionToPerform=request.getParameter("actionToPerform");
        List<String> zuIdList=new ArrayList<String>();
        zuIdList.add(String.valueOf(zuId));
        if(actionToPerform!=null)
        {
            if(actionToPerform.equals("enableNewSearch"))
            {
            	CoreFeatureUtil.addOrUpdateTrailOrg(CrmFeatureUtil.Feature.NEWSEARCH.name(), zgId.toString(), zuIdList,CoreFeatureUtil.Type.ORG.name(), true, null);
                resultObj.put("response","new search enabled successfully");//no i18n
            }
            else
            {
            	CoreFeatureUtil.addOrUpdateTrailOrg(CrmFeatureUtil.Feature.NEWSEARCH.name(), zgId.toString(), zuIdList,CoreFeatureUtil.Type.ORG.name(), false, null);
                resultObj.put("response","new search disabled successfully");//no i18n
            }
        }
        else
        {
            resultObj.put("response","Nothing was done.check your data...");//No I18N
        }
        resultObj.put("status", true);
        return resultObj;
    }

