    public JSONObject setup_reset_new()
    {
    	try
    	{
    		/*
    		 * To delete the entries of the dependant_component entries of widget.
    		 */
    		Criteria criteria = new Criteria(Column.getColumn(CRMCOMPONENTRELATION.TABLE, CRMCOMPONENTRELATION.DEPENDANT_COMPONENT_NAME), SETUP_PAGE, QueryConstants.EQUAL);
            PersistenceCacheUtil.getPurePersistenceLiteHandle().delete(criteria);

    		SelectQueryImpl selectQuery = new SelectQueryImpl(Table.getTable(CRMSETTINGS.TABLE));
    		selectQuery.addSelectColumn(Column.getColumn(null, "*"));
    		selectQuery.addSortColumn(new SortColumn(Column.getColumn(CRMSETTINGS.TABLE, CRMSETTINGS.ELEMENT_ID),true));
    		DataObject data_object =  PersistenceCacheUtil.getPurePersistenceLiteHandle().get(selectQuery);
            /*
             * To delete custom elements
             */
            criteria = new Criteria(Column.getColumn(CRMSETTINGS.TABLE, CRMSETTINGS.GENERATED_SOURCE),CrmSettingsUtil.SYSTEM_GENERATED_ELEMENT_SOURCE, QueryConstants.NOT_EQUAL);
            criteria = criteria.and(new Criteria(Column.getColumn(CRMSETTINGS.TABLE, CRMSETTINGS.API_NAME),"userelement_", QueryConstants.STARTS_WITH));
            //PersistenceCacheUtil.getPurePersistenceLiteHandle().delete(criteria);
            data_object.deleteRows(CRMSETTINGS.TABLE, criteria);
            /*
             * To udpate the sequence for the setup elements
             */
			
			Criteria grp_criteria = new Criteria(Column.getColumn(CRMSETTINGS.TABLE, CRMSETTINGS.PARENT_ID), null, QueryConstants.EQUAL);
			grp_criteria = grp_criteria.and(new Criteria(Column.getColumn(CRMSETTINGS.TABLE, CRMSETTINGS.ELEMENT_TYPE), CrmSettingsUtil.GROUP_ELEMENT_ELEMENT_TYPE, QueryConstants.EQUAL));
			
			Iterator<Row> group_rows = data_object.getRows(CRMSETTINGS.TABLE, grp_criteria);
			
			int group_seq = 1;
			while(group_rows.hasNext())
			{
				Row group_row = group_rows.next();
				
				Long group_id = (Long)group_row.get(CRMSETTINGS.ELEMENT_ID);
				
				Criteria menu_cri = new Criteria(Column.getColumn(CRMSETTINGS.TABLE, CRMSETTINGS.PARENT_ID), group_id, QueryConstants.EQUAL);
				menu_cri = menu_cri.and(new Criteria(Column.getColumn(CRMSETTINGS.TABLE, CRMSETTINGS.ELEMENT_TYPE), CrmSettingsUtil.MENU_ELEMENT_ELEMENT_TYPE, QueryConstants.EQUAL));
				
				Iterator<Row> menu_rows = data_object.getRows(CRMSETTINGS.TABLE, menu_cri);
				
				int menu_seq = 1;
				while(menu_rows.hasNext())
				{
					Row menu_row = menu_rows.next();
					String menu_api_name = (String) menu_row.get(CRMSETTINGS.API_NAME);
					
					if(menu_api_name != null && !"system.compliancesettings".equals(menu_api_name)) {
						
						Long menu_id = (Long)menu_row.get(CRMSETTINGS.ELEMENT_ID);
						
						Criteria submenu_cri = new Criteria(Column.getColumn(CRMSETTINGS.TABLE, CRMSETTINGS.PARENT_ID), menu_id, QueryConstants.EQUAL);
						submenu_cri = submenu_cri.and(new Criteria(Column.getColumn(CRMSETTINGS.TABLE, CRMSETTINGS.ELEMENT_TYPE), CrmSettingsUtil.SUB_MENU_ELEMENT_ELEMENT_TYPE, QueryConstants.EQUAL));
						
						Iterator<Row> submenu_rows = data_object.getRows(CRMSETTINGS.TABLE, submenu_cri);
						
						int submenu_seq = 1;
						while(submenu_rows.hasNext())
						{
							Row submenu_row = submenu_rows.next();
							submenu_row.set(CRMSETTINGS.SEQUENCE, submenu_seq);
							data_object.updateRow(submenu_row);
							submenu_seq++;
						}
					}	
					menu_row.set(CRMSETTINGS.SEQUENCE, menu_seq);
					data_object.updateRow(menu_row);
					menu_seq++;
				}
				group_row.set(CRMSETTINGS.SEQUENCE, group_seq);
				data_object.updateRow(group_row);
				group_seq++;
			}				
			
			/*
             * To change the presence of system elements which are in hidden presence to 1
             */
            criteria = new Criteria(Column.getColumn(CRMSETTINGS.TABLE, CRMSETTINGS.GENERATED_SOURCE),CrmSettingsUtil.SYSTEM_GENERATED_ELEMENT_SOURCE, QueryConstants.EQUAL);
            criteria = criteria.and(new Criteria(Column.getColumn(CRMSETTINGS.TABLE, CRMSETTINGS.PRESENCE),CrmSettingsUtil.HIDDEN_ELEMENT, QueryConstants.EQUAL));
            
            Iterator<Row> systemRows = data_object.getRows(CRMSETTINGS.TABLE, criteria);
            while(systemRows.hasNext()) {
            	Row sysRow = systemRows.next();
            	sysRow.set(CRMSETTINGS.PRESENCE,CrmSettingsUtil.ACTIVE_ELEMENT);
            	data_object.updateRow(sysRow);
            }
            PersistenceCacheUtil.getPersistenceLiteHandle().update(data_object);
            
    		status = true;
            resultObj.put("response", "Setup resetted ");
        }
    	catch (Exception e)
    	{
             status = false;
             resultObj.put("response", e.toString());
        }
    	resultObj.put("status", status);
    	return resultObj;
    }
