    public JSONObject includeallrelatedlistitems() throws JSONException {
        try {
            String info = "";
            String moduleFromReq = request.getParameter("module");
            if(moduleFromReq != null){
                modules = new String[]{moduleFromReq};
            }
            for (String module: modules) {
                SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMLISTSRELATION.TABLE));
                Long tabId = (Long) CommonDBService.getpcId(module);
                if(tabId!=null){
                Criteria cr = new Criteria(Column.getColumn(CRMLISTSRELATION.TABLE, "TABID"), tabId, QueryConstants.EQUAL);
                cr = cr.and(new Criteria(Column.getColumn(CRMLISTSRELATION.TABLE, CRMLISTSRELATION.PRESENCE), 0, QueryConstants.EQUAL));
                sq.addSelectColumn(Column.getColumn(null, "*"));
                sq.setCriteria(cr);

                DataObject dobject = PersistenceCacheUtil.getNonCachePersistenceHandle().get(sq);
                if (!dobject.isEmpty()) {
                    info += module + "==>";
                }
                @SuppressWarnings("rawtypes")
                Iterator r = dobject.getRows(CRMLISTSRELATION.TABLE);

                while (r.hasNext()) {
                    Row updateRow = (Row) r.next();
                    info += updateRow.get(CRMLISTSRELATION.LISTLABEL) + " || ";
                    updateRow.set("PRESENCE", Long.valueOf(1)); //No I18N
                    dobject.updateRow(updateRow);
                    PersistenceCacheUtil.getNonCachePersistenceHandle().update(dobject);
                }
                if (!dobject.isEmpty()) {
                    info += "</br>";
                }
            }
            }
            modules = getModulesList();
            resultObj.put("status", info + " = > All modules related list items included"); //no i18n
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }

