    public JSONObject makefieldsvisible() throws JSONException {
        try {
            for (String module: "Leads,Accounts,Contacts,Potentials".split(",")) {
                SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMTAB.TABLE));
                sq.addJoin(new Join(CRMTAB.TABLE, CRMFIELD.TABLE, new String[] {
                    CRMTAB.TABID
                }, new String[] {
                    CRMFIELD.TABID
                }, Join.INNER_JOIN));
                sq.addJoin(new Join(CRMFIELD.TABLE, CRMPROFILEFIELDREL.TABLE, new String[] {
                    CRMFIELD.FIELDID
                }, new String[] {
                    CRMPROFILEFIELDREL.FIELDID
                }, Join.INNER_JOIN));

                Criteria fieldCr = new Criteria(Column.getColumn(CRMTAB.TABLE, CRMTAB.NAME), module, QueryConstants.EQUAL);
                Criteria permCr = new Criteria(Column.getColumn(CRMPROFILEFIELDREL.TABLE, CRMPROFILEFIELDREL.ISVISIBLE), 0, QueryConstants.EQUAL);
                permCr = permCr.or(new Criteria(Column.getColumn(CRMPROFILEFIELDREL.TABLE, CRMPROFILEFIELDREL.ISREADONLY), 1, QueryConstants.EQUAL));

                fieldCr = fieldCr.and(permCr);

                sq.setCriteria(fieldCr);
                sq.addSelectColumn(Column.getColumn(CRMTAB.TABLE, CRMTAB.TABID));
                sq.addSelectColumn(Column.getColumn(CRMTAB.TABLE, CRMTAB.NAME));
                sq.addSelectColumn(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDID));
                sq.addSelectColumn(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.COLUMNNAME));
                sq.addSelectColumn(Column.getColumn(CRMPROFILEFIELDREL.TABLE, "*"));

                DataObject fieldDO = PersistenceCacheUtil.getNonCachePersistenceHandle().get(sq);
                boolean isUpdated = false;
                @SuppressWarnings("unchecked")
                Iterator < Row > fldIter = fieldDO.getRows(CRMPROFILEFIELDREL.TABLE);
                while (fldIter != null && fldIter.hasNext()) {
                    Row profileFldRow = (Row) fldIter.next();
                    profileFldRow.set(CRMPROFILEFIELDREL.ISVISIBLE, 1);
                    profileFldRow.set(CRMPROFILEFIELDREL.ISREADONLY, 0);
                    fieldDO.updateRow(profileFldRow);
                    isUpdated = true;
                }
                isUpdated = true;
                if (isUpdated) {
                    PersistenceCacheUtil.getNonCachePersistenceHandle().update(fieldDO);
                }
                PageCacheUtil.deleteCreateEntityJSON(module);
            }
            resultObj.put("response", "All fields in Leads,Accounts,Contacts,Potentials made visible"); //no i18n
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }

