    public JSONArray getCustomViewList(String module) throws Exception {
        JSONArray customViewIds = new JSONArray();
        @SuppressWarnings("unchecked")
        LinkedHashMap < String, Object > customViews = CustomViewUtil.getCustomViewList(module, userId);
        @SuppressWarnings("unchecked")
        LinkedHashMap < String, Object > sharedViewIds = (LinkedHashMap < String, Object > ) customViews.get("Created By Me");
        @SuppressWarnings("unchecked")
        LinkedHashMap < String, Object > otherUserViewIds = (LinkedHashMap < String, Object > ) customViews.get("Other User's Views");
        sharedViewIds.putAll(otherUserViewIds);
        for (int j = 0; j < sharedViewIds.size(); j++) {
            String vName = (String) sharedViewIds.keySet().toArray()[j];
            customViewIds.put(sharedViewIds.get(vName));
        }
        return customViewIds;
    }

    public void deleteCV(String module, Long cvid) throws Exception {
        Integer category = null;
        Long cvconfigId = null;
        Long queryId = null;

        DataObject customViewObj = com.zoho.crm.customviews.util.CustomViewUtil.getCustomViewObject(cvid, null);
        Row row = customViewObj.getFirstRow(CRMCUSTOMVIEW.TABLE);

        if (row != null) {
            category = (Integer) row.get(CRMCUSTOMVIEW.CATEGORY);
            cvconfigId = (Long) row.get(CRMCUSTOMVIEW.CVCONFIGID);
            queryId = (Long) row.get(CRMCUSTOMVIEW.QUERYID);
        }
        boolean isUserDefined = false;
        if(CustomViewUtil.isCustomViewRQFlow())
        {
            isUserDefined = (category == CustomViewConstants.Category.USER_DEFINED.getCategory()) ? true : false;
        }
        else
        {
            isUserDefined = (category == com.zoho.crm.customviews.util.CustomViewUtil.Category.USER_DEFINED.getCategory() || category == com.zoho.crm.customviews.util.CustomViewUtil.Category.OLD_USER_DEFINED.getCategory()) ? true : false;
        }

        //Avoiding deleting predefined custom view.
        if (isUserDefined) {
            Long default_cv_id = CustomViewUtil.getDefaultCVID(module);
            SelectQuery squery = new SelectQueryImpl(Table.getTable(CRMDEFAULTCV.TABLE));
            squery.addJoin(new Join(Table.getTable(CRMDEFAULTCV.TABLE), Table.getTable(CRMCUSTOMVIEW.TABLE), new String[] {
                CRMDEFAULTCV.CVID
            }, new String[] {
                CRMCUSTOMVIEW.CVID
            }, Join.INNER_JOIN));
            Criteria joinCr = new Criteria(Column.getColumn(CRMCUSTOMVIEW.TABLE, CRMCUSTOMVIEW.QUERYID), Column.getColumn(CRMUSERCVSORTCOLUMN.TABLE, CRMUSERCVSORTCOLUMN.QUERYID), QueryConstants.EQUAL);
            joinCr = joinCr.and(new Criteria(Column.getColumn(CRMUSERCVSORTCOLUMN.TABLE, CRMUSERCVSORTCOLUMN.USERID), userId, QueryConstants.EQUAL));
            squery.addJoin(new Join(CRMCUSTOMVIEW.TABLE, CRMCUSTOMVIEW.TABLE, CRMUSERCVSORTCOLUMN.TABLE, CRMUSERCVSORTCOLUMN.TABLE, joinCr, Join.LEFT_JOIN));
            Criteria cvCrt = new Criteria(Column.getColumn(CRMDEFAULTCV.TABLE, CRMDEFAULTCV.CVID), cvid, QueryConstants.EQUAL);
            String temp = "*" + cvid + "*";
            Criteria favCriteria = new Criteria(Column.getColumn(CRMDEFAULTCV.TABLE, CRMDEFAULTCV.FAVORITECVIDS), temp, QueryConstants.LIKE, false);
            Criteria cr = cvCrt.or(favCriteria);
            squery.setCriteria(cr);
            Persistence per = PersistenceCacheUtil.getNonCachePersistenceHandle();
            squery.addSelectColumn(Column.getColumn(null, "*"));
            DataObject qobject = per.get(squery);
            if (qobject.containsTable(CRMDEFAULTCV.TABLE)) {
                UpdateQueryImpl updateQuery = null;
                @SuppressWarnings("unchecked")
                Iterator < Row > cvIter = qobject.getRows(CRMDEFAULTCV.TABLE, cvCrt);
                if (cvIter.hasNext()) {
                    updateQuery = new UpdateQueryImpl(CRMDEFAULTCV.TABLE);
                    updateQuery.setCriteria(cvCrt);
                    updateQuery.setUpdateColumn(CRMDEFAULTCV.CVID, default_cv_id);
                }
                CustomViewUtil.updateFavorite(null, null, null, new String[] {
                    cvid.toString()
                }, qobject, favCriteria, false);
                per.update(qobject);
                if (updateQuery != null) {
                    per.update(updateQuery);
                }
            }
            if (module.equals(CrmModuleConstants.CONTACTS) || module.equals(CrmModuleConstants.LEADS)) {
                BestTimeUtil.deleteRemindersOnCVDeleted(userId, cvid);
            }
    		List<Long> autoResponderIds = AutoResponderUtil.getAllRespondersIdforCVID(cvid);
            Criteria cr1 = new Criteria(Column.getColumn(SELECTQUERY.TABLE, SELECTQUERY.QUERYID), queryId, QueryConstants.EQUAL);
            Criteria configCr = new Criteria(Column.getColumn(CRMCONFIG.TABLE, CRMCONFIG.CONFIGID), new Long[]{cvconfigId, cvid}, QueryConstants.IN);
            per.delete(cr1);
            per.delete(configCr);

            Criteria cr2 = new Criteria(Column.getColumn(CRMHOMEPAGELAYOUT.TABLE, CRMHOMEPAGELAYOUT.DASHLETID), cvid, QueryConstants.EQUAL);
            per.delete(cr2);
    		ComponentsUsageUtil.deleteDependentComponentsUsage(autoResponderIds);
        }
    }

