    public JSONObject updateWaitingTime() throws JSONException {
        try{
            PrivacyPreferences ppObj = PrivacyPreferenceUtil.getPrivacyPreferences();
            String awaitingDuration = ppObj.getAwaitingPeriod();
            if(!awaitingDuration.isEmpty()){
                String mails = this.request.getParameter("mailIds");
                if(mails == null || mails.isEmpty()){
                    resultObj.put("response", "");
                    resultObj.put("status", true);
                    return resultObj;
                }
                String [] mailArr = mails.split(",");
                Long awaitingDurationInMills = CrmPrivacyUtil.getConsentDurationBasedOnConsentUnits(awaitingDuration);
                Long currTime = DateTimeUtils.getCurrentLongTimeInGMT();

                SelectQuery sq=new SelectQueryImpl(Table.getTable(CrmConstants.CRMCONSENTDETAILS));
                sq.addSelectColumn(Column.getColumn( null, "*" ));
                sq.setCriteria(new Criteria(Column.getColumn(CrmConstants.CRMCONSENTDETAILS, CRMCONSENTDETAILSTEMPLATE.EMAIL), mailArr, QueryConstants.IN));
                Persistence per = PersistenceCacheUtil.getPersistenceLiteHandle();
                DOIterator doIter = new DOIterator(per, sq, 0, 1000, true);
                while(doIter.hasNext()) {
                    DataObject dataObj =  doIter.next();
                    if(dataObj!=null && !dataObj.isEmpty()){
                        @SuppressWarnings("unchecked")
                        Iterator<Row> iter = dataObj.getRows(CrmConstants.CRMCONSENTDETAILS);
                        while(iter != null && iter.hasNext()){
                            Row row = iter.next();
                            row.set(CRMCONSENTDETAILSTEMPLATE.MAILSENTTIME, currTime-awaitingDurationInMills);
                            dataObj.updateRow(row);
                        }
                        per.update(dataObj);
                    }
                }
                }
            }
            catch(Exception e){

            }
            try{
                Long jobId = Long.parseLong(CrmKeyValueUtil.getCrmNCKeyValueRowWithoutTransaction("GDPR_CONSENT_EXPIRY_SCHEDULAR",true).get(CRMNCKEYVALUE.KEYID).toString());//NO I18N
                resultObj.put("response", "jobId = > "+jobId);
                ZohoCRMSchedule.updateRepetitiveJobById(jobId, CoreScheduleConstants.RECURRING_LOW_PROCESS, true, new Timestamp(System.currentTimeMillis() + 1000 * 60));
                }
            catch (Exception e){}
        resultObj.put("response", "updateWaitingTime completed");
        return resultObj;
    }

