	//while issue in pipeline creation in automation accounts
	public static void deleteModeFieldEntryWhileNewPipeline()throws Exception
	{
		String zgid = String.valueOf(OrgUtil.getCurrentZGID());
		Long fieldId = FieldUtil.getPipelineFieldId();
		Row fieldRow = FieldUtil.getFieldRow(fieldId);
		Long tabId = Long.valueOf(fieldRow.get(CRMFIELD.TABID).toString());
		String module = TabUtil.getTabNameById(tabId, zgid);
		Long zuid = IAMUtil.getCurrentUser().getZUID();
		Long userID = UserUtil.getUserIdByZUID(zuid);
		Locale locale = UserUtil.getUserLangLocaleByUserId(userID);
		DataObject modeFieldDO = FieldUtil.getNCModeFieldDOBasedOnCriteria(new Criteria(Column.getColumn(CRMTAB.TABLE, CRMTAB.TABID),fieldRow.get(CRMFIELD.TABID),QueryConstants.EQUAL),zgid);
		Boolean isModeFieldEntryPresent =  modeFieldDO.getRow(CRMMODEFIELD.TABLE, new Criteria(Column.getColumn(CRMMODEFIELD.TABLE, CRMMODEFIELD.FIELDID),fieldId,QueryConstants.EQUAL))!=null ;
		if( Integer.parseInt( fieldRow.get(CRMFIELD.PRESENCE).toString()) == -1 && isModeFieldEntryPresent  )
		{
			DeleteQuery dq = new DeleteQueryImpl(Table.getTable(CRMMODEFIELD.TABLE));
	        Criteria delCr = new Criteria(Column.getColumn( CRMMODEFIELD.TABLE,CRMMODEFIELD.FIELDID ),fieldId,QueryConstants.EQUAL );
	        LOGGER.log(Level.INFO,new StringBuilder("-----delete modefield entry for new pipeline creation started----->>").append(zgid).toString());
	        PersistenceCacheUtil.getPurePersistenceLiteHandle().delete(delCr);
	        PageCacheUtil.deleteCreateEntityJSON(module);
		}

		LOGGER.log(Level.INFO,new StringBuilder("-----delete modefield entry for new pipeline creation ended----->>").append(zgid).toString());

	}

	public void cleanReviewProcessDetailsTrigger()throws Exception
	{
		try {
			Long timePeriod = (long) 100;
			Long expireTime = DateTimeUtils.getTimeinMillisGMT(DateTimeUtils.getCurrentTimeInGMT()) - timePeriod * 86400000;
			HashMap<String, String> detailNameVsIds = ReviewProcessUtil.getPickListNameVsId(CRMREVIEWPROCESSDETAILS.TABLE,CRMREVIEWPROCESSDETAILS.STATUSID);
			SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMREVIEWPROCESSDETAILS.TABLE));
			sq.addSelectColumn(Column.getColumn(CRMREVIEWPROCESSDETAILS.TABLE,CRMREVIEWPROCESSDETAILS.RECORDID));
			sq.addSelectColumn(Column.getColumn(CRMREVIEWPROCESSDETAILS.TABLE,CRMREVIEWPROCESSDETAILS.STATUSID));
			DOIterator DOItr = new DOIterator(PersistenceCacheUtil.getNonCachePersistenceHandle(), sq, 2000);
			while(DOItr.hasNext())
			{
				DataObject dobj = DOItr.next();
				Iterator<Row> rpDetailRows = dobj.getRows(CRMREVIEWPROCESSDETAILS.TABLE);
				while(rpDetailRows.hasNext())
				{
					Row row = rpDetailRows.next();
					String statusID = row.get(CRMREVIEWPROCESSDETAILS.STATUSID).toString();
					if (!(detailNameVsIds.get(ReviewProcessConstants.UNREVIEWED).equals(statusID) ||  detailNameVsIds.get(ReviewProcessConstants.APPROVED).equals(statusID)))
					{
		               row.set(CRMREVIEWPROCESSDETAILS.REVIEW_INTIME, expireTime);
	                   dobj.updateRow(row);
		            }
				 }
				PersistenceCacheUtil.getNonCachePersistenceHandle().update(dobj);
			 }
			ReviewProcessUtil.cleanReviewProcessDetails(false);
			resultObj.put("response", "Review Processes cleanup scheduler trigger succeeded");
    	}
    	catch (Exception e)
    	{
    		resultObj.put("response", "Review Processes cleanup scheduler trigger failed");
    	}
	}
	
	
