    //Push Default Field Prediction Notfication
    public JSONObject pushDefaultPredictionNotification() throws Exception{

        JSONObject response = new JSONObject();
        try {
			String zgid = OrgUtil.getCurrentZGID().toString();
			DefaultFieldPredictionConfiguration predictionConfiguration = new DefaultFieldPredictionConfiguration(zgid,1);
			if(predictionConfiguration.isPredictionNeeded()) {			
				boolean isNotificationPushed = predictionConfiguration.pushDefaultPredictionNotifcation();
				if(isNotificationPushed) {
					LOGGER.log(Level.INFO, "Default Field Prediction Configuration Creation completed.");				
				}
				else {
					LOGGER.log(Level.INFO, "Default Field Prediction Configuration Failure in creation flow.");
				}
			}
			response.put("status","Success");
        }catch(Exception e) {
            LOGGER.log(Level.SEVERE, "Exception in pushing Default Prediction Notification :: ",e);
            response.put("status","Failed");
        }
        return new JSONObject().put("response", response);
    }

    /**
     * @author jagan-7039
     * 
     * @return  churned customers details
     * @throws Exception
     */
    public JSONObject getChurnedCustomers() throws Exception{
    	JSONObject response = new JSONObject();
    	JSONObject result = new JSONObject();
    	try {
	        Long configId = Long.parseLong(request.getParameter("predictionId"));
	        ChurnPredictionConfiguration config = ChurnPredictionLogicUtil.getConfigurationById(configId);
	       
	        Row tabRow = TabUtil.getAllTabsCachedDO().getRow(CRMTAB.TABLE, new Criteria(Column.getColumn(CRMTAB.TABLE, CRMTAB.TABID), config.getCustomerModuleId().toString(), QueryConstants.EQUAL));
	        String moduleName = (String) tabRow.get(CRMTAB.NAME);
	        String baseTable = EntityMetaDataUtil.getBaseTableByModuleName(moduleName);
	        String pkCol = EntityMetaDataUtil.getPKColumnName(baseTable);
	        
	        PredictionModule iModule = config.getModule();
	        Row insightTabRow = TabUtil.getAllTabsCachedDO().getRow(CRMTAB.TABLE, new Criteria(Column.getColumn(CRMTAB.TABLE, CRMTAB.TABID), iModule.getTabId().toString(), QueryConstants.EQUAL));
	        String iModuleName = (String) insightTabRow.get(CRMTAB.NAME);
	        String iBaseTable = EntityMetaDataUtil.getBaseTableByModuleName(iModuleName);
	        String iPkCol = EntityMetaDataUtil.getPKColumnName(iBaseTable);
	        DataObject fieldDO = FieldUtil.getCrmFieldsDOForModule(iModuleName, OrgUtil.getCurrentZGID().toString());
	        List< String > currencyFL = FieldUtil.getCurrencyFieldsList(fieldDO);
	        Boolean isMultiCurrencyEnabled = CurrencyUtil.isMultiCurrencyEnabled();
	        
	        Long churnTimeId = iModule.getChurnedTime();
	        Criteria churnTimeCri = new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDID), churnTimeId.toString(), QueryConstants.EQUAL) ;
	        Row churnTimeRow = fieldDO.getRow(CRMFIELD.TABLE, churnTimeCri);
	        String tableName = (String) churnTimeRow.get(CRMFIELD.TABLENAME);
	        String colName = (String) churnTimeRow.get(CRMFIELD.COLUMNNAME);
	        
	        Long recordId = iModule.getRecordId();
	        Criteria recordCri = new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDID), recordId.toString(), QueryConstants.EQUAL) ;
	        Row recordRow = fieldDO.getRow(CRMFIELD.TABLE, recordCri);
	        String rTableName = (String) recordRow.get(CRMFIELD.TABLENAME);
	        String rColName = (String) recordRow.get(CRMFIELD.COLUMNNAME);
	        
	        Persistence persistence = PersistenceCacheUtil.getPersistenceLiteHandle();
	        int start = 0;
	        boolean isDataAvail = true;
	        DataObject entityDo = null;
	        
	        SelectQuery sq = CrmQueryConstructor.getForPersonality(EntityMetaDataUtil.getPersonalityByModule(iModuleName), (Criteria) null);
	        Criteria cri = new Criteria(Column.getColumn(iBaseTable, "SE_PRESENCE"), 1, QueryConstants.EQUAL);
	        cri = cri.and(new Criteria(Column.getColumn(tableName, colName), null, QueryConstants.NOT_EQUAL));
	        CriteriaUtil.processCriteria(cri, ",",  config.getCreatedBy() , currencyFL, isMultiCurrencyEnabled);
			sq.setCriteria(cri);
	        while(isDataAvail) {
	        	int end = start + 2000;
	        	Range range = new Range(start, 2000);
	        	sq.setRange(range);
	        	if(entityDo == null) {
	    			entityDo = persistence.get(sq);
	    		}
	    		else {
	    			entityDo.merge(persistence.get(sq));
	    		}
	        	isDataAvail = entityDo.size(iBaseTable) == end ? true : false;
	        	start = end;
	        }
	        if(entityDo != null) {
	        	List<Long> ids = new ArrayList<Long>();
	        	
				Iterator<?> rItr = entityDo.getRows(rTableName);
	        	while(rItr.hasNext()) {
	        		Row row = (Row) rItr.next();
                    if(row.get(rColName) != null){
	        		    ids.add((Long) row.get(rColName));
                    }
	        	}
				
	        	SelectQuery entitySq = CrmQueryConstructor.getForPersonality(EntityMetaDataUtil.getPersonalityByModule(moduleName), (Criteria) null);
		        Criteria entityCri = new Criteria(Column.getColumn(baseTable, pkCol), ids.toArray(), QueryConstants.IN);
		        entitySq.setCriteria(entityCri);
		        DataObject recordsDO = persistence.get(entitySq);
		        
	        	Iterator<?> itr = entityDo.getRows(tableName);
	        	while(itr.hasNext()) {
	        		Row row = (Row) itr.next();
	        		if(tableName.equals(rTableName)) {
	        			String recId = row.get(rColName).toString();
	//        			recordsDO.get(baseTable, EntityMetaDataUtil.getDisplayColumn(moduleName));
	        			Criteria recCri = new Criteria(Column.getColumn(baseTable, pkCol), recId, QueryConstants.EQUAL);
	        			Row recRow = recordsDO.getRow(baseTable, recCri);
	        			String recName = recRow.get(EntityMetaDataUtil.getDisplayColumn(moduleName)).toString();
	        			Long time = (Long) row.get(colName);
	        			result.put(recName, PredictionConfigParseUtil.getISOTimestamp(time, config.getCreatedBy()));
	        		}
	        		else {
	        			String id = row.get(iPkCol).toString();
	        			Criteria rCri = new Criteria(Column.getColumn(rTableName, iPkCol), id, QueryConstants.EQUAL) ; 
	        			Row rRow = entityDo.getRow(rTableName, rCri);
	        			String recId = rRow.get(rColName).toString();
	        			Criteria recCri = new Criteria(Column.getColumn(baseTable, pkCol), recId, QueryConstants.EQUAL);
	        			Row recRow = recordsDO.getRow(baseTable, recCri);
	        			String recName = recRow.get(EntityMetaDataUtil.getDisplayColumn(moduleName)).toString();
	        			Long time = (Long) row.get(colName);
	        			result.put(recName, PredictionConfigParseUtil.getISOTimestamp(time, config.getCreatedBy()));
	        		}
	        	}
	        }       
    	}
    	catch(Exception e) {
    		LOGGER.log(Level.SEVERE, "Churned customer get failed", e);
    	}
        response.put("result",result);
        response.put("status","Success");
        return new JSONObject().put("response", response);
    }
