    /**
     * @author jagan-pt1626
     *
     * @category automation
     * @implNote delete all predictions
     * @return success message
     */
    public JSONObject deleteAllChurn() throws Exception {
        JSONObject response = new JSONObject();
        List<Long> ids = ChurnPredictionLogicUtil.getAllChurnIds();
        int len = ids.size();
        CrmUsers crmUsers = CrmUsers.getInstance(UserUtil.getCurrentUserId(), false);
        ChurnPredictionConfigApi configApi = new ChurnPredictionConfigApi();
        configApi.setCrmUsers(crmUsers);
		ChurnPredictionConfigApi.Delete config = configApi.new Delete();
		for(int i = 0 ; i < len ; i++) {
            try{
                config.deleteConfig(ids.get(i));
                response.put("deleted", ids.get(i));
            }
            catch(Exception e) {
                LOGGER.log(Level.SEVERE, "Churn Prediction configuration delete :: for automation", e);
                response.put("delete_failed", ids.get(i));
            }
        }
        return new JSONObject().put("response", response);
    }

// Prediction Analytics
    public JSONObject splitPredictionData() throws Exception{

        JSONObject response = new JSONObject();
        Persistence per = PersistenceCacheUtil.getPurePersistenceLiteHandle();
        try {
        String predictionId = request.getParameter("predictionId");
        String filterBy = request.getParameter("filterBy");
        FieldPredictionConfiguration config = FieldPredictionLogicUtil.getConfigurationById(Long.parseLong(predictionId));
        PredictionModule iModule = config.getInsightModule();
        Long iTabId = iModule.getTabId();
        Row iModulerow = TabUtil.getAllTabsCachedDO().getRow(CRMTAB.TABLE, new Criteria(Column.getColumn(CRMTAB.TABLE, CRMTAB.TABID), iTabId.toString(), QueryConstants.EQUAL));
        String iModuleName = (String) iModulerow.get(CRMTAB.NAME);
        DataObject iFieldsDO = FieldUtil.getCrmFieldsDOForModule(iModuleName, OrgUtil.getCurrentZGID().toString());

        Row endField = iFieldsDO.getRow(CRMFIELD.TABLE, new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDID), iModule.getIsEnded() , QueryConstants.EQUAL));
        String endTable = (String) endField.get(CRMFIELD.TABLENAME);
        String endColumn = (String) endField.get(CRMFIELD.COLUMNNAME);

        Criteria endCri = new Criteria(Column.getColumn(endTable, endColumn), true, QueryConstants.EQUAL);

        SelectQuery sq = CrmQueryConstructor.getForPersonality(EntityMetaDataUtil.getPersonalityByModule(iModuleName), endCri);
        sq.setRange(new Range(0, 2000));
        DataObject iModuleObj = per.get(sq);

        int size = iModuleObj.size(endTable);

        int ind_size = size / 4 ;

        Row timeField = iFieldsDO.getRow(CRMFIELD.TABLE, new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDID), iModule.getPredictedTime() , QueryConstants.EQUAL));
        String timeTable = (String) timeField.get(CRMFIELD.TABLENAME);
        String timeColumn = (String) timeField.get(CRMFIELD.COLUMNNAME);

        Iterator<?> datsItr = iModuleObj.getRows(timeTable);
        int count = 0;
        int period = 0;
        int[] periods = {0,1,2,3};

		if(filterBy.equals("last_week")) {
			Calendar date = Calendar.getInstance();
			date.set(Calendar.DAY_OF_WEEK, 1);
		    date.add(Calendar.DATE, -7);
		    while(datsItr.hasNext()) {
				Row dataRow =  (Row) datsItr.next();
				dataRow.set(timeColumn, date.getTimeInMillis());
				iModuleObj.updateRow(dataRow);
		    }
		}
		else if(filterBy.equals("last_month")) {
			Calendar date = Calendar.getInstance();
			date.set(Calendar.DATE, 1);
		    date.add(Calendar.DAY_OF_MONTH, -1);
			while(datsItr.hasNext()) {
				Row dataRow =  (Row) datsItr.next();
				dataRow.set(timeColumn, date.getTimeInMillis());
				iModuleObj.updateRow(dataRow);
		    }
		}
		else if(filterBy.equals("last_quarter")) {
			Calendar date = Calendar.getInstance();
			date.add(Calendar.DATE, 1);
		    date.add(Calendar.MONTH, -3);
			while(datsItr.hasNext()) {
				Row dataRow =  (Row) datsItr.next();
				dataRow.set(timeColumn, date.getTimeInMillis());
				iModuleObj.updateRow(dataRow);
		    }
		}
		else if(filterBy.equals("last_year")) {
			Calendar date = Calendar.getInstance();
			date.add(Calendar.YEAR, -1);
		    date.set(Calendar.DAY_OF_YEAR, 1);
			while(datsItr.hasNext()) {
				Row dataRow =  (Row) datsItr.next();
				dataRow.set(timeColumn, date.getTimeInMillis());
				iModuleObj.updateRow(dataRow);
		    }
		}
		else if(filterBy.equals("all")) {
			while(datsItr.hasNext()) {
				Row dataRow =  (Row) datsItr.next();
				if(count != ind_size)
				{
					count++;
				}
				else {
					count = 1;
					++period;
				}
				if(period < 4) {
					if(periods[period] == 0) {
						Calendar date = Calendar.getInstance();
						date.set(Calendar.DAY_OF_WEEK, 1);
					    date.add(Calendar.DATE, -7);
						dataRow.set(timeColumn, date.getTimeInMillis());
						iModuleObj.updateRow(dataRow);
					}
					else if(periods[period] == 1) {
						Calendar date = Calendar.getInstance();
						date.set(Calendar.DATE, 1);
					    date.add(Calendar.DAY_OF_MONTH, -1);
						dataRow.set(timeColumn, date.getTimeInMillis());
						iModuleObj.updateRow(dataRow);
					}
					else if(periods[period] == 2) {
						Calendar date = Calendar.getInstance();
						date.add(Calendar.DATE, 1);
					    date.add(Calendar.MONTH, -3);
						dataRow.set(timeColumn, date.getTimeInMillis());
						iModuleObj.updateRow(dataRow);
					}
					else if(periods[period] == 3) {
						Calendar date = Calendar.getInstance();
						date.add(Calendar.YEAR, -1);
					    date.set(Calendar.DAY_OF_YEAR, 1);
						dataRow.set(timeColumn, date.getTimeInMillis());
						iModuleObj.updateRow(dataRow);
					}
				}
				else {
					break;
				}
			}
		}
		per.update(iModuleObj);
		response.put("status","Success");
		}
		catch(Exception e) {
			LOGGER.log(Level.SEVERE, "Exception in splitPredictionData :: ",e);
			response.put("status","Failed");
		}
		return new JSONObject().put("response", response);
	}
    
    //Update End Records of Prediction
    public JSONObject endRecords() throws Exception{

        JSONObject response = new JSONObject();
        Persistence per = PersistenceCacheUtil.getPurePersistenceLiteHandle();
        try {
	        String predictionId = request.getParameter("predictionId");
	        String filterBy = request.getParameter("filterBy");
	        FieldPredictionConfiguration config = FieldPredictionLogicUtil.getConfigurationById(Long.parseLong(predictionId));
	        PredictionModule iModule = config.getInsightModule();
	        Long iTabId = iModule.getTabId();
	        Row iModulerow = TabUtil.getAllTabsCachedDO().getRow(CRMTAB.TABLE, new Criteria(Column.getColumn(CRMTAB.TABLE, CRMTAB.TABID), iTabId.toString(), QueryConstants.EQUAL));
	        String iModuleName = (String) iModulerow.get(CRMTAB.NAME);
	        DataObject iFieldsDO = FieldUtil.getCrmFieldsDOForModule(iModuleName, OrgUtil.getCurrentZGID().toString());
	
	        Row endField = iFieldsDO.getRow(CRMFIELD.TABLE, new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDID), iModule.getIsEnded() , QueryConstants.EQUAL));
	        String endTable = (String) endField.get(CRMFIELD.TABLENAME);
	        String endColumn = (String) endField.get(CRMFIELD.COLUMNNAME);
	
	        DataObject tabDO = TabUtil.getAllTabsCachedDO(OrgUtil.getCurrentZGID().toString());
	        String moduleName = tabDO.getRow(CRMTAB.TABLE,new Criteria(Column.getColumn(CRMTAB.TABLE,CRMTAB.TABID),config.getTabId(),QueryConstants.EQUAL)).get(CRMTAB.NAME).toString();
	        DataObject fieldDO = FieldUtil.getCrmFieldsDOForModule(moduleName, OrgUtil.getCurrentZGID().toString());
	        Row predict_row = fieldDO.getRow(CRMFIELD.TABLE,new Criteria(Column.getColumn(CRMFIELD.TABLE,CRMFIELD.FIELDID),config.getPredictFieldId(),QueryConstants.EQUAL));
	        
	        Criteria endCri = new Criteria(Column.getColumn(endTable, endColumn), Boolean.FALSE, QueryConstants.EQUAL);
	        DataObject pickListValuesDO = PickListFieldUtil.getAllPicklistDOForFieldId(config.getPredictFieldId(),OrgUtil.getCurrentZGID().toString());
		    List<Long> closedWonIds = FieldPredictionAnalyticsQuery.getClosedStageIds(Boolean.FALSE,Arrays.asList(new String[] {"Closed Won","Closed Lost"}),pickListValuesDO); //NO I18N
	        Criteria closedPredictionCri = new Criteria(Column.getColumn(CRMPOTENTIAL.TABLE,CRMPOTENTIAL.STAGE),closedWonIds.toArray(),QueryConstants.IN);
	        if(closedPredictionCri != null) {
	        	endCri = endCri.and(closedPredictionCri);
	        }
	        SelectQuery sq = CrmQueryConstructor.getForPersonality(EntityMetaDataUtil.getPersonalityByModule(moduleName), endCri);
	        sq = getInsightJoin(moduleName, sq, iTabId, iFieldsDO, config.getInsightModule().getJO());
	        sq.setCriteria(endCri);
	        sq.setRange(new Range(0, 2000));
	        DataObject iModuleObj = per.get(sq);
	
	        Row timeField = iFieldsDO.getRow(CRMFIELD.TABLE, new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDID), iModule.getPredictedTime() , QueryConstants.EQUAL));
	        String timeTable = (String) timeField.get(CRMFIELD.TABLENAME);
	        String timeColumn = (String) timeField.get(CRMFIELD.COLUMNNAME);
	
	        Iterator<?> datsItr = iModuleObj.getRows(endTable);
	
		    while(datsItr.hasNext()) {
				Row endRow =  (Row) datsItr.next();
				endRow.set(endColumn, Boolean.TRUE);
				iModuleObj.updateRow(endRow);
		    }
			per.update(iModuleObj);
			response.put("status","Success");
		}
		catch(Exception e) {
			LOGGER.log(Level.SEVERE, "Exception in splitPredictionData :: ",e);
			response.put("status","Failed");
		}
		return new JSONObject().put("response", response);
	}
    
