    /**
     *
     * @param config
     * @param modelInfo
     * @throws Exception
     */
    public static void insertModelData(FieldPredictionConfiguration config, JSONObject modelInfo) throws Exception {

    	Persistence persistence = PersistenceCacheUtil.getPersistenceLiteHandle();
		DataObject configModelDO = persistence.constructDataObject();

		Long currentTimeInMillis = DateTimeUtils.getMillisInGMT(DateTimeUtils.getCurrentTimeInGMT().toString());

		Row modelRow = new Row(CRMZIAMODELMETA.TABLE);
		modelRow.set(CRMZIAMODELMETA.CONFIGID, config.getIntelligenceConfigId());
		modelRow.set(CRMZIAMODELMETA.CONFIGTYPE, 1);
		modelRow.set(CRMZIAMODELMETA.MODELVERSION, 1);
		modelRow.set(CRMZIAMODELMETA.MODELSTATUS, 2);
		modelRow.set(CRMZIAMODELMETA.MODELNAME, "adaboost classifier"); //no i18n
		modelRow.set(CRMZIAMODELMETA.TOTALINFERENCE, 0);
		modelRow.set(CRMZIAMODELMETA.SUCCESSFULINFERENCE, 0);
		modelRow.set(CRMZIAMODELMETA.MODELACCURACY, 90);
		modelRow.set(CRMZIAMODELMETA.CONFIGRELATEDINFO, modelInfo.toString());
		modelRow.set(CRMZIAMODELMETA.LASTRUNTIME, currentTimeInMillis);
		modelRow.set(CRMZIAMODELMETA.NEXTRUNTIME, currentTimeInMillis);
		configModelDO.addRow(modelRow);

		persistence.add(configModelDO);

    }

    /**
     *
     * @param config
     * @throws Exception
     */
	public static void updatePredictionResults(FieldPredictionConfiguration config) throws Exception {
		List<JSONObject> predictionResultObjects = new ArrayList<>();

        CrmUsers crmUsers = CrmUsers.getInstance(UserUtil.getCurrentUserId(), false);

		DataObject tabDO = TabUtil.getAllTabsCachedDO();
		Row predictionTabRow = tabDO.getRow(CRMTAB.TABLE, new Criteria(Column.getColumn(CRMTAB.TABLE, CRMTAB.TABID), config.getTabId(), QueryConstants.EQUAL));
		Get predictModuleGet = CrmModules.getInstance(crmUsers).new Get((String) predictionTabRow.get(CRMTAB.SYS_REF_NAME), true);

		CrmFields.Get crmFieldsGet = CrmFields.getInstance(predictModuleGet).GET();
		CrmRecordsGet crmRecordsGet = CrmRecordsGet.getInstance(crmFieldsGet);
		DataObject predictRecordsDO = crmRecordsGet.getRecordsDO();

		String baseTableName = EntityMetaDataUtil.getBaseTableByModuleName(predictionTabRow.get(CRMTAB.NAME).toString());
//		JSONObject obj1 = new JSONObject("{\"record_id\":\"111111000000060108\",\"classification\":[{\"value\":\"111111000000060004\",\"probability\":10},{\"value\":\"111111000000060002\",\"probability\":10}],\"regression\":null}");

		Iterator<Row> recordRows = predictRecordsDO.getRows(baseTableName);
		int updateCount = 0;
		String primaryKeyColumn=EntityMetaDataUtil.getPrimaryKeyByModuleName(predictionTabRow.get(CRMTAB.NAME).toString());

		int binSize = 0;
		List<Long> regressionValues = new ArrayList<>();

		if(!(config.getPredictFieldType().equals("picklist") || config.getPredictFieldType().equals("B"))) {
			Row modelRow = ZiaModelMetaDBUtil.getMetaRow(config.getIntelligenceConfigId(), null);
			JSONObject modelInfo = new JSONObject(modelRow.get(CRMZIAMODELMETA.CONFIGRELATEDINFO).toString());
			JSONArray bins = modelInfo.getJSONObject("model_info").getJSONObject("target_stats").getJSONArray("bins"); //NO I18N
			binSize = bins.length();
			for(int k = 0; k < binSize; k++) {
				JSONObject bin = bins.getJSONObject(k);
				Long average = Long.sum(Long.parseLong(bin.getString("min")), Long.parseLong(bin.getString("max"))) / 2;
				regressionValues.add(average);
			}
		}


		while(recordRows.hasNext() && updateCount < 1000) {
			Row recordRow = recordRows.next();
			JSONObject predictionResult = new JSONObject();
			predictionResult.put("record_id", recordRow.get(primaryKeyColumn).toString());
			if(config.getPredictFieldType().equals("picklist")) {
				List<Long> picklistValues = config.getPicklistValues();
    			int picklistValuesLength = picklistValues.size();
    			JSONArray classificationValue = new JSONArray();
    			if(picklistValuesLength != 1) {
    				for(int idx = 0; idx < picklistValuesLength; idx++) {
        				JSONObject classification = new JSONObject();
     					classification.put("value", picklistValues.get(idx).toString());
     					classification.put("probability", idx == updateCount % picklistValuesLength ? 90 : 10);
     					classificationValue.put(classification);
        			}
    				predictionResult.put("classification", classificationValue);
    				predictionResult.put("regression", JSONObject.NULL);
    			}
    			else {
    				List<Integer> possibleProbabilities = new ArrayList<Integer>();
    				possibleProbabilities.add(10);
    				possibleProbabilities.add(30);
    				possibleProbabilities.add(60);
    				possibleProbabilities.add(80);
    				JSONObject classification = new JSONObject();
 					classification.put("value", picklistValues.get(0).toString());
 					classification.put("probability", possibleProbabilities.get(updateCount % 4));
 					classificationValue.put(classification);
    				predictionResult.put("classification", classificationValue);
    				predictionResult.put("regression", JSONObject.NULL);
    			}
			}
            else if(config.getPredictFieldType().equals("B")) {
    			JSONArray classificationValue = new JSONArray();
    			for(int idx = 0; idx < 2; idx++) {
    				JSONObject classification = new JSONObject();
    				Integer value = updateCount % 2;
 					classification.put("value", value.toString());
 					classification.put("probability", new Random().nextInt(50) + 1);
 					classificationValue.put(classification);
    			}
				predictionResult.put("classification", classificationValue);
				predictionResult.put("regression", JSONObject.NULL);
			}
			else {
				predictionResult.put("classification", JSONObject.NULL);
				String regressionValue = regressionValues.get(new Random().nextInt(binSize)).toString();
				predictionResult.put("regression", regressionValue);
			}
			predictionResultObjects.add(predictionResult);
			updateCount += 1;
		}

		PredictionResultUpdate.updatePredictionResults(predictionResultObjects, config.getIntelligenceConfigId());

	}

	//Update End Records of Prediction
	/**
	 *
	 * @param config
	 * @throws Exception
	 */
	public static void updateEndRecords (FieldPredictionConfiguration config) throws Exception {

        Persistence per = PersistenceCacheUtil.getPurePersistenceLiteHandle();

    	List<Integer> possibleAccuracy = new ArrayList<Integer>();
    	for(int num = 1; num <= 100; num ++) {
    		possibleAccuracy.add(num);
    	}

    	List<Integer> possibleMonths = new ArrayList<Integer>();
    	for(int num = 1; num <= 12; num ++) {
    		possibleMonths.add(num);
    	}

        PredictionModule iModule = config.getInsightModule();
        Long iTabId = iModule.getTabId();
        Row iModulerow = TabUtil.getAllTabsCachedDO().getRow(CRMTAB.TABLE, new Criteria(Column.getColumn(CRMTAB.TABLE, CRMTAB.TABID), iTabId.toString(), QueryConstants.EQUAL));
        String iModuleName = (String) iModulerow.get(CRMTAB.NAME);
        DataObject iFieldsDO = FieldUtil.getCrmFieldsDOForModule(iModuleName, OrgUtil.getCurrentZGID().toString());

        Row endField = iFieldsDO.getRow(CRMFIELD.TABLE, new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDID), iModule.getIsEnded() , QueryConstants.EQUAL));
        String endTable = (String) endField.get(CRMFIELD.TABLENAME);
        String endColumn = (String) endField.get(CRMFIELD.COLUMNNAME);

        Row trendField = iFieldsDO.getRow(CRMFIELD.TABLE, new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDID), iModule.getTrend() , QueryConstants.EQUAL));
        String trendTable = (String) trendField.get(CRMFIELD.TABLENAME);
        String trendColumn = (String) trendField.get(CRMFIELD.COLUMNNAME);

        Row accuracyField = iFieldsDO.getRow(CRMFIELD.TABLE, new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDID), iModule.getAccuracy() , QueryConstants.EQUAL));
        String accuracyTable = (String) accuracyField.get(CRMFIELD.TABLENAME);
        String accuracyColumn = (String) accuracyField.get(CRMFIELD.COLUMNNAME);

        Row predictedTimeField = iFieldsDO.getRow(CRMFIELD.TABLE, new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDID), iModule.getPredictedTime() , QueryConstants.EQUAL));
        String predictedTimeTable = (String) predictedTimeField.get(CRMFIELD.TABLENAME);
        String predictedTimeColumn = (String) predictedTimeField.get(CRMFIELD.COLUMNNAME);

        DataObject tabDO = TabUtil.getAllTabsCachedDO(OrgUtil.getCurrentZGID().toString());
        String moduleName = tabDO.getRow(CRMTAB.TABLE,new Criteria(Column.getColumn(CRMTAB.TABLE,CRMTAB.TABID),config.getTabId(),QueryConstants.EQUAL)).get(CRMTAB.NAME).toString();
        DataObject fieldDO = FieldUtil.getCrmFieldsDOForModule(moduleName, OrgUtil.getCurrentZGID().toString());
        Row predict_row = fieldDO.getRow(CRMFIELD.TABLE,new Criteria(Column.getColumn(CRMFIELD.TABLE,CRMFIELD.FIELDID),config.getPredictFieldId(),QueryConstants.EQUAL));
        Row predictionFieldRow = fieldDO.getRow(CRMFIELD.TABLE,new Criteria(Column.getColumn(CRMFIELD.TABLE,CRMFIELD.FIELDID),config.getPredictionFieldId(),QueryConstants.EQUAL));

        Criteria entityCri = new Criteria(Column.getColumn(predictionFieldRow.get(CRMFIELD.TABLENAME).toString(), predictionFieldRow.get(CRMFIELD.COLUMNNAME).toString()), null, QueryConstants.NOT_EQUAL);
        SelectQuery sq = CrmQueryConstructor.getForPersonality(EntityMetaDataUtil.getPersonalityByModule(moduleName), entityCri);
        List<Column> selectColumns = sq.getSelectColumns();
        for(Column col : selectColumns){
            sq.removeSelectColumn(col);
        }
        com.adventnet.crm.common.util.CriteriaUtil.addFkJoins_New(sq, moduleName, LookUpFieldUtil.getLookupFieldDetailsAsMapByChildModule(moduleName, null, false), true, true, false,false);

        sq = getInsightJoin(moduleName, sq, iTabId, iFieldsDO, config.getInsightModule().getJO());

        String endTablePK = EntityMetaDataUtil.getPKColumnName(endTable);
        String accuracyTablePK = EntityMetaDataUtil.getPKColumnName(accuracyTable);
        String predictedTimeTablePK = EntityMetaDataUtil.getPKColumnName(predictedTimeTable);

        sq.addSelectColumn(Column.getColumn(endTable, endTablePK));
        if(endTable != accuracyTable) {
	        sq.addSelectColumn(Column.getColumn(accuracyTable, accuracyTablePK));
        }
        if(endTable != predictedTimeTable && accuracyTable != predictedTimeTable) {
	        sq.addSelectColumn(Column.getColumn(predictedTimeTable, predictedTimeTablePK));
        }

        sq.addSelectColumn(Column.getColumn(endTable, endColumn));
        sq.addSelectColumn(Column.getColumn(accuracyTable, accuracyColumn));
        sq.addSelectColumn(Column.getColumn(predictedTimeTable, predictedTimeColumn));

        entityCri = entityCri.and(new Criteria(Column.getColumn(endTable, endColumn), Boolean.FALSE, QueryConstants.EQUAL));
        sq.setCriteria(entityCri);
        sq.setRange(new Range(0, 500));

//		LOGGER.log(Level.WARNING, "Prediction EndRecords Query -- {0} ", RelationalAPI.getInstance().getSelectSQL(sq));

        DataObject iModuleObj = per.get(sq);

//	        Row timeField = iFieldsDO.getRow(CRMFIELD.TABLE, new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDID), iModule.getPredictedTime() , QueryConstants.EQUAL));
//	        String timeTable = (String) timeField.get(CRMFIELD.TABLENAME);
//	        String timeColumn = (String) timeField.get(CRMFIELD.COLUMNNAME);

        Iterator<?> endRowItr = iModuleObj.getRows(endTable);

	    while(endRowItr.hasNext()) {
			Row endRow =  (Row) endRowItr.next();
			endRow.set(endColumn, Boolean.TRUE);
			iModuleObj.updateRow(endRow);
	    }

//	        Iterator<?> trendItr = iModuleObj.getRows(trendTable);
//
//		    while(trendItr.hasNext()) {
//				Row trendRow =  (Row) trendItr.next();
//				trendRow.set(trendColumn, Boolean.TRUE);
//				iModuleObj.updateRow(trendRow);
//		    }

        Iterator<?> accuracyItr = iModuleObj.getRows(accuracyTable);

        int updateCount = 0;

	    while(accuracyItr.hasNext()) {
			Row accuracyRow =  (Row) accuracyItr.next();
			accuracyRow.set(accuracyColumn, possibleAccuracy.get(new Random().nextInt(100)));
			iModuleObj.updateRow(accuracyRow);
			updateCount += 1;
	    }

        Iterator<?> predictedTimeItr = iModuleObj.getRows(predictedTimeTable);

        updateCount = 0;

	    while(predictedTimeItr.hasNext()) {
	    	Calendar date = Calendar.getInstance();
	    	if(updateCount % 4 == 0) {
	            date.set(Calendar.DAY_OF_WEEK, Calendar.SUNDAY);
	            date.add(Calendar.DATE, -7);
			    int randomDays = new Random().nextInt(7);
			    date.add(Calendar.DATE, randomDays);
	            Row timeRow =  (Row) predictedTimeItr.next();
				timeRow.set(predictedTimeColumn, date.getTimeInMillis());
				iModuleObj.updateRow(timeRow);
			}
			else if(updateCount % 4 == 1) {
		        date.add(Calendar.MONTH, -1);
		        int lastDay = date.getActualMaximum(Calendar.DAY_OF_MONTH);
			    int randomDays = new Random().nextInt(lastDay);
			    date.add(Calendar.DATE, randomDays);
		        Row timeRow =  (Row) predictedTimeItr.next();
				timeRow.set(predictedTimeColumn, date.getTimeInMillis());
				iModuleObj.updateRow(timeRow);
			}
			else if(updateCount % 4 == 2) {
				date.add(Calendar.DATE, new Random().nextInt(16) + 1);
			    date.add(Calendar.MONTH, possibleMonths.get(new Random().nextInt(12)));
			    Row timeRow =  (Row) predictedTimeItr.next();
				timeRow.set(predictedTimeColumn, date.getTimeInMillis());
				iModuleObj.updateRow(timeRow);
			}
			else if(updateCount % 4 == 3) {
				date.add(Calendar.YEAR, -1);
			    date.set(Calendar.DAY_OF_YEAR, new Random().nextInt(350) + 1);
			    Row timeRow =  (Row) predictedTimeItr.next();
				timeRow.set(predictedTimeColumn, date.getTimeInMillis());
				iModuleObj.updateRow(timeRow);
			}
	    	updateCount += 1;
	    }
		per.update(iModuleObj);
		LOGGER.log(Level.WARNING, "Prediction result updated successfully :: ");

	}

	/**
	 *
	 * @param parent_module
	 * @param lookUpFieldId
	 * @param sq
	 * @param iModeuleID
	 * @param iFieldDO
	 * @param insights
	 * @return
	 * @throws Exception
	 */
	private static SelectQuery getInsightJoin(String parent_module, SelectQuery sq, Long iModeuleID, DataObject iFieldDO, JSONObject insights) throws Exception {

	    String base_table = EntityMetaDataUtil.getBaseTableByModuleName(parent_module);
	    String module_pk_col = EntityMetaDataUtil.getPKColumnName(base_table);
	    String iModule = TabUtil.getTabNameById(iModeuleID);
        String iModule_pk =  EntityMetaDataUtil.getPKColumnName( EntityMetaDataUtil.getBaseTableByModuleName(iModule));
	    //Row
	    Row lookup_row = iFieldDO.getRow(CRMFIELD.TABLE , new Criteria(Column.getColumn(CRMFIELD.TABLE,CRMFIELD.FIELDID),insights.get(PredictionConstants.InsightsModule.IM_LOOKUPID),QueryConstants.EQUAL));
	    Row accuracy_row = iFieldDO.getRow(CRMFIELD.TABLE , new Criteria(Column.getColumn(CRMFIELD.TABLE,CRMFIELD.FIELDID),insights.get(PredictionConstants.InsightsModule.FP_ACCURACY),QueryConstants.EQUAL));
        Row predicted_time_row = iFieldDO.getRow(CRMFIELD.TABLE,new Criteria(Column.getColumn(CRMFIELD.TABLE,CRMFIELD.FIELDID),insights.get(PredictionConstants.InsightsModule.FP_PREDICTEDTIME),QueryConstants.EQUAL));
        Row end_row = iFieldDO.getRow(CRMFIELD.TABLE,new Criteria(Column.getColumn(CRMFIELD.TABLE,CRMFIELD.FIELDID),insights.get(PredictionConstants.InsightsModule.FP_ISENDED),QueryConstants.EQUAL));
        
	    //Table 
        String insight_tab = lookup_row.get(CRMFIELD.TABLENAME).toString(); 
        String accuracy_tab = accuracy_row.get(CRMFIELD.TABLENAME).toString();
        String end_tab = end_row.get(CRMFIELD.TABLENAME).toString();
        String time_tab = predicted_time_row.getColumnType(CRMFIELD.TABLENAME).toString();
	    sq.addJoin(new Join(base_table,lookup_row.get(CRMFIELD.TABLENAME).toString(),new String[] {module_pk_col},new String[] {lookup_row.get(CRMFIELD.COLUMNNAME).toString()},Join.LEFT_JOIN));
	    return sq;
	}

