	// Zia Next best Experience
	/**
	 * @implNote Used to Update a Nba Result for Record Manually.
	 * 		record = Deal Id
	 * 		type = Calls/Events/Emails
	 * 		days = 1/2/3/4/5/6/7/8/9..../28/29/30  (For now 30 is limit Smartfilter)
	 * @return
	 * @throws Exception
	 */
	public JSONObject updateNbx() throws Exception{
        JSONObject returnRes = new JSONObject();
        try {
                String recordId = request.getParameter("record");
                String type = request.getParameter("type");
                int day = Integer.parseInt(request.getParameter("days"));
                String module = Objects.nonNull(request.getParameter("config_type")) ? request.getParameter("config_type") : "" ;
                int configtype = "Deals".equals(module) ? 7 : "Leads".equals(module) ? 8 : 9;//no i18n
                

                List<String> nba = new ArrayList<String>();
                nba.add(recordId);nba.add(type);nba.add((day*86400000)+"");
                List<List<String>> data = new ArrayList<List<String>>();
                data.add(nba);
                NbaResultUpdate.updateNbaResults(data, false,configtype);
                returnRes.put("status", "completed");
        }
        catch(Exception e) {
                returnRes.put("status", "error");
                return new JSONObject().put("response", returnRes);
        }

        return new JSONObject().put("response", returnRes);
	}
