	/**
	 * 
	 * @implNote 
     * 	* This method used to reset the Zia Next best action for a Org
     * 	* Change the config into initial state (Migration state)
     * 	* Delete Nba model Meta
     * 	* Delete Nba custom fields
	 * @throws Exception
	 */
	public void resetZiaNba(int type) throws Exception{
		Range range = new Range(0,1);
        Persistence per = PersistenceCacheUtil.getPurePersistenceLiteHandle();
        Long configId = null;
        //CONFIG
        Criteria cri =new Criteria(Column.getColumn(CRMZIANOTIFICATIONCONFIG.TABLE, CRMZIANOTIFICATIONCONFIG.CONFIG_TYPE), type , QueryConstants.EQUAL);
        cri = cri.and(new Criteria(Column.getColumn(CRMZIANOTIFICATIONCONFIG.TABLE, CRMZIANOTIFICATIONCONFIG.CATEGORY), 2 , QueryConstants.EQUAL));
        SelectQuery sq =  new SelectQueryImpl(Table.getTable(CRMZIANOTIFICATIONCONFIG.TABLE));
        sq.addSelectColumn(Column.getColumn(CRMZIANOTIFICATIONCONFIG.TABLE,"*"));
        sq.setCriteria(cri);
        sq.setRange(range);
        DataObject configObj = per.get(sq);
        if(!configObj.isEmpty()) {
            Row configRow = configObj.getRow(CRMZIANOTIFICATIONCONFIG.TABLE);
            configId = (Long) configRow.get(CRMZIANOTIFICATIONCONFIG.ZIACONFIGID);
            configRow.set(CRMZIANOTIFICATIONCONFIG.STATUS, 0);
            JSONObject confDetails = new JSONObject(configRow.get(CRMZIANOTIFICATIONCONFIG.CONFIG_DETAILS)+"");
            if(confDetails.has("last_modified_time")) {
            	confDetails.remove("last_modified_time");
            }
			//Custom Fields
            JSONObject insightDetails = confDetails.has("insightDetails") ? confDetails.getJSONObject("insightDetails") : null;//no i18n
            if(insightDetails != null && NbxConfigUtil.deleteNbxFields(insightDetails,false)) {
				confDetails.remove("insightDetails");
			}
            if(confDetails.has("model_run_info")) {
                confDetails.remove("model_run_info");
            }
            if(confDetails.has("picklist_migration_info")) {
                confDetails.remove("picklist_migration_info");
            }
            if(confDetails.has("erc_info")) {
                confDetails.remove("erc_info");
            }
            //Criteria delFieldCr = new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDLABEL),"*NBX*", QueryConstants.LIKE);
            //delFieldCr = delFieldCr.or(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDLABEL),"*Nba*", QueryConstants.LIKE));
            //per.delete(delFieldCr);
            
            configRow.set(CRMZIANOTIFICATIONCONFIG.CONFIG_DETAILS, confDetails.toString());
            configObj.updateRow(configRow);
            per.update(configObj);

            //Subscription Model Disable
            SubscriptionModelForNBX.disableSubscriptionModel(type == 7 ? CrmModuleConstants.DEALS : type == 8 ? CrmModuleConstants.LEADS : CrmModuleConstants.CONTACTS);

            //META
            Criteria metacri =new Criteria(Column.getColumn(CRMZIAMODELMETA.TABLE, CRMZIAMODELMETA.CONFIGTYPE), 5 , QueryConstants.EQUAL);
            metacri = metacri.and(new Criteria(Column.getColumn(CRMZIAMODELMETA.TABLE, CRMZIAMODELMETA.CONFIGID), configId , QueryConstants.EQUAL));
            SelectQuery metasq =  new SelectQueryImpl(Table.getTable(CRMZIAMODELMETA.TABLE));
            metasq.addSelectColumn(Column.getColumn(CRMZIAMODELMETA.TABLE,"*"));
            metasq.setCriteria(metacri);
            metasq.setRange(range);
            DataObject meta = per.get(metasq);
            if(!meta.isEmpty()) {
            	try {
                    if(NbaPermissions.isGoalBasedNBXEnabled()){
                        NbxDICall.makeModelDeletionCallV3(configId);
                    }
                    else{
                        if(type == 7) {
                            NbaCommonUtil.triggerModelCallForNba(configId,  IntegrationConstants.DELETE);
                        }
                        else{
                            NbxDICall.makeModelDeletionCall(configId);
                        }
                    }
            	}
            	catch(Exception e) {
            		LOGGER.log(Level.WARNING,"Exception while Nba meta Deletion in Reset config ",e);
            	}
            	}
            }
        }
	/**
	 * 
	 * @implNote 
     * 	* initiate the bulk serving flow for check NBX completion notification.
	 * @throws Exception
	 */
	public JSONObject trigerNbxNotification() throws Exception {
		JSONObject response = new JSONObject();
		 String module = Objects.nonNull(request.getParameter("config_type")) ? request.getParameter("config_type") : "" ;
	     int configtype = "Deals".equals(module) ? 7 : "Leads".equals(module) ? 8 : 9;//no i18n
		Row configRow = NbxConfigUtil.getConfigRowByType(OrgUtil.getCurrentZGID().toString(), configtype);
        if(configRow != null) {
            String configId = configRow.get(CRMZIANOTIFICATIONCONFIG.ZIACONFIGID).toString();
            try {
                String url = configtype == 7 ? "/crm/zia/api/v1/nba/"+configId+"/trigger/bulk" : "/crm/zia/nbx/api/v2/configs/"+configId+"/trigger/model";//no i18n
                //DIIntegration.getInstance(ZiaFeatures.FEATURE.NBX, ZiaCloseablehttpConnPools.NBX, url, null , null, HttpMethod.PUT,OrgUtil.getCurrentZGID(), false).connectToService();
                ZiaIntegrationUtil request = new ZiaIntegrationUtil( url , IntegrationConstants.PUT , null , false, OrgUtil.getCurrentZGID(), false);
                request.setConnectionPool(ZiaCloseablehttpConnPools.NBX);
                request.connectToDI();
                response.put("status","Success");
            }
            catch(Exception e) {
            	response.put("status","Failed");
            	LOGGER.log(Level.INFO,"Exception while Nba complete notification trigger ",e);
            }
        }
        return new JSONObject().put("response", response);
	}
	
