		/**
	 * @implNote Used to check whether prediction result calculated for given records Ids using ERC
	 * @return
	 * @throws Exception
	 */
		public JSONObject checkPredictionErc() throws Exception{
			String recordId = request.getParameter("recordId");
			String predictionId = request.getParameter("predictionId");
			FieldPredictionConfiguration config = FieldPredictionLogicUtil.getConfigurationById(Long.valueOf(predictionId), null, false);
			String tabId = config.getTabId().toString();
			Long predictionFieldId = config.getPredictionFieldId();
			String type = config.getPredictFieldType();
			Long scoreField = type.equals(PredictionConstants.DataType.PICKLIST) || type.equals(PredictionConstants.DataType.BOOLEAN_TYPE) ? config.getScoreToFieldId() : null;
			
			Row tabrow = TabUtil.getAllTabsCachedDO().getRow(CRMTAB.TABLE, new Criteria(Column.getColumn(CRMTAB.TABLE, CRMTAB.TABID), tabId, QueryConstants.EQUAL));
			String moduleName = tabrow.get(CRMTAB.NAME).toString();
			String baseTableName = EntityMetaDataUtil.getBaseTableByModuleName(moduleName);
			DataObject fieldDO = FieldUtil.getCrmFieldsDOForModule(moduleName,OrgUtil.getCurrentZGID().toString());
			
			Row predictionFieldRow = fieldDO.getRow(CRMFIELD.TABLE,new Criteria(Column.getColumn(CRMFIELD.TABLE,CRMFIELD.FIELDID),predictionFieldId,QueryConstants.EQUAL));
			String colName = predictionFieldRow.get(CRMFIELD.COLUMNNAME).toString();
			String tableName = predictionFieldRow.get(CRMFIELD.TABLENAME).toString();
			String pkcol = EntityMetaDataUtil.getPKColumnName(tableName);
			
			SelectQuery sq = new SelectQueryImpl(Table.getTable(tableName));
			sq.addSelectColumn(Column.getColumn(tableName,colName));
			sq.addSelectColumn(Column.getColumn(tableName,pkcol));
			sq.setCriteria(new Criteria(Column.getColumn(tableName,pkcol),recordId,QueryConstants.EQUAL));
			DataObject recordsDO = PersistenceCacheUtil.getPersistenceLiteHandle().get(sq);
			Iterator<Row> iter = recordsDO.getRows(tableName);
			while(iter.hasNext()) {
				Row recordRow = iter.next();
				if(recordRow.get(colName) == null || recordRow.get(colName).equals("")) {
					String recId = recordRow.get(pkcol).toString();
					String logMsg = "Prediction Result Not Found ZGID:"+OrgUtil.getCurrentZGID()+", record id :"+recId+", Prediction Id :"+predictionId;//no i18n
					LOGGER.log(Level.INFO,logMsg);
					return new JSONObject().put("response", false);
				}
				else if(scoreField != null) {
					Row scoreFieldRow = fieldDO.getRow(CRMFIELD.TABLE,new Criteria(Column.getColumn(CRMFIELD.TABLE,CRMFIELD.FIELDID),scoreField,QueryConstants.EQUAL));
					String scoreColName = scoreFieldRow.get(CRMFIELD.COLUMNNAME).toString();
					String scoreTableName = scoreFieldRow.get(CRMFIELD.TABLENAME).toString();
					SelectQuery scoreSq = new SelectQueryImpl(Table.getTable(scoreTableName));
					scoreSq.addSelectColumn(Column.getColumn(scoreTableName,scoreColName));
					scoreSq.addSelectColumn(Column.getColumn(scoreTableName,pkcol));
					scoreSq.setCriteria(new Criteria(Column.getColumn(scoreTableName,pkcol),recordId,QueryConstants.EQUAL));
					DataObject scoreRecordsDO = PersistenceCacheUtil.getPersistenceLiteHandle().get(scoreSq);
					Iterator<Row> scoreIter = scoreRecordsDO.getRows(scoreTableName);
					while(scoreIter.hasNext()) {
						Row scoreRecordRow = scoreIter.next();
						if(scoreRecordRow == null || scoreRecordRow.get(scoreColName) == null || scoreRecordRow.get(scoreColName).equals("")) {
							String recId = scoreRecordRow.get(pkcol).toString();
							String logMsg = "Prediction Result Not Found ZGID:"+OrgUtil.getCurrentZGID()+", record id :"+recId+", Prediction Id :"+predictionId;//no i18n
							LOGGER.log(Level.INFO,logMsg);
							return new JSONObject().put("response", false);
						}
					}
				}
			}
			return new JSONObject().put("response", true);
		}

