    /**
     * @author jagan-pt1626
     *
     * @implNote to get Prediction record details, after prediction happened on that record.
     *
     * @see
     * 1.trend up/down
     * 2.is ended or not
     * 3.predicted time
     * 4.accuracy
     *
     * @return Prediction record related details.
     * @sample {"trend":"1","accuracy":"100","predicted time":"1615296937000","isended":"true"}
     *
     * @throws Exception
     */
    public JSONObject getPredictionRecord() throws Exception{
        JSONObject response = new JSONObject();
        try {
            String predictionId = request.getParameter("predictionId");
            String recordId = request.getParameter("recordId");

            FieldPredictionConfiguration config = FieldPredictionLogicUtil.getConfigurationById(Long.parseLong(predictionId), null, false);
            PredictionModule moduleP = config.getInsightModule();

            Row tabrow = TabUtil.getAllTabsCachedDO().getRow(CRMTAB.TABLE, new Criteria(Column.getColumn(CRMTAB.TABLE, CRMTAB.TABID), moduleP.getTabId().toString(), QueryConstants.EQUAL));
            String moduleName = tabrow.get(CRMTAB.NAME).toString();
            DataObject fieldDO = FieldUtil.getCrmFieldsDOForModule(moduleName,OrgUtil.getCurrentZGID().toString());

            String baseTableName = EntityMetaDataUtil.getBaseTableByModuleName(moduleName);
            List<String> cfTableName = EntityMetaDataUtil.getCFTableByBaseTable(baseTableName);
            String pkColumn = EntityMetaDataUtil.getPKColumnName(baseTableName);

            Row lookupRow = fieldDO.getRow(CRMFIELD.TABLE, new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDID), moduleP.getRecordId().toString() , QueryConstants.EQUAL));
            SelectQuery sq = CrmQueryConstructor.getForPersonality(EntityMetaDataUtil.getPersonalityByModule(moduleName), new Criteria(Column.getColumn(lookupRow.get(CRMFIELD.TABLENAME).toString(),lookupRow.get(CRMFIELD.COLUMNNAME).toString()),recordId,QueryConstants.EQUAL));

            Persistence persistence = PersistenceCacheUtil.getPersistenceLiteHandle();
            DataObject recordDO = persistence.get(sq);


            if(recordDO.size(baseTableName) > 0) {
                Row trendRow = fieldDO.getRow(CRMFIELD.TABLE, new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDID), moduleP.getTrend().toString() , QueryConstants.EQUAL));
                Row accRow = fieldDO.getRow(CRMFIELD.TABLE, new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDID), moduleP.getAccuracy().toString() , QueryConstants.EQUAL));
                Row endRow = fieldDO.getRow(CRMFIELD.TABLE, new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDID), moduleP.getIsEnded().toString() , QueryConstants.EQUAL));
                Row timeRow = fieldDO.getRow(CRMFIELD.TABLE, new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDID), moduleP.getPredictedTime().toString() , QueryConstants.EQUAL));

                response.put("trend", recordDO.getRow(trendRow.get(CRMFIELD.TABLENAME).toString()).get(trendRow.get(CRMFIELD.COLUMNNAME).toString()));
                response.put("accuracy", recordDO.getRow(accRow.get(CRMFIELD.TABLENAME).toString()).get(accRow.get(CRMFIELD.COLUMNNAME).toString()));
                response.put("isended", recordDO.getRow(endRow.get(CRMFIELD.TABLENAME).toString()).get(endRow.get(CRMFIELD.COLUMNNAME).toString()));
                response.put("predicted time", recordDO.getRow(timeRow.get(CRMFIELD.TABLENAME).toString()).get(timeRow.get(CRMFIELD.COLUMNNAME).toString()));

            }

        }catch(Exception e) {
            LOGGER.log(Level.SEVERE, "Exception in getPredictionRecord :: ",e);
            throw e;
        }
        return new JSONObject().put("response", response);
    }

