    /**
     * callTranscriptionProcess
     */
    public JSONObject callTranscriptionProcess(){
        JSONObject response = new JSONObject();
        try{
            String callId = request.getParameter("callId");
            String fileUrl = request.getParameter("fileUrl");
            String emotions = request.getParameter("emotions");
            fileUrl = fileUrl == null ? "" : fileUrl;
            int callDuration = NumberUtil.getInteger(request.getParameter("callDuration"));
            boolean isValiedFileUrl = Boolean.parseBoolean(request.getParameter("isValiedFileUrl") != null ? request.getParameter("isValiedFileUrl") : "false" );
            ZiaCallAnalyticsZLabUtil.getInstance(zgId.toString()).setForAutomation(!isValiedFileUrl).uploadFileToZLabModel(callId,fileUrl,"mp3",callDuration,emotions); //NO I18N
            response.put("status","Sucess");
        }catch (Exception ex){
            LOGGER.log(Level.SEVERE, "Recommendation Exception on ResetConfigurations from method callTranscriptionProcess :: ",ex);
            response.put("status","Failed");
        }
        return new JSONObject().put("response", response);
    }

