    /**
     * callTranscriptionProcess
     */
    public JSONObject callTranscriptionDowngradeAndUpgradeLic(){
        JSONObject response = new JSONObject();
        try{
            String lic = request.getParameter("lic");
            response.put("extend_trial",extendTrialMethod(lic,false));
            final String licenseType = LicenseUtil.getLicenseType(zgId.toString());

            Map<String,Integer> licenseTypeVal = new HashMap<String,Integer>(){
                {
                    put("E",4);put("P",3);put("S",2);put("X",1); //NO I18N
                }
            };

            if(licenseTypeVal.computeIfAbsent(lic,it -> 0) > licenseTypeVal.computeIfAbsent(licenseType,it -> 0)){
                ZiaCallAnalyticsPermissions.licenseEventListenerEnableHigherEditionFeatures(lic,zgId.toString());
            }else{
                ZiaCallAnalyticsPermissions.licenseEventListenerDisableHigherEditionFeatures(lic,zgId.toString());
            }

            response.put("status","Sucess");
        }catch (Exception ex){
            LOGGER.log(Level.SEVERE, "Recommendation Exception on ResetConfigurations from method callTranscriptionProcess :: ",ex);
            response.put("status","Failed");
        }
        return new JSONObject().put("response", response);
    }

