	/**
	 * This {@code getDataForAutomationRecommendation } is use for getting recommendation result of table
	 * <p> BOUGHT_TOGETHER </p>
	 * <p> ALREADY_BOUGHT </p>
	 * <p> FIRST_BUY </p>
	 * <p> REBUY </p>
	 * <p> NEXT_BUY </p>
	 *
	 * input is given by the parameter zgId , whomId , recommendationId and also type
	 *
	 * <code>
	 * 		baseUrl like "/crm/?whomId= &recommendationId= &type="
	 * </code>
	 *
	 * @throws Exception
	 */

	public JSONObject getDataForAutomationRecommendation() throws Exception{
		JSONObject resJsonObject = null;
		String whomIdStr = request.getParameter("whomId");
		String recommendationIdstr = request.getParameter("recommendationId");
		String type = request.getParameter("type");
		String zgid = zgId.toString();

		try{
			switch(type){
				case "BOUGHT_TOGETHER":
					resJsonObject = getDataForAutomation_BOUGHT_TOGETHER(whomIdStr,recommendationIdstr,zgid);
					break;
				case "ALREADY_BOUGHT":
					resJsonObject = getDataForAutomation_ALREADY_BOUGHT(whomIdStr,recommendationIdstr,zgid);
					break;
				case "FIRST_BUY":
					resJsonObject = getDataForAutomation_FIRST_BUY(whomIdStr,recommendationIdstr,zgid);
					break;
				case "REBUY":
					resJsonObject = getDataForAutomation_REBUY(whomIdStr,recommendationIdstr,zgid);
					break;
				case "NEXT_BUY":
					resJsonObject = getDataForAutomation_NEXT_BUY(whomIdStr,recommendationIdstr,zgid);
					break;
				default:
					resJsonObject = new JSONObject();
					break;
			}
		}catch(Exception e){
			LOGGER.log(Level.SEVERE, "Exception on getDataForAutomationRecommendation :: ",e);
			throw e;
		}

		resultObj.put("response", resJsonObject);
		return resJsonObject;
	}

