	 public static String createUsers(int from,int to,String email,String userPrefix,String password,String validity) {
	      String resp="test"; //no i18n

	       //json generation
	      JSONObject user = new JSONObject();
	      JSONObject user_data = new JSONObject();
	      JSONArray all_users = new JSONArray();
	      for(int i=from;i<=to;i++) {
	        JSONObject each_user = new JSONObject();
	        each_user.put("email", email+"+"+userPrefix+i+"t"+validity+"@zohotest.com"); //no i18n
	        each_user.put("password", password);//no i18n
	        all_users.put(each_user);
	      }
	      user_data.put("userdata", all_users);//no i18n
	      user.put("user",user_data);//no i18n


	      BufferedReader br=null;
	      HttpURLConnection conn=null;
	      try{
	        String temp = "https"; //no i18n
	    	 String requestUrl = temp+"://accounts-aoc.localzoho.com/aoc/api/v1/user?ticket="+IAMUtil.getCurrentTicket();//no i18n
	        byte[] postData       = user.toString().getBytes(StandardCharsets.UTF_8);
	        int    postDataLength = postData.length;

	        URL    url            = new URL( requestUrl );
	        conn= (HttpURLConnection) url.openConnection();

	        String redirect = conn.getHeaderField("Location");//no i18n
	        if (redirect != null){
	          conn = (HttpURLConnection) new URL(redirect).openConnection();
	        } else {
	          try {
	            conn.disconnect();
	            conn= (HttpURLConnection) url.openConnection();
	          } catch(Throwable e) {
	            throw e;
	          }
	        }

	        conn.setDoOutput( true );

	        conn.setRequestMethod("POST"); //no i18n

//	        conn.setRequestProperty("Authorization","ZohoCRM-1530708383115-6eea7b57709f4c9469fa87ef636295b9b093ff0f07360af9d6b7932f802095d97870d7feff87cc86fe4ef08868a9d92456bc19e628c151d3a357283948389dc0");

	        if(postDataLength>2) {
	          conn.setRequestProperty("Content-Type","application/json"); //no i18n
	          conn.setRequestProperty( "Content-Length", Integer.toString( postDataLength )); //no i18n
	          conn.setUseCaches( false );
	          conn.getOutputStream().write(postData);
	        }

	        StringBuilder responseSB = new StringBuilder();
	            br = new BufferedReader(new InputStreamReader(conn.getInputStream()));

	            String line;
	            while ( (line = br.readLine()) != null){
	                responseSB.append(line);
	            }
	        resp=responseSB.toString();
	      }
	      catch(Throwable x){
	        resp = x.getLocalizedMessage();
	      }
	      finally{
	        if(br!=null){
	          try {
	            br.close();
	          } catch(Exception e) {
	            resp = e.getLocalizedMessage();
	          }

	        }
	      }
	      return resp;
	      }
