	public JSONObject updateMailUsageCount() {
		try{
			Long zgid=OrgUtil.getCurrentZGID();
			String count = request.getParameter("mailCount");
			SelectQuery sq=new SelectQueryImpl(Table.getTable(CRMNCFEATURELIMITS.TABLE));
			Criteria cr=new Criteria(Column.getColumn(CRMNCFEATURELIMITS.TABLE, CRMNCFEATURELIMITS.FEATURENAME),"MAIL_COUNT",QueryConstants.EQUAL);
			sq.setCriteria(cr);
			sq.addSelectColumn(Column.getColumn(null, "*"));
			sq.setRange(new Range(0,1));
			DataObject dobj=zgid!=null ? PersistenceCacheUtil.getNonCachePersistenceHandle(zgid.toString()).get(sq) : PersistenceCacheUtil.getNonCachePersistenceHandle().get(sq);
			if(dobj.isEmpty()){
				Row row=new Row(CRMNCFEATURELIMITS.TABLE);
				row.set(CRMNCFEATURELIMITS.FEATURENAME,"MAIL_COUNT");// No I18N
				Timestamp currenttime=DateTimeUtils.getCurrentTimeInGMT();
				row.set(CRMNCFEATURELIMITS.UPDATEDTIME,currenttime);
				row.set(CRMNCFEATURELIMITS.LIMITCOUNT,200);
				row.set(CRMNCFEATURELIMITS.ACTUALCOUNT,Long.parseLong(count));
				row.set(CRMNCFEATURELIMITS.EXTRACOUNT,0);
				dobj.addRow(row);
				PersistenceCacheUtil.getCrmWithoutTransactionPersistenceHandle().add(dobj);
			}
			else{
				Row row=dobj.getRow(CRMNCFEATURELIMITS.TABLE);
				Long featureid=(Long)row.get(CRMNCFEATURELIMITS.FEATUREID);
				Criteria crt=new Criteria(Column.getColumn(CRMNCFEATURELIMITS.TABLE, CRMNCFEATURELIMITS.FEATUREID),featureid,QueryConstants.EQUAL);
				UpdateQuery updq=new UpdateQueryImpl(CRMNCFEATURELIMITS.TABLE);
				updq.setCriteria(crt);
				updq.setUpdateColumn(CRMNCFEATURELIMITS.ACTUALCOUNT, Long.parseLong(count));
				PersistenceCacheUtil.getCrmWithoutTransactionPersistenceHandle().update(updq);
			}
			resultObj.put("status", "success");// NO I18N
		} catch (Exception e) {
			LOGGER.log(Level.INFO,":::Error in updating mail usage count:::");
			status = false;
			resultObj.put("response", e.toString());
		}
		resultObj.put("status", status);
		return resultObj;
	}

