	public JSONObject reset_orgTaxes() throws Exception
	{
		try
		{
			LOGGER.log(Level.INFO, new StringBuilder("$$$$$$$ Tax reset called for the zgid ").append(zgId).toString());
			JSONArray array = new JSONArray();
			DataObject taxDO = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(CRMSERVICETAX.TABLE, TaxComponentUtil.TAX_ACTIVE_ONLY_CRITERIA);
			Iterator<Row> rows = taxDO.getRows(CRMSERVICETAX.TABLE);
			while(rows.hasNext())
			{
				Row taxRow = rows.next();
				taxRow.set(CRMSERVICETAX.STATUS, TaxComponentUtil.DELETED_TAX_STATUS);
				taxDO.updateRow(taxRow);

				JSONObject json = new JSONObject();
				json.put("service_id",taxRow.get(CRMSERVICETAX.SERVICEID).toString());
				json.put("display_name",taxRow.get(CRMSERVICETAX.DISPLAY_NAME));
				array.put(json);
			}

			Double value = new Double(0);
			String tax = "Sales Tax";// NO I18N

			Row salesTax = new Row(CRMSERVICETAX.TABLE);
			salesTax.set(CRMSERVICETAX.TAXTYPE, tax);
			salesTax.set(CRMSERVICETAX.TAXVALUE,value );
			salesTax.set(CRMSERVICETAX.DISPLAY_NAME, TaxComponentUtil.getTaxDisplayName(tax, value));
			salesTax.set(CRMSERVICETAX.SORTORDERID, 1);
			salesTax.set(CRMSERVICETAX.STATUS, TaxComponentUtil.ACTIVE_TAX_STATUS);
			taxDO.addRow(salesTax);

			tax = "Vat";// NO I18N

			Row vatTax = new Row(CRMSERVICETAX.TABLE);
			vatTax.set(CRMSERVICETAX.TAXTYPE, tax);
			vatTax.set(CRMSERVICETAX.TAXVALUE,value );
			vatTax.set(CRMSERVICETAX.DISPLAY_NAME, TaxComponentUtil.getTaxDisplayName(tax, value));
			vatTax.set(CRMSERVICETAX.SORTORDERID, 2);
			vatTax.set(CRMSERVICETAX.STATUS, TaxComponentUtil.ACTIVE_TAX_STATUS);
			taxDO.addRow(vatTax);

			PersistenceCacheUtil.getPurePersistenceLiteHandle().update(taxDO);
			JSONObject configJson = new JSONObject();
			configJson.put(TaxComponentUtil.AUTO_POPULATE_TAX, request.getParameter("autoPopulateTax").equals("true"));
			configJson.put(TaxComponentUtil.CAN_EDIT_TAX_VALUE, request.getParameter("canEditTaxValue").equals("true"));
			configJson.put(TaxComponentUtil.SHOW_EDIT_TAX_PREFERENCE, request.getParameter("show_edit_preference").equals("true"));

			CrmOrgLevelConfigUtil.insertOrUpdateConfigDetails(CrmOrgLevelConfigUtil.ORG_TAX,configJson.toString());
			if(array.length()>0)
			{
				ZohoCRMBeanWTImpl beanWT = (ZohoCRMBeanWTImpl)ScopedAccess.getInstance(ZohoCRMBeanWTImpl.class, null, TransactionType.REQUIRED);
				beanWT.scheduleTaxUpdateScheduler(array,currentUserId,null);
			}
			resultObj.put("status", "success");// NO I18N
		}
		catch (Exception e)
		{
			status = false;
			resultObj.put("response", e.toString());
			resultObj.put("status", "failure");// NO I18N
			LOGGER.log(Level.WARNING, "Exception in reset_orgTaxes :",e);

		}
		return resultObj;
	}
	public JSONObject updateWebFormAnalyticsUsage() throws Exception
	{
		try
		{
			Integer usage_count = Integer.valueOf(request.getParameter("usage_count")+""); // the name of the param in request
			Boolean isOver = request.getParameter("limit_over")!=null ? request.getParameter("limit_over").equals("true"):false ; // the name of the param in request
			String redisKey = new StringBuilder().append(zgId).append("_").append(FeatureNameConstants.WEBFORM_ANALYTICS).append("_").append(WebFormAnalyticsConstants.VISITOR_LIMIT_CONST).toString();
			DataObject dataObject = FeatureEditionUtil.getCachedFeatureLimitsDO(zgId.toString());

			Row featureRow = dataObject.getRow(CRMFEATURELIMITS.TABLE, new Criteria((Column.getColumn(CRMFEATURELIMITS.TABLE, CRMFEATURELIMITS.FEATURENAME)), FeatureNameConstants.WEBFORM_ANALYTICS, QueryConstants.EQUAL)) ;
			Integer extra_count=0,limit_count = WebformAnalyticsUtil.getLimitForSupportedEdition(zgId.toString());
			if(featureRow!=null)
			{
				limit_count = (int)featureRow.get(CRMFEATURELIMITS.LIMITCOUNT);
				extra_count = (int)featureRow.get(CRMFEATURELIMITS.EXTRACOUNT);
			}
			FeatureEditionUtil.setFeatureLimitCount(FeatureNameConstants.WEBFORM_ANALYTICS,limit_count,extra_count,usage_count,isOver,zgId.toString());
			if(isOver)
			{
				Map<String,String> valueMap = new HashMap<String,String>();
                valueMap.put(WebFormAnalyticsConstants.VISITOR_COUNT, String.valueOf("0")) ;
				CrmCacheUtil.putMapInRedis(redisKey, valueMap,null);
			}
			LOGGER.log(Level.INFO,"WebForm Analytics Tracking Count updated in Redis and CRMFEATURELIMITS zgId : {0} --- limit_count : {1} --- extra_count : {2} --- usage_count : {3} --- has_limit_exceeded --- {4} ",new Object[]{zgId,limit_count,extra_count,usage_count,isOver});
			resultObj.put("status", "success");//no i18n
			resultObj.put("message","Webform Analytics Visitor Limit changed to value - "+usage_count);//no i18n
		}catch(Exception e)
		{
			resultObj.put("status","failure");//no i18n
			resultObj.put("message",e.getMessage());//no i18n
		}
		return resultObj;
	}

