	/**
	 * Should not be used to delete webforms, it deletes webform analytics alone.
	 * Should be used only to clear analytics data if scheduler creation after webform deletion has failed
	 * @return
	 * @throws Exception
	 */
	public JSONObject deleteWebFormAnalytics() throws Exception
	{
		try
	    {
			Integer deleteLimit = 10000;
	        DeleteQueryImpl counterCleanUpQuery = new DeleteQueryImpl(Table.getTable(CRMWEBFORMUSAGECOUNTER.TABLE));
	        counterCleanUpQuery.setLimit(deleteLimit);
	        int counterDeleteLimit = deleteLimit;
	        while(deleteLimit == counterDeleteLimit)
	        {
	            counterDeleteLimit = PersistenceCacheUtil.getPurePersistenceLiteHandle().delete(counterCleanUpQuery);
	        }
	        DeleteQueryImpl usageCleanUpQuery = new DeleteQueryImpl(Table.getTable(CRMWEBFORMUSAGE.TABLE));
	        usageCleanUpQuery.setLimit(deleteLimit);
	        int usageDeleteLimit = deleteLimit;
	        while(deleteLimit == usageDeleteLimit)
	        {
	            usageDeleteLimit = PersistenceCacheUtil.getPurePersistenceLiteHandle().delete(usageCleanUpQuery);
	        }
	        resultObj.put("status", "success");//no i18n
	        resultObj.put("message","Webform Analytics data from CRMWEBFORMUSAGE and CRMWEBFORMUSAGECOUNTER cleaned up");//no i18n
	    }catch(Exception e)
	    {
	    	resultObj.put("status","failure");//no i18n
			resultObj.put("message",e.getMessage());//no i18n
	    }
		return resultObj;
	}
	  public JSONObject sendAnomalyNotification() throws JSONException {
		try
		{
	        	String componentName = request.getParameter("component_name");
	        	if (CrmFeatureUtil.isFeatureEnabled(Feature.NEW_ANOMALY_NOTIFICATION_FLOW_ENABLED.getName(), null, OrgUtil.getCurrentZGID().toString()) && (componentName == null || !"triggerAnomalyDailyScheduler".equals(componentName)) ) {
					AnomalyNotificationUtil.scheduleAnomalyNotificationJob(0,true);
					resultObj.put("response", "bulk flow triggered. Notification will be sent for the subscribed components");
				}else if(componentName!=null && !componentName.equals(""))
	        	{
				if ("triggerAnomalyDailyScheduler".equals(componentName))
				{
					return triggerAnomalyDailyScheduler();
				}
				else
	        	{
	        	String reponse = AnomalyNotificationUtil.sendAnomalyNotification(componentName,userId);
	            resultObj.put("response", reponse);
				}
			}
			else
			{
	        		status = false;
	        	}
		} catch (Exception e)
		{
			status = false;
			resultObj.put("response", e.toString());
		}
		resultObj.put("status", status);
		return resultObj;
	}
	  
