	  public JSONObject enableAnalyticsFiltersDataTypes() throws JSONException {
		  try {
			  String zgid = OrgUtil.getCurrentZGID().toString();
			  boolean isNewDashboardsEnabled = DashboardsUtil.isNewDashboardsEnabled(zgid);
			  Row analyticsFilterRow = CrmKeyValueUtil.getCrmKeyValueRow("ANALYTICS_FILTER_UI_TYPES", zgid);//No I18n
			  //Insert supported filter uitypes only if newDashboards is enabled and no existing rows present.
			  if(isNewDashboardsEnabled && analyticsFilterRow == null) {
				  CrmKeyValueUtil.insertOrUpdateCrmKeyValueByKeyName("ANALYTICS_FILTER_UI_TYPES", "4,5,210,55,133,1,62", true);// No I18N
				  LOGGER.log(Level.INFO, "Analytics Filter UITypes Insertion completed");
			  }
			  else {
				  status = false;
			  }
		  }
		  catch(Exception e) {
			  status = false;
			  resultObj.put("response", e.toString());
		  }
		  resultObj.put("status", status);
		  return resultObj;
	  }
