	  public void createApprovalRules() {
		  try {
			  List activeusers = UserClientUtil.getAllUsersDetails("ActiveUsers");  //NO i18N
			  Integer noOfRules = 2;
			  String[] criPatterns = new String[]{"(1 and 2)" , "(1 or 2)" };  //NO i18N
			  String[] approvalTypes = new String[]{"1" , "3" };  //NO i18N
			  String[] noOfApproversPerRule = new String[]{"1" , "1"};  //NO i18N
			  String[] noOfCriteriaRule = new String[]{"2" , "2"};
			  JSONArray typeOfCriteria = new JSONArray().put(new JSONArray().put("N").put("T")).put(new JSONArray().put("N").put("T"));
			  if(activeusers.size() > 1){
				  noOfApproversPerRule[1] = "2" ;
			  }
			  HttpServletRequestExtends httpsEx = RequestAndResponseUtil.getRequest();
			  httpsEx.setAttribute("isSandbox", false);
			  setParameterValue(httpsEx, "module", "Leads");//NO i18N
			  setParameterValue(httpsEx ,  "processName" , "ApprovalProcess1" );   //NO i18N
			  setParameterValue(httpsEx , "ProcessDesc", "Description");  //NO i18N
			  setParameterValue(httpsEx , "excutionType" , "1" );  //NO i18N
			  setParameterValue( httpsEx, "lastRule" , noOfRules + 1);  //NO i18N
			  for(int i =1 ;i <= noOfRules ; i++){
				  setParameterValue(httpsEx , "approvalType_"+i , approvalTypes[i-1]); //NO i18n
				  setParameterValue(httpsEx , "patternVal_"+i , criPatterns[i-1]);  //NO i18N
				  setParameterValue(httpsEx , "ruleActionType_"+i , 1); //NO i18N
				  setParameterValue(httpsEx , "rowCount_"+i , criPatterns.length); //NO i18N
				  setParameterValue(httpsEx ,"approverRowCnt_"+i ,noOfApproversPerRule[i-1]); //NO i18N
				  setParameterValue(httpsEx , "rowCount_"+i,"2"); //NO i18N
				  for(String number : noOfApproversPerRule){
					  int num = Integer.valueOf(number);
					  for(int j=1;j<=num;j++){
						  Details userDtls = (Details) activeusers.get(j-1);
						  setParameterValue(httpsEx , "approverType"+j+"_"+i,"1:"+userDtls.getUserId()); //NO i18N
					  }
				  }
				  int criCnt = Integer.valueOf(noOfCriteriaRule[i-1]);
				  for(int j=1;j<=criCnt;j++){
					  String criType = typeOfCriteria.getJSONArray(i-1).getString(j-1);
					  setParameterValue(httpsEx , "searchfieldtype"+j+"_"+i,criType); //NO i18N
					  if(criType.equals("N")){
						  setParameterValue(httpsEx , "numcondition"+j+"_"+i,"="); //NO i18N
						  setParameterValue(httpsEx , "searchnum"+j+"_"+i,"1"); //NO i18N
						  setParameterValue(httpsEx , "searchfield"+j+"_"+i,"CrmLeadDetails:ANNUALREVENUE:Annual Revenue:1:1"); //NO i18N
					  }
					  else {
						  setParameterValue(httpsEx , "textcondition"+j+"_"+i,"is"); //NO i18N
						  setParameterValue(httpsEx , "searchfield"+j+"_"+i,"CrmLeadDetails:CITY:City:1:1"); //NO i18N
						  setParameterValue(httpsEx , "searchtext"+j+"_"+i,"CHENNAI"); //NO i18N
					  }
				  }
			  }
			  ApprovalProcessUtil.createAPConfiguration(httpsEx);
			  resultObj.put("status", status);
		  }
		  catch(Exception e){
			  resultObj.put("response", e.getMessage());
			  resultObj.put("status", false);
			  LOGGER.log(Level.WARNING,"Exception ",e);
		  }
	  }
	  public JSONObject createApprovalProcess() throws Exception
	    {

	       // HashMap approverTypeVsId = new HashMap();
	        String approvalType = request.getParameter("approvalType");
	        JSONObject notifyJSON = new JSONObject(request.getParameter("notifyJson"));
	        HashMap<String,String> approverTypeVsId =  new Gson().fromJson(request.getParameter("approverTypeVsId"), HashMap.class);
	        try {
	        	ResetApprovalProcess reviewProcess = new ResetApprovalProcess();
	        	reviewProcess.createApprovalProcess(approverTypeVsId, approvalType, notifyJSON);
	            resultObj.put("status", true);
	        } catch (Exception e) {
	           resultObj.put("status", false);
	           resultObj.put("response", "Error while creating approval process. "+e);
	        }
	        return resultObj;
	    }
	private static void setParameterValue(HttpServletRequestExtends httpsEx, String key, Object value) {
		httpsEx.setParameter(key, value);

	}

