	  public static void updateDashboardsRefName()throws Exception
	  {
		  UpdateQuery updQry = new UpdateQueryImpl(CRMTAB.TABLE);
		  Criteria crt = new Criteria(Column.getColumn(CRMTAB.TABLE, CRMTAB.NAME), CrmModuleConstants.DASHBOARDS, QueryConstants.EQUAL);
		  crt = crt.and(new Criteria(Column.getColumn(CRMTAB.TABLE, CRMTAB.SYS_REF_NAME), CrmModuleConstants.DASHBOARDS, QueryConstants.EQUAL));
		  updQry.setCriteria(crt);
		  updQry.setUpdateColumn(CRMTAB.SYS_REF_NAME, CrmModuleConstants.ANALYTICS);
		  PersistenceCacheUtil.getNonCachePersistenceHandle().update(updQry);
	  }
