	  public JSONObject enableOrDisableLucenePush() throws JSONException
    {
    	boolean isLocalZohoSetup = Boolean.parseBoolean(RebrandLinkUtil.getRebrandKeys("IS_LOCAL_ZOHO"));//No I18N

    	if(isLocalZohoSetup)
    	{
	        String actionToPerform=request.getParameter("actionToPerform");
	        List<String> zuIdList=new ArrayList<String>();
	        zuIdList.add(String.valueOf(zuId));
	        if(actionToPerform!=null)
	        {
	            if(actionToPerform.equals("disableLucenePush"))
	            {
	            	CoreFeatureUtil.addOrUpdateTrailOrg(CrmFeatureUtil.Feature.LOCALZOHOLUCENEPUSHSTATUS.name(), zgId.toString(), zuIdList,CoreFeatureUtil.Type.ORG.name(), false, null);
	                resultObj.put("response","new search enabled successfully");//no i18n
	            }
	            else if(actionToPerform.equals("enableLucenePush"))
	            {
	            	CoreFeatureUtil.addOrUpdateTrailOrg(CrmFeatureUtil.Feature.LOCALZOHOLUCENEPUSHSTATUS.name(), zgId.toString(), zuIdList,CoreFeatureUtil.Type.ORG.name(), true, null);
	                resultObj.put("response","new search disabled successfully");//no i18n
	            }
	            else
	            {
	            	resultObj.put("response","Invalid Action...");//No I18N
	            }
	        }
	        
	        {
	            resultObj.put("response","Nothing was done.check your data...");//No I18N
	        }
    	}
    	else
    	{
    		resultObj.put("response","Only Applicable in LOCALZOHO Setup");//No I18N
    	}
    	resultObj.put("status", true);
        return resultObj;
    }

