	  //this method has to be strictly called for cases where pipeline creation has failed due to scheduler problem and meta is corrupted .
	  //Cofirm with developers before running this .Dont include this in any automation code
	  public static void updatePipelineMetaForAutomationAccounts() throws Exception
	  {
		  Long pipelineFieldId = FieldUtil.getPipelineFieldId(null);
		  //Updating pipeline field presence to -1
		  UpdateQuery pipePresenceQry = new UpdateQueryImpl(CRMFIELD.TABLE);
		  Criteria pipePresenceCrt = new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDID), pipelineFieldId, QueryConstants.EQUAL);
		  pipePresenceQry.setCriteria(pipePresenceCrt);
		  pipePresenceQry.setUpdateColumn(CRMFIELD.PRESENCE, -1);
		  PersistenceCacheUtil.getPurePersistenceLiteHandle().update(pipePresenceQry);

		  //Updating pipeline None option presence to be 0
		  UpdateQuery nonePresQry = new UpdateQueryImpl(CRMPICKLISTVALUES.TABLE);
		  Criteria nonePresCrt = new Criteria(Column.getColumn(CRMPICKLISTVALUES.TABLE, CRMPICKLISTVALUES.FIELDID), pipelineFieldId, QueryConstants.EQUAL);
		  nonePresCrt = nonePresCrt.and(new Criteria(Column.getColumn(CRMPICKLISTVALUES.TABLE, CRMPICKLISTVALUES.ACTUALVALUE), "-None-", QueryConstants.EQUAL));
		   nonePresQry.setCriteria(nonePresCrt);
		   nonePresQry.setUpdateColumn(CRMPICKLISTVALUES.PRESENCE, 0);
		  PersistenceCacheUtil.getPurePersistenceLiteHandle().update(nonePresQry);

		  //Deleting pipeline Mode Field Entries
		  DeleteQuery modeDelQry = new DeleteQueryImpl(CRMMODEFIELD.TABLE);
		  Criteria modeDelCrt = new Criteria(Column.getColumn(CRMMODEFIELD.TABLE, CRMMODEFIELD.FIELDID), pipelineFieldId, QueryConstants.EQUAL);

		  modeDelQry.setCriteria(modeDelCrt);
		  PersistenceCacheUtil.getPurePersistenceLiteHandle().delete(modeDelQry);

		  //Deleting fielddeprel entries which involves pipeline field
		  DeleteQuery fieldDepDelQry = new DeleteQueryImpl(CRMFIELDDEPREL.TABLE);
		  Criteria fieldDepCrt = new Criteria(Column.getColumn(CRMFIELDDEPREL.TABLE, CRMFIELDDEPREL.CONFIELDID), pipelineFieldId, QueryConstants.EQUAL);
		  fieldDepCrt = fieldDepCrt.or(new Criteria(Column.getColumn(CRMFIELDDEPREL.TABLE, CRMFIELDDEPREL.DEPFIELDID),pipelineFieldId , QueryConstants.EQUAL));
		  fieldDepDelQry.setCriteria(fieldDepCrt);
		  PersistenceCacheUtil.getPurePersistenceLiteHandle().delete(fieldDepDelQry);

		  deletePipelinePickListValues();

		  List<String> modulesList = new ArrayList<String>();
		  modulesList.add("Potentials"); //no i18n
		  PageCacheUtil.createSchedulerForPageRegen(modulesList);

		  if(pipelineFieldId==null)
			{
		    	LOGGER.log(Level.SEVERE, "Pipeline field is not found in this account {0}", new Object[]{OrgUtil.getCurrentZGID()});
				return;
			}
			Criteria crt = new Criteria(Column.getColumn(CRMSCHEDULEDJOBS.TABLE, CRMSCHEDULEDJOBS.ACTION), new String[] {"PICKLIST_ACTIONS","MASSACTIONS"}, QueryConstants.IN);
			crt = crt.and(new Criteria(Column.getColumn(CRMSCHEDULEDJOBS.TABLE, CRMSCHEDULEDJOBS.TYPE), "Potentials", QueryConstants.EQUAL));
			crt = crt.and(new Criteria(Column.getColumn(CRMSCHEDULEDJOBS.TABLE, CRMSCHEDULEDJOBS.ACTIONINFO), pipelineFieldId.toString(), QueryConstants.CONTAINS));
			crt = crt.and(new Criteria(Column.getColumn(CRMSCHEDULEDJOBS.TABLE, CRMSCHEDULEDJOBS.ACTIONINFO), "isPipelineTransfer", QueryConstants.CONTAINS).or(new Criteria(Column.getColumn(CRMSCHEDULEDJOBS.TABLE, CRMSCHEDULEDJOBS.ACTIONINFO), "delete", QueryConstants.CONTAINS)));
			crt = crt.and(new Criteria(Column.getColumn(CRMSCHEDULEDJOBS.TABLE, CRMSCHEDULEDJOBS.STATUS), new int[] { ScheduledJobDetails.Status.FINISHED.getValue(), ScheduledJobDetails.Status.FAILED.getValue() }, QueryConstants.NOT_IN));
			CrmScheduledJobsUtil.deleteJob(crt);
	  }


      public static void resetAccountNamePresenceTo2() throws Exception
	  {
		  UpdateQuery pipePresenceQry = new UpdateQueryImpl(CRMFIELD.TABLE);
		  Criteria pipePresenceCrt = new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.COLUMNNAME), "ACCOUNTID", QueryConstants.EQUAL);
		  pipePresenceCrt = pipePresenceCrt.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.TABLENAME), "CrmPotential", QueryConstants.EQUAL)) ;
		  pipePresenceCrt = pipePresenceCrt.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.GENERATEDTYPE), 1, QueryConstants.EQUAL)) ;
		  pipePresenceCrt = pipePresenceCrt.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.PRESENCE), -2, QueryConstants.EQUAL)) ;
		  pipePresenceQry.setCriteria(pipePresenceCrt);
		  pipePresenceQry.setUpdateColumn(CRMFIELD.PRESENCE, 2);
		  PersistenceCacheUtil.getPurePersistenceLiteHandle().update(pipePresenceQry);
		  LOGGER.log(Level.INFO, "ACCOUNTID column presence is checked and corrected for its presence as 2");//No I18N

	  }

      public static void resetDescriptionFieldMaxLenTo32k() throws Exception
	  {
		  UpdateQuery pipePresenceQry = new UpdateQueryImpl(CRMFIELD.TABLE);
		  Criteria pipePresenceCrt = new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.COLUMNNAME), "DESCRIPTION", QueryConstants.EQUAL);
		  pipePresenceCrt = pipePresenceCrt.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.TABLENAME), "CrmPotential", QueryConstants.EQUAL)) ;
		  pipePresenceCrt = pipePresenceCrt.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.GENERATEDTYPE), 1, QueryConstants.EQUAL)) ;

		  pipePresenceQry.setCriteria(pipePresenceCrt);
		  pipePresenceQry.setUpdateColumn(CRMFIELD.MAXIMUMLEN , 32000);
		  PersistenceCacheUtil.getPurePersistenceLiteHandle().update(pipePresenceQry);
		  LOGGER.log(Level.INFO, "DESCRIPTION column max len is checked and corrected to 32000");//No I18N

	  }

