	 public static void removeDraftRecordsFromRP() throws Exception {
		 try
		   {
		   	   DataObject layoutDO = com.zoho.crm.core.meta.wizards.WizardUtil.getWizardDO(null);
		   	   if(!layoutDO.isEmpty())
		   	   {
			     Iterator<Row> layoutRow = layoutDO.getRows(CRMPAGELAYOUT.TABLE);
	   			     HashSet<Long> Ids = new HashSet();
			     while(layoutRow.hasNext())
			     {
	 			   Row lrow = layoutRow.next();
	  			   Ids.add((Long)lrow.get(CRMPAGELAYOUT.TABID));
			     }
 			     Criteria crt = new Criteria(Column.getColumn(CRMTAB.TABLE, CRMTAB.TABID), Ids.toArray(), QueryConstants.IN);
		  		 SelectQuery sql= new SelectQueryImpl(Table.getTable(CRMTAB.TABLE));
	  	         sql.addSelectColumn(Column.getColumn(CRMTAB.TABLE,CRMTAB.TABID));
 	             sql.addSelectColumn(Column.getColumn(CRMTAB.TABLE,CRMTAB.NAME));
 	             sql.setCriteria(crt);
 	             DataObject moduleDO = PersistenceCacheUtil.getNonCachePersistenceHandle().get(sql);
 	             Iterator<Row> moduleRow = moduleDO.getRows(CRMTAB.TABLE);
			     while(moduleRow.hasNext())
			     {
	              Row mrow = moduleRow.next();
	              String modulename = (String)mrow.get(CRMTAB.NAME);
	              String tablename = EntityMetaDataUtil.getBaseTableByModuleName(modulename);
	   		 	  Table tabname = Table.getTable(tablename);
	   			  Persistence per = PersistenceCacheUtil.getPurePersistenceLiteHandle();
	   			  UpdateQuery uq = new UpdateQueryImpl(tablename);
	   			  uq.setUpdateColumn("ISAPPROVED", 1);//No I18n
	   			  Criteria cr = new Criteria(Column.getColumn(tabname.getTableName(),"ISAPPROVED"), 7, QueryConstants.EQUAL);
	   			  cr = cr.and(new Criteria(Column.getColumn(tabname.getTableName(),"SE_PRESENCE" ), 2, QueryConstants.EQUAL));
	   			  PKChunker chunk = new PKChunker(tabname.getTableName(), null, cr, per, 1000, true);
	   			  while (chunk.hasNext())
	   			  {
	   				 Criteria temp = chunk.next();
	   				 uq.setCriteria((temp != null) ? cr.and(temp) : cr);
	   				 per.update(uq);
	   			  }
			    }
		   	  }
		   }
		   catch(Exception e)
		   {
			   LOGGER.log(Level.SEVERE,"Exception Occurs when on removing the Draft Records from Review process in module table", e);
			   throw e;
		   }
	 }
	 
