  public void invokeOneTimeScheduler() throws Exception
  {
	    TimeZone tz = OrgUtil.getOrgOrPersonalUserTimeZone();
	    Timestamp currTimeInGMT = DateTimeUtils.getCurrentTimeInGMT();
	    Timestamp currTime = DateTimeUtils.convertDateTime(currTimeInGMT, TimeZone.getTimeZone(CrmConstants.GMT_TZ), tz);

		Long currentTimeInLong = currTime.getTime();
	    String currentZGID = OrgUtil.getCurrentZGID().toString();
		ZohoCRMBeanWOTImpl wotbean = (ZohoCRMBeanWOTImpl)ScopedAccess.getInstance(ZohoCRMBeanWOTImpl.class,currentZGID,TransactionType.NOSUPPORT);

	//	ZohoCRMBeanWOT wotbean=(ZohoCRMBeanWOT)BeanUtil.lookup(EmailStatsConstants.ZOHOCRMBEANWOT, currentZGID);
		try
		{
			wotbean.createEmailStatsScheduler(null, 0); // EmailStatsOneTimeScheduler
          CrmKeyValueUtil.insertOrUpdateCrmKeyValueByKeyName(EmailStatsConstants.EMAILSTATS_LASTLOAD, String.valueOf(currentTimeInLong),false);
			CrmKeyValueUtil.insertOrUpdateCrmNCKeyValueByKeyName(EmailStatsConstants.EMAILSTATS_AUTOMATION_KEY, "true", false);
			LOGGER.log(Level.WARNING, "EmailStats OneTime Scheduler job created through automation for zgid ::: {0}",new Object[]{currentZGID});//No I18N
		}
		catch(Exception e)
		{
			LOGGER.log(Level.WARNING, "EmailStats OneTime Scheduler job creation error through automation for zgid ::: {0}",new Object[]{currentZGID});//No I18N
		}
	 }
  
  
