  public void invokeEmailStorageScheduler() throws Exception
  {
	  String currentZGID = OrgUtil.getCurrentZGID().toString();
	 try{
		 JSONObject msObj=new JSONObject();
	 	 if(EmailStorageUtil.isEmailStorageAvailable(currentZGID)) {
		  Row row=CrmKeyValueUtil.getCrmKeyValueRow("EMAILSTORAGE_JOBID");//NO I18N
		  Long jobId=(Long) row.get("KEYID");

		  ZohoCRMSchedule.updateRepetitiveJobById(jobId, CoreScheduleConstants.RECURRING_HIGH_PROCESS, true, new Timestamp(System.currentTimeMillis()));
	      LOGGER.log(Level.INFO,"recurring job scheduled of email storage for zgid :: {0}",new Object[] {currentZGID}); //No I18N
	      msObj.put("info", "Email Storage recurring job scheduled");
	      resultObj.put("status", "success");//no i18n
		  resultObj.put("response",  msObj);
	  }
	  else{
	  	msObj.put("info", "recurring job not scheduled as Email Storage feature not enabled for this org");//No I18N
	    resultObj.put("status", "failure");//no i18n
		resultObj.put("response",  msObj);
	  }
	 }
	 catch(Exception e){
		LOGGER.log(Level.WARNING, "EmailStorage Scheduler job creation error through automation for zgid ::: {0}",new Object[]{currentZGID});//No I18N
		status = false;
		resultObj.put("response", e.toString());
		resultObj.put("status", "failure");//No I18N
	 }

  }

