  public JSONObject moveToOrg() throws JSONException{ // ###used
	  try {
		  IAMProxy proxy = IAMProxy.getInstance();
		  UserAPI userapi = proxy.getUserAPI();
		  OrgAPI orgapi = proxy.getOrgAPI();
		  Long zoid = OrgUtil.getZoidFromIAM(OrgUtil.getCurrentZGID());
		  if(zoid != -1){
			  resultObj.put("status", status);
			  resultObj.put("response", "Already migrated to org");
			  return resultObj;
		  }
		  ArrayList<Long> allUsersAuthList = CrmAllowedIPsUtil.getAuthDomainIDvsSourceID(-1L);
		  if(!allUsersAuthList.isEmpty()){
			  request.setAttribute("hideAllUsers", "yes");
		  }
		  if(zoid == -1){
			  long primayCntZuid = OrgUtil.getZUIDOfPrimaryContact(Long.valueOf(zgId));
			  String serviceName = ZohoCRMIAMUtil.SERVICENAME;
              ServiceOrg serviceOrg = CoreIAMUtil.getServiceOrgAPI().getServiceOrg(IAMServiceOrg.getType(), Long.valueOf(zgId));
			  if(!serviceOrg.isMigratedToOrg()){
                  CoreIAMUtil.getServiceOrgAPI().migrateToOrg(IAMServiceOrg.getType(), Long.valueOf(zgId),primayCntZuid);
              }
              //                iamProxy.getUserAPI().changeUserRole(primayCntZuid, UserRole.ADMIN);
              IAMUtil.clearTicketCache(request, serviceName);
              User user = proxy.getUserAPI().getUser(zuId);
			  zoid = user.getZOID();
			  if(zoid != -1){
				  proxy.getOrgAPI().updateOrgDisplayName(zoid, OrgUtil.getCompanyName());
			  }
		  }

		  resultObj.put("response", "moveToOrg executed successfully.");
	  } catch (Exception e) {
		  status = false;
		  resultObj.put("response", e.toString());
	  }
	  resultObj.put("status", status);
	  return resultObj;
  }

  public JSONObject addUser_toZOID() throws JSONException{ // ###used
	  try {
		  if (OrgUtil.isSandboxAccount(OrgUtil.getCurrentZGID())) {
			  resultObj.put("response", "addUser_toZOID action is not allowed for sandboxOrg.");
			  return resultObj;
		  }
		  String name = request.getParameter("userName");
		  String userValidity = "t5"; //NO I18N
          String isDevUser = request.getParameter("isDeveloperUser") != null ? request.getParameter("isDeveloperUser") : "";
          if ("true".equals(isDevUser)) {
        	  userValidity = "t999"; //No I18N
          }
		  IAMProxy proxy = IAMProxy.getInstance();
		  UserAPI userapi = proxy.getUserAPI();
		  OrgAPI orgapi = proxy.getOrgAPI();
		  Long zoid = OrgUtil.getZoidFromIAM(OrgUtil.getCurrentZGID());
		  List<OrgDomain> domains = orgapi.getAllOrgDomain(zoid);
		  boolean isBigin = CrmEnvironment.BIGIN.equals(CrmEnvironment.getCurrentEnvironment());

		  if(zoid==-1){
//			  enable_ip_restriction();
			  moveToOrg();
			  zoid = OrgUtil.getZoidFromIAM(OrgUtil.getCurrentZGID());
		  }
		  
		  if(isBigin && zoid == -1) {
	            Long primaryCntZuid = OrgUtil.getZUIDOfPrimaryContact(OrgUtil.getCurrentZGID());
	            User user = userapi.getUser(primaryCntZuid);
	            if(user != null) {
	                zoid = user.getZOID();
	            }
	            domains = orgapi.getAllOrgDomain(zoid);
	      }

		  if(domains==null||domains.isEmpty())
		  {
			  orgapi.addOrgDomain(zoid.toString(), zoid+".com", true, true);   //no i18n
		  }

		  String new_email = "zcrm_qa"+name+userValidity+"@"+zoid+".com";//No I18N
          String zuid_response = userapi.addUserToOrg(new_email, name, zoid, "Z1@crmtest", "test", "test", "en_IN",  "en_US", "IST", null, null,false,null); //no i18N
		  String new_zuid = zuid_response.substring(zuid_response.indexOf(':')+1, zuid_response.lastIndexOf(':'));

		  addZUIDtoOrg(new_zuid, new_email, isBigin, name);

		  resultObj.put("response", "addUser_toZOID executed successfully.");
	  }
	  catch (Exception e) {
		  LOGGER.log(Level.INFO, "Exception occured in addUser_toZOID reset method {0}", e);
		  status = false;
		  resultObj.put("response", e.toString());
	  }
	  resultObj.put("status", status);
	  return resultObj;
  }

