	public JSONObject deleteCFSegments() {
		String moduleName = request.getParameter("module");
		Long tabId;
		try {
			tabId = TabUtil.getTabIdByName(moduleName);
			String segmentTable =  CRMSEGMENTATION.TABLE + "s" ;  //No I18N
			Criteria cr = new Criteria(Column.getColumn(segmentTable, CRMSEGMENTATION.SEGMENTMODULE),tabId,QueryConstants.EQUAL);
			DataObject moduleDO = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(segmentTable,cr);
			cr = cr.and(new Criteria(Column.getColumn(segmentTable, CRMSEGMENTATION.STATUS),1,QueryConstants.NOT_EQUAL));
//			DataObject newModuleDO = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(segmentTable,cr);
			if(moduleDO.isEmpty() || !moduleDO.getDataObject(segmentTable, cr).isEmpty()){
				for (RFMConstants.RFM_CustomFields segPart : RFMConstants.RFM_CustomFields.values()) {
					Long fieldId = FieldUtil.getFieldIdByApiNm(segPart.name(),
							FieldUtil.getFieldDObyTabID(tabId, OrgUtil.getCurrentZGID()));
					try {
						FieldUtil.deleteCustomField(fieldId, moduleName, currentUserId,
								CreateUpdateEntityDetails.RFM_SEGMENTATION, OrgUtil.getCurrentZGID().toString(), false,
								true);
					} catch (Exception e) {
						FieldUtil.restoreDeletionMarkedField(moduleName, fieldId);
					}
				}
			}
			resultObj.put("status", true);
		} catch (Exception e1) {
			resultObj.put("status", false);
			resultObj.put("response", "RFM fields Not present");
		}

	  return resultObj;
  }
	public  JSONObject updateRepetitiveJob() {
		Timestamp time = new Timestamp(System.currentTimeMillis());
		ZCRMAdminBeanImpl zcrmAdmBean = new ZCRMAdminBeanImpl();
		try {
			Criteria crt = new Criteria(Column.getColumn(CRMKEYVALUE.TABLE, CRMKEYVALUE.KEYNAME),"DATEBASED_SCORING_SCHEDULER",QueryConstants.EQUAL);// NO I18N
			SelectQuery sql = new SelectQueryImpl(Table.getTable(CRMKEYVALUE.TABLE));
			//sql.addSelectColumns("*");
			sql.addSelectColumn(Column.getColumn(CRMKEYVALUE.TABLE, "*"));
			sql.setCriteria(crt);
			DataObject moduleDO = PersistenceCacheUtil.getNonCachePersistenceHandle().get(sql);
			Row row = moduleDO.getFirstRow(CRMKEYVALUE.TABLE);
			if(row != null){
			String jobId =  String.valueOf(row.get(CRMKEYVALUE.VALUE));
			jobId = jobId.split(";")[0];
			zcrmAdmBean.updateRepetitiveJobById(Long.valueOf(jobId), CoreScheduleConstants.RECURRING_LOW_PROCESS, true, time);
			status = true;
			}
		} catch (Exception e) {
			// TODO Auto-generated catch block
			status = false;
			//e.printStackTrace();
		}
		resultObj.put("status", status);
		return resultObj;

	}

	public JSONObject setCreatedTimeAsAssignedTime(){
 		try{
 			String module = request.getParameter("module");
 			Persistence per = PersistenceCacheUtil.getPersistenceLiteHandle();
 			String table = EntityMetaDataUtil.getBaseTableByModuleName(module);
 			SelectQuery sq = new SelectQueryImpl(Table.getTable(table));
 			String pkColumn = EntityMetaDataUtil.getPKColumnName(table);
 			sq.addSelectColumn(Column.getColumn(table, "*"));
 			Criteria crt = new Criteria( Column.getColumn( table, CRMLEADDETAILS.SE_PRESENCE), 1, QueryConstants.EQUAL );
 			Criteria se_statusCri = new Criteria( Column.getColumn( table, CRMLEADDETAILS.SE_STATUS), "c_"+CreateUpdateEntityDetails.MIGRATION, QueryConstants.EQUAL );
 			se_statusCri = se_statusCri.or(new Criteria( Column.getColumn( table, CRMLEADDETAILS.SE_STATUS), "cm_"+CreateUpdateEntityDetails.MIGRATION+"-"+CreateUpdateEntityDetails.MIGRATION, QueryConstants.EQUAL ));
 			crt = crt.and(se_statusCri);
 			sq.setCriteria(crt);
 			DOIterator iter = new DOIterator(per,sq,500);

 			while(iter.hasNext()){
 				DataObject counterDO = iter.next();
 				if(!counterDO.isEmpty()){
 					Iterator<Row> itr = counterDO.getRows(table);
 					HashMap<Long,Long> seidVsTime = new HashMap<Long,Long>();
 					while(itr.hasNext()){
 						Row row = itr.next();
 						String temp = row.get(CRMLEADDETAILS.CREATEDTIME).toString();
 						SimpleDateFormat dt = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss.S");
 						dt.setTimeZone(TimeZone.getTimeZone("GMT"));//no i18n
 						Date date = dt.parse(temp);
 						Long createdTime = date.getTime();
 						Long seid = (Long) row.get(pkColumn);
 						seidVsTime.put(seid, createdTime);
 						row.set(CRMLEADDETAILS.SE_STATUS, "c_"+CreateUpdateEntityDetails.IMPORT);//no i18n
 						counterDO.updateRow(row);
 					}
 					per.update(counterDO);
 					updateSharingTime(seidVsTime,module);
 				}
 			}
 			status = true;
 		}
 		catch(Exception e){
 			status = false;
 		}
 		resultObj.put("status", status);
		return resultObj;
 	}
	
	public JSONObject setCreatedTimeApprovalProcess(){
 		try{
 			
 			Persistence per = PersistenceCacheUtil.getNonCachePersistenceHandle();
 			
 			SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMRECORDAPPROVALSTATUS.TABLE));
 			sq.addSelectColumn(Column.getColumn(CRMRECORDAPPROVALSTATUS.TABLE, "*"));
 			Criteria crt = new Criteria(Column.getColumn(CRMRECORDAPPROVALSTATUS.TABLE, CRMRECORDAPPROVALSTATUS.ISAPPROVER_APPROVED), false, QueryConstants.EQUAL);
 			crt = crt.and(new Criteria(Column.getColumn(CRMRECORDAPPROVALSTATUS.TABLE, CRMRECORDAPPROVALSTATUS.PROCESSID), null, QueryConstants.NOT_EQUAL));
 			crt = crt.and(new Criteria(Column.getColumn(CRMRECORDAPPROVALSTATUS.TABLE, CRMRECORDAPPROVALSTATUS.FEATURE_TYPE), new Integer[] {2, 3},QueryConstants.IN));			
 			sq.setCriteria(crt);
 			 			
 			Calendar cal = Calendar.getInstance();
 	        Timestamp todaysDate = DateTimeUtils.getCurrentTimeInGMT();
 	        cal.setTimeInMillis(todaysDate.getTime());
 	        cal.add(Calendar.DATE, -(45));
 	        Timestamp result =  new Timestamp(cal.getTimeInMillis());
 	        
			DOIterator DOItr = new DOIterator(per, sq, 500);
			while(DOItr.hasNext())
			{
				DataObject dobj = DOItr.next();
				Iterator<Row> approvalRows = dobj.getRows(CRMRECORDAPPROVALSTATUS.TABLE);
				while(approvalRows.hasNext())
				{
					Row row = approvalRows.next();
		            row.set(CRMRECORDAPPROVALSTATUS.CREATEDTIME, result);
	                dobj.updateRow(row);
				}
				per.update(dobj);
			}
 			status = true;
			resultObj.put("response", "Approval Process Reset Date for CrmRecordApprovalStatus Table succeeded");
 			
 		}
 		catch(Exception e){
 			status = false;
			resultObj.put("response", "Approval Process Reset Date for CrmRecordApprovalStatus Table Failed");
 		}
		return resultObj;
 	}

 	private void updateSharingTime(HashMap<Long,Long> seidVsTime, String module) throws Exception
 	{
 		Persistence per = PersistenceCacheUtil.getPersistenceLiteHandle();
 		String parentModule=EntityMetaDataUtil.getParentModule(module);
		if(!parentModule.equals(module)){
			updateSharingTime(seidVsTime, parentModule);
		}
 		String sharingTable = EntityMetaDataUtil.getSharingTableByModuleName(module,false);
		SelectQuery sharingSQ = new SelectQueryImpl(Table.getTable(sharingTable));
		sharingSQ.addSelectColumn(Column.getColumn(sharingTable, "*"));
		Criteria sharingCrt = new Criteria(Column.getColumn(sharingTable, CRMSHARING.SHARINGSOURCE),20,QueryConstants.EQUAL);
		sharingCrt = sharingCrt.and(new Criteria(Column.getColumn(sharingTable, CRMSHARING.SEID),seidVsTime.keySet().toArray(),QueryConstants.IN));
		sharingSQ.setCriteria(sharingCrt);
		DataObject sharingDo = per.get(sharingSQ);
		Iterator<Row> iterator = sharingDo.getRows(sharingTable);
		while(iterator.hasNext()){
			Row row = iterator.next();
			Long seid = (Long) row.get(CRMSHARING.SEID);
			row.set(CRMSHARING.SHAREDTIME, seidVsTime.get(seid));
			sharingDo.updateRow(row);
		}
		per.update(sharingDo);
 	}

