 	public void removePitchKey() throws Exception {
		Long zgid = OrgUtil.getCurrentZGID() ;
		DataObject keyValueDO = CrmKeyValueUtil.getCachedKeyValueDO(zgid.toString());
		Criteria delCr;
		if(keyValueDO != null && !keyValueDO.isEmpty()) {
			List<Long> keyIds = new ArrayList<Long>();
			Criteria keyCri = new Criteria(Column.getColumn(CRMKEYVALUE.TABLE, CRMKEYVALUE.KEYNAME),"Forecast_Pitch_Scheduler",QueryConstants.EQUAL);
			Iterator<Row> keyValueRows = keyValueDO.getRows(CRMKEYVALUE.TABLE,keyCri);
			while(keyValueRows.hasNext()) {
				Row keyValueRow = keyValueRows.next();
				keyIds.add((Long)keyValueRow.get(CRMKEYVALUE.KEYID));
				if(keyIds.size() >= 10000) {
					delCr = new Criteria(Column.getColumn(CRMKEYVALUE.TABLE, CRMKEYVALUE.KEYID),keyIds.toArray(),QueryConstants.IN);
					CrmKeyValueUtil.deleteCrmKeyValueByCriteria(delCr, true, false);
					keyIds.clear();
				}
			}
			if(!keyIds.isEmpty()) {
				delCr = new Criteria(Column.getColumn(CRMKEYVALUE.TABLE, CRMKEYVALUE.KEYID),keyIds.toArray(),QueryConstants.IN);
				CrmKeyValueUtil.deleteCrmKeyValueByCriteria(delCr, true, false);
			}
		}
	}

