 	//Deleting field of lookup links for non subform lookup fields
	public JSONObject deleteFieldOfLookup() throws JSONException {
		try {
			List<String> modulenames = new ArrayList<String>();
			DataObject moduleDO = TabUtil.getAllTabsCachedDO();
			Iterator<Row> moduleiter = moduleDO.getRows(CRMTAB.TABLE);
			while (moduleiter.hasNext()) {
				Row modRow = moduleiter.next();
				modulenames.add((String) modRow.get(CRMTAB.NAME));
			}
			Long zgid = OrgUtil.getCurrentZGID();
			int modsize = modulenames.size();
			for(int i=0;i<modsize;i++){
				DataObject dobject = FieldUtil.getFieldsDOForModule(modulenames.get(i), zgid.toString());
				DataObject clonedobject = (DataObject) dobject.clone();
				if (!clonedobject.isEmpty()) {
					Iterator<Row> r = clonedobject.getRows(CRMFIELD.TABLE);
					while (r.hasNext()) {
						Row updateRow = r.next();
						Long tabId = (Long) updateRow.get(CRMFIELD.TABID);
						Long lookupfieldid = (Long) updateRow.get(CRMFIELD.LOOKUP_FIELDID);
						if (!TabUtil.isSubformModule(tabId) && lookupfieldid!=null) {
							updateRow.set(CRMFIELD.LOOKUP_FIELDID, null);
							updateRow.set(CRMFIELD.REFER_FROM_FIELDID, null);
							clonedobject.updateRow(updateRow);
						}
					}
					PersistenceCacheUtil.getNonCachePersistenceHandle().update(clonedobject);
				}
				resultObj.put("response", "All Field of lookup has been cleared"); //no i18n
			}
		} catch (Exception e) {
			status = false;
			resultObj.put("response", e.toString());
		}
		resultObj.put("status", status);
		return resultObj;
	}
	
