 	public JSONObject triggerZiaAction(String action, String revert){
		String response = null;
		Long zgid =  null;

		try{
			zgid = OrgUtil.getCurrentZGID();
    		OAuth.InternalOAuth internalAPI = OAuth.getInstance().new InternalOAuth();
    		JSONObject oauthJObj = internalAPI.getInternalOAuthCredential(zgid, "crm_org_oauth");//NO I18N
    		if ( oauthJObj != null && oauthJObj.length() > 0 )
    		{
    			Long getstartTime = DateTimeUtils.getCurrentLongTimeInGMT();
    			String url = IntegrationConstants.HTTPS + RebrandLinkUtil.getRebrandKeys("ZIAURL");//NO I18N
    			url += "/crm/zia/AssignmentRule?action="+action+"&zgid="+zgid;//NO I18N
    			if(action.equals("generateModel") || action.equals("generateModelScheduler")){
    				url += "&revert="+revert; //no i18n
    			}
    			HashMap<String, String> postParam = new HashMap<String,String>();
    			postParam.put( IAMConstants.AUTHORIZATION, oauthJObj.get(IAMConstants.API_KEY).toString() );
    			IntegrationUtil.setCRMOrgIdHeaderInPostParam(postParam, zgid);
                //LOGGER.info("triggerZiaAction postparam ::: "+postParam);
    			response = IntegrationUtil.connectAPIWithOrWithoutBodyWithConnectionTimeOut(postParam, url+"&iscsignature="+com.adventnet.iam.security.SecurityUtil.sign(), IntegrationConstants.GET_METHOD, null, 0, 0, null,-1,true).toString();//no i18n
    			LOGGER.info("Time taken for Zia API URL : "+url+" zgid :"+zgid+" and time taken is : "+(DateTimeUtils.getCurrentLongTimeInGMT()-getstartTime)+" ms ::: Response ::: "+response);
    			status = true;
    		}

    	}
		catch(Exception e){
    		String loggerMsg = "Exception occurred while connecting zia for action ::: "+action+" ::: zgid :: " + zgid+ " ::: response :: "+ response;//NO I18N
			LOGGER.log(Level.WARNING, loggerMsg, e );
			status = false;
		}
		resultObj.put("status", status);
		return resultObj;

 	}
 	
