 	public JSONObject setZiaRecordAssignedCount() {
 		status = false;
 		
 		String userid = request.getParameter("userId");
 		String module = request.getParameter("module");
 		String count = request.getParameter("count");
		LOGGER.log(Level.INFO, "setZiaRecordAssignedCount ::: userId : {0} ::: module : {1} ::: count : {2}", new Object[] {userid, module, count});
 		try {
 			int countInt = Integer.parseInt(count);
 			countInt = countInt >=0 ? countInt : 0;
 			Long tabId = TabUtil.getTabIdByName(module);
 			LOGGER.log(Level.INFO, "setZiaRecordAssignedCount ::: tabId : {0} ::: count : {1}", new Object[] {tabId, count});

 			if(tabId != null) {
	 			Persistence per = PersistenceCacheUtil.getPersistenceLiteHandle();
	 			SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMRECORDASSIGNCOUNTER.TABLE));
				sq.addSelectColumn(Column.getColumn(null, "*"));
				Criteria crt = new Criteria( Column.getColumn( CRMRECORDASSIGNCOUNTER.TABLE, CRMRECORDASSIGNCOUNTER.FEATURE), LARUtil.LAR_ZIA_RESTRICTION, QueryConstants.EQUAL );
//				crt = crt.and(new Criteria( Column.getColumn( CRMRECORDASSIGNCOUNTER.TABLE, CRMRECORDASSIGNCOUNTER.RECORD_ASSIGNED_COUNT), countInt, QueryConstants.NOT_EQUAL ));
				crt = crt.and(new Criteria( Column.getColumn( CRMRECORDASSIGNCOUNTER.TABLE, CRMRECORDASSIGNCOUNTER.TABID), tabId, QueryConstants.EQUAL ));
				crt = crt.and(new Criteria( Column.getColumn( CRMRECORDASSIGNCOUNTER.TABLE, CRMRECORDASSIGNCOUNTER.USER_ID), userid, QueryConstants.EQUAL ));
				sq.setCriteria(crt);
				DataObject dobj = per.get(sq);
	 			LOGGER.log(Level.INFO, "setZiaRecordAssignedCount ::: dobj : {0}", new Object[] {dobj});
				if(dobj == null || dobj.isEmpty()) {
					Row row = new Row(CRMRECORDASSIGNCOUNTER.TABLE);
					row.set(CRMRECORDASSIGNCOUNTER.FEATURE, LARUtil.LAR_ZIA_RESTRICTION);
					row.set(CRMRECORDASSIGNCOUNTER.RECORD_ASSIGNED_COUNT, countInt);
					row.set(CRMRECORDASSIGNCOUNTER.TABID, tabId);
					row.set(CRMRECORDASSIGNCOUNTER.USER_ID, userid);
					dobj.addRow(row);
					per.add(dobj);
					LOGGER.log(Level.INFO, "Previous value : 0 ::: Updated value : {0}", new Object[] {countInt});
					resultObj.put("response", "Previous value : 0 ::: Updated value : "+ countInt);
				}else {
					Row row = dobj.getFirstRow(CRMRECORDASSIGNCOUNTER.TABLE);
					Object prevValue = row.get(CRMRECORDASSIGNCOUNTER.RECORD_ASSIGNED_COUNT);
					row.set(CRMRECORDASSIGNCOUNTER.RECORD_ASSIGNED_COUNT, countInt);
					dobj.updateRow(row);
					per.update(dobj);
					LOGGER.log(Level.INFO, "Previous value : {0} ::: Updated value : {1}", new Object[] {prevValue, countInt});
					resultObj.put("response", "Previous value : "+prevValue+" ::: Updated value : "+ countInt);
				}
				status = true;
 			}
 		}catch(Exception e) {
 			resultObj.put("response", e.toString());
 		}
 		resultObj.put("status", status);
		return resultObj;
 	}

