	private void closeAccount(Long envZgid) throws Exception {
		LOGGER.log(Level.INFO, "closeAccount called for zuid {0} zgid {1}", new Object[] { zuId, envZgid });
		Long orgZOID = OrgUtil.getZoidFromIAM(Long.valueOf(envZgid));
		Long userIdOfProdOrg = UserUtil.getUserIdByZUID(zuId, String.valueOf(envZgid));
        LOGGER.log(Level.INFO, "UserId -- {0} by ZUID and ZGID  -- {1}", new Object[] {userIdOfProdOrg, envZgid});
		ZohoCRMBeanWOTImpl beanInstance = (ZohoCRMBeanWOTImpl) ScopedAccess.getInstance(ZohoCRMBeanWOTImpl.class, envZgid.toString(), TransactionType.SUPPORT);
//		CrmUser user = new CrmUser(userIdOfProdOrg);
//		user.setZuid(zuId);
        OrgContext orgContext = OrgContext.getInstance();
        orgContext.setCurrentUserId(userIdOfProdOrg);
//        orgContext.setCurrentZuid(zuId);
		CrmAccount org = new CrmAccount(envZgid);
		org.setZoid(orgZOID);
//		org.setClosedFrom(CrmAccount.ClosedAccountStatus.CLOSED_FROM_RESET);
        orgContext.setClosedFrom(OrgContextImpl.ClosedAccountStatus.CLOSED_FROM_RESET);
		beanInstance.closeAccount(org, orgContext);
		LOGGER.log(Level.INFO, "closeAccount complete for zuid {0} zgid {1}", new Object[] { zuId, envZgid });
	}

 	public JSONObject closeAppAccountForMDM(){
 		Long zoid = -1L;
 		String mdmServiceName = RebrandLinkUtil.getRebrandKeys("MDM_SERVICE");  //NO I18N
 		int mdmType = AccountsConstants.OrgType.MDM.getType();
 		try{
 			zoid = OrgUtil.getZoidFromIAM(zgId);
 	 		if(zoid == -1){
 	 			resultObj.put("response", "No ZOID");
 	 			return resultObj;
 	 		}

 			List<AppAccount> appAccounts = IAMProxy.getInstance().getAppAccountAPI().getAllAppAccountForAccount(mdmType, zoid + "", mdmServiceName);
 	 		if(appAccounts == null || appAccounts.size() == 0){
 	 			resultObj.put("response", "No appAccounts found for this account");
 	 			return resultObj;
 	 		}
 	 		resultObj.put("zaaid", appAccounts.get(0).getZaaid());
 	 		status = IAMProxy.getInstance().getAppAccountAPI().closeAppAccountService(mdmType, Long.parseLong(appAccounts.get(0).getZaaid()), mdmServiceName);
 		}catch(Exception e){
 			LOGGER.log(Level.WARNING, "MDM AppAccount Deletion ::: Exception occurred: ", e);
 		}

 		resultObj.put("status", status);
 		return resultObj;
     }


