 	public JSONObject populateActualValuesForPitch(){
		String pitchid = request.getParameter("pitchid");
		try{
			Long primaryUserId = (Long) request.getAttribute("USERID_FROM_FILTER");
			TimeZone orgTimeZone = OrgUtil.getOrgOrPersonalUserTimeZone();
			Locale locale = UserUtil.getUserLangLocaleByUserId(primaryUserId);
			UserMetadataHolder userMetaDataHolder = new UserMetadataHolder();
			userMetaDataHolder.setLocale(locale);
			userMetaDataHolder.setUserId(primaryUserId);
			userMetaDataHolder.setZgid(zgId.toString());
			InputStream inpStream = null;
			StrategyPlanner strategyplanner = null;
			DataObject dashboardDO = DashboardsDBService.getDashboardDOById(Long.parseLong(pitchid), primaryUserId, true, false, "ANALYTICS_PITCH");//NO I18N
			Criteria crt = new Criteria(Column.getColumn(CRMCHARTCONFIG.TABLE, CRMCHARTCONFIG.CHARTTYPE), ComponentType.PITCH.getTypeCode(), QueryConstants.EQUAL);
			crt = crt.and(new Criteria(Column.getColumn(CRMCHARTCONFIG.TABLE, CRMCHARTCONFIG.SUBTYPE), VisualizationType.PITCH_STRATEGY_PLANNER.getSubType(), QueryConstants.EQUAL));
			DataObject chartDO = dashboardDO.getDataObject(CRMCHARTCONFIG.TABLE, crt);
			Row chartRow = chartDO.getFirstRow(CRMCHARTCONFIG.TABLE);
			Long componentId = (Long) chartRow.get(CRMCHARTCONFIG.CCID);
			Row dbItemRow = new Row(CRMDASHBOARDITEMS.TABLE);
			dbItemRow.set(CRMDASHBOARDITEMS.DASHBOARDITEMSID_IDX, componentId);
			dbItemRow = dashboardDO.findRow(dbItemRow);
			Component component = DashboardsService.getComponentDetails(dashboardDO, dbItemRow, userMetaDataHolder, userMetaDataHolder.getLocale(),true);
			ComponentGenObj compGen = DashboardsUtil.generateComponentObj(component, null, primaryUserId, userMetaDataHolder.getLocale(), null, null);
			compGen.setObjectRelationship(component.getObject_relationship());
			compGen.setUserId(primaryUserId);
			compGen.setLocale(locale);
			inpStream = PitchCacheUtil.getFromCache(compGen.getConfigId(), AnalyticsInfoType.WEEK);
			strategyplanner = AnalyticsConstants.OBJECT_MAPPER_WITHOUT_ANNOTATIONS.readValue(inpStream, StrategyPlanner.class);
			PitchUtil.calculateActualValues(strategyplanner,compGen,com.adventnet.crm.api.commons.ISO8601Util.DBFormatToISO(DateTimeUtils.getCurrentTimeInGMT(),orgTimeZone,false), false, AnalyticsInfoType.WEEK,null, null, false,"v4"); //No I18N
			PitchUtil.formatPitchActualAndExpectedValues(compGen,strategyplanner);
			byte[] bytes = AnalyticsConstants.OBJECT_MAPPER_WITHOUT_ANNOTATIONS.writeValueAsBytes(strategyplanner);
			PitchCacheUtil.upsertInCache(primaryUserId, compGen.getConfigId(), AnalyticsInfoType.WEEK,  bytes);
			inpStream = PitchCacheUtil.getFromCache(compGen.getConfigId(), AnalyticsInfoType.MONTH);
			strategyplanner = AnalyticsConstants.OBJECT_MAPPER_WITHOUT_ANNOTATIONS.readValue(inpStream, StrategyPlanner.class);
			PitchUtil.calculateActualValues(strategyplanner,compGen,com.adventnet.crm.api.commons.ISO8601Util.DBFormatToISO(DateTimeUtils.getCurrentTimeInGMT(),orgTimeZone,false), false, AnalyticsInfoType.MONTH,null, null, false, "v4"); //No I18N
			PitchUtil.formatPitchActualAndExpectedValues(compGen,strategyplanner);
			bytes = AnalyticsConstants.OBJECT_MAPPER_WITHOUT_ANNOTATIONS.writeValueAsBytes(strategyplanner);
			PitchCacheUtil.upsertInCache(primaryUserId, compGen.getConfigId(), AnalyticsInfoType.MONTH,  bytes);
			inpStream = PitchCacheUtil.getFromCache(compGen.getConfigId(), AnalyticsInfoType.QUARTER);
			strategyplanner = AnalyticsConstants.OBJECT_MAPPER_WITHOUT_ANNOTATIONS.readValue(inpStream, StrategyPlanner.class);
			PitchUtil.calculateActualValues(strategyplanner,compGen,com.adventnet.crm.api.commons.ISO8601Util.DBFormatToISO(DateTimeUtils.getCurrentTimeInGMT(),orgTimeZone,false), false, AnalyticsInfoType.QUARTER,null, null, false, "v4"); //No I18N
			PitchUtil.formatPitchActualAndExpectedValues(compGen,strategyplanner);
			bytes = AnalyticsConstants.OBJECT_MAPPER_WITHOUT_ANNOTATIONS.writeValueAsBytes(strategyplanner);
			PitchCacheUtil.upsertInCache(primaryUserId, compGen.getConfigId(), AnalyticsInfoType.QUARTER,  bytes);
			
			
			crt = new Criteria(Column.getColumn(CRMCHARTCONFIG.TABLE, CRMCHARTCONFIG.CHARTTYPE), ComponentType.PITCH.getTypeCode(), QueryConstants.EQUAL);
			crt = crt.and(new Criteria(Column.getColumn(CRMCHARTCONFIG.TABLE, CRMCHARTCONFIG.SUBTYPE), VisualizationType.PITCH_PREDICTOR.getSubType(), QueryConstants.EQUAL));
			@SuppressWarnings("unchecked")
			Iterator<Row> iter = dashboardDO.getRows(CRMCHARTCONFIG.TABLE,crt);
			String week_str_date[] = DateTimeUtils.getDateRange("thisweek", orgTimeZone,"dd/MM/yyyy", FiscalUtil.getFiscal().intValue()-1, -1);//No I18N
			JSONObject requestBody = new JSONObject();
			requestBody.put("pitchid", pitchid);
			requestBody.put("zgid", zgId.toString());
			requestBody.put("start_period", week_str_date[0]);
			requestBody.put("end_period", week_str_date[1]);
			String response = PitchUtil.executeRequest("/crm/zia/pitch/v4/factors",requestBody,zgId,"POST");//No I18N
			strategyplanner = AnalyticsConstants.OBJECT_MAPPER_WITHOUT_ANNOTATIONS.readValue(response, StrategyPlanner.class);
			while(iter.hasNext())
			{
				chartRow = iter.next();
				componentId = (Long) chartRow.get(CRMCHARTCONFIG.CCID);
				dbItemRow = new Row(CRMDASHBOARDITEMS.TABLE);
				dbItemRow.set(CRMDASHBOARDITEMS.DASHBOARDITEMSID_IDX, componentId);
				dbItemRow = dashboardDO.findRow(dbItemRow);
				component = DashboardsService.getComponentDetails(dashboardDO, dbItemRow, userMetaDataHolder, userMetaDataHolder.getLocale(),true);
				compGen = DashboardsUtil.generateComponentObj(component, null, primaryUserId, userMetaDataHolder.getLocale(), null, null);
				compGen.setObjectRelationship(component.getObject_relationship());
				compGen.setUserId(userMetaDataHolder.getUserId());
				compGen.setLocale(userMetaDataHolder.getLocale());
				List<GroupingInfo> grps = component.getGroupings();
				String selectedImportantFieldColumnName = "";
				List<AllowedValue> allowedValues = new ArrayList<AllowedValue>();
				for(GroupingInfo grpInfo : grps)
				{
					if(grpInfo.getGrouping_config() != null && !grpInfo.getGrouping_config().getAllowed_values().isEmpty())
					{
						selectedImportantFieldColumnName = grpInfo.getName();
						allowedValues = grpInfo.getGrouping_config().getAllowed_values();
					}
				}
				List<String> grpAllowedValues = new ArrayList<String>();
				for(AllowedValue allowedValue : allowedValues)
				{
					grpAllowedValues.add(allowedValue.getValue());
				}
				ImportantFieldNameInfo curImportantFieldNameInfo = new ImportantFieldNameInfo();
				for(ImportantFieldNameInfo importantfieldInfo : strategyplanner.getImportant_categorical_fields())
				{
					String columnname = CrmFieldUtil.getFieldApiNameById(component.getObject_relationship().getBase_object().getModule(), importantfieldInfo.getField_id());
					if(selectedImportantFieldColumnName.equals(columnname))
					{
						curImportantFieldNameInfo = importantfieldInfo;
						break;
					}
				}
				inpStream = PitchCacheUtil.getFromCache(componentId, AnalyticsInfoType.WEEK);
				Predictor predictor = AnalyticsConstants.OBJECT_MAPPER_WITHOUT_ANNOTATIONS.readValue(inpStream, Predictor.class);
				inpStream = PitchCacheUtil.getFromCache(componentId, AnalyticsInfoType.MONTH);
				Predictor monthpredictor = AnalyticsConstants.OBJECT_MAPPER_WITHOUT_ANNOTATIONS.readValue(inpStream, Predictor.class);
				inpStream = PitchCacheUtil.getFromCache(componentId, AnalyticsInfoType.QUARTER);
				Predictor quarterpredictor = AnalyticsConstants.OBJECT_MAPPER_WITHOUT_ANNOTATIONS.readValue(inpStream, Predictor.class);
				List<PredictedValues> weekPredictions = com.zoho.crm.analytics.dashboards.pitch.v3.util.PitchUtil.getPredictions(predictor,componentId,AnalyticsInfoType.WEEK);
//				List<PredictedValues> yearPredictions = getPredictions(predictor,componentId,AnalyticsInfoType.YEAR);
				List<PredictedValues> monthPredictions = com.zoho.crm.analytics.dashboards.pitch.v3.util.PitchUtil.getPredictions(monthpredictor,componentId,AnalyticsInfoType.MONTH);
				List<PredictedValues> quarterPredictions = com.zoho.crm.analytics.dashboards.pitch.v3.util.PitchUtil.getPredictions(quarterpredictor,componentId,AnalyticsInfoType.QUARTER);
				if(!weekPredictions.isEmpty())
				{
					PitchUtil.calculatePredictorActualValues(predictor, compGen,AnalyticsInfoType.WEEK,curImportantFieldNameInfo,grpAllowedValues);
					bytes = AnalyticsConstants.OBJECT_MAPPER_WITHOUT_ANNOTATIONS.writeValueAsBytes(predictor);
					PitchCacheUtil.upsertInCache(primaryUserId, compGen.getConfigId(), AnalyticsInfoType.WEEK,  bytes);
				}
				if(!monthPredictions.isEmpty())
				{
					PitchUtil.calculatePredictorActualValues(monthpredictor, compGen,AnalyticsInfoType.MONTH,curImportantFieldNameInfo,grpAllowedValues);
					byte[] monthbytes = AnalyticsConstants.OBJECT_MAPPER_WITHOUT_ANNOTATIONS.writeValueAsBytes(monthpredictor);
					PitchCacheUtil.upsertInCache(primaryUserId, compGen.getConfigId(), AnalyticsInfoType.MONTH,  monthbytes);
				}
//				if(!yearPredictions.isEmpty())
//				{
//					com.zoho.crm.analytics.dashboards.pitch.util.PitchUtil.calculatePredictorActualValues(yearPredictorClone, compGen,AnalyticsInfoType.YEAR,curImportantFieldNameInfo,grpAllowedValues);
//					byte[] yearbytes = AnalyticsConstants.OBJECT_MAPPER_WITHOUT_ANNOTATIONS.writeValueAsBytes(yearPredictorClone);
//					PitchCacheUtil.upsertInCache(primaryUserId, compGen.getConfigId(), AnalyticsInfoType.YEAR,  yearbytes);
//				}
				if(!quarterPredictions.isEmpty())
				{
					PitchUtil.calculatePredictorActualValues(quarterpredictor, compGen,AnalyticsInfoType.QUARTER,curImportantFieldNameInfo,grpAllowedValues);
					byte[] quarterbytes = AnalyticsConstants.OBJECT_MAPPER_WITHOUT_ANNOTATIONS.writeValueAsBytes(quarterpredictor);
					PitchCacheUtil.upsertInCache(primaryUserId, compGen.getConfigId(), AnalyticsInfoType.QUARTER,  quarterbytes);
				}
			}
			resultObj.put("status", "success");
			return resultObj;
		}
		catch(Exception e)
		{
			status=false;
			resultObj.put("status", e);
			return resultObj;
		}
	}

