	public JSONObject generatePrescriptor() throws Exception
	{
		String pitchid = request.getParameter("pitchid");
		try {
			Long primaryUserId = (Long) request.getAttribute("USERID_FROM_FILTER");
			TimeZone orgTimeZone = OrgUtil.getOrgOrPersonalUserTimeZone();
			Locale locale = UserUtil.getUserLangLocaleByUserId(primaryUserId);
			UserMetadataHolder userMetaDataHolder = new UserMetadataHolder();
			userMetaDataHolder.setLocale(locale);
			userMetaDataHolder.setUserId(primaryUserId);
			userMetaDataHolder.setZgid(zgId.toString());
			DataObject dashboardDO = DashboardsDBService.getDashboardDOById(Long.parseLong(pitchid), primaryUserId, true, false, "ANALYTICS_PITCH");//NO I18N
			Criteria prescriptorCrt = new Criteria(Column.getColumn(CRMCHARTCONFIG.TABLE, CRMCHARTCONFIG.CHARTTYPE), ComponentType.PITCH.getTypeCode(), QueryConstants.EQUAL);
			prescriptorCrt = prescriptorCrt.and(new Criteria(Column.getColumn(CRMCHARTCONFIG.TABLE, CRMCHARTCONFIG.SUBTYPE), VisualizationType.PITCH_PRESCRIPTOR.getSubType(), QueryConstants.EQUAL));
			DataObject prescriptorDo = dashboardDO.getDataObject(CRMCHARTCONFIG.TABLE, prescriptorCrt);
			if(prescriptorDo.isEmpty())
			{
				Row chartRow = dashboardDO.getFirstRow(CRMCHARTCONFIG.TABLE);
				Long componentId = (Long) chartRow.get(CRMCHARTCONFIG.CCID);
				Row dbItemRow = new Row(CRMDASHBOARDITEMS.TABLE);
				dbItemRow.set(CRMDASHBOARDITEMS.DASHBOARDITEMSID_IDX, componentId);
				dbItemRow = dashboardDO.findRow(dbItemRow);
				Component component = DashboardsService.getComponentDetails(dashboardDO, dbItemRow, userMetaDataHolder, userMetaDataHolder.getLocale(),true);
				ItemProps strategy_planner_item_props = com.zoho.crm.analytics.common.AnalyticsConstants.OBJECT_MAPPER.readValue((String)dbItemRow.get(CRMDASHBOARDITEMS.ITEMPROPS_IDX),ItemProps.class);
				List<Component> newComponents = new ArrayList<Component>();
				ItemProps itemProps = new ItemProps();
				LayoutProps layoutProps = new LayoutProps();
				ObjectNode fl = AnalyticsConstants.OBJECT_MAPPER.valueToTree(component);
				layoutProps.setHeight("4");
				layoutProps.setWidth("12");
				layoutProps.setX("0");
				layoutProps.setY((Integer.valueOf(strategy_planner_item_props.getLayout().getHeight())+1)+"");
				Component prescriptor = AnalyticsConstants.OBJECT_MAPPER.convertValue(fl, Component.class);
//				BeanUtils.copyProperties(component, flawfinder);
				prescriptor.setId(null);
				prescriptor.setName("Prescriptor");//No I18N
				ObjectNode prescriptorlayoutPropsObj= AnalyticsConstants.OBJECT_MAPPER.valueToTree(layoutProps);
				LayoutProps prescriptorLayoutProps = AnalyticsConstants.OBJECT_MAPPER.convertValue(prescriptorlayoutPropsObj, LayoutProps.class);
//				BeanUtils.copyProperties(layoutProps, predictorLayoutProps);
				prescriptorLayoutProps.setY((Integer.valueOf(strategy_planner_item_props.getLayout().getHeight())+9)+"");
				ItemProps prescriptorItemProps = new ItemProps();
				BeanUtils.copyProperties(itemProps, prescriptorItemProps);
				prescriptorItemProps.setLayout(prescriptorLayoutProps);
				prescriptor.setItem_props(prescriptorItemProps);
				prescriptor.getComponent_props().getVisualization_props().setType(VisualizationType.PITCH_PRESCRIPTOR.getVisualizaionType());
				newComponents.add(prescriptor);
				ComponentsDBService.createComponents(Long.parseLong(pitchid), newComponents, userMetaDataHolder);
			}
			ComponentStatus status = com.zoho.crm.analytics.dashboards.pitch.util.PitchUtil.getPitchStatus(Long.parseLong(pitchid), zgId);
			String version = status.getVersion();
			com.zoho.crm.analytics.dashboards.pitch.v3.util.PitchUtil.calculatePrescriptorActualValues(dashboardDO, userMetaDataHolder, Long.parseLong(pitchid), zgId, primaryUserId, orgTimeZone, null, false,version);
			
			resultObj.put("status", "success");
			return resultObj;
		}
		catch(Exception e)
		{
			resultObj.put("status", e);
			return resultObj;
		}
	}
	public JSONObject enableOrDisableOldIndexingandSearch() throws JSONException
    {
        String actionToPerform=request.getParameter("actionToPerform");
        List<String> zuIdList=new ArrayList<String>();
        zuIdList.add(String.valueOf(zuId));
        if(actionToPerform!=null)
        {
            if(actionToPerform.equals("enableOldIndexingandSearch"))
            {
            	CoreFeatureUtil.addOrUpdateTrailOrg(CrmFeatureUtil.Feature.OLD_SEARCH_INDEXING_DISABLE.name(), zgId.toString(), zuIdList,CoreFeatureUtil.Type.ORG.name(), false, null);
            	CoreFeatureUtil.addOrUpdateTrailOrg(CrmFeatureUtil.Feature.NEWSEARCH.name(), zgId.toString(), zuIdList,CoreFeatureUtil.Type.ORG.name(), false, null);
                resultObj.put("response","OLD indexing and search enabled successfully");//no i18n
            }
            else
            {
            	CoreFeatureUtil.addOrUpdateTrailOrg(CrmFeatureUtil.Feature.OLD_SEARCH_INDEXING_DISABLE.name(), zgId.toString(), zuIdList,CoreFeatureUtil.Type.ORG.name(), true, null);
            	CoreFeatureUtil.addOrUpdateTrailOrg(CrmFeatureUtil.Feature.NEWSEARCH.name(), zgId.toString(), zuIdList,CoreFeatureUtil.Type.ORG.name(), true, null);
                resultObj.put("response","OLD indexing and search disabled successfully");//no i18n
            }
        }
        else
        {
            resultObj.put("response","Nothing was done.check your data...");//No I18N
        }
        resultObj.put("status", true);
        return resultObj;
    }

