	public static void changeZiaPresenceForNonMigratedAccount() throws Exception{
		if(! "True".equalsIgnoreCase(CrmKeyValueUtil.getCrmKeyValue("isZiaSetupMigRan"))){
			Criteria cri = new Criteria(Column.getColumn(CRMSETTINGS.TABLE,CRMSETTINGS.PRESENCE),-1 , QueryConstants.EQUAL);
			DataObject originalDObj =  CrmSettingsUtil.getSettingsDataObject(cri);
			if(!originalDObj.isEmpty()){
				Iterator<Row> rowItr = originalDObj.getRows(CRMSETTINGS.TABLE);
				while(rowItr.hasNext()){
					Row entityRow = rowItr.next();
					entityRow.set(CRMSETTINGS.PRESENCE, 1);
					originalDObj.updateRow(entityRow);
				}
			}
			PersistenceCacheUtil.getPurePersistenceLiteHandle().update(originalDObj);

		}


	}

	public static void delete_duplicate_zia_rows() throws Exception {
		try {
			SelectQuery settingsSQ =  new SelectQueryImpl(Table.getTable(CRMSETTINGS.TABLE));
			settingsSQ.addSelectColumn(Column.getColumn(null, "*"));
			Criteria ziaCrt = new Criteria(Column.getColumn(CRMSETTINGS.TABLE,CRMSETTINGS.API_NAME), "system.zia2", QueryConstants.EQUAL);
			Persistence pers = PersistenceCacheUtil.getPurePersistenceLiteHandle();
			settingsSQ.setCriteria(ziaCrt);
			DataObject setupDO = pers.get(settingsSQ);
			if(!setupDO.isEmpty() && setupDO.size(CRMSETTINGS.TABLE)  > 1) {
				Iterator<Row> rowItr = setupDO.getRows(CRMSETTINGS.TABLE);
				rowItr.next();
				while(rowItr.hasNext()) {
					Row row = rowItr.next();
					setupDO.deleteRow(row);

				}
				pers.update(setupDO);
			}
		}catch(Exception e) {
			LOGGER.log(Level.SEVERE, "Exception occured while delete migration of zia duplicate rows",e);
		}


	}

	public static void change_zia_presence() throws Exception {
		DataObject originalDObj =  CrmSettingsUtil.getSettingsDataObject();

	Row generalRow = originalDObj.getRow(CRMSETTINGS.TABLE, new Criteria(Column.getColumn(CRMSETTINGS.TABLE,CRMSETTINGS.API_NAME), "system.general", QueryConstants.EQUAL));
	Long parentId = Long.valueOf(generalRow.get(CRMSETTINGS.ELEMENT_ID).toString());

	Criteria ziaCrt = new Criteria(Column.getColumn(CRMSETTINGS.TABLE,CRMSETTINGS.API_NAME), "system.zia", QueryConstants.EQUAL);
	ziaCrt = ziaCrt.and(new Criteria(Column.getColumn(CRMSETTINGS.TABLE,CRMSETTINGS.PARENT_ID),parentId , QueryConstants.EQUAL));

	Row ziaRow = originalDObj.getRow(CRMSETTINGS.TABLE, ziaCrt);
	Long ziaId = Long.valueOf(ziaRow.get(CRMSETTINGS.ELEMENT_ID).toString());


	ziaCrt = new Criteria(Column.getColumn(CRMSETTINGS.TABLE,CRMSETTINGS.ELEMENT_ID), ziaId, QueryConstants.EQUAL);
	ziaCrt = ziaCrt.or(new Criteria(Column.getColumn(CRMSETTINGS.TABLE,CRMSETTINGS.PARENT_ID),ziaId , QueryConstants.EQUAL));

	DataObject existingDObj = originalDObj.getDataObject(CRMSETTINGS.TABLE, ziaCrt);
	Iterator<Row> rowItr = existingDObj.getRows(CRMSETTINGS.TABLE);
	while(rowItr.hasNext()){
		Row entityRow = rowItr.next();
		entityRow.set(CRMSETTINGS.PRESENCE, -1);
		existingDObj.updateRow(entityRow);
	}
	PersistenceCacheUtil.getPurePersistenceLiteHandle().update(existingDObj);

	}
