	public JSONObject autoResponseRules() {
		try {
			CrmWebEntityAutoRespRulesUtil.deleteAllAutoResponseRules();
            Persistence persistenceHandle = PersistenceCacheUtil.getPurePersistenceLiteHandle();
			SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMWEBENTITYAUTORESPRULES.TABLE));
			sq.addSelectColumn(Column.getColumn(null,"*"));
			Join join = new Join(CRMWEBENTITYAUTORESPRULES.TABLE,CRMWEBENTITYAUTORESPENTRY.TABLE,new String[]{CRMWEBENTITYAUTORESPRULES.RULEID},new String[]{CRMWEBENTITYAUTORESPENTRY.RULEID},Join.LEFT_JOIN);
			sq.addJoin( join );
			join = new Join(CRMWEBENTITYAUTORESPENTRY.TABLE,CRMEMAILADDRESSDETAILS.TABLE,new String[]{CRMWEBENTITYAUTORESPENTRY.ENTRYID},new String[]{CRMEMAILADDRESSDETAILS.FEATURERELATEDID},Join.LEFT_JOIN);
			sq.addJoin( join );
			DataObject dataObj =  persistenceHandle.get(sq);
			Iterator<Row> entryRows = dataObj.getRows(CRMWEBENTITYAUTORESPRULES.TABLE);
			if(entryRows.hasNext()){
				status = false;
				Row entryRow = entryRows.next();
				Long id = (Long)entryRow.get(CRMWEBENTITYAUTORESPRULES.RULEID);
				resultObj.put("response","Auto Response rules not deleted : "+id); //No I18N
			}else{
				resultObj.put("response","Auto Response rules deleted"); //No I18N
			}
		} catch (Exception e) {
			status = false;
			resultObj.put("response", e.toString());
		}
		resultObj.put("status", status);
		return resultObj;
	}

