	public JSONObject populatePaidCredits() throws Exception
	{
		String date = (String)request.getParameter("date");
		int count = Integer.valueOf((String)request.getParameter("count"));
		SimpleDateFormat format1 = new SimpleDateFormat(ISO8601Util.ISODATE_FORMAT);
		format1.setTimeZone(TimeZone.getTimeZone("GMT"));//NO I18N
		Date fromDate = format1.parse(date);
		{
			Criteria cr = new Criteria(Column.getColumn(CRMFEATUREUSAGECOUNTER.TABLE, CRMFEATUREUSAGECOUNTER.USAGEDATE), fromDate.getTime(),QueryConstants.GREATER_EQUAL);
			cr = cr.and(new Criteria(Column.getColumn(CRMFEATUREUSAGECOUNTER.TABLE, CRMFEATUREUSAGECOUNTER.USAGEDATE), fromDate.getTime()+86400000,QueryConstants.LESS_EQUAL));
			cr = cr.and(new Criteria(Column.getColumn(CRMFEATUREUSAGECOUNTER.TABLE, CRMFEATUREUSAGECOUNTER.FEATUREID), 6,QueryConstants.EQUAL));
			PersistenceCacheUtil.getPurePersistenceLiteHandle().delete(cr);
		}
		DataObject obj = new WritableDataObject();
        JSONArray slabJson = new JSONArray("[{\"count\":25000,\"amount\":0.14},{\"count\":75000,\"amount\":0.06},{\"count\":150000,\"amount\":0.05},{\"count\":250000,\"amount\":0.025}]");//NO I18N
        Row row = new Row(CRMFEATUREUSAGECOUNTER.TABLE);
        row.set(CRMFEATUREUSAGECOUNTER.FEATUREID, 6);
        row.set(CRMFEATUREUSAGECOUNTER.USAGECOUNT, count);
        DecimalFormat form = new DecimalFormat("0.00");
        int given = count+0;
        boolean continu = true;
        Float existValue = 0.0F;
        int length = slabJson.length();
        for ( int i = 0; i < length && continu ; i++ ) {
        	JSONObject json = slabJson.getJSONObject(i);
        	int jsoncount = json.getInt("count");//NO I18N
        	if ( given > jsoncount ) {
        		existValue += (json.getFloat("amount") * jsoncount/1000); //NO I18N
        		given -= jsoncount;
        	} else {
        		existValue += (json.getFloat("amount") * given/1000); //NO I18N
        		continu = false;
        	}
        }
        row.set(CRMFEATUREUSAGECOUNTER.TRACKINGFIELD1,Float.valueOf(form.format(existValue)));
        row.set(CRMFEATUREUSAGECOUNTER.TRACKINGFIELD2, "USD");//NO I18N
        row.set(CRMFEATUREUSAGECOUNTER.USAGEDATE, (fromDate.getTime()+43200000));
        obj.addRow(row);
        PersistenceCacheUtil.getPurePersistenceLiteHandle().add(obj);
        resultObj.put("response", count);
		return resultObj;
	}

	public JSONObject populateFunctionsPaidCredits() throws Exception
	{
		String date = (String)request.getParameter("date");
		int count = Integer.valueOf((String)request.getParameter("count"));
		SimpleDateFormat format1 = new SimpleDateFormat(ISO8601Util.ISODATE_FORMAT);
		format1.setTimeZone(TimeZone.getTimeZone("GMT"));//NO I18N
		List<String> enabledLang = CustomFunctionUtil.enabledLanguages();
		int totalLangCount = enabledLang.size();
		Date fromDate = format1.parse(date);
		{
			Criteria cr = new Criteria(Column.getColumn(CRMFEATUREUSAGECOUNTER.TABLE, CRMFEATUREUSAGECOUNTER.USAGEDATE), fromDate.getTime(),QueryConstants.GREATER_EQUAL);
			cr = cr.and(new Criteria(Column.getColumn(CRMFEATUREUSAGECOUNTER.TABLE, CRMFEATUREUSAGECOUNTER.USAGEDATE), fromDate.getTime()+86400000,QueryConstants.LESS_EQUAL));
			cr = cr.and(new Criteria(Column.getColumn(CRMFEATUREUSAGECOUNTER.TABLE, CRMFEATUREUSAGECOUNTER.FEATUREID), FeatureUsageCounterUtil.Feature.FUNCTIONS_PAYMENTS_SYNC.FeatureId(),QueryConstants.EQUAL));
			PersistenceCacheUtil.getPurePersistenceLiteHandle().delete(cr);
		}
		DataObject obj = new WritableDataObject();
        JSONArray slabJson = new JSONArray(CustomFunctionCredits.SLABJSON.toString());
        Row row = new Row(CRMFEATUREUSAGECOUNTER.TABLE);
        row.set(CRMFEATUREUSAGECOUNTER.FEATUREID, FeatureUsageCounterUtil.Feature.FUNCTIONS_PAYMENTS_SYNC.FeatureId());
        row.set(CRMFEATUREUSAGECOUNTER.USAGECOUNT, count);
        DecimalFormat form = new DecimalFormat("0.00");
        int given = count+0;
        boolean continu = true;
        Float existValue = 0.0F;
        int length = slabJson.length();
        for ( int i = 0; i < length && continu ; i++ ) {
        	JSONObject json = slabJson.getJSONObject(i);
        	int jsoncount = json.getInt("count");//NO I18N
        	if ( given > jsoncount ) {
        		existValue += (json.getFloat("amount") * jsoncount/1000); //NO I18N
        		given -= jsoncount;
        	} else {
        		existValue += (json.getFloat("amount") * given/1000); //NO I18N
        		continu = false;
        	}
        }
        row.set(CRMFEATUREUSAGECOUNTER.TRACKINGFIELD1,Float.valueOf(form.format(existValue)));
        Iterator<String> enabledLangIter = enabledLang.iterator();
    	while(enabledLangIter.hasNext())
		{
			String langName = enabledLangIter.next().toLowerCase();
			if(langName.equals("deluge")) {
				row.set(ZCloudUtil.getLanguageSpecificFeatureUsageCol(langName),( (count/totalLangCount) + (count%totalLangCount) ) );
			}else {
				row.set(ZCloudUtil.getLanguageSpecificFeatureUsageCol(langName),(count/totalLangCount) );
			}
		}
        row.set(CRMFEATUREUSAGECOUNTER.TRACKINGFIELD7, "USD");//NO I18N
        row.set(CRMFEATUREUSAGECOUNTER.USAGEDATE, (fromDate.getTime()+43200000));
        obj.addRow(row);

        List<JSONObject> slabJsonFullVal = CustomFunctionCredits.StaticUtils.getAllExtraCreditsRangeKey();
        int totalCount = count;
        Iterator<JSONObject> slabJsonFullValIter = slabJsonFullVal.iterator();
        while(slabJsonFullValIter.hasNext())
        {
        	JSONObject slabData = slabJsonFullValIter.next();
        	int from = slabData.getInt("from");//NO I18N
        	int to = slabData.getInt("to");//NO I18N
        	int rangeCount = (to == -1) ? from : to - from;
        	int currentCount = (totalCount - rangeCount <= 0) ? totalCount : rangeCount;
        	row = new Row(CRMFEATUREUSAGECOUNTER.TABLE);
       		row.set(CRMFEATUREUSAGECOUNTER.FEATUREID, FeatureUsageCounterUtil.Feature.FUNCTIONS_CREDITS_SLAB.FeatureId());
        	enabledLangIter = enabledLang.iterator();
	    	while(enabledLangIter.hasNext())
			{
				String langName = enabledLangIter.next().toLowerCase();
				if(langName.equals("deluge")) {
					row.set(ZCloudUtil.getLanguageSpecificFeatureUsageCol(langName), ( (currentCount/totalLangCount) + (currentCount%totalLangCount) ) );
				}else {
					row.set(ZCloudUtil.getLanguageSpecificFeatureUsageCol(langName),(currentCount/totalLangCount) );
				}
			}
        	row.set(CRMFEATUREUSAGECOUNTER.USAGECOUNT,currentCount );
        	row.set(CRMFEATUREUSAGECOUNTER.USAGEDATE, (fromDate.getTime()+43200000));
        	obj.addRow(row);
        	totalCount = totalCount - rangeCount;
        	if(totalCount <= 0)
        	{
        		break;
        	}
        }

        PersistenceCacheUtil.getPurePersistenceLiteHandle().add(obj);
        LOGGER.log(Level.INFO,"obj ::: {0}",new Object[]{obj});
        resultObj.put("response", "The given count " +count +" is updated in DB.");
		return resultObj;
	}

	public JSONObject getPaymentsDate() throws Exception {
		JSONObject json = new JSONObject();
		int orgtype = IAMServiceOrg.getType();
		long crmPlusOrgId = ZohoBundleAPIUtil.getAssociatedOrgId(orgtype,zgId);
		long zohoOneOrgId = ZohoOneAPIUtil.getAssociatedOrgId(orgtype,zgId);
		if ( crmPlusOrgId != -1 )
		{
			ZohoBundleOrg crmBundle = ZohoBundleAPIUtil.getZohoBundleOrg(orgtype, zgId);
			if(APIRateLimitCheck.isFlexInstance(crmBundle)) {
				json.put("serviceid", "970000");//NO I18N
				json.put("customid", String.valueOf(crmBundle.getOrgId()));//NO I18N
			}
			else {
				json.put("serviceid", "180000");//NO I18N
				json.put("customid", String.valueOf(crmPlusOrgId));//NO I18N
			}
		}
		else if ( zohoOneOrgId != -1 )
		{
			json.put("serviceid", "360000");//NO I18N
			json.put("customid", String.valueOf(zohoOneOrgId));//NO I18N
		}
		else
		{
			json.put("serviceid", "2");//NO I18N
			json.put("customid", String.valueOf(zgId));//NO I18N
		}
		json.put("source","api");//NO I18N
		json.put("zuid",String.valueOf(zuId));//NO I18N
		JSONObject paymentObj = StoreUtil.getSubscriptionDetails(zgId.toString());
		SimpleDateFormat format1 = new SimpleDateFormat(ISO8601Util.ISODATE_FORMAT);
		if ( paymentObj.has("next_payment_date") )
		{
			String to = paymentObj.getString("next_payment_date");
			Date temp = new SimpleDateFormat("yyyy-MM-dd").parse(to);
//			Date toDate = ISO8601Util.ISODateToDBFormat(to);
			Date currentDate = new Date(System.currentTimeMillis());
			Calendar currentCal = Calendar.getInstance();
			currentCal.setTime(currentDate);
			Calendar cal = Calendar.getInstance();
			cal.setTime(format1.parse(to));
			int date = cal.get(Calendar.DATE);
			int month = currentCal.get(Calendar.DATE) < date ?  currentCal.get(Calendar.MONTH) : currentCal.get(Calendar.MONTH) + 1;
			if ( month > 11 )
			{
				month = 0;
				cal.set(Calendar.YEAR,currentCal.get(Calendar.YEAR)+1);
			}
			else
			{
				cal.set(Calendar.YEAR,currentCal.get(Calendar.YEAR));
			}
			cal.set(Calendar.MONTH, month);
			Date datetime = cal.getTime();
			String toStr = format1.format(datetime);
			resultObj.put("response", toStr);
			resultObj.put("status", status);
		}
		else
		{
			resultObj.put("status", false);
		}
		return resultObj;
	}

	public JSONObject resetPayPerAPI() throws Exception {
		try
		{
			int exist_limit = FeatureEditionUtil.getFeatureLimitCount("API_PAID_CREDITS");//NO I18N
			if ( exist_limit < 0 )
			{
				exist_limit = 0;
			}
				JSONObject json = new JSONObject();
				int orgtype = IAMServiceOrg.getType();
				long crmPlusOrgId = ZohoBundleAPIUtil.getAssociatedOrgId(orgtype,zgId);
				long zohoOneOrgId = ZohoOneAPIUtil.getAssociatedOrgId(orgtype,zgId);
				if ( crmPlusOrgId != -1 )
				{
					ZohoBundleOrg crmBundle = ZohoBundleAPIUtil.getZohoBundleOrg(orgtype, zgId);
					if(APIRateLimitCheck.isFlexInstance(crmBundle)) {
						json.put("serviceid", "970000");//NO I18N
						json.put("customid", String.valueOf(crmBundle.getOrgId()));//NO I18N
					}
					else {
						json.put("serviceid", "180000");//NO I18N
						json.put("customid", String.valueOf(crmPlusOrgId));//NO I18N
					}
				}
				else if ( zohoOneOrgId != -1 )
				{
					json.put("serviceid", "360000");//NO I18N
					json.put("customid", String.valueOf(zohoOneOrgId));//NO I18N
				}
				else
				{
					json.put("serviceid", "2");//NO I18N
					json.put("customid", String.valueOf(zgId));//NO I18N
				}
				json.put("source","api");//NO I18N
				json.put("zuid",String.valueOf(zuId));//NO I18N
				HttpServletRequest request = IAMUtil.getCurrentRequest();
				if(request != null) {
					json.put("remoteuserip", request.getRemoteAddr()); //NO I18N
					json.put("signedremoteuserip", IAMUtil.generateRemoteUserIPSignature(request));
					json.put("useragent", IAMUtil.getUserAgent(request));
				}
				JSONObject paymentObj = StoreUtil.getSubscriptionDetails(zgId.toString());
				Integer count = null;
				if ( paymentObj.has("addondetails") )
				{
					JSONArray addonArr = paymentObj.getJSONArray("addondetails");//NO I18N
					for ( int i = 0; i < addonArr.length(); i++ )
					{
						JSONObject addon = addonArr.getJSONObject(i);
						if ( addon.optString("addonname","").equals("API Credits"))
						{
							count = Integer.valueOf(addon.getString("addonvalue"));
						}
					}
				}
				JSONObject resp = null;
				if ( count != null )
				{
					if ( count != exist_limit )
					{
						FeatureEditionUtil.setFeatureLimitCount("API_PAID_CREDITS", count, 0, 0,false);//NO I18N
					}
					String planId = LicenseUtil.getPlanIdByLicenseType(LicenseUtil.getLicenseType());
					json.put("subscription", new JSONObject().put(LicenseUtil.getAddonId(planId, SubscriptionBeanImpl.API_EXTRA_CREDIT),String.valueOf(0-count)));//NO I18N
					resp = StoreAPI.placeOrder(json);
				}
				else
				{
					resp = new JSONObject().put("success",true);
				}
				if ( resp.has("success") && resp.getBoolean("success"))
				{
					Criteria criteria = new Criteria((Column.getColumn(CRMFEATURELIMITS.TABLE, CRMFEATURELIMITS.FEATURENAME)), "API_PAID_CREDITS", QueryConstants.EQUAL);
					FeatureEditionUtil.deleteFeatureLimitsEntries(criteria, false, zgId.toString(), true);
				}
				else
				{
					status=false;
					resultObj.put("response", resp.toString());
				}
			}
		catch (Exception ex)
		{
			status = false;
		}
		resultObj.put("status", status);
		return resultObj;
	}

