    public JSONObject lockAndUnlockRecordForMerge() throws Exception
	{
    	try{
		String tableName=EntityMetaDataUtil.getBaseTableByModuleName(request.getParameter("module"));
		String pk=EntityMetaDataUtil.getPKColumnName(tableName);
		SelectQuery modSq=new SelectQueryImpl(Table.getTable(tableName));
		modSq.addSelectColumn(Column.getColumn(tableName,pk));
		modSq.addSelectColumn(Column.getColumn(tableName,"ISAPPROVED"));
		Criteria cri = new Criteria(Column.getColumn(tableName,pk),request.getParameter("recordid"),QueryConstants.EQUAL);
		modSq.setCriteria(cri);
		DataObject mastObj=PersistenceCacheUtil.getNonCachePersistenceHandle().get(modSq);
		if(!mastObj.isEmpty())
		{
			Row masterRow=mastObj.getFirstRow(tableName);
			/*if(Boolean.valueOf(request.getParameter("needLock")))
			{
				masterRow.set("ISAPPROVED",9);//No I18N
			}
			else
			{ */
				masterRow.set("ISAPPROVED",1);//No I18N
			//}
			mastObj.updateRow(masterRow);
			PersistenceCacheUtil.getNonCachePersistenceHandle().update(mastObj);
		}
            mastObj=PersistenceCacheUtil.getNonCachePersistenceHandle().get(modSq);
            Boolean stat = true;
            if(!mastObj.isEmpty())
            {
                Row masterRow=mastObj.getFirstRow(tableName);
                int val = Integer.parseInt(masterRow.get("ISAPPROVED").toString());//No I18N
                if(Boolean.valueOf(request.getParameter("needLock")) ){
                	if(val != 9){
                		stat = false;
                	}
                }else{
    				if(val != 1){
    					stat = false;
                	}
                }
            }
            if(stat){
            	resultObj.put("response","lockAndUnlockRecordForMerge performed as expected");//No I18N
            }else{
            	status = false;
            	resultObj.put("response","lockAndUnlockRecordForMerge not performed as expected");//No I18N
            }
    	}catch(Exception e){
    		status = false;
    		resultObj.put("response", "Error while changing record lock value");
    	}
    	resultObj.put("status", status);
        return resultObj;
	}
