	public void  deleteInvalidMxNLinkingModules() throws Exception{
		SelectQuery fldSql = new SelectQueryImpl(Table.getTable(CRMFIELD.TABLE));
		fldSql.addSelectColumn(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDID));
		fldSql.addSelectColumn(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.TABID));
		fldSql.addSelectColumn(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDLABEL));
		fldSql.addSelectColumn(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.SYS_REF_NAME));
		fldSql.addSelectColumn(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.COLUMNNAME));

		Criteria fldCrt = new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.UITYPE),new Integer[]{444,445},QueryConstants.IN);

		fldSql.setCriteria(fldCrt);
		DataObject fldDo  = PersistenceCacheUtil.getNonCachePersistenceHandle().get(fldSql);


		SelectQuery tabSql = new SelectQueryImpl(Table.getTable(CRMTAB.TABLE));
		tabSql.addSelectColumn(Column.getColumn(CRMTAB.TABLE, "*"));
		Criteria tabCrt = new Criteria(Column.getColumn(CRMTAB.TABLE, CRMTAB.GENERATEDTYPE),6,QueryConstants.EQUAL);
		tabCrt = tabCrt.and(new Criteria(Column.getColumn(CRMTAB.TABLE, CRMTAB.NAME),"LinkingModule*",QueryConstants.LIKE));
		tabCrt = tabCrt.and(new Criteria(Column.getColumn(CRMTAB.TABLE, CRMTAB.ISSYSTEMGENERATED),false,QueryConstants.EQUAL));
		tabSql.setCriteria(tabCrt);
    	Iterator<Row> tabRows = PersistenceCacheUtil.getNonCachePersistenceHandle().get(tabSql).getRows(CRMTAB.TABLE);


		List<String> invalidLinkingModList = new ArrayList<String>();
    	HashSet<String> deleteInvalidRowsLinkingModule = new HashSet<String>();
    	while(tabRows.hasNext()){

    		Row tabRow = tabRows.next();
    		String linkingModule = tabRow.get(CRMTAB.NAME).toString();
    		CrmCache childCache = new CrmCriteriaBasedCache(CoreSingleColumnCachedTables.LS_MODULE_REL_MODULE, linkingModule);


    		if(childCache.getDataObject().getRow(CRMLSMODULEREL.TABLE) == null){
    			invalidLinkingModList.add(linkingModule);

    		}


    	}

    	for(String module : invalidLinkingModList){
    		Long userId = OrgUtil.getUserIdOfPrimaryContact();
    		CrmModuleUtil.deleteModule(userId, module, null, true);
    	}
	}



