	public JSONObject createWorkFlow() throws Exception
	{
        String module=request.getParameter("module");
        String workflowName=request.getParameter("workflowName");
        String comparator1=request.getParameter("criteriaComparator1");
        String criteriaField1=request.getParameter("criteriaField1");
        String criteriaValue1=request.getParameter("criteriaValue1");

        String comparator2=request.getParameter("criteriaComparator2");
        String criteriaField2=request.getParameter("criteriaField2");
        String criteriaValue2=request.getParameter("criteriaValue2");

        String fieldUpdateName=request.getParameter("fieldUpdateName");
        String updateField=request.getParameter("updateField");
        String fieldUpdateValue=request.getParameter("fieldUpdateValue");
        try {
            ResetConfigWorkFlow wfbeanObj = (ResetConfigWorkFlow) ScopedAccess.getInstance(ResetConfigWorkFlow.class, OrgUtil.getCurrentZGID().toString(), TransactionType.REQUIREDNEW);
            wfbeanObj.createWorkFlowImpl(module,workflowName,criteriaField1,criteriaValue1,comparator1,criteriaField2,criteriaValue2,comparator2,fieldUpdateName,updateField,fieldUpdateValue);
            resultObj.put("status", true);
        } catch (Exception e) {
            resultObj.put("status", false);
            resultObj.put("response", "Error while creating workflow. "+e);
        }
        return resultObj;
    }
	
