	public JSONObject create_allowedips_without_movetoorg() throws Exception{
        if(OrgUtil.isSandboxAccount(zgId)){
            resultObj.put("status", false);
            resultObj.put("response", "Allowed ips is not supported in sandbox");
            return resultObj;
        }
        try{

        	Long zoid = OrgUtil.getZoidFromIAM(OrgUtil.getCurrentZGID());
    		List<AuthDomain> ads = IAMProxy.getInstance().getAuthDomainAPI().getAllAuthDomains(zoid.toString());
    		if(ads!=null){
    			AuthDomainAPI authAPI = IAMProxy.getInstance().getAuthDomainAPI();
    			for(AuthDomain ad : ads){
    				if(!authAPI.deleteAuthDomain(zoid,ad.getDomainName(),ZohoCRMIAMUtil.SERVICENAME)){
    					LOGGER.log(Level.INFO, "failed authdomain to delete internal 12-------------------> {0}",ad.getDomainName());
    				}
    			}
    		}
        	Criteria cr = new Criteria(Column.getColumn(CRMAUTHDOMAIN.TABLE , CRMAUTHDOMAIN.AUTH_DOMAIN_ID), null , QueryConstants.NOT_EQUAL);
    		PersistenceCacheUtil.getNonCachePersistenceHandle().delete(cr);

        	SelectQuery authDomainSq = new SelectQueryImpl(Table.getTable(CRMAUTHDOMAIN.TABLE));
    		authDomainSq.addSelectColumn(new Column(CRMAUTHDOMAIN.TABLE,CRMAUTHDOMAIN.AUTH_DOMAIN_ID));
    		authDomainSq.addSelectColumn(new Column(CRMAUTHDOMAIN.TABLE,CRMAUTHDOMAIN.SOURCE_ID));
    		DataObject doObj = PersistenceCacheUtil.getNonCachePersistenceHandle().get(authDomainSq);
    		Row row = new Row(CRMAUTHDOMAIN.TABLE);
    		row.set(CRMAUTHDOMAIN.SOURCE_ID, CommonDBService.getUniqueIdNoTransact());
    		row.set(CRMAUTHDOMAIN.SOURCE_TYPE, 2);
    		doObj.addRow(row);
    		PersistenceCacheUtil.getNonCachePersistenceHandle().add(doObj);
    		LOGGER.log(Level.INFO, "dummy authdomain create ==== {0}", row.get(CRMAUTHDOMAIN.SOURCE_ID)); // No I18n
            resultObj.put("response", "Success.");
        }
        catch(Exception e){
            status = false;
            resultObj.put("response", "unable to create allowed_ips Hours through ResetConfigurations.jsp. Exception > "+e.toString());
        }
        resultObj.put("status", status);
		return resultObj;
	}

