    /**This method resets the CRMTAB.CUSTOMIZED value for the module to false
     * if CRMTAB.TABLABEL and CRMTAB.SINGULARLABEL are in default values and
     * CRMTAB.CUSTOMIZED is true
     * @return resultObj
     */
    public JSONObject reset_customised() {
    	String moduleName = null;
    	try {
    		moduleName = request.getParameter("moduleName").toString();
    	}catch (Exception e) {
    		LOGGER.log(Level.SEVERE,"Exception occured while getting name from request. request.getParameter(\"moduleName\") = {0}",new Object[] {request.getParameter("moduleName")});
    		resultObj.put("response", "Error occured in resetting CrmTab.CUSTOMIZED to false because ".concat(e.getMessage()));
    		resultObj.put("status", false);
    		return resultObj;
		}
    	return resetConf.reset_customised(moduleName);
    }


    public boolean validateAndCreateCustomModulesForAutomation(int customModuleNumber, JSONObject moduleInfo, Long loginUserId, Locale locale, boolean craeteCF) throws Exception {
    	ArrayList<String> requiredKeysList = new ArrayList<String>(Arrays.asList("tabName","singularName","modulePermissionIds")); //No i18n
    	ArrayList<String> keysList =  new ArrayList<String>(moduleInfo.keySet());
    	if(!keysList.containsAll(requiredKeysList)) {
    		LOGGER.log(Level.SEVERE,"ModuleInfo does not contains all the required keys. available keys are {0} and required keys are {1}",new Object[] {keysList,requiredKeysList});
    		throw new MandatoryParameterMissingException("moduleInfo is missing one or many of keys ".concat(requiredKeysList.toString())); //No i18n
    	}
       IModuleContext iModuleCarrierDefintion = ModuleUtil.getIModuleCarrierDefintionForCreateModule();
       com.zoho.crmmeta.module.bean.Module moduleMeta = getModuleMetaForCreateCustomModules((String) moduleInfo.get("tabName"), (String) moduleInfo.get("singularName"), (String) moduleInfo.get("apiName"));
       String moduleName = CoreFeatureNameConstants.CUSTOM_MODULE + customModuleNumber;
       moduleMeta.getModuleBasicInfo().setName(moduleName);
       Long currentUserId = UserUtil.getCurrentUserId();
       if(loginUserId == null || loginUserId.longValue() != currentUserId.longValue()) {
           loginUserId = currentUserId;
       }
       iModuleCarrierDefintion.setCurrentUserId(loginUserId);
       //iModuleCarrierDefintion.setChangeNameToAutoNumberNeeded(false);
       //iModuleCarrierDefintion.setCustomModuleNumber(customModuleNumber);
       //ModuleUtil.setAllowedProfileIds(iModuleCarrierDefintion, (JSONArray)moduleInfo.get("modulePermissionIds"));
       JSONArray moduleProfilesJsonArray = moduleInfo.has("modulePermissionIds") ? (JSONArray) moduleInfo.get("modulePermissionIds") : CustomModuleUtil.getProfilesToAssociate(null, iModuleCarrierDefintion.getCurrentUserId(), false); // No I18n
       ModuleProfiles moduleProfiles = moduleMeta.getModuleProfiles();
       int len = moduleProfilesJsonArray.length();
       for(int i = 0 ; i < len ; i++) {
    	   ModuleProfile moduleProfile = (ModuleProfile) ModelUtil.getInstanceForORM(ModuleProfile.class);
    	   moduleProfile.setModuleId(moduleProfiles.getParentKeyForModel());
    	   moduleProfile.setProfileId(Long.parseLong(moduleProfilesJsonArray.get(i).toString()));
    	   moduleProfiles.add(moduleProfile);
       }
       return validateAndCreateCustomModulesForAutomation(moduleMeta, iModuleCarrierDefintion, craeteCF);
    }



    public boolean validateAndCreateCustomModulesForAutomation( com.zoho.crmmeta.module.bean.Module moduleMeta , IModuleContext iModuleCarrierDefintion, boolean craeteCF) throws Exception {
    	int customModuleNumber = -1;
		//check if the module already exists
        String moduleName = moduleMeta.getModuleBasicInfo().getName();
        if(StringUtils.isBlank(moduleName)) {
            customModuleNumber = CrmCustomModuleUtil.returnNextCustomModuleNumber();
            if (customModuleNumber <= 0) {
                throw new MandatoryParameterMissingException("CustomModuleNumber is not positive"); //No i18n
            }
            moduleName = CoreFeatureNameConstants.CUSTOM_MODULE.concat(String.valueOf(customModuleNumber));
        }else {
            customModuleNumber = Integer.parseInt(moduleName.replace(CoreFeatureNameConstants.CUSTOM_MODULE, "")); //No i18n
        }
        Long tabId = TabUtil.getTabIdByName(moduleName);
        Locale locale = iModuleCarrierDefintion.getCurrentLocale();
    	Long loginUserId = iModuleCarrierDefintion.getCurrentUserId();
        if(tabId == null) {
        	if (customModuleNumber <= 0) {
        		LOGGER.log(Level.SEVERE,"CustomModuleNumber is zero");
        		throw new MandatoryParameterMissingException("CustomModuleNumber is zero"); //No i18n
        	}
        	Criteria tabCriteria = new Criteria(new Column(CRMTAB.TABLE,CRMTAB.NAME),moduleName,QueryConstants.EQUAL);
        	tabCriteria = tabCriteria.or(new Criteria(new Column(CRMTAB.TABLE,CRMTAB.TABLABEL),moduleMeta.getModuleBasicInfo().getPluralLabel(),QueryConstants.EQUAL));
        	tabCriteria = tabCriteria.or(new Criteria(new Column(CRMTAB.TABLE,CRMTAB.SINGULARLABEL),moduleMeta.getModuleBasicInfo().getSingularLabel(),QueryConstants.EQUAL));
        	tabCriteria = tabCriteria.and(new Criteria(new Column(CRMTAB.TABLE,CRMTAB.PRESENCE),new Long(-2),QueryConstants.NOT_EQUAL));
        	DataObject tabsDO = TabUtil.getAllTabsCachedDO().getDataObject(CRMTAB.TABLE, tabCriteria);
        	if(tabsDO != null && !tabsDO.isEmpty()) {
        		String exString = "Custom Module Already Exists with name "+moduleName+" or pname "+moduleMeta.getModuleBasicInfo().getPluralLabel()+" or sname "+ moduleMeta.getModuleBasicInfo().getSingularLabel(); //No i18n
        		LOGGER.log(Level.INFO,exString);
        		throw new MandatoryParameterMissingException(exString);
        	}
        	JSONObject moduleValidatorJSON = CustomModuleJsonValidatorUtil.validateModuleLabels(moduleMeta.getModuleBasicInfo().getPluralLabel(), moduleMeta.getModuleBasicInfo().getSingularLabel(), null, locale);
        	if(moduleValidatorJSON != null && !moduleValidatorJSON.isEmpty()) {
        		throw new MandatoryParameterMissingException(moduleValidatorJSON.toString());
        	}
//        	Properties properties = new Properties();
//        	properties.put(CrmConstants.USERID_FROM_FILTER, loginUserId);
//        	properties.put(CrmConstants.LOCALE_FROM_FILTER, locale);
//        	properties.put("SYS_REF_NAME",moduleInfo.has("apiName")? moduleInfo.get("apiName"):moduleInfo.get("tabName")); //no i18n
//        	properties.put("moduleInfo", moduleInfo.toString()); //no i18n

        	//validate and put values in redis for creation
        	String[] redisKeys = {moduleName, moduleMeta.getModuleBasicInfo().getPluralLabel().concat("tabName"), moduleMeta.getModuleBasicInfo().getSingularLabel().concat("singularName")}; //No i18n
        	try {
        		for (String key : redisKeys) {
        			String redisKey = CustomModuleUtil.getKeyForCreatingModuleInRedis(CustomModuleUtil.getZgidForRedis(), key);
        			if(CrmCacheProxy.getStringExecutor(CrmFeature.BASIC).get(redisKey) != null && "working".equals(CrmCacheProxy.getStringExecutor(CrmFeature.BASIC).get(redisKey))) {
        				LOGGER.log(Level.SEVERE, "Could not create more custom module due to parallel threading and thus resulting in '{0}' ---- ",ResourceUtil.getResourceValueByKey("crm.mb.module.dplk", locale, null));
        				throw new Exception("Parallel threading for Create new Custom Module in Reset Configurations"+ResourceUtil.getResourceValueByKey("crm.mb.module.dplk", OrgUtil.getPrimaryUserLangLocale(), null));
        			}
        			CustomModuleUtil.putCreatingModuleInRedis(key);
        		}
        		LOGGER.log(Level.INFO,"Rediskeys added succesfully.");
        		//create CustomModule and do post creation processes
        		Row tabRow = CrmModuleUtil.createCustomModule(moduleMeta, iModuleCarrierDefintion);
        		
        		//create row for CRMSANDBOXCONFIGCHANGES table for providing sandbox tracking for module creation through ResetConfigurations.jsp

        		if(tabRow != null && OrgUtil.isSandboxAccount()) {
        			SandboxConfigUtil.trackChanges(tabRow.get(CRMTAB.TABID),"Module",tabRow.get(CRMTAB.TABLABEL).toString(),SandboxOperationType.CREATE,null,null);	//no i18n
        		}

        		if(tabRow == null || tabRow.get(CRMTAB.TABID) == null || tabRow.get(CRMTAB.NAME) == null) {
        			LOGGER.log(Level.SEVERE, "tabRow or tabid or crmtab.name is null {0}",new Object[] {tabRow});
        		}
        		tabId = (Long) tabRow.get(CRMTAB.TABID);
        		moduleName = (String) tabRow.get(CRMTAB.NAME);
                //Need to be arrested inside com.zoho.crm.core.meta.tabs.custommodule.CustomModuleUtil.createCustomModule(Properties, int, boolean)
        		if((int)tabRow.get(CRMTAB.ACCESSTYPE) == 1) {
        			DataObject userProfileRelDobj = PersistenceCacheUtil.getNonCachePersistenceHandle().constructDataObject();
        			List<long[]> userPrivateProfile = new ArrayList<long[]>() {{
        	            add(new long[]{iModuleCarrierDefintion.getCurrentUserId(), ProfileUtil.getAdminPrivateProfileId() });
        	        }};

        			CustomModuleUtil.addPrivateProfileToTeamModule( userProfileRelDobj , userPrivateProfile, tabId);
        			PersistenceCacheUtil.getNonCachePersistenceHandle().add(userProfileRelDobj);
        		}
        		//end

				/* Connected Records related handling - Start */
				DataObject relatedListMetaDO = RelatedListMetaUtil.getAllCachedSortedListsRelationDO();
				Criteria connectedRecordRLCr = new Criteria(Column.getColumn(CRMLISTSRELATION.TABLE, CRMLISTSRELATION.SYS_REF_NAME), EntityMetaDataUtil.CONNECTED_RECORDS_SYS_REF_NAME, QueryConstants.EQUAL);
				connectedRecordRLCr = connectedRecordRLCr.and(new Criteria(Column.getColumn(CRMLISTSRELATION.TABLE, CRMLISTSRELATION.LISTLABEL),EntityMetaDataUtil.CONNECTED_RECORDS_LISTLABEL , QueryConstants.EQUAL));
				DataObject existingCRRLDO = relatedListMetaDO.getDataObject(CRMLISTSRELATION.TABLE, connectedRecordRLCr);
				List<Long> allTeamTabIds = TabUtil.getTeamModulesIdAsList();
				if((int)tabRow.get(CRMTAB.ACCESSTYPE) == 1){
					DataObject connectedRecordsDO = PersistenceCacheUtil.getPurePersistenceLiteHandle().constructDataObject();
					Boolean isUpdatedNeeded = false;
					Criteria connectedToFieldCr = new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.SYS_REF_NAME), com.zoho.crm.core.common.Constants.CONNECTED_TO_SYS_REF_NAME, QueryConstants.EQUAL);
					connectedToFieldCr = connectedToFieldCr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.UITYPE), 132, QueryConstants.EQUAL));
					connectedToFieldCr = connectedToFieldCr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.TABID), tabId, QueryConstants.EQUAL));
					Row mmlField = FieldUtil.getFieldRow( connectedToFieldCr);
					if(mmlField != null) {
						Criteria statusFieldCr = new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.SYS_REF_NAME), "Status", QueryConstants.EQUAL);
						statusFieldCr = statusFieldCr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.UITYPE), 2,QueryConstants.EQUAL));
						statusFieldCr = statusFieldCr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.TABID), tabId,QueryConstants.EQUAL));
						Row statusFieldRow =  FieldUtil.getFieldRow(statusFieldCr);
						if (statusFieldRow != null) {
							Row statusDisplayColummn = new Row(CRMDISPLAYCOLUMNS.TABLE);
							statusDisplayColummn.set(CRMDISPLAYCOLUMNS.TABID, statusFieldRow.get(CRMFIELD.TABID));
							statusDisplayColummn.set(CRMDISPLAYCOLUMNS.FIELDID, statusFieldRow.get(CRMFIELD.FIELDID));
							statusDisplayColummn.set(CRMDISPLAYCOLUMNS.TABLENAME, statusFieldRow.get(CRMFIELD.TABLENAME));
							statusDisplayColummn.set(CRMDISPLAYCOLUMNS.COLUMNNAME, statusFieldRow.get(CRMFIELD.COLUMNNAME));
							statusDisplayColummn.set(CRMDISPLAYCOLUMNS.FIELDLABEL, statusFieldRow.get(CRMFIELD.FIELDLABEL));
							statusDisplayColummn.set(CRMDISPLAYCOLUMNS.SORTORDERID, 5);
							connectedRecordsDO.addRow(statusDisplayColummn);
						}
						/* We will get the all eligible modules using below method and will add the list relation for that modules */
						JSONArray moduleDetails = ConnectedRecordsUtil.getAllEligibleModulesForMMLField(false);
						Long childCustomization = RelatedList.CUSTOMIZATIONS.getValue(Arrays.asList(RelatedList.CUSTOMIZATIONS.CUSTOMIZE_SEQUENCE, RelatedList.CUSTOMIZATIONS.CUSTOMIZE_LABEL, RelatedList.CUSTOMIZATIONS.CUSTOMIZE_RELATEDLIST_FIELDS, RelatedList.CUSTOMIZATIONS.CUSTOMIZE_SORTCOLUMN));

						/* List Relation for MML field */
						int tabSeq = 1;
						for (Object moduleDetail : moduleDetails) {
							JSONObject moduleJO = (JSONObject) moduleDetail;
							String parentTabName = moduleJO.getString(CustomModuleConstants.JSON_KEY_MODULE_NAME);
							Long parentTabId = moduleJO.getLong(CoreFieldConstants.ID);
							if (!parentTabId.equals(tabId)) {
								RelatedList parentRelatedList = RelatedListMetaUtil.constructConnectRecordsRL(connectedRecordsDO, tabId);
								Row parentRLRow = RelatedListMetaUtil.checkAndInsertParentRLPresentIfPresent(parentTabId, relatedListMetaDO, connectedRecordsDO, parentRelatedList);

								String childRelName = ConnectedRecordsUtil.getChildRelNameForConnectedRecord(relatedListMetaDO, parentRLRow.get(CRMLISTSRELATION.LISTRELATIONID), parentTabName, null);
								Row lsModuleRelRow = LookUpFieldUtil.getLSModuleRelRow(mmlField, parentTabName, moduleName, childRelName, childRelName, CustomModuleConstants.SEID, true, tabSeq, 1, 1, "SID", "SI");  // no i18n
								connectedRecordsDO.addRow(lsModuleRelRow);

								HashMap<String, Object> extraProperties = new HashMap<String, Object>();
								extraProperties.put(CRMLISTSRELATION.PARENT_LISTRELATIONID, parentRLRow.get(CRMLISTSRELATION.LISTRELATIONID));
								extraProperties.put(CRMLISTSRELATION.CUSTOMIZATIONS, childCustomization);
								//sys ref name generation as per the isSystemRL value given.
								String tempFldLblApiNm = FieldUtil.genFldNameForApi(childRelName, "relatedlist");//NO I18N
								String apiname = RelatedListMetaUtil.genRelListName(tempFldLblApiNm, parentTabName, null, false, true);

								Row listsRelationRow = RelatedListMetaUtil.insertCrmListsRelationRow(parentTabId, (moduleName + "PERSONALITY").toUpperCase(), RelatedListMetaUtil.getListNextSeq(relatedListMetaDO, parentTabId), childRelName, apiname, lsModuleRelRow.get(CRMLSMODULEREL.MODULERELID), connectedRecordsDO, 1, extraProperties);  // no i18n
								Iterator<Row> layoutsRows = PageLayoutUtil.getAllLayoutCachedDO(parentTabId).getRows(CRMPAGELAYOUT.TABLE);
								Long layoutId, layoutSeq = null;
								while (layoutsRows.hasNext()) {
									layoutId = (Long) layoutsRows.next().get(CRMPAGELAYOUT.LAYOUTID);
									layoutSeq = Long.valueOf(PageLayoutUtil.getListSequenceForLayout(parentTabId, layoutId));
									RelatedListMetaUtil.insertCrmListsRelationLayoutRelRow(listsRelationRow.get(CRMLISTSRELATION.LISTRELATIONID), layoutId, layoutSeq, connectedRecordsDO, 1, parentTabId);
								}
								tabSeq++;
								isUpdatedNeeded = true;
							}
						}
					}
					if (allTeamTabIds.size() > 1 && (existingCRRLDO!= null && !existingCRRLDO.isEmpty())) {
						allTeamTabIds.remove(tabId);
						ConnectedRecordsUtil.addLookUpModuleForConnectedToField(relatedListMetaDO, connectedRecordsDO, tabId, moduleName, allTeamTabIds, false);
						isUpdatedNeeded = true;
					}
					if(isUpdatedNeeded){
						PersistenceCacheUtil.getPurePersistenceLiteHandle().update(connectedRecordsDO);
						//To populate the layout rule
						FormRuleUtil.sendAllLayoutIdsToAllClient();
					}
				}


				if ((int)tabRow.get(CRMTAB.ACCESSTYPE) == 0 && allTeamTabIds.size() > 0  && (existingCRRLDO!= null && !existingCRRLDO.isEmpty())) {
					/* Create ConnnectedRecord parentRL for newly created module */
					DataObject connectedRecordsDO = PersistenceCacheUtil.getPurePersistenceLiteHandle().constructDataObject();
					ConnectedRecordsUtil.addLookUpModuleForConnectedToField(relatedListMetaDO, connectedRecordsDO, tabId, moduleName, allTeamTabIds, false);
					PersistenceCacheUtil.getPurePersistenceLiteHandle().update(connectedRecordsDO);
				}

				/* Connected Records related handling - End */
        		 HashMap<String ,String> customModuleValues = new HashMap();
        		customModuleValues.put("moduleNumber",String.valueOf(customModuleNumber));
        		customModuleValues.put("name",moduleName);
        		populateUnsubscribedModePickListLayoutRel(moduleName);
        	    WebformAnalyticsUtil.addAnalyticsSupportForCustomModules(customModuleValues);
                // default custom view population for new flow
                if(CustomViewUtil.isCustomViewRQFlow())
                {
                    boolean isLinkingModule = moduleName.startsWith("LinkingModule") ? true : false;//No I18N
                    SystemCustomViewPopulationHelper.populateCVDoForCustomModule(null, isLinkingModule ? CVJsonTemplates.LINKING_MODULE : CVJsonTemplates.CUSTOM_MODULE, moduleMeta.getModuleBasicInfo().getName(), loginUserId);
                }
        	    CrmModuleUtil.postModuleCreationHandlingForSurveyIntegration(tabRow);
        	    CustomViewUtil.setDefaultCVName(moduleName,userId);
        	    RecordLockingUtil.populateCustomModuleRows(ProfileUtil.getAllProfileIds(), PageLayoutUtil.getMasterLayoutIdForTabId(tabId), tabRow, ProfileUtil.getProfileDOForModules(new String[]{CrmSecurityConstants.IMPLIED_ROLE_CONTACTHIERARCHY+"_"+moduleName}), false);
        		AuditLogUtil.addEntryInAuditLog(moduleName,CrmModuleUtil.CUSTOMMODULE_CREATED_AUDIT_LOGMSG,null,tabId,null,CreateUpdateEntityDetails.API,AuditLogConstants.AUDIT_ACTION_CREATE,null,null);
        		
        		//Below line used to send kafka notification of creating custom module via integration
				new KafkaMetaDataUtil().pushCustomModuleCreationViaIntegrationToKafka(tabRow);
				
        	}catch (Exception e) {
        		LOGGER.log(Level.SEVERE, "Could not create custom module and add auditLog entry.",e);
        		throw e;
        	}finally {
        		for (String key : redisKeys) {
        			String redisKey = CustomModuleUtil.getKeyForCreatingModuleInRedis(CustomModuleUtil.getZgidForRedis(), key);
        			if(CrmCacheProxy.getStringExecutor(CrmFeature.BASIC).get(redisKey) != null) {
        				CrmCacheProxy.getBaseExecutor(CrmFeature.BASIC).delete(redisKey);
        			}
        		}
        		LOGGER.log(Level.INFO,"Rediskeys deleted succesfully.");
        	}
        }

        //add or update the section or field
		if(craeteCF && tabId != null) {
			JSONObject updateModuleInfo = returnJSON(tabId.toString(), PageLayoutUtil.getMasterLayoutIdForTabId(tabId).toString(), moduleName);
			CustomModuleUtil.updateModuleDetails(updateModuleInfo, tabId, new JSONObject(), loginUserId, locale, OrgUtil.getCurrentZGID().toString());
		}else {
			LOGGER.log(Level.INFO, "CustomModule created without adding or updating any section or field for the module {0}",new Object[] {moduleName});
		}
		return true;
	}



    public JSONObject populateUnsubscribedModePickListLayoutRel(){
    	try{
    		String moduleName = request.getParameter("module");
    		boolean status = populateUnsubscribedModePickListLayoutRel(moduleName);
    		resultObj.put("status", status);
    	}catch(Exception e){
    		resultObj.put("status", false);
    		resultObj.put("response", "Error while populateUnsubscribedModePickListLayoutRel");
    	}
    	return resultObj;

    }

    /**
     * @param moduleName
     */
    private boolean populateUnsubscribedModePickListLayoutRel(String moduleName)
    {
    	try {
    		Persistence pers = PersistenceCacheUtil.getPurePersistenceLiteHandle();
    		String baseTable = EntityMetaDataUtil.getBaseTableByModuleName(moduleName);
    		String zgid = OrgUtil.getCurrentZGID().toString();
    		Long fieldId = CrmFieldUtil.getFieldId(baseTable, CrmConstants.UNSUBSCRIBEDMODE);

    		DataObject modeFieldsDo = CrmFieldUtil.getModeFieldsDOForGivenFieldId(zgid, fieldId, null);
    		DataObject pickListDO =  PickListFieldUtil.getAllPicklistDOForFieldId( fieldId, zgid);
    		DataObject pickListLayoutRelDo = PickListFieldUtil.getPickListDOwithLayoutRelForFieldIds(Arrays.asList(fieldId), null, zgid);
    		DataObject addedObj = pers.constructDataObject();
    		
    		LOGGER.log(Level.INFO, "populateUnsubscribedModePickListLayoutRel migration started for module: {0}, baseTable: {1}, fieldId: {2}", new String[] {moduleName, baseTable, fieldId.toString()});

    		Iterator<Row> modeFields = modeFieldsDo.getRows(CRMMODEFIELD.TABLE);

    		while(modeFields.hasNext())
    		{ 
    			Row modeField = modeFields.next();
    			Long layoutId = (Long) modeField.get(CRMMODEFIELD.LAYOUTID);

    			Iterator<Row> pickListValues = pickListDO.getRows(CRMPICKLISTVALUES.TABLE, new Criteria(Column.getColumn(CRMPICKLISTVALUES.TABLE, CRMPICKLISTVALUES.FIELDID), fieldId, QueryConstants.EQUAL));

    			while(pickListValues.hasNext())
    			{
    				Row pickListRow = pickListValues.next();
    				Long uniqueId = (Long) pickListRow.get(CRMPICKLISTVALUES.UNIQUEID);

    				Criteria cri = new Criteria(Column.getColumn(CRMPICKLISTLAYOUTREL.TABLE, CRMPICKLISTLAYOUTREL.LAYOUTID), layoutId, QueryConstants.EQUAL);
    				cri = cri.and(new Criteria(Column.getColumn(CRMPICKLISTLAYOUTREL.TABLE, CRMPICKLISTLAYOUTREL.UNIQUEID), uniqueId, QueryConstants.EQUAL));

    				if(pickListLayoutRelDo.getRow(CRMPICKLISTLAYOUTREL.TABLE, cri) == null) {
    					addedObj.addRow(PickListFieldUtil.createCRMPicklistLayoutRelRow(uniqueId, layoutId, pickListRow.get(CRMPICKLISTVALUES.SORTORDERID)));
    				}
    			}
    		}

    		if(!addedObj.isEmpty()) {
    			pers.add(addedObj);
    			LOGGER.log(Level.INFO, "populateUnsubscribedModePickListLayoutRel migration completed for module: {0}, addedObj: {1}", new Object[] {moduleName, addedObj});
    			return true; 
    		}else {
    			LOGGER.log(Level.INFO, "populateUnsubscribedModePickListLayoutRel migration not completed for module: {0}, modeFieldsDo: {1}, pickListDO: {2}, pickListLayoutRelDo: {3}", new Object[] {moduleName, modeFieldsDo, pickListDO, pickListLayoutRelDo});
    		}
    	}
    	catch(Exception e) {
    		LOGGER.log(Level.SEVERE,"populateUnsubscribedModePickListLayoutRel : {0}", new Object[] {e});
    	}
    	
    	return false;
    }

	public JSONObject getModuleInfoForCreateCustomModules(String pluralLabel,String singularLabel,String apiName,JSONArray profileIds) throws Exception {
		JSONObject details = new JSONObject();
		if(profileIds == null || profileIds.isEmpty() || singularLabel == null || singularLabel.isEmpty() || pluralLabel == null || pluralLabel.isEmpty() || apiName == null | apiName.isEmpty()){
			LOGGER.log(Level.SEVERE,"null or empty : profileIds = {0} , singularLabel = {1} , pluralLabel = {2} , apiName = {3} ",new Object[] {profileIds, singularLabel, pluralLabel, apiName});
			throw new MandatoryParameterMissingException();
		}
		pluralLabel = pluralLabel.trim().replaceAll("\\s+"," ");
		singularLabel = singularLabel.trim().replaceAll("\\s+"," ");
		details.put("tabName", pluralLabel); //no i18n
		details.put("singularName", singularLabel); //no i18n
		details.put("apiName", apiName);//no i18n
		details.put("modulePermissionIds", profileIds);//no i18n
		return details;
	}


	public com.zoho.crmmeta.module.bean.Module getModuleMetaForCreateCustomModules(String pluralLabel,String singularLabel,String apiName) throws Exception {
        if(singularLabel == null || singularLabel.isEmpty() || pluralLabel == null || pluralLabel.isEmpty() || apiName == null | apiName.isEmpty()){
            LOGGER.log(Level.SEVERE,"null or empty : apiName = {0} , singularLabel = {1} , pluralLabel = {2} ",new Object[] { apiName, singularLabel, pluralLabel});
            throw new MandatoryParameterMissingException();
        }
        com.zoho.crmmeta.module.bean.Module moduleMeta = (com.zoho.crmmeta.module.bean.Module) com.zoho.crmmeta.module.bean.Module.getInstance();
        moduleMeta.getModuleBasicInfo().setApiName(apiName);
        moduleMeta.getModuleBasicInfo().setSingularLabel(singularLabel);
        moduleMeta.getModuleBasicInfo().setPluralLabel(pluralLabel);
        moduleMeta.getModuleBasicInfo().setSequence(TabUtil.getMaxTabSeqence()+1);
        if(request.getAttribute("isTeamModule") != null && request.getAttribute("isTeamModule") == Boolean.TRUE) {
        	moduleMeta.setAccessType(DefaultAccessType.TEAM);       
        }
        return moduleMeta;
    }

