    /**
     * reset fiscal configuration to standard january
     **/ 
    public static void resetFiscalYearToStandard() throws Exception
	{
    	FiscalYearService fiscalYearService = new FiscalYearService();
    	FiscalYear fiscalYear = new FiscalYear();
    	fiscalYear.setStartMonth("January");	//NO I18n
    	fiscalYear.setCalendarType("gregorian");//NO I18n
    	fiscalYearService.updateFiscalYearSettings(fiscalYear,UserUtil.getCurrentUserId(),false,null);
	}
    
