    public JSONObject deleteUnusedPickListOptions() throws JSONException{
        try {
        	String  fieldLabel = request.getParameter("fieldLabel");
			String module = request.getParameter("module");
            String response = resetPickListFieldUtil.deleteUnusedPickListOptions(fieldLabel,module);
            if(response.equals("Picklist_Options_Deleted")){
                resultObj.put("response", "Unused options deleted");
            }
            else
            {
            	status = false;
                resultObj.put("response", response);
            }
        } catch (Exception e) {
			LOGGER.log(Level.SEVERE, "Exception occured while deleting unused picklist options ",e);
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }
    
    
