    public JSONObject removeSchedularEntry(){
        try{
        	String key= (String)request.getParameter("key");//no i18n
        	if(key.equals("TIME_TRIGGER"))//no i18n
        	{
        		JSONObject jObj = TimeTriggerUtil.getCachedTimeTriggerSchedulerDetails();
    	        if(jObj != null)
    	        {
    	        	Long jobId = jObj.getLong(TimeTriggerUtil.JOBID);
    	            String threadpool = jObj.optString(TimeTriggerUtil.THREADPOOL, null);
    	            if(threadpool==null) {
    	            	CrmKeyValueUtil.deleteCrmKeyValueByKeyId(jobId, true);
    	        		AutomationLastRunDetailsUtil.deleteLastRunDetails(CommonUtility.getAsList(jobId));
    	            }
    	            else if(!CoreScheduleConstants.RECURRING_LOW_PROCESS.equals(threadpool)) {
    	            	CrmKeyValueUtil.deleteCrmKeyValueByKeyId(jobId, true);
    	        		AutomationLastRunDetailsUtil.deleteLastRunDetails(CommonUtility.getAsList(jobId));
    	        		ZohoCRMSchedule.deleteRepetitiveJobByJobID(jobId, threadpool);
    	        		LOGGER.log(Level.INFO, "TimeTriggerScheduler deleted for JobID :{0}, threadpool:{1}", new Object[] {String.valueOf(jobId), threadpool});
    	            }
    	        }
        	}
        	resultObj.put("response", "Schedular entry has been removed succesfull");//no i18n
        	resultObj.put("status",true);//no i18n
        }catch(Exception e){
            resultObj.put("status", false);//no i18n
            resultObj.put("response", "Error while removing Schedular entry");//no i18n
        }
        return resultObj;
    }
