	public void resetStaticRscConfigurations() throws Exception {
        try{
            DeleteQuery dQry1 = new DeleteQueryImpl(Table.getTable(CRMCSCRIPTDEPENDENCYINFO.TABLE));
            SelectQueryImpl selectQuery = new SelectQueryImpl(Table.getTable(CRMSTATICRESOURCES.TABLE));
            selectQuery.addSelectColumn(Column.getColumn(null, "*"));
            Criteria userScriptsCr = new Criteria(Column.getColumn(CRMSTATICRESOURCES.TABLE, CRMSTATICRESOURCES.SOURCE), 1, QueryConstants.EQUAL);
            selectQuery.setCriteria(userScriptsCr);
            Iterator<Row> rows = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(selectQuery).getRows(CRMSTATICRESOURCES.TABLE);
            ArrayList<String> s = new ArrayList<String>();
            while (rows.hasNext()) {
                Row row = rows.next();
                s.add(String.valueOf(row.get(CRMSTATICRESOURCES.RESOURCE_ID)));
            }
            dQry1.setCriteria(new Criteria(Column.getColumn(CRMCSCRIPTDEPENDENCYINFO.TABLE, CRMCSCRIPTDEPENDENCYINFO.RESOURCE_INFO), s.toArray(new String[0]) ,QueryConstants.IN));
            dQry1.setLimit(5000);
            while (true) {
                int count1 = PersistenceCacheUtil.getPersistenceLiteHandle().delete(dQry1);
                if (count1 < 5000) {
                    break;
                }
            }

            
            try {
                StaticResourceIntegrator.UploadEngine.Init(StaticResourceIntegrator.FEATURE.STATIC_RESOURCE).RemoveApp();
            } catch (Exception e) {
                LOGGER.log(Level.SEVERE,"Exception:rstdx staticrsc",e);
            }

            DeleteQuery dq = new DeleteQueryImpl(CRMSTATICRESOURCES.TABLE);
            dq.setCriteria(userScriptsCr);
            dq.setLimit(5000);
            PersistenceCacheUtil.getPurePersistenceLiteHandle().delete(dq);
            if (OrgUtil.isSandboxAccount()) {
            	deleteSandboxDxChanges(new Criteria(Column.getColumn(CRMSANDBOXCONFIGCHANGES.TABLE, CRMSANDBOXCONFIGCHANGES.CONFIGTYPE), SandboxConfigConstants.STATIC_RESOURCES, QueryConstants.EQUAL));
            }
        }catch (Exception e) {
			LOGGER.log(Level.SEVERE,"Exception:rstdx staticrsc",e);
		}
	}
	private void deleteSandboxDxChanges(Criteria cr) throws Exception{
		DeleteQuery dQry2 = new DeleteQueryImpl(Table.getTable(CRMSANDBOXCONFIGCHANGES.TABLE));
    	dQry2.setCriteria(cr);
    	dQry2.setLimit(5000);
        while (true) {
            int count1 = PersistenceCacheUtil.getPersistenceLiteHandle().delete(dQry2);
            if (count1 < 5000) {
                break;
            }
        }
	}

