	public JSONObject allowSigmaOperation(){
		boolean is_allowed = true;
		String redisKey = "SIGMA_OPERATIONS_COUNT_"+java.time.LocalDate.now(); //no i18n
		StringCommandExecutor strCmdExe =  CrmCacheProxy.getStringExecutor(CrmFeature.COMMON);
		if(strCmdExe.exists(redisKey)) {
			if(Integer.parseInt(strCmdExe.get(redisKey))>=25) {
				is_allowed = false;
			}
		}
		resultObj.put("response", ""+is_allowed );
		resultObj.put("status", true);
		return resultObj;
	}

	/**
	 * @return
	 * @param baseLayout - layoutId for the baseLayout
	 * @param module - name of the module
	 * @param layoutName - name of the new layout
	 * @param profiles - comma separated profileIds
	 */
	public JSONObject cloneLayoutPOJO(){
		try {
			String baseLayoutName = request.getParameter("baseLayout").toString();
			String moduleName = request.getParameter("module").toString();
			Long tabId = TabUtil.getTabIdByName(moduleName);
			if(tabId == null) {
				LOGGER.log(Level.INFO,"tabId is null for the modulename = {0}",new Object[]{moduleName});
			}
			Long baseLayoutId = PageLayoutUtil.getLayoutIDByLayoutName(tabId, baseLayoutName);
			String layoutName = request.getParameter("layoutName").toString();
			String[] profilesStrArr = request.getParameter("profiles").toString().split(",");
			ArrayList<Long> profiles = new ArrayList<Long>();
			int profilesCount = profilesStrArr.length;
			for(int i=0;i<profilesCount;i++) {
				Long profileId = ProfileUtil.getProfileIdByProfileName(profilesStrArr[i]);
				if(profileId == null) {
					LOGGER.log(Level.INFO,"profileId is null for the profilename = {0}",new Object[]{profilesStrArr[i]});
					continue;
				}
				profiles.add(profileId);
			}
			resultObj = resetConf.cloneLayoutPOJO(baseLayoutId,tabId,layoutName,profiles);
			return resultObj;
		}catch (Exception e) {
			LOGGER.log(Level.SEVERE,"Exception occured in cloneLayoutPOJO resetconfig",e);
			resultObj.put("response", "clone layout failed in cloneLayoutPOJO resetConfig.");
			resultObj.put("status", false);
			return resultObj;
		}
	}

