     public JSONObject SetLimitReached() throws Exception{
    	 JSONObject json = new JSONObject();
    		JSONObject allowed_json = new JSONObject();
    		allowed_json.put("purchased_space", 1153433600l);//no i18n
    		allowed_json.put("count", 0);//no i18n
    		allowed_json.put("base_limit", 10737418240l);//no i18n
    		allowed_json.put("user_limit", 52428800l);//no i18n

    		json.put("allowed_space", allowed_json);//no i18n

    		JSONObject used_json = new JSONObject();
    		used_json.put("size", 105854976782l);//no i18n
    		used_json.put("count", 51721111l);//no i18n

    		json.put("used_space", used_json);//No i18n

    		LOGGER.log(Level.INFO, "DSR--->increase data storage for automation: {0}", new String[]{json.toString()});

    		SelectQuery sql = new SelectQueryImpl(Table.getTable(CRMSTORAGEDETAILS.TABLE));
    		sql.addSelectColumn(Column.getColumn(CRMSTORAGEDETAILS.TABLE, "*"));
    		sql.setCriteria(null);
    		sql.setRange(new Range(0,1));
    		DataObject dataObj = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(sql);
    		Row dsrow = dataObj.getRow(CRMSTORAGEDETAILS.TABLE);
    		String data = (String) dsrow.get(CRMSTORAGEDETAILS.DATA_STORAGE);
    		if(data != null)
    		{
    			JSONObject data_storage = new JSONObject(data);
    			JSONObject cleanup_suggestions_count = data_storage.has("cleanup_suggestions_count") ? (JSONObject)data_storage.get("cleanup_suggestions_count") : new JSONObject(); //No i18n

    			json.put("cleanup_suggestions_count", cleanup_suggestions_count); //NO I18N
    			dsrow.set(CRMSTORAGEDETAILS.DATA_STORAGE, json.toString());
    			dataObj.updateRow(dsrow);
    			PersistenceCacheUtil.getPurePersistenceLiteHandle().update(dataObj);

    		}
    	com.zoho.common.components.cache.CrmCacheUtil.putValueInJVMCache(CrmCacheUtil.SEGMENT_CRM_CONFIG_LIMITS, "DATA_STORAGE_DETAILS", json); //No I18N
    	DataStorageUtil.notifyOfflineFailure("ActiveConfirmedUsers","refresh_storage");//no i18n
     	resultObj.put("response", "Storage is set to limit reached");
     	return resultObj;
     }

