     @SuppressWarnings({ "deprecation", "unchecked", "unused" })
     public JSONObject enableCircuitsTab() throws JSONException { // ###used
         try {
 				
 				SelectQueryImpl selectQuery = new SelectQueryImpl(Table.getTable(CRMSETTINGS.TABLE));
 				selectQuery.addSelectColumn(Column.getColumn(null, "*"));
 				selectQuery.setRange(new Range(1, 1000));
 				DataObject dob = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(selectQuery);
 				
 				
 				Criteria cr = new Criteria(Column.getColumn(CRMSETTINGS.TABLE, CRMSETTINGS.API_NAME), "system.circuits", QueryConstants.EQUAL, false);
 				cr =  cr.or(new Criteria(Column.getColumn(CRMSETTINGS.TABLE, CRMSETTINGS.API_NAME), "system.circuit", QueryConstants.EQUAL, false));
 				
 				Row prechkrow = dob.getRow(CRMSETTINGS.TABLE, cr);
 				
 				Integer linksRowSeq =  4;
 				
 				if(prechkrow == null){
 					
 					Row parentRow = dob.getRow(CRMSETTINGS.TABLE, new Criteria(Column.getColumn(CRMSETTINGS.TABLE, CRMSETTINGS.API_NAME), "system.developerspace", QueryConstants.EQUAL, false));
 					Long parentId = (Long) parentRow.get(CRMSETTINGS.ELEMENT_ID);
 					Persistence per = PersistenceCacheUtil.getPurePersistenceLiteHandle();
 					
 					DataObject fsDO = per.constructDataObject();
 					Row rw1 = new Row(CRMSETTINGS.TABLE);
 					rw1.set(CRMSETTINGS.API_NAME, "system.circuits"); // no i18n
 					rw1.set(CRMSETTINGS.ELEMENT_ACTION, 1);
 					rw1.set(CRMSETTINGS.ELEMENT_LABEL, "Circuits"); // no i18n
 					rw1.set(CRMSETTINGS.ELEMENT_TYPE, 2);
 					rw1.set(CRMSETTINGS.GENERATED_SOURCE, 1);
 					rw1.set(CRMSETTINGS.PARENT_ID, parentId);
 					rw1.set(CRMSETTINGS.PRESENCE, 1);
 					rw1.set(CRMSETTINGS.SEQUENCE, 5);
 					fsDO.addRow(rw1);
 					Row row2 = new Row(CRMSETTINGS.TABLE);
 					row2.set(CRMSETTINGS.API_NAME, "system.circuits1"); // no i18n
 					row2.set(CRMSETTINGS.ELEMENT_ACTION, 1);
 					row2.set(CRMSETTINGS.ELEMENT_LABEL, "Circuits"); // no i18n
 					row2.set(CRMSETTINGS.ELEMENT_TYPE, 3);
 					row2.set(CRMSETTINGS.GENERATED_SOURCE, 1);
 					row2.set(CRMSETTINGS.PARENT_ID, rw1.get(CRMSETTINGS.ELEMENT_ID));
 					row2.set(CRMSETTINGS.PRESENCE, 1);
 					row2.set(CRMSETTINGS.SEQUENCE, 1);
 					fsDO.addRow(row2);

 					per.add(fsDO);
 					
 					Criteria reArrCri = new Criteria(Column.getColumn(CRMSETTINGS.TABLE, CRMSETTINGS.PARENT_ID), parentId, QueryConstants.EQUAL);
 					reArrCri = reArrCri.and(new Criteria(Column.getColumn(CRMSETTINGS.TABLE, CRMSETTINGS.SEQUENCE), linksRowSeq, QueryConstants.GREATER_EQUAL));
 					Iterator<Row> settingsSubSection = dob.getRows(CRMSETTINGS.TABLE, reArrCri);
 					// sorting the sub section
 					List<Row> sortedList = new ArrayList<>();
 					while (settingsSubSection.hasNext()) {
 						Row currRow = settingsSubSection.next();
 						sortedList.add(currRow);
 					}
 					sortedList.sort(new Comparator<Row>() {
 						@Override
 						public int compare(Row r1, Row r2) {
 							return (Integer) r1.get(CRMSETTINGS.SEQUENCE) < (Integer) r2.get(CRMSETTINGS.SEQUENCE) ? -1 : 1;
 						}
 					});
 					Iterator<Row> sortedSubSectionItr = sortedList.iterator();
 					while (sortedSubSectionItr.hasNext()) {
 						Row currRow = sortedSubSectionItr.next();
 						linksRowSeq++;
 						currRow.set(CRMSETTINGS.SEQUENCE, linksRowSeq);
 						dob.updateRow(currRow);

 					}
 					per.update(dob);
 					
 				} else {
 					
 					Row parentRow = dob.getRow(CRMSETTINGS.TABLE, new Criteria(Column.getColumn(CRMSETTINGS.TABLE, CRMSETTINGS.API_NAME), "system.developerspace", QueryConstants.EQUAL, false));
 					Long parentId = (Long) parentRow.get(CRMSETTINGS.ELEMENT_ID);
 					
 					Long elemId = (Long) prechkrow.get(CRMSETTINGS.PARENT_ID);
 					
 					if(parentId.longValue()!=  elemId.longValue()) {
 						
 						Persistence per = PersistenceCacheUtil.getPurePersistenceLiteHandle();
 						
 						Criteria crt = new Criteria(Column.getColumn(CRMSETTINGS.TABLE, CRMSETTINGS.ELEMENT_LABEL), new String[] {"Circuits","Circuits1"}, QueryConstants.IN);
 						per.delete(crt);
 						
 						DataObject fsDO = per.constructDataObject();
 						Row rw1 = new Row(CRMSETTINGS.TABLE);
 						rw1.set(CRMSETTINGS.API_NAME, "system.circuits"); // no i18n
 						rw1.set(CRMSETTINGS.ELEMENT_ACTION, 1);
 						rw1.set(CRMSETTINGS.ELEMENT_LABEL, "Circuits"); // no i18n
 						rw1.set(CRMSETTINGS.ELEMENT_TYPE, 2);
 						rw1.set(CRMSETTINGS.GENERATED_SOURCE, 1);
 						rw1.set(CRMSETTINGS.PARENT_ID, parentId);
 						rw1.set(CRMSETTINGS.PRESENCE, 1);
 						rw1.set(CRMSETTINGS.SEQUENCE, 5);
 						fsDO.addRow(rw1);
 						
 						Row row2 = new Row(CRMSETTINGS.TABLE);
 						row2.set(CRMSETTINGS.API_NAME, "system.circuits1"); // no i18n
 						row2.set(CRMSETTINGS.ELEMENT_ACTION, 1);
 						row2.set(CRMSETTINGS.ELEMENT_LABEL, "Circuits"); // no i18n
 						row2.set(CRMSETTINGS.ELEMENT_TYPE, 3);	
 						row2.set(CRMSETTINGS.GENERATED_SOURCE, 1);
 						row2.set(CRMSETTINGS.PARENT_ID, rw1.get(CRMSETTINGS.ELEMENT_ID));
 						row2.set(CRMSETTINGS.PRESENCE, 1);
 						row2.set(CRMSETTINGS.SEQUENCE, 1);
 						fsDO.addRow(row2);

 						per.add(fsDO);
 						
 						Criteria reArrCri = new Criteria(Column.getColumn(CRMSETTINGS.TABLE, CRMSETTINGS.PARENT_ID), parentId, QueryConstants.EQUAL);
 						reArrCri = reArrCri.and(new Criteria(Column.getColumn(CRMSETTINGS.TABLE, CRMSETTINGS.SEQUENCE), linksRowSeq, QueryConstants.GREATER_EQUAL));
 						Iterator<Row> settingsSubSection = dob.getRows(CRMSETTINGS.TABLE, reArrCri);
 						// sorting the sub section
 						List<Row> sortedList = new ArrayList<>();
 						while (settingsSubSection.hasNext()) {
 							Row currRow = settingsSubSection.next();
 							sortedList.add(currRow);
 						}
 						sortedList.sort(new Comparator<Row>() {
 							@Override
 							public int compare(Row r1, Row r2) {
 								return (Integer) r1.get(CRMSETTINGS.SEQUENCE) < (Integer) r2.get(CRMSETTINGS.SEQUENCE) ? -1 : 1;
 							}
 						});
 						Iterator<Row> sortedSubSectionItr = sortedList.iterator();
 						while (sortedSubSectionItr.hasNext()) {
 							Row currRow = sortedSubSectionItr.next();
 							linksRowSeq++;
 							currRow.set(CRMSETTINGS.SEQUENCE, linksRowSeq);
 							dob.updateRow(currRow);

 						}
 						per.update(dob);
 						
 					}
 					
 				}
 				CoreFeatureUtil.addOrUpdateTrailOrg("CIRCUITS_ENABLE", OrgUtil.getCurrentZGID() + "", null, "ORG", true, null); //NO I18N
 				resultObj.put("response", "CIRCUITS enabled");
         } catch (Exception e) {
             status = false;
             resultObj.put("response", e.toString());
         }
         resultObj.put("status", status);
         return resultObj;
     }


