	 public JSONObject resetProductCodeCustomization() throws Exception{
			LOGGER.log(Level.INFO, "resetProductCodeCustomization method starts");
			try {
				ArrayList<String> moduleList = new ArrayList<String>();
				Persistence persistenceLite = PersistenceCacheUtil.getPurePersistenceLiteHandle();
				ArrayList<Long> tabIdList = new ArrayList<Long>();
			    for(String module : CrmModuleConstants.LINEITEMS_MODULE_ARRAY) {
			    	tabIdList.add(TabUtil.getTabIdByName(module));
			    }

				Criteria criteria = new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.TABID), tabIdList.toArray(), QueryConstants.IN);
				criteria = criteria.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.COLUMNNAME), CrmSubformNCUtil.LineColumns.getProductid(), QueryConstants.EQUAL));

				DataObject fieldDo = persistenceLite.get(CRMFIELD.TABLE, criteria);

				Iterator<Row> iter = fieldDo.getRows(CRMFIELD.TABLE);
			    while( iter.hasNext())
			    {
			    	Row fieldRow = iter.next();

			    	JSONObject fieldProp =	fieldRow.get(CRMFIELD.FIELDPROP)!=null ? new JSONObject((String)fieldRow.get(CRMFIELD.FIELDPROP)) : null;
					if(fieldProp != null && fieldProp.has(CrmSubformNCUtil.LINEITEM_PRODUCT_CODE)){
						fieldProp.remove(CrmSubformNCUtil.LINEITEM_PRODUCT_CODE);
						fieldRow.set(CRMFIELD.FIELDPROP, fieldProp);
						fieldDo.updateRow(fieldRow);
						moduleList.add(TabUtil.getTabNameById((Long)fieldRow.get(CRMFIELD.TABID)));
					}
					else if(fieldProp!=null && fieldProp.has(CustomModuleConstants.JSON_KEY_PRODUCT_LOOKUP_FIELDS) ) {
						resetConf.resetProductLookupFields(true,fieldProp);
						fieldRow.set(CRMFIELD.FIELDPROP, fieldProp);
						fieldDo.updateRow(fieldRow);
						moduleList.add(TabUtil.getTabNameById((Long)fieldRow.get(CRMFIELD.TABID)));
					}
			    }

			    if(moduleList.size() > 0) {
			    	persistenceLite.update(fieldDo);
			    	PageCacheUtil.dropCache(zgId.toString(),moduleList);
			    }

				resultObj.put("response", "resetProductCodeCustomization method completed successfully");
				resultObj.put("status", true);
			}catch(Exception e) {
				LOGGER.log(Level.SEVERE,"Exception occured in resetProductCodeCustomization method",e);
				resultObj.put("response", "resetProductCodeCustomization method failed");
				resultObj.put("status", false);
			}
			return resultObj;
		}

public void revertNumberFormtatField(String zgId)
     {
    	 try {

    		 ArrayList<String> columnName= new ArrayList<String>( Arrays.asList("NUMBER_SEPARATOR","DECIMAL_SEPARATOR")); // NO I18N
    		 Long tabId = TabUtil.getTabIdByName("Users", zgId); //no i18n
    		 int col_size = columnName.size();
    		 DataObject dobj = null;
    		 for (int i=0; i < col_size; i++)
    		 {
    			 // Removing field entries
    			 SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMFIELD.TABLE));
    			 sq.addSelectColumn(Column.getColumn(null, "*"));
    			 Criteria cr = new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.TABID), tabId, QueryConstants.EQUAL);
    			 cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.COLUMNNAME), columnName.get(i), QueryConstants.EQUAL));
    			 sq.setCriteria(cr);
    			 dobj = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(sq);
    			 Row row = dobj.getRow(CRMFIELD.TABLE);
    			 if( row != null)
    			 {
    				dobj.deleteRow(row);
    			 }
    		 }
    		 if(!dobj.isEmpty())
    		 {
    			 PersistenceCacheUtil.getPurePersistenceLiteHandle().update(dobj);
    		 }


    		  // Depopulating in CrmIamUser
    		 	SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMIAMUSER.TABLE));
    			sq.addSelectColumn(Column.getColumn(null, "*"));
    			DOIterator doIter = new DOIterator(PersistenceCacheUtil.getPurePersistenceLiteHandle(), sq, 3000);
    			while(doIter.hasNext())
    			{
    				DataObject userDob = doIter.next();
    				Iterator<Row> usrRows = userDob.getRows(CRMIAMUSER.TABLE);
    				while(usrRows.hasNext())
    				{
    					Row usrRow = usrRows.next();
    					usrRow.set(CRMIAMUSER.NUMBER_SEPARATOR, null);
    					usrRow.set(CRMIAMUSER.DECIMAL_SEPARATOR, null);
    					userDob.updateRow(usrRow);

    				}
    				PersistenceCacheUtil.getPurePersistenceLiteHandle().update(userDob);
    			}

    	 }
    	 catch(Exception e) {
    		 LOGGER.log(Level.SEVERE, "Exception while revert migrating number format field in ResetConfigurations" );
    	 }
     }

	public JSONObject resetMemberStatus() throws Exception {
		try {
			String[] defaultValues = new String []{
	                "Planned", //No I18N
	                "Invited", //No I18N
	                "Sent",//No I18N
	                "Received",//No I18N
	                "Opened",//No I18N
	                "Responded",//No I18N
	                "Bounced",//No I18N
	                "Opted Out"//No I18N
	            };
			HttpServletRequestExtends request = RequestAndResponseUtil.getRequest();
			Criteria statusDelCr = new Criteria(Column.getColumn(CRMCAMPAIGNMEMBERSTATUS.TABLE, CRMCAMPAIGNMEMBERSTATUS.STATUS), defaultValues, QueryConstants.NOT_IN);
			Criteria picklistCr = new Criteria(Column.getColumn(CRMPICKLISTVALUES.TABLE, CRMPICKLISTVALUES.ACTUALVALUE), defaultValues, QueryConstants.NOT_IN);
			for (String module : Arrays.asList(CrmModuleConstants.LEADS, CrmModuleConstants.CONTACTS)) {
			String linkingModule = EntityMetaDataUtil.getMemberModule(module);
			Long fieldid = FieldUtil.getFieldIdFromTabIdAndColumnName(TabUtil.getTabIdByName(linkingModule), "STATUS"); //No I18N
			DataObject dObj = PickListFieldUtil.getPickListDoByFieldId(fieldid, null, null);
			if (dObj != null && !dObj.isEmpty()) {
			Iterator<?> rows = dObj.getRows(CRMPICKLISTVALUES.TABLE, picklistCr);
			HashMap<Long, String> picklistIdsMap = new HashMap<>();
			while(rows.hasNext()) {
				Row row = (Row) rows.next();
				picklistIdsMap.put((Long) row.get(CRMPICKLISTVALUES.UNIQUEID), row.get(CRMPICKLISTVALUES.ACTUALVALUE).toString());
			}
			if (!picklistIdsMap.isEmpty()) {
				ReplaceAndDeletePickListUtils.replacePicklistIdsWithValues(UserUtil.getCurrentUserId(), linkingModule, EntityMetaDataUtil.getMemberTableForModule(module), "STATUS", 2, picklistIdsMap, fieldid); //No I18N
				PickListFieldUtil.deletePickListOptionsForGivenFieldId(fieldid, Arrays.asList(picklistIdsMap.keySet().toArray(new Long[] {})), null);
			}
			}
			}

			PersistenceCacheUtil.getPurePersistenceLiteHandle().delete(statusDelCr);

			SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMCAMPAIGNMEMBERSTATUS.TABLE));
			sq.addSelectColumn(Column.getColumn(null, "*"));
			sq.addSortColumn( new SortColumn(Column.getColumn(CRMCAMPAIGNMEMBERSTATUS.TABLE, CRMCAMPAIGNMEMBERSTATUS.SORTORDERID),true));
			sq.setRange(new Range(0,50));
			DataObject dObj = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(sq);
			for (int i = 1, len = defaultValues.length; i <= len; i++) {
			String status = defaultValues[i - 1];
			Row row = dObj.getRow(CRMCAMPAIGNMEMBERSTATUS.TABLE, new Criteria(Column.getColumn(CRMCAMPAIGNMEMBERSTATUS.TABLE, CRMCAMPAIGNMEMBERSTATUS.STATUS), status, QueryConstants.EQUAL));
			if (row != null) {
			request.setParameter("property(statusId" + i + ")", row.get(CRMCAMPAIGNMEMBERSTATUS.STATUSID)); //No I18N
			}
			request.setParameter("property(status" + i + ")", status);//No I18N
			request.setParameter("property(sortOrder" + i + ")", i);//No I18N
			}
			request.setParameter("cricnt", 8); //No I18N
			UpdateCustomizedMemStatusAction action = new UpdateCustomizedMemStatusAction();
			action.request = request;
			action.response = response;
			action.execute();
			resultObj.put("response", "resetMemberStatus method completed successfully");
			resultObj.put("status", true);
		}catch(Exception e) {
			LOGGER.log(Level.SEVERE,"Exception occured in resetProductCodeCustomization method",e);
			resultObj.put("response", "resetMemberStatus method failed");
			resultObj.put("status", false);
		}
		return resultObj;
	}
