	public static void deleteAllIpDetails() throws Exception{
		if(RebrandLinkUtil.isDevelopmentSetup() || RebrandLinkUtil.isLocalSetup() || RebrandLinkUtil.isSubSetup()){
			Long zoid = OrgUtil.getZoidFromIAM(OrgUtil.getCurrentZGID());
			List<AuthDomain> ads = IAMProxy.getInstance().getAuthDomainAPI().getAllAuthDomains(zoid.toString());
			if(ads!=null){
				AuthDomainAPI authAPI = IAMProxy.getInstance().getAuthDomainAPI();
				for(AuthDomain ad : ads){
					if(!authAPI.deleteAuthDomain(zoid,ad.getDomainName(),ZohoCRMIAMUtil.SERVICENAME)){
						LOGGER.log(Level.INFO, "failed authdomain to delete internal 12-------------------> {0}",ad.getDomainName());
					}
				}
			}
			LOGGER.log(Level.INFO, "all auth_domain_id delete from crmDB start"); // No I18n
			Criteria cr = new Criteria(Column.getColumn(CRMAUTHDOMAIN.TABLE , CRMAUTHDOMAIN.AUTH_DOMAIN_ID), null , QueryConstants.NOT_EQUAL);
			PersistenceCacheUtil.getPurePersistenceLiteHandle().delete(cr);
			LOGGER.log(Level.INFO, "all auth_domain_id delete from crmDB end"); // No I18n
			IAMProxy.getInstance().getOrgAPI(zoid+"").deleteAllAllowedIPRangeForOrg(zoid);
			LOGGER.log(Level.INFO, "all allowed ips deleted from IAM"); // No I18n
		}
	}

    public JSONObject enableEmailIntelligence() throws Exception{

        LOGGER.log(Level.INFO,"::::enableEmailIntelligence userId::::"+currentUserId);
        try{

            SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMZIANOTIFICATIONCONFIG.TABLE));
            sq.addSelectColumn( Column.getColumn(CRMZIANOTIFICATIONCONFIG.TABLE, CRMZIANOTIFICATIONCONFIG.ZIACONFIGID) );

            Criteria cr = new Criteria(Column.getColumn(CRMZIANOTIFICATIONCONFIG.TABLE, CRMZIANOTIFICATIONCONFIG.CONFIG_TYPE), 5, QueryConstants.EQUAL);
            cr = cr.and(new Criteria(Column.getColumn(CRMZIANOTIFICATIONCONFIG.TABLE, CRMZIANOTIFICATIONCONFIG.CATEGORY), 55, QueryConstants.EQUAL));

            sq.setCriteria(cr);
            sq.setRange(new Range(0, 1));
            CrmUsers crmUsers = CrmUsers.getInstance(currentUserId, Boolean.FALSE);
            DataObject dObj = PersistenceCacheUtil.getNonCachePersistenceHandle().get(sq);
            Row row = dObj.getFirstRow(CRMZIANOTIFICATIONCONFIG.TABLE);
            if(row != null)
            {
                Long configId =  (Long)row.get(CRMZIANOTIFICATIONCONFIG.ZIACONFIGID);
                LOGGER.log(Level.INFO,"::::enableEmailIntelligence configId:::"+configId);
                CrmZiaConfig.Put configPut = CrmZiaConfig.getInstance(crmUsers, false).new Put(true);
                JSONObject statusObj = new JSONObject();
                statusObj.put("status",true);
                configPut.updateNotificationStatus(currentUserId, 55, configId, statusObj, true, false, null);
                resultObj.put("status", "Enabled Successfully");
            }else{
                resultObj.put("status", "ZiaInEmail not enabled. Please enable and try again");
            }
        }
        catch (Exception e){
            resultObj.put("status", "Enabling failed");
        }
        return resultObj;
    }

