    public JSONObject email_searchindex() throws JSONException {
    	String st = null;
    	boolean resreturn = false;
        try {
            Long   userId = UserUtil.getCurrentUserId();
            String searchVersion = request.getParameter("searchVersion");
            String limit = request.getParameter("limit");
            String searchid = request.getParameter("searchid");
            String emailid = request.getParameter("emailid");
            String sub = request.getParameter("subject");
            HashMap < String, String > params = new HashMap < String, String > ();
    		HashMap zmailConfigMap = ZMailConfigUtil.getMailConfigDetails(userId,ZMailConstants.ZOHO_MAIL);
    		
    		if(searchid != null) {
    			params.put("searchid", searchid );
    		}else {
            	params.put("searchid", (String) zmailConfigMap.get(ZMailConstants.ZMAIL) );
            }
            
            if(emailid != null) {
            	params.put("emailid", emailid );
            }else {
            	params.put("emailid", (String) zmailConfigMap.get(ZMailConstants.ZMAIL) );
            }
            params.put("fromemailid", emailid);
            params.put("includeArchive", "true");
            params.put("strictCheck", "false");
            params.put("afn", "true");
            String[] range = {
                "0",
                "10"
            };
            if(limit != null && !limit.isEmpty() && Integer.valueOf(limit) < 200) {
            	range[1] = limit;
            }
            
            if(searchVersion != null && ("v1".equals(searchVersion) || "v2".equals(searchVersion))) {
            	 params.put("searchVersion", searchVersion);
            }
            
            String remoteAddr = remoteAddress;
            HashMap < String, String > authentication = new HashMap < String, String > ();
            authentication.put("ticket", ticket);
            st = MailAPIRouting.getResults(zmailConfigMap,params, range, remoteAddr, authentication);
            boolean isV2 = false;
            
        	Map<String, String> apiKeys = ZMailConstants.V1_MESSAGES_API_KEYS;
        	JSONArray responseText=new JSONArray(st);
        	int arrLength=responseText.length();
        	
        	if(arrLength > 0) {
        		
    			JSONObject jsonObj = new JSONObject(responseText.get(0).toString());
    			LOGGER.log(Level.INFO, "jsonObj.has MESSAGEID : {0}", jsonObj.has(apiKeys.get(ZMailConstants.MESSAGEID)));		
    			if(!(jsonObj.has(apiKeys.get(ZMailConstants.MESSAGEID)))) {
    				apiKeys = ZMailConstants.V2_MESSAGES_API_KEYS;
    				isV2 = true;
    			}
	 
	            //resultObj.put("response from MailApps",st);
	            		
	            if(sub!=null)
	            {
	            	for(int i=0;i<arrLength;i++)
	        		{
	            		JSONObject jsonObj11=new JSONObject(responseText.get(i).toString());
	            		if( jsonObj11.has(apiKeys.get(ZMailConstants.SUBJECT)) && !jsonObj11.optString(apiKeys.get(ZMailConstants.SUBJECT)).isEmpty())
	    				{
	    					String subject=(String)jsonObj11.get(apiKeys.get(ZMailConstants.SUBJECT));
	    					if(subject.equals(sub))
							{
								resreturn = true;
								break;
							}
	    				}
	        		}
	            }
	            else
	            {
	              if(jsonObj.has(apiKeys.get(ZMailConstants.MESSAGEID))) {
	            	  resreturn = true;
	              }
	              else {
	            	  resreturn = false;
	              }
	            }
	    		}
        	
        	resultObj.put("response", resreturn + "");
        	resultObj.put("isV2",isV2);
        	resultObj.put("Mail360response", responseText);

        }
        catch(SocketTimeoutException e)
        {
        	status = false;
        	resultObj.put("failure reason", "Socket Timeout Exception");
        }
        catch(JSONException e)
        {
        	status = false;
        	if(st==null)
        	{
        	resultObj.put("failure reason", "MailApps returned null");
        	}
        	else
        	{
        	resultObj.put("failure reason", "Mailapps response"+ st);
        	}
        }
        catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        
        resultObj.put("status", status);
        return resultObj;
    }
    /**
     * this method used for getting mail 360 search modes (v1/v2/dual) 
     * @author karthi-11422
     * @return
     * @throws JSONException
     */
    public JSONObject email_searchMode() throws JSONException {
    	boolean resreturn = false;
    	try {
            Long   userId = UserUtil.getCurrentUserId();
            String mode = request.getParameter("mode");
            String zuid = new String();
            if(mode.equals("getSearchMode")) {
            	String searchMode = MailAPIRouting.getSearchMode(zgId, Long.toString(zuId),remoteAddress);
            	if(searchMode!=null && searchMode.isEmpty()) {
                	status = false;
            	}
                resultObj.put("response", "Search Mode : "+ searchMode);
            }
            if(mode.equals("updateSearchMode")) {
                String version = request.getParameter("version");
                resreturn =  MailAPIRouting.updateSearchMode(zgId, Long.toString(zuId),remoteAddress, version);  
                if(resreturn) {
                    resultObj.put("response", mode +" Search mode updated successfully.");
                }else {
                	status = false;
                    resultObj.put("response", "Search mode updation failed.");
                }
            }
                   	
    	}
    	catch(SocketTimeoutException e)
        {
        	status = false;
        	resultObj.put("failure reason", "Socket Timeout Exception");
        }
        catch(JSONException e)
        {
        	status = false;
        	
        }
        catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
    	
        resultObj.put("status", status);
    	return resultObj;
    }

    
