       /**
      	 * author - madhava-17028
      	 * IMAP/POP Email configuration
      	 * r
      	 * @return
      	 */
       public JSONObject get_configuredEmail()throws Exception
       {
    	   Criteria newCr = new Criteria(Column.getColumn(CRMMAILUSERCONFIG.TABLE, CRMMAILUSERCONFIG.USERID), userId, QueryConstants.EQUAL);
   		
   		try{
   			DataObject mailDetailsObj =  (DataObject) ZMailConfigUtil.getCrmMailUserConfigCachedDO();
   			Row mailDetailsRow = (Row) mailDetailsObj.getRow(CRMMAILUSERCONFIG.TABLE, newCr);
   			if( mailDetailsRow != null ){
   				resultObj.put("EMAIL" , (mailDetailsRow.get(CRMMAILUSERCONFIG.EMAIL) != null ? mailDetailsRow.get(CRMMAILUSERCONFIG.EMAIL).toString() : null));
   				resultObj.put("IS_INTEGRATED" , (mailDetailsRow.get(CRMMAILUSERCONFIG.IS_ACTIVE) != null ? mailDetailsRow.get(CRMMAILUSERCONFIG.IS_ACTIVE).toString() : null));
   				JSONObject otherMailInfo = ZMailConfigUtil.getOtherZohoMailInfo(mailDetailsRow);
   				if( otherMailInfo != null)
				{
   					int type = otherMailInfo.optInt(MailAppsConstants.ACCOUNT_TYPE);

   			   		switch(type)
   			   		{
   			   			case 0  :
   			   			resultObj.put("PROTOCOL","pop");
   			   			break;
   			   			
   			   			case 2  :
   			   			resultObj.put("PROTOCOL","imap");
   			   			break;
   			   		}
				}
   				if(mailDetailsRow.get(CRMMAILUSERCONFIG.INCOMING_SERVER_DETAILS) != null){
   					JSONObject incoming_server = JsonUtil.parseStringToJSON((String)mailDetailsRow.get(CRMMAILUSERCONFIG.INCOMING_SERVER_DETAILS));
   					int status = incoming_server.has(MailAppsConstants.ConfigurationConstants.SYNC_STATUS) ? incoming_server.optInt(MailAppsConstants.ConfigurationConstants.SYNC_STATUS) : null;
   					switch(status)
   					{
   					case MailAppsConstants.ConfigurationConstants.SYNC_STATUS_YET_TO_START:
   						resultObj.put("SYNC_STATUS","yet_to_start");
   						break;

   					case MailAppsConstants.ConfigurationConstants.SYNC_STATUS_STARTED:
   						resultObj.put("SYNC_STATUS","in_progress"); 
   						break;

   					case MailAppsConstants.ConfigurationConstants.SYNC_STATUS_FINISHED:
   						resultObj.put("SYNC_STATUS","completed");  
   						break;
   					
   					}
   					
   					String mail_provider = incoming_server.has(MailAppsConstants.ConfigurationConstants.SERVER) ? incoming_server.optString(MailAppsConstants.ConfigurationConstants.SERVER) : null;
   					if(mail_provider != null)
   					{
   					if(mail_provider.contains("zoho.com"))
   					{
   						mail_provider = "ZOHO";//no i18n
   					}
   					else if(mail_provider.contains("localzoho.com"))
   					{
   						mail_provider = "LOCAL_ZOHO";//no i18n
   					}
   					else if(mail_provider.contains("gmail.com"))
   					{
   						mail_provider = "GMAIL";//no i18n
   					}
   					else if(mail_provider.contains("outlook.com"))
   					{
   						mail_provider = "OUTLOOK";//no i18n
   					}
   					else if(mail_provider.contains("office365.com"))
   					{
   						mail_provider = "OFFICE_365";//no i18n
   					}
   					else
   					{
   						mail_provider = "OTHER_"+mail_provider;//no i18n
   					}
   					}
   					
   					resultObj.put("MAIL_PROVIDER",mail_provider);
   					
   					int sharing_type = (Integer)mailDetailsRow.get(CRMMAILUSERCONFIG.SHARING_TYPE);
   					resultObj.put("SHARING_TYPE" ,EmailConfPersistenceProcessor.convertSharingTypeUIToAPI(ZMailConfigUtil.convertSharingTypeIntToString(sharing_type)));
   					
   					resultObj.put("MAIL_ALIASES" , mailDetailsRow.get(CRMMAILUSERCONFIG.MAIL_ALIASES));
   					
   					resultObj.put("DEFAULT_ADDRESS" , mailDetailsRow.get(CRMMAILUSERCONFIG.DEFAULT_FROM_ADDRESS));
   					
				}
   				status = true;
   			}
   		}catch(Exception e){
			status = false;
			resultObj.put("response", e.toString());
   			LOGGER.log(Level.INFO,"Exception while getting the Mail configuration :::::: ", e);
   		}
   		resultObj.put("status", status);
		return resultObj;
       }
       
       
