    public JSONObject revertCustomModuleAutoNumberIssue() {
		 try {
			 JSONArray responseJSONArray = new JSONArray();
			 ArrayList<String> modules = new ArrayList<String>(Arrays.asList("CustomModule51","CustomModule1")); //No i18n
			 for(String moduleName : modules) {
			 	JSONObject responseJSONObject = resetFieldUtil.validateAndCorrectCustomModuleAutoNumberAutomationAccount(moduleName);
			 	responseJSONArray.put(responseJSONObject);
			 	if(!responseJSONObject.getBoolean("status")) {
			 		resultObj.put("status", false);
			 		resultObj.put("response", responseJSONArray);
			 		return resultObj;
			 	}
			 }
			 //Module re creation
			 List<Long> profileIds = ProfileUtil.getAllProfileIds(null,false,false);
        	 Long liteProfileId = CrmLiteUser.getLiteProfile();
        	 if(liteProfileId!=null) {
        		 profileIds.remove(liteProfileId);
        	 }
			 boolean module51 = validateAndCreateCustomModulesForAutomation(51, getModuleInfoForCreateCustomModules("NewDBModules", "NewDBModule", "NewDBModules", new JSONArray(profileIds)), currentUserId, currentUserLocale, Boolean.TRUE);//no i18n
			 boolean module1 = validateAndCreateCustomModulesForAutomation(1, getModuleInfoForCreateCustomModules("CModules", "CModule", "CModules", new JSONArray(profileIds)), currentUserId, currentUserLocale, Boolean.TRUE);//no i18n
			 JSONObject json = new JSONObject();
			 json.put("module51", module51);
			 json.put("module1", module1);
			 responseJSONArray.put(json);

			 resultObj.put("status", true);
			 resultObj.put("response", responseJSONArray);
		 }catch (Exception e) {
			 LOGGER.log(Level.INFO, "Exception occurred in revertCustomModuleAutoNumberIssue", e);
			 resultObj.put("status", false);
			 resultObj.put("response", "revertCustomModuleAutoNumber failed");
		}
		return resultObj;
	 }

