	public JSONObject getRecipientEmailContent()
	{
		try
		{
			Properties props = new Properties();
			Integer usagePercentage = Integer.parseInt(request.getParameter("usage_percentage"));
			String email = request.getParameter("email");
			HashCommandExecutor hashExecutor = CrmCacheProxy.getHashExecutor(RedisConstants.IntegFeature.API);
			String key = new StringBuilder().append(zgId).append("_custom_api_notification_").append(usagePercentage).toString();//No I18N
			String additionalEmailStr = hashExecutor.getKeyValueFromMap(key, "additionalRecipientEmails");//No I18N
            String userEmailStr = hashExecutor.getKeyValueFromMap(key, "userRecipientEmails");//No I18N
			if(additionalEmailStr != null || userEmailStr != null)
			{
				List<String> additionalEmails = additionalEmailStr != null ? Arrays.asList(additionalEmailStr.split(",")) : new ArrayList<>();
				List<String> userEmails = userEmailStr != null ? Arrays.asList(userEmailStr.split(",")) : new ArrayList<>();
				List<String> emailList = new ArrayList<>();
				emailList.addAll(additionalEmails);
				emailList.addAll(userEmails);
				if(emailList.contains(email))
				{
					Locale locale = UserUtil.getUserLangLocaleByUserId(OrgUtil.getUserIdOfPrimaryContact());
					String maxLimit = CrmCacheProxy.getHashExecutor(RedisConstants.IntegFeature.API).getKeyValueFromMap(key, "api_max_limit");//No I18N
                    String apiUsed = CrmCacheProxy.getHashExecutor(RedisConstants.IntegFeature.API).getKeyValueFromMap(key, "api_used_count");//No I18N

					String templateName = "";
					String graphViewURL = new StringBuilder(40).append("https://").append(RebrandLinkUtil.getRebrandKeys("CRMURL")).append(PortalUtil.getCrmBasePath()).append("/settings/api/usage/graph-view").toString();// No I18N
					String paidCreditsURL = new StringBuilder(30).append("https://").append(RebrandLinkUtil.getRebrandKeys("CRMURL")).append(PortalUtil.getCrmBasePath()).append("/settings/api/paid").toString();// No I18N
					props.setProperty("\\#GREETING_CONTENT", ResourceUtil.getResourceValueByKey("api.notification.greetings", locale, new String[] {PartnerUtil.getBrandName()}));
					props.setProperty("\\#THANKS_CONTENT", ResourceUtil.getResourceValueByKey("api.notification.regards.content", locale, new String[] {OrgUtil.getCompanyName(),  OrgUtil.getAppName() }));
					if(usagePercentage != 100)
					{
						props.setProperty("\\#CONTENT1", ResourceUtil.getResourceValueByKey("api.notification.content9", locale, new String[] { maxLimit, apiUsed, String.valueOf(usagePercentage) }));
					}
					if(additionalEmails.contains(email))
					{
						props.setProperty("\\#GREETINGS", ResourceUtil.getResourceValueByKey("api.notification.greetings1", locale, new String[] {com.adventnet.crm.api.v4.commons.NotificationUtil.getDisplayNameByEmail(email)}));
						props.setProperty("\\#CONTENT2", "");
						props.setProperty("\\#DISPLAY_VALUE_FOR_CONTENT2","none");
					}
					else
					{
						CrmUsersService crmUsersService = new CrmUsersServiceImpl();
						CrmUserCriteria emailIdsCriteria = CrmUserCriteria.builder().setEmailIds(Arrays.asList(email)).build();
						props.setProperty("\\#CONTENT2", ResourceUtil.getResourceValueByKey("api.notification.content12", locale, new String[] { graphViewURL , paidCreditsURL}));
						props.setProperty("\\#GREETINGS", ResourceUtil.getResourceValueByKey("api.notification.greetings1", locale, new String[] {UserUtil.getUserName(crmUsersService.geUserIds(emailIdsCriteria).get(0))}));
						props.setProperty("\\#DISPLAY_VALUE_FOR_CONTENT2","block");
					}
					if(CrmCacheProxy.getHashExecutor(RedisConstants.IntegFeature.API).getKeyValueFromMap(zgId+"_custom_api_notification_"+usagePercentage, "is_integration_tasks_used") != null)
					{
						templateName = usagePercentage == 100 ? "api_with_integ_task_mail_100.html" : "api_with_integ_task_mail_80_90.html"; // No I18N
						props.setProperty("\\#CONTENT3", ResourceUtil.getResourceValueByKey("api.notification.content11", locale, new String[] { RebrandLinkUtil.getRebrandKeys("INTEGRATION_TASK_CONSUMES_LIMIT") }));
					}
					else
					{
						templateName = usagePercentage == 100 ? "api_mail_100.html" : "api_mail.html";//No I18N
					}
					byte[] bytes = com.zoho.crm.core.common.CommonUtil.readFile(new StringBuilder().append(CrmConstants.PATH_FOR_HTML).append(templateName).toString());
		  	        String htmlContent = new String( bytes );
		  	        htmlContent = CrmResourceBundleUtil.replaceResourceBundle(htmlContent); 
		  	        Enumeration<Object> keys = props.keys();
		  	        while( keys != null && keys.hasMoreElements() )
		  	        {
		  	            String propertyKey = ( String )keys.nextElement();
		  	            String value = props.getProperty( propertyKey );   
		  	            value = value.replaceAll("\\$","\\\\\\$");
		  	            htmlContent = htmlContent.replaceAll( propertyKey, value );
		  	        }
		  	        resultObj.put("response", htmlContent);
					resultObj.put("status", true);
				}
				else
				{
					LOGGER.log(Level.INFO, "mail not sent in the recent times for the given email", email);
					resultObj.put("response", "mail not sent recently for the given mail");
					resultObj.put("status", false);
				}
			}
			else
			{
				LOGGER.log(Level.INFO, "mail not sent in the recent times for any emails", email);
				resultObj.put("response", "mail not sent recently for any emails");
				resultObj.put("status", false);
			}
		}
		catch(Exception e)
		{
			LOGGER.log(Level.INFO, "Exception occurred", e);
			resultObj.put("response", "mail content not received");
			resultObj.put("status", false);
		}
		return resultObj;
	}
	public JSONObject resetNotificationConfiguration()
	{
		try
		{
			List<Column> columnList = new ArrayList<>();
			columnList.add(Column.getColumn(CRMNOTIFICATIONCONFIGURATION.TABLE, "*"));
			DataObject notificationConfigurationDO = com.adventnet.crm.api.v4.commons.NotificationUtil.getNotificationConfigurationDO(Boolean.FALSE, com.adventnet.crm.api.v4.commons.NotificationUtil.ConfigurationType.API, columnList, null);
			if (notificationConfigurationDO != null && !notificationConfigurationDO.isEmpty()) {
				Row notificationRow = notificationConfigurationDO.getFirstRow(CRMNOTIFICATIONCONFIGURATION.TABLE);
				JSONArray oldThresholds = new JSONArray(notificationRow.get(CRMNOTIFICATIONCONFIGURATION.THRESHOLDS).toString());
				List<Object> oldThresholdsList = oldThresholds.toList();
				for(Object threshold: oldThresholdsList)
				{
					CrmCacheProxy.getHashExecutor(IntegFeature.API).delete(new StringBuilder().append(zgId).append("_custom_api_notification_").append(threshold).toString());//NO I18N
                    CrmCacheProxy.getHashExecutor(IntegFeature.API).delete(new StringBuilder().append(zgId).append("_custom_api_notification_").append(threshold).append("_percent").toString());//NO I18N
				}
				List<String> notificationNcKeys = new ArrayList<>();
				notificationNcKeys.add(APIUsageNotificationUtil.getNotificationSentKey(80));
				notificationNcKeys.add(APIUsageNotificationUtil.getNotificationSentKey(90));
				notificationNcKeys.add(APIUsageNotificationUtil.getNotificationSentKey(100));
				Criteria deleteKeyCriteria = new Criteria(Column.getColumn(CRMNCKEYVALUE.TABLE, CRMNCKEYVALUE.KEYNAME), notificationNcKeys.toArray(), QueryConstants.NOT_IN);
				deleteKeyCriteria = deleteKeyCriteria.and(new Criteria(Column.getColumn(CRMNCKEYVALUE.TABLE, CRMNCKEYVALUE.KEYNAME), "API_USAGE_NOTIFICATION_", QueryConstants.STARTS_WITH));
				CrmKeyValueUtil.deleteCrmNCKeyValueByCriteria(deleteKeyCriteria, Boolean.FALSE, Boolean.FALSE);
				notificationConfigurationDO.deleteRow(notificationRow);
				PersistenceCacheUtil.getPurePersistenceLiteHandle().update(notificationConfigurationDO);
			}
			resultObj.put("response", "notification configuration deleted successfully");
			resultObj.put("status", true);
		}
		catch(Exception e)
		{
			LOGGER.log(Level.INFO, "Exception Occurred", e);
			resultObj.put("response", "notification configuration deletion failed");
			resultObj.put("status", false);
		}
		return resultObj;
	}
	public JSONObject populateAPIUsage() throws Exception
	{
		try
		{
			Integer usagePercentage = Integer.parseInt(request.getParameter("usage_percentage"));
			Integer dreUsagePercentage = Integer.parseInt(request.getParameter("dre_usage_percentage"));
			RollingWindowThrottler rwt = new RollingWindowThrottler(System.currentTimeMillis(), String.valueOf(zgId));
			CrmCacheProxy.getHashExecutor(RedisConstants.IntegFeature.API).delete(rwt.getTodayKey(Boolean.FALSE));
			CrmCacheProxy.getHashExecutor(RedisConstants.IntegFeature.API).delete(rwt.getYesterdayKey(Boolean.FALSE));
			CrmCacheProxy.getHashExecutor(RedisConstants.IntegFeature.API).delete(rwt.getTodayKey(Boolean.TRUE));
			CrmCacheProxy.getHashExecutor(RedisConstants.IntegFeature.API).delete(rwt.getYesterdayKey(Boolean.TRUE));
			String paidKey = new StringBuilder().append(zgId).append("_API_PAID").toString();//NO I18N
			CrmCacheProxy.getHashExecutor(RedisConstants.IntegFeature.API).delete(paidKey);
			String paidDailyKey = new StringBuilder().append(zgId).append("_API_PAY_").append(rwt.getTodaysDate()).toString();//NO I18N
			CrmCacheProxy.getHashExecutor(RedisConstants.IntegFeature.API).delete(paidDailyKey);
			String paidHalfHourKey = new StringBuilder().append(zgId).append("_API_PAY").toString();//NO I18N
			CrmCacheProxy.getHashExecutor(RedisConstants.IntegFeature.API).delete(paidHalfHourKey);
			int limitCount = 0;
			if ( !LicenseUtil.isEditionTrialEvaluationAccount() )
			{
				limitCount = FeatureEditionUtil.getFeatureLimitCount("API_PAID_CREDITS");//NO I18N
				int maxLimit = APIRateLimitCheck.getAvailableExtraLimit();
				limitCount = limitCount > maxLimit ? maxLimit : limitCount;
			}
			int apiLimitWithoutPaidCredits = APIRateLimitCheck.getFeatureLimitCount();
			int maxNewAPILimit = apiLimitWithoutPaidCredits + (limitCount > 0 ? limitCount : 0);
			int usageCount = 0;
			int paidUsageCount = 0;
			if(Boolean.parseBoolean(CrmKeyValueUtil.getCrmKeyValue("IS_NEW_SIGNUP", zgId.toString())) || APIRateLimitCheck.isApiDreMergeEnabled())
			{
				usageCount = maxNewAPILimit * usagePercentage/100;
				paidUsageCount = usageCount > apiLimitWithoutPaidCredits ? usageCount - apiLimitWithoutPaidCredits : 0;
				usageCount = usageCount - paidUsageCount;
			}
			else
			{
				usageCount = maxNewAPILimit * (usagePercentage-dreUsagePercentage)/100;
				int dreUsageCount = maxNewAPILimit * dreUsagePercentage/100;
				paidUsageCount = usageCount > apiLimitWithoutPaidCredits ? usageCount - apiLimitWithoutPaidCredits : 0;
				usageCount = usageCount - paidUsageCount;
				String dreUsedKey = new StringBuilder().append(zgId).append("_DRE_API_USED").toString();//NO I18N
				CrmCacheProxy.getStringExecutor(RedisConstants.IntegFeature.API).put(dreUsedKey, dreUsageCount+"");
				CrmCacheProxy.getHashExecutor(RedisConstants.IntegFeature.API).putKeyValueInMap(rwt.getTodayKey(Boolean.TRUE), rwt.getCurrent5MinKey(), dreUsageCount+"");
				CrmCacheProxy.getHashExecutor(RedisConstants.IntegFeature.API).putKeyValueInMap(rwt.getTodayKey(Boolean.TRUE), rwt.getCurrentHourKey(), dreUsageCount+"");
				CrmCacheProxy.getHashExecutor(RedisConstants.IntegFeature.API).expire(rwt.getTodayKey(Boolean.TRUE), 25*60*60);
			}
			StringBuilder apiUsedKeyBuilder = new StringBuilder().append(zgId).append("_API_USED");//NO I18N
			String apiUsedKey = apiUsedKeyBuilder.toString();
			CrmCacheProxy.getStringExecutor(RedisConstants.IntegFeature.API).put(apiUsedKey, (paidUsageCount > 0 ? usageCount : (usageCount - 1))+"");
			CrmCacheProxy.getHashExecutor(RedisConstants.IntegFeature.API).putKeyValueInMap(rwt.getTodayKey(Boolean.FALSE), rwt.getCurrent5MinKey(), (paidUsageCount > 0 ? usageCount : (usageCount - 1))+"");
			CrmCacheProxy.getHashExecutor(RedisConstants.IntegFeature.API).putKeyValueInMap(rwt.getTodayKey(Boolean.FALSE), rwt.getCurrentHourKey(), (paidUsageCount > 0 ? usageCount : (usageCount - 1))+"");
			CrmCacheProxy.getHashExecutor(RedisConstants.IntegFeature.API).expire(rwt.getTodayKey(Boolean.FALSE), 25*60*60);
			if(paidUsageCount > 0)
			{
				CrmCacheProxy.getStringExecutor(RedisConstants.IntegFeature.API).put(paidKey, (paidUsageCount - 1)+"");
				CrmCacheProxy.getHashExecutor(RedisConstants.IntegFeature.API).putKeyValueInMap(paidDailyKey, rwt.getCurrent5MinKey(), (paidUsageCount - 1)+"");//No I18N
				CrmCacheProxy.getHashExecutor(RedisConstants.IntegFeature.API).putKeyValueInMap(paidDailyKey, rwt.getCurrentHourKey(), (paidUsageCount - 1)+"");//No I18N
				CrmCacheProxy.getHashExecutor(RedisConstants.IntegFeature.API).putKeyValueInMap(paidHalfHourKey, rwt.getTodaysDate()+"_"+rwt.getHalfAnHourKey(), (paidUsageCount - 1)+"");//No I18N
				CrmCacheProxy.getHashExecutor(RedisConstants.IntegFeature.API).expire(paidDailyKey, 25*60*60);
				CrmCacheProxy.getHashExecutor(RedisConstants.IntegFeature.API).expire(paidHalfHourKey, 25*60*60);
			}
			LOGGER.log(Level.INFO, "usagePercentage: {0}, dreUsagePercentage: {1}, limitCount: {2}, apiLimitWithoutPaidCredits:{3},usageCount:{4},paidUsageCount:{5}", new Object[] {usagePercentage,dreUsagePercentage,limitCount,apiLimitWithoutPaidCredits,usageCount,paidUsageCount});
			CloseableHttpClient client= IntegrationUtil.getCloseableHttpClient(0, false);
			String requestURL = request.getRequestURL().toString();
			HttpGet request = new HttpGet( new StringBuilder().append(RebrandLinkUtil.getRebrandKeys("URLPROTOCOL")).append("://").append(OrgUtil.isSandboxAccount() ? RebrandLinkUtil.getRebrandKeys("SANDBOXURL") : RebrandLinkUtil.getRebrandKeys("CRMURL")).append("/crm/v2.1/Contacts?ticket=").append(IAMUtil.getCurrentTicket()).toString());//NO I18N
			request.addHeader("x-crm-org", zgId.toString());//No I18N
			request.addHeader("x-crm-reset", Boolean.TRUE.toString());//No I18N
			client.execute(request);
			resultObj.put("response", "notification triggered successfully");
			resultObj.put("status", true);
		}
		catch(Exception e)
		{
			LOGGER.log(Level.INFO, "Exception Occurred", e);
			resultObj.put("response", "notification trigger failed");
			resultObj.put("status", false);
		}
		return resultObj;
	}
	
