public JSONObject insertDummyHistoryData() throws Exception {
		try {
			DataStorageForecastUtil.savePrediction();
			SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMTIMESERIESSTATS.TABLE));
			sq.addSelectColumn(Column.getColumn(null, "*"));

			Calendar calPrevMonth = Calendar.getInstance();
			calPrevMonth.add(Calendar.MONTH, -12);
			Timestamp timestampPrevMonth = new Timestamp(calPrevMonth.getTimeInMillis());
			Criteria cr1 = new Criteria(Column.getColumn(CRMTIMESERIESSTATS.TABLE, CRMTIMESERIESSTATS.PERIODSTARTTIME), timestampPrevMonth.getTime(), QueryConstants.GREATER_THAN);
			sq.setCriteria(cr1);

			sq.setCriteria(cr1);
			Persistence per = PersistenceCacheUtil.getPurePersistenceLiteHandle();
			DOIterator doIter = new DOIterator(per, sq, 1000, false);
			if (doIter.hasNext()) {
				DataObject dataObj = doIter.next();
				if (!dataObj.isEmpty()) {
					List<Long> timeSeriesStatsIds = new ArrayList<Long>();
					Iterator<Row> rows = dataObj.getRows(CRMTIMESERIESSTATS.TABLE);
					while (rows.hasNext()) {
						Row row = rows.next();
						timeSeriesStatsIds.add((Long) row.get(CRMTIMESERIESSTATS.TIMESERIESSTATSID));
					}
					Criteria deleteCrt = new Criteria(Column.getColumn(CRMTIMESERIESSTATS.TABLE, CRMTIMESERIESSTATS.TIMESERIESSTATSID), timeSeriesStatsIds.toArray(), QueryConstants.IN);
					per.delete(deleteCrt);
				}
			}
			String configId = DataStorageForecastUtil.getStorageConfigId();
			DataObject dataObject = PersistenceCacheUtil.getPurePersistenceLiteHandle().constructDataObject();

			Calendar cal = Calendar.getInstance();
			cal.set(Calendar.DAY_OF_WEEK, Calendar.SUNDAY);
			cal.set(Calendar.HOUR_OF_DAY, 0);
			cal.set(Calendar.MINUTE, 0);
			cal.set(Calendar.SECOND, 0);
			cal.set(Calendar.MILLISECOND, 0);
			cal.add(Calendar.MONTH, -3);
			Timestamp fromTimestamp = DateTimeUtils.getTimeInGMT(cal.getTimeInMillis());

			Calendar currentDate = Calendar.getInstance();
			Timestamp currentTimestamp = DateTimeUtils.getTimeInGMT(currentDate.getTimeInMillis());
			Long usedStorageBefore = 2 * LicenseConstants.ONE_GB_IN_MB * LicenseConstants.ONE_MB_IN_BYTES;

			while (currentTimestamp.after(fromTimestamp)) {

				Row insertRow = new Row(CRMTIMESERIESSTATS.TABLE);
				insertRow.set(CRMTIMESERIESSTATS.INTELLIGENCECONFIGID, configId);
				insertRow.set(CRMTIMESERIESSTATS.PERIODSTARTTIME, fromTimestamp.getTime());
				insertRow.set(CRMTIMESERIESSTATS.TSVALUEA, usedStorageBefore);
				insertRow.set(CRMTIMESERIESSTATS.TSVALUEB, 3);
				insertRow.set(CRMTIMESERIESSTATS.PERIODTYPE, 1);
				dataObject.addRow(insertRow);

				cal.setTimeInMillis(fromTimestamp.getTime());
				cal.add(Calendar.DATE, 7);
				fromTimestamp = new Timestamp(cal.getTimeInMillis());
				usedStorageBefore = (long) (usedStorageBefore + (0.5 * LicenseConstants.ONE_GB_IN_MB * LicenseConstants.ONE_MB_IN_BYTES));
			}
			PersistenceCacheUtil.getPurePersistenceLiteHandle().add(dataObject);
			resultObj.put("status", "Populated Successfully");

		} catch (Exception e) {
			resultObj.put("status", "Populating failed");
		}
		return resultObj;
	}

