	public  JSONObject deleteDummyHistoryData() throws Exception {

		try {
		SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMTIMESERIESSTATS.TABLE));
		sq.addSelectColumn(Column.getColumn(null, "*"));
		Persistence per = PersistenceCacheUtil.getPurePersistenceLiteHandle();
		DOIterator doIter = new DOIterator(per, sq, 1000, false);
		while (doIter.hasNext()) {
			DataObject dataObj = doIter.next();
			if (!dataObj.isEmpty()) {
				List<Long> timeSeriesStatsIds = new ArrayList<Long>();
				Iterator<Row> rows = dataObj.getRows(CRMTIMESERIESSTATS.TABLE);
				while (rows.hasNext()) {
					Row row = rows.next();
					timeSeriesStatsIds.add((Long) row.get(CRMTIMESERIESSTATS.TIMESERIESSTATSID));
				}
				Criteria deleteCrt = new Criteria(Column.getColumn(CRMTIMESERIESSTATS.TABLE, CRMTIMESERIESSTATS.TIMESERIESSTATSID), timeSeriesStatsIds.toArray(), QueryConstants.IN);
				per.delete(deleteCrt);
				resultObj.put("status", "Deleted Successfully");
			}
		}
		}catch(Exception e){
			resultObj.put("status", "Deleting failed");
		}
		return resultObj;
	}

