	/**
	 * to migrate specific reports
	 * dharan-13578
	 * @throws Exception
	 */
	public JSONObject migrateSpecificOldReports() throws Exception
	{
		LOGGER.log(Level.INFO, "migrateSpecificOldReports for {0} -----> started", zgId);
		String [] emailReportTypes = new String [] {"email topusers", "email general", "stats", "email toptemplates"}; //no i18n
		Criteria reportCr = new Criteria(Column.getColumn(CRMREPORT.TABLE, CRMREPORT.ISSAVED), true, QueryConstants.EQUAL);
		reportCr = reportCr.and(new Criteria(Column.getColumn(CRMREPORT.TABLE, CRMREPORT.CATEGORY), 4, QueryConstants.NOT_EQUAL));
		reportCr = reportCr.and(new Criteria(Column.getColumn(CRMREPORT.TABLE, CRMREPORT.QUERYID), null, QueryConstants.NOT_EQUAL));
		reportCr = reportCr.and(new Criteria(Column.getColumn(CRMREPORT.TABLE, CRMREPORT.REPORT_QUERYID), null, QueryConstants.EQUAL));
		reportCr = reportCr.and(new Criteria(Column.getColumn(CRMREPORT.TABLE, CRMREPORT.REPORTTYPE), emailReportTypes, QueryConstants.NOT_IN));
		Persistence per = PersistenceCacheUtil.getPurePersistenceLiteHandle();
		PKChunker chunk = new PKChunker(CRMREPORT.TABLE, null, reportCr, per, 1000, true);

		SelectQuery reportSq = new SelectQueryImpl(Table.getTable(CRMREPORT.TABLE));
		reportSq.addSelectColumn(Column.getColumn(null, "*"));
		boolean status = false;
		while (chunk.hasNext())
		{
			
			Criteria chuckCr = chunk.next();
			reportSq.setCriteria(chuckCr != null ? reportCr.and(chuckCr) : reportCr);
			DataObject repDo = per.get(reportSq);
			Iterator<Row> reportItr = repDo.getRows(CRMREPORT.TABLE);
			List<Long> reportIds = new ArrayList<Long>();
			while (reportItr.hasNext())
			{
				Row reportRow = reportItr.next();
				Long repId = (Long) reportRow.get(CRMREPORT.REPORTID);
				reportIds.add(repId);
			}
			new ReportUtil().migrateSpecificReports(zgId, reportIds);
			status = true;
		}
		if (status)
		{
			resultObj.put("response", "Reports were migrated successfully"); // No I18N
			resultObj.put("status", true);
		}
		else
		{
			resultObj.put("response", "No reports available to migrate"); // No I18N
			resultObj.put("status", false);
		}
		return resultObj;
	}
	
