	/**
	 * populate default new report
	 * @param userId
	 * @param zgId
	 * @throws Exception
	 */
	public static void populateDefaultReports(Long userId, Long zgId) throws Exception
	{
		if(userId == null)
		{
			userId = UserUtil.getCurrentUserId();
		}
		String property = CrmDynamicProperty.getPropertyOrDefault("REPORTS_ENABLED", "false");	//no i18n
		
			ObjectNode reportConfigJsonArray = com.adventnet.crm.common.util.CommonUtil.getConfigJson(CrmConstants.PATH_FOR_REPORTS_CONFIG + "CrmDefaultReportConfig.json");//No I18N
			ArrayNode reportsArr = (ArrayNode)reportConfigJsonArray.get("Reports");
			
			if(FieldUtil.isNewViewEnabled()) {
				for(int i = 0; i < reportsArr.size() ; i++)
				{
					if(reportsArr.get(i).get("name").asText().equals("Call Status Report")) {
						reportsArr.remove(i);
//						ObjectNode callreportConfigJsonArray = CommonUtil.getConfigJson(CrmConstants.PATH_FOR_REPORTS_CONFIG + "CrmCallReportsConfig.json");//No I18N
//						ArrayNode callreportsArr = (ArrayNode)callreportConfigJsonArray.get("Reports");
//						reportsArr.insert(i, callreportsArr.get(0));
//						reportsArr.insert(i, callreportsArr.get(1));
						break;
					}
				}
			}
			
			DeleteQuery dq = new DeleteQueryImpl(Table.getTable(SELECTQUERY.TABLE));
			Join join = new Join(SELECTQUERY.TABLE, CRMREPORT.TABLE, new String[]{SELECTQUERY.QUERYID}, new String[]{CRMREPORT.QUERYID}, Join.INNER_JOIN);
			dq.addJoin(join);
			Criteria presenceCrt = new Criteria(Column.getColumn(CRMREPORT.TABLE, CRMREPORT.CATEGORY), 4, QueryConstants.NOT_EQUAL);	//To hide trend dashboard reports
			dq.setCriteria(presenceCrt);
			PersistenceCacheUtil.getPurePersistenceLiteHandle().delete(dq);

			dq = new DeleteQueryImpl(Table.getTable(CRMANALYTICALCOMPONENTS.TABLE));
			join = new Join(CRMANALYTICALCOMPONENTS.TABLE, CRMREPORT.TABLE, new String[]{CRMANALYTICALCOMPONENTS.COMPONENTID}, new String[]{CRMREPORT.REPORTID}, Join.INNER_JOIN);
			dq.addJoin(join);
			Criteria crt = new Criteria(Column.getColumn(CRMANALYTICALCOMPONENTS.TABLE, CRMANALYTICALCOMPONENTS.COMPONENTTYPE), "Report", QueryConstants.EQUAL);
			crt = crt.and(presenceCrt);
			dq.setCriteria(crt);
			PersistenceCacheUtil.getPurePersistenceLiteHandle().delete(dq); 
			UserMetadataHolder userMeta = new UserMetadataHolder();
			userMeta.setUserId(userId);
			List<ReportFolder> folders = ReportsFolderService.getAllFolders(userMeta.getUserId(), userMeta.getLocale(), new HashMap<>(), false);

			Map<String, Long> folderNameVsId = new HashMap<>();
			int folderLen = folders.size();
			for(int j = 0 ; j < folderLen ; j++)
			{
				ReportFolder rep = folders.get(j);
				folderNameVsId.put(rep.getName(), rep.getId());
			}
			
			int size = reportsArr.size();
			ObjectMapper mapper = new ObjectMapper();
			for(int i = 0; i < size ; i++)
			{
				Report report = mapper.treeToValue(reportsArr.get(i), Report.class);
				report.getFolder().setId(folderNameVsId.get(report.getFolder().getName()));
				ReportsDBService.createReport(report, userId, null);
			}
	}
	
	/**
	 * returns whether org contains atleast 10 default report
	 */
	private boolean containsNewDefaultReports(Persistence per) throws Exception
	{
		SelectQuery reportQry = new SelectQueryImpl(Table.getTable(CRMREPORT.TABLE));
		Column col = Column.createFunction(CalculationTypeEnum.COUNT.getFunctionName(), Column.getColumn(CRMREPORT.TABLE, CRMREPORT.REPORTID));
		col.setColumnAlias("count");
		Criteria crt = new Criteria(Column.getColumn(CRMREPORT.TABLE, CRMREPORT.CATEGORY), 0, QueryConstants.EQUAL);
		crt = crt.and(new Criteria(Column.getColumn(CRMREPORT.TABLE, CRMREPORT.REPORT_QUERYID), null, QueryConstants.NOT_EQUAL));
		reportQry.addSelectColumn(col);
		reportQry.setCriteria(crt);
		reportQry.setRange(new Range(0, 1));

		DataObject dobj =  per.get(reportQry);
		if(dobj != null && !dobj.isEmpty())
		{
			Row row = dobj.getRow(CRMREPORT.TABLE);
			Object count = row.get("count");
			if(count != null & Integer.parseInt((String) count) > 10)	//contains atleast 10 reports
			{
				return true;
			}
		}
		return false;
	}
	
	
