	public JSONObject rename_globalpicklists() {
    	try
    	{
    		Persistence per=PersistenceCacheUtil.getPurePersistenceLiteHandle();
    		SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMSETTINGS.TABLE) );
    		Criteria globalCri=new Criteria(Column.getColumn(CRMSETTINGS.TABLE, CRMSETTINGS.API_NAME), "system.globalfields", QueryConstants.EQUAL);
    		globalCri = globalCri.and(new Criteria(Column.getColumn(CRMSETTINGS.TABLE, CRMSETTINGS.ELEMENT_LABEL), "Global Picklists", QueryConstants.EQUAL));
    		sq.setRange(new Range(0,100));
    		sq.addSelectColumn(Column.getColumn(null,"*"));
    		sq.setCriteria(globalCri);
    		DataObject dobj = per.get(sq);

    		if ( !dobj.isEmpty())
			{
    			Row globalRow = dobj.getRow(CRMSETTINGS.TABLE);
    	        globalRow.set(CRMSETTINGS.ELEMENT_LABEL, "Global Sets"); //No i18N
    	        dobj.updateRow(globalRow);
    	        per.update(dobj);
    	        status = true;
			}
    		else
    		{
    			status = true;
    			LOGGER.log(Level.WARNING, "Global Set name is already correct");
    		}
    	}
    	catch(Exception e)
    	{
        	LOGGER.log(Level.WARNING, "Problem while resetting global picklist name in ResetConfigurations", e);
    		status = false;
    		resultObj.put("response", e.toString());
    		LOGGER.log(Level.WARNING,"Exception while resetting global picklist name", e);
    	}
    	resultObj.put("status", status);
    	return resultObj;
    }

    /**
	 * @return
	 * @throws JSONException
	 */
	public JSONObject resetSystemGlobalFields() throws JSONException {
    	try
    	{
    		Criteria globalDeletecr=new Criteria(Column.getColumn(CRMGLOBALFIELD.TABLE, CRMGLOBALFIELD.GENERATEDTYPE),1,QueryConstants.EQUAL);
    		globalDeletecr= globalDeletecr.and( new Criteria(Column.getColumn(CRMGLOBALFIELD.TABLE, CRMGLOBALFIELD.SYS_REF_NAME),  new String[] {"Source","Industry"} ,QueryConstants.IN));
    		DataObject dobj = GlobalFieldUtil.getGlobalFieldsDOCriteria(globalDeletecr,null);
    		ArrayList<Long> ids = new ArrayList<Long>();
    		if ( !dobj.isEmpty())
			{
    			Iterator<Row> iter = dobj.getRows(CRMGLOBALFIELD.TABLE);
    			while( iter.hasNext()){

    				Row row =  iter.next();
    				Long globalFieldId=(Long) row.get(CRMGLOBALFIELD.GLOBALFIELDID);
    				ids.add(globalFieldId);
    				DataObject fieldsDO = GlobalFieldUtil.getFieldsDO(globalFieldId,null);
    				if(!fieldsDO.isEmpty())
					{
    					LOGGER.log(Level.WARNING, "skipping resetSystemGlobalFields since the global set is associated to field: {0}", globalFieldId);
    	    			status = false;
    	    			break;
					}
    			}
				if(!ids.isEmpty() && status)
    			{
					Map<Long, String> globalPicklistsInScheduler = GlobalFieldUtil.getGlobalPicklistsInScheduler(new HashSet<>(ids),null);
					Set<Long> gplInScheduler = globalPicklistsInScheduler.keySet();
					if(!gplInScheduler.isEmpty())
					{
						LOGGER.log(Level.WARNING, "skipping resetSystemGlobalFields since the global set is in scheduler", gplInScheduler);
		    			status = false;
					}
					else
					{
						deleteGlobalField(ids);
						LOGGER.log(Level.INFO, "Following Global Sets are deleted via resetSystemGlobalFields reset: {0}", ids);
						status = true;
					}
    			}
			}
    		else
    		{
    			status = true;
    			LOGGER.log(Level.WARNING, "No custom global picklist to delete");
    		}

    		if(status)
    		{
    			// need to populate default global set
    			GlobalFieldUtil.populateDefaultGlobalSet();
    		}
    	}
    	catch(Exception e)
    	{
        	LOGGER.log(Level.WARNING, "Problem in resetSystemGlobalFields ResetConfigurations", e);
    		status = false;
    		resultObj.put("response", e.toString());
    	}
    	resultObj.put("status", status);
    	return resultObj;
    }

	private void deleteGlobalField(ArrayList<Long> ids) throws Exception {
		if(!ids.isEmpty())
		{
			DataObject globalPickListValuesDOFromGlobalFieldIdList = GlobalFieldUtil.getGlobalPickListValuesDOFromGlobalFieldIdList(ids, null, true);
			Iterator<Row> pickRows = globalPickListValuesDOFromGlobalFieldIdList.getRows(CRMPICKLISTVALUES.TABLE);
			List<Long> uniqueIds = new ArrayList<Long>();
			while(pickRows.hasNext())
			{
				Row pickRow = pickRows.next();
				uniqueIds.add((Long)pickRow.get(CRMPICKLISTVALUES.UNIQUEID));
			}
			DeleteQueryImpl deletePicQueryImpl = new DeleteQueryImpl(CRMPICKLISTVALUES.TABLE);
			deletePicQueryImpl.setCriteria(new Criteria(Column.getColumn(CRMPICKLISTVALUES.TABLE, CRMPICKLISTVALUES.GLOBALFIELDID),ids.toArray() , QueryConstants.IN));
			PersistenceCacheUtil.getNonCachePersistenceHandle().delete(deletePicQueryImpl);

			DeleteQueryImpl deleteQueryImpl = new DeleteQueryImpl(CRMGLOBALFIELD.TABLE);
			deleteQueryImpl.setCriteria(new Criteria(Column.getColumn(CRMGLOBALFIELD.TABLE, CRMGLOBALFIELD.GLOBALFIELDID),ids.toArray() , QueryConstants.IN));
			PersistenceCacheUtil.getNonCachePersistenceHandle().delete(deleteQueryImpl);

			if(!uniqueIds.isEmpty())
			{
				DeleteQueryImpl deleteTransQueryImpl = new DeleteQueryImpl(CRMTRANSLATIONVALUES.TABLE);
				deleteTransQueryImpl.setCriteria(new Criteria(Column.getColumn(CRMTRANSLATIONVALUES.TABLE, CRMTRANSLATIONVALUES.TRANSLATIONID),uniqueIds.toArray() , QueryConstants.IN));
				PersistenceCacheUtil.getNonCachePersistenceHandle().delete(deleteTransQueryImpl);
			}
		}
	}


	/**
	 * @return
	 * @throws JSONException
	 */
	public JSONObject createInternalGlobalSet() throws JSONException {
		Long globalFieldId = null;
		String apiName = "apiAutomationInternalGPL"; //No I18N
		GlobalFieldService globalFieldService = GlobalFieldService.getInstance();
		IContext context = IContext.getInstance();

		try {
			GlobalField globalSet = globalFieldService.getGlobalSet(apiName, context);
			globalFieldId = globalSet.getGlobalFieldId();
			resultObj.put("globalFieldId", globalFieldId);
            resultObj.put("response",globalFieldId.toString());
			status = true;
		} catch (Exception e) {
            status= false;
			LOGGER.log(Level.WARNING, "createInternalGlobalSet:: Global Field doesn't exist so creating new internal global set", e);
		}
        if(!status)
        {
            try {
                GlobalField gf = (GlobalField) ModelUtil.getInstanceForModel(GlobalField.class);
                gf.setFieldLabel(apiName);
                gf.setApiName(apiName);
                gf.setIsprivate(true);
                GlobalPickListOptions globalPickListOptionDetails = gf.getGlobalPickListOptionDetails(context);
                PickListOption pk = new PickListOption();
                pk.setDisplayValue("a"); // No I18N
                globalPickListOptionDetails.add(pk);
                PickListOption pk2 = new PickListOption();
                pk2.setDisplayValue("b"); // No I18N
                globalPickListOptionDetails.add(pk2);
                GlobalField createGlobalSet = globalFieldService.createGlobalSet(gf, context);
                globalFieldId = createGlobalSet.getGlobalFieldId();
                resultObj.put("globalFieldId", globalFieldId);
                resultObj.put("response",globalFieldId.toString());
                status = true;
            } catch (Exception e) {
                LOGGER.log(Level.WARNING, "Problem in createInternalGlobalSet ResetConfigurations", e);
                status = false;
                resultObj.put("response", e.toString());
            }
        }
		resultObj.put("status", status);
		return resultObj;
	}



