    public JSONObject updateSubformFieldLimit() throws JSONException {
		try {
			String featureName = request.getParameter("featureName");
			int limitCount = Integer.parseInt(request.getParameter("limitCount"));
			int extraCount = Integer.parseInt(request.getParameter("extraCount"));
			int actualCount = Integer.parseInt(request.getParameter("actualCount"));
			if (featureName.equals("SubForm_Configured_Fields") && limitCount <= 25) {
				FeatureEditionUtil.insertORupdateCrmFeatureLimits("SubForm_Configured_Fields", limitCount, extraCount, actualCount, true); // NO I18N
				resultObj.put("response", "Field limit increased/decreased in subform");

			} else {
				resultObj.put("response", "Feature name should be SubForm_Configured_Fields and limitcount should be less than or equal to 25");
				status = false;

			}
		} catch (Exception e) {
			status = false;
			resultObj.put("response", e.toString());
		}
		resultObj.put("status", status);
		return resultObj;
	}

