	public JSONObject scheduleUnallocation() throws Exception
	{
		ReallocationExecutor executor = null;
		try {
			executor = new ReallocationExecutor();
			executor.populateThresholdIdsToRun(false);
			//Method to pick all threshold Id's start
			LOGGER.info("Schedule Unallocation method called directly, will try to unallocate all records irrespective of time gap");
			List<Long> tempThresholdIds=new ArrayList<Long>();
			Iterator<Map.Entry<Long, AssignmentThreshold>> iter = executor.getThresholdIdVsDetails().entrySet().iterator();
			while(iter.hasNext())
			{
				Map.Entry<Long, AssignmentThreshold> entry = iter.next();
				long thresholdId= entry.getKey();
				tempThresholdIds.add(thresholdId);
			}
			executor.setUnallocationThresholdIds(tempThresholdIds);
			//Method to pick all threshold Id's end
			if(executor.isJobNeeded()) {
				executor.process(false);
			}
			
		} catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
		finally {
			ReallocationExecutorUtil.updateExecutionTime(executor.getThresholdDO(), executor.getThresholdIdVsExecutionTimeinGMT(), false, executor.getThresholdIdVsLastAssignedUserId());
		}
        resultObj.put("status", status);
        return resultObj;
	}
