	public void resetReallocationExecutionTime(boolean isFromRealloc) throws Exception
	{
		DataObject doToUpdate = ReallocationUtil.getReallocationThresholdDO(false);
		Iterator<Row> itr = doToUpdate.getRows(CRMASSIGNMENTRESTRICTION.TABLE);
		while(itr.hasNext())
		{
			Row thresRow = itr.next();
				String configDetails = (String) thresRow.get(CRMASSIGNMENTRESTRICTION.CONFIG_DETAILS);
				if(configDetails != null)
				{
					JSONObject configJson = new JSONObject(configDetails);
					JSONObject allocJson = configJson.optJSONObject(ThresholdConstants.ALLOC_PROCESS);
					if(isFromRealloc) {
						allocJson.put(new StringBuilder().append(ThresholdConstants.REALLOCATION_PREFIX).append(ThresholdConstants.ALLOCATION_LAST_RUN).toString(), 0);
					}else {
						allocJson.put(new StringBuilder().append(ThresholdConstants.UNALLOCATION_PREFIX).append(ThresholdConstants.ALLOCATION_LAST_RUN).toString(), 0);
					}
					configJson.put(ThresholdConstants.ALLOC_PROCESS, allocJson);
					thresRow.set(CRMASSIGNMENTRESTRICTION.CONFIG_DETAILS, configJson.toString());
					doToUpdate.updateRow(thresRow);
				}
		}
		PersistenceCacheUtil.getPurePersistenceLiteHandle().update(doToUpdate);
	}
	
	public JSONObject triggerBackLog() throws Exception {
		try {
			Set<Long> defaultAssignees = new HashSet<Long>();
			String module = request.getParameter("module");
			Set<Long> allUsers = ThresholdConfigUtil.getAllAssignmentThresholdUsers(module, defaultAssignees);
			if(!allUsers.isEmpty()) {
				String tableName =  EntityMetaDataUtil.getBaseTableByModuleName(module);
				Criteria crt = new Criteria(Column.getColumn(tableName, CRMLEADDETAILS.SMOWNERID),allUsers.toArray(),QueryConstants.IN);
				UpdateQuery uq = new UpdateQueryImpl(tableName);
				uq.setCriteria(crt);
				uq.setUpdateColumn(CRMLEADDETAILS.CREATEDTIME, DateTimeUtils.getTimestampProiorToGivenDay(1));
				PersistenceCacheUtil.getPurePersistenceLiteHandle().update(uq);
				
				uq = new UpdateQueryImpl(CRMRECORDASSIGNCOUNTER.TABLE);
				uq.setUpdateColumn(CRMRECORDASSIGNCOUNTER.BACKLOG_EXECUTED_TIME, null);
				PersistenceCacheUtil.getPurePersistenceLiteHandle().update(uq);
				
				String sharingTableName = EntityMetaDataUtil.getSharingTableByModuleName(module);
				uq = new UpdateQueryImpl(sharingTableName);
				uq.setUpdateColumn("SHAREDTIME", DateTimeUtils.getTimestampProiorToGivenDay(1));	//No I18N
				crt = new Criteria(Column.getColumn(sharingTableName, "SHAREDTO"),allUsers.toArray(),QueryConstants.IN); //No I18N
				uq.setCriteria(crt);
				PersistenceCacheUtil.getPurePersistenceLiteHandle().update(uq);
				
				ThresholdSchedulerUtil.executeDailyScheduler(OrgUtil.getCurrentZGID(), 999L);
			}
			
		}
		catch(Exception e) {
			status = false;
            resultObj.put("response", e.toString());
		}
		return resultObj.put("status", status);
	}
	public JSONObject exhaustedFunctionsDayLimit() {
		Calendar cal = Calendar.getInstance();
		cal.setTime(cal.getTime());
		cal.setTimeZone(TimeZone.getTimeZone(PMDConstants.GMT));
		int hour = cal.get(Calendar.HOUR_OF_DAY);
		Jedis jedisObj = null;
		Transaction trans = null;
		DateFormat dateFormat = new SimpleDateFormat(STATS_DATE_FORMAT);
		String today=dateFormat.format(cal.getTime()).toString();
		Boolean isLocalZoho = Boolean.valueOf(RebrandLinkUtil.getRebrandKeys("IS_LOCAL_ZOHO")); //No I18N
		if(isLocalZoho)
		{
		try
		{
			String ZGID= OrgUtil.getCurrentZGID().toString();
			jedisObj = RedisConnectionPoolHandler.getRedisConnection(APIConstants.NEW_API_POOL_NAME,RedisUtil.getShardValueForApi(ZGID, null));
			trans = jedisObj.multi();
//			String todayDate = DateTimeUtils.getCurrentDate(PMDConstants.GMT, STATS_DATE_FORMAT).toString();
//			String dateSplitter []=todayDate.split(" ");
			String redisKey=ZGID+"_FUNCTIONS-EXECUTION_"+today;// No I18N
			LOGGER.log(Level.INFO,"Exhaust Day Limit Key ::: {0}",redisKey);
			String hourString=hour<=9?"0"+(hour-1):(hour-1)+"";
			trans.hset(redisKey,hourString, "35000");//NO I18N
			trans.set(ZGID+"_FUNCTIONS-EXECUTION_USED","35000");//NO I18N
			String value = CrmKeyValueUtil.getCrmKeyValue("FUNCTIONS_EXECUTION_EXHAUST_KEY");// No I18N
			if(value==null)
			{
				CrmKeyValueUtil.addCrmKeyValueRow(CommonDBService.getUniqueIdNoTransact(), "FUNCTIONS_EXECUTION_EXHAUST_KEY", hourString);// No I18N
			}
			else
			{
				ResetConfigurations res= new ResetConfigurations();
				res.resetFunctionsDayLimit();
				CrmKeyValueUtil.updateCrmKeyValue("FUNCTIONS_EXECUTION_EXHAUST_KEY", hourString+"");// No I18N
			}
			trans.exec();
			resultObj.put("status", "Successfully Exhausted");

		}
		catch(Exception e)
		{
			resultObj.put("status", "Exhausting Failed For"+e);
			LOGGER.log(Level.WARNING,"Jedis exception ::: ",e);
		}
		finally
		{
			if(jedisObj != null)
			{
				RedisConnectionPoolHandler.returnRedis(jedisObj, APIConstants.NEW_API_POOL_NAME);
			}
		}
		}
		return resultObj;
		
	}
	public JSONObject resetFunctionsDayLimit() {
		
		Jedis jedisObj = null;
		Transaction trans = null;
		Boolean isLocalZoho = Boolean.valueOf(RebrandLinkUtil.getRebrandKeys("IS_LOCAL_ZOHO")); //No I18N
		Calendar cal = Calendar.getInstance();
		cal.setTime(cal.getTime());
		cal.setTimeZone(TimeZone.getTimeZone(PMDConstants.GMT));
		DateFormat dateFormat = new SimpleDateFormat(STATS_DATE_FORMAT);
		String today=dateFormat.format(cal.getTime()).toString();
		cal.add(Calendar.DATE, -1);
		String yesterday=dateFormat.format(cal.getTime()).toString();
		if(isLocalZoho)
		{
		try
		{
			String ZGID= OrgUtil.getCurrentZGID().toString();
			jedisObj = RedisConnectionPoolHandler.getRedisConnection(APIConstants.NEW_API_POOL_NAME,RedisUtil.getShardValueForApi(ZGID, null));
			trans = jedisObj.multi();
//			String todayDate = DateTimeUtils.getCurrentDate(PMDConstants.GMT, STATS_DATE_FORMAT).toString();
//			String dateSplitter []=todayDate.split(" ");
			String redisKey=ZGID+"_FUNCTIONS-EXECUTION_"+today;// No I18N
			String redisKeyYesterday=ZGID+"_FUNCTIONS-EXECUTION_"+yesterday;// No I18N
			LOGGER.log(Level.INFO,"Reset Functions Day Limit Key ::: {0}",redisKey);
			String value = CrmKeyValueUtil.getCrmKeyValue("FUNCTIONS_EXECUTION_EXHAUST_KEY");// No I18N
			String functionExecutionExhaustValue=null;
			if(value!=null)
			{
				functionExecutionExhaustValue=value;
			}
			else
			{
				LOGGER.log(Level.INFO,"FUNCTIONS_EXECUTION_EXHAUST_VALUe ::: {0}","Function Limit still not exceeded");
			}
			trans.hset(redisKey, functionExecutionExhaustValue, "0");//NO I18N
			trans.hset(redisKeyYesterday, functionExecutionExhaustValue, "0");//NO I18N
			trans.set(ZGID+"_FUNCTIONS-EXECUTION_USED","0");//NO I18N
			trans.exec();
			resultObj.put("status", "Successfully Reseted Functions Exhausted Data");

		}
		catch(Exception e)
		{
			resultObj.put("status", "Exhausting Failed For"+e);
			LOGGER.log(Level.WARNING,"Jedis exception ::: ",e);
		}
		finally
		{
			if(jedisObj != null)
			{
				RedisConnectionPoolHandler.returnRedis(jedisObj, APIConstants.NEW_API_POOL_NAME);
			}
		}
		}
		return resultObj;
		
	}
	
