    /**
	 * Schedules rollup summary field dynamic scheduler immediately for Automation cases
	 */
	public JSONObject triggerRollupSummaryFieldsDynamicScheduler() throws JSONException {
		try
		{

			String zgId = OrgUtil.getCurrentZGID().toString();
			Long uniqueId = CommonDBService.getUniqueIdNoTransact();

			CrmJobBean job = new CrmJobBean(uniqueId, CoreScheduleConstants.ROLLUP_DYNAMIC_SCHEDULER, CoreScheduleConstants.ONETIME_HIGH_PROCESS, new Timestamp(System.currentTimeMillis() + 3000));
			job.setTransactionTimeout(-1);
			ScheduleProcessor zcp = new ScheduleProcessor();
			zcp.setJobType(ScheduleProcessor.JobType.OneTimeJob);
			zcp.setCrmJobBean(job);
			try {
				zcp.execute();
				JSONObject json = new JSONObject();
				JSONObject moduleJSON = new JSONObject();
				json.put(RollupDynamicSchConfigHandler.SCH_NEEDED, moduleJSON);
				new RollupDynamicSchConfigHandler(zgId).insertOrUpdateConfigValueForDynamicScheduler(json, Boolean.TRUE, true, true);
			} catch (Throwable e) {
				LOGGER.log(Level.WARNING, "Exception in scheduling Dynamic Rollup Scheduler"); //No I18n
				throw (Exception)e.getCause();
			}
			LOGGER.log(Level.INFO, "Dynamic Rollup Scheduler Triggered zgId - {0} jobId - {1}", new Object[] {zgId, uniqueId}); //No I18n
		}catch (Exception e) {
            status = false;
            LOGGER.log(Level.SEVERE, "Exception in scheduling Dynamic Rollup Scheduler", e); //No I18n
            resultObj.put("response", e.toString());
		}
	    resultObj.put("status", status);
	    return resultObj;
    }

