    /**
	 *  balu-9014
	 */
    public JSONObject resetRetryBulkWorkFlowSchedulerJobs() throws JSONException
    {
        try
        {
        	List <String> actionTypes = new ArrayList<String>();
        	actionTypes.add(AutomationSchedulerUtil.TWOTONINERECORDSOFFLOAD);
        	actionTypes.add(AutomationSchedulerUtil.SINGLE_RECORD_WORKFLOW);
        	actionTypes.add(AutomationSchedulerUtil.BULK_WORKFLOW);
    		Criteria crt = new Criteria(Column.getColumn(CRMSCHEDULEDJOBS.TABLE, CRMSCHEDULEDJOBS.RUNCOUNT), 1, QueryConstants.GREATER_EQUAL);
    		crt = crt.and(new Criteria(Column.getColumn(CRMSCHEDULEDJOBS.TABLE, CRMSCHEDULEDJOBS.ACTION), actionTypes.toArray(), QueryConstants.IN));
    		DataObject scheduleDo = CrmScheduledJobsUtil.getCrmScheduledDataObject(crt);
    		if(!scheduleDo.isEmpty()){
    			Row scheduleRow = scheduleDo.getRow(CRMSCHEDULEDJOBS.TABLE);
    			Long jobId = (Long) scheduleRow.get(CRMSCHEDULEDJOBS.JOBID);
    			String actionType = (String) scheduleRow.get(CRMSCHEDULEDJOBS.ACTION);
    			if (jobId != null) {
                    ZohoCRMSchedule.updateOneTimeJob(jobId, AutomationSchedulerUtil.BULK_WORKFLOW.equals(actionType) ? ZohoCRMScheduleConstants.WORKFLOW_PROCESS : ZohoCRMScheduleConstants.AUTOMATION_PROCESS, true, new Timestamp(System.currentTimeMillis() + 1000 * 3));
                    resultObj.put("response", "job rescheduled for BulkWorkflowScheduler" + jobId); //no i18n
                } else {
                	resultObj.put("response", "There is no jobs execute"); //no i18n
                }
    		}
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }

	public JSONObject hardDeleteScoringRules() throws Exception
	{
		try {
			Criteria crt = new Criteria(Column.getColumn(CRMWORKFLOWRULE.TABLE, CRMWORKFLOWRULE.ISDELETED),true,QueryConstants.EQUAL)
					.and(new Criteria(Column.getColumn(CRMWORKFLOWRULE.TABLE, CRMWORKFLOWRULE.TYPE), CrmAutomationConstants.TYPE_SCORING, QueryConstants.EQUAL));
			SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMSCORINGRULES.TABLE));
			sq.addJoin(new Join(CRMSCORINGRULES.TABLE, CRMWORKFLOWRULE.TABLE, new String[] {CRMSCORINGRULES.SCORINGRULEID}, new String[] {CRMWORKFLOWRULE.RULEID}, Join.INNER_JOIN));
			sq.setCriteria(crt);
			sq.addSelectColumn(Column.getColumn(null, "*"));
			DataObject scoreDO = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(sq);
			List<Long> queryIds = new ArrayList<Long>();
			if(scoreDO != null && !scoreDO.isEmpty())
			{
				Iterator<Row> itr = scoreDO.getRows(CRMSCORINGRULES.TABLE, new Criteria(Column.getColumn(CRMSCORINGRULES.TABLE, CRMSCORINGRULES.QUERYID),null,QueryConstants.NOT_EQUAL));
				while(itr.hasNext())
				{
					Row scoringRow =  itr.next();
					Long queryId = (Long) scoringRow.get(CRMSCORINGRULES.QUERYID);
					if(queryId != null)
					{
						queryIds.add(queryId);
					}
				}
			}
			CrmAutomationUtil.deleteRowsUsingPKChunker(CRMWORKFLOWRULE.TABLE, crt, PersistenceCacheUtil.getPurePersistenceLiteHandle(), 1000);
			if(!queryIds.isEmpty())
			{
				Criteria qryCrt = new Criteria(Column.getColumn(SELECTQUERY.TABLE, SELECTQUERY.QUERYID),queryIds.toArray(),QueryConstants.IN);
				CrmAutomationUtil.deleteRowsUsingPKChunker(SELECTQUERY.TABLE, qryCrt, PersistenceCacheUtil.getPurePersistenceLiteHandle(), 1000);
			}
		}
		catch (Exception e) {
        	    	status = false;
            		resultObj.put("response", e.toString());
        	}
        	resultObj.put("status", status);
        	return resultObj;
	}
	public JSONObject disableLSO() throws Exception
	{
		Long listSubordinatesOnlyPermissionId=null;
	    JSONObject resultObj = new JSONObject();
		SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMPERMISSIONS.TABLE));
		sq.addSelectColumn(new Column(null, "*"));
		Criteria cr = new Criteria(new Column(CRMPERMISSIONS.TABLE,CRMPERMISSIONS.NAME),SecurityConstants.IMPLIED_LIST_SUBORDINATE_USERS,QueryConstants.EQUAL);
		sq.setCriteria(cr);
		sq.setRange(new Range(0, 1));
		DataObject dobj = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(sq);
		if(dobj!=null && !dobj.isEmpty())
		{
			Iterator<Row> iter = dobj.getRows(CRMPERMISSIONS.TABLE);
			while(iter.hasNext())
			{
				Row row = iter.next();
				listSubordinatesOnlyPermissionId = Long.parseLong((String)row.get(CRMPERMISSIONS.PERMISSIONID));
			}
		}
		if(listSubordinatesOnlyPermissionId==null)
		{
			
			resultObj.put("response", " ListSubordinateOnly permission doesn't exist");
		}
		else
		{
				
				 sq = new SelectQueryImpl(Table.getTable(CRMPROFILEPERMISSIONS.TABLE));
				sq.addSelectColumn(new Column(null, "*"));
				 cr = new Criteria(new Column(CRMPROFILEPERMISSIONS.TABLE,CRMPROFILEPERMISSIONS.PERMISSIONID),listSubordinatesOnlyPermissionId,QueryConstants.EQUAL);
					sq.setCriteria(cr);				
					List profileList=ProfileUtil.getProfilesList(String.valueOf(zgId));
					sq.setRange(new Range(0,profileList.size()));
				 dobj = (WritableDataObject)PersistenceCacheUtil.getPurePersistenceLiteHandle().get(sq).clone();
				 if(dobj!=null && !dobj.isEmpty())
					{
						Iterator<Row> iter = dobj.getRows(CRMPROFILEPERMISSIONS.TABLE);
						while(iter.hasNext())
						{
							Row row = iter.next();
							 row.set(CRMPROFILEPERMISSIONS.PRESENCE,0);
							 
						}
					}
					PersistenceCacheUtil.getPurePersistenceLiteHandle().update(dobj);
				 
		resultObj.put("response", "Diabled ListSubordinateOnly permission for all profiles");

		}
		
	
		return resultObj;
	}
	
	public JSONObject activateAllLiteUsers() throws Exception
	{
	    JSONObject resultJO = new JSONObject();
	    
		CrmUserCriteria userCriteria = new CrmUserCriteria();
		userCriteria.setIsLiteUser(true);
		List<UserConstants.Status> statusList = new ArrayList<UserConstants.Status>();
    	statusList.add(UserConstants.Status.DISABLED);
		userCriteria.setStatus(statusList);	    
	    CrmUsersNonCache usersNonCache = CrmUsersNonCache.builder().setUserCriteria(userCriteria).build();
	  	List<Long> inactiveLiteUserIds = usersNonCache.getUserIdsAsList();
	  	
	  	Criteria cr = new Criteria(Column.getColumn(com.zoho.crmcore.CRMIAMUSER.TABLE, com.zoho.crmcore.CRMIAMUSER.SOURCE), UserConstants.TpsourceConstants.LITE_USER.getValue(), QueryConstants.EQUAL);
	  	Integer liteUsersCount = UserUtil.getUsersCount(cr,false,false);
	    
	    if(liteUsersCount==0)
	    {
	    	resultJO.put("response", "No Lite user found for this org");
	    	return resultJO;
	    }
	    try
	    {
	    	OrgContext orgContext = (OrgContext) OrgContext.getInstance().setCurrentUserId(UserUtil.getCurrentUserId());
    		CrmOrgServiceImpl orgServiceImpl = (CrmOrgServiceImpl)ScopedAccess.getInstance(CrmOrgServiceImpl.class, OrgUtil.getCurrentZGID().toString(), TransactionType.REQUIRED);
    		CrmOrgService orgService = CrmOrgService.getInstance();
    		CrmOrg companyInfo = orgService.getCompany();
    		if(companyInfo != null) {
	    		companyInfo.setLite_user_enabled(1);
	    		orgServiceImpl.updateCompanyDetailsDB(companyInfo, orgContext, false);
    		}
    	
    	/*	CrmCompanyInfo table direct reference removal
     	UpdateQuery uq = new UpdateQueryImpl(CRMCOMPANYINFO.TABLE);
      	uq.setUpdateColumn(CRMCOMPANYINFO.LITE_USER_ENABLED,1);
      	PersistenceCacheUtil.getPersistenceLiteHandle().update(uq);
      	*/
      	
    	UpdateQuery uq=new UpdateQueryImpl(CRMLICENSEKEY.TABLE);
      	uq.setUpdateColumn(CRMLICENSEKEY.LITE_USERS_COUNT,liteUsersCount);
      	PersistenceCacheUtil.getPersistenceLiteHandle().update(uq);
      	
      	CrmOrg crmOrg = new CrmOrg(OrgUtil.getCurrentZGID());
		crmOrg.setIsFromOneHandler(false);
		
		RequestDetails req_details = new RequestDetails();
		req_details.setIpaddress(request.getRemoteAddr());
		
		HashMap<Long,CrmUser> setOfOldCrmUser = new HashMap<Long,CrmUser>();
		List<CrmUser> users = new ArrayList<CrmUser>();

		for(Long id :inactiveLiteUserIds) {
			CrmUser crmuser_=new CrmUser();
			crmuser_.setId(id);
			crmuser_.setCurrent_status(UserConstants.Status.ACTIVE.getVal());
			users.add(crmuser_);
		}
		
    	CrmUserData core_user = CrmUserData.builder().setOrg(crmOrg).setUsers(users).setReqDetails(req_details).build();
		core_user.setOld_users(setOfOldCrmUser);
		UserContext userContext = UserContext.getInstance();
		CrmUserFactory.getService().active(core_user, userContext);
	    }
	    catch(Exception e)
	    {
	    	resultJO.put("response", "Lite users are not activated");
			LOGGER.log(Level.WARNING,"Exception occured in activateAllLiteUsers method {0}",e);
			return resultJO;
	    }
    	resultJO.put("response", "Number of Lite users activated "+inactiveLiteUserIds.size()+" - Activated userIds "+inactiveLiteUserIds);  	
    	return resultJO;
	}

/**
	 * @return
	 * @throws Exception
	 */
	public JSONObject getPortalEmailTemplate() throws Exception {
		
		CrmUsers crmUsers = CrmUsers.getInstance(UserUtil.getCurrentUserId(), false);
		String templateName = request.getParameter("templateName"); 
		Long usertypeId = Long.parseLong(request.getParameter("usertypeId"));
		String language = request.getParameter("language");
		Long entityId =  Long.parseLong(request.getParameter("entityId"));
		Long pTabId = CrmClientPortalUtil.getPersonalityTabIdByUserTypeId(usertypeId);
		String moduleApiName = TabUtil.getApiNameByTabId(pTabId);
		String module = TabUtil.getTabNameById(pTabId);
		HashMap <Long, Set<String>> userTypeVsLanguages = new HashMap<>();
		userTypeVsLanguages.put(usertypeId, new HashSet<String>());
		userTypeVsLanguages.get(usertypeId).add(language);
        Map<Long, String[]> entityIdVsUTndLang = new HashMap<Long, String[]>();
        entityIdVsUTndLang.put(entityId, new String[]{usertypeId.toString(), language});
		HashMap<Long, HashMap<String, JSONObject>> userTypeVslangaugeVsJSONObject = CrmPortalTemplates.obtainTemplateDetailsToSendMail(templateName, moduleApiName, crmUsers, userTypeVsLanguages);
		DataObject recordsDO = com.adventnet.crm.clientportal.util.CrmClientPortalInvitationUtil.getRecordsDo(entityIdVsUTndLang.keySet().toArray(), module, true);
		Map<Long, JSONObject> eIdVsTemplateJSON =  CrmPortalTemplates.convertTemplateMergeFieldToSendMail(userTypeVslangaugeVsJSONObject, entityIdVsUTndLang, recordsDO, module, crmUsers);
		for(Entry<Long, JSONObject> template : eIdVsTemplateJSON.entrySet()) {
			String subject = template.getValue().optString("subject"); //NO I18N
			if(subject == null || subject.isEmpty()) {
				String[] lanCon = template.getValue().optString("language").split("_"); //No I18N
				Locale locale = new Locale(lanCon[0], lanCon[1]);
				if(templateName.equals(CrmPortalTemplates.CONFIRM_EMAIL_ADDRESS)) {
					subject = LocalizationUtil.getResourceValueByKey("custmr.prtl.email.update.mail.subject", crmUsers.getCurrentUserId(), OrgUtil.getCompanyName(crmUsers.getCurrentZgid()), locale); //No I18N
					subject = URLDecoder.decode(subject);
				}else if(templateName.equals(CrmPortalTemplates.ACCEPT_INVITAION)) {
					subject = LocalizationUtil.getResourceValueByKey("custmr.prtl.invite.mail.sbjct", crmUsers.getCurrentUserId(), OrgUtil.getCompanyName(crmUsers.getCurrentZgid()), locale); //No I18N
				    subject = URLDecoder.decode(subject);
				}else if(templateName.equals(CrmPortalTemplates.SIGNUP_EMAIL)) {
					subject = LocalizationUtil.getResourceValueByKey("custmr.prtl.signup.mail.subject", crmUsers.getCurrentUserId(), OrgUtil.getCompanyName(crmUsers.getCurrentZgid()), locale); //No I18N
				    subject = URLDecoder.decode(subject);
				}
				template.getValue().put("subject", subject); //No I18N
			}
		}		
		resultObj.put("response", eIdVsTemplateJSON.get(entityId));
		resultObj.put("status", status);
		return resultObj;
	}
	
