	public JSONObject runEmailStatsScheduler() throws Exception {
		Long zgid=OrgUtil.getCurrentZGID();
		String resp;
		String fromDate = (String) request.getParameter("fromDate");//No I18N
		boolean result=false;
		try {
            CrmKeyValueUtil.insertOrUpdateCrmNCKeyValueByKeyName(EmailStatsConstants.EMAILSTATS_AUTOMATION_KEY, "true", false);
			TimeZone tz = OrgUtil.getOrgOrPersonalUserTimeZone();
			Criteria cr= new Criteria(Column.getColumn(CRMNCKEYVALUE.TABLE,CRMNCKEYVALUE.KEYNAME),CrmKeyValueConstants.EMAIL_ANALYTICS_TIMEZONE,QueryConstants.STARTS_WITH);
			CrmKeyValueUtil.deleteCrmNCKeyValueByCriteria(cr, false, false);
			LinkedHashMap<String, String> timeZoneMap = CrmKeyValueUtil.getValueStartingWith(CrmKeyValueConstants.EMAIL_ANALYTICS_TIMEZONE, 1);
			if(timeZoneMap.isEmpty())
			{
			    Timestamp currTimeInGMT = DateTimeUtils.getCurrentTimeInGMT();
			    String date = currTimeInGMT.toString().split(PMDConstants.ONESPACE)[0];//yyyy-mm-dd format
			    String[] dateArr = date.split(PMDConstants.HYPHEN);
			    Calendar c = EmailStatsSchedulerUtil.getCalendarForDate(Integer.parseInt(dateArr[2]), Integer.parseInt(dateArr[1])-1, Integer.parseInt(dateArr[0])-1, true, -1);
			    String yesterday = c.get(Calendar.YEAR) + PMDConstants.HYPHEN + (c.get(Calendar.MONTH) + 1) + PMDConstants.HYPHEN + c.get(Calendar.DAY_OF_MONTH);
			    CrmKeyValueUtil.insertOrUpdateCrmNCKeyValueByKeyName(CrmKeyValueConstants.EMAIL_ANALYTICS_TIMEZONE+yesterday, tz.getID(),false);
			}
		}catch(Exception e) {
			LOGGER.log(Level.WARNING,"Exception occured in runEmailStatsScheduler method while updating Email_analytics_timezone key");
		}
		if(!fromDate.isEmpty()) {
			try {
				Timestamp t=new Timestamp(Long.parseLong(fromDate));
				Date date=new Date(t.getTime());
				Row row=CrmKeyValueUtil.getCrmKeyValueRow("EMAILSTATS_JOBID", zgid.toString());//No I18N
				if(row!=null) {
					Long jobid=(Long)row.get(CRMKEYVALUE.KEYID);

					int day=date.getDate();
					int month=date.getMonth()+1;
					int year=date.getYear()+1900;
					String ncKeyValue="EMAIL_ANALYTICS_FAILURE__"+day+"-"+month+"-"+year;//No I18N
					CrmKeyValueUtil.insertOrUpdateCrmNCKeyValueByKeyName("EMAIL_ANALYTICS_STATUS", ncKeyValue, zgid.toString(), false);//No I18N
					EmailStatsScheduler stats=new EmailStatsScheduler();
					stats.run(jobid);
					result=true;
				}
			}catch(Exception e) {
				LOGGER.log(Level.WARNING,"Exception Occured in startEmailStatsScheduler Method in EmailCredibilityUtil" , e);//No I18N
			}
		}
		if(result) {
			resp="Completed";//No I18N
			resultObj.put("response",resp);
			resultObj.put("status", true);
		}else {
			resp="Not started";//No I18N
			resultObj.put("response",resp);
			resultObj.put("status", false);
		}
		return resultObj;
	}
