	/**
	 *  @serverAudit and tools team
	 *  Automatic ETM profiler enabling before LZ load Automation starts.
	 */
	public JSONObject etmLoadAutoProfilerEnable(){
		try{
			String ipList = request.getParameter("ipList");
			String automationName = request.getParameter("automationName");
			JSONArray requestDetails = new JSONArray(URLDecoder.decode(request.getParameter("requestDetails")));//NO I18N
			LOGGER.log(Level.INFO, "Automatic ETM profiler enabling {0} {1} {2}", ipList+automationName+requestDetails);
			StringBuilder throttleBuilder = new StringBuilder(5000);
			String requestThrotler = CrmDynamicProperty.getPropertyOrDefault(CrmRequestThrottler.REQUEST_THROTTLER,"",true);
			String aliveThreadConfig = CrmDynamicProperty.getPropertyOrDefault(MonitoringConstants.ALIVE_THREAD_MONITORS,"",false);
			String defaultETMEnabled = CrmDynamicProperty.getPropertyOrDefault(MonitoringConstants.EXTERNAL_MONITOR_STATUS,"DISABLED",false);//NO I18N
			String previousETMConfig = CrmDynamicProperty.getProperty(ZCRMAdminConstants.PREVIOUS_ETM_CONFIG);
			JSONObject obj = new JSONObject();
			if(previousETMConfig == null){
				obj.put("AutomationName", automationName);
			}else{
				obj = new JSONObject(previousETMConfig);
				obj.put("AutomationName", addString(obj.optString("AutomationName", ""),automationName));
			}
			boolean isAliveMonitorChange = false;
			if(!aliveThreadConfig.contains("EXTERNAL_MONITOR")){
				isAliveMonitorChange=true;
				aliveThreadConfig = addString(aliveThreadConfig, "EXTERNAL_MONITOR");//NO I18N
			}else{
				if(previousETMConfig == null){
					obj.put("ISAlive", true);//NO I18N
				}
			}
			throttleBuilder.append(requestThrotler);
			int len = requestDetails.length();
			for(int i=0;i<len;i++){
				StringBuilder inner = new StringBuilder();
				JSONObject requestDetail = requestDetails.getJSONObject(i);
				String reqPath = requestDetail.getString("path").trim().replaceAll(" ", "+");
				String method = requestDetail.getString("Method");
				String zgid = requestDetail.getString("Zgid");
				String zuid = requestDetail.getString("Zuid");
				String criticalType = requestDetail.getString("criticalType");
				String etmConf = "DISABLED";// no i18n
				if("CPU Intensive".equals(criticalType)){
					etmConf = "cpu-1-ms-5-"+automationName;// no i18n
				}else if("Memory Intensive".equals(criticalType) || "Max Rows Iterated".equals(criticalType)){// no i18n
					etmConf = "alloc-1-kb-5-"+automationName;// no i18n
				}else{
					continue;
				}
				inner.append(zuid).append(":").append(zgid).append(":").append(reqPath).append(":ALL:EXTERNAL_MONITOR:").append(method).append(":Automated:Automated:").append(etmConf);
				throttleBuilder.append(inner+";");
			}

			HashMap<String,String> dataMap = new HashMap<String,String>();
			dataMap.put(CrmRequestThrottler.REQUEST_THROTTLER, throttleBuilder.toString());
			if(!"DISABLE".equals(defaultETMEnabled)){
				if(previousETMConfig == null){
					obj.put(MonitoringConstants.EXTERNAL_MONITOR_STATUS, defaultETMEnabled);
				}
				dataMap.put(MonitoringConstants.EXTERNAL_MONITOR_STATUS, "DISABLE");
			}
			if(isAliveMonitorChange){
				dataMap.put(MonitoringConstants.ALIVE_THREAD_MONITORS, aliveThreadConfig.toString().replaceAll("^,|:,$|,$", ""));//No I18N
			}
			dataMap.put(automationName, ipList);
			dataMap.put(ZCRMAdminConstants.PREVIOUS_ETM_CONFIG, obj.toString());

			HashCommandExecutor hash = CrmCacheProxy.getHashExecutor(CacheConstants.CrmFeature.COMMON);
			hash.putMultipleKeyValueInMap("DYNAMIC_PROPERTY_CRITICAL_CONFS", dataMap);//No I18N
			StringCommandExecutor string = CrmCacheProxy.getStringExecutor(CacheConstants.CrmFeature.COMMON);
			string.incrementByValue("CRITICAL_CONFS", 1);//No I18N
			resultObj.put("response", "ETM config Successfully added"); //no i18n
		}catch (Exception e) {
			status = false;
			resultObj.put("response", e.toString());
			LOGGER.log(Level.WARNING,"Exception Occurred in etmLoadAutoProfiler ",e);
		}
		resultObj.put("status", status);
		return resultObj;
	}

	/**
	 *  @serverAudit and tools team
	 *  Automatic ETM profiler disabling after LZ load Automation completes.
	 */
	public JSONObject etmLoadAutoProfilerDisable(){
		String result="Success";//NO I18N
		try{
			String automationName = request.getParameter("automationName");
			LOGGER.log(Level.INFO, "Automatic ETM profiler disabling {0}", automationName);
			HashMap<String,String> dataMap = new HashMap<String,String>();
			StringBuilder throttleBuilder = new StringBuilder(5000);
			String previousETMConfig = CrmDynamicProperty.getProperty(ZCRMAdminConstants.PREVIOUS_ETM_CONFIG);
			JSONObject obj = new JSONObject();
			boolean isNoLoadAuto = true;
			if(previousETMConfig != null){
				obj = new JSONObject(previousETMConfig);
				String automationNames = removeString(obj.optString("AutomationName", ""), automationName);//NO I18N
				if("".equals(automationNames)){
					if(obj.has(MonitoringConstants.EXTERNAL_MONITOR_STATUS)){
						dataMap.put(MonitoringConstants.EXTERNAL_MONITOR_STATUS, obj.getString(MonitoringConstants.EXTERNAL_MONITOR_STATUS));
					}
					if(!obj.has("ISAlive")){
						String aliveThreadConfig = CrmDynamicProperty.getPropertyOrDefault(MonitoringConstants.ALIVE_THREAD_MONITORS,"",false);
						dataMap.put(MonitoringConstants.ALIVE_THREAD_MONITORS, removeString(aliveThreadConfig, "EXTERNAL_MONITOR").toString().replaceAll("^,|:,$|,$", ""));//No I18N
					}
				}else{
					isNoLoadAuto = false;
					obj.put("AutomationName", automationNames);
					dataMap.put(ZCRMAdminConstants.PREVIOUS_ETM_CONFIG, obj.toString());
				}
			}
			String requestThrotler = CrmDynamicProperty.getProperty(CrmRequestThrottler.REQUEST_THROTTLER);
			if(requestThrotler != null){
				String[] reqThro = requestThrotler.split(";");
				for(String reqThrottleData: reqThro){
					String innersplit[] = reqThrottleData.split(":");
					if(innersplit.length == 9){
						String samplerType[] = innersplit[8].split("-");
						if(samplerType.length == 5 && automationName.equals(samplerType[4])){
							continue;
						}
						throttleBuilder.append(reqThrottleData+";");
					}else{
						throttleBuilder.append(reqThrottleData+";");
					}
				}
			}

			dataMap.put(CrmRequestThrottler.REQUEST_THROTTLER, throttleBuilder.toString());
			HashCommandExecutor hash = CrmCacheProxy.getHashExecutor(CacheConstants.CrmFeature.COMMON);
			hash.putMultipleKeyValueInMap("DYNAMIC_PROPERTY_CRITICAL_CONFS", dataMap);//No I18N
			hash.deleteKeyInMap("DYNAMIC_PROPERTY_CRITICAL_CONFS", automationName);//No I18N
			if(isNoLoadAuto){
				hash.deleteKeyInMap("DYNAMIC_PROPERTY_CRITICAL_CONFS", ZCRMAdminConstants.PREVIOUS_ETM_CONFIG);//No I18N
			}
			StringCommandExecutor string = CrmCacheProxy.getStringExecutor(CacheConstants.CrmFeature.COMMON);
			string.incrementByValue("CRITICAL_CONFS", 1);//No I18N
			resultObj.put("response", "ETM config Successfully removed "); //no i18n
		}catch (Exception e) {
			status = false;
			resultObj.put("response", e.toString());
			LOGGER.log(Level.WARNING,"Exception Occurred in etmLoadAutoProfiler ",e);
		}
		resultObj.put("status", status);
		return resultObj;
	}

	public static String removeString(String commaSeperateString, String wordToRemove){
		StringBuilder result = new StringBuilder();
		try{
			Set<String> seperatedSet = new HashSet<String>(Arrays.asList(commaSeperateString.split(",")));
			seperatedSet.remove(wordToRemove);
			for(String feature:seperatedSet){
				result.append(feature).append(',');
			}
		}catch (Exception e) {
			LOGGER.log(Level.WARNING,"Exception Occurred in convertString ",e);
		}
		return result.toString();
	}

	public static String addString(String commaSeperateString, String wordToadd){
		StringBuilder result = new StringBuilder();
		try{
			Set<String> seperatedSet = new HashSet<String>(Arrays.asList(commaSeperateString.split(",")));
			seperatedSet.add(wordToadd);
			for(String feature:seperatedSet){
				result.append(feature).append(',');
			}
		}catch (Exception e) {
			LOGGER.log(Level.WARNING,"Exception Occurred in convertString ",e);
		}
		return result.toString();
	}
	
