	/**
	 * deleting Extra CPQ Setup Tabs In CRM
	 */ 
	private void deleteDuplicateCPQSetupPageEntry() {
		try {
			LOGGER.log(Level.INFO,"Deleting Extra CPQ Entry in Setup Page");
			DataObject settingsDo = CrmSettingsUtil.getSettingsCacheDataObject();
			Criteria criteria = new Criteria(Column.getColumn(CRMSETTINGS.TABLE, CRMSETTINGS.ELEMENT_LABEL), "Zoho CPQ", QueryConstants.LIKE);
			Iterator<Row> rows = settingsDo.getRows(CRMSETTINGS.TABLE,criteria);
			List<Long> linkedList = new LinkedList<>();
			int count = 0;
			while(rows.hasNext()) {
				if(count == 0) {
					rows.next();
					count ++;
				}
				else{
					Row next = rows.next();
					Long sourceElement = (Long)next.get(CRMSETTINGS.ELEMENT_ID);
					linkedList.add(sourceElement);
					checkInnerElements(sourceElement, settingsDo, linkedList,0);
				}
			}
			if(linkedList.size() > 0) {
				LOGGER.log(Level.INFO, "Duplicate CPQ setup entries found {0}",new Object[] {linkedList.toArray()});
				DeleteQueryImpl deleteQueryImpl = new DeleteQueryImpl(CRMSETTINGS.TABLE);
				deleteQueryImpl.setCriteria(new Criteria(Column.getColumn(CRMSETTINGS.TABLE, CRMSETTINGS.ELEMENT_ID), linkedList.toArray() , QueryConstants.IN));
				PersistenceCacheUtil.getNonCachePersistenceHandle().delete(deleteQueryImpl);
			}
			//Updating the presence as 1 in CrmSettings Table. Due to CPQ Extension, few accounts presence column having -1
			try {
				DataObject updatedSettingsDo = CrmSettingsUtil.getSettingsCacheDataObject();
				Criteria cpqPresenceCriteria = new Criteria(Column.getColumn(CRMSETTINGS.TABLE, CRMSETTINGS.PRESENCE), "-1", QueryConstants.EQUAL);
				cpqPresenceCriteria = cpqPresenceCriteria.and(new Criteria(Column.getColumn(CRMSETTINGS.TABLE, CRMSETTINGS.GENERATED_SOURCE), "1", QueryConstants.EQUAL));
				cpqPresenceCriteria = cpqPresenceCriteria.and(criteria);
				rows = updatedSettingsDo.getRows(CRMSETTINGS.TABLE,cpqPresenceCriteria);
				if(rows.hasNext()) {
					LOGGER.log(Level.INFO, "CPQ - Crm Settings wrong presence ");
			     	UpdateQuery uq = new UpdateQueryImpl(CRMSETTINGS.TABLE);
			      	uq.setCriteria(cpqPresenceCriteria);
			      	uq.setUpdateColumn(CRMSETTINGS.PRESENCE,1);
			      	PersistenceCacheUtil.getPersistenceLiteHandle().update(uq);
				}
			}catch (Exception e) {
				LOGGER.log(Level.SEVERE, "Exception while updating CPQ Setup page presence :",e); // no i18n
			}
		} catch (Exception e) {
			LOGGER.log(Level.SEVERE, "Exception while deleting CPQ Setup page Entry :",e); // no i18n
		}
	}
	
	/**
	 * 
	 * Method will collect the list of Id's entry
	 * @param elementID
	 * @param settingsDo
	 * @param listOfIds
	 * @throws Exception
	 */
	private void checkInnerElements(Long elementID, DataObject settingsDo, List<Long> listOfIds, int recurssionCount) {
		try {
			Criteria criteria = new Criteria(Column.getColumn(CRMSETTINGS.TABLE, CRMSETTINGS.PARENT_ID), elementID, QueryConstants.EQUAL);
			Iterator<Row> rows = settingsDo.getRows(CRMSETTINGS.TABLE,criteria);
			if(!rows.hasNext() || recurssionCount > 1000) {
				return;
			}
			while(rows.hasNext()) {
				Row next = rows.next();
				Long id = (Long)next.get(CRMSETTINGS.ELEMENT_ID);
				listOfIds.add(id);
				recurssionCount++;
				checkInnerElements(id, settingsDo, listOfIds,recurssionCount);
			}
		} catch (Exception e) {
			LOGGER.log(Level.SEVERE, "Exception while collecting CPQ Setup page Entry :",e); // no i18n
		}
	}

