	/**
	 * deletes given report folder and it's reports
	 * note : it will not delete default reports and report folders
	 */
	@SuppressWarnings("unchecked")
	public JSONObject deleteCustomReportFolders() throws Exception
	{		
		try {
			if(CrmFeatureUtil.isFeatureEnabled("REPORTS_ENABLED", null, String.valueOf(zgId)))
			{
				Criteria cr = new Criteria(Column.getColumn(CRMREPORTFOLDER.TABLE, CRMREPORTFOLDER.CREATEDON), null, QueryConstants.NOT_EQUAL);	// custom folders
				DataObject dataObj = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(CRMREPORTFOLDER.TABLE, cr);
				Iterator<Row> rows = dataObj.getRows(CRMREPORTFOLDER.TABLE);
				List<Long> folderIds = new ArrayList<>();
				while(rows.hasNext())
				{
					Row row = rows.next();
					folderIds.add((Long) row.get(CRMREPORTFOLDER.FOLDERID));
				}
				if(!folderIds.isEmpty())
				{
					Criteria cr1 = new Criteria(Column.getColumn(CRMREPORT.TABLE, CRMREPORT.FOLDERID), folderIds.toArray(), QueryConstants.IN);
					DataObject dataObj1 = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(CRMREPORT.TABLE, cr1);
					Iterator<Row> rows1 = dataObj1.getRows(CRMREPORT.TABLE);
					List<Long> reportIds = new ArrayList<>();
					while(rows1.hasNext())
					{
						Row row = rows1.next();
						reportIds.add((Long) row.get(CRMREPORT.REPORTID));
					}
					if(!reportIds.isEmpty())
					{
						UserMetadataHolder userMeta = new UserMetadataHolder();
						userMeta.setUserId(currentUserId);
						userMeta.setLocale(UserUtil.getUserLangLocaleByUserId(currentUserId));
						userMeta.setZgid(zgId.toString());

						ReportsDBService reportObj = (ReportsDBService) ScopedAccess.getInstance(ReportsDBService.class, null, TransactionType.REQUIRED);
						reportObj.deleteFromTrash(reportIds, userMeta, true);
						
						ReportsFolderDBService.deleteFolders(folderIds, userMeta);
					}
				}
			}
			else
			{
				resultObj.put("response","This can't delete custom report folders in old report flow"); //No I18N
				status = false;
			}
		}
		catch(Exception e)
		{
	       	LOGGER.log(Level.WARNING, "Exception in deleteReportFolder", e);
			resultObj.put("response","Exception in deleteReportFolder"); //No I18N
			status = false;
		}
		resultObj.put("status", status);
		return resultObj;
	}


