    /**
     * @return
     * @throws Exception
     */
    public JSONObject deleteUndeletedWFTaskForOrch() throws Exception
    {
    	try
    	{
    		List<String> modules = OrchestrationConfigUtil.getOrchestrationModules();
    		Persistence per = PersistenceCacheUtil.getPurePersistenceLiteHandle();
    		status = true;
	  		if(!modules.isEmpty()) {
	  			Criteria criteraCrt = new Criteria(Column.getColumn(CRMWORKFLOWTASK.TABLE, CRMWORKFLOWTASK.RELATEDMODULE), modules.toArray(), QueryConstants.NOT_IN).and(new Criteria(Column.getColumn(CRMWORKFLOWTASK.TABLE, CRMWORKFLOWTASK.RELATEDMODULE), "Orchestration", QueryConstants.CONTAINS));
	  			per.delete(criteraCrt);
	    		resultObj.put("response", "Undeleted WFTask- deleted successfully");
	  		
	  		}else {
	    		Criteria criteraCrt = new Criteria(Column.getColumn(CRMWORKFLOWTASK.TABLE, CRMWORKFLOWTASK.RELATEDMODULE), "Orchestration", QueryConstants.CONTAINS);
	  			per.delete(criteraCrt);
	    		resultObj.put("response", "Deleted all orchestration related tasks if present");
	  		}
    	}catch(Exception e)
    	{
	  		  status = false;
	  		  resultObj.put("response", "Exception while deleting undeleted WFTask for orch ::: " + e);
    	}
    	resultObj.put("status", status);
    	return resultObj;
    }
    
    /**
     * Used to check the Health of a machine
     * @param IP
     * @return
     * @throws Exception
     */
    public JSONObject checkConsumerHealth() throws Exception
    {
    	int code=0;
    	String IP=(String) request.getParameter("ip");
    	try {
    		LOGGER.log(Level.INFO, "Given IP {0}", new Object[] {IP});
    		URL url = new URL("http://"+IP+":8080/_app/health"); //No I18N
			HttpURLConnection connection = (HttpURLConnection)url.openConnection();
			connection.setRequestMethod("GET");//No I18N
			connection.connect();

			code = connection.getResponseCode();
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
    	if(code==200) {
    		resultObj.put("status", "success");
    	}else {
    		resultObj.put("status", "failure");
    	}
    		
    	
        return resultObj;
    }

