	public JSONObject revertCPQGSMigration() throws Exception {
	    	try {
	    		if(GuidedSellingUtil.isCpqGsActivated()) {
	    			ZCPQGuidedSellingMigration cpqGSMigration = (ZCPQGuidedSellingMigration)ScopedAccess.getInstance(ZCPQGuidedSellingMigration.class, null, TransactionType.REQUIRED);
	        		cpqGSMigration.doMigration(true);
	        		
	        		Criteria cr = new Criteria(Column.getColumn(CRMTRIALFEATURES.TABLE, CRMTRIALFEATURES.FEATURENAME),Feature.ZOHOCPQ_GUIDEDSELLING.getName(),QueryConstants.EQUAL);
	        		PersistenceCacheUtil.getPurePersistenceLiteHandle().delete(cr);

	        		Criteria fileNameCr = new Criteria(Column.getColumn(AUTOISUAUDITLOG.TABLE, AUTOISUAUDITLOG.MIGRATION_FILENAME), "com.adventnet.crm.autoISU.ZCPQGuidedSellingMigration", QueryConstants.EQUAL);
	    			DeleteQueryUtil.deleteRowsInBatch(AUTOISUAUDITLOG.TABLE, PersistenceCacheUtil.getPurePersistenceLiteHandle(), fileNameCr);

	    			resultObj.put("response", "CPQ Guided Selling Migration Reverted"); //no i18n
	    		}
	    		else {
	    			resultObj.put("status", false); //no i18n
	    			resultObj.put("response", "CPQ Guided Selling Migration already reverted"); //no i18n
	    		}

			} catch (Exception e) {
				resultObj.put("status", false); //no i18n
				resultObj.put("response", e.toString()); //no i18n
			}
	    	resultObj.put("status", status);
	        return resultObj;
	}
	
	/**
	 * Delete MICS Completely & removes the early access too
	 *
	 * @author praveen-10342
	 * @return
	 * @throws Exception
	 */
	public JSONObject revertMICSMigrationAndIntegration() throws Exception {
		try {
			CrmMICSIntegrationUtil.uninstallPlugin();
			CrmMICSIntegrationUtil.deleteMICSPermissionAndTab();

			CrmKeyValueUtil.deleteCrmKeyValueByKeyName(CrmMICSIntegrationConstants.KEY, false);
			CrmKeyValueUtil.deleteCrmNCKeyValueByKeyName(CrmMICSIntegrationConstants.NCKEY, zgId.toString(), false);

			Criteria cr = new Criteria(Column.getColumn(CRMTRIALFEATURES.TABLE, CRMTRIALFEATURES.FEATURENAME), FeatureNameConstants.MICS_ENTERPRISE, QueryConstants.EQUAL);
			PersistenceCacheUtil.getPurePersistenceLiteHandle().delete(cr);

			Criteria fileNameCr = new Criteria(Column.getColumn(AUTOISUAUDITLOG.TABLE, AUTOISUAUDITLOG.MIGRATION_FILENAME), "com.adventnet.crm.autoISU.MICSEnterpriseIntegrationMigration", QueryConstants.EQUAL);
			DeleteQueryUtil.deleteRowsInBatch(AUTOISUAUDITLOG.TABLE, PersistenceCacheUtil.getPurePersistenceLiteHandle(), fileNameCr);

			DeleteQuery dq = new DeleteQueryImpl(Table.getTable(CRMSETTINGS.TABLE));
			Criteria delCr = new Criteria(Column.getColumn(CRMSETTINGS.TABLE, CRMSETTINGS.API_NAME), new String[]{"system.micsent", "system.micsent1"}, QueryConstants.IN);
			dq.setCriteria(delCr);
			dq.setLimit(2);
			PersistenceCacheUtil.getNonCachePersistenceHandle().delete(dq);
			resultObj.put("response", "MICS Migration Reverted"); // no i18n

		} catch (Exception e) {
			resultObj.put("status", false); // no i18n
			resultObj.put("response", e.toString()); // no i18n
		}
		resultObj.put("status", status);
		return resultObj;
	}

