	/**
	 * Onboard MICS to all LZ Services
	 *
	 * @return
	 * @author praveen-10342
	 */
	public JSONObject onBoardMicsELZ() {
		try {
			try {
				JSONArray responseJsonArr = new JSONArray();
				HashSet<String> services = new HashSet<String>(Arrays.asList("546", "529", "44", "547"));
				for (String service : services) {
					JSONObject resp = CrmMICSIntegrationUtil.triggerOnBoardCall(service);
					responseJsonArr.put(resp);
					if (!resp.optString("status").equalsIgnoreCase("SUCCESS")) {
						LOGGER.log(Level.SEVERE, "CrmMICSIntegrationUtil - Other service Onboarding failed. Service - {0}", new Object[]{service});
					}
				}
				resultObj.put("response", responseJsonArr); //no i18n
				resultObj.put("status", true); //no i18n
			} catch (Exception ex) {
				LOGGER.log(Level.SEVERE, "MICSE : Exception in Reverting synced features", ex);
				resultObj.put("response", false); //no i18n
				resultObj.put("status", false); //no i18n
			}
		} catch (Exception e) {
			resultObj.put("status", false); //no i18n
			resultObj.put("response", e.toString()); //no i18n
		}
		resultObj.put("status", status);
		return resultObj;
	}

