    /*
     * This method will add permission for Vendor_Approval
     */
    public JSONObject populateVendorApprovalPerm() throws Exception
    {
    	try {
    		Permission permission = new Permission();
    		permission.setName("Crm_Implied_Approve_Web_Vendors"); //no i18n
    		permission.setDescription("crm.permission.approve.web.Vendors"); //no i18n
    		permission.setPermission_group_name("Approval");	//no i18n
    		permission.setSetype(CrmModuleConstants.VENDORS);
    		
    		List<Long> profileList = new ArrayList<>(Arrays.asList(ProfileUtil.getAdminProfileId(),ProfileUtil.getStandardProfileId()));
    		List<PermissionProfile> permissionProfileList = new ArrayList<PermissionProfile>();
    		Integer profileLen = profileList.size();
    		 for(int i=0;i<profileLen;i++)
    		 {
    		
    			 Long profileId= profileList.get(i);
    			 
    			 PermissionProfile permissionProfile = new PermissionProfile();
    			 permissionProfile.setProfileId(profileId);
    			 permissionProfile.setIscustomizable(Boolean.FALSE);
    			permissionProfile.setPresence(PermissionPresenceType.ENABLE.getValue());
    			permissionProfileList.add(permissionProfile);
    				
    		 }
    		 ProfileUtil.addPermissionsPOJOAndAssoicateToProfiles(permission,permissionProfileList);
    		
    		resultObj.put("status", true); // no i18n
			resultObj.put("response", "vendor approval permission added successfully");
  
    	}
    	catch(Exception ex)
    	{
    		LOGGER.log(Level.SEVERE, "Exception  occurred while adding permission for vendor approval", ex);
    		resultObj.put("exception",ex);
    	}
    	return resultObj;
    }
	/**
	 * @author yahya-pt5660
	 * @throws Exception
	 */
	public void resetTelephonyExternalField() throws  Exception {
		Criteria crt = new Criteria(Column.getColumn(CRMEXTENSION.TABLE, CRMEXTENSION.NAMESPACE),ZPBConstants.EXTNNAMESPACE,QueryConstants.EQUAL);
		PersistenceCacheUtil.getPurePersistenceLiteHandle().delete(crt);
		SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMFIELD.TABLE));
		sq.addSelectColumn(Column.getColumn(null, "*"));
		Criteria cr = new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.SYS_REF_NAME),"Telephony_External_ID__s",QueryConstants.EQUAL);
		cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.TABID),TabUtil.getTabIdByAPIName("Calls"),QueryConstants.EQUAL));
		sq.setCriteria(cr);
		DataObject dataObj = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(sq);
		if( dataObj != null && !dataObj.isEmpty()) {
			Row fieldRow = dataObj .getFirstRow(CRMFIELD.TABLE);
			Long fieldID = (Long) fieldRow.get(CRMFIELD.FIELDID);
			Criteria deleteModeField = new Criteria(Column.getColumn(CRMMODEFIELD.TABLE, CRMFIELD.FIELDID),fieldID,QueryConstants.EQUAL);
	
			PersistenceCacheUtil.getPurePersistenceLiteHandle().delete(cr);
			PersistenceCacheUtil.getPurePersistenceLiteHandle().delete(deleteModeField);
		}

	}

