	    /**
     * To Reset Territory Informations
     * @return
     * @throws Exception
     */
    public JSONObject deleteTerritoryInfo() throws JSONException 
    {
    	try
    	{
    		if(!TerritoryDBService.getCachedTerritoryDo(null).isEmpty())
    		{
    			//Remove the existing entry in CrmScheduledJobs
    			CrmScheduledJobsUtil.deleteJob(new Criteria(Column.getColumn(CRMSCHEDULEDJOBS.TABLE, CRMSCHEDULEDJOBS.ACTION), TerritoryConstants.CREATE_TERRITORY_HIERARCHY_VIA_ROLE, QueryConstants.EQUAL));
    			
                Long[] terr=TerritoryUtil.getTerritoriesList(userId, true, false, true);
                resetConf.deleteQuotasForTerritories(Arrays.asList(terr));
    			TerritoryService terrService=TerritoryService.getInstance();
    			TerritoryContext terrCarrier=TerritoryContext.getInstance();
        		List<Territory> territories = new ArrayList<>();
        		Territory territory = new Territory();
            	territory.setTerritoryId(TerritoryUtil.getOrgTerritoryIDOfAccount(zgId.toString()));
        		terrCarrier.setIsValidationNeeded(false);
                terrService.deleteTerritory(territory, terrCarrier);
                territory();
                HashMap<String,Object> colVsValue = new HashMap<String,Object>();
                colVsValue.put(CRMCOMPANYINFO.TM_ENABLED, Integer.valueOf(0));
                colVsValue.put(CRMCOMPANYINFO.TM_POTENTIALRULE_ENABLED,  Integer.valueOf(0));
                OrgUtil.insertorupdateOrgDetails(colVsValue);
                resultObj.put("response","Territories Informations are Reset Successfully");
                
                //Remove Territory Reports Folder
                SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMREPORTFOLDER.TABLE));
                sq.addSelectColumn(new Column(CRMREPORTFOLDER.TABLE, CRMREPORTFOLDER.FOLDERID));
                sq.setCriteria(new Criteria(Column.getColumn(CRMREPORTFOLDER.TABLE, CRMREPORTFOLDER.STATE), "FEATURE_TERRITORY", QueryConstants.EQUAL));
                DataObject dObj = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(sq);
                if(!dObj.isEmpty()) {
                	Long folderId = (Long) dObj.getFirstRow(CRMREPORTFOLDER.TABLE).get(CRMREPORTFOLDER.FOLDERID);
                	
                	Map<String, String> repFoldParams = new HashMap<String, String>();
                	repFoldParams.put("folder_id", folderId.toString());
                	
                    UserMetadataHolder user = new UserMetadataHolder();
                    user.setUserId(userId);
                    user.setLocale(currentUserLocale);
                    List<Report> territoryReports = ReportsService.getAllReports(user, null, repFoldParams);
                    
                    if(!territoryReports.isEmpty()) {
                    	List<Long> terrRepIds = new ArrayList<Long> ();
                    	territoryReports.forEach( territoryReport -> terrRepIds.add(territoryReport.getId()));
                    	ReportsService.deleteReports(terrRepIds, user, true);
                    	
                    	ReportsFolderService.deleteFolders(new ArrayList<Long> (Arrays.asList(folderId)), user);
                    }
                }
                
                //Remove Territory Dashboard Folder
                Criteria dashCr = new Criteria(Column.getColumn(CRMDASHBOARD.TABLE, CRMDASHBOARD.DASHBOARDNAME), "Territory Dashboard", QueryConstants.EQUAL);
                dashCr = dashCr.and(new Criteria(Column.getColumn(CRMDASHBOARD.TABLE, CRMDASHBOARD.CATEGORY), Integer.valueOf(0), QueryConstants.EQUAL));
                DataObject dashDo = DashboardsUtil.getDashBoardDO(null, dashCr, false, currentUserId);
                if(!dashDo.isEmpty()) {
                	Long folderId = (Long) dashDo.getFirstRow(CRMDASHBOARD.TABLE).get(CRMDASHBOARD.DASHBOARDID);
                	DashboardsDBService.delete(new ArrayList<Long>(Arrays.asList(folderId)), currentUserId, false);
                }
    		}
    	}
    	catch (Exception e) 
    	{
			status = false;
			resultObj.put("response", e.toString());
			LOGGER.log(Level.WARNING, "Exception occured while resetting Territory Informations : {0}",e); // no i18n
		 }
    	return resultObj;
    }
    
    /**
     * Method added for Temprovary Purpose. Will remove this method soon
     * @return
     * @throws Exception
     */
    public JSONObject updateTerritoryFieldsSysRefNameInCustomModule()  throws Exception{
    	try {
    		List<String> customModuleList = new ArrayList<String>();
    		TerritoryCommonUtil.addCustomModulesToCacheModule(customModuleList);
    		
    		if(!customModuleList.isEmpty()) {
    			List<Long> tabIds = TabUtil.getTabIdsByNames(customModuleList, null);
    			UpdateQuery updQry = new UpdateQueryImpl(CRMFIELD.TABLE);
    			updQry.setUpdateColumn(CRMFIELD.SYS_REF_NAME, TerritoryConstants.TERRITORIES_LABEL);
    			
    			Criteria cr = new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.TABID), tabIds.toArray(), QueryConstants.IN);
    			cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.COLUMNNAME), TerritoryConstants.SHAREDTO, QueryConstants.EQUAL));
    			cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.UITYPE), CoreFieldConstants.UITYPE.BIG_INT.TERRITORY_ID_BIGINT.getValue(), QueryConstants.EQUAL));

    			updQry.setCriteria(cr);
    			
    			Persistence per = PersistenceCacheUtil.getPurePersistenceLiteHandle();

    			PKChunker pkRangeCriteria = new PKChunker(CRMFIELD.TABLE, null, cr, per, 1000, false);
    			while (pkRangeCriteria.hasNext()) {
    				Criteria upCr = pkRangeCriteria.next();
    				upCr = (upCr != null) ? upCr.and(cr) : cr;
    				updQry.setCriteria(upCr);
    				per.update(updQry);
    			}
    			TerritoryNonCoreDependentMethodsMigration.dropPageCacheOfModules(customModuleList);
    		}

    	} catch(Exception e) {
			LOGGER.log(Level.WARNING, "exception occurred while resetting Sharedto column api name ===> {0} ", e);
			throw e;
    	}
		return resultObj;
    	
    }
    
    public JSONObject getTerritoryRulesStatus() throws Exception {
    	try {
			DataObject dataObj = TerritoryAssignmentTaskUtil.getTerritoryAssignmentTaskDO(null);
			if(dataObj != null && !dataObj.isEmpty()) {
				List<JSONObject> jsonLst = new ArrayList<JSONObject>();
				Iterator<Row> rows = dataObj.getRows(CRMTERRITORYASSIGNMENTTASK.TABLE);
				Row row = null;
				JSONObject json = null;
				while(rows.hasNext()) {
					json = new JSONObject();
					row = rows.next();
					json.put("jobId", (Long) row.get(CRMTERRITORYASSIGNMENTTASK.QUERYID));
					json.put("module", (String) row.get(CRMTERRITORYASSIGNMENTTASK.SETYPE));
					json.put("scheduled_by", UserUtil.getUserName((Long) row.get(CRMTERRITORYASSIGNMENTTASK.CREATEDBY)));
					json.put("scheduled_time", row.get(CRMTERRITORYASSIGNMENTTASK.CREATEDTIME));
					String type = (String) row.get(CRMTERRITORYASSIGNMENTTASK.RUNTYPE);
					String status = type.indexOf("_COMPLETED") > 0 ? "completed" : type.indexOf("_FAILED") > 0 ? "failed" : "in progress"; //No I18n
					switch(status) {
						case "completed" : 
							type = type.replaceAll("_COMPLETED", "");
							break;
						
						case "failed" : 
							type = type.replaceAll("_FAILED", "");
							break;
					}
					
					json.put("status", status);
					json.put("type", "".equals(type) ? "All Accounts" : type);
					jsonLst.add(json);
				}
                resultObj.put("response", jsonLst.toString());
			} else {
                resultObj.put("response", "There is no territory run rules informations available to show");
			}
    	} catch (Exception ex){
			status = false;
			resultObj.put("response", ex.toString());
			LOGGER.log(Level.WARNING, "Exception occured while retriving Territory Run Rules Status {0} : ",ex); // no i18n
    	}
		return resultObj;
    }


	 /* CPQ permission revert handling done for QA team permission revert case. Dont use this method
	 * 
	 * @author sharan-14131
	 *   
	 */
	public static void revertCPQPermissionQAForAdminProfile() {
		try {
			Long adminProfileId = ProfileUtil.getAdminProfileId();
			List<String> allCPQPermissionsQA = new ArrayList<String>();
			allCPQPermissionsQA.add(SecurityConstants.IMPLIED_ROLE_CPQ_VIEW_PRD_CONF);
			allCPQPermissionsQA.add(SecurityConstants.IMPLIED_ROLE_CPQ_CREATE_PRD_CONF);
			allCPQPermissionsQA.add(SecurityConstants.IMPLIED_ROLE_CPQ_EDIT_PRD_CONF);
			allCPQPermissionsQA.add(SecurityConstants.IMPLIED_ROLE_CPQ_DELETE_PRD_CONF);
			allCPQPermissionsQA.add(SecurityConstants.IMPLIED_ROLE_CPQ_VIEW_PRC_RULES);
			allCPQPermissionsQA.add(SecurityConstants.IMPLIED_ROLE_CPQ_CREATE_PRC_RULES);
			allCPQPermissionsQA.add(SecurityConstants.IMPLIED_ROLE_CPQ_EDIT_PRC_RULES);
			allCPQPermissionsQA.add(SecurityConstants.IMPLIED_ROLE_CPQ_DELETE_PRC_RULES);
			allCPQPermissionsQA.add(SecurityConstants.IMPLIED_ROLE_CPQ_VIEW_QUOTES_DASHBOARD);
			allCPQPermissionsQA.add(SecurityConstants.IMPLIED_ROLE_CPQ_EDIT_QUOTES_DASHBOARD);
			if(ProfileUtil.isPermissionPresence(ProfileUtil.getPermissionIdByName(SecurityConstants.IMPLIED_ROLE_CPQ_VIEW_GUIDED_SELLING))) {
				allCPQPermissionsQA.add(SecurityConstants.IMPLIED_ROLE_CPQ_VIEW_GUIDED_SELLING);
				allCPQPermissionsQA.add(SecurityConstants.IMPLIED_ROLE_CPQ_CREATE_GUIDED_SELLING);
				allCPQPermissionsQA.add(SecurityConstants.IMPLIED_ROLE_CPQ_EDIT_GUIDED_SELLING);
				allCPQPermissionsQA.add(SecurityConstants.IMPLIED_ROLE_CPQ_DELETE_GUIDED_SELLING);
			}
			if(TabUtil.isTabEntryAvailable(CrmModuleConstants.ZOHO_CPQ)) {
				List<Long> permissionsId = ProfileUtil.getPermissionIdsByNames(allCPQPermissionsQA);
				SelectQuery qry = new SelectQueryImpl(Table.getTable(CRMPROFILEPERMISSIONS.TABLE));
				qry.addSelectColumn(Column.getColumn(CRMPROFILEPERMISSIONS.TABLE, "*"));
				qry.setRange(new Range(0,500));
				Criteria permCr = new Criteria(Column.getColumn(CRMPROFILEPERMISSIONS.TABLE, CRMPROFILEPERMISSIONS.PROFILEID), adminProfileId.toString(), QueryConstants.EQUAL);
				permCr = permCr.and(new Criteria(Column.getColumn(CRMPROFILEPERMISSIONS.TABLE, CRMPROFILEPERMISSIONS.PERMISSIONID), permissionsId.toArray(), QueryConstants.IN));
				qry.setCriteria(permCr);
				DataObject permObj = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(qry);
				if ( !permObj.isEmpty() ) {
					Iterator<?> permIter = permObj.getRows(CRMPROFILEPERMISSIONS.TABLE);
					while ( permIter.hasNext() ) {
						Row permRow = (Row) permIter.next();
						permRow.set(CRMPROFILEPERMISSIONS.PRESENCE, "1");
						permObj.updateRow(permRow);
					}
					PersistenceCacheUtil.getPurePersistenceLiteHandle().update(permObj);
				}
			}
		}catch (Exception e) {
			LOGGER.log(Level.SEVERE, "Exception in reverting the CPQ Permission for Admin profiles",e);
		}
	}
	
	/**
	 * This method will return the webform owner notification mail content.
	 * @author balaraman-0027
	 * @return
	 * @throws Exception
	 */
	public JSONObject getWebformNotifyOwnerEmailContent() throws Exception{
    	status = false;
    	try {
    		String entityId = URLDecoder.decode(request.getParameter("entityid").toString(),StandardCharsets.UTF_8.name());
    		String path = zgId +"/webformownernotificationmail/"+entityId+".txt";//No I18N
    		InputStream is =  ZFSUtil.retriveSystemFileFromZFS(zgId.toString(), path);
    		if(is != null) {
    			String notifyOwnerMailStr = IOUtils.toString(is,"utf-8");//No I18N
    			JSONObject notifyOwnerMailObj =  new JSONObject(notifyOwnerMailStr);
    			
    			String trackDomain =  IntegrationConstants.HTTPS + "senderinsights5" + ".";//No I18N
    			
    			trackDomain += "localzoho" + "." + "com";//No I18N
    			
    			LocalZohoTrackLinkUtil obj= new  LocalZohoTrackLinkUtil(notifyOwnerMailObj.getString("MessageID"),trackDomain);//No I18N
    			String content= obj.getMailContentWithTrack(notifyOwnerMailObj.getString("content"));

    			resultObj.put("response", content);
    			status =  true;
    		}else {
    			LOGGER.log(Level.INFO,"Mail content not found in ZFS, Path :: {0}", new Object[]{path});
    		}
    	}catch(Exception e){
    		LOGGER.log(Level.INFO,"Exception while  getting owner notification email content",e);
    		resultObj.put("response",JSONObject.NULL);
    	}

    	resultObj.put("status", status);
    	return resultObj;
	}

