		/**
		 * SupportAccess Revoking Reset Configuration
		 * @return
		 * @throws JSONException
		 */
		public JSONObject revokeSupportAccess() throws Exception {
			String zgid = request.getParameter("zgid");
			JSONObject response = new JSONObject();

			if(zgid!=null) {
				try {
                    SupportAccessUtil.deleteSupportUserAccessJob();
                }catch(Exception e) {
                    LOGGER.log(Level.SEVERE, "EXCEPTION OCCURED WHILE deleteSupportUserAccessJob ",e);
                }
				//IAM end support access disabled
				ServiceOrgAPI serviceOrgAPI = CoreIAMUtil.getServiceOrgAPI();
				serviceOrgAPI.disableTempAccess(IAMServiceOrg.getType(),Long.valueOf(zgid));
				
				try {
                    //Disabling in CRM
                    ResetConfigurationWithTransaction resetConfigs = (ResetConfigurationWithTransaction) ScopedAccess.getInstance(ResetConfigurationWithTransaction.class, zgid, TransactionType.REQUIRED);
                    Long userId = resetConfigs.getSupportUserID(Long.valueOf(zgid));
                    resetConfigs.disableSupportUserInCrmCustomerOrg(userId,Long.valueOf(zgid));
                }catch(Exception e) {
                    LOGGER.log(Level.SEVERE, "EXCEPTION OCCURED WHILE disableSupportUserInCrmCustomerOrg ",e);
                }
				CrmKeyValueUtil.deleteCrmNCKeyValueByKeyName("SUPPORT_ACCESS_ENABLED", String.valueOf(zgid), true); //No i18n
				CrmKeyValueUtil.deleteCrmKeyValueByKeyName("SUPPORT_USER_ACTIVATED", String.valueOf(zgid), true);   //No i18n
				try {
                    //Mark it disabled in common org
                    SupportAccessStore.endSupportAccessOrgSession(Long.valueOf(zgid));
                }catch(Exception e) {
                    LOGGER.log(Level.SEVERE, "EXCEPTION OCCURED WHILE endSupportAccessOrgSession ",e);
                }
				OldLogProps oldLogProps = new OldLogProps();
				AuditLogUtil.addAuditLog(oldLogProps, "disable", "supportaccess", null, null, //no i18n
						null, null, null, currentUserId, 
						null, 0, CreateUpdateEntityDetails.UI, AuditLogConstants.SUPPORT_ACCESS_DISABLED, 
						DateTimeUtils.getCurrentTimeInGMT(), true, null, null, zgid);
				SupportAccessLogService.insertLogForStatusChange(oldLogProps, currentUserId, false);
				resultObj.put("status", status); //no i18n
				resultObj.put("response", "Support Access revoked successfully from the org "+zgid); //no i18n
				return resultObj;
			}
			resultObj.put("status", false); //no i18n
			resultObj.put("response", "zgid Param missing"); //no i18n
			return resultObj;
			
		}
		/**
		 * @author vignesh-pt5645
		 * @throws exception
		 */
		public JSONObject exitSupportUserSession() throws Exception {
			User originalUser = IAMUtil.getCurrentActualUser();
			Long originalZuid = originalUser.getZUID();		

			SupportAccessStore wfbeanObj = (SupportAccessStore) ScopedAccess.getInstance(SupportAccessStore.class, SupportAccessStore.COMMON_ORG_ZGID, TransactionType.SUPPORT);
			Long customerOrgId = wfbeanObj.validateUserMemberOfOtherSupportAccess(originalZuid);
			
			if(customerOrgId!=null && customerOrgId!=-1) {		
				ResetConfigurationWithTransaction resetConfigs = (ResetConfigurationWithTransaction) ScopedAccess.getInstance(ResetConfigurationWithTransaction.class, customerOrgId.toString(), TransactionType.REQUIRED);
				Long userId = resetConfigs.getSupportUserID(customerOrgId);
				try {
					resetConfigs.disableSupportUserInCrmCustomerOrg(userId,customerOrgId);
				}catch(Exception e) {
					 LOGGER.log(Level.SEVERE, "EXCEPTION OCCURED WHILE exitSupportUserSession ",e);
				}
							
				//disable user to the crmiamuser table
				String emailId = originalUser.getContactEmail();
				SupportAccessUtil.removeSupportUserToCustomerOrgInIAM(customerOrgId, String.valueOf(originalZuid));
				
				Long supportAccessId = wfbeanObj.exitActiveSupportAccessOrgSession(customerOrgId, originalZuid);
				wfbeanObj.insertIntoSupportAccessActivityLogs(supportAccessId, originalZuid, emailId, SupportAccessUtil.EXITED);

				OldLogProps oldLogProps = new OldLogProps();
				AuditLogUtil.addAuditLog(oldLogProps, "LogOut", "supportaccess", null, null, //no i18n
						null, null, null, userId, 
						null, 0, CreateUpdateEntityDetails.UI, AuditLogConstants.SUPPORT_ACCESS_LOGOUT, 
						DateTimeUtils.getCurrentTimeInGMT(), true, null, null, customerOrgId.toString());
				SupportAccessLogService.insertLogForLogout(oldLogProps, userId);
				CrmKeyValueUtil.deleteCrmKeyValueByKeyName(SupportAccessUtil.SUPPORTUSERACTIVATED, customerOrgId.toString(), true);
				resultObj.put("status", status); //no i18n
				resultObj.put("response", "Support User exited successfully from the org "+customerOrgId); //no i18n
				return resultObj;
			}
			resultObj.put("status", false); //no i18n
			resultObj.put("response", "Support Access not enable or Support User not logged in to the org "); //no i18n
			return resultObj;
		}
		
