		/**
		 * @return
		 * @throws Exception
		 */
		public JSONObject checkCreationOfDefaultCVNames() throws Exception {
			try {
			    if(OrchestrationConfigUtil.isFeatureAvailable()) {
				    status = true;
				    int orchCount =0;
				    DataObject tabDO = TabUtil.getAllTabsCachedDO();
					String[] orchSystemDefinedTabs = {"Orchestration", "OrchestrationState"}; //no I18N
					Criteria orchestrationCr = new Criteria(Column.getColumn(CRMTAB.TABLE, CRMTAB.NAME), EntityMetaDataUtil.ORCHESTRATION_MODULE_NAME_PREFIX, QueryConstants.STARTS_WITH);
					orchestrationCr = orchestrationCr.and(new Criteria(Column.getColumn(CRMTAB.TABLE, CRMTAB.NAME), orchSystemDefinedTabs, QueryConstants.NOT_IN));
					Iterator<Row> orchTabItr = tabDO.getRows(CRMTAB.TABLE, orchestrationCr);
				    while(orchTabItr.hasNext()) {
					    orchCount++;
					    orchTabItr.next();
				    }
				    Long activeUsersCount = UserUtil.getActiveUsersCount();
				    Long expectedRowCountInDefaultCV = orchCount*activeUsersCount;
				    Long actualRowCountInDefaultCV = 0l;
				    Criteria moduleCri = new Criteria(Column.getColumn(CRMDEFAULTCV.TABLE, CRMDEFAULTCV.MODULE),  EntityMetaDataUtil.ORCHESTRATION_MODULE_NAME_PREFIX, QueryConstants.STARTS_WITH);
				    SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMDEFAULTCV.TABLE));
				    sq.addSelectColumn(Column.getColumn(CRMDEFAULTCV.TABLE,CRMDEFAULTCV.CVID));
				    sq.addSelectColumn(Column.getColumn(CRMDEFAULTCV.TABLE, CRMDEFAULTCV.USERID));
				    sq.setCriteria(moduleCri);
				    DataObject defaultCVDO= null;
				    DOIterator doItr = new DOIterator(PersistenceCacheUtil.getNonCachePersistenceHandle(), sq, 1000);
				    while(doItr!=null && doItr.hasNext()) {
					    defaultCVDO=doItr.next();
					    Iterator<Row> defaultCVRows = defaultCVDO.getRows(CRMDEFAULTCV.TABLE);
					    while(defaultCVRows.hasNext()) {
						    actualRowCountInDefaultCV++;
						    defaultCVRows.next();
					    }
				    }
				    if(expectedRowCountInDefaultCV.equals(actualRowCountInDefaultCV)) {
				    	resultObj.put("response", "DefaultCV names creation successful"); //no i18n
				    }
				    else {
					    resultObj.put("status", false); //no i18n
					    resultObj.put("response", "DefaultCV names count creation failed"); //no i18n
				    }
			    }
			} catch (Exception e) {
				resultObj.put("status", false); //no i18n
				resultObj.put("response", e.toString()); //no i18n
			}
		    resultObj.put("status", status);
		    return resultObj;
		}
		
