        /**
	 * @author mathi-12219
	 * To disable duplicate check preference	
	 * @return
	 */
	public JSONObject disableDuplicateCheckPreference() {
		try {
			DataObject accountdob=PersistenceCacheUtil.getNonCachePersistenceHandle().get(CRMACCOUNTDETAILS.TABLE,(Criteria)null);
			Row accountdobRow = accountdob.getRow( CRMACCOUNTDETAILS.TABLE);
			boolean isUpdated = false;
			if(accountdobRow.get(CRMACCOUNTDETAILS.ORGLEVELCONFIGURATIONS) != null) {
				JSONObject orgLevelConfigJSON = new JSONObject((String)accountdobRow.get(CRMACCOUNTDETAILS.ORGLEVELCONFIGURATIONS));		
				if(orgLevelConfigJSON.has(NameFormatUtil.UNIQUE_FLD_CHK_FOR_CONVERTED_RECORDS)) {
					orgLevelConfigJSON.remove(NameFormatUtil.UNIQUE_FLD_CHK_FOR_CONVERTED_RECORDS);	
					isUpdated = true;
				}
				if(orgLevelConfigJSON.has(NameFormatUtil.UNIQUE_FLD_CHK_FOR_CONTACT_RECORDS)) {
					orgLevelConfigJSON.remove(NameFormatUtil.UNIQUE_FLD_CHK_FOR_CONTACT_RECORDS);	
					isUpdated = true;
				}
				if(orgLevelConfigJSON.has("fieldMapping"))		
				{		
					orgLevelConfigJSON.remove("fieldMapping");		
					isUpdated = true;
				}
				if(isUpdated) {
				   accountdobRow.set(CRMACCOUNTDETAILS.ORGLEVELCONFIGURATIONS, orgLevelConfigJSON.toString());		
				   accountdob.updateRow(accountdobRow);		
				   PersistenceCacheUtil.getNonCachePersistenceHandle().update(accountdob);
				}
			}
		}catch(Exception e) {
			LOGGER.log(Level.SEVERE, "Exception occurred while disabling duplicate check preference",e);
			status = false;
		    resultObj.put("response", e.toString());
		}
		resultObj.put("status", status);
	    return resultObj;
	}	
