	  /**
		 * @author pranav.gr - 14133
		 * Creates system external field
		 * @throws Exception
		 */
		public JSONObject createSystemExternalField() throws Exception
		{
			try {
				String module = request.getParameter("module");
				String fieldLabel = request.getParameter("fieldLabel");
                String sectionName = request.getParameter("sectionName");
				Integer externalType = Integer.valueOf(request.getParameter("externalType"));
				Long layoutId = Long.valueOf(request.getParameter("layoutId"));
				Long tabId = TabUtil.getTabIdByName(module);
				Row sectionRow = SectionUtil.getSectionRowbySectionName(tabId, sectionName, layoutId);
				Long section_Id = (Long) sectionRow.get(CRMSECTION.SECTION_ID);

				ExternalAdapter.System.Record.addSystemExternalField(module, layoutId, section_Id, fieldLabel, externalType);
				
				resultObj.put("response", "System External Field created");
				status = true;
			}
			catch(Exception e) {
				LOGGER.log(Level.INFO, "Exception while creating external field in automation and exception is {0}", new Object[] {e});
				resultObj.put("response", "Exception while creating System External Field ::: " + e); //no i18n
				status = false;
			}
			resultObj.put("status",status);
	    	return resultObj;
		}
		
		/**
		 * @author pranav.gr - 14133
		 * Removes system external field
		 * @throws Exception
		 */
		public JSONObject removeSystemExternalField()
		{
			try {
				String module = request.getParameter("module");
				String fieldName = request.getParameter("fieldName");
				Criteria cr = new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDLABEL), fieldName, QueryConstants.EQUAL);
				Row fieldRow = FieldUtil.getFieldRow(cr);
				
				ExternalAdapter.System.Record.deleteSystemExternalField(module, fieldRow);
				
				resultObj.put("response", "System External Field deleted"); //no i18n
				status = true;
			}
			catch (Exception e) {
				LOGGER.log(Level.INFO, "Exception while deleting field row from automation and exception is {0}", e);
				resultObj.put("response", "Exception while creating System External Field ::: " + e); //no i18n
				status = false;
			}
			resultObj.put("status",status);
	    	return resultObj;
		}
		
		/**
		 * @author pranav.gr - 14133
		 * Removes all system external field from a particular module
		 * @throws Exception
		 */
		public JSONObject removeAllSystemExternalField() {
			try {
				String module = request.getParameter("module");
				Long tabId = TabUtil.getTabIdByName(module);
				Criteria cr = new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.EXTERNALTYPE), null, QueryConstants.NOT_EQUAL);
				cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.GENERATEDTYPE), 1, QueryConstants.EQUAL));
				cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.TABID), tabId, QueryConstants.EQUAL));
				PersistenceCacheUtil.deleteWithLimit(CRMFIELD.TABLE, cr, PersistenceCacheUtil.getPurePersistenceLiteHandle(), 20);
				
				resultObj.put("response", "System External Fields deleted for " + module + " module"); //no i18n
				status = true;
			} catch (Exception e) {
				LOGGER.log(Level.INFO, "Exception while deleting field row from automation and exception is {0}", e);
				resultObj.put("response", "Exception while creating System External Field ::: " + e); //no i18n
				status = false;
			}
			resultObj.put("status",status);
	    	return resultObj;
		}
		
		/**
		 * @author yugesh-13075
		 * Revert Migration for UsersModulePicklistIdConversion Feature
		 * @throws Exception
		 */
		public JSONObject revertUsersModulePicklistIDConversion() throws Exception
		{
			try {

				//feature enable check
				if(!CoreFeatureUtil.isFeatureEnabled(CoreFeatureNameConstants.USERSMODULE_PICKLIST_ID_REFERENCE,null,OrgUtil.getCurrentZGID().toString())) {
					LOGGER.log(Level.INFO, "Feature -UsersModulePicklistIdConversion- Not enabled for the current account {0}", new Object[]{OrgUtil.getCurrentZGID().toString()});
					resultObj.put("response","Feature -UsersModulePicklistIdConversion- Not enabled for the current account {0}" + OrgUtil.getCurrentZGID()); // No I18N
					return resultObj;
				}

                LOGGER.log(Level.INFO, "Reverting Migration - start for UsersModulePickListMigration org :: {0}",new Object[]{OrgUtil.getCurrentZGID().toString()});

                //Fetching all CrmIamuser table picklist values from crmpicklist values table
                HashMap<String,String> UniqueIdVsValues = new HashMap<>();
                SelectQuery picklistValuesTablesQry = new SelectQueryImpl(Table.getTable(CRMPICKLISTVALUES.TABLE));

                Criteria iamUserCustomPicklistCriteria = new Criteria(new Column(CRMFIELD.TABLE,CRMFIELD.TABLENAME),CRMIAMUSER.TABLE,QueryConstants.EQUAL);
                iamUserCustomPicklistCriteria = iamUserCustomPicklistCriteria.and(new Criteria(new Column(CRMFIELD.TABLE,CRMFIELD.GENERATEDTYPE),2,QueryConstants.EQUAL));
                iamUserCustomPicklistCriteria = iamUserCustomPicklistCriteria.and(new Criteria(new Column(CRMFIELD.TABLE,CRMFIELD.UITYPE),2,QueryConstants.EQUAL));

                Join fieldVsPicklistTableJoin = new Join(CRMPICKLISTVALUES.TABLE,CRMFIELD.TABLE,new String[]{CRMPICKLISTVALUES.FIELDID},new String[]{CRMFIELD.FIELDID},Join.INNER_JOIN);
                picklistValuesTablesQry.addSelectColumns(Arrays.asList(new Column(CRMPICKLISTVALUES.TABLE, CRMPICKLISTVALUES.UNIQUEID),new Column(CRMPICKLISTVALUES.TABLE, CRMPICKLISTVALUES.VALUE)));
                picklistValuesTablesQry.addJoin(fieldVsPicklistTableJoin);
                picklistValuesTablesQry.setCriteria(iamUserCustomPicklistCriteria);

                Persistence picklistValuesPers = PersistenceCacheUtil.getNonCachePersistenceHandle(); // Need to check this.
                DOIterator picklistValuesdoIterator = new DOIterator(picklistValuesPers, picklistValuesTablesQry, 1000, true);

                //Fetching picklistvalues from PicklistValues table
                while(picklistValuesdoIterator.hasNext()) {
                    DataObject picklistDO = picklistValuesdoIterator.next();
                    if(!picklistDO.isEmpty()){
                        Iterator<Row> rowIter = picklistDO.getRows(CRMPICKLISTVALUES.TABLE);
                        while(rowIter.hasNext())
                        {
                            Row row = rowIter.next();
                            String uniqueId = row.get(CRMPICKLISTVALUES.UNIQUEID).toString();
                            if(UniqueIdVsValues.get(uniqueId) == null) {
                                UniqueIdVsValues.put(uniqueId, row.get(CRMPICKLISTVALUES.VALUE).toString());
                            }
                        }
                    }
                }
                
                //Getting the PickListfield columns from CrmIamUser table
                List<String> pickListFields = new ArrayList<>();

            	UserFieldHelper field_access = UserFieldHelper.getInstance();
                Map<String, com.zoho.crm.core.service.meta.field.Field> fieldsMeta = field_access.getUserCustomFields();
                for (Map.Entry<String, com.zoho.crm.core.service.meta.field.Field> entry : fieldsMeta.entrySet()) {
                	com.zoho.crm.core.service.meta.field.Field fieldMeta = entry.getValue();
                    if (CRMIAMUSER.TABLE.equals(fieldMeta.getTable_name()) && !fieldMeta.getColumn_name().contains("MXNDUMMYCOLUMN") && fieldMeta.getUi_type() == PickListTrackerConstants.TRACKING_PICKLISTTYPE) {
                            pickListFields.add(fieldMeta.getColumn_name());
                    }
                }

                //Criteria formation using the columns
                Criteria ColumnCriteria = null;
                List<Column> selectColumnList = new ArrayList<Column>();
                int pickListFieldsCount = pickListFields.size();
                for(int i=0;i< pickListFieldsCount;i++){
                	ColumnCriteria = ColumnCriteria == null? new Criteria(new Column(CRMIAMUSER.TABLE,pickListFields.get(i)),null,QueryConstants.NOT_EQUAL) : ColumnCriteria.or(new Column(CRMIAMUSER.TABLE,pickListFields.get(i)),null,QueryConstants.NOT_EQUAL);
                    selectColumnList.add(new Column(CRMIAMUSER.TABLE,pickListFields.get(i)));
                }
                //Select Query formation

                SelectQuery sQry = new SelectQueryImpl(Table.getTable(CRMIAMUSER.TABLE));
                sQry.addSelectColumns(selectColumnList);
                sQry.addSelectColumn(new Column(CRMIAMUSER.TABLE,CRMIAMUSER.USER_ID));
                sQry.setCriteria(ColumnCriteria);

                //Fetching data from DB

                Persistence pers = PersistenceCacheUtil.getNonCachePersistenceHandle(); // Need to check this.
                DOIterator doIterator = new DOIterator(pers, sQry, 1000, true);

                while(doIterator.hasNext()) {
                    DataObject usersDO = doIterator.next();
                    if(!usersDO.isEmpty()){
                    Iterator<Row> rowIter = usersDO.getRows(CRMIAMUSER.TABLE);
                    while(rowIter.hasNext())
                    {
                        Row row = rowIter.next();
                        for(int i = 0; i < selectColumnList.size(); i++){
                            String currentColumn = selectColumnList.get(i).getColumnName();
                            Object value = row.get(currentColumn);
                            if(value != null && UniqueIdVsValues.get(value.toString()) != null){
                                row.set(currentColumn,UniqueIdVsValues.get(value.toString()));
                            }
                        }
                        usersDO.updateRow(row);
                    }
                        pers.update(usersDO);
                    }
                }

                LOGGER.log(Level.INFO, "Reverting Migration - End for UsersModulePickListMigration org :: {0}",new Object[]{OrgUtil.getCurrentZGID()});
                LOGGER.log(Level.INFO, "UsersModulePickListMigration ran successfully for Org {0}",new Object[]{OrgUtil.getCurrentZGID()});
                resultObj.put("response", "UsersModulePickListMigration ran successfully for Org {0}" + OrgUtil.getCurrentZGID());
                CoreFeatureUtil.addOrUpdateTrailOrg(CoreFeatureNameConstants.USERSMODULE_PICKLIST_ID_REFERENCE,OrgUtil.getCurrentZGID().toString(),null,CoreFeatureUtil.Type.ORG.toString(),false,null);
			}
			catch (Exception e) {
				LOGGER.log(Level.INFO, "Exception while running revert migration for UsersModulePicklist Feature {0}", e);
				resultObj.put("response", "Exception while running revert migration for UsersModulePicklist Feature Org {0}" + OrgUtil.getCurrentZGID());
			}
			return resultObj;
		}

    /**
     * @author yugesh-13075
     * Enable Migration for UsersModulePicklistIdConversion Feature
     * @throws Exception
     */
    public JSONObject enableUsersModulePicklistIDConversion() throws Exception {

        try {
        	
        	if(CoreFeatureUtil.isFeatureEnabled(CoreFeatureNameConstants.USERSMODULE_PICKLIST_ID_REFERENCE,null,OrgUtil.getCurrentZGID().toString())) {
				LOGGER.log(Level.INFO, "Feature -UsersModulePicklistIdConversion- already enabled for the current account {0}", new Object[]{OrgUtil.getCurrentZGID().toString()});
				resultObj.put("response","Feature -UsersModulePicklistIdConversion- already enabled for the current account {0}" + OrgUtil.getCurrentZGID()); // No I18N
				return resultObj;
			}
        	
            //Fetching all CrmIamuser table picklist values from crmpicklist values table
            HashMap<String, HashMap<String, String>> columnNameVsValuesVsUniqueId = new HashMap<>();
            SelectQuery picklistValuesTablesQry = new SelectQueryImpl(Table.getTable(CRMPICKLISTVALUES.TABLE));

            Criteria iamUserCustomPicklistCriteria = new Criteria(new Column(CRMFIELD.TABLE, CRMFIELD.TABLENAME), CRMIAMUSER.TABLE, QueryConstants.EQUAL);
            iamUserCustomPicklistCriteria = iamUserCustomPicklistCriteria.and(new Criteria(new Column(CRMFIELD.TABLE, CRMFIELD.GENERATEDTYPE), 2, QueryConstants.EQUAL));
            iamUserCustomPicklistCriteria = iamUserCustomPicklistCriteria.and(new Criteria(new Column(CRMFIELD.TABLE, CRMFIELD.UITYPE), 2, QueryConstants.EQUAL));

            Join fieldVsPicklistTableJoin = new Join(CRMPICKLISTVALUES.TABLE, CRMFIELD.TABLE, new String[]{CRMPICKLISTVALUES.FIELDID}, new String[]{CRMFIELD.FIELDID}, Join.INNER_JOIN);
            picklistValuesTablesQry.addSelectColumns(Arrays.asList(new Column(CRMFIELD.TABLE, CRMFIELD.FIELDID), new Column(CRMFIELD.TABLE, CRMFIELD.COLUMNNAME), new Column(CRMPICKLISTVALUES.TABLE, CRMPICKLISTVALUES.UNIQUEID), new Column(CRMPICKLISTVALUES.TABLE, CRMPICKLISTVALUES.VALUE), new Column(CRMPICKLISTVALUES.TABLE, CRMPICKLISTVALUES.FIELDID)));
            picklistValuesTablesQry.addJoin(fieldVsPicklistTableJoin);
            picklistValuesTablesQry.setCriteria(iamUserCustomPicklistCriteria);

            Persistence picklistValuesPers = PersistenceCacheUtil.getNonCachePersistenceHandle(); // Need to check this.
            DOIterator picklistValuesdoIterator = new DOIterator(picklistValuesPers, picklistValuesTablesQry, 1000, true);

            //Fetching picklistvalues from PicklistValues table
            while (picklistValuesdoIterator.hasNext()) {
                DataObject picklistDO = picklistValuesdoIterator.next();
                if (!picklistDO.isEmpty()) {
                    Iterator<Row> rowIter = picklistDO.getRows(CRMPICKLISTVALUES.TABLE);
                    while (rowIter.hasNext()) {
                        Row row = rowIter.next();
                        Row row2 = picklistDO.getRow(CRMFIELD.TABLE, row); //Getting relevant row from Crmfield table
                        String columnName = row2.get(CRMFIELD.COLUMNNAME).toString();
                        if (columnNameVsValuesVsUniqueId.get(columnName) == null) {
                            columnNameVsValuesVsUniqueId.put(columnName, new HashMap<String, String>());
                        }
                        HashMap<String, String> columnMap = columnNameVsValuesVsUniqueId.get(columnName);
                        columnMap.put(row.get(CRMPICKLISTVALUES.VALUE).toString(), row.get(CRMPICKLISTVALUES.UNIQUEID).toString());
                    }
                }
            }

            //Getting the PickListfield columns from CrmIamUser table
            List<String> pickListFields = new ArrayList<>();

            UserFieldHelper field_access = UserFieldHelper.getInstance();
            Map<String, com.zoho.crm.core.service.meta.field.Field> fieldsMeta = field_access.getUserCustomFields();
            for (Map.Entry<String, com.zoho.crm.core.service.meta.field.Field> entry : fieldsMeta.entrySet()) {
                com.zoho.crm.core.service.meta.field.Field fieldMeta = entry.getValue();
                if (CRMIAMUSER.TABLE.equals(fieldMeta.getTable_name()) && !fieldMeta.getColumn_name().contains("MXNDUMMYCOLUMN") && fieldMeta.getUi_type() == PickListTrackerConstants.TRACKING_PICKLISTTYPE) {
                    pickListFields.add(fieldMeta.getColumn_name());
                }
            }

            //Criteria formation using the columns
            if (pickListFields.size() > 0) {
                Criteria ColumnCriteria = null;
                List<Column> selectColumnList = new ArrayList<Column>();
                int pickListFieldsCount = pickListFields.size();
                for (int i = 0; i < pickListFieldsCount; i++) {
                    ColumnCriteria = ColumnCriteria == null ? new Criteria(new Column(CRMIAMUSER.TABLE, pickListFields.get(i)), null, QueryConstants.NOT_EQUAL) : ColumnCriteria.or(new Column(CRMIAMUSER.TABLE, pickListFields.get(i)), null, QueryConstants.NOT_EQUAL);
                    selectColumnList.add(new Column(CRMIAMUSER.TABLE, pickListFields.get(i)));
                }
                //Select Query formation

                SelectQuery sQry = new SelectQueryImpl(Table.getTable(CRMIAMUSER.TABLE));
                sQry.addSelectColumns(selectColumnList);
                sQry.addSelectColumn(new Column(CRMIAMUSER.TABLE, CRMIAMUSER.USER_ID));
                sQry.setCriteria(ColumnCriteria);

                //Fetching data from DB

                Persistence pers = PersistenceCacheUtil.getNonCachePersistenceHandle(); // Need to check this.
                DOIterator doIterator = new DOIterator(pers, sQry, 1000, true);
                while (doIterator.hasNext()) {
                    DataObject usersDO = doIterator.next();
                    if (!usersDO.isEmpty()) {
                        Iterator<Row> rowIter = usersDO.getRows(CRMIAMUSER.TABLE);
                        while (rowIter.hasNext()) {
                            Row row = rowIter.next();
                            for (int i = 0; i < selectColumnList.size(); i++) {
                                String currentColumn = selectColumnList.get(i).getColumnName();
                                if (row.get(currentColumn) != null) {
                                    Object value = row.get(currentColumn);
                                    String uniqueID = columnNameVsValuesVsUniqueId.get(currentColumn).get(value.toString());
                                    if (uniqueID != null) {
                                        row.set(currentColumn, uniqueID);
                                    }
                                }
                            }
                            usersDO.updateRow(row);
                        }
                        pers.update(usersDO);
                    }
                }
                LOGGER.log(Level.INFO, "UsersModulePickListMigration ran successfully for Org {0}", new Object[]{OrgUtil.getCurrentZGID()});
                resultObj.put("response", "UsersModulePickListMigration ran successfully for Org " + OrgUtil.getCurrentZGID());
            }
            else {
                LOGGER.log(Level.INFO, "Skipped the migration as no custom picklist fields are available in UsersModule for the org {0}", new Object[]{OrgUtil.getCurrentZGID()});
                resultObj.put("response", "Migration invoked - Skipped the migration as no custom picklist fields are available in UsersModule for the org " + OrgUtil.getCurrentZGID());
            }
            CoreFeatureUtil.addOrUpdateTrailOrg(CoreFeatureNameConstants.USERSMODULE_PICKLIST_ID_REFERENCE,OrgUtil.getCurrentZGID().toString(),null,CoreFeatureUtil.Type.ORG.toString(),true,null);
        }
        catch (Exception e){
            LOGGER.log(Level.INFO, "Exception occurred while running Migration :: {0}",e);
            resultObj.put("response", "Exception occurred while enabling UserModulePicklistIdConversion feature for org " + OrgUtil.getCurrentZGID());
        }
        return resultObj;
    }   
        /**
		 * @author suryabhagavan.g - 11091
		 * Blocks an email with given category and Type
		 * @throws Exception
		 */
		public JSONObject blockEmail() throws Exception
		{
			try {
				LOGGER.log(Level.INFO, " while blockEmail email for automation ::::  start");
				String email = request.getParameter("email");
				String bounceCategory = request.getParameter("bounceCategory");
				String bounceType = request.getParameter("bounceType");
				Long blockedTimeInMillis = StringUtils.isValidString(request.getParameter("blockedTimeInMillis")) ? Long.parseLong(request.getParameter("blockedTimeInMillis")) : System.currentTimeMillis();
				String zgid = OrgUtil.getCurrentZGID().toString();
				LOGGER.log(Level.INFO, " while blocking email for automation ::::  blockedTimeInMillis ::: {0}", blockedTimeInMillis);
				BouncedMailsUtil bounceUtil =  new BouncedMailsUtil();
				bounceUtil.blockEmailAddress(zgid, email, bounceCategory, bounceType,blockedTimeInMillis);
				resultObj.put("response","Email blocked Successfully"); // No I18N
				LOGGER.log(Level.INFO, " while blockEmail email for automation ::::  end");
				return resultObj;
				
			}
			catch (Exception e) {
				resultObj.put("response","Email block Failed"); // No I18N
				LOGGER.log(Level.INFO, "Exception while blocking email for automation ::::  exception ::: {0}", e);		
			}
			return resultObj;
		}

        /**
        * To update the limit in table for enabling the paid version of bigin booking pages
        * 
        * @author adithan.p
        *   
        */
        public JSONObject setBiginBookingPagesAddonLimit() {
            JSONObject resultObj = new JSONObject();
            
            try {
                String zgidParam = request.getParameter("zgid");
                if(zgidParam == null || zgidParam.isEmpty()) {
                    zgidParam = String.valueOf(OrgUtil.getCurrentZGID());
                }
                int totallimit = FeatureEditionUtil.getFeatureLimitCount("Booking_Pages", false);//No I18N
                if(totallimit != 1) {
                    FeatureEditionUtil.setFeatureLimitCount("Booking_Pages", 1, 0, 0, false, zgidParam); //No I18N
                }
                resultObj.put("status", true); //No I18N
                resultObj.put("response", "Bigin booking pages addon limit added successfully"); //No I18N
            } catch (Exception e) {
                LOGGER.log(Level.SEVERE, "Exception while setting the bigin booking pages addon limit ==> {0}", new Object[] {e});
                resultObj.put("status", false); //No I18N
                resultObj.put("response", e.getMessage()); //No I18N
            }
            
            return resultObj;
        }

        /**
		 * @return
		 * @throws Exception
		 */
		public JSONObject resetActivityBannerPopup() throws Exception{
            String module = request.getParameter("isPopupEnabled");
            boolean flag = module.equalsIgnoreCase("true")?Boolean.TRUE:Boolean.FALSE;
            return resetActivityBannerPopup(flag);
        }

		/**
		 * @return
		 * @throws Exception
		 */
		private JSONObject resetActivityBannerPopup(boolean isPopupEnabled) throws Exception{
			JSONObject response = new JSONObject();
			String action = isPopupEnabled?"Popup Enabled":"Popup disabled";//NO I18N
			try {
				Long userId = UserUtil.getCurrentUserId();
				if(!isPopupEnabled) {
					CrmActivityUtil.storeBannerAckForUser(userId, Boolean.TRUE, CrmConstants.ACTIVITIES_DEPRECIATION);					
				}else {
					CrmActivityUtil.resetBannerKeyFromRedis(userId);
				}
				
			}catch(Exception ex) {
				LOGGER.log(Level.INFO, "Exception while delting key from redis and exception is {0}", ex);
				response.put("action", action);	
				response.put("status", "Failed");
				return response;
			}
			
			response.put("action", action);	
			response.put("status", "success");
			return response;
		}
		
	/**
     * formViewMigration
     *
     * @author sharan.ka
     *
     */
    public void formViewMigration() throws Exception {
        SelectQueryImpl selectQuery = new SelectQueryImpl(Table.getTable(CRMSETTINGS.TABLE));
        selectQuery.addSelectColumn(Column.getColumn(null, "*"));
        selectQuery.setRange(new Range(0, 1000));
        DataObject settingsObj = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(selectQuery);
        Criteria cr = new Criteria(Column.getColumn(CRMSETTINGS.TABLE, CRMSETTINGS.API_NAME),"system.formview",QueryConstants.EQUAL);
        Row row = settingsObj.getRow(CRMSETTINGS.TABLE, cr);
        if(row == null) {
            //canvas system.formview changed to 3
            Criteria cr4 = new Criteria(Column.getColumn(CRMSETTINGS.TABLE, CRMSETTINGS.API_NAME),"system.canvasbuilder",QueryConstants.EQUAL);
            Row row4 = settingsObj.getRow(CRMSETTINGS.TABLE, cr4);
            Row detailview = new Row(CRMSETTINGS.TABLE);
            detailview.set(CRMSETTINGS.API_NAME, "system.formview");//No i18N
            detailview.set(CRMSETTINGS.ELEMENT_TYPE, 3);
            detailview.set(CRMSETTINGS.SEQUENCE, 3);
            detailview.set(CRMSETTINGS.PRESENCE, 1);
            detailview.set(CRMSETTINGS.ELEMENT_ACTION, 1);
            detailview.set(CRMSETTINGS.GENERATED_SOURCE, 1);
            detailview.set(CRMSETTINGS.ELEMENT_LABEL, "Form View");//No i18N
            detailview.set(CRMSETTINGS.PARENT_ID,row4.get(CRMSETTINGS.ELEMENT_ID));
            settingsObj.addRow(detailview);
            PersistenceCacheUtil.getNonCachePersistenceHandle().update(settingsObj);
        }
    }

