		public JSONObject resetBiginMigrationInCRM() throws Exception {
			try {
				
				Persistence persistence = PersistenceCacheUtil.getPurePersistenceLiteHandle();
				SelectQuery migrationQuery = new SelectQueryImpl(Table.getTable(CRMDATAMIGRATION.TABLE));
				migrationQuery.addSelectColumn(Column.getColumn(CRMDATAMIGRATION.TABLE, CRMDATAMIGRATION.MIGRATIONID));
				int[] arr = {MigrationConstants.RUNNING_SUBSTATUS,MigrationConstants.STOPPED_SUBSTATUS,MigrationConstants.PROGRESS_SUBSTATUS};
				Criteria subStatusCriteria = new Criteria(Column.getColumn(CRMDATAMIGRATION.TABLE, CRMDATAMIGRATION.SUBSTATUS),
						arr, QueryConstants.IN);
				subStatusCriteria = subStatusCriteria.and(new Criteria(Column.getColumn(CRMDATAMIGRATION.TABLE, CRMDATAMIGRATION.SOURCESYSTEM),
						MigrationConstants.CONST_ZOHOBIGIN, QueryConstants.EQUAL));
				migrationQuery.setCriteria(subStatusCriteria);
				DOIterator migrationDOIterator = new DOIterator(persistence,migrationQuery,20);
				while(migrationDOIterator.hasNext()) {
					DataObject migrationDO = migrationDOIterator.next();
					if(migrationDO != null) {
						Iterator<Row> rowIterator = migrationDO.getRows(CRMDATAMIGRATION.TABLE);
						while(rowIterator.hasNext()) {
							Row migrationRow = rowIterator.next();
							migrationRow.set(CRMDATAMIGRATION.SUBSTATUS, MigrationConstants.FIELD_MAP_SUBSTATUS);
							migrationDO.updateRow(migrationRow);
						}
					}
					persistence.update(migrationDO);
				}
				status = true;
				resultObj.put("response", "sub status changed"); //no 18n
				LOGGER.log(Level.INFO,new StringBuilder().append("Bigin CRM Migration Sub status updated").toString()); //no i18n
			}
			catch(Exception e) {
				status = false;
				resultObj.put("response", "Exception occured. please check log"); //noi18n
				LOGGER.log(Level.INFO,new StringBuilder().append("Bigin CRM Migration Exception occured at reverting sub status. The exception is").append(e).toString()); //no i18n
			}
			resultObj.put("status", status);
			return resultObj;
		}
		
