		public void deleteBiginFileCabinetFolders() {
            try {
                    LOGGER.log(Level.INFO, "File Cabinet delete all records and files started");
                    JSONArray dataArray = new JSONArray();
                    JSONArray dataArray1 = new JSONArray();
                    Long tabId = TabUtil.getTabIdByAPIName(CrmModuleConstants.CONTACTS);
                    SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMWORKDRIVEFOLDERMAPPING.TABLE));
                    sq.addSelectColumn(Column.getColumn(CRMWORKDRIVEFOLDERMAPPING.TABLE, "*")); // NO I18N
                    Criteria cr = new Criteria(Column.getColumn(CRMWORKDRIVEFOLDERMAPPING.TABLE, CRMWORKDRIVEFOLDERMAPPING.TAB_ID), tabId, QueryConstants.EQUAL);
                    cr = cr.and(new Criteria(Column.getColumn(CRMWORKDRIVEFOLDERMAPPING.TABLE, CRMWORKDRIVEFOLDERMAPPING.USER_ID), userId, QueryConstants.EQUAL));
                    sq.setCriteria(cr);
                    sq.setRange(new Range(0, 25000));
                    DataObject dobj = PersistenceCacheUtil.getNonCachePersistenceHandle().get(sq);
                    Iterator<Row> iter = dobj.getRows(CRMWORKDRIVEFOLDERMAPPING.TABLE);
                    JSONObject attributes = new JSONObject();
                    attributes.put("status", "51");
                    JSONObject attributes1 = new JSONObject();
                    attributes1.put("status", "61");
                    while (iter.hasNext()) {
                        Row row = iter.next();
                            String pFolderId = (String) row.get(CRMWORKDRIVEFOLDERMAPPING.WD_FOLDER_ID);
                            Long userId = (Long) row.get(CRMWORKDRIVEFOLDERMAPPING.USER_ID);
                            JSONObject filesList = WorkDriveUtil.getFilesListFromFc(pFolderId, userId, 0, 200);
                            if (filesList.has("data")) {
                                    JSONArray fileArray = filesList.getJSONArray("data");		//NO I18n
                                    int arraysize = fileArray.length();
                                    if (arraysize > 0) {
                                            for (int i = 0; i < arraysize; i++) {
                                                    JSONObject js = fileArray.getJSONObject(i);
                                                    if (js.has("id")) {
                                                            String folderId = js.getString("id");
                                                            JSONObject innerObj = new JSONObject();
                                                            innerObj.put("type", "files");
                                                            innerObj.put("attributes", attributes);
                                                            innerObj.put("id", folderId);
                                                            dataArray.put(innerObj);
                                                            JSONObject innerObj1 = new JSONObject();
                                                            innerObj1.put("type", "files");
                                                            innerObj1.put("attributes", attributes1);
                                                            innerObj1.put("id", folderId);
                                                            dataArray1.put(innerObj1);
                                                    }
                                            }
                                    }
                            }
                    }
                    String workdriveAPIUrl = WorkDriveUtil.getWorkdriveDomainUrl() + "/api/v1/files";// No I18n
                    LOGGER.log(Level.INFO, "workdriveAPIUrl::::{0}", workdriveAPIUrl);
                    HttpPatch reqObj = (HttpPatch) IntegrationUtil.getRequestObject(IntegrationConstants.PATCH, workdriveAPIUrl);
                    WorkDriveUtil.prePopulateHeadersPatch(reqObj, WorkdriveAuthenticationType.ORG_OAUTH, null, null, null, null);
                    reqObj.setHeader("isAccessedFromAdmin", "1"); // No i18N
                    JSONObject requestObj = new JSONObject();
                    requestObj.put("data", dataArray);
                    StringEntity params = new StringEntity(requestObj.toString());
                    reqObj.setEntity(params);
                    HttpPatch reqObj1 = reqObj;

                    HttpResponse httpResponse = IntegrationUtil.connectToInternalServiceAPI(reqObj, CloseablehttpConnPools.WORKDRIVE);
                    String response = IntegrationUtil.convertStreamToString(httpResponse.getEntity().getContent());
                    LOGGER.log(Level.WARNING, "response deleteFolders::::{0}", response);
					JSONObject requestObj1 = new JSONObject();
					requestObj1.put("data", dataArray1);
					reqObj1.setEntity(new StringEntity(requestObj1.toString()));
                    HttpResponse httpResponse1 = IntegrationUtil.connectToInternalServiceAPI(reqObj1, CloseablehttpConnPools.WORKDRIVE);
                    String response1 = IntegrationUtil.convertStreamToString(httpResponse1.getEntity().getContent());
                    LOGGER.log(Level.WARNING, "response permanent deleteFolders::::{0}", response1);
                    
                    LOGGER.log(Level.INFO, "File Cabinet delete all records and file completed");
            } catch (Exception e) {
                    LOGGER.log(Level.INFO, "Exception while deleting file and folder of File Cabinet {0}", e);
            }
		}
		
		public JSONObject invokeCompetitorExtractionEmail() {

			  try 
			  {				  	
				    JSONObject mailJson = new JSONObject();			
					String zgid = request.getParameter("zgid");
					String senderEmail = request.getParameter("senderemail");
				  	JSONObject resultObj = new JSONObject();		
					mailJson.put("emailContent","Hi team,   Tech Mahindra is a good & the best company in India. And also your service is very poor. So we are planning to quit from your service.  Regardsvicknesh G");
					
					mailJson.put("id",1l);
					mailJson.put("emailReceivedDate",  System.currentTimeMillis());								
					mailJson.put("emailSubject", "QA Automation Competitor testing");
					mailJson.put("zgid",zgid);
					mailJson.put("senderEmailId",senderEmail);			
					String timeZone = "Asia/Kolkata"; //no i18n
					mailJson.put("featureParams",new JSONArray().put(new JSONObject().put("feature", "ActivityExtraction").put("params", new JSONObject().put("timeZone", timeZone)))); //no i18n	   					
					  
					JSONArray featuresListJson = new JSONArray();	
		            featuresListJson.put("CompetitorExtraction");			
					
					JSONObject reqBody = new JSONObject();
					reqBody.put("features", featuresListJson);
					reqBody.put("inputs", new JSONArray().put(mailJson));			
											
				  	String iscsignature = com.adventnet.iam.security.SecurityUtil.sign();
					String targetURL = (new StringBuilder("https://").append(RebrandLinkUtil.getRebrandKeys("ZIAURL")).append("/crm/zia/text/emailextraction/v2/predict").append("?iscsignature=").append(iscsignature)).toString(); //No I18N
					
//					LOGGER.log(Level.INFO, " QA automation invokeCompetitorExtractionEmail reset config reqBody {0}  targetURL {1} ", new Object[] {reqBody.toString(), targetURL});
					
					RemoteHTTPRequestBuilder builder = RemoteHTTPRequest.builder(targetURL);
					
					builder.setJSONRequestBody(reqBody);
					builder.setConnectionTimeOut(15000);
					
					boolean isCompetitorExtractionSuccess = false;
					String competitorResponse = "";
					RemoteHTTPResponse remoteResponse = builder.build().executePOST();			
					if(remoteResponse!=null) 
					{
						JSONObject resObj = remoteResponse.toJSONObject();
//						LOGGER.log(Level.INFO, "QA automation invokeCompetitorExtractionEmail reset config resObj {0} ", new Object[] {resObj.toString()});
						if(resObj!=null && !resObj.isEmpty() && resObj.getInt("statusCode") == 200) 
						{
							int resLength = resObj.getJSONArray("response").getJSONObject(0).getJSONArray("response").length(); //NO I18N
							JSONArray resArray = resObj.getJSONArray("response").getJSONObject(0).getJSONArray("response"); //NO I18N
							for(int index=0;index<resLength;index++) {
								if(resArray.getJSONObject(index).getString("feature").equals("CompetitorExtraction")) {
									int resStatusCode = resArray.getJSONObject(index).getInt("statusCode"); //NO I18N
									if(resStatusCode==200) {
										isCompetitorExtractionSuccess = true;
									}
								}
							}
							if(isCompetitorExtractionSuccess) {
								resultObj.put("response", "Competitor Extraction success");
							}
							else {
								resultObj.put("response", "Competitor Extraction failure");
							}				
							return resultObj;
						}	
					}	
					resultObj.put("response", "Competitor Extraction failure");
					return resultObj;
			  }catch(Exception e) {
				  LOGGER.log(Level.INFO, "QA automation invokeCompetitorExtractionEmail reset config  Exception while try to make DI team API {0}", new Object[] {e});//No I18N
				  resultObj.put("response", "Competitor Extraction failure due to di call failure");
				  return resultObj;
			  }
		  
		}
		
