		/**
		 * Remove published charts
		 * @return
		 * @throws JSONException
		 */
		public JSONObject removePublishedCharts() throws JSONException {
			try {
				Persistence persistence = PersistenceCacheUtil.getPurePersistenceLiteHandle();
				List<Long> chartIds = new ArrayList<>();
				List<Long> componentIds = new ArrayList<>();
				SelectQuery cvQuery = new SelectQueryImpl(Table.getTable(CRMCUSTOMVIEW.TABLE));
		    	cvQuery.addSelectColumn(Column.getColumn(null,PMDConstants.ASTERISK));
		    	
				Criteria cvCriteria = new Criteria(Column.getColumn(CRMCUSTOMVIEW.TABLE, CRMCUSTOMVIEW.FEATURETYPE), 4, QueryConstants.EQUAL);
				cvCriteria = cvCriteria.and(com.zoho.crm.customviews.util.CustomViewUtil.getCVUserDefinedCriteria());
				cvQuery.setCriteria(cvCriteria);
				DOIterator cvDOIter = new DOIterator(persistence, cvQuery, 1000);
				while(cvDOIter.hasNext())
				{
					DataObject cvDo = cvDOIter.next();
					Iterator<Row> cvRows = cvDo.getRows(CRMCUSTOMVIEW.TABLE);
					while(cvRows.hasNext())
					{
						Row row = cvRows.next();
						chartIds.add((Long)row.get(CRMCUSTOMVIEW.CVID));
						JSONObject configJson = new JSONObject(row.get(CRMCUSTOMVIEW.CONFIGPROPS).toString());
						if(configJson.has("chart_id"))
						{
							componentIds.add(configJson.getLong("chart_id"));//No I18N
						}
					}
				}
				
				
				SelectQuery dashboardQuery = new SelectQueryImpl(Table.getTable(CRMDASHBOARD.TABLE));
				dashboardQuery.addSelectColumn(Column.getColumn(null,PMDConstants.ASTERISK));
				Criteria dashboardCrt = new Criteria(Column.getColumn(CRMDASHBOARD.TABLE, CRMDASHBOARD.FEATURETYPE), new String[]{"CUSTOM_VIEW"}, QueryConstants.IN);
				dashboardCrt = dashboardCrt.and(new Criteria(Column.getColumn(CRMDASHBOARD.TABLE, CRMDASHBOARD.CATEGORY), Integer.valueOf(5), QueryConstants.EQUAL));
				dashboardQuery.setCriteria(dashboardCrt);
				
				DOIterator dashboardDOIter = new DOIterator(persistence, dashboardQuery,100);
				Long cvDashboardId = null;
				while(dashboardDOIter.hasNext())
				{
					DataObject dashboardDO = dashboardDOIter.next();
						if(!dashboardDO.isEmpty())
						{
							Row dashboardRow = dashboardDO.getFirstRow(CRMDASHBOARD.TABLE);
							if(dashboardRow != null)
							{
								cvDashboardId = (Long)dashboardRow.get(CRMDASHBOARD.DASHBOARDID);
							}
						}
				}
				ComponentsServiceImpl componentService = ComponentsServiceImpl.getInstance();
				componentService.deleteComponents(cvDashboardId, componentIds, UserUtil.getCurrentUserId());
				
				cvCriteria = new Criteria(Column.getColumn(CRMCONFIG.TABLE, CRMCONFIG.CONFIGID), chartIds.toArray(), QueryConstants.IN);
				CommonDBUtil.deleteWithLimit(CRMCONFIG.TABLE,cvCriteria,persistence,1000);
				
				resultObj.put("response", "Published charts deleted  successfully for all users"); //No I18N
			}catch (Exception e) {
				status = false;
				resultObj.put("response", e.toString());
				LOGGER.log(Level.WARNING, "Exception occured while deleting  Published charts :",e); // no i18n
			}
			resultObj.put("status", status);
			return resultObj;
		}
		
		/**
		 * 
		 * @return
		 * @throws Exception
		 */
		public static JSONObject deleteChartFromCustomView() throws Exception
		{
			JSONObject result =new JSONObject();
			boolean status = true;
			try {
				Persistence persistence = PersistenceCacheUtil.getPurePersistenceLiteHandle();
				List<Long> chartIds = new ArrayList<>();
				List<Long> componentIds = new ArrayList<>();
				SelectQuery cvQuery = new SelectQueryImpl(Table.getTable(CRMCUSTOMVIEW.TABLE));
		    	cvQuery.addSelectColumn(Column.getColumn(null,PMDConstants.ASTERISK));
		    	
				Criteria cvCriteria = new Criteria(Column.getColumn(CRMCUSTOMVIEW.TABLE, CRMCUSTOMVIEW.FEATURETYPE), 4, QueryConstants.EQUAL);
				cvQuery.setCriteria(cvCriteria);
				DOIterator cvDOIter = new DOIterator(persistence, cvQuery, 1000);
				while(cvDOIter.hasNext())
				{
					DataObject cvDo = cvDOIter.next();
					Iterator<Row> cvRows = cvDo.getRows(CRMCUSTOMVIEW.TABLE);
					while(cvRows.hasNext())
					{
						Row row = cvRows.next();
						chartIds.add((Long)row.get(CRMCUSTOMVIEW.CVID));
						JSONObject configJson = new JSONObject(row.get(CRMCUSTOMVIEW.CONFIGPROPS).toString());
						if(configJson.has("chart_id"))
						{
							componentIds.add(configJson.getLong("chart_id"));//No I18N
						}
					}
				}
				if(chartIds.size() > 0) {
					cvCriteria = new Criteria(Column.getColumn(CRMCONFIG.TABLE, CRMCONFIG.CONFIGID), chartIds.toArray(), QueryConstants.IN);
					CommonDBUtil.deleteWithLimit(CRMCONFIG.TABLE,cvCriteria,persistence,1000);	
				}
				
				if(componentIds.size() > 0) {
					ComponentsServiceImpl componentService = ComponentsServiceImpl.getInstance();
					componentService.deleteAnalyticalComponents(componentIds, null, true);	
				}
				
				result.put("response", "CustomView charts deleted successfully"); //No i18N
			}catch(Exception e) {
				status = false;
				result.put("response", e.toString());
				LOGGER.log(Level.WARNING, "Exception occured while deleting CustomView charts :",e); // no i18n
			}
			result.put("status", status);
			return result;
		}

        /**
         * for enable or disabe chart cache flow
         */
		public  JSONObject resetChartCache() throws Exception
		{
			try {
				   Boolean keyStatus = Boolean.parseBoolean(request.getParameter("keyStatus"));
				   String[] keys = new String[]{"CHART_VIEW_CACHE","MATERIALIZED_VIEW_STATIC","MATERIALIZED_VIEW"};//No I18n
				    if(keyStatus == null) {
				 	   status = false;
				 	   resultObj.put("response", "keyName or keyStatus should not be empty");
				 	   return resultObj;
				    }
				   LOGGER.log(Level.INFO, "Chart cache reset configuration started with status as " + keyStatus);
				   for(String key : keys)
				   {
					   CrmKeyValueUtil.insertOrUpdateCrmKeyValueByKeyName(key, keyStatus.toString(), true);
				   }
				   
				   } catch(Exception e) {
					   status = false;
					   resultObj.put("response", e.toString());
					   LOGGER.log(Level.WARNING, "Exception occured in Enable Chart cache Flow", e);
				   }
			   return resultObj;
		}
	     
        /** @return
	     * @throws Exception
	     */
	    public static JSONObject resetJobToAddedState() throws Exception {
	    	List<Long> jobids = new ArrayList<Long>();
	        try {
	        	LOGGER.log(Level.SEVERE, "resetJobToAddedState method is invoked");
	            Persistence persistence = PersistenceCacheUtil.getPersistenceLiteHandle();
	            SelectQuery select_query = new SelectQueryImpl(Table.getTable(CRMBULKJOB.TABLE));
	            select_query.addSelectColumn(Column.getColumn(CRMBULKJOB.TABLE, CRMBULKJOB.JOBID));
	            select_query.addSelectColumn(Column.getColumn(CRMBULKJOB.TABLE, CRMBULKJOB.STATE));
	            Criteria criteria = new Criteria(new Column(CRMBULKJOB.TABLE, CRMBULKJOB.STATE),
	            		new Object[] {State.COMPLETE}, QueryConstants.IN);
	            Long current_time_in_millis = System.currentTimeMillis();
	            Long week = current_time_in_millis - (7*24*60*60*1000);
	            criteria=criteria.and(new Criteria(new Column(CRMBULKJOB.TABLE,CRMBULKJOB.CREATEDTIME), week, QueryConstants.GREATER_EQUAL));
	            select_query.setCriteria(criteria);
	            DOIterator doiter = new DOIterator(persistence,select_query, 500);
	            while(doiter.hasNext()) {
	            	DataObject dobj = doiter.next();
	            	if(dobj!=null && !dobj.isEmpty()) {
	            		Iterator<Row> rows = dobj.getRows(CRMBULKJOB.TABLE);
	            		while(rows.hasNext()) {
	            			Row row = rows.next();
	            			Long jobid = (Long) row.get(CRMBULKJOB.JOBID);
	            			jobids.add(jobid);
	            			row.set(CRMBULKJOB.STATE, State.START);
	            			dobj.updateRow(row);
	            		}
	            	}
	            	persistence.update(dobj);            	
	            }
	        }
	        catch(Exception ex) {
	        	LOGGER.log(Level.SEVERE, "Problem while deleting queued bulk jobs", ex);
	        }
			JSONObject jobList =new JSONObject();
			jobList.put("jobid_list",jobids);
	        return jobList;
	    }
	     
	     /**
	     * @return
	     * @throws Exception
	     */
	    public static JSONObject resetJobToQueuedState() throws Exception {
	     	List<Long> jobids = new ArrayList<Long>();
	         try {
	         	LOGGER.log(Level.SEVERE, "resetJobToQueuedState method is invoked");
	             Persistence persistence = PersistenceCacheUtil.getPersistenceLiteHandle();
	             SelectQuery select_query = new SelectQueryImpl(Table.getTable(CRMBULKJOB.TABLE));
	             select_query.addSelectColumn(Column.getColumn(CRMBULKJOB.TABLE, CRMBULKJOB.JOBID));
	             select_query.addSelectColumn(Column.getColumn(CRMBULKJOB.TABLE, CRMBULKJOB.STATE));
	             Criteria criteria = new Criteria(new Column(CRMBULKJOB.TABLE, CRMBULKJOB.STATE),
	             		new Object[] {State.START}, QueryConstants.IN);
	             Long current_time_in_millis = System.currentTimeMillis();
	             Long week = current_time_in_millis - (7*24*60*60*1000);
	             criteria=criteria.and(new Criteria(new Column(CRMBULKJOB.TABLE,CRMBULKJOB.CREATEDTIME), week, QueryConstants.GREATER_EQUAL));
	             select_query.setCriteria(criteria);
	             DOIterator doiter = new DOIterator(persistence,select_query, 500);
	             while(doiter.hasNext()) {
	             	DataObject dobj = doiter.next();
	             	if(dobj!=null && !dobj.isEmpty()) {
	             		Iterator<Row> rows = dobj.getRows(CRMBULKJOB.TABLE);
	             		while(rows.hasNext()) {
	             			Row row = rows.next();
	             			Long jobid = (Long) row.get(CRMBULKJOB.JOBID);
	             			jobids.add(jobid);
	             			row.set(CRMBULKJOB.STATE, State.QUEUED);
	             			dobj.updateRow(row);
	             		}
	             	}
	             	persistence.update(dobj);            	
	             }
	         }
	         catch(Exception ex) {
	         	LOGGER.log(Level.SEVERE, "Problem while deleting queued bulk jobs", ex);
	         }
	 		JSONObject jobList =new JSONObject();
	 		jobList.put("jobid_list",jobids);
	         return jobList;
	     }
	     
	     /**
	     * @return
	     * @throws Exception
	     */
	    public static JSONObject resetJobToFailureState() throws Exception {
	      	List<Long> jobids = new ArrayList<Long>();
	          try {
	          	LOGGER.log(Level.SEVERE, "resetJobToFailureState method is invoked");
	              Persistence persistence = PersistenceCacheUtil.getPersistenceLiteHandle();
	              SelectQuery select_query = new SelectQueryImpl(Table.getTable(CRMBULKJOB.TABLE));
	              select_query.addSelectColumn(Column.getColumn(CRMBULKJOB.TABLE, CRMBULKJOB.JOBID));
	              select_query.addSelectColumn(Column.getColumn(CRMBULKJOB.TABLE, CRMBULKJOB.STATE));
	              Criteria criteria = new Criteria(new Column(CRMBULKJOB.TABLE, CRMBULKJOB.STATE),
	              		new Object[] {State.START}, QueryConstants.IN);
	              Long current_time_in_millis = System.currentTimeMillis();
	              Long week = current_time_in_millis - (7*24*60*60*1000);
	              criteria=criteria.and(new Criteria(new Column(CRMBULKJOB.TABLE,CRMBULKJOB.CREATEDTIME), week, QueryConstants.GREATER_EQUAL));
	              select_query.setCriteria(criteria);
	              DOIterator doiter = new DOIterator(persistence,select_query, 500);
	              while(doiter.hasNext()) {
	              	DataObject dobj = doiter.next();
	              	if(dobj!=null && !dobj.isEmpty()) {
	              		Iterator<Row> rows = dobj.getRows(CRMBULKJOB.TABLE);
	              		while(rows.hasNext()) {
	              			Row row = rows.next();
	              			Long jobid = (Long) row.get(CRMBULKJOB.JOBID);
	              			jobids.add(jobid);
	              			row.set(CRMBULKJOB.STATE, State.FAILURE);
	              			dobj.updateRow(row);
	              		}
	              	}
	              	persistence.update(dobj);            	
	              }
	          }
	          catch(Exception ex) {
	          	LOGGER.log(Level.SEVERE, "Problem while deleting queued bulk jobs", ex);
	          }
	   		JSONObject jobList =new JSONObject();
	   		jobList.put("jobid_list",jobids);
	        return jobList;
	      }
	    
