        /**
		 * method to reset teamspace
		 * this will delete all teamspaces and repopulate default teamspace
		 * @return
		 * @throws Exception
		 */
		public JSONObject resetTeamSpace() throws Exception
		{
			Persistence per = PersistenceCacheUtil.getPurePersistenceLiteHandle();
			try {
				SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMTEAMSPACE.TABLE));
				sq.addSelectColumn(Column.getColumn(CRMTEAMSPACE.TABLE, CRMTEAMSPACE.TEAMSPACEID));
				
				DataObject teamspaceDo = new WritableDataObject();
				
				DOIterator doItr = new DOIterator(per, sq, 1000);
				while(doItr.hasNext())
				{
					teamspaceDo.merge(doItr.next());
				}
				
				
				if(!teamspaceDo.isEmpty())
				{
					List<Long> teamspaceIds = new ArrayList<Long>();
					Iterator<Row> teamspaceItr = teamspaceDo.getRows(CRMTEAMSPACE.TABLE);
					while(teamspaceItr.hasNext())
					{
						Row teamspaceRow = teamspaceItr.next();
						if(teamspaceRow != null)
						{
							teamspaceIds.add((Long) teamspaceRow.get(CRMTEAMSPACE.TEAMSPACEID));
						}
					}
					
					if(!teamspaceIds.isEmpty())
					{
						CommonDBUtil.deleteWithLimit(CRMTEAMSPACEUSERREL.TABLE, new Criteria(Column.getColumn(CRMTEAMSPACEUSERREL.TABLE, CRMTEAMSPACEUSERREL.TEAMSPACEID), teamspaceIds.toArray(), QueryConstants.IN), per, 1000);
						CommonDBUtil.deleteWithLimit(CRMTEAMSPACETABREL.TABLE, new Criteria(Column.getColumn(CRMTEAMSPACETABREL.TABLE, CRMTEAMSPACETABREL.TEAMSPACEID), teamspaceIds.toArray(), QueryConstants.IN), per, 1000);
						CommonDBUtil.deleteWithLimit(CRMCONFIG.TABLE, new Criteria(Column.getColumn(CRMCONFIG.TABLE, CRMCONFIG.CONFIGID), teamspaceIds.toArray(), QueryConstants.IN), per, 1000);
					}
				}
				
				TeamSpaceHelper.populateDefaultTeamSpace(userId);
				Row defaultTeamspaceRow = TeamSpaceHelper.getDefaultTeamSpaceRow();
				if(defaultTeamspaceRow != null)
				{
					Long defaultTeamspaceId = (Long) defaultTeamspaceRow.get(CRMTEAMSPACE.TEAMSPACEID);
					List<Long> teamspaceIdsList = new ArrayList<Long>();
					teamspaceIdsList.add(defaultTeamspaceId);
                    ResetApprovalProcess.addApprovalsTabToTeamSpace(zgId,userId,currentUserLocale);
					LOGGER.log(Level.INFO, "populating teamspace user rel entries started for org {0} teamspace id {1}", new Object[] {zgId}); //no i18n
					TeamSpaceHelper.updateTeamSpaceUserRelEntries(teamspaceIdsList, null);
					LOGGER.log(Level.INFO, "populating teamspace user rel entries started for org {0} teamspace id {1}", new Object[] {zgId}); //no i18n
				}
				//deleting existing scheduled jobs entry
				Criteria cr1 = new Criteria(Column.getColumn(CRMSCHEDULEDJOBS.TABLE, CRMSCHEDULEDJOBS.ACTION), "TEAMSPACEUSERMAPPING",QueryConstants.EQUAL);
				cr1 = cr1.and(new Criteria(Column.getColumn(CRMSCHEDULEDJOBS.TABLE, CRMSCHEDULEDJOBS.STATUS),ScheduledJobDetails.Status.QUEUED.getValue(),QueryConstants.EQUAL));
				CrmScheduledJobsUtil.deleteJob(cr1);
				status = true;
				resultObj.put("response", "reset teamspace successful"); //no 18n
				LOGGER.log(Level.INFO, "reset teamspace successfull for org {0}", new Object[] {zgId}); //no i18n
				
			}catch(Exception e)
			{
				status = false;
				resultObj.put("response", "Exception occured in reset teamspace"); //noi18n
				LOGGER.log(Level.INFO, "Exception occurred in reset Teamspace for org {0} - Exception : {1}", new Object[] {zgId, e}); //no i18n
			}
			// To reset Manage_Teamspace permission in profile
			Long standardProfileId = ProfileUtil.getStandardProfileId();
			Long permissionId = null;
			try{
				CrmCache cObj = new CrmDefaultCache(CoreCachedTables.ALLPERMISSIONS);
				DataObject permissionObj = cObj.getDataObject();
				Criteria cr = new Criteria(Column.getColumn(CRMPERMISSIONS.TABLE, CRMPERMISSIONS.NAME), CrmSecurityConstants.IMPLIED_ROLE_MANAGE_TEAMSPACE, QueryConstants.EQUAL);
				Iterator<Row> iter = permissionObj.getRows(CRMPERMISSIONS.TABLE,cr);
				while(iter.hasNext())
				{
					Row row = iter.next();
					permissionId = (Long) row.get(CRMPERMISSIONS.PERMISSIONID);
					UpdateQuery s = new UpdateQueryImpl(CRMPROFILEPERMISSIONS.TABLE);
					Criteria c = new Criteria(new Column(CRMPROFILEPERMISSIONS.TABLE, CRMPROFILEPERMISSIONS.PROFILEID), standardProfileId, QueryConstants.EQUAL); 
					c = c.and(new Criteria(new Column(CRMPROFILEPERMISSIONS.TABLE, CRMPROFILEPERMISSIONS.PERMISSIONID), permissionId, QueryConstants.EQUAL));
					s.setCriteria(c);
					s.setUpdateColumn(CRMPROFILEPERMISSIONS.PRESENCE, 0);
					LOGGER.log(Level.INFO, "Reset Manage_Teamspace Permission (Permission id {0}) For Standard Profile (Profile id {1}) Started --> Zgid : {2})",new Object[] {standardProfileId, permissionId, zgId}); //no i18n
					per.update(s);
					LOGGER.log(Level.INFO, "Reset Manage_Teamspace Permission (Permission id {0}) For Standard Profile (Profile id {1}) Ended --> Zgid : {2}", new Object[] {standardProfileId, permissionId, zgId}); //no i18n
				}
			}
			catch(Exception e)
			{
				status = false;
				resultObj.put("response", "Exception occured in reset Manage_Teamspace permission"); //noi18n
				LOGGER.log(Level.INFO, "Exception occurred in reset Manage_Teamspace permission (Permission id {0}) for Standard profile (Profile id {1}) for org {2} - Exception : {3}", new Object[] {standardProfileId, permissionId, zgId, e}); //no i18n
			}
			resultObj.put("status", status);
			return resultObj;
		}
		
