		public JSONObject resetNextGenUIOnboardingForAdmins()
		{
			try
			{
				LOGGER.log(Level.INFO, "reset NextGenUI Onboarding for Admins started for org {0}", new Object[] {zgId}); //no i18n
				
				Persistence per = PersistenceCacheUtil.getPurePersistenceLiteHandle();
				
				// delete CrmUserStateConfig Entries
				// left panel configuration 
				Criteria leftPanelConfig = new Criteria(Column.getColumn(CRMUSERSTATECONFIG.TABLE, CRMUSERSTATECONFIG.FEATUREID), CrmUserStateConfigType.NEWUI_ONBOARDING.getType() , QueryConstants.EQUAL);
				leftPanelConfig = leftPanelConfig.and(new Criteria(Column.getColumn(CRMUSERSTATECONFIG.TABLE, CRMUSERSTATECONFIG.USERID), userId , QueryConstants.EQUAL));
				CommonDBUtil.deleteWithLimit(CRMUSERSTATECONFIG.TABLE, leftPanelConfig, per, 5);
				
				// userViewPreference
				Criteria userViewPreference = new Criteria(Column.getColumn(CRMUSERSTATECONFIG.TABLE, CRMUSERSTATECONFIG.FEATUREID), CrmUserStateConfigType.TABS_LEFT_PANEL.getType() , QueryConstants.EQUAL);
				userViewPreference = userViewPreference.and(new Criteria(Column.getColumn(CRMUSERSTATECONFIG.TABLE, CRMUSERSTATECONFIG.USERID), userId , QueryConstants.EQUAL));
				CommonDBUtil.deleteWithLimit(CRMUSERSTATECONFIG.TABLE, userViewPreference, per, 5);
				
				// delete newui_onboarding data from redis
				String redisKey = zgId+"_NEWUI_ONBOARDING_"+userId;//no i18n
				CrmCacheUtil.deleteKeyInRedis(redisKey);
				
				// delete userViewPreference data in redis
				redisKey = zgId+"_LEFT_PANEL_PREFERENCE_"+userId;//no i18n
				CrmCacheUtil.deleteKeyInRedis(redisKey);
				
				// delete onboarding rescheduled date from CrmKeyValue
				String keyName = "NEXTGENUI_ONBOARDING_RESCHEDULED_DATE";//No i18N
				CrmKeyValueUtil.deleteCrmKeyValueByKeyName(keyName, false);
				
				// add NEXTGENUI_ONBOARDING_ADMINS
				CoreFeatureUtil.addOrUpdateTrailOrg(Feature.NEXTGENUI_ONBOARDING_ADMINS.getName(), zgId.toString(), null, CoreFeatureUtil.Type.ORG.name(), true, null);
				
				// remove NEXTGENUI_ONBOARDING
				String[] featureNames=new String[]{Feature.NEXTGENUI_ONBOARDING.getName(), Feature.NEXTGENUI_ENABLED.getName()};
				DataObject trialFeaturesDo = CrmTrialFeature.getTrialFeatureDOForGivenFeatureList(Arrays.asList(featureNames));
				Iterator<Row> featureItr = trialFeaturesDo.getRows(CRMTRIALFEATURES.TABLE);
				Set<Long> featureIds = new HashSet<Long>();
				while(featureItr.hasNext())
				{
					Row featureRow = featureItr.next();
					featureIds.add((Long) featureRow.get(CRMTRIALFEATURES.FEATUREID));
				}
				CrmTrialFeature.deleteReleasedFeatureEntries(featureIds);
				
				
				status = true;
				resultObj.put("response", "reset NextGenUI Onboarding for Admins successful"); //no 18n

				LOGGER.log(Level.INFO, "reset NextGenUI Onboarding for Admins successfull for org {0}", new Object[] {zgId}); //no i18n
			}
			catch(Exception e)
			{
				status = false;
				resultObj.put("response", "Exception occured in reset LeftPanelPreference data in DB"); //noi18n

				LOGGER.log(Level.INFO, "Exception occurred in reset NextGenUI Onboarding for Admins for org {0} - Exception : {1}", new Object[] {zgId, e}); //no i18n
			}
			resultObj.put("status", status);
			return resultObj;
		}
		
