		/**
		 * @author madhavaraman.vr-17028
		 * Stale mail account cleanup
		 */
		public JSONObject staleMail360Account_cleanup()throws Exception {
			try {
				List<String> activeEmailConfig = new ArrayList<>();
				List<String> activeAcccountConfig = new ArrayList<>();
				DataObject crmMailUserConfigCachedDO = (DataObject) ZMailConfigUtil.getCrmMailUserConfigCachedDO(zgId);
				Criteria criteria = new Criteria(Column.getColumn(CRMMAILUSERCONFIG.TABLE, CRMMAILUSERCONFIG.IS_ACTIVE), Boolean.TRUE, QueryConstants.EQUAL);
				criteria = criteria.and(Column.getColumn(CRMMAILUSERCONFIG.TABLE, CRMMAILUSERCONFIG.ZM_ACCOUNTID), null, QueryConstants.NOT_EQUAL);
				criteria = criteria.and(Column.getColumn(CRMMAILUSERCONFIG.TABLE, CRMMAILUSERCONFIG.MAIL_TYPE), 1, QueryConstants.EQUAL);
				Iterator<Row> activeConfigRows = crmMailUserConfigCachedDO.getRows(CRMMAILUSERCONFIG.TABLE, criteria);
				
				while(activeConfigRows.hasNext())
				{
					Row activeConfigRow = activeConfigRows.next();
					String email = activeConfigRow.get(CRMMAILUSERCONFIG.EMAIL) != null ? activeConfigRow.get(CRMMAILUSERCONFIG.EMAIL).toString() : null;
					activeEmailConfig.add(email);
					String accountID = activeConfigRow.get(CRMMAILUSERCONFIG.ZM_ACCOUNTID) != null ? activeConfigRow.get(CRMMAILUSERCONFIG.ZM_ACCOUNTID).toString() : null;
					activeAcccountConfig.add(accountID);
				}

				com.zoho.crm.mailagent.Authentication authObj = MailAPIRouting.getAuthObject( zgId , zuId , true , null ,true );
	    		
	    		if(authObj.isOrgOauth()) {
	    			authObj.setAddSoType(true);
	    			authObj.setSoType(String.valueOf(IAMServiceOrg.getType()));	
	    			authObj.setZid(zgId.toString());
	    		}
              
                MailAPI mailAPI = MailAPI.getInstance(authObj);
                JSONObject accountJSON = mailAPI.getAccount();
                if(accountJSON.has("data") && accountJSON.getJSONObject("data").has("account_details")) {
				JSONArray accountDetails = accountJSON.getJSONObject("data").getJSONArray("account_details");//No I18N
                LOGGER.log(Level.INFO,"MAIL360 ACCOUNTS  :::::::: {0}",new Object[]{response});
                for (int i = 0; i < accountDetails.length(); i++) {
                    JSONObject account = accountDetails.getJSONObject(i);
                    String mail360Email = account.getString("email");
                    String accountID = account.getString("id");
                    if ((!activeAcccountConfig.contains(accountID) || !activeEmailConfig.contains(mail360Email)) && !mail360Email.contains("orgmailbox")) {
                        LOGGER.log(Level.INFO,"INACTIVE ACCOUNT ID  :::::::: {0}  MAIL360 EMAIL ::: {1} ::",new Object[]{accountID,mail360Email});
                        resultObj.put("MAIL360 Email ",mail360Email);
                        resultObj.put("Account ID ",accountID);
                        if(accountID != null)
                        {
                        	status = mailAPI.deleteAccount(accountID);
                        } 
                    }
                }
			}
		}
			catch(Exception e) {
				status = false;
				resultObj.put("response", e.toString());
				LOGGER.log(Level.INFO,":::Exception occurred while deleting stale mailbox account {0}", e);
			}
			resultObj.put("status", status);
			return resultObj;
		}


		
