		/**
		 * Removes Undeleted Team Pipeline from DB
		 * 
		 * @author vikash.k - 13379
		 * @throws Exception
		 */
		public JSONObject removeUndeletedTeamPipeline() throws Exception {
			JSONObject resultObj = new JSONObject();
			Constants constants = new Constants();
			
			try {
				Long zgidLong = OrgUtil.getCurrentZGID();
				Long userIdLong = UserUtil.getCurrentUserId();
				if (zgidLong == null) { 
					throw new Exception("ZGID is null");
				}
				
				if (userIdLong == null) {
					throw new Exception("USERID is null");
				}
				
				String zgid = zgidLong.toString();
				String module = CrmModuleConstants.POTENTIALS;
				Long tabId = TabUtil.getTabIdByName(module);
				Criteria hiddenLayoutsCr = new Criteria(Column.getColumn(CRMPAGELAYOUT.TABLE, CRMPAGELAYOUT.TABID), tabId, QueryConstants.EQUAL);
				hiddenLayoutsCr = hiddenLayoutsCr.and(new Criteria(Column.getColumn(CRMPAGELAYOUT.TABLE, CRMPAGELAYOUT.STATUS), CoreLayoutConstants.STATUS.HIDDEN.getValue(), QueryConstants.EQUAL));
				hiddenLayoutsCr = hiddenLayoutsCr.and(new Criteria(Column.getColumn(CRMPAGELAYOUT.TABLE, CRMPAGELAYOUT.GENERATEDTYPE), CoreLayoutConstants.GENERATEDTYPE.CUSTOM.getValue(), QueryConstants.EQUAL));
				
				DataObject hiddenLayoutDo = PageLayoutUtil.getAllLayoutNonCachedDOBasedOnCriteria(hiddenLayoutsCr, zgid);
				Iterator<Row> hiddenLayoutRows = hiddenLayoutDo.getRows(CRMPAGELAYOUT.TABLE);
				List<Long> deletedHiddenLayouts = new ArrayList<Long>();
				
				while (hiddenLayoutRows.hasNext()) {
					Row hiddenLayoutRow = hiddenLayoutRows.next();		
					Long hiddenlayoutId = (Long) hiddenLayoutRow.get(CRMPAGELAYOUT.LAYOUTID);
					if (hiddenlayoutId != null ) {
						BiginPipelineUtil.schedulePipelineDelete(hiddenlayoutId, userIdLong, tabId, module);
						deletedHiddenLayouts.add(hiddenlayoutId);
					}
				}
				
				LOGGER.log(Level.INFO, "Removed undeleted team pipelines :: {0}", new Object[] {deletedHiddenLayouts.toString()});	
				resultObj.put(constants.status_small, constants.response_ins.success);
                resultObj.put(constants.details, "Hidden Team Pipelines deleted"); //no i18n
                resultObj.put(constants.response, String.format("These Hidden Team Pipelines %s have been deleted", deletedHiddenLayouts.toString())); //no i18n
				
			} catch (Exception ex) {
				LOGGER.log(Level.INFO, "Exception while removing undeleted team pipelines :: {0}", ex);	
				resultObj.put(constants.status_small, constants.error);
                resultObj.put(constants.details, ex.getMessage());
                resultObj.put(constants.response, ex.getMessage());
			}
			
			return resultObj;
		}

        /**
         * To remove unused sub pipeline in bigin
         * 
         * @author vikash-15756
         * @return JSONObject
         */
        public JSONObject removeUnusedSubPipelinesInBigin() {
            JSONObject resultObj = new JSONObject();
            Constants constants = new Constants();

            try {
                if (!LicenseUtil.isBiginAccount()) {
                    LOGGER.log(Level.INFO, "Exception occured :: Not a Bigin Account"); // NO I18N
                    resultObj.put(constants.status_small, constants.error);
                    resultObj.put(constants.response, "Operable only on a Bigin Account"); // NO I18N
                    return resultObj;
                }
                
                Long zgidLong = OrgUtil.getCurrentZGID();
				String zgid = zgidLong != null ? zgidLong.toString() : null;
                BiginPipelineUtil.handleUnusedSubPipelines(zgid);

                resultObj.put(constants.status_small, constants.response_ins.success);
                resultObj.put(constants.response, "Unused Subpipelines Removed"); // NO I18N
            } catch (Exception ex) {
                LOGGER.log(Level.INFO, "Exception occured :: ", ex); // NO I18N
                resultObj.put(constants.status_small, constants.error);
                resultObj.put(constants.response, ex.getMessage());
            }

            return resultObj;
        }
		
		
