								PageLayoutUtil.addModeField(writableDo, modeField.getTabId(), (Long) eventSecRows[i].get(CRMSECTION.SECTIONID), 1, modeField.getFieldId(), ++eventSecSeqs[i], modeField.getLayoutId(), (Long) eventSecRows[i].get(CRMSECTION.SECTION_ID), null, null);
