    public JSONObject updateCurrencyLocale() {
    	try {
    		String currencyISOCode = request.getParameter("currencyISOCode");
    		CurrencyUtil.updateCountryCode(currencyISOCode,false);
    		resultObj.put("response", "Currency code updated - ISOCODE ::: " + currencyISOCode);
    	}catch(Exception e) {
    		resultObj.put("response", e.toString());
    	}
    	return resultObj;
    }

    /**
     * @return This method remove or add Activities module for the org
     * @throws Exception
     */    
    public JSONObject removeAddActivitiesTab() throws Exception {
       String add = (String)request.getParameter("tab");
       try {
               if(add.equals("add") && EntityMetaDataUtil.isActivityFieldMigrationDone() && ActivityUtil.isActivityTabHidden()) {
                       TabUtil.updateTabPresense(CrmModuleConstants.ACTIVITIES, 1L);
                       status = true;
               }else if(add.equals("remove") && EntityMetaDataUtil.isActivityFieldMigrationDone() && !ActivityUtil.isActivityTabHidden()) {
                       TabUtil.updateTabPresense(CrmModuleConstants.ACTIVITIES, -1L);
                       status = true;
               }else {
                       resultObj.put("response", "Invalid module");
                       status = false;
               }
       }catch(Exception e) {
               status = false;
            resultObj.put("response", e.toString());
               LOGGER.log(Level.WARNING, "Exception occurred while deleting custom domain mappings ",e);
       }
       resultObj.put("status", status);
        return resultObj;
    }
    
    /**
     * @return This method to disable custom email preference for the org
     * @throws Exception
     */    
    public JSONObject disableCustomEmailPreference() throws Exception {
    	try {
    		new EASKeyValueUtil(zgId).insertOrUpdateKey("CUSTOMEMAIL_CUSTOMSHARING_ENABLED", "false", zgId, -1, -1);	//NO I18N
    		status = true;
    		resultObj.put("response", "Custom email fields preference disabled");
    	}catch(Exception e) {
    		status = false;
    		resultObj.put("response", e.toString());
    		LOGGER.log(Level.WARNING, "Exception occurred while disabling custom email fields preference ",e);
    	}
    	resultObj.put("status", status);
    	return resultObj;
    }
    
