		//To get Last 25 bulk write ids
				/**
				 * 
				 * @return
				 * @throws Exception
				 */
				public JSONObject getBulkWriteIdsForAutomation() throws Exception {
					JSONArray bulkwriteIdsArray = new JSONArray();
					try {
						SelectQuery sq1=new SelectQueryImpl(Table.getTable(CRMDATAMIGRATION.TABLE));
						sq1.addSelectColumn(Column.getColumn(CRMDATAMIGRATION.TABLE, CRMDATAMIGRATION.MIGRATIONID));
					    Criteria cr1 = new Criteria( Column.getColumn( CRMDATAMIGRATION.TABLE, CRMDATAMIGRATION.OPERATION ),null, QueryConstants.NOT_EQUAL);
					    cr1 = cr1.or(new Criteria(Column.getColumn(CRMDATAMIGRATION.TABLE, CRMDATAMIGRATION.IMPORTTYPE), ImportType.BulkWrite.getCode(), QueryConstants.EQUAL));
					    sq1.setCriteria(cr1);
					    sq1.addSortColumn(new SortColumn(CRMDATAMIGRATION.TABLE, CRMDATAMIGRATION.MIGRATIONID, false));
					    sq1.setRange(new Range(0,25));
					    DataObject dataObj = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(sq1);
					    Iterator<Row> rows = dataObj.getRows(CRMDATAMIGRATION.TABLE);
					    while (rows != null && rows.hasNext()) {
							Row dataRow = rows.next();
							JSONObject idObj = new JSONObject();
							idObj.put("id",String.valueOf(dataRow.get(CRMDATAMIGRATION.MIGRATIONID)));
							bulkwriteIdsArray.put(idObj);
						}
					    resultObj.put("response",bulkwriteIdsArray.toString()); 
		                	    resultObj.put("status", status);
					    
					}
					catch(Exception e)
					{
						LOGGER.log(Level.INFO, "Exception while fetching bulkwrite Ids for automation :: {0}", e);
						status = false;
						resultObj.put("response",e.toString()); 
		                resultObj.put("status", status);
					}
					
					
					return resultObj;
					
				}
				
				//To get Last 25 migration ids
				/**
				 * 
				 * @return
				 * @throws Exception
				 */
				public JSONObject getMigrationIdsForAutomation() throws Exception {
					JSONArray migIdsArray = new JSONArray();
					try {
						SelectQuery sq1=new SelectQueryImpl(Table.getTable(CRMDATAMIGRATION.TABLE));
						sq1.addSelectColumn(Column.getColumn(CRMDATAMIGRATION.TABLE, CRMDATAMIGRATION.MIGRATIONID));
					    Criteria cr1 = new Criteria( Column.getColumn( CRMDATAMIGRATION.TABLE, CRMDATAMIGRATION.OPERATION ),null, QueryConstants.EQUAL);
					    cr1 = cr1.or(new Criteria(Column.getColumn(CRMDATAMIGRATION.TABLE, CRMDATAMIGRATION.IMPORTTYPE), ImportType.Migration.getCode(), QueryConstants.EQUAL));
					    sq1.setCriteria(cr1);
					    sq1.addSortColumn(new SortColumn(CRMDATAMIGRATION.TABLE, CRMDATAMIGRATION.MIGRATIONID, false));
					    sq1.setRange(new Range(0,25));
					    DataObject dataObj = PersistenceCacheUtil.getPurePersistenceLiteHandle().get(sq1);
					    Iterator<Row> rows = dataObj.getRows(CRMDATAMIGRATION.TABLE);
					    while (rows != null && rows.hasNext()) {
							Row dataRow = rows.next();
							JSONObject idObj = new JSONObject();
							idObj.put("id",String.valueOf(dataRow.get(CRMDATAMIGRATION.MIGRATIONID)));
							migIdsArray.put(idObj);
							
						}
		                resultObj.put("response",migIdsArray.toString()); 
		                resultObj.put("status", status);
					}
					catch(Exception e)
					{
						LOGGER.log(Level.INFO, "Exception while fetching migration Ids for automation :: {0}", e);
			    		status = false;
			    		resultObj.put("response",e.toString()); 
		                resultObj.put("status", status);
					}
					
					return resultObj;
						
				}
				
				
				
