    /**
     * To remove user associated to private profiles for the default Team Module 
     * @return
     */
    public JSONObject resetTeamModuleUserAssociations() {
    	JSONObject response = new JSONObject();
    	boolean status = false;
    	try {
        	Long tabId =  Long.valueOf(request.getParameter("tabId")); //no i18n
    		if(tabId != null && TabUtil.isPrivateModule(tabId)) 
    		{
	          	LOGGER.log(Level.SEVERE, "resetTeamModuleUserAssociations method is invoked for tabId - {0}",new Object[] {tabId});
				List<Long> parentChildTeamModuleIds = new ArrayList<Long>();
				parentChildTeamModuleIds.add(tabId);
				PrivateModuleUsersUtil.addChildModule(tabId, parentChildTeamModuleIds);
				Criteria tabCri = new Criteria(Column.getColumn(CRMUSERTABREL.TABLE, CRMUSERTABREL.TABID), parentChildTeamModuleIds.toArray(), QueryConstants.IN);
				// Team module created super admin row excluded
//				Criteria adminCri = new Criteria(Column.getColumn(CRMUSERTABREL.TABLE, CRMUSERTABREL.PROFILEID), ProfileUtil.getPrivateAdminProfileId(),QueryConstants.EQUAL);
//				adminCri = adminCri.and( new Criteria(Column.getColumn(CRMUSERTABREL.TABLE, CRMUSERTABREL.USERID),primaryUserId,QueryConstants.EQUAL));
//				CommonDBUtil.deleteWithLimit(CRMUSERTABREL.TABLE,tabCri.and(adminCri.negate()),PersistenceCacheUtil.getPurePersistenceLiteHandle(),500);
					
				CommonDBUtil.deleteWithLimit(CRMUSERTABREL.TABLE,tabCri,PersistenceCacheUtil.getPurePersistenceLiteHandle(),500);

				Map<Long,Long> superAdminUserVsPrivateAdminMap = new HashMap<Long, Long>();
				superAdminUserVsPrivateAdminMap.put(OrgUtil.getUserIdOfPrimaryContact(), ProfileUtil.getPrivateAdminProfileId());
				TabUtil.addUserTabRelation(superAdminUserVsPrivateAdminMap, parentChildTeamModuleIds);
				status = true;

    		}
    	}
    	catch (Exception e) {
			LOGGER.log(Level.INFO, "Exception occured while resetting TeamModuleUserAssociations {0}", e);
			status = false;
			response.put("status", "Failed");
			return response;
		}
		
		response.put("status", String.valueOf(status));
		return response;
    }
    
    /**
     * To reset TeamModule private profile permissions 
     * @return
     */
    public JSONObject resetTeamModulePermissions() {
    	JSONObject response = new JSONObject();
    	boolean status = false;
    	try {
          	LOGGER.log(Level.SEVERE, "resetTeamModulePermissions method is invoked");
          	List<Long> privateProfileIds = ProfileUtil.getPrivateProfileIds();
          	if(privateProfileIds != null)
          	{
	          	Set<String> teammodules = TabUtil.getPrivateModulesSet();
	        	DataObject permissionObj = ProfileUtil.getCachedPermissionsDO();
	        	for(String module : teammodules) 
	        	{
		        	List<Long> permissionIds = new ArrayList<Long>();
		        	List<Long> notesAttachPermissionIds = new ArrayList<Long>();
	
		        	Criteria cr = new Criteria(Column.getColumn(CRMPERMISSIONS.TABLE, CRMPERMISSIONS.SETYPE),module,QueryConstants.EQUAL);
		        	cr = cr.and(new Criteria(Column.getColumn(CRMPERMISSIONS.TABLE, CRMPERMISSIONS.ISCUSTOMIZABLE),Boolean.TRUE,QueryConstants.EQUAL));
		        	cr = cr.and(new Criteria(Column.getColumn(CRMPERMISSIONS.TABLE, CRMPERMISSIONS.PRESENCE),1,QueryConstants.EQUAL));
		        	DataObject permissionTabDo = permissionObj.getDataObject(CRMPERMISSIONS.TABLE,cr);
		        	
		        	Criteria notesAttachCri = new Criteria(Column.getColumn(CRMPERMISSIONS.TABLE, CRMPERMISSIONS.PERMISSION_GROUP_NAME),new String[] {CrmModuleConstants.NOTES,CrmModuleConstants.ATTACHMENTS},QueryConstants.IN);
		        	DataObject notesAttachPermissionTabDO = permissionTabDo.getDataObject(CRMPERMISSIONS.TABLE,notesAttachCri);
		        			
					addProfilePermissions( permissionTabDo, permissionIds);
					addProfilePermissions( notesAttachPermissionTabDO,notesAttachPermissionIds);
	
					for(Long profileId : privateProfileIds) {
						if(ProfileUtil.isRequesterPrivateProfile(profileId)) {
							ProfileUtil.enableProfilePermissions(profileId, notesAttachPermissionIds);
						}
						else {
							ProfileUtil.enableProfilePermissions(profileId, permissionIds);
						}
					}
	          	}
          	}
    	}
    	catch (Exception e) {
			LOGGER.log(Level.INFO, "Exception occured while resetting TeamModulePermissions {0}", e);
			status = false;
			response.put("status", "Failed");
			return response;
		}
		
		status = true;
		response.put("status", String.valueOf(status));
		return response;
    }
    
    /*
     * Method to reset all the users in all team module and associate the current user as private admin
     * 
     * */
    
    public JSONObject resetAllTeamModuleUserAssociation() throws Exception {
    	JSONObject response = new JSONObject();
    	LOGGER.log(Level.INFO, "resetAllTeamModuleUserAssociation is invoked");
    	
    	try {
    		//Fetching all the Team Module Tab IDs
    		Set<Long> tabIds = TabUtil.getPrivateTabIdsList();    		
    		Long privateAdminProfileId = ProfileUtil.getPrivateAdminProfileId();
    		Long userId = UserUtil.getCurrentUserId();
        	
        	for(Long tabId : tabIds) {    		
        		if(!ProfileUtil.getCurrentOrPrivateProfileIdByTabId(tabId, userId).equals(privateAdminProfileId))
        		{              	
        			List<Long> parentChildTeamModuleIds = new ArrayList<Long>();
        			parentChildTeamModuleIds.add(tabId);
        			//The child modules including Subform and picklist tracking modules are added to the list
        			PrivateModuleUsersUtil.addChildModule(tabId, parentChildTeamModuleIds);
        			Criteria tabCri = new Criteria(Column.getColumn(CRMUSERTABREL.TABLE, CRMUSERTABREL.TABID), parentChildTeamModuleIds.toArray(), QueryConstants.IN);
        				
        			//Deleting the entries from DB
        			CommonDBUtil.deleteWithLimit(CRMUSERTABREL.TABLE,tabCri,PersistenceCacheUtil.getPurePersistenceLiteHandle(),500);
        			
        			//All the entries removed tabs are associated with the current user in usertabrel with private admin profile id
        			Map<Long,Long> currentUserVsPrivateAdminMap = new HashMap<Long, Long>();
					currentUserVsPrivateAdminMap.put(userId, ProfileUtil.getPrivateAdminProfileId());
    				TabUtil.addUserTabRelation(currentUserVsPrivateAdminMap, parentChildTeamModuleIds);    				
        		}
        	}
        	response.put("status", String.valueOf(true));
    	}catch(Exception exp) {
    		LOGGER.log(Level.INFO, "Exception occured while resetAllTeamModuleUserAssociation {0}", exp);
    		response.put("status", String.valueOf(false));
    	}

    	return response;
    }

    /**
     *
     * @return
     * @throws Exception
     */
    public JSONObject enableFreeTeamUsers() throws Exception {
    	JSONObject response = new JSONObject();
    	LOGGER.log(Level.INFO, "enableFreeTeamUsers is invoked");
    	String zgid= request.getParameter("zgid");
    	try {
    		Criteria cr = new Criteria(Column.getColumn(CRMFEATURELIMITS.TABLE, CRMFEATURELIMITS.FEATURENAME ),"FREE_TEAM_LITE_USERS" , QueryConstants.EQUAL);
    		DataObject featureLimitDo = FeatureEditionUtil.getFeatureLimitsDo(cr);
    		if (!featureLimitDo.isEmpty()) {
    			HashMap<String, Object> updateDetails = new HashMap<String, Object>();
                updateDetails.put(CRMFEATURELIMITS.ISFEATUREAVAILABLE,true);
    			FeatureEditionUtil.updateFeatureLimitsEntries(updateDetails, cr, false,null,false);
                TeamUserFreeCountPopulationMigration mig = new TeamUserFreeCountPopulationMigration();
                mig.scheduleExpiryScheduler(zgid);
    		}

    		response.put("status", String.valueOf(true));
    	}catch(Exception exp) {
    		LOGGER.log(Level.INFO, "Exception occured while enableFreeTeamUsers {0}", exp);
    		response.put("status", String.valueOf(false));
    	}

    	return response;
    }

/**
     *
     * @return
     * @throws Exception
     */
    public JSONObject enableFreeTeamUsersLink() throws Exception {
    	JSONObject response = new JSONObject();
    	LOGGER.log(Level.INFO, "enableFreeTeamUsersLink is invoked");

    	try {
    		Criteria cr = new Criteria(Column.getColumn(CRMFEATURELIMITS.TABLE, CRMFEATURELIMITS.FEATURENAME ),"FREE_TEAM_LITE_USERS" , QueryConstants.EQUAL);
    		DataObject featureLimitDo = FeatureEditionUtil.getFeatureLimitsDo(cr);
    		if (!featureLimitDo.isEmpty()) {
    			HashMap<String, Object> updateDetails = new HashMap<String, Object>();
    			Row featureRow = featureLimitDo.getRow(CRMFEATURELIMITS.TABLE);
                Timestamp dateTime =  (Timestamp)featureRow.get(CRMFEATURELIMITS.UPDATEDTIME);
                if(dateTime != null) {
                    Timestamp userDateTime= DateTimeUtils.getPresentUserDate(dateTime, UserUtil.getCurrentUserTimeZone());
                    LocalDate date = userDateTime.toLocalDateTime().toLocalDate().minusDays(60);
                    Timestamp ts = Timestamp.valueOf(date.atStartOfDay());
                    updateDetails.put(CRMFEATURELIMITS.UPDATEDTIME, ts);
                    FeatureEditionUtil.updateFeatureLimitsEntries(updateDetails, cr, false,null,false);
                }

    		}
    		LOGGER.log(Level.INFO, "enableFreeTeamUsersLink executed");

    		response.put("status", String.valueOf(true));
    	}catch(Exception exp) {
    		LOGGER.log(Level.INFO, "Exception occured while enableFreeTeamUsersLink {0}", exp);
    		response.put("status", String.valueOf(false));
    	}

    	return response;
    }

    /**
     *
     * @return
     * @throws Exception
     */
    public JSONObject resetFreeTeamUsers() throws Exception {
    	JSONObject response = new JSONObject();
    	LOGGER.log(Level.INFO, "resetFreeTeamUsers is invoked");
    	try {
    		Criteria expirySchCr = new Criteria(Column.getColumn(CRMSCHEDULEDJOBS.TABLE, CRMSCHEDULEDJOBS.ACTION),"FREE_TEAMUSER_DEACTIVATE",QueryConstants.EQUAL);
            Criteria userCr = new Criteria(Column.getColumn(CRMSCHEDULEDJOBS.TABLE, CRMSCHEDULEDJOBS.TYPE),CoreModuleConstants.USERS,QueryConstants.EQUAL);

    		DataObject jobDo = CrmScheduledJobsUtil.getCrmScheduledDataObject(expirySchCr.and(userCr));
    		if(!jobDo.isEmpty()) 
    		{   
    			Row jobRow = jobDo.getRow(CRMSCHEDULEDJOBS.TABLE);
    			Long jobId = (Long) jobRow.get(CRMSCHEDULEDJOBS.JOBID);
    			Job jobInfo = ZohoCRMSchedule.getJobObjectById(jobId, CoreScheduleConstants.ONETIME_LOW_PROCESS);
    			if(jobInfo != null){
        			jobId = jobInfo.getJobID();
            		ZohoCRMSchedule.updateOneTimeJob(jobId, CoreScheduleConstants.ONETIME_LOW_PROCESS, true, new Timestamp(System.currentTimeMillis()));
                    LOGGER.log(Level.INFO, "resetFreeTeamUsers:::"+jobId+":::reschedule to time : "+new Timestamp(System.currentTimeMillis()));
                    resultObj.put("response", "resetFreeTeamUsers schedule time updated to current time");
        		}

    		}
    		LOGGER.log(Level.INFO, "resetFreeTeamUsers executed");

    		response.put("status", String.valueOf(true));
    	}catch(Exception exp) {
    		LOGGER.log(Level.INFO, "Exception occured while resetFreeTeamUsers {0}", exp);
    		response.put("status", String.valueOf(false));
    	}

    	return response;
    }


