    /**
     * adds Export Permission for the report modules.
     * @return
     * @throws Exception
     */
    public JSONObject addExportPermissionForReports() throws Exception 
    {
    	try
    	{
	    	Permission permission = (Permission) ModelUtil.getInstanceForORM(Permission.class);
			permission.setName("Crm_Implied_Export_Reports"); // No I18N
			permission.setDescription("crm.permission.export.reports"); // No I18N
			permission.setSetype("Reports"); // No I18N
			permission.setPermission_group_name("Export"); // No I18N
			permission.setPresence(1);
			permission.setSource(1);
			permission.setIscustomizable(true);
			
			List<String> parentPermissionNames = new ArrayList<>();
		    parentPermissionNames.add("Crm_Implied_View_Reports"); // No I18N
			
			List <Object[]> profilesList = ProfileUtil.getProfilesList(null,true,true,false);
			Long lightprofileId = CrmLiteUser.getLiteProfile();
			List<PermissionProfile> permissionProfileList = new ArrayList<PermissionProfile>();
			Iterator<Object[]> proIter = profilesList.iterator();
			while(proIter.hasNext())
			{
				 Object profileObj[]= proIter.next();
				 Long profileId= (Long)profileObj[0];
				 
				 PermissionProfile permissionProfile = (PermissionProfile) ModelUtil.getInstanceForORM(PermissionProfile.class);
				 permissionProfile.setProfileId(profileId);
				 permissionProfile.setIscustomizable(Boolean.TRUE);
				 if(lightprofileId != null && profileId == lightprofileId) {				 
					 permissionProfile.setPresence(PermissionPresenceType.DISABLE.getValue());
				 }	else {
					 permissionProfile.setPresence(PermissionPresenceType.ENABLE.getValue());
				 } 
				 permissionProfileList.add(permissionProfile);		
			}
			permission.setPermissionProfile(permissionProfileList);
			permission.setParentPermissionNames(parentPermissionNames);
			List<Permission> permissions = new ArrayList<>();
			permissions.add(permission);
			new PermissionServiceImpl().addPermissions(permissions);
			status = true;
			resultObj.put("response", "Export Permission is added successfully for reports module"); 	
    	}
    	catch(Exception e)
    	{
    		status = false;
            resultObj.put("response", e.toString());
    		LOGGER.log(Level.WARNING, "Exception occurred while adding export permission for report modules ",e);
    	}
    	resultObj.put("status", status);
    	return resultObj;
    }

    /**
     * enables the recordid for the existing scheduled reports
     */
    public JSONObject enableRecordIdForScheduledReports()
    {
    	try
    	{
	    	SelectQueryImpl sq = new SelectQueryImpl(Table.getTable(CRMREPSCHEDULE.TABLE));
			sq.addSelectColumn(Column.getColumn(CRMREPSCHEDULE.TABLE, CRMREPSCHEDULE.INSTANCE_ID));
			sq.addSelectColumn(Column.getColumn(CRMREPSCHEDULE.TABLE, CRMREPSCHEDULE.CONFIGURATIONS));
            sq.addSelectColumn(Column.getColumn(CRMREPSCHEDULE.TABLE, CRMREPSCHEDULE.FILE_TYPE));
			Persistence per = PersistenceCacheUtil.getPurePersistenceLiteHandle();
			DOIterator doIter = new DOIterator(per, sq, 1000, true);
			DataObject scheduledReportsDO = per.constructDataObject();
			while(doIter!=null && doIter.hasNext()) {
				scheduledReportsDO = doIter.next();
	            if(scheduledReportsDO != null && !scheduledReportsDO.isEmpty()) {
					@SuppressWarnings("unchecked")
					Iterator<Row> rowIter = scheduledReportsDO.getRows(CRMREPSCHEDULE.TABLE);
	                while(rowIter.hasNext()) 
	                { 
	                    Row fieldRow = rowIter.next();
                        if(3 != (Integer)fieldRow.get(CRMREPSCHEDULE.FILE_TYPE))
                        {
	                        fieldRow.set(CRMREPSCHEDULE.CONFIGURATIONS, ScheduledReportsConfigurations.INCLUDE_ID.getValue());
                        }
                        scheduledReportsDO.updateRow(fieldRow);
	                }
	        	    per.update(scheduledReportsDO);
	            }
			}
			status = true;
			resultObj.put("response", "Reocrd Id is enabled for scheduled reports!!!!"); 
    	}
    	catch(Exception e)
    	{
    		status = false;
            resultObj.put("response", e.toString());
    		LOGGER.log(Level.WARNING, "Exception occurred while enabling Record Id scheduled reports",e);
    	}
    	resultObj.put("status", status);
    	return resultObj;
    }
    
    /**
     * adds daily limit for the detailed report export
     * @return
     * @throws Exception
     */
    public JSONObject addDailyLimitEntryForDetailedReport() throws Exception
    {
    	LOGGER.log(Level.INFO, "Addition of Daily Limit for detailed report export started");
    	try
    	{
    		int limit = "U".equals(LicenseUtil.getLicenseType()) ? 300 : 200;//no i18n
    		for(int i = 0; i < limit; i++)
    		{
    			String orgTimeZone = OrgUtil.getOrgTimeZone();
    			ZoneId zoneId = orgTimeZone == null ? ZoneId.of(UserUtil.getCurrentUserTimeZone()) : ZoneId.of(orgTimeZone);
    			Long startTime = ZonedDateTime.now(zoneId).toLocalDate().atStartOfDay(zoneId).withZoneSameInstant(ZoneId.systemDefault()).toInstant().toEpochMilli(); 
    			ScheduledJobDetails jobDetails = new ScheduledJobDetails();
    			jobDetails.setSeType(CrmModuleConstants.REPORTS);
    			jobDetails.setActionType(ReportsUseCase.REPORT_EXPORT.getType());
    			jobDetails.setStartTime(startTime);
    			jobDetails.setStatus(Status.FINISHED);
    			CrmScheduledJobsUtil.addAndPersistJobDetails(jobDetails, null);
    		}
			status = true;
			resultObj.put("response", "Added Daily Limit For Detailed Report successfully"); 
    	}
    	catch(Exception e)
    	{
    		status = false;
            resultObj.put("response", e.toString());
    		LOGGER.log(Level.WARNING, "Exception occurred while adding Daily Limit For Detailed Report ",e);
    	}
    	LOGGER.log(Level.INFO, "Addition of Daily Limit for detailed report export completed");
    	resultObj.put("status", status);
    	return resultObj;
    }
    
    /**
     * revert the daily limit for the detailed report
     * @return
     * @throws Exception
     */
    public JSONObject revertDailyLimitForDetailedReport() throws Exception
    {
    	try
    	{
    		LOGGER.log(Level.INFO, "Revert of Daily Limit for detailed report export started");
	    	Persistence persistence = PersistenceCacheUtil.getPersistenceLiteHandle();
	    	String orgTimeZone = OrgUtil.getOrgTimeZone();
	    	DeleteQuery deleteQuery = new DeleteQueryImpl(CRMSCHEDULEDJOBS.TABLE);
	    	ZoneId zoneId = orgTimeZone == null ? ZoneId.of(UserUtil.getCurrentUserTimeZone()) : ZoneId.of(orgTimeZone);
	    	Criteria crt = new Criteria(Column.getColumn(CRMSCHEDULEDJOBS.TABLE, CRMSCHEDULEDJOBS.STARTTIME), ZonedDateTime.now(zoneId).toLocalDate().atStartOfDay(zoneId).withZoneSameInstant(ZoneId.systemDefault()).toInstant().toEpochMilli(), QueryConstants.GREATER_EQUAL);
			crt = crt.and(new Criteria(Column.getColumn(CRMSCHEDULEDJOBS.TABLE, CRMSCHEDULEDJOBS.STARTTIME), ZonedDateTime.now(zoneId).toLocalDate().atTime(23, 59, 59).atZone(zoneId).withZoneSameInstant(ZoneId.systemDefault()).toInstant().toEpochMilli(), QueryConstants.LESS_EQUAL));
			crt = crt.and(new Criteria(Column.getColumn(CRMSCHEDULEDJOBS.TABLE, CRMSCHEDULEDJOBS.ACTION),ReportsUseCase.REPORT_EXPORT.getType(), QueryConstants.EQUAL));
			deleteQuery.setCriteria(crt);
			deleteQuery.setLimit("U".equals(LicenseUtil.getLicenseType()) ? 300 : 200);//no i18n
	        persistence.delete(deleteQuery);
	        status = true;
			resultObj.put("response", "Reverted Daily Limit For Detailed Report successfully"); 
    	}
    	catch(Exception e)
    	{
    		status = false;
            resultObj.put("response", e.toString());
    		LOGGER.log(Level.WARNING, "Exception occurred while reverting Daily Limit For Detailed Report ",e);
    	}
    	LOGGER.log(Level.INFO, "Revert of Daily Limit for detailed report export started");
    	resultObj.put("status", status);
    	return resultObj;
    }
    
