    /**
	 * Method to enable or disable pages feature
	 * @return
	 * @throws Exception
	 */
	public JSONObject pagesFeature() throws Exception
	{
		status = false;
		String mode = request.getParameter("status");

		if(!mode.isEmpty())
		{
			if(!mode.equals("disable") && !mode.equals("enable"))
			{
				resultObj.put("response", "Improper value sent for status param");
			}
			else
			{
				try
				{
					PagePermissionUtils.enableDisablePagesFeature(request.getParameter("zgid"), mode);	//No I18N
					resultObj.put("response", "Action performed successfully.");
					status = true;
				}
				catch (Exception e)
				{
					LOGGER.log(Level.INFO, "Exception occurred while enabling or disabling the pages feature", e);
				}
			}
		}
		else
		{
			resultObj.put("response", "mandatory param status not sent.");
			return resultObj;
		}

		resultObj.put("status", status);
		return resultObj;
	}

