	/**
	 *
	 * @return
	 * @throws Exception
	 */
	public JSONObject pagesFeaureRedisFlush() throws Exception
	{
		status = false;
		String position = request.getParameter("position");
		String moduleId = request.getParameter("module_id");
		String layoutId = request.getParameter("layout");

		if(request.getParameter("user_ids") == null)
		{
			resultObj.put("response", "mandatory param user_ids not sent.");
		}
		else
		{
			String userIds[] = (request.getParameter("user_ids")).split("//,");
			try
			{
				if(userIds.length == 0)
				{
					resultObj.put("response", "mandatory param user_ids not sent.");
				}
				else if(position == null)
				{
					resultObj.put("response", "mandatory param position not sent.");
				}
				else if(!position.equalsIgnoreCase("record_list_view") && !position.equalsIgnoreCase("record_detail_view"))
				{
					resultObj.put("response", "Invalid value sent for position param. Valid values - record_list_view or record_detail_view");
				}
				else
				{
					if(moduleId == null && layoutId == null)
					{
						LastAccessedPagesAPI.deleteEntryInRedisCache(position, null, userIds);
						resultObj.put("response", position+" flush is cleared");
						status = true;
					}
					else if(moduleId != null && layoutId != null)
					{
						LastAccessedPagesAPI.deleteEntryInRedisCache(position, Long.parseLong(moduleId), Long.parseLong(layoutId), userIds);
						resultObj.put("response", position + " - " +moduleId+" - "+layoutId+ " flush is cleared");
						status = true;
					}
					else if(moduleId != null)
					{
						LastAccessedPagesAPI.deleteEntryInRedisCache(position, Long.parseLong(moduleId), userIds);
						resultObj.put("response", position + " - " +moduleId+ " flush is cleared");
						status = true;
					}
					else if(moduleId == null)
					{
						resultObj.put("response", "expected param moduleId not sent.");
					}
				}
			}
			catch (Exception e)
			{
				LOGGER.log(Level.INFO, "Exception occurred while enabling or disabling the pages feature", e);
			}
		}

		resultObj.put("status", status);
		return resultObj;
	}

