    /**
     * @return This method replace submodules api with Activities module new field api for the Activities smart filter changes
     * @throws Exception
     */    
    public JSONObject resetActivitiesSmartFilterMIgration() throws Exception {
       String isRevert = (String)request.getParameter("revert");
       String filterId = (String)request.getParameter("filterId");
		try {
			ActivitiesSmartFilterMigrator txnBean = (ActivitiesSmartFilterMigrator) ScopedAccess.getInstance(ActivitiesSmartFilterMigrator.class, null, TransactionType.REQUIRED);
			if (isRevert.equals("true") && EntityMetaDataUtil.isActivityFieldMigrationDone()) {
				txnBean.revertMigraiton();
				List<Long> sandboxZgids = SandboxConfigUtil.getAllActiveSandboxZgids();
				if (!OrgUtil.isSandboxAccount() && !sandboxZgids.isEmpty()) {
					for (Long sandboxZgid : sandboxZgids) {
						ActivitiesSmartFilterMigrator sandboxTxnBean = (ActivitiesSmartFilterMigrator) ScopedAccess.getInstance(ActivitiesSmartFilterMigrator.class, sandboxZgid.toString(), TransactionType.REQUIRED);
						sandboxTxnBean.revertMigraiton();
					}
				}
				status = true;
			} else if (isRevert.equals("false") && EntityMetaDataUtil.isActivityFieldMigrationDone()) {
				txnBean.doMigration(Long.valueOf(filterId));

				List<Long> sandboxZgids = SandboxConfigUtil.getAllActiveSandboxZgids();
				if (!OrgUtil.isSandboxAccount() && !sandboxZgids.isEmpty() && filterId == null) {
					for (Long sandboxZgid : sandboxZgids) {
						ActivitiesSmartFilterMigrator sandboxTxnBean = (ActivitiesSmartFilterMigrator) ScopedAccess.getInstance(ActivitiesSmartFilterMigrator.class, sandboxZgid.toString(), TransactionType.REQUIRED);
						sandboxTxnBean.doMigration(null);
					}					
				} 
				status = true;
			}
		} catch (Exception e) {
			status = false;
			resultObj.put("response", e.toString());
			LOGGER.log(Level.WARNING, "Exception occurred while reseting Activities smart filter configurations", e);
		}
       resultObj.put("status", status);
        return resultObj;
    }
    /**
     * @return
     * @throws Exception
     */
    public JSONObject resetEnableActivityDeprecation() throws Exception{

    	String isRevert = (String)request.getParameter("revert");    	
		ActivitiesModuleDepricationMigrator txnBean = (ActivitiesModuleDepricationMigrator) ScopedAccess.getInstance(ActivitiesModuleDepricationMigrator.class, null, TransactionType.REQUIRED);
        if(ActivityUtil.isActivityTabHidden() && isRevert.equals("true"))
		{
			try {
				LOGGER.log(Level.INFO, " resetEnableActivityDeprecation Revert Migration Started ====================>");
				txnBean.revertMigration();
				List<Long> sandboxZgids = SandboxConfigUtil.getAllActiveSandboxZgids();
				if (!OrgUtil.isSandboxAccount() && !sandboxZgids.isEmpty()) {
					for (Long sandboxZgid : sandboxZgids) {
						ActivitiesModuleDepricationMigrator sandboxTxnBean = (ActivitiesModuleDepricationMigrator) ScopedAccess.getInstance(ActivitiesModuleDepricationMigrator.class, sandboxZgid.toString(), TransactionType.REQUIRED);
						sandboxTxnBean.revertMigration();
					}
				}
				status = true;
				LOGGER.log(Level.INFO, " resetEnableActivityDeprecation Revert Migration end =========>");
			} catch (Exception ex) {
				status = false;
				resultObj.put("response", ex.toString());
				LOGGER.log(Level.SEVERE, " ACTDEP2:: Exception in resetEnableActivityDeprecation revert migration  ====================>", ex);
			}

		} else if (!ActivityUtil.isActivityTabHidden() && isRevert.equals("false")) {
			try {
				LOGGER.log(Level.INFO, " resetEnableActivityDeprecation Migration Started ====================>");
				DataObject ruleDo=txnBean.doMigration(null);
				List<Long> sandboxZgids = SandboxConfigUtil.getAllActiveSandboxZgids();
				if (!OrgUtil.isSandboxAccount() && !sandboxZgids.isEmpty()) {
					for (Long sandboxZgid : sandboxZgids) {
						ActivitiesModuleDepricationMigrator sandboxTxnBean = (ActivitiesModuleDepricationMigrator) ScopedAccess.getInstance(ActivitiesModuleDepricationMigrator.class, sandboxZgid.toString(), TransactionType.REQUIRED);
						sandboxTxnBean.doMigration(ruleDo);
					}
				}
				status = true;
				resultObj.put("response", "Activities module deprecation completed"); // no i18n
				LOGGER.log(Level.INFO, " resetEnableActivityDeprecation Migration end =========>");
			} catch (Exception ex) {
				LOGGER.log(Level.INFO, " Exception occured while reset the automation tool config ====================>",ex);
				status = false;
				resultObj.put("response", ex.toString());
			}
		} else {
			status = false;
			resultObj.put("response", "Activity deprecation not run, something went wrong OR provide mandatory inputs");
			LOGGER.log(Level.INFO, "Activity deprecation not run, something went wrong OR provide mandatory inputs isRever :: {0}",new Object[] {isRevert});
		}
		resultObj.put("status", status);
        return resultObj;
    }
    
    
    
    /***
     * @author aniket.soni
     * @return Status
     */
    public JSONObject RDATesting() throws Exception {
 
    	try {
    		Boolean create =request.getParameter("create") != null? Boolean.valueOf(request.getParameter("create").toString()):false;
    		if(create) {
    			JSONObject response = new JSONObject(CustomFunctionUtil.createCustomFunction("parent", "void", OrgUtil.getCurrentZGID(), IAMUtil.getCurrentTicket(), "this is a parent Function", IAMUtil.getRemoteUserIPAddress(IAMUtil.getCurrentRequest()), "Automation", "info \"helper\";", "parent", null, "parent")); //NO I18N
        		String Status = response.get("status").toString();
        		LOGGER.log(Level.INFO,Status);
            	resultObj.put("status", Status.equals("Success")?true:false);
                return resultObj;
    		}
    		Integer from = Integer.parseInt(request.getParameter("iteration")); //no i18n
    		Integer end =  from*50;
    		JSONObject parent = CustomFunctionUtil.getCustomFunctionInfoByAPIName("parent"); //no i18n
    		if(!parent.isEmpty()) {
    			for(int i=(from-1)*50; i < end; i++) {
    				String ChidResponse = new JSONObject( CustomFunctionUtil.createCustomFunction("Child"+i, "void", OrgUtil.getCurrentZGID(), IAMUtil.getCurrentTicket(), "this is a Child Function", IAMUtil.getRemoteUserIPAddress(IAMUtil.getCurrentRequest()), "Automation", "automation.parent();", "Child"+i, null, "Child"+i)).get("status").toString(); //NO I18N
    				LOGGER.log(Level.INFO,ChidResponse);
        		}    		
    			
    			String UpdateScript = "void automation.parent(){\n"; //NO I18N
    			for(int i = 1;i < end; i++) {
    				UpdateScript = UpdateScript	+ "automation.Child"+i+"();\n"; //NO I18N
    			}
    			UpdateScript = UpdateScript	+ "}";//NO I18N
        		JSONObject UpdateResp = new JSONObject(CustomFunctionUtil.updateDRECustomFunction(ticket, remoteAddress, OrgUtil.getCurrentZGID(), UpdateScript, null, parent.get("id").toString(), null,null, null,null)); //NO I18N
        		String UpdateStatus = UpdateResp.get("status").toString();
        		
        		if(!UpdateStatus.equals("Success")) {
        			status = false;
        		}else{
                    status = true;	
                }
    		}
    	}
    	catch(Exception e){
    		throw e;	
    	}
    	resultObj.put("status", status);
        return resultObj;
    }
    
