        	String campaignId = (String) request.getParameter("CampaignId");
        	Long entityId=Long.parseLong(campaignId);
        	String campMemberStatus=(String) request.getParameter("campaignMemberStatus");
        	String idList=(String)request.getParameter("idList");
        	Long id=Long.parseLong(idList);
