    /**
     * @author venkat-15070
     *
     */
    public JSONObject pinSubformFields() {
    	JSONObject resultObj = new JSONObject();
    	try {
        	Long parentLayoutId = Long.valueOf(request.getParameter("parentLayoutId").toString());
        	String sys_ref_name = (String) request.getParameter("sys_ref_name");
    		int index = 0;
    		Long tabId = TabUtil.getTabIdByAPIName(sys_ref_name);
    		DataObject fieldDO = FieldUtil.getCachedFieldDetailsForModule(tabId, null,null);
    		DataObject pageLayoutDO = PageLayoutUtil.getAllLayoutCachedDO(tabId);
    		Row pageLayoutRow = pageLayoutDO.getRow(CRMPAGELAYOUT.TABLE,new Criteria(Column.getColumn(CRMPAGELAYOUT.TABLE,CRMPAGELAYOUT.PARENT_LAYOUTID),parentLayoutId,QueryConstants.EQUAL));
    		Long layoutId = (Long) pageLayoutRow.get(CRMPAGELAYOUT.LAYOUTID);
    		Criteria cr = new Criteria(Column.getColumn(CRMMODEFIELD.TABLE,CRMMODEFIELD.LAYOUTID),layoutId,QueryConstants.EQUAL);
    		cr = cr.and(new Criteria(Column.getColumn(CRMMODEFIELD.TABLE,CRMMODEFIELD.MODE),10,QueryConstants.EQUAL));
    		cr = cr.and(new Criteria(Column.getColumn(CRMMODEFIELD.TABLE,CRMMODEFIELD.TABID),tabId,QueryConstants.EQUAL));

    		List<String> seq = new ArrayList<String>();
    		int limit = CrmSubformUtil.pinnedColumnLimit();
    		for(int i = 1; i <= limit+4; i++) {
    			seq.add(String.valueOf(i));
    		}
    		cr = cr.and(new Criteria(Column.getColumn(CRMMODEFIELD.TABLE,CRMMODEFIELD.FIELDSEQUENCE),seq.toArray(),QueryConstants.IN));

    		DataObject modeFieldDO = fieldDO.getDataObject(CRMMODEFIELD.TABLE, cr);

    		if(!modeFieldDO.isEmpty()) {
    			Row firstSeqRow = fieldDO.getRow(CRMMODEFIELD.TABLE,new Criteria(Column.getColumn(CRMMODEFIELD.TABLE,CRMMODEFIELD.FIELDSEQUENCE),1,QueryConstants.EQUAL));
    			Long fieldId = (Long) firstSeqRow.get(CRMMODEFIELD.FIELDID);
    			Row firstFieldRow = fieldDO.getRow(CRMFIELD.TABLE,new Criteria(Column.getColumn(CRMFIELD.TABLE,CRMFIELD.FIELDID),fieldId,QueryConstants.EQUAL));
    			String field_column_name = firstFieldRow.get(CRMFIELD.COLUMNNAME).toString();
    			boolean skipFirst = false;
    			if(field_column_name.equals("SERIAL_NUMBER")) {
    				skipFirst = true;
    			}
    			Iterator<Row> iter = modeFieldDO.getRows(CRMMODEFIELD.TABLE);
    			DataObject subform_firld_properties = (DataObject) CrmSubformUtil.getSubformFieldPropertiesDO(null, layoutId, null).clone();
    			int pinned_columns = 0;
    			while(iter.hasNext()) {
    				if(pinned_columns >= limit) {
    					break;
    				}
    				Row row = iter.next();
    				Long fieldId_ = (Long) row.get(CRMMODEFIELD.FIELDID);
    				if(sys_ref_name.equals("Quoted_Items")) {
    					Row firstFieldRow_ = fieldDO.getRow(CRMFIELD.TABLE,new Criteria(Column.getColumn(CRMFIELD.TABLE,CRMFIELD.FIELDID),fieldId_,QueryConstants.EQUAL));
        				String field_column_name_ = firstFieldRow_.get(CRMFIELD.COLUMNNAME).toString();
        				if(field_column_name_.equals("BOOKID") || field_column_name_.equals("ITEMDESCRIPTION")) {
        					continue;
        				}
    				}
    				if(skipFirst ? index != 0 : true) {
    					Criteria criteria = new Criteria(Column.getColumn(CRMSUBFORMFIELDPROPERTIES.TABLE,CRMSUBFORMFIELDPROPERTIES.FIELDID),fieldId_,QueryConstants.EQUAL);
    					criteria = criteria.and(new Criteria(Column.getColumn(CRMSUBFORMFIELDPROPERTIES.TABLE,CRMSUBFORMFIELDPROPERTIES.RELATED_COMPONENTID),layoutId,QueryConstants.EQUAL));
    					Row subform_field_property_row = subform_firld_properties.getRow(CRMSUBFORMFIELDPROPERTIES.TABLE,criteria);
    					if(subform_field_property_row == null) {
    						subform_field_property_row = new Row(CRMSUBFORMFIELDPROPERTIES.TABLE);
    						subform_field_property_row.set(CRMSUBFORMFIELDPROPERTIES.ISPINNED,true);
    						subform_field_property_row.set(CRMSUBFORMFIELDPROPERTIES.RELATED_COMPONENTID,layoutId);
    						subform_field_property_row.set(CRMSUBFORMFIELDPROPERTIES.FIELDID,fieldId_);
    						subform_firld_properties.addRow(subform_field_property_row);
    					}else {
    						subform_field_property_row.set(CRMSUBFORMFIELDPROPERTIES.ISPINNED,true);
    						subform_firld_properties.updateRow(subform_field_property_row);
    					}
    					pinned_columns++;
     				}
    				index++;
    			}
    			PersistenceCacheUtil.getPersistenceLiteHandle().update(subform_firld_properties);
    		}
    		resultObj.put("response", "Fields are pinned for "+sys_ref_name+" Subform"); //No I18N
    	}catch(Exception e) {
    		status = false;
			resultObj.put("response", e.toString());
			LOGGER.log(Level.WARNING, "Exception occured while pin a fields in subform :",e); // no i18n
    	}
    	return resultObj;
    }

    /**
     * @author venkat-15070
     *
     */
    public JSONObject upPinAllSubformFields() throws Exception {
    	JSONObject resultObj = new JSONObject();
    	try {
    		SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMSUBFORMFIELDPROPERTIES.TABLE));
        	sq.addSelectColumn(Column.getColumn(CRMSUBFORMFIELDPROPERTIES.TABLE,"*"));
        	Criteria cr = new Criteria(Column.getColumn(CRMSUBFORMFIELDPROPERTIES.TABLE,CRMSUBFORMFIELDPROPERTIES.ISPINNED),true,QueryConstants.EQUAL);
        	sq.setCriteria(cr);
        	sq.setRange(new Range(1,2000));
        	DataObject subformFieldPropertiesDO = PersistenceCacheUtil.getPersistenceLiteHandle().get(sq);
        	Iterator<Row> iter = subformFieldPropertiesDO.getRows(CRMSUBFORMFIELDPROPERTIES.TABLE);
        	while(iter.hasNext()) {
        		Row row = iter.next();
        		row.set(CRMSUBFORMFIELDPROPERTIES.ISPINNED,false);
        		subformFieldPropertiesDO.updateRow(row);
        	}
        	PersistenceCacheUtil.getPersistenceLiteHandle().update(subformFieldPropertiesDO);
        	resultObj.put("response", "All pinned fields are unpinned."); //No I18N
    	}catch(Exception e) {
			status = false;
    		resultObj.put("response", e.toString());
    		LOGGER.log(Level.WARNING, "Exception occured while unpin a fields :",e); // no i18n
    	}
    	return resultObj;
    }

