    /**
     *
     * @return
     */
	public JSONObject setLimitReachedForAutomationActions() {
		status = true;
		String res = "";
		try {

			String featureName = request.getParameter("featurename");
			if(featureName == null || featureName.isEmpty()) {
				status = false;
				res = "Required featureName!"; //NO I18N
			}else {
				HashMap<String, Object> limitDetails = WorkFlowActionsUtil.getCachedLimitDetailsForFeature(featureName, false);
				Integer maxPerDayCnt = (Integer) limitDetails.getOrDefault(CrmAutomationConstants.LIMIT_COUNT, 0) + 0;
				Integer extraCount = (Integer) limitDetails.getOrDefault(CrmAutomationConstants.EXTRA_COUNT, 0) + 0;
				long actualCnt = (maxPerDayCnt + extraCount + 1000);

				Map<String, String> featureRedisLimitValueMap = new HashMap<String, String>();
				featureRedisLimitValueMap.put(CrmAutomationConstants.ACTUAL_COUNT, String.valueOf(actualCnt));
				featureRedisLimitValueMap.put(CrmAutomationConstants.IS_LIMIT_EIGTHY_EXCEEDED, CrmAutomationConstants.TRUE);
				featureRedisLimitValueMap.put(CrmAutomationConstants.IS_LIMIT_EXCEEDED, CrmAutomationConstants.TRUE);
				featureRedisLimitValueMap.put(CrmAutomationConstants.UPDATED_TIME, String.valueOf(System.currentTimeMillis()));
				String featureRedisLimitKey = new StringBuilder().append(String.valueOf(OrgUtil.getCurrentZGID())).append("_").append(featureName).toString();
				CrmCacheUtil.putMapInRedis(featureRedisLimitKey, featureRedisLimitValueMap, null);
				FeatureEditionUtil.setFeatureLimitCount(featureName, (int) maxPerDayCnt, 0, (int) actualCnt, true);
				res = "Successfully setup email notification action limit reached"; //NO I18N
			}
		} catch (Exception e) {
			res = e.getMessage();
			status = false;
			LOGGER.log(Level.SEVERE, "Exception occured while getting set Email Notification Limit Reached: ", e); //NO I18N
		}
		resultObj.put("status", status);
		resultObj.put("response", res);
		return resultObj;
	}

