    /**
     * @return
     * @throws Exception
     */
	public JSONObject migrateSettingsTable() throws Exception{
		try
		{
			Long zgId = OrgUtil.getCurrentZGID();
			if(zgId != null) {
				Persistence pers = PersistenceCacheUtil.getPurePersistenceLiteHandle();				

				SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMSETTINGS.TABLE));
				sq.addSelectColumn( Column.getColumn(CRMSETTINGS.TABLE, PMDConstants.ASTERISK) );

				Criteria cr = new Criteria(Column.getColumn(CRMSETTINGS.TABLE, CRMSETTINGS.ELEMENT_LABEL), "Custom Email Preference", QueryConstants.EQUAL);
				cr = cr.and(new Criteria(Column.getColumn(CRMSETTINGS.TABLE, CRMSETTINGS.API_NAME), "system.customemailpreference", QueryConstants.EQUAL));

				sq.setCriteria(cr);				
				sq.setRange(new Range(0, 1));

				DataObject existingData = pers.get(sq);

				if(existingData == null || existingData.isEmpty())
				{	
					LOGGER.log(Level.INFO, "Settings row not available already hence trying to migrate");
					Criteria parentRowCr = new Criteria(Column.getColumn(CRMSETTINGS.TABLE, CRMSETTINGS.ELEMENT_LABEL), "Email", QueryConstants.EQUAL);
					parentRowCr = parentRowCr.and(new Criteria(Column.getColumn(CRMSETTINGS.TABLE, CRMSETTINGS.API_NAME), "system.email", QueryConstants.EQUAL));
					parentRowCr = parentRowCr.and(new Criteria(Column.getColumn(CRMSETTINGS.TABLE, CRMSETTINGS.PRESENCE), 1, QueryConstants.EQUAL));																								

					sq.setCriteria(parentRowCr);		
					sq.setRange(new Range(0, 1));

					DataObject dobj = pers.get(sq);

					if(!dobj.isEmpty() && dobj != null)
					{
						LOGGER.log(Level.INFO, "parent Settings row is available");
						Row parentRow = dobj.getRow(CRMSETTINGS.TABLE);

						Criteria sequenceCr = new Criteria(Column.getColumn(CRMSETTINGS.TABLE, CRMSETTINGS.PARENT_ID), parentRow.get(CRMSETTINGS.ELEMENT_ID), QueryConstants.EQUAL);
						SortColumn sortColumn = new SortColumn(CRMSETTINGS.TABLE, CRMSETTINGS.SEQUENCE, false);

						sq.setCriteria(sequenceCr);
						sq.addSortColumn(sortColumn);						

						dobj = pers.get(sq);

						if(!dobj.isEmpty() && dobj != null)
						{	
							LOGGER.log(Level.INFO, "parent Settings row after sorting");
							Row seqRow = dobj.getRow(CRMSETTINGS.TABLE);
							int seq = (int) seqRow.get(CRMSETTINGS.SEQUENCE);					

							Row newRow = new Row(CRMSETTINGS.TABLE);

							newRow.set(CRMSETTINGS.ELEMENT_TYPE, 3);			

							newRow.set(CRMSETTINGS.SEQUENCE, seq+1);

							newRow.set(CRMSETTINGS.PRESENCE, 1);

							newRow.set(CRMSETTINGS.GENERATED_SOURCE, 1);

							newRow.set(CRMSETTINGS.ELEMENT_ACTION, 1);

							newRow.set(CRMSETTINGS.ELEMENT_LABEL, "Custom Email Preference"); // no i18n
							newRow.set(CRMSETTINGS.API_NAME, "system.customemailpreference"); //no i18n

							newRow.set(CRMSETTINGS.PARENT_ID, parentRow.get(CRMSETTINGS.ELEMENT_ID));

							DataObject newRowDobj  = pers.constructDataObject();
							LOGGER.log(Level.INFO, "newRowDobj before row added:::: {0}",new Object[] {newRowDobj});
							newRowDobj.addRow(newRow);
							LOGGER.log(Level.INFO, "newRowDobj after row added:::: {0}",new Object[] {newRowDobj});
							DataObject newRowDobj2 = pers.add(newRowDobj);
							LOGGER.log(Level.INFO, "newRowDobj2 after insert:::: {0}",new Object[] {newRowDobj2});
							if(newRowDobj2.isEmpty()){
								LOGGER.log(Level.INFO, "newRowDobj2 is empty :::: {0}",new Object[] {System.currentTimeMillis()});
							}else {
								LOGGER.log(Level.INFO, "newRowDobj2 is not empty :::: {0}",new Object[] {System.currentTimeMillis()});
							}
						}else {
							LOGGER.log(Level.INFO, "Parent Settings row is not found for sequence");
						}
					}else {
						LOGGER.log(Level.INFO, "Parent Settings row is not found or has negative presence hence cannot migrate");
					}
				}else {
					LOGGER.log(Level.INFO, "Settings row already available for the org");
				}

				sq.setCriteria(cr);
				sq.setRange(new Range(0, 1));

				DataObject reCheckingData = pers.get(sq);
				if(reCheckingData == null || reCheckingData.isEmpty())
				{
					resultObj.put("status", false);
					resultObj.put("response", "Settings row is not available for the org");
					LOGGER.log(Level.INFO, "Settings row is not available for the org :::: {0}",new Object[] {System.currentTimeMillis()});
				}else {
					resultObj.put("status", true);
					resultObj.put("response", "Settings row is available for the org");
					LOGGER.log(Level.INFO, "Settings row is available for the org :::: {0}",new Object[] {System.currentTimeMillis()});
				}
			}

		}catch(Exception e) {
			resultObj.put("status", false);
			resultObj.put("response", "Settings row is not available for the org");
			LOGGER.log(Level.SEVERE, "EmailPreferenceTabMigration Exception", e);
			throw e;
		}
		return resultObj;
	}
    /**
     * @return
     * @throws Exception
     */
    public JSONObject enableOrDisablePayloadEncryption() throws Exception {
		String zgid = request.getParameter("zgid");
		String isEnable = request.getParameter("isEnable");
		if(zgid!=null){
            if(isEnable!=null){
                String msg = "Payload encryption enabled successfully";//no i18n
                if(isEnable.equals("true")) {
                    LOGGER.log(Level.INFO,"PAYLOAD_ENCRYPTION enable started");//no i18n
			        CrmKeyValueUtil.insertOrUpdateCrmKeyValueByKeyName("PAYLOAD_ENCRYPTION",isEnable, String.valueOf(zgid), true);//no i18n
                     LOGGER.log(Level.INFO,"PAYLOAD_ENCRYPTION enable completed");//no i18n

		        }
		        else {
                    LOGGER.log(Level.INFO,"PAYLOAD_ENCRYPTION disable started");//no i18n
			        CrmKeyValueUtil.deleteCrmKeyValueByKeyName("PAYLOAD_ENCRYPTION", true);//no i18n
                    LOGGER.log(Level.INFO,"PAYLOAD_ENCRYPTION disable completed");//no i18n
                    msg ="Payload encryption disabled successfully";//no i18n
		        }
                resultObj.put("status", true); //no i18n
		        resultObj.put("response", msg); //no i18n
		        return resultObj;

            }
            resultObj.put("status", false); //no i18n
		    resultObj.put("response", "isEnable Param missing"); //no i18n
		    return resultObj;
        }
		resultObj.put("status", false); //no i18n
		resultObj.put("response", "zgid Param missing"); //no i18n
		return resultObj;

    }


	/**
	 * 
	 * @return
	 * @throws Exception
	 */
	public JSONObject deleteStaleComponentRelationInAutoResponse() throws Exception{
		status = true;
		String res = "";
		try {
			SelectQuery qry = new SelectQueryImpl(Table.getTable(CRMWEBENTITYAUTORESPENTRY.TABLE));
			qry.addSelectColumn( Column.getColumn(CRMWEBENTITYAUTORESPENTRY.TABLE,CRMWEBENTITYAUTORESPENTRY.RULEID));
			qry.addSelectColumn( Column.getColumn(CRMWEBENTITYAUTORESPENTRY.TABLE,CRMWEBENTITYAUTORESPENTRY.ENTRYID));
			DoIterator doIterator = new DoIterator(PersistenceCacheUtil.getPurePersistenceLiteHandle(), qry, 1000);
			List<Long> entryIds=new ArrayList<>();
			while(doIterator.hasNext())
			{
				DataObject autoRespEntryDO = doIterator.next();
				if(autoRespEntryDO!=null) {
					Iterator<?> autoRespEntryRows  = autoRespEntryDO.getRows(CRMWEBENTITYAUTORESPENTRY.TABLE);
					while(autoRespEntryRows.hasNext()) {
						Row autoRespEntryRow = (Row) autoRespEntryRows.next();
						entryIds.add((long)autoRespEntryRow.get(CRMWEBENTITYAUTORESPENTRY.ENTRYID));
					}
				}
			}
			
			SelectQuery qry2 = new SelectQueryImpl(Table.getTable(CRMCOMPONENTRELATION.TABLE));
			qry2.addSelectColumn( Column.getColumn(CRMCOMPONENTRELATION.TABLE,CRMCOMPONENTRELATION.CRMCOMPONENTRELATIONID));
			qry2.addSelectColumn( Column.getColumn(CRMCOMPONENTRELATION.TABLE,CRMCOMPONENTRELATION.DEPENDANT_COMPONENT_NAME));
			qry2.addSelectColumn( Column.getColumn(CRMCOMPONENTRELATION.TABLE,CRMCOMPONENTRELATION.DEPENDANT_COMPONENT_ID));
			Criteria crt = new Criteria(Column.getColumn(CRMCOMPONENTRELATION.TABLE, CRMCOMPONENTRELATION.DEPENDANT_COMPONENT_ID) , entryIds.toArray() , QueryConstants.NOT_IN );
			crt = crt.and(new Criteria(Column.getColumn(CRMCOMPONENTRELATION.TABLE, CRMCOMPONENTRELATION.DEPENDANT_COMPONENT_NAME) , CrmTemplateUtil.AUTORESPONSERULE , QueryConstants.EQUAL ));
			qry2.setCriteria(crt);
			
			doIterator = new DoIterator(PersistenceCacheUtil.getPurePersistenceLiteHandle(), qry2, 1000);
			List<Long> staledependentComponentIds=new ArrayList<>();
			while(doIterator.hasNext())
			{
				DataObject crmComponentDO = doIterator.next();
				if(crmComponentDO!=null) {
					Iterator<?> crmComponentRows  = crmComponentDO.getRows(CRMCOMPONENTRELATION.TABLE);
					while(crmComponentRows.hasNext()) {
						Row crmComponentRow = (Row) crmComponentRows.next();
						staledependentComponentIds.add((long)crmComponentRow.get(CRMCOMPONENTRELATION.DEPENDANT_COMPONENT_ID));
					}
				}
			}
			if(!staledependentComponentIds.isEmpty()) {
				ComponentsUsageUtil.deleteDependentComponentsUsage(staledependentComponentIds);
			}
			
		}catch(Exception e) {
			res = e.getMessage();
			status = false;
		}
		resultObj.put("status", status);
		resultObj.put("response", res);
		return resultObj;
	}

