    /**
    * Returns Download links for feature for given ids
    * @return
    * @throws Exception
    */
    public JSONObject getDownloadLinks() throws Exception {
		String downloadIds = String.valueOf(request.getParameter("downloadIds")).trim();//NO I18N
		String feature = String.valueOf(request.getParameter("feature")).trim();//NO I18N
		String msg = null;
		JSONObject respObj = new JSONObject();
		if(UDSFactory.getUDSRouterForFeature(feature)==null) {
			msg = "Invalid Feature "+feature;//NO I18N
			respObj.put("status","failure");//NO I18N
			respObj.put("message",msg);//NO I18N
		} else {
			for(String downloadId : downloadIds.split(",")) {
				downloadId = downloadId.trim();
				if(NumberUtil.getLong(downloadId)==null) {
					LOGGER.info("INVALID DOWNLOADID ".concat(downloadId));
					continue;
				} else if(respObj.has(downloadId)) {
					LOGGER.info("DUPLICATE ".concat(downloadId));
					continue;
				}
				JSONObject eachResponse = new JSONObject();
				List<String> fileNames = new ArrayList<String>(1), previewNames = new ArrayList<String>(1);
				switch(feature) {
				case "export":
				case "bulk-write":
					fileNames.add(downloadId+".zip");//NO I18N
					break;
				case "backup":
					String zgid = OrgUtil.getCurrentZGID()+"";
					List<String> filesdata = ZFSUtil.getDFileNames(zgid, DataBackupUtil.getZFSPath(DataBackupConstants.DATA_INIT_CAP,downloadId), null, null);
					List<String> filesattachment = ZFSUtil.getDFileNames(zgid, DataBackupUtil.getZFSPath(DataBackupConstants.CONST_ATTACHMENTS,downloadId), null, null);
					List<String> filesemails = ZFSUtil.getDFileNames(zgid, DataBackupUtil.getZFSPath(DataBackupConstants.CONST_EMAILS,downloadId), null, null);
					filesdata = filesdata==null?ZFSUtil.getDFileNames(zgid, DataBackupUtil.getZFSPath(DataBackupConstants.DATA_INIT_CAP, zgid), null, null):filesdata;
					filesattachment = filesattachment==null?ZFSUtil.getDFileNames(zgid, DataBackupUtil.getZFSPath(DataBackupConstants.CONST_ATTACHMENTS,zgid), null, null):filesattachment;
					filesemails = filesemails==null?ZFSUtil.getDFileNames(zgid, DataBackupUtil.getZFSPath(DataBackupConstants.CONST_EMAILS,zgid), null, null):filesemails;
					for(List<String> list : Arrays.asList(filesdata,filesattachment,filesemails)) {
						if(list!=null) {
							for(String name : list) {
								fileNames.add(name.substring(name.lastIndexOf('/')+1));
							}
						}
					}
					break;
				case "auditlog":
					String folderPath = new StringBuilder(ExportSchedulerConstants.ZFS_FILE_SEPARATOR)
					.append(ExportSchedulerConstants.EXPORT_FILE_PATH)
					.append(ExportSchedulerConstants.ZFS_FILE_SEPARATOR)
					.append(downloadId)
					.append(ExportSchedulerConstants.ZFS_FILE_SEPARATOR).toString();
					List<String> files = ZFSUtil.getDFileNames(null,folderPath,null,null);
					if(files!=null) {
						for(String name : files) {
							fileNames.add(name.substring(name.lastIndexOf('/')+1));
						}
					}
					break;
				case "files":
				case "attachments":
					previewNames.add("view");//NO I18N
					fileNames.add("download");//NO I18N
					break;
				case "fileupload":
					DataObject dObj = AttachmentUtil.getAttachmentObjectUsingFieldList(Arrays.asList(Long.parseLong(downloadId)));
					if(!dObj.isEmpty()) {
						String tableName = (String)dObj.getTableNames().get(0);
						String pkColumn = EntityMetaDataUtil.getPKColumnName(tableName);
						Iterator<Row> itr = dObj.getRows(tableName);
						while(itr.hasNext()) {
							Row row = itr.next();
							Long pkId = Long.parseLong(row.get(pkColumn)+"");
							fileNames.add(pkId+"_download");//NO I18N
							previewNames.add(pkId+"_view");//NO I18N
						}
					}
				}
				List<String> downloadLinks = new ArrayList<String>(0);
				for(String fName : fileNames) {
					String link = UDSService.getDownloadLink(feature,downloadId,fName);
					if(link!=null) {
						downloadLinks.add(link);
					}
				}
				if(downloadLinks.isEmpty()) {
					eachResponse.put("download_error","Invalid Link");//NO I18N
				}
				eachResponse.put("download_links",downloadLinks);
				List<String> previewLinks = new ArrayList<String>(0);
				for(String preName : previewNames) {
					String previewLink = UDSService.getDownloadLink(feature,downloadId,preName);
					if(previewLink!=null) {
						previewLinks.add(previewLink);
					}
				}
				eachResponse.put("preview_links",previewLinks);
				respObj.put(downloadId,eachResponse);
			}
		}
		return respObj;
    }

