	 /**
	 * to fetch the encrypted data related to the survey integration for the survey RL api QA automation
	 * @return
	 * @throws Exception
	 */
	public JSONObject fetchSendSurveyEncryptedData() throws Exception{
		status = true ;
		String msg = "success";//No I18N
        JSONObject data = new JSONObject();

		try {
		//	String entityEmail 	= request.getParameter("toEmail");//NO I18N
			String entityModule = request.getParameter("module");//NO I18N
			String entityRecId 	= request.getParameter("entityId");//NO I18N
			String userId    	= request.getParameter("crmUserId");//NO I18N
		//	String isNonEmailModule = request.getParameter("isNonEmailModule");//NO I18N

			String mappedModule = request.getParameter("mappedModule");//NO I18N
			String mappedRecId = request.getParameter("mappedRecId");//NO I18N

			String entIdForZMail  = request.getParameter("entIdForZMail");//NO I18N


			JSONObject surveyEntityDetails = new JSONObject();

			surveyEntityDetails.put("entityId" ,entityRecId );//No I18N
			surveyEntityDetails.put("module" , entityModule);// No I18N

			if (ZSurveyUtil.getNonEmailSurveyModule().contains(entityModule) &&
				    CrmModuleConstants.POTENTIALS.equals(entityModule) && entIdForZMail != null)
			{
				surveyEntityDetails.put("entIdForZMail" , entIdForZMail);// No I18N
			}

			if(mappedModule!=null && mappedRecId!=null)
			{
				surveyEntityDetails.put("mappedRecId" , mappedRecId);// No I18N
				surveyEntityDetails.put("mappedModule" , mappedModule);// No I18N
			}
			if(userId!=null) {

				surveyEntityDetails.put("crmUserId" , userId);// No I18N
			}


			ZSurveyUtil surveyUtil = new ZSurveyUtil();
			data = surveyUtil.getSurveyEncryptedContentsForEntity(surveyEntityDetails);

		} catch (Exception e) {
			LOGGER.log(Level.SEVERE, "Exception occured while forming the encryted contents", e);
			msg = e.getMessage();
			status = false ;
		}
		resultObj.put("response", msg);//No I18N
		resultObj.put("details" ,  data ) ; //NO I18N
		resultObj.put("status" , status ) ; //No I18N
		return resultObj;
	}







