    /**
	 * disable calls preferences
	 * @throws Exception
	 */
	public JSONObject disableCallsPreferences() throws Exception{
		status=true;
		try {
			String jsonStr =  CrmOrgLevelConfigUtil.getConfigurationDetails(CrmConstants.CALLS_PREFERENCE_SETTINGS);
			JSONObject jo  = new JSONObject();
			if(jsonStr!=null) {
				jo = new JSONObject(jsonStr);
			}
			if(!jo.has("calls")) {
				throw new Exception("calls preference not enabled");
			}
			JSONObject call_pref = jo.getJSONObject("calls");

			call_pref.put("show_from_number", false);
			call_pref.put("show_to_number", false);
			jo.put("calls", call_pref);
			FieldUtil.updateFieldPresence(-1, 33, "TONUMBER", null); //No I18N
			FieldUtil.updateFieldPresence(-1, 33, "FROMNUMBER", null); //No I18N
			CrmOrgLevelConfigUtil.insertOrUpdateConfigDetails(CrmConstants.CALLS_PREFERENCE_SETTINGS,jo.toString());
		}catch(Exception ex) {
			status=false;
			LOGGER.log(Level.INFO,"Exception  While disabling the calls preferences",ex);
        }
		resultObj.put("status", status);
		return resultObj;
	}
