	/**
     * @return This method to update showtype for convert fields
     * @throws Exception
     */
	public JSONObject updateShowTypeForConvertField() throws Exception{
		try {
			Long tabId = TabUtil.getTabIdByAPIName("Leads"); //NO I18N
			if (tabId != null) {
				String[] columnNames = { CRMLEADDETAILS.CONVERTED_ACCOUNTID, CRMLEADDETAILS.CONVERTED_CONTACTID, CRMLEADDETAILS.CONVERTED_POTENTIALID };
				Criteria cr = new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.COLUMNNAME), columnNames, QueryConstants.IN);
				cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.SHOWTYPE), 17, QueryConstants.EQUAL));
				cr = cr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.TABID), tabId, QueryConstants.EQUAL));
				DataObject fieldsDO = FieldUtil.getFieldsDOUsingCriteria(cr);
				if (fieldsDO != null && !fieldsDO.isEmpty()) {
					Iterator<Row> fieldRows = fieldsDO.getRows(CRMFIELD.TABLE);
					while (fieldRows.hasNext()) {
						Row row = fieldRows.next();
						row.set(CRMFIELD.SHOWTYPE, 8);
						row.set(CRMFIELD.VIEWTYPE, 18);
						fieldsDO.updateRow(row);
					}
					PersistenceCacheUtil.getNCPurePersistenceLiteHandle().update(fieldsDO);

					List<String> modules = new ArrayList<String>();
					modules.add(CrmModuleConstants.LEADS);
					PageCacheUtil.createSchedulerForPageRegen(modules);
					status = true;
					resultObj.put("response", "showtype for convert fields updated successfully");
				}else {
					status = false;
					resultObj.put("response", "no converted fields needs to update in lead module");
				}
			}else {
				status = false;
				resultObj.put("response", "no tabid present");
			}
		} catch (Exception e) {
			status = false;
			resultObj.put("response", e.toString());
			LOGGER.log(Level.WARNING, "Exception occurred while job migration", e);
		}
		resultObj.put("status", status);
		return resultObj;
	}

