	/**
	 * @return method to mark the scheduled call as calendar booked call
	 */
	public JSONObject createCalendarBookingCall() {
		try {
			status=true;
			Long callid = Long.valueOf(request.getParameter("callid"));
			EntityQueryBean querybean = new EntityQueryBean(CrmModuleConstants.CALLS, false, false, false);
			querybean.setId(callid);
			querybean.setSavedRecordOnly(true);

			DataObject recordDO = EntityUtil.getEntityDO(querybean);

			if(!recordDO.isEmpty()) {
				Row callRow = recordDO.getRow(CRMCALL.TABLE, (Criteria)null);
				DataObject calFormDO = CalendarScheduleUtil.getCalendarScheduleDataObject(null,null);
				Long tabid = TabUtil.getTabIdByAPIName(CrmModuleConstants.CALLS);
				Long sourceId = !calFormDO.isEmpty() ? ((Long)calFormDO.getValue(CRMCALENDARFORMCONFIG.TABLE, CRMCALENDARFORMCONFIG.CALFORMCONFIGID, new Criteria(Column.getColumn(CRMCALENDARFORMCONFIG.TABLE,CRMCALENDARFORMCONFIG.DATAPUSHMODULE), tabid, QueryConstants.EQUAL))) : null;
				if(sourceId!=null) {
						callRow.set(CRMCALL.SOURCEID, sourceId);
						recordDO.updateRow(callRow);
						PersistenceCacheUtil.getPurePersistenceLiteHandle().update(recordDO);
				}else {
					status=false;
					resultObj.put("response", "calendar booking for call not found");
				}
			}else {
				status=false;
				resultObj.put("response","record not found");
			}
			resultObj.put("response", "call is marked as calendar booked call");
			resultObj.put("status",status);
		}catch(Exception e) {
			status = false;
			resultObj.put("response", e.toString());
			LOGGER.log(Level.WARNING, "Exception occurred while createCalendarBookingCall ", e);
		}

		return resultObj;
	}


