	/**
	 * @throws Exception
	 */
	public JSONObject retrieveClusterInfo() throws Exception {
		String msg = null;
		try {
			String retrieveType = request.getParameter("retrieveType").toLowerCase();
			resultObj.put("retrieveType", retrieveType);
			switch (retrieveType) {
			case "slavelag":
				Long slaveLagInSec = ReplicationLagMonitor.getMySQLSlaveConnectionLagTime();
				if (slaveLagInSec != null) {
					LOGGER.log(Level.FINE, "Successfully retrieved slavelag for zgid - {0} ", new Object[] { zgId });
					msg = "Successfully retrieved slaveLag";// no i18n
					resultObj.put("slaveLagInSec", slaveLagInSec);
				} else {
					LOGGER.log(Level.FINE, "Issue while retrieving slavelag for zgid - {0} ", new Object[] { zgId });
					msg = "Kindly check whether the slave is in live state!!!";// no i18n
					status = false;
					resultObj.put("slaveLagInSec", JSONObject.NULL);
				}
				break;
			case "clusterip":
				String clusterIp = SASThreadLocal.getClusterIp();
				resultObj.put("clusterIp", clusterIp);
				LOGGER.log(Level.FINE, "Successfully retrieved clusterIp for zgid - {0}", new Object[] { zgId });
				msg = "Successfully retrieved the clusterip";// no i18n
				break;
			default:
				LOGGER.log(Level.INFO, "Unknown Type found {0}", new Object[] { retrieveType });
				msg = "Unknown Type found!! Supported Types {clusterip,slavelag}";// no i18n
			}

		} catch (Exception e) {
			LOGGER.log(Level.SEVERE, "Exception occurred while retrieving clusterspecific info :: ", e);
			status = false;
			msg = e.getMessage();
		}
		resultObj.put("response", msg);
		return resultObj;

    }

