    /**
     * It will be removed once Lyte CV is enabled for all accounts.
     * for populating default customviews
     */
    public JSONObject populateDefaultCustomViews() throws Exception
    {
        try
        {
            String module = request.getParameter("module");
            boolean isNewFlow = Boolean.parseBoolean(request.getParameter("newFlow"));

            List<String> defaultModuleList = module.equals("default") ? new ArrayList<>(Arrays.asList("Leads","Contacts","Accounts","Potentials","Tasks","Events","Vendors","Campaigns","Cases","Solutions","Products","Quotes","SalesOrders","PurchaseOrders","Invoices","PriceBooks","Calls","Activities","Users","Messages")) : new ArrayList<>(Arrays.asList(module));//No I18N
            Criteria categoryCriteria = new Criteria(Column.getColumn(CRMCUSTOMVIEW.TABLE, CRMCUSTOMVIEW.SOURCE), CustomViewConstants.Source.RECORDS.getSource(), QueryConstants.EQUAL);
            categoryCriteria = categoryCriteria.or(new Criteria(Column.getColumn(CRMCUSTOMVIEW.TABLE, CRMCUSTOMVIEW.SOURCE), null, QueryConstants.EQUAL));

            Criteria featureCriteria = new Criteria(Column.getColumn(CRMCUSTOMVIEW.TABLE, CRMCUSTOMVIEW.FEATURETYPE), com.zoho.crm.customviews.util.CustomViewUtil.FeatureType.CUSTOM_VIEW.getFeatureType(), QueryConstants.EQUAL);
            featureCriteria = featureCriteria.or(new Criteria(Column.getColumn(CRMCUSTOMVIEW.TABLE, CRMCUSTOMVIEW.FEATURETYPE), null, QueryConstants.EQUAL));
            if(module.equals("Home"))
            {
                categoryCriteria = new Criteria(Column.getColumn(CRMCUSTOMVIEW.TABLE, CRMCUSTOMVIEW.CATEGORY), com.zoho.crm.customviews.util.CustomViewUtil.Category.HOMEPAGE_VIEWS.getCategory(), QueryConstants.EQUAL);
                categoryCriteria = categoryCriteria.or(new Criteria(Column.getColumn(CRMCUSTOMVIEW.TABLE, CRMCUSTOMVIEW.SOURCE), CustomViewConstants.Source.HOMEPAGE.getSource(), QueryConstants.EQUAL));
            }
            else
            {
                if(!isNewFlow)
                {
                    categoryCriteria = categoryCriteria.and(new Criteria(Column.getColumn(CRMCUSTOMVIEW.TABLE, CRMCUSTOMVIEW.CATEGORY), com.zoho.crm.customviews.util.CustomViewUtil.Category.getFeatureSpecificCategories(), QueryConstants.NOT_IN));
                    if(module.equals("default"))
                    {
                        defaultModuleList.addAll(new ArrayList<>(Arrays.asList("InvoicedItems", "PurchaseItems", "OrderedItems", "QuotedItems")));//No I18N
                    }
                }
                featureCriteria = featureCriteria.and(new Criteria(Column.getColumn(CRMCUSTOMVIEW.TABLE, CRMCUSTOMVIEW.CVMODULE), defaultModuleList.toArray(), QueryConstants.IN));
            }
            featureCriteria = featureCriteria.and(categoryCriteria);

            DataObject defaultCvDo = PersistenceCacheUtil.getNonCachePersistenceHandle().constructDataObject();
            // delete old entry if there
            DeleteQuery dq = new DeleteQueryImpl(Table.getTable(CRMCUSTOMVIEW.TABLE));
            dq.addJoin(new Join(CRMCUSTOMVIEW.TABLE, CRMQUERY.TABLE, new String[]{CRMCUSTOMVIEW.CVQUERYID}, new String[]{CRMQUERY.QUERYID}, Join.LEFT_JOIN));
            dq.addJoin(new Join(CRMCUSTOMVIEW.TABLE, SELECTQUERY.TABLE, new String[]{CRMCUSTOMVIEW.QUERYID}, new String[]{SELECTQUERY.QUERYID}, Join.LEFT_JOIN));
            dq.setCriteria(featureCriteria);
            PersistenceCacheUtil.getPurePersistenceLiteHandle().delete(dq);

            //add cv enrty
            if(module == null || module.equals("default"))
            {
                if(isNewFlow)
                {
                    Long zgid = OrgUtil.getCurrentZGID();
                    Long userId = OrgUtil.getUserIdOfPrimaryContact(String.valueOf(zgid));
                    SystemCustomViewPopulationHelper.populateDefaultCustomViews(userId, zgid, CVJsonTemplates.ALLVIEWS, false);
                    SystemCustomViewPopulationHelper.populateDefaultCustomViews(userId, zgid, CVJsonTemplates.DEFAULT, false);
                }
                else
                {
                    defaultCvDo = Xml2DoConverter.transform(CrmConstants.PATH_FOR_SFA+"DefaultCustomView.xml"); //No I18N
                }
            }
            else if(module.equals("Home"))
            {
                if(isNewFlow)
                {
                    SystemCustomViewPopulationHelper.populateCVForModules(new ArrayList<String>(Arrays.asList("Home")), CVJsonTemplates.HOMEPAGE, false);//No I18N
                    SystemCustomViewPopulationHelper.populateCVForModules(new ArrayList<String>(Arrays.asList("Home")), CVJsonTemplates.ACTIVITIES_HOMEPAGE, false);//No I18N
                }
                else
                {
                    defaultCvDo = Xml2DoConverter.transform(CrmConstants.PATH_FOR_SFA+"DefaultHomeCV.xml"); //No I18N
                    defaultCvDo.merge(Xml2DoConverter.transform(CrmConstants.PATH_FOR_SFA+"DefaultHomeCVSplit.xml"));//No I18N
                    defaultCvDo.merge(Xml2DoConverter.transform(CrmConstants.PATH_FOR_SFA+"ActivitiesComponentCV.xml"));//No I18N
                }
            }
            else if(module.equals(CrmModuleConstants.APPOINTMENTS))
            {
                if(isNewFlow)
                {
                    SystemCustomViewPopulationHelper.populateCVForModules(new ArrayList<String>(Arrays.asList(CrmModuleConstants.APPOINTMENTS)), CVJsonTemplates.APPOINTMENTS, true);
                }
                else
                {
                    defaultCvDo = Xml2DoConverter.transform(CrmConstants.PATH_FOR_SFA+"PopulateAppointmentModule.xml"); //No I18N
                }
            }
            else if(module.equals(CrmModuleConstants.SERVICES))
            {
                if(isNewFlow)
                {
                    SystemCustomViewPopulationHelper.populateCVForModules(new ArrayList<String>(Arrays.asList(CrmModuleConstants.SERVICES)), CVJsonTemplates.SERVICES, true);
                }
                else
                {
                    defaultCvDo = Xml2DoConverter.transform(CrmConstants.PATH_FOR_SFA+"PopulateServiceModule.xml"); //No I18N
                }
            }
            else if(module.equals(CrmModuleConstants.VISITS))
            {
                if(isNewFlow)
                {
                    SystemCustomViewPopulationHelper.populateCVForModules(new ArrayList<String>(Arrays.asList(CrmModuleConstants.VISITS)), CVJsonTemplates.VISITS, true);
                }
                else
                {
                    defaultCvDo = Xml2DoConverter.transform(CrmConstants.PATH_FOR_SFA+"livedesk-fields.xml"); //No I18N
                }
            }
            else if(module.startsWith("CustomModule"))
            {
                if(isNewFlow)
                {
                    SystemCustomViewPopulationHelper.populateCustomViewRelatedRows(null, module, CVJsonTemplates.LOCKED, null, false, false, true);
                    SystemCustomViewPopulationHelper.populateCVDoForCustomModule(null, CVJsonTemplates.CUSTOM_MODULE, module, null);
                }
                else
                {
                    String moduleNum = module.replace("CustomModule","");
                    defaultCvDo = com.zoho.crm.core.meta.tabs.custommodule.CustomModuleUtil.generateCustomModuleDOFromXMLTemplate(Integer.parseInt(moduleNum), CoreFeatureNameConstants.CUSTOM_MODULE, null);
                }

            }
            else if(module.startsWith("LinkingModule"))
            {
                if(isNewFlow)
                {
                    SystemCustomViewPopulationHelper.populateCVDoForCustomModule(null, CVJsonTemplates.LINKING_MODULE, module, null);
                }
                else
                {
                    String moduleNum = module.replace("LinkingModule","");
                    defaultCvDo = com.zoho.crm.core.meta.tabs.custommodule.CustomModuleUtil.generateCustomModuleDOFromXMLTemplate(Integer.parseInt(moduleNum), CoreFeatureNameConstants.LINKING_MODULE, null);
                }

            }
            else if(module != null && !defaultModuleList.isEmpty())
            {
                if(isNewFlow)
                {
                    SystemCustomViewPopulationHelper.populateCVForModules(new ArrayList(defaultModuleList), CVJsonTemplates.ALLVIEWS, true);
                    SystemCustomViewPopulationHelper.populateCVForModules(new ArrayList(defaultModuleList), CVJsonTemplates.DEFAULT, false);
                }
                else
                {
                    defaultCvDo = Xml2DoConverter.transform(CrmConstants.PATH_FOR_SFA+"DefaultCustomView.xml"); //No I18N
                }

            }
            if(!isNewFlow)
            {
                DataObject finalDo = PersistenceCacheUtil.getNonCachePersistenceHandle().constructDataObject();
                
                Iterator<Row> iter = defaultCvDo.getRows(CRMCUSTOMVIEW.TABLE);
                List tableList = new ArrayList();
                tableList.add(SELECTQUERY.TABLE);
                tableList.add(SELECTTABLE.TABLE);
                tableList.add(SELECTCOLUMN.TABLE);
                tableList.add(SORTCOLUMN.TABLE);
                tableList.add(JOINTABLE.TABLE);
                tableList.add(JOINCOLUMNS.TABLE);
                tableList.add(CRITERIA.TABLE);
                tableList.add(RELATIONALCRITERIA.TABLE);
                tableList.add(CRMCONFIG.TABLE);
                tableList.add(CRMACCESSIBILITY.TABLE);
                while(iter.hasNext())
                {
                    Row row = (Row)iter.next();
                    if(!module.equals("Home") && row != null && row.get(CRMCUSTOMVIEW.CATEGORY) != null && row.get(CRMCUSTOMVIEW.CATEGORY).equals(com.zoho.crm.customviews.util.CustomViewUtil.Category.HOMEPAGE_VIEWS.getCategory()))
                    {
                        continue;
                    }
                    if(!module.equals("Home") && !module.equals("default") && !defaultModuleList.contains(row.get(CRMCUSTOMVIEW.CVMODULE)))
                    {
                        continue;
                    }
                    DataObject newobj = defaultCvDo.getDataObject(tableList, row);
                    if(finalDo != null && newobj != null && !newobj.isEmpty())
                    {
                        finalDo.merge(newobj);
                    }
                }
                PersistenceCacheUtil.getPurePersistenceLiteHandle().add(finalDo);
            }
            else if(!isNewFlow)
            {
                PersistenceCacheUtil.getPurePersistenceLiteHandle().add(defaultCvDo);
            }
            resultObj.put("response", "Default custom views populated successfully"); //No I18N
            resultObj.put("status", true); //No I18N
        }
        catch(Exception e)
        {
            resultObj.put("status", false); //No I18N
            resultObj.put("response", e.getMessage()); //No I18N
        }
        return resultObj;
    }

