    public JSONObject getMailCollabUserStatus() throws Exception {
		String userId = request.getParameter("userid"); // no i18n
		Long zgId = OrgUtil.getCurrentZGID();
		JSONObject resultObj = new JSONObject();
		if (userId != null && !userId.isEmpty()) {
			Row mailRow = MailAppsDBUtil.getMailRow(Long.valueOf(userId), zgId.toString());
			JSONObject otherMailInfo = MailAppsDBUtil.getOtherZohoMailInfo(mailRow);
			boolean isMailCollabUser = otherMailInfo.optString(MailAppsConstants.ConfigurationConstants.MAILCOLLAB_USER, "false").equals("true");    //No I18n
			if (isMailCollabUser) {
				resultObj.put("status", true);	//No I18n
				resultObj.put("response", "MailCollabView available for user");	//No I18n
				LOGGER.log(Level.INFO, "MailCollabView available for user :::: {0}", new Object[]{System.currentTimeMillis()});	//No I18n
			} else {
				resultObj.put("status", false);	//No I18n
				resultObj.put("response", "MailCollabView unavailable for user");	//No I18n
				LOGGER.log(Level.INFO, "MailCollabView unavailable for user :::: {0}", new Object[]{System.currentTimeMillis()});	//No I18n
			}
		}
		return resultObj;
	}

