    /**
	 * @author adithan-10376
	 * @throws Exception
	 */
	public JSONObject removeBiginOnboardingHelpVideoWhatsNew() {

		try {
			String zgId = OrgUtil.getCurrentZGID().toString();
			SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMUSERDETAILS.TABLE));
            sq.addSelectColumn(Column.getColumn(CRMUSERDETAILS.TABLE, CRMUSERDETAILS.USERID));
			sq.addSelectColumn(Column.getColumn(CRMUSERDETAILS.TABLE, CRMUSERDETAILS.CUSTOMIZE_INFO));
			DataObject dObj = PersistenceCacheUtil.getNonCachePersistenceHandle(zgId).get(sq);
			if(!dObj.isEmpty()) {
				Iterator<Row> itr = dObj.getRows(CRMUSERDETAILS.TABLE);
				while(itr.hasNext())
				{
					Row usrRow = itr.next();
					if (usrRow.get(CRMUSERDETAILS.CUSTOMIZE_INFO) != null) {
						String customizeInfo = (String)usrRow.get(CRMUSERDETAILS.CUSTOMIZE_INFO);
                        JSONObject customizeJsonObj = new JSONObject();
                        boolean isValidCustomInfoJSON = com.adventnet.crm.api.commons.JSONUtil.isValidJsonObject(customizeInfo);
						if(customizeInfo != null) {
                            if(isValidCustomInfoJSON) {
							    customizeJsonObj = new JSONObject(customizeInfo);
                            } else {
                                customizeInfo = customizeInfo + "}"; //No I18N
                                isValidCustomInfoJSON = com.adventnet.crm.api.commons.JSONUtil.isValidJsonObject(customizeInfo);
                                if(isValidCustomInfoJSON) {
                                    customizeJsonObj = new JSONObject(customizeInfo);
                                }
                            }
							String help_key = RebrandLinkUtil.getRebrandKeys("BIGIN_HELP_VIDEOS"); //No I18N
							String[] helpkeys = help_key.split(","); //NO I18N
							customizeJsonObj.put("bigin_hv", helpkeys); //NO I18N
                            if(customizeJsonObj.has("bigin_o")) {
							    customizeJsonObj.remove("bigin_o"); //NO I18N
                            }
							String whatsnew_key = RebrandLinkUtil.getRebrandKeys("BIGIN_WHATSNEW_BUILDLABEL"); //No I18N
							customizeJsonObj.put("bigin_wn", whatsnew_key + "_0123456789"); //NO I18N
							usrRow.set(CRMUSERDETAILS.CUSTOMIZE_INFO, customizeJsonObj.toString());
							dObj.updateRow(usrRow);
						}
					}
				}
				PersistenceCacheUtil.getNonCachePersistenceHandle(zgId).update(dObj);
	    		resultObj.put("status", true); //No I18N
	    		resultObj.put("response", "success"); //No I18N
			}
		} catch (Exception ex) {
    		resultObj.put("status", false); //No I18N
    		resultObj.put("response", ex.getMessage()); //No I18N
			LOGGER.log(Level.INFO, "Exception occurred during removeBiginDuplicateHelpVideoKeys :: ", ex);
		}

		return resultObj;
	}
	
	/**
	 * 
	 * @throws Exception
	 */
	public void resetRequesterSettingsConfig() throws Exception {
		try {
			DataObject privateTabDo = TabUtil.getAllPrivateModuleDo(OrgUtil.getCurrentZGID().toString());
			Iterator<Row> tabRows = privateTabDo.getRows(CRMTAB.TABLE);
			while (tabRows.hasNext()) {
				Row tabRow = tabRows.next();
				if (tabRow.getInt(CRMTAB.MODULE_TYPE).equals(DefaultModuleType.ENTITIES.getValue())) {
					Long privateTabId = tabRow.getLong(CRMTAB.TABID);
					RequesterSettingsUtil.deleteRequesterSettings(privateTabId);
					WorkflowFilter wfFilter = new WorkflowFilter();
					wfFilter.setModule(TabUtil.getTabNameById(privateTabId));
					wfFilter.setCategories(List.of(AutomationConstants.AUTOMATION_CATEGORY.INTERNAL));
					wfFilter.setSources(List.of(CrmAutomationConstants.AUTOMATION_SOURCES.REQUESTER_SETTINGS.Source()));
					List<WorkFlowRule> rule = WorkFlowRead.getInstance().getAllRulesForListView(wfFilter, 1, 200);
					if(rule != null && !rule.isEmpty()) {
						WorkFlow wf = WorkFlowRead.getInstance().getRuleDetails(rule.get(0).getId(), true, true);
						WorkFlowDelete.getInstance().deleteWorkflowRule(wf.getRuleId(), WorkFlowRuleUtil.getAdminUserId(), CrmAutomationConstants.INVOKEDFROM.REQUESTER_SETTINGS.name());
					}
				}
			}
			resultObj.put("status", true); // NO I18N
			resultObj.put("response", "success"); // NO I18N
		}catch(Exception exp) {
			resultObj.put("status", false); // NO I18N
			resultObj.put("response", exp.getMessage()); // NO I18N
			LOGGER.log(Level.SEVERE, "Exception Occurred during resetting Requester Settings Config :: {0}", new Object[] {exp});
		}
	}
	
