	public JSONObject changeCrmAccountBiginLicenseType() {
		boolean isSuccess = false;
		try {

			String zgId = OrgUtil.getCurrentZGID().toString();
			String edition = request.getParameter("edition");

			boolean isBigin = CrmEnvironment.BIGIN.equals(CrmEnvironment.getCurrentEnvironment());
			if(!isBigin) {
				SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMLICENSEKEY.TABLE));
				sq.addSelectColumn(Column.getColumn(CRMLICENSEKEY.TABLE, CRMLICENSEKEY.LICENSEID));
				sq.addSelectColumn(Column.getColumn(CRMLICENSEKEY.TABLE, CRMLICENSEKEY.LICENSE_TYPE));
				DataObject dObj = PersistenceCacheUtil.getNonCachePersistenceHandle(zgId).get(sq);
				if(!dObj.isEmpty()) {
					Row licRow = dObj.getFirstRow(CRMLICENSEKEY.TABLE);
					String licType = (String)licRow.get(CRMLICENSEKEY.LICENSE_TYPE);
					if((licType.equals("M") || licType.equals("I") || licType.equals("G") || licType.equals("B")) && (!edition.equals("M") && !edition.equals("I") && !edition.equals("G") && !edition.equals("B"))) {
						licRow.set(CRMLICENSEKEY.LICENSE_TYPE, edition);
						dObj.updateRow(licRow);
						PersistenceCacheUtil.getNonCachePersistenceHandle(zgId).update(dObj);
						isSuccess = true;
			    		resultObj.put("status", true); //No I18N
			    		resultObj.put("response", "success"); //No I18N
					}
				}
			}

		} catch (Exception ex) {
    		resultObj.put("status", false); //No I18N
    		resultObj.put("response", ex.getMessage()); //No I18N
			LOGGER.log(Level.INFO, "Exception occurred during changeBiginLicenseTypeForCrmAccount :: ", ex);
		}

		if(!isSuccess) {
    		resultObj.put("status", false); //No I18N
    		resultObj.put("response", "failure"); //No I18N
		}
		return resultObj;
	}

