    public JSONObject populateChurnData() throws Exception {
        List<ChurnPredictionConfiguration> configs = ChurnPredictionLogicUtil.getAllConfigurations();
        JSONObject response = new JSONObject();
        for(ChurnPredictionConfiguration config : configs){
            Long predictionId = config.getConfigId();
            JSONObject resultInfo = new JSONObject().put("isModelMetaUpdated", updateModelMeta(predictionId)).put("isConfigStatusUpdated", updateConfigStatus(predictionId)).put("isChurnResultsUpdated", populateChurnResults(predictionId));
            response.put(predictionId.toString(), resultInfo);
        }
        return response;
    }

