    public boolean updateModelMeta(Long configId) {
		try {
			ChurnPredictionConfiguration config = ChurnPredictionLogicUtil.getConfigurationById(configId);
        	DataObject modelDO = ZiaModelMetaDBUtil.getMetaDOByConfigIdType(configId,Arrays.asList(6),new Range(0,10));

			Criteria configCriteria = new Criteria(Column.getColumn(CRMZIAMODELMETA.TABLE, CRMZIAMODELMETA.CONFIGID), config.getConfigId(), QueryConstants.EQUAL);
	        Row modelRow = modelDO != null ? modelDO.getRow(CRMZIAMODELMETA.TABLE, configCriteria) : null;

			if(modelRow != null){
				Criteria cri = new Criteria(Column.getColumn(CRMZIAMODELMETA.TABLE, CRMZIAMODELMETA.CONFIGID), config.getConfigId(), QueryConstants.EQUAL);
				CommonDBUtil.deleteWithLimit(CRMZIAMODELMETA.TABLE,cri,PersistenceCacheUtil.getPurePersistenceLiteHandle(),1);
			}
			JSONObject modelInfo = new JSONObject("{\"accuracy\":69,\"accuracy_actual\":null,\"record_count\":1936,\"meta_version\":\"1.0\"}"); // NO I18N
			insertModelData(config, modelInfo);
            return true;
		}
		catch(Exception e) {
			LOGGER.log(Level.WARNING, "Exception in churn prediction model update." , e); // NO I18N
		}
		return false;
	}

	/**
     *
     * @param config
     * @param modelInfo
     * @throws Exception
     */
    public static void insertModelData(ChurnPredictionConfiguration config, JSONObject modelInfo) throws Exception {

    	Persistence persistence = PersistenceCacheUtil.getPersistenceLiteHandle();
		DataObject configModelDO = persistence.constructDataObject();

		Long currentTimeInMillis = DateTimeUtils.getMillisInGMT(DateTimeUtils.getCurrentTimeInGMT().toString());

		Row modelRow = new Row(CRMZIAMODELMETA.TABLE);
		modelRow.set(CRMZIAMODELMETA.CONFIGID, config.getConfigId());
		modelRow.set(CRMZIAMODELMETA.CONFIGTYPE, 6);
		modelRow.set(CRMZIAMODELMETA.MODELVERSION, 0);
		modelRow.set(CRMZIAMODELMETA.MODELSTATUS, 2);
		modelRow.set(CRMZIAMODELMETA.MODELNAME, "V2.0"); //no i18n
		modelRow.set(CRMZIAMODELMETA.TOTALINFERENCE, 0);
		modelRow.set(CRMZIAMODELMETA.SUCCESSFULINFERENCE, 0);
		modelRow.set(CRMZIAMODELMETA.MODELACCURACY, 95);
		modelRow.set(CRMZIAMODELMETA.CONFIGRELATEDINFO, modelInfo.toString());
		modelRow.set(CRMZIAMODELMETA.LASTRUNTIME, currentTimeInMillis);
		modelRow.set(CRMZIAMODELMETA.NEXTRUNTIME, currentTimeInMillis);
		configModelDO.addRow(modelRow);

		persistence.add(configModelDO);

    }
    
