	public boolean populateChurnResults(Long configId) {
		try {
			ChurnPredictionConfiguration config = ChurnPredictionLogicUtil.getConfigurationById(configId);
        	CrmUsers crmUsers = CrmUsers.getInstance(UserUtil.getCurrentUserId(), false);

			JSONObject churnData = new JSONObject();
			JSONArray servingData = new JSONArray();

			DataObject tabDO = TabUtil.getAllTabsCachedDO();
			Row predictionTabRow = tabDO.getRow(CRMTAB.TABLE, new Criteria(Column.getColumn(CRMTAB.TABLE, CRMTAB.TABID), config.getCustomerModuleId(), QueryConstants.EQUAL));
			Get predictModuleGet = CrmModules.getInstance(crmUsers).new Get((String) predictionTabRow.get(CRMTAB.SYS_REF_NAME), true);
			String baseTableName = EntityMetaDataUtil.getBaseTableByModuleName(predictionTabRow.get(CRMTAB.NAME).toString());

			CrmFields.Get crmFieldsGet = CrmFields.getInstance(predictModuleGet).GET();
			CrmRecordsGet crmRecordsGet = CrmRecordsGet.getInstance(crmFieldsGet);
			DataObject predictRecordsDO = crmRecordsGet.getRecordsDO();

			Iterator<Row> recordRows = predictRecordsDO.getRows(baseTableName);
			String primaryKeyColumn = EntityMetaDataUtil.getPrimaryKeyByModuleName(predictionTabRow.get(CRMTAB.NAME).toString());

			while(recordRows.hasNext()) {
				Row recordRow = recordRows.next();
				JSONObject servingDataItem = new JSONObject();
				servingDataItem.put("score", new JSONArray("[10]"));
				servingDataItem.put("customer_id", recordRow.get(primaryKeyColumn).toString());
				servingData.put(servingDataItem);
			}
			churnData.put("serving_data", servingData);
			churnData.put("churn_id", configId.toString());
			ChurnPredictionResult result = new ChurnPredictionResult(new JSONArray().put(churnData),OrgUtil.getCurrentZGID().toString());
			result.update();
            return true;
		}
		catch(Exception e) {
			LOGGER.log(Level.WARNING, "Exception in churn prediction results update." , e); // NO I18N
		}
		return false;
	}
	/**
	 * Method to reset mapview congiguration
	 */
	public JSONObject resetMapviewConfig() throws JSONException{
        try {
        	Map<String, Map<String, Object>> configMap = MapViewUtil.configMap;
    		String zgId = OrgUtil.getCurrentZGID().toString();
    		JSONObject configJson = new JSONObject();
    		DataObject mapviewDO = MapViewUtil.getMapViewDO(null, null, zgId);
    		Iterator<Row>mapviewIter = mapviewDO.getRows(CRMVIEWSETTINGS.TABLE);
    		DataObject tabDo = TabUtil.getAllTabsCachedDO(zgId);
    		boolean isUpdated = Boolean.FALSE;
    		while(mapviewIter.hasNext()) {
    			Row configRow = mapviewIter.next();
    			Long tabId = (Long)configRow.get(CRMVIEWSETTINGS.TABID);
    			String moduleName = MapViewUtil.getModuleName(tabId, tabDo);
    			if(moduleName == null) {
    				continue;
    			}
    			if(configMap.containsKey(moduleName)) {
    				Map<String, Object> moduleConfig = configMap.get(moduleName);
    				configJson = MapViewUtil.createConfig(moduleConfig, null, tabId, zgId);
    			} else {
    				String displayField = MapViewUtil.getDisplayField(tabId, zgId);
    				configJson = MapViewUtil.createConfig(null, displayField, tabId, zgId);
    			}
    			configRow.set(CRMVIEWSETTINGS.CONFIGPROPS, configJson.toString());
    			mapviewDO.updateRow(configRow);
    			isUpdated = Boolean.TRUE;	
    		}
    		if(isUpdated) {
    			PersistenceCacheUtil.getPurePersistenceLiteHandle(zgId).update(mapviewDO);
    		}
            resultObj.put("response", "MapviewConfig Reset done");
        } catch (Exception e) {
            status = false;
            resultObj.put("response", e.toString());
        }
        resultObj.put("status", status);
        return resultObj;
    }
	

	/**
	 * 
	 * @return
	 * @author joseph-20046
	 */
	public JSONObject getAPIUsageDetails() {
		status = true;
		try {
			JSONObject responseJO = new JSONObject();
			String apiUsed = CrmCacheProxy.getStringExecutor(IntegFeature.API).get(zgId+"_API_USED");// NO I18N
			responseJO.put("api_used", apiUsed != null ? Integer.valueOf(apiUsed) : 0);
			String apiPaid = CrmCacheProxy.getStringExecutor(IntegFeature.API).get(zgId+"_API_PAID");// NO I18N
			responseJO.put("api_paid", apiPaid != null ? Integer.valueOf(apiPaid) : 0);
			String surgeUsed = CrmCacheProxy.getStringExecutor(IntegFeature.API).get(zgId+"_API_GRACE_USED");// NO I18N
			responseJO.put("api_surge_used", surgeUsed != null ? Integer.valueOf(surgeUsed) : 0);
			String apiThrottle = CrmCacheProxy.getStringExecutor(IntegFeature.API).get(zgId+"_CREDITS_THROTTLE_MTU");// NO I18N
			responseJO.put("api_throttle", apiThrottle != null ? apiThrottle : JSONObject.NULL);
			String paidThrottle = CrmCacheProxy.getStringExecutor(IntegFeature.API).get(zgId+"_API_PAY_THROTTLE");// NO I18N
			responseJO.put("api_paid_throttle", paidThrottle != null ? paidThrottle : JSONObject.NULL);
			String surgeThrottle = CrmCacheProxy.getStringExecutor(IntegFeature.API).get(zgId+"_API_GRACE_THROTTLE");// NO I18N
			responseJO.put("api_surge_throttle", surgeThrottle != null ? surgeThrottle : JSONObject.NULL);
			responseJO.put("free_limit", CrmAPITrackingFilterUtil.getAPILimit());
			responseJO.put("paid_limit", CrmAPITrackingFilterUtil.getPaidAPILimit());
			responseJO.put("surge_limit", CrmAPITrackingFilterUtil.getSurgeAPILimit());
			Calendar cal = Calendar.getInstance();
			cal.setTimeZone(TimeZone.getTimeZone(PMDConstants.GMT));
			cal.setTimeInMillis(System.currentTimeMillis());
			String date = cal.get(Calendar.YEAR)+"-";
			if((cal.get(Calendar.MONTH)+1) <= 9 ) {
				date = date + "0";
			}
			date = date + (cal.get(Calendar.MONTH)+1) +"-";
			if(cal.get(Calendar.DATE) <= 9) {
				date = date + "0";
			}
			String todayDate = date + cal.get(Calendar.DATE);
			Calendar yesterday = Calendar.getInstance();
			yesterday.setTimeInMillis(cal.getTimeInMillis());
			yesterday.add(Calendar.DATE, -1);
			yesterday.setTimeZone(TimeZone.getTimeZone(PMDConstants.GMT));
			String yesterdaysDate = yesterday.get(Calendar.YEAR)+"-";
			if((yesterday.get(Calendar.MONTH)+1) <= 9 ) {
				yesterdaysDate = yesterdaysDate + "0";
			}
			yesterdaysDate = yesterdaysDate + (yesterday.get(Calendar.MONTH)+1) +"-";
			if(yesterday.get(Calendar.DATE) <= 9) {
				yesterdaysDate = yesterdaysDate + "0";
			}
			yesterdaysDate = yesterdaysDate + yesterday.get(Calendar.DATE);
			ScanResult<Entry<String, String>> apiUsageDetails = CrmCacheProxy.getHashExecutor(IntegFeature.API).getMapPage(zgId+"_"+todayDate, "0");
			JSONObject apiUsageMap = new JSONObject();
			if(apiUsageDetails != null)
			{
				for(Entry<String, String> apiUsageDetail: apiUsageDetails.getResult())
				{
					apiUsageMap.put(apiUsageDetail.getKey(), apiUsageDetail.getValue());
				}
			}
			responseJO.put("today_api_usage_map", apiUsageMap);
			ScanResult<Entry<String, String>> previousApiUsageDetails = CrmCacheProxy.getHashExecutor(IntegFeature.API).getMapPage(zgId+"_"+yesterdaysDate, "0");
			JSONObject previousApiUsageMap = new JSONObject();
			if(previousApiUsageDetails != null)
			{
				for(Entry<String, String> previousApiUsageDetail: previousApiUsageDetails.getResult())
				{
					previousApiUsageMap.put(previousApiUsageDetail.getKey(), previousApiUsageDetail.getValue());
				}
			}
			responseJO.put("yesterday_api_usage_map", previousApiUsageMap);
			ScanResult<Entry<String, String>> apiPaidUsageDetails = CrmCacheProxy.getHashExecutor(IntegFeature.API).getMapPage(zgId+"_API_PAY_"+todayDate, "0");// NO I18N
			JSONObject apiPaidUsageMap = new JSONObject();
			if(apiPaidUsageDetails != null)
			{
				for(Entry<String, String> apiPaidUsageDetail: apiPaidUsageDetails.getResult())
				{
					apiPaidUsageMap.put(apiPaidUsageDetail.getKey(), apiPaidUsageDetail.getValue());
				}
			}
			responseJO.put("today_api_paid_usage_map", apiPaidUsageMap);
			ScanResult<Entry<String, String>> previousApiPaidUsageDetails = CrmCacheProxy.getHashExecutor(IntegFeature.API).getMapPage(zgId+"_API_PAY_"+yesterdaysDate, "0");// NO I18N
			JSONObject previousApiPaidUsageMap = new JSONObject();
			if(previousApiPaidUsageDetails != null)
			{
				for(Entry<String, String> previousApiPaidUsageDetail: previousApiPaidUsageDetails.getResult())
				{
					previousApiPaidUsageMap.put(previousApiPaidUsageDetail.getKey(), previousApiPaidUsageDetail.getValue());
				}
			}
			responseJO.put("yesterday_api_paid_usage_map", previousApiPaidUsageMap);
			ScanResult<Entry<String, String>> apiSurgeUsageDetails = CrmCacheProxy.getHashExecutor(IntegFeature.API).getMapPage(zgId+"_API_GRACE_"+todayDate, "0");// NO I18N
			JSONObject apiSurgeUsageMap = new JSONObject();
			if(apiSurgeUsageDetails != null)
			{
				for(Entry<String, String> apiSurgeUsageDetail: apiSurgeUsageDetails.getResult())
				{
					apiSurgeUsageMap.put(apiSurgeUsageDetail.getKey(), apiSurgeUsageDetail.getValue());
				}
			}
			responseJO.put("today_api_surge_usage_map", apiSurgeUsageMap);
			ScanResult<Entry<String, String>> previousSurgeUsageDetails = CrmCacheProxy.getHashExecutor(IntegFeature.API).getMapPage(zgId+"_API_GRACE_"+yesterdaysDate, "0");// NO I18N
			JSONObject previousSurgeUsageMap = new JSONObject();
			if(previousSurgeUsageDetails != null)
			{
				for(Entry<String, String> previousSurgeUsageDetail: previousSurgeUsageDetails.getResult())
				{
					previousSurgeUsageMap.put(previousSurgeUsageDetail.getKey(), previousSurgeUsageDetail.getValue());
				}
			}
			responseJO.put("yesterday_api_surge_usage_map", previousSurgeUsageMap);
			RollingWindowThrottler rwt = new RollingWindowThrottler(cal.getTimeInMillis(),zgId.toString());
			List<Object> usedData = rwt.getAPICountUsedInPrevious24Hours();
			responseJO.put("exact_used_count", APIUsageNotificationUtil.getUsedFromList(usedData));
			responseJO.put("exact_paid_count",rwt.getLast24HoursPaidCount());
			responseJO.put("exact_surge_count",rwt.getLast24HoursAPIGraceLimitCount());
			resultObj.put(CONSTANTS.response, "api usage details are provided");
			resultObj.put(CONSTANTS.details, responseJO);
		}
		catch(Exception e) {
			status = false;
			LOGGER.log(Level.WARNING, "Exception in getting api usage details" , e); // NO I18N
		}
		resultObj.put(CONSTANTS.status_small, status);
		return resultObj;
	}

	/**
	 * This method is used to revert the connected records feature
	 * @return
	 * @throws Exception
	 */
	public JSONObject revertConnectedRecords() throws Exception {
		try {
			LOGGER.log(Level.INFO, "deleteConnectedRecordsRelatedEntries Started for ::: zgid: {0}", new String[] {zgId.toString()});

			Criteria cr = new Criteria(Column.getColumn(CRMTRIALFEATURES.TABLE, CRMTRIALFEATURES.FEATURENAME),Feature.CONNECTED_RECORDS.getName(),QueryConstants.EQUAL);
			PersistenceCacheUtil.getPurePersistenceLiteHandle().delete(cr);

			Criteria fileNameCr = new Criteria(Column.getColumn(AUTOISUAUDITLOG.TABLE, AUTOISUAUDITLOG.MIGRATION_FILENAME), "com.adventnet.crm.autoISU.AddMMLFieldToTeamModule", QueryConstants.EQUAL);
			DeleteQueryUtil.deleteRowsInBatch(AUTOISUAUDITLOG.TABLE, PersistenceCacheUtil.getPurePersistenceLiteHandle(), fileNameCr);

			HashMap<Long, String> tabVsNameMap = new HashMap<Long, String>();
			List<String> teamModulesName = new ArrayList<>();

			//To Get CrmFields
			SelectQuery connectedToFieldSQ = new SelectQueryImpl(Table.getTable(CRMFIELD.TABLE));
			Criteria fieldCr = new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.SYS_REF_NAME), "Connected_To__s" , QueryConstants.EQUAL);
			fieldCr = fieldCr.and(new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.UITYPE),CoreFieldConstants.UITYPE.STRINGFIELD.MULTIMODULE_LOOKUP_FIELD.getValue() ,QueryConstants.EQUAL));
			connectedToFieldSQ.addSelectColumn(Column.getColumn(null,"*"));
			connectedToFieldSQ.setCriteria(fieldCr);
			DataObject fieldObj = PersistenceCacheUtil.getPurePersistenceLiteHandle().constructDataObject();
			Persistence per = PersistenceCacheUtil.getPurePersistenceLiteHandle(zgId.toString());
			DOIterator doIter = new DOIterator(per, connectedToFieldSQ, 500);
			while(doIter.hasNext())	{
				fieldObj.merge(doIter.next());
			}
			List<Long> fieldIdsList = new ArrayList<Long>();
			if(!fieldObj.isEmpty()){
				Iterator<Row> fieldItr = fieldObj.getRows(CRMFIELD.TABLE);
				while(fieldItr.hasNext()){
					Row fieldRow = fieldItr.next();
					fieldIdsList.add((Long)fieldRow.get(CRMFIELD.FIELDID));
					String moduleName = TabUtil.getTabNameById((Long) fieldRow.get(CRMFIELD.TABID), zgId.toString());
					teamModulesName.add(moduleName);
					tabVsNameMap.put((Long) fieldRow.get(CRMFIELD.TABID), moduleName);
				}
			}

			//To get the formruleid, queryid
			List<Long> formRuleIdsList = new ArrayList<Long>();
			List<Long> queryIdsList = new ArrayList<Long>();
			if(!fieldIdsList.isEmpty()) {
				SelectQuery formRuleSq = new SelectQueryImpl(Table.getTable(CRMFORMRULE.TABLE));
				Criteria formRuleCr = new Criteria(Column.getColumn(CRMFORMRULE.TABLE, CRMFORMRULE.PRIMARYFIELDID), fieldIdsList.toArray(), QueryConstants.IN);
				formRuleSq.setCriteria(formRuleCr);
				Join join = new Join(CRMFORMRULE.TABLE, CRMFORMRULEQUERYIDMAP.TABLE, new String[]{CRMFORMRULE.FORMRULEID}, new String[]{CRMFORMRULEQUERYIDMAP.FORMRULEID}, Join.INNER_JOIN);
				formRuleSq.addJoin(join);
				formRuleSq.addSelectColumn(Column.getColumn(CRMFORMRULEQUERYIDMAP.TABLE, "*"));
				DataObject formRuleQueryMapDo = per.get(formRuleSq);
				Iterator<Row> formRuleIter = formRuleQueryMapDo.getRows(CRMFORMRULEQUERYIDMAP.TABLE);
				while (formRuleIter.hasNext()) {
					Row formRuleQueryMapRow = formRuleIter.next();
					formRuleIdsList.add((Long) formRuleQueryMapRow.get(CRMFORMRULEQUERYIDMAP.FORMRULEID));
					queryIdsList.add((Long) formRuleQueryMapRow.get(CRMFORMRULEQUERYIDMAP.QUERYID));
				}
			}

			//Delete CrmFormRule & CRMFORMRULEQUERYIDMAP
			if(!formRuleIdsList.isEmpty()){
				DeleteQuery formRuleDq = new DeleteQueryImpl(CRMFORMRULE.TABLE);
				formRuleDq.setCriteria(new Criteria(Column.getColumn(CRMFORMRULE.TABLE, CRMFORMRULE.FORMRULEID), formRuleIdsList.toArray(), QueryConstants.IN));
				per.delete(formRuleDq);
				LOGGER.log(Level.INFO, "deleteConnectedRecordsRelatedEntries deleted FormRuleIds :::  {0}", new Object[] {formRuleIdsList});
			}

			if(!queryIdsList.isEmpty()) {
				//Delete CRMFORMRULEACTION
				DeleteQuery formRuleActionDq = new DeleteQueryImpl(CRMFORMRULEACTION.TABLE);
				formRuleActionDq.setCriteria(new Criteria(Column.getColumn(CRMFORMRULEACTION.TABLE, CRMFORMRULEACTION.QUERYID), queryIdsList.toArray(), QueryConstants.IN));
				per.delete(formRuleActionDq);

				//Delete SelectQuery
				DeleteQuery selectQueryDq = new DeleteQueryImpl(SELECTQUERY.TABLE);
				selectQueryDq.setCriteria(new Criteria(Column.getColumn(SELECTQUERY.TABLE, SELECTQUERY.QUERYID), queryIdsList.toArray(), QueryConstants.IN));
				per.delete(selectQueryDq);
				LOGGER.log(Level.INFO, "deleteConnectedRecordsRelatedEntries deleted QueryIds :::  {0}", new Object[] {queryIdsList});
			}

			if(!fieldIdsList.isEmpty()) {
				//Delete CrmModeField
				Criteria delModeFieldcr = new Criteria(Column.getColumn(CRMMODEFIELD.TABLE, CRMMODEFIELD.FIELDID), fieldIdsList.toArray(), QueryConstants.IN);
				DeleteQueryUtil.deleteRowsInBatch(CRMMODEFIELD.TABLE, per, delModeFieldcr);

				//Delete CrmField & CrmLsModuleRel
				Criteria delFieldcr = new Criteria(Column.getColumn(CRMFIELD.TABLE, CRMFIELD.FIELDID), fieldIdsList.toArray(), QueryConstants.IN);
				DeleteQueryUtil.deleteRowsInBatch(CRMFIELD.TABLE, per, delFieldcr);
				LOGGER.log(Level.INFO, "deleteConnectedRecordsRelatedEntries deleted FieldIds :::  {0}", new Object[] {fieldIdsList});
			}

			// To get the parent relatedListId
			List<Long> parentListsRelationIds = new ArrayList<Long>();
			SelectQuery listRelationSq = new SelectQueryImpl(Table.getTable(CRMLISTSRELATION.TABLE));
			Criteria connectedRecordRLCr = new Criteria(Column.getColumn(CRMLISTSRELATION.TABLE, CRMLISTSRELATION.SYS_REF_NAME), EntityMetaDataUtil.CONNECTED_RECORDS_SYS_REF_NAME, QueryConstants.EQUAL);
			listRelationSq.setCriteria(connectedRecordRLCr);
			listRelationSq.addSelectColumn(Column.getColumn(null,"*"));
			DataObject parentListRelationDO = PersistenceCacheUtil.getPurePersistenceLiteHandle().constructDataObject();
			DOIterator rlDoIter = new DOIterator(per, listRelationSq, 500);
			while(rlDoIter.hasNext())	{
				parentListRelationDO.merge(rlDoIter.next());
			}
			if(!parentListRelationDO.isEmpty()) {
				Iterator<Row> parentListRelationIter = parentListRelationDO.getRows(CRMLISTSRELATION.TABLE);
				while (parentListRelationIter.hasNext()) {
					Row parentListRelationRow = parentListRelationIter.next();
					parentListsRelationIds.add((Long) parentListRelationRow.get(CRMLISTSRELATION.LISTRELATIONID));
				}
			}

			//Delete both child and parent CrmListsRelations
			if(!parentListsRelationIds.isEmpty()) {
				Criteria listRelationCr = new Criteria(Column.getColumn(CRMLISTSRELATION.TABLE, CRMLISTSRELATION.PARENT_LISTRELATIONID), parentListsRelationIds.toArray(), QueryConstants.IN);
				listRelationCr = listRelationCr.or(new Criteria(Column.getColumn(CRMLISTSRELATION.TABLE, CRMLISTSRELATION.LISTRELATIONID), parentListsRelationIds.toArray(), QueryConstants.IN));
				DeleteQueryUtil.deleteRowsInBatch(CRMLISTSRELATION.TABLE, per, listRelationCr);
				LOGGER.log(Level.INFO, "deleteConnectedRecordsRelatedEntries deleted parentlist RelationIds :::  {0}", new Object[] {parentListsRelationIds});
			}
			if(!teamModulesName.isEmpty()){
				PageCacheUtil.createSchedulerForPageRegen(teamModulesName);
			}
			if(!tabVsNameMap.isEmpty()){
				FormRuleUtil.deleteFormRuleJSONEntryFromCacheAndZFSByModuleList(tabVsNameMap);
			}
			LOGGER.log(Level.INFO, "deleteConnectedRecordsRelatedEntries Completed for ::: zgid: {0}", new String[] {zgId.toString()});
			resultObj.put("status", true); // no i18n
			resultObj.put("response", "connected records feature has been reverted successfully");
		}
		catch(Exception ex) {
			LOGGER.log(Level.SEVERE, "Problem while reverting the connected records", ex);
			resultObj.put("exception",ex);
		}
		return resultObj;

	}

	/**
	 * Method to delete all custom fields in associated products subform only in Bigin
	 * @throws Exception
	 */
	public JSONObject deleteAssociatedProductCFFieldsInBigin() throws Exception {
		Long orgId = OrgUtil.getCurrentZGID();
		Long currentUserId = UserUtil.getCurrentUserId();
		String moduleApiName = "Associated_Products"; //No I18N
		String tabName = TabUtil.getTabNameByAPIName(moduleApiName);
		List<String> defaultFieldsApiNames = new ArrayList<>(Arrays.asList("Product", "Discount_Amount", "List_Price", "Quantity", "Discount", "Total")); //No I18N
		try {
			DataObject fieldsDO = FieldUtil.getFieldsDO(tabName, false, 2, orgId);
			if(fieldsDO!=null && !fieldsDO.isEmpty()){
				Iterator<Row> fieldItr=fieldsDO.getRows(CRMFIELD.TABLE);
				while (fieldItr.hasNext()){
					Row fieldRow= fieldItr.next();
					Long fieldId = Long.parseLong(fieldRow.get(CRMFIELD.FIELDID).toString());
					String apiName = fieldRow.get(CRMFIELD.SYS_REF_NAME).toString();
					if(!defaultFieldsApiNames.contains(apiName)) {
	                    FieldUtil.validateNHideCustomField(tabName, fieldId, currentUserId, CreateUpdateEntityDetails.UI, false, false, false );
					}
				}
			}
			status = true;
			resultObj.put("response", "Removed all associated products custom fields permanently");
		} catch(Exception e) {
			status = false;
			resultObj.put("response", e.toString());
		}
		return resultObj;
	}	
	
