	/**
	 * @author harish-10434
	 * Method to update the Sync Start Time For Mail360 Configuration
	 * @throws Exception
	 */
	public JSONObject updateSyncStartTimeForMail360Configuration() throws Exception{
		try {
			int year =Integer.valueOf(request.getParameter("year"));
			int month =Integer.valueOf(request.getParameter("month"));
			int day =Integer.valueOf(request.getParameter("day"));
			Calendar calendar = Calendar.getInstance();
			calendar.set(year, month - 1, day);
			Date date = calendar.getTime();
			Date currentDate=new Date();
			int numberOfDays=DateTimeUtils.getDayDiffBtwTwoDates(date, currentDate);
			CrmCacheProxy.getStringExecutor(CacheConstants.CrmFeature.BASIC,zgId).put("LOCALZOHO_MAILSYNC_LIMIT_IN_DAYS_"+Long.toString(zuId), String.valueOf(numberOfDays));
			resultObj.put("status", true);
		
		}catch(Exception e) {
			LOGGER.log(Level.INFO, "Exception while updating Sync Start Time in Redis {0}", e);
            resultObj.put("status", false);
		}
		return resultObj;
	}

    /**
	 * @author thanuja-18128
	 * Method to update created/modified/lastviewaccessedreports time for default PF
	 */
    public JSONObject updateDefaultPFCreatedTime() throws Exception {
		LOGGER.log(Level.INFO, "updateDefaultPFCreatedTime Started for ::: zgid: {0}", new String[] {zgId.toString()});
        ArrayList<String> defaultPF = new ArrayList<>();
        defaultPF.add("Sales Journey (Default Path Finder)"); // No I18N
        defaultPF.add("Sales Journey (Default PathFinder)"); // No I18N

        try{
            Persistence pers = PersistenceCacheUtil.getPurePersistenceLiteHandle();
            SelectQuery sq = new SelectQueryImpl(new Table(CRMPROCESSFLOW.TABLE));
            Criteria cri = new Criteria( Column.getColumn(CRMPROCESSFLOW.TABLE, CRMPROCESSFLOW.FEATURE_TYPE), AUTOMATION_FEATURES.PATHFINDER.getInt(), QueryConstants.EQUAL);
            cri = cri.and(new Criteria(Column.getColumn(CRMPROCESSFLOW.TABLE, CRMPROCESSFLOW.NAME), defaultPF.toArray(), QueryConstants.IN));
            sq.addSelectColumn(Column.getColumn(null, "*"));    
            sq.setCriteria(cri);
            sq.setRange(new Range(0,50));     
            DataObject defaultPfDO = pers.get(sq);

            if(defaultPfDO != null && !defaultPfDO.isEmpty()){
                Long oneYearInMillis = 31537000000L;
                Long oneMinsInMillis = 60000L;
                Iterator<Row> defaultPfDOItr = defaultPfDO.getRows(CRMPROCESSFLOW.TABLE);
                while(defaultPfDOItr.hasNext()){
                    Row pfRow = defaultPfDOItr.next();
                    Long createdOn = (Long) pfRow.get(CRMPROCESSFLOW.CREATEDON);
                    Long modifiedOn = (Long) pfRow.get(CRMPROCESSFLOW.MODIFIEDON);
                    pfRow.set(CRMPROCESSFLOW.CREATEDON, createdOn - oneYearInMillis);
                    pfRow.set(CRMPROCESSFLOW.MODIFIEDON, createdOn - oneYearInMillis + oneMinsInMillis);
                    if(pfRow.get(CRMPROCESSFLOW.CHARTDATA) != null){
                        JSONObject chartData = new JSONObject(pfRow.get(CRMPROCESSFLOW.CHARTDATA).toString());
                        Long lastViewReportsTime = chartData.has("lastAccessedViewReportsTime") ? (Long) chartData.get("lastAccessedViewReportsTime") : null; // No I18N
                        if(lastViewReportsTime != null){
                            chartData.put("lastAccessedViewReportsTime", lastViewReportsTime-oneYearInMillis);
                            pfRow.set(CRMPROCESSFLOW.CHARTDATA, chartData);
                        }
                    }
                    defaultPfDO.updateRow(pfRow);
                }
                if(!defaultPfDO.getOperations().isEmpty()){
                    pers.update(defaultPfDO);
                    resultObj.put("status", true); // no i18n
                    resultObj.put("response", "time updated for retain migration");
                    PathFinderIsRetainMigration retainMigration = new PathFinderIsRetainMigration();
                    retainMigration.doMigrationForCRM();
                }
            }
        }catch(Exception e){
            LOGGER.log(Level.SEVERE, "Problem while updating the time for retain migration - {0}", new Object[]{e});
			resultObj.put("exception",e);
            resultObj.put("status", false);
        }	
        return resultObj;	
	}
	
	/**
	 * @author harish-10434
	 * Method to map an account to one of the test mail360consumer
	 * @return
	 */
	public JSONObject updateMail360ConsumerTestAccount() {
		try {
			String machineName =request.getParameter("machineName");
			com.zoho.crm.mailagent.Authentication  authObj = MailAPIRouting.getAuthObject(zgId, zuId, false, null, true);
			if (authObj.isOrgOauth()) {
				authObj.setAddSoType(true);
				authObj.setSoType(String.valueOf(IAMServiceOrg.getType()));
				authObj.setZid(String.valueOf(zgId));
			}
			MailAPI mailAPI = MailAPI.getInstance(authObj);
			
			String prdId = RebrandLinkUtil.getRebrandKeys("WMS_PRDID"); //No I18N
			if(machineName.equalsIgnoreCase("testmail360consumer"))
	        {
	            prdId = "TM"; //No I18N
	        }
	        else if(machineName.equalsIgnoreCase("mail360consumer_qa"))
	        {
	        	prdId = "QA"; //No I18N
	        }
			JSONObject appData = new JSONObject();
			appData.put("ZGID", zgId);
			appData.put("PRODUCT_ID", prdId);

			String notifyId = MailAPIRouting.getNotifyId();
			
			if( notifyId==null || notifyId.isEmpty())
			{
				throw new Exception("notifyId should not be empty , please check");
			}
			
			String notifyResult = mailAPI.notifyToMailApps(ZMailConfigUtil.UPDATE, appData,notifyId).toString();
			LOGGER.log(Level.INFO,"Response of Updating Mail360Consumer Test Account : {0}",new Object[] {notifyResult});
            resultObj.put("status", true);
		}catch(Exception e) {
			LOGGER.log(Level.INFO, "Exception while updating Account as Test Account for Mail360Consumer {0}", e);
            resultObj.put("status", false);
		}
		return resultObj;
	}


    /**
	 * @author vinoth-14902
	 * Method to update default layout for Deal
	 * @return
	 */
    public void updateDefaultLayoutForDeals() {
		Long zgId = null;
        String layoutProp = "{\"pipeline_properties\":{\"singular_label\":\"Deal\",\"plural_label\":\"Deals\"}}"; //No I18N
		try {
			zgId = OrgUtil.getCurrentZGID();
			LOGGER.log(Level.INFO, "layout default value update  started for Org::{0}", new String[] { zgId.toString() });
            if(zgId != null)
            {
                if (LicenseUtil.isBiginAccount(zgId.toString())) {
                    Long tabId = TabUtil.getTabIdByName(CrmModuleConstants.POTENTIALS);
                    Criteria layoutCr = new Criteria(Column.getColumn(CRMPAGELAYOUT.TABLE, CRMPAGELAYOUT.TABID), tabId, QueryConstants.EQUAL);
                    SelectQuery sq = new SelectQueryImpl(Table.getTable(CRMPAGELAYOUT.TABLE));
                    sq.setCriteria(layoutCr);
                    sq.addSelectColumn(Column.getColumn(CRMPAGELAYOUT.TABLE, "*"));
                    sq.setRange(new Range(0,15)); 
                    DataObject sqDO = PersistenceCacheUtil.getNonCachePersistenceHandle().get(sq);
                    if(!sqDO.isEmpty()){

                        Iterator<Row> sqIter = sqDO.getRows(CRMPAGELAYOUT.TABLE);
                        while(sqIter.hasNext()){
                            Row row = sqIter.next();
                            if(row.get(CRMPAGELAYOUT.SYS_REF_NAME).equals("Standard__s")) {
                                row.set(CRMPAGELAYOUT.GENERATEDTYPE, 2);
                                sqDO.updateRow(row);
                            }
                            else if(row.get(CRMPAGELAYOUT.SYS_REF_NAME).equals("Sales_Pipeline")) {
                                row.set(CRMPAGELAYOUT.GENERATEDTYPE, 1);
                                row.set(CRMPAGELAYOUT.SYS_REF_NAME, "Standard__s"); //No I18N
                                row.set(CRMPAGELAYOUT.ACTIONS_ALLOWED, 77L);
                                row.set(CRMPAGELAYOUT.LAYOUTPROP, layoutProp);
                                sqDO.updateRow(row);
                            }
                            
                        }
                        PersistenceCacheUtil.getNonCachePersistenceHandle().update(sqDO);
                    }
                }
            }
		
		}catch(Exception e) {
        	LOGGER.log(Level.INFO, "layout default value update  failed  for Org::{0}", new String[] { zgId.toString() });
        }

	}
    
