    /**
	 * @throws Exception
	 *
	 */
	public JSONObject revertWorkdriveIntegration() {
		try {
			LOGGER.log(Level.WARNING,"Revert WorkDrive Integration Starts");
            
			Long zgid = OrgUtil.getCurrentZGID();
			CoreFeatureUtil.addOrUpdateTrailOrg("WORKDRIVE_INTEGRATION", zgid + "", null, "ORG", false, null); //NO I18N
			List<Long> permissionIds = ProfileUtil.getPermissionIdsByNames(Arrays.asList(new String[]{"Crm_Implied_Create_Team_Folder","Crm_Implied_Associate_Team_Folder","Crm_Implied_Edit_Team_Folder"})); //NO I18N

			if(permissionIds.size() == 3){

				PermissionService permissionService = PermissionService.getInstance();
				Permissions permissions = Permissions.getInstance();
				List<Permission> updatePermissions = new ArrayList<>();

				Permission 	permission = (Permission) ModelUtil.getInstanceForORM(Permission.class);
				permission.setPermissionId(permissionIds.get(0));
				permission.setName("Crm_Implied_Create_Docs");							//NO I18N
				permission.setDescription("docs.create.permission");					//NO I18N
				permissions.update(permission);
				updatePermissions.add(permission);

				Permission 	permissionEdit = (Permission) ModelUtil.getInstanceForORM(Permission.class);
				permissions 			   = Permissions.getInstance();
				permissionEdit.setPermissionId(permissionIds.get(1));
				permissionEdit.setName("Crm_Implied_Edit_Docs");						//NO I18N
				permissionEdit.setDescription("docs.edit.permission");					//NO I18N
				permissions.update(permissionEdit);
				updatePermissions.add(permissionEdit);

				permissionService.updatePermissions(updatePermissions);

				Permission 	permissiondelete = (Permission) ModelUtil.getInstanceForORM(Permission.class);
				permissions 			   	 = Permissions.getInstance();
				permissiondelete.setPermissionId(permissionIds.get(2));
				permissions.remove(permissiondelete);
				permissionService.deletePermission(permissiondelete);
			}

			Criteria CKVCriteria = new Criteria(Column.getColumn(CRMKEYVALUE.TABLE, CRMKEYVALUE.KEYNAME),"WORKDRIVE_INTEG_ENABLED",QueryConstants.EQUAL);
			CrmKeyValueUtil.deleteCrmKeyValueByCriteria(CKVCriteria,false , true);
			UpdateQueryImpl updateWorkdriveIntegInfo = new UpdateQueryImpl(CRMINTEGRATIONCONFIG.TABLE);
			updateWorkdriveIntegInfo.setUpdateColumn(CRMINTEGRATIONCONFIG.WORKDRIVE_INTEG_INFO, null);
			PersistenceCacheUtil.getPurePersistenceLiteHandle().update(updateWorkdriveIntegInfo);

			LOGGER.log(Level.INFO,"Revert WorkDrive Integration Ends");
            resultObj.put("status", true);
            resultObj.put("response", "Revert WorkDrive Integration proccess Completed");
		}
		catch(Exception e) {
			LOGGER.log(Level.WARNING,"Exception while Disabling workdrive integration:::: {0}",e);
            resultObj.put("exception",e);
            resultObj.put("status", false);
		}
        return resultObj;
	}

